INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(1834, 0, 3, 'koKR', '붉은십자군은 사악한 자들을 쳐부수고, 이 땅에서 악마를 몰아낼 것이다!'),
(1835, 0, 0, 'koKR', '타락한 스컬지의 냄새가 나는군. 뒤틀린 황천에 갈 준비나 해라!'),
(1835, 0, 1, 'koKR', '도망칠 곳은 없다! 붉은십자군은 타락한 스컬지 녀석들을 모두 없애버릴 것이다.'),
(1835, 0, 2, 'koKR', '너같이 악을 일삼는 자는 빛의 심판을 받아 죽게 될 것이다!'),
(1835, 0, 3, 'koKR', '붉은십자군은 사악한 자들을 쳐부수고, 이 땅에서 악마를 몰아낼 것이다!'),
(1840, 0, 0, 'koKR', '오, 이런... 폴드링, 자네를 그렇게 쉽게 보내줄 수는 없지.'),
(1840, 1, 0, 'koKR', '결국, 날 좌절시키는군, 탤런! 널 목표로... 굉장한 계획을 세웠는데. 아아! 시간이 조금만 더 있었더라면 네가 그 더러운 혈통을 타고난 사실을 땅을 치며 후회하게 해줄 것을...'),
(1840, 2, 0, 'koKR', '들은 대로군. 그 아버지에 그 아들이라니... 티리온 만큼이나 나약하군. 어쩌면 더 나약할지도 모르겠고 말이야. 내가 보낸 암살자가 티리온의 비참한 삶을 끝내주길 바랄 뿐...'),
(1840, 3, 0, 'koKR', '십자군 사령관께서 너와 최근에 발견한 너의 친구들을 제거하라고 하셨지. 하지만 말이야 탤런, 이 말은 꼭하고 싶군. 꼭 명령이나 임무가 아니더라도 난 이 일을 하게 되어 즐겁다네.'),
(1840, 4, 0, 'koKR', '%s|1이;가; 보초병을 부릅니다.'),
(1840, 5, 0, 'koKR', '이제 끝이군, 폴드링.'),
(1840, 6, 0, 'koKR', '그만!'),
(1840, 7, 0, 'koKR', '%s|1이;가; 웃습니다.'),
(1840, 8, 0, 'koKR', '정말 날 이길 수 있다고 생각했나? 네 친구도 곧 보내 주마, 탤런.'),
(1840, 9, 0, 'koKR', '비극적이군. 저 늙은 폴드링이 아직 살아 있다니... 이보라고, 당신은 너무 오래 살았어. 뒤틀린 황천에 있는 아들을 따라가고 싶지 않으면 다시 동굴로 돌아가서 숨어서 지내라고!'),
(1840, 10, 0, 'koKR', '그렇다면 덤벼봐!'),
(1841, 0, 0, 'koKR', '%s|1이;가; 분노합니다!'),
(1842, 0, 0, 'koKR', '내가 하스글렌을 지나 이곳 외곽까지 인도하지. 자네는 거기서부터 날 아버지에게로 안내하게.'),
(1842, 1, 0, 'koKR', '내가 분노해 휘두른 칼에 맞으면 안 되니까 변장을 풀도록 하게.'),
(1842, 2, 0, 'koKR', '잠시만... 멈춰 보게.'),
(1842, 3, 0, 'koKR', '%s|1이;가; 말을 부릅니다.'),
(1842, 4, 0, 'koKR', '그렇게 멀지는 않군. 큰 길이 바로 위에 있네.'),
(1842, 5, 0, 'koKR', '이실리엔!'),
(1842, 6, 0, 'koKR', '이방인, 자네와는 상관없는 싸움이다. 진홍십자군 정예병의 공격으로부터 몸을 지켜라. 나는 종교재판장과 일전을 치르겠다.'),
(1853, 0, 0, 'koKR', '수업이 시작됐다!'),
(1854, 0, 0, 'koKR', '환영하오, 친구들!'),
(1854, 1, 0, 'koKR', '맹세코 성스러운 빛에 의해 그대는 이 무덤을 떠나게 될 것이오!'),
(1931, 0, 0, 'koKR', '아아아... 속이... 안 좋아...'),
(1931, 1, 0, 'koKR', '아아아... 내 영혼... 내 살이... 썩어 들어가고 있어...!'),
