(15953, 4, 0, 'koKR', '%s|1이;가; 귀부인의 은총에 영향을 받습니다!'),
(15953, 5, 0, 'koKR', '%s|1이;가; 분노에 휩싸입니다!'),
(15953, 6, 0, 'koKR', '나에게서 도망칠 수는 없다!'),
(15953, 6, 1, 'koKR', '내 앞에 무릎을 꿇어라, 벌레들아!'),
(15953, 6, 2, 'koKR', '도망칠 수 있을 때 달리십시오!'),
(15954, 0, 0, 'koKR', '주인님께 영광을!'),
