(23418, 6, 0, 'koKR', '%s|1이;가; 분노합니다!'),
(23419, 0, 0, 'koKR', '선택은 자유지만... 대가는 치러야 하는 법.'),
(23419, 1, 0, 'koKR', '이제 곧 다 이루리라.'),
(23419, 1, 1, 'koKR', '이제, 우리와 함께하자...'),
(23419, 1, 2, 'koKR', '분에 넘치는 욕심은 화를 부르지.'),
(23419, 2, 0, 'koKR', '주제 파악부터 하고 덤벼라.'),
