INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(29523, 0, 5, 'koKR', '어서 오십시오. 찾는 물건이라도 있으신가요?'),
(29523, 0, 6, 'koKR', '안녕하세요.'),
(29525, 0, 0, 'koKR', '고맙네, 고마워! 이 시퍼런 미치광이 여인들로부터 이제 벗어날 수 있겠군!'),
(29542, 0, 0, 'koKR', '이번에는 그렇게 쉽게 죽지 않을 것이다!'),
(29560, 0, 0, 'koKR', '잘했네. 이 일을 마무리짓도록 하세.'),
(29560, 1, 0, 'koKR', '자, 랜드그렌. 아주 중요한 질문을 해야 하니 그 영혼을 드러내라.'),
(29560, 2, 0, 'koKR', '웨스트윈드가 어디 있는지 당장 털어놓지 않으면 네 영혼을 박살 내 버리겠다!'),
(29560, 3, 0, 'koKR', '그렇다면, 별수 없군. 이런 일이 또 나름대로 재미가 없는 것도 아니니.'),
(29560, 4, 0, 'koKR', '잘 생각했다. 어서 말해라!'),
