INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(1, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'koKR', '안녕하세요, $n. 무엇을 도와 드릴까요?', '반갑습니다, $n. 어떻게 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'koKR', '안녕하신가요, 스톰윈드의 시민이여. 내게 하실 말씀이 없으시면 가던 길을 가 주셨으면 합니다만…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'koKR', '나는 오직 왕을 섬길 뿐이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'koKR', '계속 가시오. 여기는 볼 것이 없어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'koKR', '환영해요 스자보! 헤이!', '책의 페이지 위에 수백 가지 도면과 설계도가 모습을 갖추기 시작합니다. 몇몇 도식은 알아보겠지만, 나머지는 낯설면서도 어딘가 익숙합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'koKR', '여기요! 여기! 당신도 사고 나도 사고!!', '여러 그림과 형상, 표식이 눈앞에서 하나로 맞춰집니다. 이 책은 당신의 가죽세공 실력을 알아보고 선택지를 내미는 듯합니다. 하지만 주의하십시오. 단 하나만 선택할 수 있으며, 한번 선택하면 마음을 바꿀 수 없습니다!:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18, 'koKR', '내 곁에 있으시오, $N. 우리가 도움이 필요할지도 모르겠오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(24, 'koKR', '아, $n! 당신이 온다는 소식을 작은 새에게 전해 들었소.$B$B아비아나 님은 이렇게 소식을 전달하신다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(34, 'koKR', '어떤 전문 기술을 배우려고 하십니까?', '어떤 전문 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(42, 'koKR', '데스윙이 돌아왔습니다. 그는 그림 바톨과 고원의 여러 지역을 손에 넣었지요. 데스윙을 막기엔 제가 너무 약하다는 자괴감이 들 정도입니다.$B$B곧 우리 여왕님께서 도착하실 겁니다. 그리고 우리는, 한때 대지의 수호자였던 그자를 물리칠 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, 'koKR', '도움이 필요하십니까?', '도움이 필요하십니까?', '어떻게 도와 드릴까요?', '어떻게 도와 드릴까요?', '어떻게 도와 드릴까요?', '어떻게 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(68, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(82, 'koKR', '용아귀 부족을 도우면 충분한 보상을 얻을 걸세, $c|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(107, 'koKR', NULL, '뭐야? 이 멍청한 녀석아', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(134, 'koKR', '호드 전투 기계가 당신을 필요로 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(141, 'koKR', NULL, '나는 지도자의 책무와 역할에 아직 익숙하지 않네. 나크랄이 이렇게 반항할 줄 미리 눈치챘어야 했는데, 대비는커녕 그가 저지른 일을 수습하고 있다니.$B$B가로쉬 헬스크림은 어떻게 호드를 이끄는지 궁금하군. 호드처럼 다양한 세력이 모인 집단을 이끄는 걸 보면 엄청난 힘의 소유자일 테지... 그를 좀 더 자세히 알고 싶군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(153, 'koKR', '어이, 친구, 잘 지내지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(158, 'koKR', NULL, '반가워요, $c님.$B$B하이잘은 불타오르고 제가 평생을 바쳐 지켜온 세상은 흔적도 없이 사라질 위기에 처해 있어요.$B$B대답해 주세요. 타이러스 블랙혼이라는 이름을 들어본 적이 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(166, 'koKR', '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(185, 'koKR', '원하시면 여기서 휴식을 취하셔도 됩니다. 대지의 사원은 이제 안전합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(194, 'koKR', '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(197, 'koKR', '북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(215, 'koKR', NULL, '대지의 수호자, 그리고 그의 아이들이 언젠가는 죄악에서 구원되리란 희망을 오랫동안 버리지 않았습니다. 하지만, 어느 순간 우리도 깨닫고, 인정할 수밖에 없었지요. 검은용들이 이 세상에 행한 파괴는 어떤 속죄로도 보상할 수 없다는 사실을 말입니다.$B$B그래서 어쩔 수 없이 이 일에 끼어들게 되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(225, 'koKR', '내 평생에, $r, 이런걸 본 적이 없네요…', NULL, '이곳에서 전투를 치르기에는 장비가 너무 열악하다네.$b$b전투에 대비해야 할 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(246, 'koKR', '나가서 저 바위 트로그들을 다시 땅속으로 돌려 보내세, $r 친구!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(247, 'koKR', '자네가 최전선에 가 주어야겠네, $n.$B$B자네라면 상황을 반전시킬 수 있을 거야. 우린 바위 트로그들을 박멸할 것이네.$B$B오어맨틀 국왕 폐하를 구출해야 하네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(248, 'koKR', '<투덜대며 코웃음 치는 클레이>$B$B하여간 요즘 젊은 것들은.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(328, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(384, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(401, 'koKR', '맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(447, 'koKR', '시험의 골짜기에서는 칼림도어에서 가장 허약한 자라도 호드와 어깨를 나란이 하고 싸울 수 있을 만한 강력한 전사로 단련시켜 주지. 우리의 시험을 통과하지 못한 자들은 이글거리는 사막의 태양 아래서 타죽게 된다고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'koKR', '할 일 많아, 할 일 많아! 조합에서 마감 기한을 정해 놨는데, 어겼다간 좋은 꼴 못 봐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'koKR', '원래 스팀휘들의 벌목기 개발 프로젝트를 감독했었지만, 지난달에 독립했어. 그러니까 물건 대주는 모두에게 찍혀버렸지. 더 나쁜 건, 개발 작업이 아직 시작도 못 했다는 거야. $n, 자네 손을 좀 빌렸으면 하는 데 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(520, 'koKR', '보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 \"빌리기로\" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!', '보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 \"빌리기로\" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(521, 'koKR', '유령울음늑대를 해치우다니! 아주 훌륭하십니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(522, 'koKR', '더 가까이 오게, 젊은이. 한창때는 사냥감의 심장 뛰는 소리도 들리더니만 지금은 큰 소리로 말해야 겨우 알아들을 수가 있다네, 허허.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(523, 'koKR', '난 아주 오랫동안 이 평원을 누벼왔지. 거대한 짐승들도 사냥해 왔고. 한 번도 패한 적은 없었네... 유령울음늑대를 상대하기 전까지는 말이야.$B$B아주 오래전, 이 거대한 유령울음늑대는 타우렌과 함께 불타는 군단에 맞서 용감히 싸운 적도 있었다네. 하지만 악마와 싸우다 살이 찢겨 나가는 심각한 부상을 입었고 그 부상을 치유하지 못해 결국 미쳐 버리고 말았던 걸세.$B$B지금은 고통 속에서 평원을 떠돌며 하루빨리 고통이 끝나기만 기다리고 있지. 나에게', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(538, 'koKR', '안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', '안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(539, 'koKR', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(558, 'koKR', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(559, 'koKR', '반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(560, 'koKR', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(561, 'koKR', '진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', '진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(562, 'koKR', '반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', '반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(563, 'koKR', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(564, 'koKR', '반갑습니다. 알려지지 않은 마법을 배우러 오셨습니까?', '반갑습니다. 알려지지 않은 마법을 배우러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(565, 'koKR', '안녕하신가, $c|1이여;여;. 안타깝지만 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', '안녕하신가, $c|1이여;여;. 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(580, 'koKR', NULL, '당신은 아직 여기 올 때가 아닙니다. 다시 삶의 세계로 돌아갈 수 있도록 내가 도와드리겠습니다... 하지만 약간의 대가를 치러야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(581, 'koKR', '실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', '실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(623, 'koKR', '원하는 게 뭐요, $c? 난 너무 늦었다고. 내 고용주는 일 처리를 굼뜨게 하는 걸 절대 달가워하지 않을 거란 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(624, 'koKR', '그런데, 무슨 일이오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(638, 'koKR', '으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', '으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(678, 'koKR', '당신 같은 젊은 $c|1이;가; 이 늙은 농부에겐 무슨 일로 오셨소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(698, 'koKR', '나랄렉스 님께서 또 잠이 드셨소!$B$B아주 오래전, 나랄렉스 님께서는 에메랄드의 꿈속으로 들어가 불모의 땅을 울창한 숲으로 만들겠다는 고귀한 뜻을 품고 이 동굴로 먼 길을 오셨소. 하지만 나랄렉스 님의 집중력이 약해지면서 뱀의 형상이 에메랄드의 꿈을 더럽히게 되었소.$B$B나랄렉스 님을 괴롭히는 그 파충류들이 이제는 이 땅까지 스며나오고 있소. 나랄렉스 님께서 악몽에서 깨어나지 않으면, 영원히 그분을 잃게 될 거요. 그러면 엄청난 악의 힘이 풀려나게', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(699, 'koKR', '송곳니 군주들이 죽었소! 아직 희망이 모두 사라진 건 아니오! 하지만 자각의 의식은 꽤 복잡하여 혼자서는 할 수 없소.$B$B필요한 준비는 내가 모두 할 테니 당신은 나를 지켜주어야 하오. 에메랄드의 꿈을 통해 나랄렉스 님의 여행에서 소환된 몽마들은 상당히 위협적이오. 당신이 도와주지 않는다면 이 임무는 실패할 거요.$B$B나를 지켜줄 줄 준비가 되거든 말해주시오. 그러면 나랄렉스 님의 안식처로 안내하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(718, 'koKR', '기계가 이쪽을 돌아봅니다.$B$B기계 뒷면에는 이상한 형태로 뒤틀린 홈이 있고 \'겔카크 자이로마스트 선장의 물건\'이라는 글귀가 새겨져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(720, 'koKR', '이보시오! 틸스의 심부름을 온 거요? 내가 당신이라면 그자를 가까이하지 않을 거요. 술에 절어 제정신이 아니지... 하지만 마법만은 여전히 강력하다오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(733, 'koKR', '여기선 발밑 조심해, $G젊은이:아가씨;. 우리 패거리가 아니라고 봐주는 건 아니야. 선 넘으면 지팡이 맛 좀 보여줄 테니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(737, 'koKR', '오, 안녕하시오. 보아하니 돈 좀 벌 기회라면 마다할 얼굴은 아니군, 흐음? 눈빛만 봐도 알겠소. 나는 거물 케복, 아제로스 사업 총책임자요. 부를 원한다면... 내가 자리를 좀 마련해 줄 수도 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(738, 'koKR', '좋소. 말해 주겠소. 대신 나를 틸스에게 데려가지 않는다면 말이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(739, 'koKR', '티르스한테 내가 아직 여기 있다고 말하지 마. 내가 소금 평원을 안 떠난 걸 알면 평생 심부름이나 하고 빨래까지 떠맡게 될 거야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(758, 'koKR', '겔카크의 열쇠를 빈 홈에 넣으니 꼭 들어맞습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(759, 'koKR', '철 족쇄에 묶여 꼼짝도 못하는 나를 조롱하는 것인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(760, 'koKR', '인간 중 한 명에게 이 고약한 장치의 열쇠가 있소. 여기 있는 자들이 그를 에스턴이라고 부르는 것 같더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(761, 'koKR', '여기서 나가시오, $c 친구. 아니면 저들이 당신을 족쇄로 묶어버릴 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(762, 'koKR', '말겐... 교도관 중에 한 명이지. 그 녀석에게 내 족쇄 열쇠가 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(764, 'koKR', '은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', '은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(766, 'koKR', '던 모로에 쌓인 눈이 모두 녹아 없어져 버렸으면 좋겠다오. 항상 내 로브 자락을 적실뿐더러 모든 걸 지저분하게 만든단 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(767, 'koKR', '아이고, 지겨운 눈 같으니... 거기, 당신 $n 아니신가? 당신에게 전할 말이 있다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(768, 'koKR', '아이언포지의 최고 흑마법사이신 라고 블랙렌치께서 당신을 찾고 계시오. 즉시 그분께 가서 보고를 드리는 게 좋겠소. 아이언포지의 쓸쓸한 뒷골목에 가면 그분을 만날 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(769, 'koKR', '$C|1이여;여;, 만나서 반갑소. 나는 타나리운 트리텐더라 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(773, 'koKR', '$C인가? 나는 크라젝, 남작 레빌가즈의 비서라네. 이 밀림 안팎에서 돌아가는 일이라면 모르는 게 없지. 톱니항 기름 시세라도 궁금한가? 아니라고? 그럼 일거리라도 찾나? 그건 내가 도와줄 수 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(778, 'koKR', '앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', '앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', '노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', '노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', '나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', '나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', '난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', '난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', '다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', '다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL),
(779, 'koKR', '아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', '아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', '며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', '며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', '씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', '씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(780, 'koKR', '고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', '고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', '이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', '이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', '우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', '우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', '내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', '내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', '내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', '내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', NULL, NULL, NULL, NULL, NULL, NULL),
(781, 'koKR', '틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', '틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', '존슨? 이 근처 어딘가에 있을 텐데...', '존슨? 이 근처 어딘가에 있을 텐데...', '씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', '씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(798, 'koKR', '드디어 이 감옥에서 해방이 됐군!$B$B나는 이곳 은빛소나무 숲에서 아루갈이 언데드를 어떻게 상대하고 있는지 조사하라는 키린 토의 지시를 받고 달라란에서 왔습니다. 아루갈이 미쳐버린 줄은 아무도 몰랐지요.$B$B즉시 이 사태에 대해 보고를 해야 합니다! 하지만 떠나기 전에 안마당 문에 걸린 마법 자물쇠를 풀어 드리지요.$B$B당신은 레실고어를 물리쳤으니 아마 이 문 너머 세상에서도 살아남을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(799, 'koKR', '드디어! 저를 이 감옥에서 구해줄 분이 오셨군요! 오, 여왕이시여! 감사합니다!$B$B우리는 아루갈을 일망타진할 계획을 세울 수 있도록 성채에 관한 정보를 모아오라는 고위집행관 하드렉의 지시를 받고 왔습니다.$B$B하지만 그 늙은 마법사가 많은 계략을 숨겨놓는 바람에 우리는 마법 감시망에 걸려 들켜버리고 말았지요. 저는 살아남아 이 감옥에라도 갇혔지만 빈센트는 운이 좋지 않았습니다.$B$B즉시 하드렉에게 돌아가 이 일을 보고해야 합니다. 그 전에 먼저', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(818, 'koKR', '나는 한때 황혼의 망치단을 따랐었소. 고대 신들을 환생시키는 데 집착했던 나는 그 몹쓸 짐승 아쿠마이의 힘을 얻기 위해 이 깊은 굴속으로 들어왔지.$B$B수많은 무고한 생명이 제물로 바쳐지는 것을 보고서야 정신을 차리게 되었소.$B$B이제는 덫에서 풀려나 자유의 몸이 되었소! 하지만 고향인 카즈 모단은 너무나 멀리 있군.$B$B용감한 모험가여, 아쿠마이를 처치해 준 답례로 아주 특별한 땅으로 가는 길을 알려주겠소. 원한다면 다르나서스로 이동시켜주리다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(820, 'koKR', '여행으로 지치신 분이시여, 저희 여관에 오신 것을 환영합니다! 무엇을 도와 드릴까요?', '여행으로 지치신 분이시여, 저희 여관에 오신 것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(821, 'koKR', '여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', '여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(822, 'koKR', '저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', '저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(823, 'koKR', '손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', '손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(824, 'koKR', '손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', '손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(825, 'koKR', '자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', '자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(838, 'koKR', NULL, '$r|1이여;여;. 만나서 반갑습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(878, 'koKR', '자... 고양이가 뭘 가져왔는지 볼까? ... 아, 뭘 도와드릴까요?', '자... 고양이가 뭘 가져왔는지 볼까? ... 아, 뭘 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(879, 'koKR', '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', '아하, 덩가 롱드링크씨를 찾고 계시군요. 그는 카즈 모단에선 제일 빠른 그리핀을 부리고 있답니다! 그를 만나려면 상업 지구에서 계단을 따라 성벽으로 올라 가시면 됩니다.', '아하, 덩가 롱드링크씨를 찾고 계시군요. 그는 카즈 모단에선 제일 빠른 그리핀을 부리고 있답니다! 그를 만나려면 상업 지구에서 계단을 따라 성벽으로 올라 가시면 됩니다.', '그리핀 탑승장을 찾으시는군요? 덩가씨는 상업 지구에 성벽 위에서 자신의 그리핀을 지키고 있습니다. 그리핀에 탑승하시면 꼭 붙잡고 계셔야 한다는 거 잊지 마시기 바랍니다!', '그리핀 탑승장을 찾으시는군요? 덩가씨는 상업 지구에 성벽 위에서 자신의 그리핀을 지키고 있습니다. 그리핀에 탑승하시면 꼭 붙잡고 계셔야 한다는 거 잊지 마시기 바랍니다!', '아, 그리핀 말씀인가요? 전 그리핀을 좋아하지 않지만 좋아하는 사람도 있더라고요.$b$b상업 지구에서 성벽 쪽으로 올라가시면 덩가 롱드링크씨를 찾으실 수 있습니다.', '아, 그리핀 말씀인가요? 전 그리핀을 좋아하지 않지만 좋아하는 사람도 있더라고요.$b$b상업 지구에서 성벽 쪽으로 올라가시면 덩가 롱드링크씨를 찾으실 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(882, 'koKR', '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '길드를 창설하시려는군요? 그렇다면, 스톰윈드 사무소에 있는 앨드윈 래프린과 상의해 보시기 바랍니다.$b$b스톰윈드 사무소는 영웅의 계곡에서 상업 지구로 들어서자마자 바로 왼쪽에 있답니다. 행운을 빕니다!', '길드를 창설하시려는군요? 그렇다면, 스톰윈드 사무소에 있는 앨드윈 래프린과 상의해 보시기 바랍니다.$b$b스톰윈드 사무소는 영웅의 계곡에서 상업 지구로 들어서자마자 바로 왼쪽에 있답니다. 행운을 빕니다!', '아, 스톰윈드 사무소를 찾으시는군요. 영웅의 계곡에서 성문을 지나 바로 왼쪽에 있는 첫 번째 건물입니다. 그리로 가보십시오.', '아, 스톰윈드 사무소를 찾으시는군요. 영웅의 계곡에서 성문을 지나 바로 왼쪽에 있는 첫 번째 건물입니다. 그리로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(898, 'koKR', '어떤 직업 상급자를 찾으십니까?', '어떤 직업 상급자를 찾으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(899, 'koKR', '마법사 지구에 있는 마법사의 성소로 가면 스톰윈드의 저명한 마법사들이 모여 있습니다. 그 멋진 곳과 비하면 우리 경비병 거처는 완전히 돼지 우리나 다름없어요.', '마법사 지구에 있는 마법사의 성소로 가면 스톰윈드의 저명한 마법사들이 모여 있습니다. 그 멋진 곳과 비하면 우리 경비병 거처는 완전히 돼지 우리나 다름없어요.', '아, 신비로운 주문을 배우고 싶습니까? 그렇다면, 마법사 지구에 있는 마법사의 성소보다 적당한 곳은 없으니, 그곳을 방문해 보십시오.', '아, 신비로운 주문을 배우고 싶습니까? 그렇다면, 마법사 지구에 있는 마법사의 성소보다 적당한 곳은 없으니, 그곳을 방문해 보십시오.', '듣자하니 마지노르 뒤마를 만나고 싶어하시는 것 같군요! 그분은 항상 마법사 지구에 있는 마법사의 성소에 계십니다. 그 마법사들이 언제 어디로 차원의 문을 통해 사라져 버릴지 아무도 모른답니다.', '듣자하니 마지노르 뒤마를 만나고 싶어하시는 것 같군요! 그분은 항상 마법사 지구에 있는 마법사의 성소에 계십니다. 그 마법사들이 언제 어디로 차원의 문을 통해 사라져 버릴지 아무도 모른답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(900, 'koKR', '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', '흠, 도적들은 순전히 우리들 애만 먹이고 있다고요. 지금이라도 할 수만 있다면 구 시가지에서 오스본과 마티아스를 끌어다가 지하감옥에 잡아넣고 싶답니다.', '흠, 도적들은 순전히 우리들 애만 먹이고 있다고요. 지금이라도 할 수만 있다면 구 시가지에서 오스본과 마티아스를 끌어다가 지하감옥에 잡아넣고 싶답니다.', '상급 도적을 만나고자 하신다면, 구 시가지로 가십시오. 스톰윈드 북동쪽 가장자리에 있습니다.', '상급 도적을 만나고자 하신다면, 구 시가지로 가십시오. 스톰윈드 북동쪽 가장자리에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(901, 'koKR', '구 시가지의 스톰윈드 병영이나 돼지와 휘파람 선술집에 강인한 전사들이 모여 있습니다. 모르긴 몰라도 지금쯤 선술집에 모여서 왁자지껄 술잔을 기울이며 시간을 보내고 있을 테니 그리로 한번 가보십시오.', '구 시가지의 스톰윈드 병영이나 돼지와 휘파람 선술집에 강인한 전사들이 모여 있습니다. 모르긴 몰라도 지금쯤 선술집에 모여서 왁자지껄 술잔을 기울이며 시간을 보내고 있을 테니 그리로 한번 가보십시오.', '전사 훈련을 받으려고 하십니까? 시간만 있다면 제가 누구보다 잘 가르쳐 드릴 자신이 있습니다만, 경비병의 직무 때문에 그럴 수는 없겠군요. 구 시가지에 있는 돼지와 휘파람 선술집이나 스톰윈드 병영 근처에서 상급 전사분을 찾아보시는 게 좋겠습니다.', '전사 훈련을 받으려고 하십니까? 시간만 있다면 제가 누구보다 잘 가르쳐 드릴 자신이 있습니다만, 경비병의 직무 때문에 그럴 수는 없겠군요. 구 시가지에 있는 돼지와 휘파람 선술집이나 스톰윈드 병영 근처에서 상급 전사분을 찾아보시는 게 좋겠습니다.', '구 시가지에서 돼지와 휘파람 선술집이나 스톰윈드 병영을 찾아보시기 바랍니다. 아, 선술집에 들르시면 꼭 그곳 맥주를 맛보십시오. 드워프가 만든 맥주와는 비교도 안 될 겁니다.', '구 시가지에서 돼지와 휘파람 선술집이나 스톰윈드 병영을 찾아보시기 바랍니다. 아, 선술집에 들르시면 꼭 그곳 맥주를 맛보십시오. 드워프가 만든 맥주와는 비교도 안 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(902, 'koKR', '스톰윈드의 파괴된 공원과 더불어 그 안에 있던 애처롭고 운이 없었던 영혼들인 나이트 엘프 대부분을 찾는 거라면... 가장 좋은 방법은 드워프 지구 바로 밖에 있는 옛 셀레스틴을 찾는 걸 겁니다.$B$B북쪽 단에서부터 아래로 이어지는 계단이 있습니다. 그곳에서 그녀의 작은 집을 볼 수 있습니다.', '스톰윈드의 파괴된 공원과 더불어 그 안에 있던 애처롭고 운이 없었던 영혼들인 나이트 엘프 대부분을 찾는 거라면... 가장 좋은 방법은 드워프 지구 바로 밖에 있는 옛 셀레스틴을 찾는 걸 겁니다.$B$B북쪽 단에서부터 아래로 이어지는 계단이 있습니다. 그곳에서 그녀의 작은 집을 볼 수 있습니다.', '상급 드루이드를 찾으려면 스톰윈드 공원으로 가셔야 합니다. 공원 중앙에 있는 달샘에 가면 맬드린과 세리단을 만나실 수 있습니다.', '상급 드루이드를 찾으려면 스톰윈드 공원으로 가셔야 합니다. 공원 중앙에 있는 달샘에 가면 맬드린과 세리단을 만나실 수 있습니다.', '자연의 길을 배우고 싶으시다면 스톰윈드 공원의 달샘 부근으로 가보시기 바랍니다.', '자연의 길을 배우고 싶으시다면 스톰윈드 공원의 달샘 부근으로 가보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(903, 'koKR', '대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', '대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', '스톰윈드의 대여사제 로레나님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', '스톰윈드의 대여사제 로레나님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', '대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', '대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(904, 'koKR', '강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', '강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(905, 'koKR', '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', '사냥꾼이라고요? 그럼 드워프 지구에 있는 톨핀 스톤쉴드와 얘기해 보는 게 좋겠군요.\r\n\r\n참, 그에게 가면 꼭 전해 주십시오. 그의 야수가 한 번만 더 소동을 일으키면 앞으로는 지하감옥 안에서 제자들을 가르치게 될 거라고 말입니다!', '사냥꾼이라고요? 그럼 드워프 지구에 있는 톨핀 스톤쉴드와 얘기해 보는 게 좋겠군요.\r\n\r\n참, 그에게 가면 꼭 전해 주십시오. 그의 야수가 한 번만 더 소동을 일으키면 앞으로는 지하감옥 안에서 제자들을 가르치게 될 거라고 말입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(906, 'koKR', '뭐라고 하셨습니까? 스톰윈드에 흑마법사가 있다고요? 제가 스톰윈드에서 경비 업무를 시작한 이후 상급 흑마법사가 있다는 소리는 처음 들어봅니다만...\n\n마법사 지구에 있는 어둠의 희생양 선술집에서 악마를 소환해 부리는 광경을 목격했다는 소리를 들어는 보았습니다. 그곳을 한번 찾아보시는 게 어떨까 싶습니다.', '뭐라고 하셨습니까? 스톰윈드에 흑마법사가 있다고요? 제가 스톰윈드에서 경비 업무를 시작한 이후 상급 흑마법사가 있다는 소리는 처음 들어봅니다만...\n\n마법사 지구에 있는 어둠의 희생양 선술집에서 악마를 소환해 부리는 광경을 목격했다는 소리를 들어는 보았습니다. 그곳을 한번 찾아보시는 게 어떨까 싶습니다.', '흑마법사라고요? 글쎄... 소문에 듣기로는 마법사 지구에 있는 어둠의 희생양이라는 선술집에 그런 족속이 모인다고 합니다. 제가 이런 얘기를 해드린 것은 비밀로 해주십시오.', '흑마법사라고요? 글쎄... 소문에 듣기로는 마법사 지구에 있는 어둠의 희생양이라는 선술집에 그런 족속이 모인다고 합니다. 제가 이런 얘기를 해드린 것은 비밀로 해주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(907, 'koKR', '어쩌다 이곳까지 오게 되셨소, $n?', '어쩌다 이곳까지 오게 되셨소, $n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(908, 'koKR', '그 녀석은 날이 갈수록 살이 찌고 타락해지고 있네. 몸에서는 악취도 나지. 더러운 녀석이야. 씻지 않아서 더럽다는 의미만은 아닐세.$B$B험담은 이제 그만하고. 무슨 일로 날 찾아왔는가, $c|1이여;여;?', '그 녀석은 날이 갈수록 살이 찌고 타락해지고 있답니다. 몸에서는 악취도 나죠. 더러운 녀석이에요. 씻지 않아서 더럽다는 의미만은 아니고요.$B$B험담은 이제 그만하고. 무슨 일로 저를 찾아오셨나요, $c|1이여;여;?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(918, 'koKR', '어떤 전문 기술을 배우려고 하십니까?', '어떤 전문 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(919, 'koKR', '스톰윈드에서 연금술을 배워보려고 하신다면 연금술 소품점을 권해드리고 싶군요. 마법사 지구에 들어서서 왼쪽 길을 따라 가시면 연금술 소품이라고 쓰인 간판이 걸린 상점을 찾으실 수 있을 겁니다.', '스톰윈드에서 연금술을 배워보려고 하신다면 연금술 소품점을 권해드리고 싶군요. 마법사 지구에 들어서서 왼쪽 길을 따라 가시면 연금술 소품이라고 쓰인 간판이 걸린 상점을 찾으실 수 있을 겁니다.', '마법사 지구에 연금술 소품이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', '마법사 지구에 연금술 소품이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(920, 'koKR', '테룸 딥포지라는 드워프를 찾아가보십시오. 제가 아는 한 최고의 대장장이입니다. 드워프 지구 중앙에서 만나실 수 있을 겁니다.', '테룸 딥포지라는 드워프를 찾아가보십시오. 제가 아는 한 최고의 대장장이입니다. 드워프 지구 중앙에서 만나실 수 있을 겁니다.', '드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', '드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(921, 'koKR', '요리의 달인이 되고 싶으신가요? 구 시가지에 있는 돼지와 휘파람 선술집에 가셔서 스티븐 라이백을 만나보시기 바랍니다. 그 친구 갈비 요리는 누구도 따라올 수가 없답니다.\n\n이런, 갑자기 그가 만든 특제 돼지 갈비가 먹고 싶어 지는군요! 그 비법을 전수해 줄 거라곤 기대하지 마십시오!', '요리의 달인이 되고 싶으신가요? 구 시가지에 있는 돼지와 휘파람 선술집에 가셔서 스티븐 라이백을 만나보시기 바랍니다. 그 친구 갈비 요리는 누구도 따라올 수가 없답니다.\n\n이런, 갑자기 그가 만든 특제 돼지 갈비가 먹고 싶어 지는군요! 그 비법을 전수해 줄 거라곤 기대하지 마십시오!', '구 시가지, 돼지와 휘파람 선술집에 훌륭한 요리사가 일하고 있습니다. 우리끼리니까 하는 얘기지만, 요리할 때 칼 놀리는 솜씨를 보아하니 전에 요리사 말고 다른... 일도 했을 것 같더군요. 뭐, 이상한 상상은 하지 마시고... 요리를 배우고 싶으시다면 여기서는 그가 최고니까 찾아가 보십시오.', '구 시가지, 돼지와 휘파람 선술집에 훌륭한 요리사가 일하고 있습니다. 우리끼리니까 하는 얘기지만, 요리할 때 칼 놀리는 솜씨를 보아하니 전에 요리사 말고 다른... 일도 했을 것 같더군요. 뭐, 이상한 상상은 하지 마시고... 요리를 배우고 싶으시다면 여기서는 그가 최고니까 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(922, 'koKR', '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', '참, 그러고 보니 저도 로켓 장화를 수선해야 하는데... 한 가지 조언을 해 드릴까요? 로켓 장화는 그리핀과 함께 쓸 수 없답니다.$b$b아, 길을 물으셨죠... 드워프 지구로 가보세요. 구석진 곳에서 릴리암 스파크스핀들을 찾을 수 있을 겁니다.', '참, 그러고 보니 저도 로켓 장화를 수선해야 하는데... 한 가지 조언을 해 드릴까요? 로켓 장화는 그리핀과 함께 쓸 수 없답니다.$b$b아, 길을 물으셨죠... 드워프 지구로 가보세요. 구석진 곳에서 릴리암 스파크스핀들을 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(923, 'koKR', '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다.', '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다', '응급치료를 배우려면 빛의 대성당에 있는 샤이나 풀러의 지도를 받는 게 최고지요.\r\n\r\n그곳에 가시려면 노란 지붕을 찾아보시든가 대성당의 높은 첨탑을 찾아보십시오. 대성당은 도시의 거의 모든 곳에서 알아볼 수 있으니까요.', '응급치료를 배우려면 빛의 대성당에 있는 샤이나 풀러의 지도를 받는 게 최고지요.\r\n\r\n그곳에 가시려면 노란 지붕을 찾아보시든가 대성당의 높은 첨탑을 찾아보십시오. 대성당은 도시의 거의 모든 곳에서 알아볼 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(924, 'koKR', '타니사를 찾아가보시기 바랍니다. 마법사 지구의 연금술의 모든 것이라는 상점 밖에 서 있을 겁니다.', '타니사를 찾아가보시기 바랍니다. 마법사 지구의 연금술의 모든 것이라는 상점 밖에 서 있을 겁니다.', '자연과 교류하는 것만큼 즐거운 일도 없죠... 적어도 나이트 엘프들이 하는 얘기로는 그렇더군요. 저는 꽃이며 나무와 대화하는 데는 그다지 취미가 없습니다만, 타니사라면 틀림없이 도와 줄 수 있을 겁니다. 마법사 지구로 가보십시오. 연금술 소품이라는 상점 바깥에 서있을 겁니다.', '자연과 교류하는 것만큼 즐거운 일도 없죠... 적어도 나이트 엘프들이 하는 얘기로는 그렇더군요. 저는 꽃이며 나무와 대화하는 데는 그다지 취미가 없습니다만, 타니사라면 틀림없이 도와 줄 수 있을 겁니다. 마법사 지구로 가보십시오. 연금술 소품이라는 상점 바깥에 서있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(925, 'koKR', '가죽세공이라면 사이먼 태너가 제대로 가르쳐 줄 겁니다. 구 시가지에 있는 태너의 가죽용품점에 가면 만날 수 있을 겁니다.', '가죽세공이라면 사이먼 태너가 제대로 가르쳐 줄 겁니다. 구 시가지에 있는 태너의 가죽용품점에 가면 만날 수 있을 겁니다.', '가죽 냄새를 좋아하시는군요? 그러면 구 시가지에 있는 시몬 터너와 얘기해 보셔야 할 것 같네요. 터너의 가죽용품점이라는 가게를 운영하고 있습니다.', '가죽 냄새를 좋아하시는군요? 그러면 구 시가지에 있는 시몬 터너와 얘기해 보셔야 할 것 같네요. 터너의 가죽용품점이라는 가게를 운영하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(927, 'koKR', '겔만 스톤핸드를 만나보시는 게 좋겠군요. 드워프 지구에서 대성당 광장으로 나가는 통로 부근에 있던 어떤 집 안에 살고 있던 걸로 기억합니다. 정확히는 모르겠습니다. 우선 그쪽에서 이층집을 찾아보시기 바랍니다.', '겔만 스톤핸드를 만나보시는 게 좋겠군요. 드워프 지구에서 대성당 광장으로 나가는 통로 부근에 있던 어떤 집 안에 살고 있던 걸로 기억합니다. 정확히는 모르겠습니다. 우선 그쪽에서 이층집을 찾아보시기 바랍니다.', '아이언포지에서 드워프들이 채광 전문가랍시고 한 명을 보내서는 우리한테 채광이 이렇니 저렇니 하는데, 곡괭이 하나 들고 바위나 때리는 게 뭐 그리 어려운 일이라고 그러는지... 뭐, 그래도 여기 와 있는 이상 그를 찾아가 보는 게 좋겠지요. 겔만이라고 하는데, 드워프 지구에 살고 있습니다.', '아이언포지에서 드워프들이 채광 전문가랍시고 한 명을 보내서는 우리한테 채광이 이렇니 저렇니 하는데, 곡괭이 하나 들고 바위나 때리는 게 뭐 그리 어려운 일이라고 그러는지... 뭐, 그래도 여기 와 있는 이상 그를 찾아가 보는 게 좋겠지요. 겔만이라고 하는데, 드워프 지구에 살고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(928, 'koKR', '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', '오크를 때려 잡고, 트롤을 박살내고, 오우거 옆구리에 이름을 새기는 것까지는 할 수 있습니다. 하지만 짐승의 가죽을 벗기는 건 정말 못 하겠어요. 생각해 보세요, 정말이지...$b$b무두질을 할 만큼 비위가 강하시다면 구 시가지에 있는 터너의 가죽용품점에서 매리스 그랑거를 만나 보십시오.', '오크를 때려 잡고, 트롤을 박살내고, 오우거 옆구리에 이름을 새기는 것까지는 할 수 있습니다. 하지만 짐승의 가죽을 벗기는 건 정말 못 하겠어요. 생각해 보세요, 정말이지...$b$b무두질을 할 만큼 비위가 강하시다면 구 시가지에 있는 터너의 가죽용품점에서 매리스 그랑거를 만나 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(929, 'koKR', '조르지오 볼레로는 스톰윈드에서 가장 훌륭한 재봉사 중 하나랍니다. 그는 마법사 지구에 있는 던컨의 옷가게에서 근무하고 있으니 그곳으로 가보시기 바랍니다.', '조르지오 볼레로는 스톰윈드에서 가장 훌륭한 재봉사 중 하나랍니다. 그는 마법사 지구에 있는 던컨의 옷가게에서 근무하고 있으니 그곳으로 가보시기 바랍니다.', '재봉사라고요? 여기 오래 있다 보니, 조르지오 볼레로란 자에 대한 얘기를 듣게 되었지요. 벌써 여러 해 동안, 동부 왕국의 유행을 창조해, 선도해 가고 있는 최고의 재봉사입니다. 그에게 재봉술을 배우고 싶다면 마법사 지구 외곽에서 찾아보십시오.', '재봉사라고요? 여기 오래 있다 보니, 조르지오 볼레로란 자에 대한 얘기를 듣게 되었지요. 벌써 여러 해 동안, 동부 왕국의 유행을 창조해, 선도해 가고 있는 최고의 재봉사입니다. 그에게 재봉술을 배우고 싶다면 마법사 지구 외곽에서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(930, 'koKR', '씩씩이는 자신이 아직 소금 평원에 있다는 사실을 틸스에게 들키고 싶지 않아서 닭으로 변신했지요.$B$B혹시라도 씩씩이를 찾거든 \'/손짓\'을 해보십시오. 모습을 드러낼지도 모릅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(931, 'koKR', '일을 시작할 준비가 되었으면 좋겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(932, 'koKR', '경주에 오신 걸 환영합니다! 계시는 동안 맘껏 즐기시기 바랍니다. 하지만 당신 돈을 한 군데 몽땅 걸지는 마십시오!', '경주에 오신 걸 환영합니다! 계시는 동안 맘껏 즐기시기 바랍니다. 하지만 당신 돈을 한 곳에 몽땅 걸지는 마십시오!', '안녕하십니까, $c|1이여;여;! 소금 평원 경주에 온 걸 환영합니다!', '안녕하십니까, $c|1이여;여;! 소금 평원 경주에 온 걸 환영합니다!', '어느 차가 가장 빠를까요? 경주의 승패를 그 누가 알겠습니까?!', '어느 차가 가장 빠를까요? 경주의 승패를 그 누가 알겠습니까?!', '고블린 경주차가 힘이 좋긴 하지만 노움들도 자동차에 한두 가지 비장의 카드 정도는 숨겨놓았을 겁니다.', '고블린 경주차가 힘이 좋긴 하지만 노움들도 자동차에 한두 가지 비장의 카드 정도는 숨겨놓았을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(933, 'koKR', '어디로 가고자 하십니까?', '어디로 가고자 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(934, 'koKR', '세찬 빗속에 있다가 들어온 고양이처럼 내 마음을 마구 긁어대고 할퀴고... 또 할퀴고... 내가 입은 상처가 더 많은...?$B$B아. 들어오시는 걸 못 봤네요, $n! 뭘 도와 드릴까요?', '세찬 빗속에 있다가 들어온 고양이처럼 내 마음을 마구 긁어대고 할퀴고... 또 할퀴고... 내가 입은 상처가 더 많은...?$B$B아. 들어오시는 걸 못 봤네요, $n! 뭘 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(938, 'koKR', '이 세계를 우리 것으로 만들려면 전투로 지친 몸을 쉬게 해줘야 할 곳이 필요하답니다. 불 옆에 도끼를 내려두고 당신의 멋진 무용담을 들려주시기 바랍니다.', '이 세계를 우리 것으로 만들려면 전투로 지친 몸을 쉬게 해줘야 할 곳이 필요하답니다. 불 옆에 도끼를 내려두고 당신의 멋진 무용담을 들려주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(940, 'koKR', '수정 호수에서 즐기는 낚시만큼 여가시간을 보내는데 좋은 취미도 없답니다. 저도 아놀드 리랜드에게 낚시를 배웠죠. 밤낮 대운하 지역에 있는 부두에서 물때를 보고 있으니 쉽게 찾을 수 있을 겁니다.\n\n참, 그가 대운하에 괴물이 산다는 얘기를 하더라도 그 말을 믿지는 마세요. 절대...', '수정 호수에서 즐기는 낚시만큼 여가시간을 보내는데 좋은 취미도 없답니다. 저도 아놀드 리랜드에게 낚시를 배웠죠. 밤낮 대운하 지역에 있는 부두에서 물때를 보고 있으니 쉽게 찾을 수 있을 겁니다.\n\n참, 그가 대운하에 괴물이 산다는 얘기를 하더라도 그 말을 믿지는 마세요. 절대...', '리랜드라는 한량 말입니까? 그가 하는 일이라고는 상업 지구 외곽에 있는 부두에 죽치고 앉아 하루 종일 낚시하는 것뿐이죠. 늘 고기나 낚고 있으니 솜씨는 분명 괜찮을 겁니다. 낚시를 배우고 싶으시다면 그를 찾아가 보시죠.', '리랜드라는 한량 말입니까? 그가 하는 일이라고는 상업 지구 외곽에 있는 부두에 죽치고 앉아 하루 종일 낚시하는 것뿐이죠. 늘 고기나 낚고 있으니 솜씨는 분명 괜찮을 겁니다. 낚시를 배우고 싶으시다면 그를 찾아가 보시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(941, 'koKR', '루칸 코르델은 스톰윈드 지하감옥 근처 대운하 가장자리에 작은 상점을 하나 운영하고 있습니다. 장담하건대 그라면 마법부여의 경지가 무엇인지 보여줄 겁니다.', '루칸 코르델은 스톰윈드 지하감옥 근처 대운하 가장자리에 작은 상점을 하나 운영하고 있습니다. 장담하건대 그라면 마법부여의 경지가 무엇인지 보여줄 겁니다.', '아, 루칸 코르델을 찾으시는군요. 지하감옥으로 가는 길, 마법 지구 외곽에서 상점을 운영하고 있답니다.', '아, 루칸 코르델을 찾으시는군요. 지하감옥으로 가는 길, 마법 지구 외곽에서 상점을 운영하고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(942, 'koKR', '나는 이 땅에서 적을 몰아내고 명예를 지키기 위해 고독한 길을 걷고 있지.$B$B$n, 내가 도와줄 일이 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(943, 'koKR', '그래, 그대가 찾는 주술사를 본 적 있어. 마지막으로 목격한 게 아마 서쪽에서였지. 보통 서슬갈기 일족의 본거지가 내려다보이는 언덕에 숨어서 지낸다네. 머리를 좀 쓰면 포악한 가시멧돼지 무리와 맞닥뜨리지 않고도, 언덕 위 그녀의 집으로 가는 길을 찾을 수 있을 걸세. 여기서 북쪽으로 그리 멀지 않은 곳에 있으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1038, 'koKR', '으스러진 손은 스랄이 있기 전부터 존재했고 스랄이 죽은 후에도 존재할 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1039, 'koKR', '으스러진 손의 잔도잔이라고 하오. 나, 잔도잔이 뭘 도와주면 되겠소? 솔직히 이 잔도잔 할까 말까 고민 중이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1040, 'koKR', '훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', '훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1041, 'koKR', '손을 대자 기계가 살아난 듯이 움직입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1058, 'koKR', '그가 벌꿀술도 갖다 주고$B맥주도 갖다 줄 것이라네.$B입이 귀에 걸리도록 히죽대고 있는 얼굴$B해마다 변함없이 우리를 기쁘게 한다네.$B우리는 그를 유쾌한 짐이라 부른다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1059, 'koKR', '텔드랏실의 다른 곳에서는 볼 수 없는 아주 특이한 식물입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1060, 'koKR', '이 식물은 신기한 보라색 광채를 내뿜기 때문에 텔드랏실의 다른 식물들보다 눈에 잘 띄고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1079, 'koKR', '안녕하십니까. 저의 역할은 아제로스 세계에 창조주가 행한 토석인 합성에 대한 정보를 이용할 수 있게 해주는 일과 권한이 허용된 분에게 이 정보에 대한 지식을 제공하는 것입니다. 원하면 언제든지 정보를 이용할 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1080, 'koKR', '토석인이란 창조주가 합성한 종족의 하나로서 아제로스 세계의 초기 모태 종족 중 하나였습니다. 창조주는 이 세계의 기반을 만들 때 자신의 수고를 덜기 위하여 토석인을 창조했습니다.$B$B토석인은 창조주가 다른 세계에서 종족을 퍼뜨릴 때 사용한 지하 생물의 모형을 수정한 것입니다. 이들 원형 종족이 최초로 합성된 이후 다양한 변종이 태어났습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1081, 'koKR', '지하 생물 모형이란 창조주께서 이 세계에 종족을 퍼뜨릴 때 사용했던 합성 모형 중 하나입니다. 각각의 합성 모형을 사용해, 창조주는 자신의 목표를 이루었습니다. 아제로스의 경우 지하 생물 모형을 개조하여 내구력이 뛰어나고 지하 건설 작업에 적합한 생물을 창조했습니다. 토석인이 바로 이러한 모형 개조의 결과물입니다.$B$B그런데 이 토석인이 창조주를 위한 작업에 투입된 이후, 극한 환경의 영향으로 인해 그 합성 모형에 예상하지 못한 부작용들이 나타났습니다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1082, 'koKR', '그 질문에 대답하려면 먼저 토석인에 대한 자세한 설명이 필요할 것 같습니다.$B$B처리 중...$B$B토석인에게 나타난 부작용을 이해하기 위해서는 먼저 토석인의 설계 목적을 이해하는 것이 중요합니다. 토석인은 지하 생물 모형의 생존 능력을 향상시키고자 하는 창조주의 뜻에 따라 설계된 것이며, 아제로스에 함유된 탄력적인 조성 물질을 지하 생물 모형에 더해 만들었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1083, 'koKR', '탄력적인 조성 물질이란 종족 합성 시 사용되는 기본 성분을 말합니다. 창조주는 토석인을 합성하고자 일반적인 유기 조성 물질 대신 아제로스 지반을 구성하는 물질을 사용했습니다.$B$B창조주는 아제로스의 조성에 대해 연구한 끝에, 아제로스 본질의 탄력적인 전형이 될 수 있는 고급 생명체를 합성할 수 있다는 이론을 세웠습니다. 창조주는 그 이론에 따라 아제로스에 있는 다양한 바위의 핵심 성분을 기초로 하여 더욱 향상된 생명체를 만들었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1084, 'koKR', '단순하게 말하자면 그렇습니다.$B$B토석인의 신체는 신장이 작은 인간형 생물과 비슷하지만, 토석인을 이루고 있는 것은 아제로스에 있는 여러 가지 바위의 핵심 성분입니다. 토석인은 지적 처리 능력을 크게 떨어뜨리지 않고도 체력을 극대화하는 방식으로 설계되었습니다. 피부와 근육조직은 물리적 손상에 거의 영향을 받지 않으며, 아주 사소한 개조 단계만 거치면 마력에 대해 놀라운 저항 능력을 보입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1085, 'koKR', '이 정보를 완전히 이해하기 위해서는 먼저 알아두어야 할 사실이 있습니다. 창조주는 자신이 떠난 후에도 오랫동안 이 세계의 발전에 중요한 역할을 해줄 종족을 창조하고자 했습니다. 그래서 장기적으로 아제로스 발전에 중요한 존재가 될 종족을 만들었습니다.$B$B참고로 \"토석인\"이라는 이름은 창조주가 토석인을 만들 때 사용한 구성 물질을 고려하여, 이 종족에게 적절하다고 판단되는 명칭을 직접 붙인 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1086, 'koKR', '토석인 창조 시 나타난 유일한 부작용은 극도로 극한 환경에 처할 경우, 모형이 불안정해지는 경향이 있다는 것입니다.$B$B참고로 새로운 모형을 설계할 때, 지반 건설 작업은 극도로 긴장되는 환경을 복제하는 데 필요한 요구 사항을 충족시키지 못했습니다. 그러므로 초기에 부작용을 예상하지 못한 것은 당연합니다.$B$B불안정화 경향이 발견된 것은 토석인을 본격적으로 투입한 훨씬 다음의 일이었습니다. 창조주는 불안정화 경향이 나타나는 토석인을 모아 다시 합성하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1087, 'koKR', '[질문을 한 후 꽤 오래 시간이 지난 후...]$B$B현재 요청하신 정보는 본 정보 저장소의 자료에서 찾을 수 없습니다. 원하시는 정보를 제공하지 못한 데 대해 진심으로 사과 드립니다.$B$B본 정보 저장소의 자료 주기가 경신된 후에 요청하십시오. 아제로스에 있는 다른 정보 저장소에서 요청하실 수도 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1088, 'koKR', '토석인의 합성 모형이 불안정해지면 두 가지 결과가 나타날 수 있습니다. 시청각 자료 1번의 설명을 시작합니다...$B$B부작용의 결과, 첫 번째로 변형된 모형은 조합의 퇴행적 산물입니다. 일반적으로 \"트로그\"라는 명칭으로 불립니다. 이 변형체는 체력이 토석인과 비슷하나 지적 처리 능력은 거의 없는 것으로 판단됩니다. 따라서 트로그의 정신을 움직이는 것은 욕심, 의지, 그리고 교활함 뿐입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1089, 'koKR', '사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B트로그의 구성 성분 중에도 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 일부 들어 있으나, 지적 처리 능력의 부족으로 인해 이 변형체는 창조주를 만족시키지 못했습니다.$B$B트로그는 표준적인 생물로 번식했습니다. 하지만, 트로그는 기본적으로 다른 트로그를 포함해 바위와 손에 잡을 수 있는 건 무엇이든 먹어 치웁니다. 창조주는 동족을 잡아먹는다는 점을 받아들일', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1090, 'koKR', '시청각 자료 2번의 설명을 시작하겠습니다...$B$B토석인 모형에서 변형된 두 번째 생물은 표준 지하 생물 모형과 비교해 볼 때 바람직한 요소를 많이 지니고 있습니다. 이 변형 생물의 일반 명칭은 \"드워프\"입니다.$B$B드워프는 토석인 고유의 체력을 지니고 있습니다. 어떤 경우 토석인 모형의 지적 처리 능력을 능가하기도 합니다. 그러나 드워프에게는 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 전혀 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1091, 'koKR', '본 정보 저장소에 보관된 자료 내용과 방금 말씀하신 예리한 발언은 분명히 유효한 상관관계가 있습니다.$B$B드워프를 이루는 구성 성분은 아제로스의 돌과 관련이 있습니다. 그러나 극한 환경에 처하면 토석인의 조합 모형 내에서 부작용이 발생해 표준 지하 생물 모형에서 볼 수 있는 기본적인 생물 자원으로 퇴화하게 됩니다.$B$B그러므로 미루어 짐작하고 계셨듯이, 드워프 변형체는 토석인 합성 모형이 퇴화한 결과물입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1092, 'koKR', '사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B드워프의 정신적인 부분은 아제로스의 돌 구성에 거의 비슷하게 맞추어져 있습니다. 그러나 살아 있는 생물 자원으로 퇴행한 결과, 퇴화한 모형이 주된 부분을 이루고 있습니다. 드워프는 다른 표준 생물에서 흔히 볼 수 있는 방법으로 영양분을 섭취하여 번식합니다.$B$B창조주는 나름대로 가치가 있는 만족스러운 변형체로 드워프를 인식하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1093, 'koKR', '창조주는... 말 그대로 창조주입니다.$B$B창조주는 자신이 계획하고 설계한 그대로 이 세계를 만들고 종족을 퍼뜨렸습니다. 이 세계가 존재하는 근원은 창조주입니다. 물론 다른 수많은 세계가 존재하게 한 장본인이기도 합니다. 즉 아제로스를 창조한 근원인 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1094, 'koKR', '창조주 또한 본 저장소에 보관된 정보가 방대하다는 사실을 인식하고 있습니다. 노르간논의 원반만 맞춘다면 이곳에 저장된 자료의 복사본을 이용하실 수 있습니다.$B$B이제 당신은 본 정보를 이해하기 위한 최소한의 요구 사항은 모두 갖추었습니다. 원하시는 때 노르간논의 원반에 접속해 원반을 조합하기만 하면 됩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1118, 'koKR', '오, 대장장이가 되고 싶습니까? 저기 있는 장갑과 망치를 집으십시오. 실력이 어떤지 한번 보겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1119, 'koKR', '이렇게 훌륭한 방어구를 본 게 실로 몇 년만인지 모르겠소, $n. 대용광로에서 그룸누스 스틸셰이퍼의 수습 대장장이로 일할 때 이후로는 처음이오. 그라면 분명 방어구 제작에 대해서 당신의 흥미를 끌 만한 기술을 가르쳐줄 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1120, 'koKR', '그룸누스를 만나고 싶으면 먼저 아이언포지로 가십시오. 그 도시 한복판으로 가서 대용광로를 둘러보면 그를 찾을 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1121, 'koKR', '$n, 당신의 솜씨는 아주 훌륭하군. 인정하긴 싫지만 당신이 만드는 검과 도끼가 내 것보다도 우수한 것은 사실이오. 내가 만난 이들 중에 당신보다 더 기술이 좋은 자는 보르구스 스틸핸드 밖에 없소. 그라면 분명 당신에게 한 수 가르쳐 줄 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1122, 'koKR', '보르구스에게 훈련을 받고 싶다고요? 어디 있는지 가르쳐 드리겠어요. 내 대장간에서 북서쪽에 있는 사거리를 지나 서쪽 길로 가십시오. 오른쪽 두 번째 건물에 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1123, 'koKR', '지금 일하느라 바쁜 게 안 보이나? 내 시간을 뺏으려면 그럴듯한 이유를 대야 할 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1124, 'koKR', '이 땅은 으스러진 손이 지배한다. 우리는 섭정, 치안대, 재판관, 배심원, 그리고 사형 집행자로서 칼림도어를 뒤덮고 있다. 으스러진 손은 모든 것을 볼 수 있고 모든 것을 알고 있다.$B$B당신은 으스러진 손에 봉사하면서 많이 성장했으니 이제 실전 경험을 쌓을 때가 됐다.$B$B다음 임무를 맡을 준비는 되었나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1127, 'koKR', '대용광로에 온 것을 환영하오. 바깥은 추워도 여기는 항상 따뜻하고 편안하지. 망치를 들고 저 모루를 한번 때려보시오. 대용광로의 대장장이가 될만한 소질이 있나 보겠소이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1128, 'koKR', '모양이 제대로 잡힌 걸 보니, 분명 기능도 괜찮을 거야. 술 내기를 해도 좋아. 브루크의 모퉁이 선술집에서 말이오. $n, 이제 미올로 선더퓨리를 찾아가 보시오. 당신에게 뭔가 가르쳐 줄 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1129, 'koKR', '미올로가 어디 있는지 당연히 가르쳐 드려야죠. 대용광로의 모루 근처에서 일하고 있어요. 그만한 솜씨를 가진 사람도 없으니 미올로의 말을 귀담아 들으세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1130, 'koKR', '아주 맘에 드는 친구로군. 내가 가르친 사람 중에 이렇게 칼을 잘 만드는 사람은 정말 오랜만이오. 하지만 진짜 무기를 만들고 싶거든 미올로 선더퓨리를 찾아가 보시오. 그 드워프라면 당신에게 칼 만드는 법 하나는 제대로 가르쳐줄 수 있을게요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1131, 'koKR', '미올로를 보러 가겠다고? 바로 저기 있소. 당신 뒤에 말이오! 아니... 당신 앞이라고 해야 하나? 어쨌든 거대한 모루 근처에 있소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1132, 'koKR', '무언가 이 탑에 역병을 퍼뜨리고 있소. 탑 안은 물론이고 근처에서 일하던 다른 투자개발회사 일꾼들도 병에 걸렸소이다. 지난주에만 감시관 둘이 숨졌지. 그런데 글쎄, 죽은 직후 넋 나간 돌연변이로 되살아나지 뭐요!$B$B내 몸에서도 생명력이 빠져나가고 있소. 통제력도 점점 잃어가고. 사악한 충동이 나를 지배... 나쁜 충동이... *피줄이 자신의 따귀를 때립니다* 아직은 안 돼. 잘 들으시오... 나는 이 탑을 감독하는 자요. 이 정도 자리에 있으면 민감', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1133, 'koKR', '정신이 제대로 박힌 건가? 그게 무슨 무기라고 만들고 있나? 배추나 다듬을 수 있겠구먼. 나는 초보자는 가르치지 않네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1135, 'koKR', '고작 이것 때문에 날 성가시게 한 거요? 이 쓰레기를 입고 다니느니 토끼 가죽을 걸치고 트롤의 소굴을 뛰어다니는 것이 낫겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1136, 'koKR', '$n|1이라;라; 했소? 아주 강하고 훌륭한 걸 걸치고 있군그래. 훈련을 시켜주지. 마그니 왕께서 몸소 걸칠 만큼 훌륭한 갑옷을 만드는 법을 가르쳐주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1138, 'koKR', '약 5개월 전, 투자개발회사의 가시덤불 지부에서는 무법항에 있는 크랭크 피즐버브라는 수상한 상인에게 특수한 독을 받기로 계약을 했소. 피즐버브는 잔질에게 독을 훔쳐온 게 분명하오!$B$B그래, 추방자 잔질 말이오. 그 트롤은 강령술 실험을 하곤 했는데, 그 때문에 부족에서 영원히 추방당하고 말았소.$B$B그들은 독을 받은 후 서로 시험해 보기 시작했고 그 결과는 실로 참담했소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1158, 'koKR', '결국, 총감독 푸직 갤리윅스가 끼어들었고 그 나머지 독을 이곳 진흙 늪에 있는 자기 탑으로 가져왔소. 독의 불안정한 성질을 연구하기 위해서라고 둘러대고서 말이지. 그는 데피아즈 결사단에게 그 독의 비밀을 알려주는 대가로, 안정적인 독을 대량 공급받기로 결정했지.$B$B데피아즈 결사단에서는 클라벤 몰트웨이크가 잔질의 혼합물이 지닌 화학적 성질을 바꾸는 일을 맡게 되었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1159, 'koKR', '중간은 생략하고... 그 결과 얻게 된 제조법은 꽤 효과가 있어서 일꾼들을 좀 더 잘 조종할 수 있게 됐지만, 부작용은 여전히 있었다오. 비활성 혼합물의 휘발성이 너무 높았지...$B$B갤리윅스와 탑 안팎에 있는 자들은 모두 독에 감염되어 버렸소. 그 독은 우리의 신체와 정신에 영향을 미치지. 그 때문에 내부 기관이 극도로 약해져 버렸소. 이게 당신의 기회요, $n. 나는 더는 버틸 기운이 없소. 곧 \'그들\'과 한패가 돼버릴 것 같소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1160, 'koKR', '이 탑의 방어력은 매우 약해져 있소. 투자개발회사 순찰대원, 보초, 망꾼은 물론이고 갤리윅스마저 감염되었기 때문에 당신의 공격에 힘없이 무너질 거요.$B$B탑 안으로 들어가시오. 적을 모두 처치하고 나올 때는 잊지 말고 가방에 총감독 푸직 갤리윅스의 머리카락과 남아있는 혼합물을 담아오시오. 그것을 셴툴에게 가져다주시오. 아마도... 그라면 무엇을 해야 할지 알 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1202, 'koKR', '이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', '이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1203, 'koKR', '오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', '오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1205, 'koKR', '여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', '여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1206, 'koKR', '스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', '스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1207, 'koKR', '요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', '요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1208, 'koKR', '이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', '이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1210, 'koKR', '무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', '무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1215, 'koKR', '큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', '큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1216, 'koKR', '스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있소.', '스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1217, 'koKR', '엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', '엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1218, 'koKR', '배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', '배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1219, 'koKR', '전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', '전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1220, 'koKR', '오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', '오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1221, 'koKR', '무슨 일이십니까? 도와드릴 일이 있습니까?', '무슨 일이십니까? 도와드릴 일이 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1225, 'koKR', '난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', '난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1226, 'koKR', '이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', '이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1228, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1231, 'koKR', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', '저는 이곳 스톰윈드의 장인과 마법사가 만든 최고의 마법 장비만을 팔고 있습니다. 원하시는 물건이 있으시면 말씀해 주시기 바랍니다.', '저는 이곳 스톰윈드의 장인과 마법사가 만든 최고의 마법 장비만을 팔고 있습니다. 원하시는 물건이 있으시면 말씀해 주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1232, 'koKR', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', '저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 물건만을 팔고 있습니다. 천천히 둘러보시기 바랍니다.', '저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 물건만을 팔고 있습니다. 천천히 둘러보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1233, 'koKR', '우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', '우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1234, 'koKR', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', '저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 장비만을 팔고 있어요. 천천히 둘러보도록 하세요.', '저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 장비만을 팔고 있어요. 천천히 둘러보도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1235, 'koKR', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '어서 오십시오, 손님. 저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 천천히 둘러보시기 바랍니다.', '어서 오십시오, 손님. 저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 천천히 둘러보시기 바랍니다.', '어서 오십시오. 오늘은 그냥 구경하시는 겁니까 아니면 특별히 찾으시는 것이 있으십니까?', '어서 오십시오. 오늘은 그냥 구경하시는 겁니까 아니면 특별히 찾으시는 것이 있으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1236, 'koKR', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑한답니다. 찾으시는 물건이 있으신가요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑한답니다. 찾으시는 물건이 있으신가요?', '어서 오세요. 오늘은 그냥 구경하시려고 오셨나요 아니면 특별히 찾는 물건이 있으신가요?', '어서 오세요. 오늘은 그냥 구경하시려고 오셨나요 아니면 특별히 찾는 물건이 있으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1237, 'koKR', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '어서 오십시오. 저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 천천히 둘러보도록 하십시오. 혹시 찾는 물건이라도 있으시다면, 말씀만 하세요.', '어서 오십시오. 저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 천천히 둘러보도록 하십시오. 혹시 찾는 물건이라도 있으시다면, 말씀만 하세요.', '어서 오세요. 오늘은 그냥 구경하러 오셨나요. 아니면 특별히 찾는 물건이라도 있으세요?', '어서 오세요. 오늘은 그냥 구경하러 오셨나요. 아니면 특별히 찾는 물건이라도 있으세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1238, 'koKR', '엄격한 품질 점검을 거친 최고의 장비만을 취급하는 만큼, 정가 판매만 고집하고 있습니다. 값을 깎고 싶다면 고블린에게나 가보시는 게 좋겠습니다.', '엄격한 품질 점검을 거친 최고의 장비만을 취급하는 만큼, 정가 판매만 고집하고 있습니다. 값을 깎고 싶다면 고블린에게나 가보시는 게 좋겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1239, 'koKR', '엄격한 품질 기준을 통과한 최고의 장비만을 판매하는 만큼 에누리는 없으니, 값을 깎으려거든 고블린에게나 가보시오.', '엄격한 품질 기준을 통과한 최고의 장비만을 판매하는 만큼 에누리는 없으니, 값을 깎으려거든 고블린에게나 가보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1240, 'koKR', '저희는 최고의 장비만을 취급합니다. 엄격한 품질 기준을 통과한 진짜 물건들입니다. 죄송하지만 깎아드릴 수는 없으니 흥정을 하시려거든 고블린에게나 가보시는 게 좋겠네요.', '저희는 최고의 장비만을 취급합니다. 엄격한 품질 기준을 통과한 진짜 물건들입니다. 죄송하지만 깎아드릴 수는 없으니 흥정을 하시려거든 고블린에게나 가보시는 게 좋겠네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1241, 'koKR', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요하시면 부르시기 바랍니다.', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요하시면 부르시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1242, 'koKR', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요한 게 있으면 부르도록 하십시오.', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요한 게 있으면 부르도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1243, 'koKR', '시장에 있는 인간들은 믿지 마세요. 노움이 건설한 지하철 덕분에 아이언포지에서 물건을 공수해오기가 생각보다 쉽답니다. 그러니까 수입 관세까지 붙여서 파는 상인이 있거든 그냥 돌아오세요. 제가 싸게 드리겠습니다.', '시장에 있는 인간들은 믿지 마세요. 노움이 건설한 지하철 덕분에 아이언포지에서 물건을 공수해오기가 생각보다 쉽답니다. 그러니까 수입 관세까지 붙여서 파는 상인이 있거든 그냥 돌아오세요. 제가 싸게 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1244, 'koKR', '글쎄, 젊고 활기찬 $c가 아니라면, 전장에서의 나의 업적에 대한 이야기에 이끌려 여기까지 온 것은 틀림없군!$B$B 지금은 이야기할 시간이 없어,훌륭하고 중요한 일들이 있기 때문이지! 앞으로 있을 영광된 일에 행운이 그대와 함께하기를...', '글쎄, 젊고 활기찬 $c가 아니라면, 전장에서의 나의 업적에 대한 이야기에 이끌려 여기까지 온 것은 틀림없군!$B$B 지금은 이야기할 시간이 없어,훌륭하고 중요한 일들이 있기 때문이지! 앞으로 있을 영광된 일에 행운이 그대와 함께하기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1249, 'koKR', '자, 80번 고리를 79번 구멍에 끼우면 쾅! 당연히 폭발하죠! 자, 내 물건들을 보여줄 테니, 구입하면 일단 릴리암에게 가서 사용법을 제대로 배워요. 폭발해서 눈썹 태워 먹지 않도록!', '자, 80번 고리를 79번 구멍에 끼우면 쾅! 당연히 폭발하죠! 자, 내 물건들을 보여줄 테니, 구입하면 일단 릴리암에게 가서 사용법을 제대로 배워요. 폭발해서 눈썹 태워 먹지 않도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1250, 'koKR', '어서 오십시오. 스톰윈드 은행에 오신 것을 환영합니다. 저희 은행은 생긴 이래로 단 한 건의 도난 사건도 발생한 적이 없습니다. 고객 만족을 위해 항상 최선을 다하겠습니다!', '어서 오십시오. 스톰윈드 은행에 오신 것을 환영합니다. 저희 은행은 생긴 이래로 단 한 건의 도난 사건도 발생한 적이 없습니다. 고객 만족을 위해 항상 최선을 다하겠습니다!', '어서 오십시오. 스톰윈드 은행입니다. 금융 업무뿐만 아니라 귀중품을 보관할 수 있습니다. 저희 은행에 보관함을 개설하셨나요, 손님?', '어서 오십시오. 스톰윈드 은행입니다. 금융 업무뿐만 아니라 귀중품을 보관할 수 있습니다. 저희 은행에 보관함을 개설하셨나요, 손님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1252, 'koKR', '어서 오십시오. 고독한 은둔자 선술집입니다. 마법에 재능이 있는 친구들이 모여 열정을 불태우는 곳이죠. 아, 화염 마법으로 불을 지른다는 건 아닙니다. 그냥 회포를 푼다는 말씀입죠. 헤헤... 뭘 도와드릴까요, 손님?', '어서 오십시오. 고독한 은둔자 선술집입니다. 마법에 재능이 있는 친구들이 모여 열정을 불태우는 곳이죠. 아, 화염 마법으로 불을 지른다는 건 아닙니다. 그냥 회포를 푼다는 말씀입죠. 헤헤... 뭘 도와드릴까요, 손님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1253, 'koKR', '내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오.', '내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1254, 'koKR', '어서 오십시오. 돼지와 휘파람 선술집입니다! 술 한잔 들고 와서 앉으시죠. 술자리에서 친구란 많으면 많을수록 흥겨운 법이니까요!', '어서 오십시오. 돼지와 휘파람 선술집입니다! 술 한잔 들고 와서 앉으시죠. 술자리에서 친구란 많으면 많을수록 흥겨운 법이니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1255, 'koKR', '저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?', '저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1256, 'koKR', '어서 오십시오. 오늘은 어디로 가시겠습니까, 손님? 몇 실버만 내시면 제 그리핀으로 천리마보다 더 빨리 목적지에 모셔다 드리겠습니다.', '어서 오십시오. 오늘은 어디로 가시겠습니까, 손님? 몇 실버만 내시면 제 그리핀으로 천리마보다 더 빨리 목적지에 모셔다 드리겠습니다.', '이 거대한 친구들은 걸어서는 갈 수 없는 길을 잘 알고 있지요. 신속하게 목적지에 모셔다 드리겠습니다. 가시는 동안 주위 경관이나 천천히 둘러보십시오.', '이 거대한 친구들은 걸어서는 갈 수 없는 길을 잘 알고 있지요. 신속하게 목적지에 모셔다 드리겠습니다. 가시는 동안 주위 경관이나 천천히 둘러보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1257, 'koKR', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있거든. 뭐 도와드릴 일이라도 있나요?', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있거든. 뭐 도와드릴 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1258, 'koKR', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있으니까요. 자, 뭐 도와드릴 일이라도 있습니까?', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있으니까요. 자, 뭐 도와드릴 일이라도 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1259, 'koKR', '어서 오십시오. 스톰윈드 길드 사무소입니다. 무엇을 도와드릴까요?', '어서 오십시오. 스톰윈드 길드 사무소입니다. 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1260, 'koKR', '스톰윈드 길드 사무소에 오신 것을 환영합니다. 어떤 업무를 도와드리면 되겠소이까?', '스톰윈드 길드 사무소에 오신 것을 환영합니다. 어떤 업무를 도와드리면 되겠소이까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1261, 'koKR', '그저 따뜻한 온기를 쬐면서 몸이나 녹이려고 대용광로까지 찾아온 건 아닐 테지. 어서 말해 보시오. 뭘 도와주면 되겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1262, 'koKR', '손톱 밑에 때 하며 튼튼한 골격까지 척 보기에도 타고난 대장장이로군그래. 당신의 몸속에는 대장장이의 피가 흐르고 있는 것이야. 그렇다면, 기술을 배우러 온 것이겠군. 자, 망치를 들어 보시오. 뭘 가르쳐야 할지 한번 보겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1272, 'koKR', '어떤 물건을 찾으시나요?', '무엇을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1291, 'koKR', '크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', '크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', '동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오.', '동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1292, 'koKR', '썬더 블러프 은행은 봉우리 하층에 있습니다.', '썬더 블러프 은행은 봉우리 하층에 있습니다.', '속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', '속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1293, 'koKR', '마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', '마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', '거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', '거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1294, 'koKR', '장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', '장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', '명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', '명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1295, 'koKR', '아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', '아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', '모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', '모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1296, 'koKR', '신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', '신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', '불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', '불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1297, 'koKR', '신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', '신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', '언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', '언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1298, 'koKR', '정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', '정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', '대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', '대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1299, 'koKR', '우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', '우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', '강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', '강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1300, 'koKR', '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1301, 'koKR', '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1302, 'koKR', '아주 재미있군요... 오크들은 인간 냄새가 역겹다 하고 인간들은 오크 냄새가 구역질 난다니 말이에요. 하지만 제겐 이 세계의 모든 종족이 같은 냄새를 풍겨요. 머리를 어지럽게 만드는 고약한 탐욕의 냄새.$B$B제 말이 맞지 않나요? 삶을 이끌고 결정하는 것들이 모두 욕심에서 비롯되지 않나요?$B$B그럼 될 대로 되라지. 고향에서 너무나 멀리 떨어진 이곳으로 저를 데려온 것이 탐욕이었으니 나를 다시 되돌려놓을 것도 탐욕이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1303, 'koKR', '이 굼이샤를 도우러 되돌아온 거예요? 고통이란 건 의지력이 약해질 때만 느껴지죠. 아무리 뼈를 깎는 고통이라도... $B$B걱정하지 마세요. 다행히 이번 수집 일은 의지력 따위와는 상관없을 테니... 당신이 물건을 가져 오면 꼭 보답하겠어요. 주인을 기다리고 있는 제 물건들은 비록 자질구레하지만 분명 마음에 들 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1332, 'koKR', '봉우리 중간층에 있는 베나의 연금술점에 가서 베나와 얘기해 보도록 하십시오. 그녀가 물약 제조 기술을 완벽히 터득할 수 있도록 도와줄 겁니다.', '봉우리 중간층에 있는 베나의 연금술점에 가서 베나와 얘기해 보도록 하십시오. 그녀가 물약 제조 기술을 완벽히 터득할 수 있도록 도와줄 겁니다.', '자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', '자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1333, 'koKR', '망치와 모루를 잡고 뜨거운 용광로에서 일하는 법을 배우고 싶으시군요? 그렇다면 봉우리 하층의 연못가에서 대장간을 하고 있는 카른 스톤후프가 잘 가르쳐줄 수 있을 겁니다.', '망치와 모루를 잡고 뜨거운 용광로에서 일하는 법을 배우고 싶으시군요? 그렇다면 봉우리 하층의 연못가에서 대장간을 하고 있는 카른 스톤후프가 잘 가르쳐줄 수 있을 겁니다.', '다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', '다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1334, 'koKR', '썬더 블러프에 아스카 미스트러너만한 요리사는 없답니다. 봉우리 상층에 있는 그녀의 주방으로 가 보시면 만날 수 있을 겁니다. 음... 그녀의 요리 냄새가 여기까지 나는 것 같군요.\n\n이런... 슬슬 배가 고픈데요.', '썬더 블러프에 아스카 미스트러너만한 요리사는 없답니다. 봉우리 상층에 있는 그녀의 주방으로 가 보시면 만날 수 있을 겁니다. 음... 그녀의 요리 냄새가 여기까지 나는 것 같군요.\n\n이런... 슬슬 배가 고픈데요.', '자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', '자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1335, 'koKR', '봉우리 중간층에 있는 돈스트라이더의 마법부여점을 찾아가 보시기 바랍니다. 테그가 기꺼이 도와줄 겁니다.', '봉우리 중간층에 있는 돈스트라이더의 마법부여점을 찾아가 보시기 바랍니다. 테그가 기꺼이 도와줄 겁니다.', '마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 던스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', '마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 던스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1336, 'koKR', '응급치료는 배워놓으면 아주 좋은 기술이랍니다. 저도 전쟁 중에 그것 덕분에 여러 번 목숨을 건졌답니다. 정기의 봉우리에 있는 정기의 치료소에 가시면 판드 스톤바인더가 자신의 목숨을 스스로 구하는 방법을 가르쳐줄 겁니다.', '응급치료는 배워놓으면 아주 좋은 기술이랍니다. 저도 전쟁 중에 그것 덕분에 여러 번 목숨을 건졌답니다. 정기의 봉우리에 있는 정기의 치료소에 가시면 판드 스톤바인더가 자신의 목숨을 스스로 구하는 방법을 가르쳐줄 겁니다.', '삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그렇기 때문에 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', '삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그렇기 때문에 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1337, 'koKR', '낚시를 배우시려고요? 멀고어에는 남부 칼림도어에서 으뜸가는 낚시터가 여러 곳 있고 봉우리 상층에 있는 산꼭대기 낚시용품점에는 온갖 낚시 장비가 다양하게 구비되어 있습니다.\n\n카 미스트러너를 만나 제가 보내더라고 전해주세요!', '낚시를 배우시려고요? 멀고어에는 남부 칼림도어에서 으뜸가는 낚시터가 여러 곳 있고 봉우리 상층에 있는 산꼭대기 낚시용품점에는 온갖 낚시 장비가 다양하게 구비되어 있습니다.\n\n카 미스트러너를 만나 제가 보내더라고 전해주세요!', '봉우리 상층, 산꼭대기 낚시용품점에 있는 카 미스트러너를 찾아가 보십시오. 요리에 쓸 물고기를 낚으면서 내면의 평화와 고요함을 찾는 법을 가르쳐줄 겁니다.', '높은 절벽 위 \'산꼭대기 미끼와 낚시도구점\'의 카 미스트러너를 찾아가게. 다음 끼니를 낚으면서 마음의 평화와 고요를 찾는 법을 알려 줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1338, 'koKR', '조화의 약초상점에 있는 코민 윈터후프를 찾아가 보셔야겠습니다. 그는 봉우리 중간층에 가시면 만나실 수 있답니다.', '조화의 약초상점에 있는 코민 윈터후프를 찾아가 보셔야겠습니다. 그는 봉우리 중간층에 가시면 만나실 수 있답니다.', '자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', '자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1339, 'koKR', '봉우리 중간층에 썬더 블러프 갑옷 상점에 있는 우나를 찾아가 보시기 바랍니다.', '봉우리 중간층에 썬더 블러프 갑옷 상점에 있는 우나를 찾아가 보시기 바랍니다.', '적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽 세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', '적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽 세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1340, 'koKR', '봉우리 하층에 있는 스톤후프 지질연구소로 가십시오. 브렉 스톤후프가 귀한 광석이나 보석을 캐내는 방법을 가르쳐 줄 겁니다.', '봉우리 하층에 있는 스톤후프 지질연구소로 가십시오. 브렉 스톤후프가 귀한 광석이나 보석을 캐내는 방법을 가르쳐 줄 겁니다.', '대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', '대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1341, 'koKR', '썬더 블러프 최고의 재봉사, 테파를 찾아가 보도록 하시기 바랍니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에 만나실 수 있습니다.', '썬더 블러프 최고의 재봉사, 테파를 찾아가 보도록 하시기 바랍니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에 만나실 수 있습니다.', '부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', '부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1343, 'koKR', '무두질이라면 무란타에게 배울 수 있을 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 그녀를 찾을 수 있을 겁니다.', '무두질이라면 무란타에게 배울 수 있을 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 그녀를 찾을 수 있을 겁니다.', '금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', '금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1351, 'koKR', '이 저주받은 땅의 짐승들은 지금까지 자연에서 한 번도 본 적 없는 기이한 성질을 나타내오.$B$B우리는 어둠의 문이 열리면서 방출된 에너지가 짐승의 육체와 결합해 지금의 형태로 변형된 것으로 본다오.$B$B두려워 할 만한 짐승들임에는 분명하지만 우리 연구에 상당히 쓸모가 있을 것이라 생각하오.$B$B짐승들 연구에 도움을 주지 않겠소, 용감한 $c|1이여;여;?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1371, 'koKR', NULL, '드라지알 오빠는 저주받은 땅에 서식하는 야생동물들의 육체적 특성을 주로 분석하지만, 저는 지적이고 영적인 면을 더 집중적으로 연구합니다.$B$B그 짐승들이 보기 드물게 강한 힘과 민첩성, 체력을 가진 것은 사실이지만 그중 일부는 육체에 구속되지 않은 높은 지능과 재생 능력도 보유하고 있답니다.$B$B$R|1이여;여;, 혹시 제 연구에 도움을 주실 생각은 없나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1391, 'koKR', '그렇게 작은 지역에 그토록 많은 죽음과 절망이 도사리고 있다는 게 상상조차 안 되겠지만, 저 늪에서 한 발짝만 넘어서도 혼돈과 파괴로 물든 땅이 있지.$B$B모험가 친구, 발밑을 조심하시오. 저주받은 땅은 당신보다 훨씬 강한 자들의 마지막 안식처니까 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1392, 'koKR', '스랄 직속 부대... 사람들은 우리를 이렇게 불렀지. 스랄 님의 병사 중 가장 실력이 뛰어나고 충성스러운 스무 명의 병사로 이뤄진 최정예부대였소.$B$B오그리마에서 명령서가 오기를 기다리는 동안 나는 저주받은 땅의 경계인 이곳에 야영지를 지으라고 지시했소. 몇 주가 지나도록 대족장님에게 아무런 소식이 없어 모두 불안해했지.$B$B나는 벌을 받은 거요, $n. 젊고 의욕에 넘쳤던 나는 아무것도 두려울 게 없었지. 대대를 이끌고 저주받은 땅으로 행군하기로', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1411, 'koKR', '후회... 그것이 지금 내게 남은 전부요. 잘못된 판단 하나가 끔찍한 결과를 낳고 말았소. 명령서를 기다렸더라면 좋았을 것을. 그랬더라면 저주받은 땅에서 우리를 기다리고 있던 공포에 대해 알 수도 있었을 텐데! 어쩌면 다른 곳으로 파견되었을지도 모르지. 결국 내 잘못이었소. 모든 게 내 잘못이었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1451, 'koKR', '내 생애에서 절정을 달리던 시기에 실패를 했다면 믿으시겠소? 그때가 내 평생 가장 눈부셨던 동시에 어두웠던 때라오.$B$B우리를 무자비하게 침략했던 세력으로부터 도망쳐 나올 때 내 귀에는 우리 병사들의 참혹한 비명 소리와 세차게 뛰는 내 심장의 빠른 고동소리만 들렸소.$B$B얼마 후 부하들을 구하고 명예를 회복하겠다는 기대를 안고 저주받은 땅으로 되돌아왔소. 하지만 붙잡혀서 구타당하다 죽고 말았지.$B$B그때 고문을 받으면서 알게 된 사실은 정말이지 끔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1452, 'koKR', '나를 붙잡은 녀석들은 차마 말로는 표현하지 못할 정도로 잔인했소. 부관 키리스와 나를 번갈아 고문하면서 괴로워하는 모습을 서로 강제로 지켜보게 하였소. 유독 고문이 심했던 어느 날인가 키리스는 잠잠한 틈을 타 우리 부하들에게 벌어진 끔찍한 사건과 그들을 해방시키기 위해 그가 세운 계획을 말해주었소.$B$B나의 부하들은 키리스와 내가 겪었던 고통보다, 아니 죽음보다도 더 끔찍한 운명에 괴로워했더군...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1453, 'koKR', '당신이나 나나 영혼이 육체에서 억지로 찢겨나갈 때의 고통은 상상도 할 수 없을 거요. 우리 병사들은 완전히 죽은 것도, 살아있는 것도 아닌 상태... 그 상태로 이 세계에 그들을 묶어둔 자들의 노예로 살아가야 했던 거요.$B$B바로 이 땅을 지배하는 악마 군주 라젤리크의 노예가 돼버린 것이오. 라젤리크는 그중 아홉 명을 어둠의 문 근처 봉인석에 배치하고 있소. 그리고 나머지 아홉은 자기 부하들에게 나눠주었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1454, 'koKR', '어둠혈맹 대마법사 알리스타즈에게 세 명, 어둠혈맹 흑마법사인 여군주 세바인에게 세 명, 그리고 이 저주받은 땅의 우레망치 오우거를 다스리는 파괴자 그롤에게 나머지 세 명을 주었소.$B$B당신도 이미 알고 있겠지만, 영혼이 없는 육체는 죽일 수 없소. 이제 내 부하들은 불로불사의 전투 부대가 되어 악의 명령에 따르고 있소. 그나마 다행인 것은 봉인석으로 이동할 수 있는 거리 내에서만 움직일 수 있다는 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1455, 'koKR', '바로 그 봉인석을 파괴해야 우리 부하들을 해방킬 수 있소! 아까도 말했지만 키리스에게는 계획이 있었소.$B$B라젤리크의 하수인에겐 모두 약점이 있소. 봉인석 근처에 있는 육신을 계속 공격하면 하수인들이 분열 상태에 가까워진다오. 바로 그때 봉인석을 공격해야 하오. 하수인들이 다시 깨어나면 아무리 공격해도 소용이 없으니 서둘러서 봉인석을 파괴해야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1456, 'koKR', '정말로 당신 혼자서 해낼 수 있다면 얼마나 좋겠소. 하지만 혼자 힘으로 라젤리크와 그 부하들을 상대한다는 것은 무리요.$B$B영웅이 되고자 모험을 하는 이들을 모아 우리 부하들을 끝이 없는 고통에서 해방시켜 주시오! 모두 18개의 돌을 부수어야만 하오.$B$B용맹스럽게 싸우다 명예롭게 죽으시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1471, 'koKR', '연금술 재료가 필요하시군요? 아니면 다른 볼일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1493, 'koKR', '사막에서 산다는 것은 참 고된 일이야! 이런 찌는 듯한 날씨에 횃불까지 들고 서 있으려니 정말 덥고 목이 마르는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1511, 'koKR', '도와줘!$B$B날 여기서 빠져나가게 해주면 줄파락의 두목이 있는 곳으로 통하는 문을 폭파해 버릴 수 있다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1513, 'koKR', '트롤을 더 많이 처치해야 해! 충분히 처치하면 트롤 두목에게로 통하는 문을 폭파해 주겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1514, 'koKR', '고마워, $n. 자네가 나타나지 않았더라면 난 분명 이미 죽은 목숨이었을 거야! 이제 우리 앞에 있는 저 문만 날려 버리면 트롤 두목이 기다리고 있을 거라고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1515, 'koKR', '도와주시오! 나는 일행과 함께 트롤들에게 붙잡혔소. 놈들은 우리를 희생 제물로 바치려 하고 있소!$B$B여기서 빠져나가게 해주면 당신이 원하는 것은 뭐든지 해주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1516, 'koKR', '떠들고 있을 시간이 없소! 저 트롤 녀석들을 처치해야 탈출할 수 있단 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1517, 'koKR', '고맙소, $n. 당신 없이는 빠져나오지 못했을 거요. 아, 전에 구해주면 보답을 하겠다고 했던가? 뭐... 그런 건 없었던 일로 하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1519, 'koKR', NULL, '안녕하세요! 모험을 즐기시는 분이시군요. 혹시 도전할 만한 일을 찾고 있다면 한 가지 제안이 있어요.$B$B지금 저는 열심히 드루이드들을 돕고 있어요. 제가 발명한 고성능 자동부화기로 히포그리프들을 구하려고요. 히포그리프들에게 페랄라스의 폐허에 사는 골두니 오우거들이 나쁜 영향을 미치고 있습니다. 때문에 그 수가 점점 줄어들고 있어요.$B$B그래서 저는 여러 종류의 알을 모은답니다. 저를 도와 알을 좀 찾아주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1521, 'koKR', NULL, '서쪽에 있는 페랄라스라는 곳에서 나이트 엘프들의 오랜 친구인 히포그리프들이 위험에 처해있다고 들었어요.$B$B남쪽의 이실디엔 폐허에서 알을 구해 오세요. 가져온 알은 고성능 자동부화기에 넣어 보면 부화할 수 있는지 알 수 있답니다. 제가 부화할 수 있는 알들만 드루이드들에게 보낼 거예요. 골두니 오우거의 사악한 마법을 피해 건강한 히포그리프로 자랄 수 있도록 말이지요.$B$B구해 온 알들 중 일부는 상태가 좋지 않아서 절대 부화하지 않는다는 걸 알아두세', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1569, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1571, 'koKR', '안녕하세요! 찾고 계신 물건이 제 가게에서 안 보이시나요? 말씀만 하시면 제가 꼭 구해다 드리겠습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1597, 'koKR', '아이언포지에서 이렇게 멀리 떨어진 곳에서는 대장장이를 보는 일이 드문데... 뭘 도와주면 좋겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1598, 'koKR', '나는 머리 위에 튼튼한 화강암 천장이 없으면 편히 쉴 수가 없답니다. 머리 위에 별이 어찌나 많은지 등골이 서늘할 정도라니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1599, 'koKR', '이 정도는 돼야 입을 만한 쇳덩어리라고 할 수 있지. 모양새에 기능까지 골고루 갖추다니 놀랐습니다. 이만한 건 예전에 딱한 번 본 적이 있는데 대용광로에 있는 장인인 그룸누스 스틸셰이퍼가 만든 것이었지요. 분명 그 친구는 그때보다 솜씨가 더 늘었을 거요. 당신에게 한 수 가르쳐 줄 수도 있겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1600, 'koKR', '아이언포지 한복판에 있는 대용광로로 가 보십시오. 그는 그곳에서 우리 종족의 다른 훌륭한 장인들과 함께 일하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1605, 'koKR', '내 작업장에 온 걸 환영하네, 대장장이 친구. 한 가지 작은 비밀을 가르쳐 주지. 이 세상에 어느 누구도 믿을 자가 없다는 거야. 남자든, 여자든, 동물이든지 할 것 없이 모두... 하지만 단 한 가지 믿을 게 있다면, 바로... 강철이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1606, 'koKR', '내 작업장에 뭘 찾으러 온 건가? 훈련을 받고 싶나? 아니면 강철의 비밀이라도 캐러 왔나? 아니면 가열로의 신비를 파헤치러? 어서 말해 보게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1609, 'koKR', '오그리마에 있는 명예의 골짜기로 가시오. 그곳에서 그녀는 남편과 두 딸이 함께 살고 있소. 실력이 뛰어난 대장장이는 많지만, 정령들이 말하길 당신을 가장 잘 지도할 사람은 그녀뿐이라는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1610, 'koKR', '이제 솜씨는 내가 결코 따라갈 수가 없구려. 강철에 영혼의 숨결을 불어넣어 자신을 보호할 수 있으니 말이오. 제자가 스승을 능가했으니 이제는 더 가르칠 것이 없소이다. 계속 가르침을 받을 수 있는 곳으로 보내겠소. 오그리마에 있는 샤이스 스틸퓨리를 찾아가시오. 그는 내가 아는 최고의 방어구제작자이니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1611, 'koKR', '모든 것에는 영혼이 있소. 영혼의 소리에 귀 기울이는 법을 배우면 사물의 모습을 당신이 원하는 대로 바꿀 수 있지. 대장장이 일이란 금속을 쳐서 당신이 원하는 모양을 억지로 만들어 내는 게 아니오. 강철 속에 살아 숨 쉬는 영혼의 소리에 귀를 기울여 그 영혼이 취하려는 모습으로 인도하는 것이지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1615, 'koKR', '당신은 지식을 갈구하는 자로 보이는군. 가열로와 망치 다루는 법을 배우고 싶은 것이겠지. 대장장이의 길을 걸어가는 데 내가 도움을 줄 수 있을 것 같소. 하지만 먼저 영혼의 존재를 인정하고 그 부름에 귀를 기울여야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1616, 'koKR', '명예의 골짜기에서 그녀와 그녀의 일족을 만날 수 있을 테니 오그리마로 가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1617, 'koKR', '$n, 자네가 만드는 방어구라면 아무리 날카로운 도끼날이라도 모두 받아 낼 수 있을 거야. 흔하게 볼 수 있는 솜씨가 아니라 정말 놀랍군. 샤이스 스틸퓨리라는 오크를 찾아가 보게. 지금 천벌이나 받을 드워프들의 요새 바깥에 머물고 있지만, 방어구 하나는 최고로 훌륭하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1618, 'koKR', '자네가 만드는 검날이 적의 복부를 꿰뚫기에 부족함이 없겠나? 무기의 날을 더욱 날카롭게 다듬는 법을 가르쳐주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1619, 'koKR', '대장장이가 되고 싶나? 단숨에 적을 가를 만큼 날카로운 검을 만들고 싶은가? 살짝 대기만 해도 목표물을 완전히 부숴 버릴 망치를 만들고 싶은 게로군. 도와주지. 그 무기로 갚아야 할 원한이 있다면 더더욱!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1620, 'koKR', '오크의 도시, 오그리마로 가게. 명예의 골짜기에 전설의 무기점이라는 곳이 있다네. 그곳에서 그를 찾아보도록 하게.', '오크의 도시 오그리마로 가게. 명예의 골짜기에 있는 \'전설의 무기\'라는 상점에서 그를 찾을 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1621, 'koKR', '$n, 아주 날카로운 검을 만들 줄 아는군. 바위라도 베어낼 수 있을 정도로 날카로운... 하지만 그보다 더 나은 것들을 본 적이 있다네. 바로 켈그룩 블러드액스라는 오크가 만든 것. 가서 그가 가르쳐 주는 건 모두 배우도록.', '칼을 제법 잘 만드는군, $N. 돌을 베고도 목을 그을 만큼 날이 살아 있어. 하지만 더 좋은 칼도 본 적 있지. 켈그룸 블러드액스라는 오크가 그런 걸 만든다네. 가서 그가 가르쳐 줄 수 있는 건 모두 배우게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1633, 'koKR', '대용광로에 또 왔군, $n. 반갑소. 이 늙은 드워프를 보러 온 건가, 아니면 다음 훈련을 받을 준비가 되어서 온 것이오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1634, 'koKR', '좋은 강철이군, $n. 망치를 들고 이리 와 보게. 전설의 무기를 만드는 비법을 가르쳐 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1635, 'koKR', '뭔가? 일하느라 바쁜 거 모르겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1637, 'koKR', '더 배우러 온 건가, $n? 더 가까이 와보게. 준비가 되었나 보겠어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1638, 'koKR', NULL, '여행은 어땠나요, $n? $g수미와 투미가 당신을 보고 싶어 했어요. 다 배우면 가서 인사라도 나누세요:당신의 모험 얘기를 전해 들었어요. 꽤 바쁜 나날을 보낸 것 같더군요;. 자, 이곳을 떠나 있던 동안 뭘 배웠는지 한번 볼까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1640, 'koKR', NULL, '난 실력이 없는 대장장이들은 훈련시키지 않는답니다. 쓸 만한 물건을 만들 실력을 갖췄다 싶을 때 다시 오도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1641, 'koKR', NULL, '재능이 있군요, $n. 자, 연습이 많이 필요하니 망치와 그 조각들을 좀 가지고 오세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1643, 'koKR', '지지직!$B$B보안 수준 알파 터미널인 행렬 천공기록기 3005-A에 오신 것을 환영합니다.$B$B터미널 기능을 이용하시려면 백색 천공 카드가 있어야 합니다.\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1644, 'koKR', '흰색 보안 카드 삽입 성공.$B$B보안 수준 베타 유닛 적용 중.\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1646, 'koKR', NULL, '골두니 오우거 부족은 페랄라스의 숲 상당 부분을 지배하고 있습니다. 그들의 사악한 마법이 주위의 자연에 스며들어 주변 환경은 물론 그곳에 사는 생명체들에게도 해를 끼치고 있답니다.$B$B혹시 페랄라스로 갈 생각이라면 이 오우거들을 조심하세요. 상당히 간악한 데다 강력한 어둠의 마법을 부릴 줄 아는 녀석들이 많으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1647, 'koKR', '지지직!$B$B보안 수준 베타 터미널인 행렬 천공기록기 3005-B에 오신 것을 환영합니다.$B$B터미널 기능을 이용하시려면 황색 천공 카드가 있어야 합니다.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1648, 'koKR', '황색 보안 카드 삽입 성공. 보안 수준 카이 유닛 적용 중...\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1649, 'koKR', '지지직!$B$B보안 수준 카이 터미널인 행렬 천공기록기 3005-C에 오신 것을 환영합니다.$B$B터미널 기능을 이용하시려면 청색 천공 카드가 있어야 합니다.\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1650, 'koKR', '청색 보안 카드 삽입 성공. 보안 수준 델타 유닛 적용 중.\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1651, 'koKR', '지지직!$B$B보안 수준 델타 터미널인 행렬 천공기록기 3005-D의 실행을 시작합니다.$B$B터미널 기능을 이용하시려면 적색 천공 카드가 있어야 합니다.\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1652, 'koKR', '적색 보안 카드 삽입 성공. 보안 수준 델타 데이터 카드 적용 중...\n\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 0110010', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1653, 'koKR', '에라카 노 킴블$B호랑이의 신이자 야수의 제왕, 고양이의 왕으로 모든 사냥감을 파멸로 이끄시는 분$B$B부에타이 노 무에잘라$B$B죽음의 신이시며 영원한 잠의 아버지, 시간의 아들이자 어두운 밤의 절친한 벗', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1654, 'koKR', '엘로르타 노 샤드라$B거미의 신, 독의 어머니, 비단 무용수, 죽음의 연인', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1655, 'koKR', '행렬 천공기록기의 최첨단 적성검사 모듈이 당신의 기계공학 소질을 감지했습니다. 다음 옵션 중 하나를 선택할 수 있습니다:\n\n01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1656, 'koKR', '접근 중...\n\n무효 -- 기술자 <기술 난이도 == 초급>\n \n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\n\n접근이 거부되었습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1657, 'koKR', '자료 접근 허가 완료.\n\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1673, 'koKR', NULL, '잠깐만요, $n. 킨달이 저 아래 그림토템 야영지에서 요정용을 풀어주려고 하고 있어요. 제때 도움을 받을 수 있어서 다행이었어요. 저 악독한 타우렌 녀석들이 무슨 짓을 했을지 어떻게 알겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1674, 'koKR', '안녕하십니까. 저는 입구를 지키는 문지기입니다. 원반 세트에 울둠의 원반을 결합하지 않으면 울둠으로 들어갈 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1675, 'koKR', '울둠의 원반이란 울둠 단지의 출입을 허가하기 위해 창조주가 만들어낸 것입니다. 이 원반에는 이 안에서 진행되는 창조주의 활동과 관련된 자세한 자료가 저장되어 있습니다.$B$B겉모양이나 크기는 지금 당신이 가지고 있는 원반 세트와 거의 동일하지만 울둠의 원반에 있는 표식들은 울다만이 아닌 울둠에 관한 정보와 직접적인 관련이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1676, 'koKR', '제 임무는 창조주를 위해 울둠 단지의 출입을 통제하는 것입니다. 이 문을 두드리는 자에게 적합한 원반 세트가 있을 때만 출입이 허가됩니다.$B$B현재 당신의 원반 세트에는 울둠의 원반이 포함되어 있지 않습니다. 울둠의 원반이 없으면 출입이 허가되지 않습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1677, 'koKR', '창조주들은 자신들이 사용할 목적으로 울둠의 원반을 여러 개 만들어두었습니다. 원반을 세계 각지에 배포하는 건 그들의 일입니다. 아제로스 방문 일정이 변경되었고 결과적으로 그때 원반이 추가로 배포될 수 있는 것입니다.$B$B기존 원반은 보안 권한이 있는 자들에게 이미 모두 배포된 상태입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1678, 'koKR', '내부와 외부의 세력이 세계의 원동력을 파괴하면 창조주들은 이 세계를 방문해 그들이 씨를 뿌린 세계에 대한 지배력을 회복하려고 할 것입니다. 이때를 가볍게 보고 넘겨서는 안 됩니다.$B$B이 세계의 방문 예정에 관한 정보는 해당 자료 저장소를 찾아보시기 바랍니다. 이곳에서 창조주의 방문 일정을 계획할 때 고려하는 사항이 처리되고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1679, 'koKR', '울둠은 창조주의 연구 시설로서 아제로스의 생활 수준을 향상시키기 위한 노력의 일환으로 만들어졌습니다. 울둠의 작업에 대한 자세한 내용은 울둠의 원반이 있는 분에게만 공개하도록 제한되어 있습니다.$B$B울둠 내 정보 저장소는 특수한 실험 결과를 처리하도록 프로그램되어 있습니다. 자세한 내용은 이 정보 저장소를 참조하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1693, 'koKR', NULL, '와줘서 정말 고마워요! 지금은 머리가 둘 달린 오우거에게라도 도움을 받고 싶은 심정이에요.\n\n도시가 트로그에게 점령당했어요! 녀석들을 몰아내려다가 심하게 오염돼 버렸지만 아직 희망은 있어요.\n\n아이언포지로 피신한 우리 과학자들이 지금 방사성 질병 치료제를 연구하고 있어요. 그동안 당신이 트로그의 침략을 막을 수 있도록 도와준다면 도시를 되찾을 수 있을지도 몰라요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1713, 'koKR', '몇 분만 시간을 주십시오. 조금 전 여기서 소동이 있었는데 이제는 좀 잠잠해졌는지 확인해보고 싶군요. 곧 다시 얘기를 하도록 하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1734, 'koKR', '푸른달 골동품점에 온 걸 환영하오. 찾는 물건이라도 있으면 말해 주시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1753, 'koKR', '지지직!$B$B보안 수준 알파 터미널, 행렬 천공기록기 3005-A에 오신 것을 환영합니다.$B$B백색 천공 카드가 감지되었습니다. 사용을 허가합니다.\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 0111010', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1754, 'koKR', '지지직!$B$B보안 수준 베타 터미널, 행렬 천공기록기 3005-B에 오신 것을 환영합니다.$B$B황색 천공 카드가 감지되었습니다. 사용을 허가합니다.\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 0111001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1755, 'koKR', '지지직!$B$B보안 수준 카이 터미널, 행렬 천공기록기 3005-C에 오신 것을 환영합니다.$B$B청색 천공 카드가 감지되었습니다. 사용을 허가합니다.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 0010000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1756, 'koKR', '지지직!$B$B보안 수준 델타 터미널, 행렬 천공기록기 3005-D에 오신 것을 환영합니다.$B$B적색 천공 카드가 감지되었습니다. 사용을 허가합니다.\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1757, 'koKR', '우리가 맞서 싸우는 생물체의 영혼, 즉 \"뮤세크\"에는 엄청난 힘이 담겨져 있지.$B$B자신을 돌아보고 자신의 고유한 영혼의 힘을 다루는 방법을 익히도록 하게. 그러면 자네는 자네가 상상했던 것 이상의 힘을 갖게 될 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1758, 'koKR', '술트라제... 처음으로 이 말을 들은 게 아마 그대 나이쯤이었을 것입니다. 지금 이 말이 그대에게 아무 의미가 없듯이 그때는 내게도 어떤 의미도 없었지요. 줄파락에서 온 트롤 부대가 이 땅을 파괴한 후에야 그 이름을... 두려워하게 됐습니다.$B$B아마 많은 이들은 고통의 영검 같은 건 존재하지 않는다고 말할 것입니다. 우는 아이를 달래기 위해 만들어낸 이야기라면서 말이지요. 하지만 고통의 영검은 정말로 존재합니다. 저를 믿으십시오.$B$B<갑자기 멍한', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1759, 'koKR', '둘로 갈라졌지만 모이면 하나가 되지요. 이 쌍둥이 검은 줄파락에 묶여 있습니다.$B$B이 두 검을 찾으면 술트라제가 부활할 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1793, 'koKR', '테라모어 경비병들은 칼림도어에 주둔하고 있는 얼라이언스 병사 중 가장 뛰어난 집단이지. 우리 고향에서 이렇게 멀리 떨어진 곳에서도 얼라이언스의 법을 수호하는 것이 우리의 임무라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1794, 'koKR', '우린 제임스 하이얄의 아내와 아이가 빠져나오지 못했다는 것 외에는 그늘 쉼터 여관의 화재에 대해선 아는 바가 없네.$B$B우린 제임스를 겨우 구해 내긴 했지만 그 후로 그는 영 딴 사람이 되어 버렸어.$B$B심증이 가는 것이 여러 가지 있지만 이렇다 할 만한 증거가 없단 말이야. 우린 테라모어 주민들의 끊임없는 도움과 경비병들의 노력으로 이 끔찍한 범죄의 전말을 파헤쳐 내게 되기를 바라고 있다네.$B$B사건 조사를 돕고 싶다면 불모의 땅 경계로 가서 타', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1796, 'koKR', '저들이 보이는가? 그래, 안 보일 줄 알았네. 멀쩡한 두 눈으로도 보이지 않는 세계가 있지. 축복이자 저주야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1812, 'koKR', '키리스의 고통을 끝내 줬다고? 믿기 힘들군. 그런데 이제 트레보르가 악마와 그 졸개들에 대해 배우라고 널 여기로 보냈단 말인가?$B$B<로라무스가 웃습니다.>$B$B비전의 고통이 마침내 가셨다는 걸 다행으로 여겨라, $r.$b$b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1813, 'koKR', '파멸자 라젤리크는 대전쟁 당시 군주 카자크의 부관 중 가장 두려운 존재였지. 불타는 군단이 패하고 카자크가 타락의 흉터로 밀려났을 때 라젤리크는 카자크로부터 저주받은 땅을 확보하라는 임무를 받았네.$B$B얼라이언스와 호드가 저주받은 땅 밖의 영토를 놓고 사소한 싸움을 벌이고 있을 때, 라젤리크는 어둠의 의회를 결속시키고 흉포한 우레망치 오우거들을 모으고 있었네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1814, 'koKR', '비극적이게도, 악마의 군주와 그 부하들의 결속을 봉해버린 것은 스랄의 지혜였지. 여기에 트레보르의 군대가 악마의 군주와 어둠혈맹, 그리고 오우거들을 단결시키는 역할을 했어. 스랄은 지도자들에게 무한한 힘과 불멸의 습격 부대를 주겠다는 것을 미끼로 삼아 거래를 피로 봉했다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1815, 'koKR', '세바인, 알리스타즈, 그리고 그롤은 그들의 부하들처럼 땅에 묶일 수도 있단 사실을 깨닫지 못했고... 라젤리크는 그들에게 불멸을 선물한 대가로 구속시켜 영원히 봉사할 것을 명했네. 라젤리크의 잔인한 교활함이 다시 한번 승리를 거둔 셈이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1816, 'koKR', '이제 그들의 정신은 타락했어. 전보다 훨씬 더러워졌지... 오직 라젤리크만을 섬기기 위해서 사는 노예나 다름없지. 그들이 하나씩 지니고 있는 아뮬렛 조각이 악마의 군주를 소환할 열쇠라네. 그런데 기존의 방법으로는 그것들을 파괴할 수가 없다네. 자네에게는 정말로 이해가 가지 않을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1817, 'koKR', '그렇다면, 자네가 그 아뮬렛 조각 세 개에 부여된 악마의 보호막을 제거할 무기를 만들기 위한 길고 험난한 임무를 수행한다고 치세. 그다음에는 어쩔 셈인가? 파멸자의 은신처에서 그와 맞서기라도 할 텐가?$B$B<큰 소리로 비웃습니다.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1818, 'koKR', '인간들이 먼지진흙 습지대의 많은 부분을 점령했지만 돌망치 일족은 우리의 도움으로 그들을 몰아낼 수 있었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1819, 'koKR', '불모의 땅 변두리에 인간들이 그늘 쉼터라는 이름의 여관을 하나 지었지만 몇 주 전에 불타 버렸소.$B$B내가 왜 신경 쓰냔 말이오? 신경쓰지 않소. 인간들에 대해서는 신경도 쓰지 않는단 말이오. 그 여관에 심어놓은 첩자가 있소. 난 그의 죽음이 대답 없는 일로 묻히도록 두진 않을 것이오. 누가 이런 일을 했는지 알아야 하오$B$B도울 의사가 있다면 타고 남은 그늘 쉼터 여관으로 가 보고 뭔가 단서를 찾으면 내게 알려 주시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1820, 'koKR', '리테가 그늘 쉼터 여관의 화재와 무슨 관련이 있다면 그를 찾아서 심문해 봐야 할 거요.$B$B내가 오그론을 보내 그를 추적하도록 했는데 말이야. 그는 남동쪽으로 습지대를 가로지르는 주 도로쪽으로 갔으니 오그론과 만나 리테를 찾아보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1833, 'koKR', NULL, '당신 말은 듣고 싶지 않아요, $n. 안 돼요. 당신을 이글거리는 협곡으로 들여보내는 건 절대 안 돼요. 불가능해요. 있어서는 안 되는 일이라고요. 제가 얼마나 더 이야기해야 하죠? 들여보낼 수 없다고요! 공용어 할 줄 몰라요? 오크가 변장한 건가? 여기로 들어갈 수 없다고요! 절대 못 들어가요!$B$B당신을 들여보내면 다른 사람들도 다 들여보내야 한단 말이에요. 그러면 또 당신의 친한 친구들도 들어가고 싶어할 테고, 또 그 친구들의 먼 친척, 그리고', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1834, 'koKR', NULL, '그곳에 어떤 괴물이 사는지 알기나 하십니까? 최악의 경우에는 우리가 당신의 유해를 삽으로 퍼서 회수해내는 일이 생긴다고요. 벌써 그 끔찍한 괴물들에게 우리 착하디 착한 드워프 친구들을 얼마나 잃었는지 모릅니다.$B$B내 대답은 \"절대 안 된다\"예요. 이글거리는 협곡에 그렇게 들어가고 싶거든 다른 길을 찾아보도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1835, 'koKR', NULL, '이 얘기도 하면 안 되는 건데, 황야의 땅에 있는 짐승과 괴물을 모조리 물리칠 수만 있다면 이글거리는 협곡에 갈 수 있습니다.$B$B맞아요! 황야의 땅 말입니다. 카르가스 근처에 오크들이 닦아놓은 뒷길 같은 게 있어요. 우리가 상대하는 적이 얼마나 바보인지 아시겠죠! 지옥으로 들어가는 뒷문이라니? 도대체 생각이란 게 있는 족속들인지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1836, 'koKR', NULL, '무적이라고요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1837, 'koKR', NULL, '정말 어리석군요. 내 경고를 무시하지 마십시오. 이 세상에 완벽한 자는 아무도 없답니다. 제 조언을 조금이라도 새겨 듣는 것이 신상에 좋을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1838, 'koKR', NULL, '한 가지만 더 말씀드리겠습니다. 자신을 영웅이라고 생각하는 것 같은데, 그렇다면 황야의 땅을 지나 그렇게 소원하는 이글거리는 협곡으로 들어가십시오. 단, 당신의 용맹함을 입증할 증거를 가지고 오도록 하세요. 그러면 생각해보고 당신에게 열쇠를 드릴 수도 있죠.$B$B이글거리는 협곡의 남동쪽 구석에 나만큼이나 힘센 여자가 있어요. 난폭한 마르골이라고 하는데, 가서 한번 만나 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1839, 'koKR', NULL, '아아... 그래, 그래. 그럼 계속 가게. 죽으러 계속 가 보라고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1853, 'koKR', '여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다.', '여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1874, 'koKR', '자신의 길을 당당히 가고 있군, $n. 하지만 자네는 아직도 배울 게 많다네. 불모의 땅 남부에서 다음 훈련을 받을 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1875, 'koKR', '이 광활한 대지를 불모의 땅이라고 부르긴 하지만, 대지의 참모습을 볼 줄 아는 이에게는 생명으로 가득 찬 곳이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1914, 'koKR', '나는 이 지역에서 최고급 원단의 천과 가죽 옷을 팔고 있소이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1916, 'koKR', NULL, '$n, 당신은 다른 이들에 비해 많이 배운 편이랍니다. 이 세계의 모든 원소들을 존중하세요. 그러면 당신의 눈은 더욱 위대한 것을 볼 수 있게 될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1918, 'koKR', '이 제단은 마치 살아있는 듯, 당신에게 손짓을 하는 느낌이 듭니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1920, 'koKR', '엘룬이시여, 감사합니다! 누가 저를 찾아온 게 얼마 만인지 모르겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1921, 'koKR', '어둠해안의 젊은 나이트 엘프였던 시절, 저는 황혼의 망치단이라는 불미스러운 작자들과 만나게 되었습니다. 그들과 어떻게 어울리다 보니 친해졌고, 젊은 혈기에 부끄럽게도 엘룬에 대한 신앙을 저버리고 황혼의 망치단을 따르게 되었지요.$B$B꿈속에서 엘룬 여신님의 환영을 만나고서야 스스로 그릇된 길을 가고 있음을 깨달았습니다. 그 이후, 저는 고대 신을 섬기는 자로 다시 태어났습니다.$B$B그리고 회개의 뜻으로 엘룬께 올리는 기도문을 만들기 시작했습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1922, 'koKR', '저는 순금 서판에다 양심의 가책, 부끄러움, 후회, 그리고 슬픔을 새겼습니다. 그런데 그 서판을 발견한 황혼의 망치단은 제게 신성 모독자라는 낙인을 찍었습니다. 엘룬께 올리는 기도문을 완성하지도 못한 채 그 자리에서 처형되고 만 것이지요. 이제는 영혼이 이 세계에 구속되어 황천으로 갈 수도 없게 되었습니다. 황혼의 망치단을 배신하는 자들에 대한 경고로 이 우리에 갇히게 되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1923, 'koKR', '고대의 학카르 제단이 방 입구 가까이 놓여 있습니다.$B$B제단 위를 살펴보니 커다란 뱀 모양의 석상이 놓여 있고 그 모양은 제단 위에 있는 모양과 굉장히 흡사합니다. 그 둘에는 뭔가 관련이 있는 듯해 보입니다.', '고대의 학카르 제단이 방 입구 가까이 놓여 있습니다.$B$B제단 위를 살펴보니 커다란 뱀 모양의 석상이 놓여 있고 그 모양은 제단 위에 있는 모양과 굉장히 흡사합니다. 그 둘에는 뭔가 관련이 있는 듯해 보입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1924, 'koKR', '이 지역에는 나이트 엘프의 동맹족으로 보이는 많은 생물들이 살고 있네. 엘프는 이 생물들의 내면에 숨겨진 힘을 이용해 왔는데 이제는 호드도 이를 실현할 때일세. 나는 이 힘을 모아 우리 동족에게 유리하게 사용하는 방법을 알아냈네.$B$B내 말을 의심하지 말게, $n. 날 도와주면 내 말이 사실이라는 것을 알게 될 것일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1933, 'koKR', '재봉술을 익힌 친구인가? 이 비즈클릭이 당신에게 필요한 물건을 거의 다 가지고 있을걸. 한번 훑어보고 사고 싶은 게 있거든 말만 하라고, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1934, 'koKR', '짐을 챙기시오, $n! 이글거리는 협곡에 있는 닐리스 로크라브에게서 방금 전갈이 왔는데 암거래상단이 용광로 중심에 사업 본부를 세웠다고 하오. 이글거리는 협곡에서 닐리스 로크라브를 찾아 자세히 알아보시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1935, 'koKR', '방 안에 한 줄기 밝은 빛이 나타나더니 곧 사라집니다. 또 다른 빛 줄기가 나타났다 사라지기를 반복합니다.$B$B어떤 순서를 보여주고 있는 듯합니다.', '방 안에 한 줄기 밝은 빛이 나타나더니 곧 사라집니다. 또 다른 빛 줄기가 나타났다 사라지기를 반복합니다.$B$B어떤 순서를 보여주고 있는 듯합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1953, 'koKR', '반드시 복수하고 말겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1954, 'koKR', '우리 아버지께서 용광로에 사는 그 쓰레기 같은 것들에게 살해되셨소. 스톰윈드의 집정관들에게 도와 달라고 간청했지만 들은 척도 않더군. 자기네들의 귀한 군대를 보내려고 하지 않는 것 같았소. 아니, 아예 그런 곳이 존재한다는 사실 자체를 무시하고 싶어 했지.$B$B그래서 이토록 복수를 원하는 거요, $n. 아주 간단한 이유지. 세상에 이보다 더 확고한 이유가 있겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1955, 'koKR', '보다시피 난 덩치만 좋고 실력은 부족한 수습기사일 뿐이오. 라그나로스가 지배하는 검은무쇠 드워프와 그 야수들을 나 혼자 무찌른다는 것은 말도 안 되는 일이지. 하지만 당신처럼 용감하고 야심 찬 분이라면 용광로의 적을 문제없이 처치할 수 있을 거라는 확신이 드는군. 날 도와주면 꿈에서도 얻지 못할 부와 명예를 얻게 해주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1973, 'koKR', '$r|1이여;여;, 진심으로 환영합니다. 동굴에 숨어 사는 저 같은 이와 대화하려고 잘 알지도 못하는 길을 찾아서 왔군요. 갑작스럽긴 하지만 예측하지 못한 방문은 아닙니다. 분명 그럴만한 이유가 있을 테지요. 안 그렇습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1994, 'koKR', '안녕하십니까. 저는 대마법사 실렘님의 수습마법사인 니릴이라고 합니다. 문제가 있으면 주저하지 말고 저희 주인님께 말씀 드리도록 하시기 바랍니다.$B$B저는 여기 있다가 당신이 산 밑으로 내려갈 준비가 되면 보내드리도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1995, 'koKR', '당신이 누군지 압니다, $n 님. 운명과 그 너머의 힘이 어떤 이유 때문에 당신을 저에게 인도한 것이지요. 그 목적에 제가 연관되어 있다는 것이 그다지 기쁘지는 않습니다. 당신은 앞으로 많은 결정을 하게 될 것입니다. 당신이 옳은 결정을 내릴 만큼 현명하다면 좋겠군요.$B$B제 말을 믿으십시오, $R|1이여;여;. 진정 옳은 결정이란 존재하는 법입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1996, 'koKR', '당신은 호기심이 아주 강하군요. 보통 그런 호기심은 이해력의 부족에서 오는 것이긴 하지만 말입니다. 이곳에 오는 데 뚜렷한 목적이 있었다면 그런 질문은 애당초 하지 않았을 테지요.$B$B당신의 갈 길이나 가보도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1997, 'koKR', '당신도 알고 있지 않습니까. 제가 알고 있다는 걸... 지금 저는 쓸데없는 말을 하고 싶지 않으니 당신도 그렇게 하는 게 좋을 것입니다.$B$B당신이 여기 온 이유는 분명 아탈라이의 가라앉은 사원에서 얻은 그 물건이겠지요. 그게 어떤 이유로 당신을 여기로 이끌었는지 궁금하겠지요. 그건 바로 저의 동지이자... 형제에게 안식을 주기 위해서입니다. 그는 에메랄드의 꿈속에서... 악몽에... 갇혀 혼자서는 빠져나올 수 없으니 말이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1998, 'koKR', '아탈라이 트롤들이 불러낸 신 때문입니다. 저희는 그 신의 육체를 파괴하고 신전을 가라앉혔지만, 그는 예상보다 훨씬 강했지요. 타락의 씨앗이 깊이 파고들어 그곳을 지나가는 모든 것을 뒤틀리게 했으니까요.$B$B에라니쿠스는 그 가라앉은 신전을 감시하며 아탈라이 부족과 그들의 신이 다시 일어나지 못하게 하는 임무를 맡았습니다. 그런데 자신도 모르는 사이 타락의 피해자가 된 것이지요. 그리고 저희도 마찬가지로, 피해를 입게 되었습니다. 타락의 힘을 과소평가한', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1999, 'koKR', '당신이 여기 왔다는 것이 첫 번째 발을 내디딘 것입니다... 말하자면, 이세라용군단을 돕는다는 것은 옳은 결정이라는 뜻이지요.$B$B당신은 순전히 개인적인 욕심 때문에 이곳에 왔을 수도 있고, 도덕적 의무감에서 온 것일 수도 있습니다. 이유 자체는 중요하지 않습니다. 지금의 결과를 낳았다는 것이 중요하지요. 에라니쿠스가 받는 고통 때문에 나도 에메랄드의 꿈에서 깨어나게 되었습니다. 이제 그의 고통을 끝내는 것이 제 임무입니다. 그리고 이것을 당신이 도와', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2013, 'koKR', '재밌군, 아주 재미있어... 내가 통곡의 동굴 위 언덕 꼭대기에 사는 드루이드를 하나 알고 있네. 그녀라면 자네가 찾은 이 조각에 대해 더 자세히 말해줄 수 있을 거야.$B$B자, 그럼 난 계속 일이나 해야겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2033, 'koKR', '이곳 아즈샤라에서 보낸 날들이 그렇게 영광스럽고 좋았던 것만은 아니지만, 우린 아직 젊고 몸속에는 아직도 뜨거운 피가 흐르고 있소. 그러니 우리는 꼭 승리할 수 있을 거요. 승리는 시간문제일 뿐이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2034, 'koKR', '벨그롬이 이 어리석은 동맹을 유지할 수 있도록 도와달라며 오그리마에 있는 우리를 이곳으로 보냈소. 하지만 그의 도박이 성공한다면 모든 호드에게 득이 될 거요.$B$B여자들을 즐겁게 해주려는 그의 욕심 때문에 이미 많은 오크들이 죽었지만, 그는 여전히 우리의 지휘관이고, 우린 명예 때문에 주어진 상황에서 최선을 다하는 수밖에 없는 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2035, 'koKR', NULL, '내가 여기 있는 건 명예 때문이 아니에요. 한 오크의 자존심 때문이죠.$B$B내가 벨그롬의 제안을 거절하지 않았던들 아직도 오그리마에 남아 진짜 일을 하고 있었을 거예요.$B$B여성에 대한 벨그롬의 탐욕을 듀로타의 많은 여전사들도 모르는 게 아니지만 여전히 벨그롬의 탐욕스러운 태도는 사라지질 않고 있어요.$B$B그 녀석 내게 치근덕거리는 걸 일찌감치 그만두길 잘했죠. 안 그랬으면 손가락이 날아가는 것으로 끝나지 않았을 테니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2036, 'koKR', NULL, '안녕하세요. 오그리마에서 우리를 도우러 오셨군요. 다행입니다. 아, 이 끔찍한 숲에서 빨리 벗어나고 싶어요. 하루라도 빨리 오그리마에 가서 맛 좋은 맥주나 마시면서 지내고 싶거든요.$B$B벨그롬에게 무슨 얘기를 들었기에 당신이 이곳까지 왔는지 궁금하군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2037, 'koKR', '$n, 세나리온 의회에는 무슨 일인가요?', '$n, 세나리온 의회에는 무슨 일인가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2038, 'koKR', '아, 내가 외딴 곳에 있다는 건 나도 알고 있소. 알고 있다니까!$B$B사실 내 집은 톱니항에 있는데 비행선이 이곳에 불시착해버린 거요. 여기 떨어진 김에 눌러앉아 그동안 해보고 싶던 연구나 해 볼까 하오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2039, 'koKR', '시체 위에 홀연히 천둥매의 영혼이 나타납니다. 희미한 두 눈이 당신 너머의 뭔가를 응시하듯이 당신을 꿰뚫어 봅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2053, 'koKR', NULL, '$n, 페랄라스에는 많은 일이 있었답니다. 대지와 나무, 생물이... 모두 페랄라스의 현재와 미래를 바꿔놓고 있습니다.$B$B하지만 저 위의 쌍둥이 바위산 만큼은 언제나 한결같지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2054, 'koKR', '쌍둥이 바위산의 멋진 자연 경관을 구경하셨나요? 무사히 아래로 내려갈 수 있도록 필요한 분께 낙하산을 팔고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2055, 'koKR', '그러고 보니 어제 오후 뭔가 이상한 걸 본 것 같소.$B$B어제 여기서 남동쪽에 있는 고대 트롤 유적지를 달려가고 있었는데... 뭐, 달렸다기보다 팔짝거렸다고 해야 하나... 모래가 워낙 뜨거워서 말이오!$B$B어쨌든 유적지를 지나 뛰어가고 있었는데 그곳에 야영지가 하나 있었소이다. 야영을 하기에는 좀 이상한 장소였지... 그 미친 독수리 하나만 없었어도 좀 더 살펴볼 수 있었는데 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2080, 'koKR', '텔드랏실의 창조는 위대한 업적이었지만, 이제 세계는 균형을 되찾기 위해 다시 움직여야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2113, 'koKR', '구해주셔서 감사합니다!$B$B저는 스톰윈드에서 온 요리사 겸 연금술사예요. 앵거스 삼촌에게 갖다 드리려고 이 지방에서 나는 약초와 조리법을 찾다가 이 가시멧돼지들에게 붙잡혔답니다. 당신이 오지 않았다면 분명 녀석들의 스튜 냄비 속에서 끝장났을 거예요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2114, 'koKR', '네. 쓸만한 조리법이 하나 있긴 합니다. 가르쳐드리지요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2115, 'koKR', '네, 희귀한 연금술을 하나 압니다. 제가 가르쳐드리죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2133, 'koKR', '어서 오게나! 고블린 기계공학 설계도는 허가 받은 고블린 기술자만이 이용할 수 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2134, 'koKR', '어서 오세요! 노움 기계공학 설계도를 이용하려고 오셨다면, 잘 오신 겁니다. 우리 측정기 결과로는 당신이 인증된 노움 기술자시니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2135, 'koKR', '안녕하세요. 나는 오글소프라고 하는데 당신이 가지고 있을지도 모르는 멋진 노움 기계 장치를 내가 만들었습니다! 장치가 폭발했어도 제 잘못이 아닙니다. 혹시 장치 덕분에 돈을 많이 벌었다면 사용료에 대해 얘기 좀 해야겠군요!$B$B아, 만약 당신이 놈리건에서 온 거라면 90도씩 두 번 돌아 그 장치를 부숴버리고 가세요. 당신한테 더 할 말 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2136, 'koKR', '아이고, 저의 은인이 아니신가요! 또 만나서 반가와요. 지금까지 저와 제 발명 작업을 도와준 데 대해 뭐라고 감사해야 할지 모르겠네요.$B$B뭐 도와드릴 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2137, 'koKR', '나는 수석땜장이 오버스파크라고 하오. 현대 노움 기계공학 원리를 설계한 중심 인물이라고 할 수 있지. 내 임무는 노움의 만능 스패너를 이용해 발명의 역사에 길이 남을 눈부신 기계를 만드는 거요.$B$B혹시 쓸만한 방사선 제거용 설계도를 찾게 되거든 우리에게 가져와 주시오. 요새 그게 필요하거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2138, 'koKR', '알기 쉽게 수학적으로 가르쳐드리지. 고블린 + 기계공학 = 전문 지식이란 말이오, 젊은 친구. 그걸 부인하는 자는 덧셈도 할 줄 모르는 거라고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2139, 'koKR', '나름대로 조사를 해보니, 자네가 학카르의 화신을 물리친 것이 그를 약하게 만든 모양이오. 하지만 머나 먼 뒤틀린 황천 구석에는 그의 힘이 아직도 많이 남아있소.$B$B당신은 이미 학카르의 화신을 한번 쓰러뜨렸소. 한 번 더 그를 쓰러뜨린다면 그의 힘이 더욱 약해져 언젠가는 화신이 아니라, 그 진짜 모습을 드러낼지 모르오.$B$B죽은 신의 성소에서 학카르의 화신을 다시 소환할 수 있는 마법을 내가 준비해놓았소. 한 번 더 싸워보겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2140, 'koKR', '안녕하시오. 술로 세월을 보내다보니 감각은 둔해졌지만 아직도 내면의 눈은 밝다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2153, 'koKR', '안녕하시오, $n. 나는 여기서 어린 히포그리프들을 조련하며 돌보고 있소. 마음 편히 둘러보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2154, 'koKR', '드루이드는 이 세계에서 곤경에 처한 생명체가 있으면 금방 알아차린다오. 히포그리프들이 위기에 처했다는 것을 알고 페랄라스의 타락으로부터 보호하기 위한 대책을 마련했소.$B$B커글 크랭크홉이라는 노움이 그 일을 주도하고 있는데, 그녀가 알을 모아서 이곳으로 보내면 내가 알을 돌본다오.$B$B우리는 이 소명을 위해 도움은 언제라도 환영이오, $n. 가젯잔으로 가서 커글을 한번 찾아보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2155, 'koKR', '고맙소, 작은 $r 친구!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2173, 'koKR', '아직은 요리 솜씨가 좀 부족하군요. 손에 물 좀 더 묻히고 오셔야 제가 아는 요리법을 가르쳐드릴 수 있겠네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2174, 'koKR', '저한테 배우기에는 당신의 연금술은 아직 좀 부족합니다. 혹시 나중에 다시 오시면...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2175, 'koKR', '정신이 나약한 자들이나 비전 마법에 압도되어 타락하는 거랍니다. 당신이 흑마법사의 길을 가지는 않을지라도 항상 이것을 기억하도록 하세요.', '정신이 나약한 자들이나 비전 마법에 압도되어 타락하는 거랍니다. 당신이 흑마법사의 길을 가지는 않을지라도 항상 이것을 기억하도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2193, 'koKR', '나약한 자들이나 마법으로 타락하게 되지. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련이라오.', '나약한 자들이나 마법으로 타락하게 되지. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련이라오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2213, 'koKR', '전, 이 저주받은 세상에 영원히 매인 몸이랍니다. 필멸의 존재여, 무엇을 원하시나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2234, 'koKR', NULL, '어서 오세요, $n. 아이언포지의 역사에 대해 배우러 오셨습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2235, 'koKR', NULL, '자세한 얘기를 들을 준비가 되면 알려 주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2236, 'koKR', NULL, '수백 년 전, 타우릿산의 위대한 도시는 초목이 무성했지만 이젠 황폐해져 먼 옛날의 당당한 위용을 흔적처럼 안고 불타는 평원에 서 있답니다.$B$B타우릿산은 검은무쇠 드워프들의 수도였고, 당시 전체적으로 내란이 벌어지던 중이었어요.$B$B그 지역은 한때 붉은마루 산맥의 일부였는데 거대한 폭발이 일어나 도시는 폐허가 되어 버리고 그 일대는 재로 가득한 황무지가 되어 버렸답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2237, 'koKR', NULL, '그건 모릅니다.$B$B하지만 살아남은 검은무쇠 드워프들은 산으로 올라가 그들의 도시를 재건하기 시작했습니다.$B$B타우릿산의 잿더미 위에 검은바위 첨탑이 세워지고 새로운 검은무쇠 제국이 탄생한 것이죠. 이글거리는 협곡 내에서 용광로라는 곳의 방비를 더욱 강화했답니다.$B$B그런데 그때부터 검은무쇠 제국을 지배한 고대 악령에 대한 이야기가 나돌기 시작했어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2238, 'koKR', NULL, '최근, 검은무쇠 드워프들을 목격하는 사례가 늘어나고 있어요. 황야의 땅 곳곳에 요새를 세우고, 고대 지식을 구하기 위해 울다만 깊숙한 곳으로 대규모 탐색 부대를 보내고 있답니다. 심지어는 우리 본국에까지 침입해 모단 호수 근처 댐을 공격하기도 했답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2239, 'koKR', NULL, '우리는 도움이 절실히 필요합니다. 당신이 도와주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2253, 'koKR', '어? 음... 안녕하세요! 돈을 받으러 왔거나 뭔가를 소환하러 온 거라면 잘못 찾아오셨어요. 죄송하게 됐네요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2273, 'koKR', NULL, '제 목걸이를 호수에 빠뜨린 거 같아요. 아빠가 주신 건데 이걸 아시면 무지 화내실 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2274, 'koKR', NULL, '목걸이를 찾아 주셔서 고맙습니다! 와! 정말 최고예요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2275, 'koKR', '밖에 있는 그런트들뿐만 아니라 내 형제들과 나도 하이잘 산 전투에 참가했었습니다. 은행에서 돈을 훔치려는 자들은 먼저 우리를 쓰러뜨려야 할 겁니다.', '밖에 있는 그런트들뿐만 아니라 내 형제들과 나도 하이잘 산 전투에 참가했었습니다. 은행에서 돈을 훔치려는 자들은 먼저 우리를 쓰러뜨려야 할 겁니다.', '이 은행의 안전은 제 목숨을 걸고 보장하겠습니다. 그 정도면 믿고 물건을 맡기시겠습니까?', '이 은행의 안전은 제 목숨을 걸고 보장하겠습니다. 그 정도면 믿고 물건을 맡기시겠습니까?', '하찮은 고블린 녀석들에게 당신의 소중한 물건을 맡기시겠습니까? 용맹스런 오그리마 그런트들이 수호하는 저희 은행을 이용해주십시오.', '하찮은 고블린 녀석들에게 당신의 소중한 물건을 맡기시겠습니까? 용맹스런 오그리마 그런트들이 수호하는 저희 은행을 이용해주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2276, 'koKR', '안녕하세요... 잠깐만 시간을 내셔서 저희를 좀 도와주시지 않으시겠어요? 제발...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2277, 'koKR', '니다를 도와주셔서 감사해요. 저도 나중에 커서 $n 님 같은 $C|1이;가; 되고 싶어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2278, 'koKR', '오랜 세월 전투와 노예 생활에 지쳤는데, 다시 고향이란 걸 갖게 되니 기분이 좋군요.', '오랜 세월 전투와 노예 생활에 지쳤는데, 다시 고향이란 걸 갖게 되니 기분이 좋군요.', '필요한 게 있거든 빨리 말씀하십시오.', '필요한 게 있거든 빨리 말씀하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2279, 'koKR', '이 몸은 주인님을 섬기기 위해 살 뿐입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2280, 'koKR', '평화롭다 해도 전쟁은 있게 마련이오. 아직도 여러 부족이 대족장님의 깃발 아래서 싸우고 있소이다. 당신의 부족도 오그리마를 위한 전투에 가담할 생각이오?', '평화롭다 해도 전쟁은 있게 마련이오. 아직도 여러 부족이 대족장님의 깃발 아래서 싸우고 있소이다. 당신의 부족도 오그리마를 위한 전투에 가담할 생각이오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2282, 'koKR', '안녕하시오, $n! 나는 선임기술자 스쿠티라고 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2284, 'koKR', '대지는 많은 비밀을 간직하고 있다네. 아제로스의 모든 종족들을 위해 비밀로 남아야만 할 것들을 지키는 것은 우리의 임무지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2285, 'koKR', '그대가 여기서 나의 시간을 뺏는다면 세나리온 의회 전체의 시간을 빼앗는 것과 같아. 무슨 일로 왔는지는 모르겠네만, 그대가 귀중한 시간을 축낼 만큼 어리석지 않다는 희망을 주게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2286, 'koKR', '스톰윈드 장교들이 대부분의 병력을 외부로 파견했다니 믿을 수가 없습니다. 지금 고향 땅의 전선이 이처럼 위험한데 말입니다.$B$B서부 몰락지대에서 도적떼가 몰려오고 동쪽, 서쪽에서 놀의 무리가 침입해 오고 있습니다. 그런데도 스톰윈드가 아직 포위되지 않았다는 게 놀라울 정도입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2287, 'koKR', '안녕하십니까, $C님. 부디 우리 병력에 힘을 보태 주기 위해 오셨기를 바랍니다. 사랑하는 고향 땅 엘윈에 짐승과 도적들이 쏟아져 들어오고 있습니다. 그런데 우리는 길가를 안전하게 지켜 줄 병력조차 모자랄 지경입니다!$B$B그리고 들창코 녀석에 대한 수배령을 보지 못했다면 가서 읽어 보시기 바랍니다. 들창코는 저쪽 숲에 사는 짐승인데 꼭 처리해야 할 녀석입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2288, 'koKR', '안녕하시오, $n. 텔사마에 온 걸 환영하오. 여기 머무르는 동안 꼭 이곳 양조장에 들러 보시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2289, 'koKR', '텔사마에 온 것을 환영합니다! 모단 호수에서 집처럼 편히 지낼 수 있는 유일한 곳이지요.$B$B텔사마는 좋은 곳이지만 임무를 수행하고자 부름을 받은 자에게 항상 좋은 것만 있는 건 아니랍니다! 얼라이언스의 이름으로 목숨을 걸 생각이 있다면 탐험가 연맹 텔사마 지부 건물의 바깥에 있는 전단을 읽어 보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2293, 'koKR', NULL, '$c|1이여;여;, 마침 잘 오셨어요! 그리 보기 좋은 광경은 아니죠?$B$B지평선 정찰함은 바다 밑바닥으로 가라앉아 버렸고, 살아남은 선원들은 모두 녹초가 돼버렸어요. 거기다 승객들의 짐과 화물의 잔해가 잔뜩 널려 있으니 꼭 축제가 끝난 뒤 너저분한 스톰윈드의 운하를 바라보는 듯한 기분이 들 거예요.$B$B게다가 위험천만한 일이 또 남아 있으니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2313, 'koKR', '모두 다 음모야. 내가 하는 일이 어떤 것인지 제대로 파악할 재량도 없으면서 날 어둠 속에 가둬 놓으려는 자들이 있단 말이오!$B$B아! 거기 흙 밟지 않게 조심하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2314, 'koKR', '뭘 하는 거냐고? 안 보인단 말이오? 나는 공상가올시다. 우리 모두에게 훨씬 더 나은 미래가 올 것을 꿈꾸고 있지. 그래요. 나는 분명 공상가요.$B$B하지만 세상은 늘 진부함을 강요하지. 대드루이드 스태그헬름께 내가 공상가라는 걸 말씀드렸더니 하시는 말씀이 \"세상에는 땅을 파는 자들도 필요할 게 아닌가?\"라고 하시더군.$B$B우리의 발목을 매고 있는 진부함의 족쇄가 완전히 풀려날 때까지 나는 세나리온 의회를 도와 이 흙더미나 옮기고 있을 참이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2315, 'koKR', '안녕하시오, $r 친구. 나는 프랑클론 포지라이트라고 하오. 검은바위 첨탑과 검은무쇠 부족에 대해 배우고 싶어 온 거요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2316, 'koKR', '내게는 선택의 여지가 없었소. 아니, 적어도 그렇게 생각했었지. 타우릿산이 파괴되는 것을 참고 견디며 우리 국왕 폐하와 그의 백성의 곁을 지키려고 했었소.$B$B라그나로스의 지배를 받은 제왕 다그란 타우릿산은 이 산의 중심부를 뜯어내 버리고 검은바위 첨탑을 세웠소. 우리는 과거 또는... 미래의 그 어느 도시나 요새보다도 강한 드워프 도시를 짓기 위해 쉬지 않고 일했소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2317, 'koKR', '나는 곁에서 라그나로스의 타락이 검은무쇠 제국의 가슴과 정신에 스며드는 것을 지켜보았소. 한때는 명예로웠던 검은무쇠 부족은 이제 광기와... 악으로 치달아 버리고 만 거요.$B$B검은바위 첨탑 건설이 끝나자 나는 내 종족과 함께 더 이상 살고 싶은 생각이 없어졌지. 나는 새로운 검은무쇠 제국에서 영웅으로 떠올랐고 사람들은 내가 계획하고 건설한 도시의 입구인 이곳에 무덤을 지어 내 노고를 칭송한 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2318, 'koKR', '내 훌륭한 망치, 무쇠지옥은 파이너스 다크바이어라는 새로운 수석 건축가에게 전해 받았지. 파이너스는 비열한 마음을 품고 있을 뿐 아니라 재능이라곤 거의 없는 녀석이지.$B$B바로 여기서 당신이 날 도와 주는 거요. 녀석을 제지해야 하오. 녀석은 너무 서툴러서 무쇠지옥의 진정한 힘을 이용하지 못하지만, 만약 무쇠지옥의 잠재력을 최대한으로 끌어낼 수 있을 만한 재능을 가진 자가 나타난다면 검은무쇠 부족이 만들어 낸 물건들로 인해 이 세계에 재앙이 닥쳐오게', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2319, 'koKR', '파이너스 다크바이어는 법의 심판장 너머, 제작의 전당에 있다. 그 비열한 놈을 죽이고 아이언펠을 되찾아라.$B$B아이언펠을 타우릿산의 제단으로 가져가, 마땅히 있어야 할 곳에 놓아라. 바로 나를 기려 세운 동상의 손에 말이다.$B$B그러면 내가 만능 열쇠를 숨겨 둔 칸이 열릴 것이다. 더 중요한 건, 아이언펠이 영원히 내 손에 남는다는 거지. 누군가 망치를 빼내려 한다면 동상과 망치가 함께 산산조각 나 영원히 사라질 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2320, 'koKR', '그렇다네. 자네가 약초채집 기술이 있다면 더 큰 보람을 얻을 수 있을 걸세. 귀한 씨앗을 기르고 재배하는 일은 도끼나 휘두르고 지나가는 그림자에 대고 손짓 발짓하는 일과는 다르거든. 늘푸른 주머니만 있으면 아무리 둔한 자라도 뭔가 길러낼 수 있긴 하지만, 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2333, 'koKR', '잘 들어 두시오. 난 지금 당신 농담이나 들어줄 기분이 아니오. 대드루이드님의 연구가 계획대로 진행되도록 하는 것이 내 임무요. 내 명령은 나의 사랑하는 세나리온 의회를 위해 땀 한 방울 흘릴 생각조차 없는 녀석들을 모조리 뽑아내 버리는 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2353, 'koKR', NULL, '안녕하세요, 고귀한 $c|1이여;여;. 세나리온 의회의 이 미천한 종이 당신의 종족 $R|1을;를; 위해 축복을 빕니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2354, 'koKR', '서투른 호기로 함부로 까불지 말게. 여차하면 변이 마법을 걸어 버릴 테니까 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2355, 'koKR', '저는 파이가 세상에서 제일 좋아요.', '저는 파이가 세상에서 제일 좋아요.', '이 세상에 집에서 갓 구운, 따뜻하고 바삭바삭한 체리 파이만큼 맛있는 게 또 있을까요?!', '이 세상에 집에서 갓 구운, 따뜻하고 바삭바삭한 체리 파이만큼 맛있는 게 또 있을까요?!', '파이 맛이 정말 죽인답니다. 한입 드셔 보시겠어요?', '파이 맛이 정말 죽인답니다. 한입 드셔 보시겠어요?', '기분이 별로 안 좋으세요? 체리 파이 좀 들어보세요. 금방 기분이 좋아질 거예요.', '기분이 별로 안 좋으세요? 체리 파이 좀 들어보세요. 금방 기분이 좋아질 거예요.', '체리 파이는 너무 맛있어서 노움 둘이 먹다가 하나가 죽어도 모를 정도랍니다.', '체리 파이는 너무 맛있어서 노움 둘이 먹다가 하나가 죽어도 모를 정도랍니다.', '체리 파이 좀 드셔 보세요. 입이 귀 밑까지가 아니라 15km 정도 좍 찢어질 겁니다.', '체리 파이 좀 드셔 보세요. 입이 귀 밑까지가 아니라 15km 정도 좍 찢어질 겁니다.', '신선한 체리 파이 팔아요. 한입 먹으면 너무 맛있어서 눈물이 다 고일 겁니다.', '신선한 체리 파이 팔아요. 한입 먹으면 너무 맛있어서 눈물이 다 고일 겁니다.', '체리 파이는 아제로스에서 제가 가장 좋아하는 음식이랍니다.', '체리 파이는 아제로스에서 제가 가장 좋아하는 음식이랍니다.'),
(2368, 'koKR', '모자케 야영지에 온 걸 환영하네, 용감한 $c여. 오늘은 무엇을 도와줄까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2393, 'koKR', '쩝, 내 앞을 가릴 나뭇가지만 있어도 경비병들이 절대 날 보지 못할 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2394, 'koKR', '내부에서 첩보로봇이 아주 세심한 주의를 요하는 작업을 하고 있는 중이니까 조금만 참고 기다리라고. 곧 끝날 테니까 말이야.$B$B아, 그리고 한가지 부탁이 있는데, 라스코발 녀석에게 들키지 않도록 하시오... 우린 곧 그를 습격하려고 하니까 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2414, 'koKR', '요즘은 무척 힘든 시기랍니다, 안 그렇습니까? 어디를 가도 도움을 필요로 하는 이가 꼭 있다니 말입니다. 저와 제 집사람도 예외는 아니죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'koKR', '무슨 일로 오셨나요?', '무슨 일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2434, 'koKR', '물론이지. 당신은 신뢰할 수 있는 사람 같으니... 신뢰말이야! 그거야 금방 알아볼 수 있지.$B$B그건 그렇고, 하던 얘기를 계속합시다. 앞날의 비약을 만들려면 에보뿌리 식물 하나가 있어야 하오. 나머지 재료는 정말 흔한 것들이지만, 그게, 에보뿌리는 구하기가 좀 까다롭소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2473, 'koKR', '죽이려면 어서 죽여, 이 망나니 같은 $r|1아;야;.$B$B<고개를 숙이며 짧은 목을 드러내는 카란>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2474, 'koKR', '가망이 없어...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2475, 'koKR', '날 바보로 아는 거요? 내가 공주를 죽이는 거나 마찬가지라고! 내가 왜 당신을 믿어야 하지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2476, 'koKR', '<한숨을 쉬는 카란>$B$B그... 그건 맞는 말인 것 같군.$B$B고르샤크가 말하기를 당신네 대족장이 어떤 큰 계획을 세우고 있다고 하더군. 얼라이언스와 호드 간의 관계를 바꿔 놓을 그런 계획 말이오. 혹시 당신은 알고 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2477, 'koKR', '그러면 잘 들어 두시오.$B$B몇 달 전에 호숫골의 집정관이 아이언포지로 사절을 보내 붉은마루 산맥과 불타는 평원에서 검은바위 부족이 침입하고 있으니 도와 달라고 국왕께 요청을 했소이다.$B$B모이라 공주는 내 반대에도 불구하고 그들을 도와주는 일을 자청했소. 나는 모단 호수에서 호숫골로 가는 위험한 여정에 공주를 보호하도록 정예 경비병 스무 명을 배치 받았소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2478, 'koKR', '<목을 가다듬는 카란>$B$B우린 이글거리는 협곡의 지하도를 지나 파괴된 황무지로 들어섰었소. 지금 생각해 보면 소름이 돋을 정도로 조용했소이다. 지나가는 길에 부닥친 것이라고는 그 지역의 야생동물들뿐이었고 내 부하들이 손쉽게 해치웠지.$B$B우리는 그나마 쉽게 검은바위 산에 이르러 아무런 일도 없이 돌다지 건물들을 지나갔소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2479, 'koKR', '불타는 평원을 지나갈 때 습격을 받았소. 족히 백 명은 되어 보이는 검은무쇠 드워프들이 달려든 거요! 불타는 평원의 바위, 벽 가릴 것 없이 온갖 틈과 구석에서 기어 나왔소. 우리에게 몰려들어 경비병들은 물론 이번 임무에 우리를 도와 주기로 했던 몇몇 용감한 영웅들도 제압해 버렸소.$B$B단 한 가지 확실했던 건 아주 철저히 준비된 습격이었단 사실이오. 마치 우리가 움직이기도 전에 녀석들이 우리의 행동을 다 꿰뚫어보고 있기라도 한 것처럼...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2480, 'koKR', '아니면 어떻게 그런 일이 있을 수 있었겠소? 누군가가 검은무쇠 녀석들에게 정보를 흘린 게 분명하오.$B$B<주먹을 흔들어 보이는 카란>$B$B그러니 날 도와주시오. 여기서 빠져나가면 내 나머지 일생을 그 배신자를 찾으며 보낼 참이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2481, 'koKR', '어디까지 얘기를 했더라? 아, 그렇지. 그래서 체포당하게 되었소. 내 정예 경비병 부하들은 그 자리에서 처형당했고, 그들은 날 살려 두고 공주는 숫양에 태워 데려가 버렸소. 나는 잿가루 채석장의 유치소로 끌고 가더니 이 감옥으로 이감시킵디다.$B$B내 처량한 목숨으로 몸값이나 받으려고 날 살려 둔 게 아닌가 하고 생각할 수밖에 없소. 아니면 자신들의 잔인함에 내가 여기 앉아서 죽을 때까지 지난 일이나 되새기도록 만들려고 한 것이든지. 후회란 세상에서 가', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2482, 'koKR', '모이라 공주는 이제 제왕 타우릿산 옆에서 지내고 있소. 무슨 세뇌 마법을 걸어 놓은 것 같은데... 그런데도 난 여기 앉아서 아무런 일도 할 수가 없으니.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2493, 'koKR', '잠자리에 든 나를 방해하는 건 바보들뿐이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2494, 'koKR', '<눈이 번쩍이며 빛나는 키루스>$B$B너를 통째로 집어삼킬까? 아니면 좀 더 살려 둘까?$B$B아직 쓸모가 있을지도 모르겠군...$B$B내 부하와 맞서 싸워. 살아남아서 네가 승리한 증거를 가져와.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2496, 'koKR', '투덜 투덜...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2497, 'koKR', '옐마크의 연금술용품점을 찾아보게. 골목길의 중앙, 거대한 나무 서쪽에 있지.', '옐마크의 연금술용품점을 찾아보게. 골목길의 중앙, 거대한 나무 서쪽에 있지.', '연금술에 소질이 있다면 옐마크가 물약이나 오일 만드는 법에 대해 가르쳐 줄 거야. 골목길의 중앙에 있는 연금술용품점으로 가보게.', '연금술에 소질이 있다면 옐마크가 물약이나 오일 만드는 법에 대해 가르쳐 줄 거야. 골목길의 중앙에 있는 연금술용품점으로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2498, 'koKR', '뭐, 뭐라고?! 우리 모두 돈 벌어야 하잖아... 가만히 서 있다고 돈이 굴러들어 오진 않는다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2499, 'koKR', '대장기술을 배우고자 한다면 불타는 모루에 있는 사루 스틸퓨리와 얘기해 보게. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가.', '대장기술을 배우고자 한다면 불타는 모루에 있는 사루 스틸퓨리와 얘기해 보게. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가.', '내가 들고 있는 도끼만큼이나 좋은 무기를 만드는 법을 사루 스틸퓨리라면 가르쳐 줄지 모르지. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가면 불타는 모루가 있다네.', '내가 들고 있는 도끼만큼이나 좋은 무기를 만드는 법을 사루 스틸퓨리라면 가르쳐 줄지 모르지. 명예의 골짜기로 들어가 붉은협곡 광부조합에서 오른쪽 길을 따라 끝까지 가면 불타는 모루가 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2500, 'koKR', '골목길 위층의 보르스탄의 아궁이에 있는 잠자를 찾아가게. 힘의 골짜기에서 골목길로 들어가면 왼쪽으로 보이는 계단을 따라 올라가.', '골목길 위층의 보르스탄의 아궁이에 있는 잠자를 찾아가게. 힘의 골짜기에서 골목길로 들어가면 왼쪽으로 보이는 계단을 따라 올라가.', '잠자를 찾아가보게. 힘의 골짜기에서 골목길로 들어서면 왼쪽에 있는 계단을 따라 위층으로 올라가. 보르스탄의 아궁이에 있을 걸세.', '잠자를 찾아가보게. 힘의 골짜기에서 골목길로 들어서면 왼쪽에 있는 계단을 따라 위층으로 올라가. 보르스탄의 아궁이에 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2501, 'koKR', '고단의 마법상점으로 가게. 골목길의 서쪽 끝, 지혜의 골짜기 옆에 있네.', '고단의 마법상점으로 가게. 골목길의 서쪽 끝, 지혜의 골짜기 옆에 있네.', '내 도끼에 마법 부여를 해 줄 수 있나? 효과가 오래가야 되는데. 아직 그만큼 능력이 안 된다면 다음 기회에 하세. 골목길의 서쪽 끝, 지혜의 골짜기 근처에 있는 고단의 마법상점으로 가보게.', '내 도끼에 마법 부여를 해 줄 수 있나? 효과가 오래가야 되는데. 아직 그만큼 능력이 안 된다면 다음 기회에 하세. 골목길의 서쪽 끝, 지혜의 골짜기 근처에 있는 고단의 마법상점으로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2502, 'koKR', '질기고 좋은 붕대라면 아르녹이 잘 만들지. 정기의 골짜기, 정기의 오두막 옆 웅덩이에 적자 생존이라는 가게가 있네. 힘의 골짜기에서 위로 이어지는 길을 따라 서쪽으로 가게.', '질기고 좋은 붕대라면 아르녹이 잘 만들지. 정기의 골짜기, 정기의 오두막 옆 웅덩이에 적자 생존이라는 가게가 있네. 힘의 골짜기에서 위로 이어지는 길을 따라 서쪽으로 가게.', '전사들의 상처에 붕대를 감아 줄 이는 반드시 필요하지. 정기의 골짜기, 정기의 오두막 옆에 있는 적자 생존에서 아르녹을 찾아봐. 힘의 골짜기에서 위로 이어지는 길을 따라 서쪽으로 가면서 웅덩이를 찾아보게.', '싸움이 끝나면 우리 전사들도 누군가는 붕대를 감아 줘야겠지. 정기의 골짜기 정령의 오두막 옆 \'적자생존\' 오두막의 아르노크를 찾아가게. 힘의 골짜기에서 위쪽과 서쪽을 바라보면 호수가 보일 거야. 그곳에 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2503, 'koKR', '루막 그 친구... 전투는 아랑곳 안 하고 늘 낚시질만 한다니까. 명예의 골짜기 호수에 있는 부두에서 찾아보게. 간 김에 샨키스에게 안부나 전해 주고.', '루막 그 친구... 전투는 아랑곳 안 하고 늘 낚시질만 한다니까. 명예의 골짜기 호수에 있는 부두에서 찾아보게. 간 김에 샨키스에게 안부나 전해 주고.', '낚시는 전장에서 살아남은 이들이 늘그막에 즐기는 최고의 취미지! 명예의 골짜기에 있는 호수에서 루막을 찾아보게.', '낚시는 전장에서 살아남은 이들이 늘그막에 즐기는 최고의 취미지! 명예의 골짜기에 있는 호수에서 루막을 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2504, 'koKR', '약초라... 골목길에 있는 수목원으로 가서 잔디와 얘기해 보게. 지혜의 골짜기, 아스란의 상점 뒤에는 나무 계단이 있네. 그 계단을 따라 골목길의 위로 올라가면 찾을 수 있을 거야.', '약초라... 골목길에 있는 수목원으로 가서 잔디와 얘기해 보게. 지혜의 골짜기, 아스란의 상점 뒤에는 나무 계단이 있네. 그 계단을 따라 골목길의 위로 올라가면 찾을 수 있을 거야.', '잔디의 수목원에나 가버려! 어라, 방금 내가 반말을 했나? 글록 타, 보초를 서느라 피곤했던 모양이군! 지혜의 골짜기에 있는 아스란의 상점 뒤편에는 나무 계단이 있네. 계단을 따라 골목길의 위로 올라가면 그곳에 잔디가 있을 거야.', '잔디의 수목원에나 가버려! 어라, 방금 내가 반말을 했나? 글록 타, 보초를 서느라 피곤했던 모양이군! 지혜의 골짜기에 있는 아스란의 상점 뒤편에는 나무 계단이 있네. 계단을 따라 골목길의 위로 올라가면 그곳에 잔디가 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2505, 'koKR', '어이! 손가락 뼈다귀 한 판 하러 왔나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2513, 'koKR', '골목길에 있는 코도 가죽용품점으로 가보게. 가서 카롤렉에게 물어보게.', '골목길에 있는 코도 가죽용품점으로 가보게. 가서 카롤렉에게 물어보게.', '골목길의 중앙에 있는 코도 가죽 용품점으로 가보게.', '골목길의 중앙에 있는 코도 가죽 용품점으로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2515, 'koKR', '명예의 골짜기에 있는 호수에서 북동쪽으로 가면 붉은협곡 광부조합이 있는데, 그곳에서 마카루와 얘기해 보게.', '명예의 골짜기에 있는 호수에서 북동쪽으로 가면 붉은협곡 광부조합이 있는데, 그곳에서 마카루와 얘기해 보게.', '마카루를 찾아 가게. 그 친구 명예의 골짜기 호수 바로 옆에 있는 붉은협곡 광부조합에서 밤낮 가리지 않고 일하고 있지.', '마카루를 찾아 가게. 그 친구 명예의 골짜기 호수 바로 옆에 있는 붉은협곡 광부조합에서 밤낮 가리지 않고 일하고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2516, 'koKR', '짐승 가죽을 벗기는 일이라면 투워드가 잘 가르쳐 줄 거야. 골목길에 있는 코도 가죽용품점에서 그 친구를 찾아보게.', '짐승 가죽을 벗기는 일이라면 투워드가 잘 가르쳐 줄 거야. 골목길에 있는 코도 가죽용품점에서 그 친구를 찾아보게.', '당신이 사냥해 죽인 짐승의 숭고한 죽음을 조금이라도 기리고 싶다면, 그들이 남긴 몸을 의미 있게 사용하게. 골목길 중앙에 있는 코도 가죽용품점에서 투워드와 얘기해 보는 게 좋겠군.', '당신이 사냥해 죽인 짐승의 숭고한 죽음을 조금이라도 기리고 싶다면, 그들이 남긴 몸을 의미 있게 사용하게. 골목길 중앙에 있는 코도 가죽용품점에서 투워드와 얘기해 보는 게 좋겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2518, 'koKR', '골목길에 마가르의 의류점이 있네. 거대한 나무의 남쪽, 코도 가죽용품점 옆에서 찾을 수 있을 거야.', '골목길에 마가르의 의류점이 있네. 거대한 나무의 남쪽, 코도 가죽용품점 옆에서 찾을 수 있을 거야.', '옷이라고!? 도끼와 검 앞에서는 무용지물일 텐데! 참, 나... 뭐, 재봉사가 되고 싶다면 골목길에 있는 마가르의 의류점에 가보게.', '옷이라고!? 도끼와 검 앞에서는 무용지물일 텐데! 참, 나... 뭐, 재봉사가 되고 싶다면 골목길에 있는 마가르의 의류점에 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2533, 'koKR', '$c|1이여;여;, 우리에겐 맡은 바 임무가 있네. 호드의 일원으로서의 책임과 의무 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2534, 'koKR', '그가 오는 소리가 들리는 것 같아! 서쪽을 보게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2554, 'koKR', '오그리마 은행은 힘의 골짜기에 있네. 도시 정문에서 북쪽으로 가서 찾아보게.', '오그리마 은행은 힘의 골짜기에 있네. 도시 정문에서 북쪽으로 가서 찾아보게.', '힘의 골짜기, 하늘탑 남쪽에서 오그리마 은행을 찾아봐.', '힘의 골짜기, 하늘탑 남쪽에서 오그리마 은행을 찾아봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2555, 'koKR', '힘의 골짜기에 있는 하늘탑 꼭대기로 가게. 와이번 조련사, 도라스가 곧장 전장으로 데려다 줄 거야.', '힘의 골짜기에 있는 하늘탑 꼭대기로 가게. 와이번 조련사, 도라스가 곧장 전장으로 데려다 줄 거야.', '와이번 조련사가 어디에 있겠나? 힘의 골짜기에 있는 하늘탑 꼭대기로 가보게.', '와이번 조련사가 어디에 있겠나? 힘의 골짜기에 있는 하늘탑 꼭대기로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2556, 'koKR', '호드 대사관에 있는 울트런 클랜브링어를 찾는 거로군. 대사관은 힘의 골짜기 서쪽에 있네.', '호드 대사관에 있는 울트런 클랜브링어를 찾는 거로군. 대사관은 힘의 골짜기 서쪽에 있네.', '호드 대사관이라면 힘의 골짜기 서쪽에 있소이다.', '호드 대사관이라면 힘의 골짜기 서쪽에 있소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2557, 'koKR', '도시 정문에서 바라보면 북쪽으로, 힘의 골짜기 오른편의 두 번째 건물이네. 여관주인 그리쉬카를 만나보게.', '도시 정문에서 바라보면 북쪽으로, 힘의 골짜기 오른편의 두 번째 건물이네. 여관주인 그리쉬카를 만나보게.', '힘의 골짜기에 있는 여관주인 그리쉬카를 찾아보게. 여관은 도시 정문에서 북동쪽에 있네.', '힘의 골짜기에 있는 여관주인 그리쉬카를 찾아보게. 여관은 도시 정문에서 북동쪽에 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2558, 'koKR', '우체통은 힘의 골짜기 중앙에 있는 오그리마 은행 바깥에 있다네.', '우체통은 힘의 골짜기 중앙에 있는 오그리마 은행 바깥에 있다네.', '당신 앞으로 연애 편지라도 왔나 보려면 힘의 골짜기 중앙에 있는 은행으로 가보게. 바깥에서 우체통을 찾을 수 있을 거야.', '당신 앞으로 연애 편지라도 왔나 보려면 힘의 골짜기 중앙에 있는 은행으로 가보게. 바깥에서 우체통을 찾을 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2559, 'koKR', '명예의 골짜기, 원형경기장 서쪽에 있는 사냥꾼의 전당으로 가보게. 오르막 그림샷을 만날 수 있을 게야.', '명예의 골짜기, 원형경기장 서쪽에 있는 사냥꾼의 전당으로 가보게. 오르막 그림샷을 만날 수 있을 게야.', '명예의 골짜기로 들어서서 북서쪽으로 곧장 가보게. 사냥꾼의 전당을 찾을 수 있을 게야.', '명예의 골짜기로 들어서서 북서쪽으로 곧장 가보게. 사냥꾼의 전당을 찾을 수 있을 게야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2560, 'koKR', '정기의 골짜기에 있는 검은장미 오두막에서 페프레도와 얘기해 보게. 검은장미 오두막은 힘의 골짜기 서쪽을 향해 위로 올라가면 있다네.', '정기의 골짜기에 있는 검은장미 오두막에서 페프레도와 얘기해 보게. 검은장미 오두막은 힘의 골짜기 서쪽을 향해 위로 올라가면 있다네.', '이런, 아직 순간이동을 배우지 못한 자로군? 정기의 골짜기 웅덩이 옆에 있는 검은장미 오두막으로 가보게.', '이런, 아직 순간이동을 배우지 못한 자로군? 정기의 골짜기 웅덩이 옆에 있는 검은장미 오두막으로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2561, 'koKR', '제이우스와 그의 사제들이라면 정기의 골짜기에 있는 정기의 오두막에 있지. 힘의 골짜기에서 서쪽으로 올라가면 있는 웅덩이로 가보게.', '제이우스와 그의 사제들이라면 정기의 골짜기에 있는 정기의 오두막에 있지. 힘의 골짜기에서 서쪽으로 올라가면 있는 웅덩이로 가보게.', '치유 같은 건 고통을 견딜 줄 모르는 나약한 자들이나 필요로 하지. 하지만 정 필요하다면 정기의 골짜기에서 서쪽 위로 올라가면 보이는 웅덩이에서 정기의 오두막을 찾아보게.', '치유 같은 건 고통을 견딜 줄 모르는 나약한 자들이나 필요로 하지. 하지만 정 필요하다면 정기의 골짜기에서 서쪽 위로 올라가면 보이는 웅덩이에서 정기의 오두막을 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2562, 'koKR', '칼드리스 드림시커를 찾는 거로군. 그녀는 다른 주술사들과 함께 지혜의 골짜기에 있는 스랄의 요새 입구에 있지.', '칼드리스 드림시커를 찾는 거로군. 그녀는 다른 주술사들과 함께 지혜의 골짜기에 있는 스랄의 요새 입구에 있지.', '제대로 찾아왔군. 지혜의 골짜기에 있는 스랄의 요새 입구에서 당신의 진리를 찾아보게.', '제대로 찾아왔군. 지혜의 골짜기에 있는 스랄의 요새 입구에서 당신의 진리를 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2563, 'koKR', '날쌘그림자 결사단의 셴툴을 찾는 거로군. 골목길에 있는 드로퍼스 부자 고물상 맞은 편에 있는 지하도를 따라 어둠의 틈으로 내려가 보게.', '날쌘그림자 결사단의 셴툴을 찾는 거로군. 골목길에 있는 드로퍼스 부자 고물상 맞은 편에 있는 지하도를 따라 어둠의 틈으로 내려가 보게.', '함부로 남의 물건에 손을 대는 건 좋지 않아! 셴툴과 날쌘그림자 결사단이라면 지하에 있는 어둠의 틈에서 찾을 수 있을 거야. 지혜의 골짜기 남쪽에서 그곳으로 내려가는 지하도를 찾게.', '함부로 남의 물건에 손을 대는 건 좋지 않아! 셴툴과 날쌘그림자 결사단이라면 지하에 있는 어둠의 틈에서 찾을 수 있을 거야. 지혜의 골짜기 남쪽에서 그곳으로 내려가는 지하도를 찾게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2564, 'koKR', '그롤다르와 검은불꽃 비밀집회를 찾는 건가? 어둠의 틈이라는 지하 동굴에서 찾아보게. 그 동굴로 내려가는 지하도는 두 개가 있는데, 하나는 지혜의 골짜기 바로 남쪽에, 다른 하나는 골목길에 있지.', '그롤다르와 검은불꽃 비밀집회를 찾는 건가? 어둠의 틈이라는 지하 동굴에서 찾아보게. 그 동굴로 내려가는 지하도는 두 개가 있는데, 하나는 지혜의 골짜기 바로 남쪽에, 다른 하나는 골목길에 있지.', '불타는 군단의 마수에서 벗어난 지 얼마나 지났다고 다시 악마들과 손을 잡으려는 건가? 흠, 어둠의 틈이라는 지하 동굴에 있는 검은불꽃 비밀집회를 찾아가보게. 골목길에서 그곳으로 내려가는 지하도가 있다네.', '불타는 군단의 마수에서 벗어난 지 얼마나 지났다고 다시 악마들과 손을 잡으려는 건가? 흠, 어둠의 틈이라는 지하 동굴에 있는 검은불꽃 비밀집회를 찾아가보게. 골목길에서 그곳으로 내려가는 지하도가 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2565, 'koKR', '명예의 골짜기에 있는 용사의 전당에서 그레즈 레이지피스트를 찾아 얘기해 보게. 혹시 나에 대해 묻거든 열심히 보초를 서고 있더라고 전하고!', '명예의 골짜기에 있는 용사의 전당에서 그레즈 레이지피스트를 찾아 얘기해 보게. 혹시 나에 대해 묻거든 열심히 보초를 서고 있더라고 전하고!', '명예의 골짜기에 있는 용사의 전당으로 가서 그레즈 레이지피스트를 찾게. 여기서 근무가 끝나면 내가 보고하러 가겠다고도 전해 줘.', '명예의 골짜기에 있는 용사의 전당으로 가서 그레즈 레이지피스트를 찾게. 여기서 근무가 끝나면 내가 보고하러 가겠다고도 전해 줘.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2566, 'koKR', '상급기사 피레아노르는 지혜의 골짜기에 있는 스랄의 그롬마쉬 요새에 있네.', '상급기사 피레아노르는 지혜의 골짜기에 있는 스랄의 그롬마쉬 요새에 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2567, 'koKR', '이 늙은이는 제발 그냥 내버려두게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2568, 'koKR', '누가 날 찾아오는 일은 아주 드문데... 무슨 일로 왔나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2569, 'koKR', '내가 아는 것은 모두 가르쳐 주었다, $n. 행운이 함께하길.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2570, 'koKR', '헤헤... 호기심이 강한 친구로구먼. 에보뿌리를 구하는 방법을 가르쳐 주지.$B$B여기서 북쪽에 있는 오래된 폐허에는 미블론 스날투스라는 아주 재수없는 놀이 한 마리 살고 있소. 내가 알기에는 유일하게 자라고 있는 에보뿌리를 지키고 있는데, 불철주야로 지키지 않겠소! 잠도 자지 않는 것 같소이다!$B$B할 수 있는 건 매수하는 방법밖에 없겠는데, 그 녀석이 좋아할 미끼를 내가 좀 주겠소. 그 녀석 옆에 그냥 두기만 하면 당신이 에보뿌리를 따올 수 있을', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2574, 'koKR', '그래... 자네가 약초채집 기술을 익히면 좀 더 큰 보람을 얻을 수 있을 걸세. 조금 특별한 씨앗을 기르고 재배해야 해. 이 늘푸른 주머니만 있으면 아무리 초보자라도 뭔가 길러낼 수 있긴 하지만 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2575, 'koKR', '안녕하시오. 페더문 요새의 이 변변찮은 자가 오늘은 뭘 도와 드리오리까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2593, 'koKR', '찾고 있는 게...?', '찾고 있는 게...?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2594, 'koKR', '어떤 기술을?', '어떤 기술을?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2595, 'koKR', NULL, '육체의 죽음은 영혼과 성스러운 임무의 탄생을 의미한 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2596, 'koKR', '우리 지도자, 운명의 문지기는 도전이라면 귀가 솔깃할거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2597, 'koKR', '우리 지도자, 운명의 문지기는 도전이라면 귀가 솔깃할거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2598, 'koKR', '나는 영원히 돌을 만질 수 없게 되었소. 두 번 다시는 무쇠를 가꾸는 영광을 알지 못할 것이오...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2599, 'koKR', '어떤 직업 상급자를?', '어떤 직업 상급자를?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2600, 'koKR', NULL, '당신은 우리의 동족도 아니고 도전장을 낸 것도 아니니 이곳을 지나갈 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2601, 'koKR', '우리의 운명은 위대한 불에 맞서는 모든 자들의 운명이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2602, 'koKR', '우리가 받고 있는 벌은 축복이기도 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2604, 'koKR', '고대 기술을 배우고 싶소? 아니면 검은 무쇠를 녹이고 싶은 거요?$B$B내 부탁을 들어주시오. 내게 희생 정신을 보여주시오. 그러면 한번 생각해 보지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2605, 'koKR', '당신은 의지가 강하고 목적이 뚜렷하군.$B$B당신이라면 자격이 있을지도 모르겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2606, 'koKR', '당신이 원하는 게 무언지 알았고 값진 보석을 대가로 지급했으니 가르쳐주겠소...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2633, 'koKR', '어... 어떻게 해서 여기로 오게 됐는지 잘 모르겠어요...$B$B뗏목...을 타고 돌아다닌 거 같은데...$B$B', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2634, 'koKR', '일단 돈을 좀 내면 제 이야기를 해드리죠.$B$B아, 당신 $n|1이로군요;로군요;? 하하... 농담이었어요.', '내 이름이 낯익나? 어쩌면 아주 오래전에 서로 알던 사이였을지도 모르지...$B$B누군가 중요한 사람의 이름을 따서 지었다고 들은 것 같군...', '내 이름이 낯익지 않나요? 어쩌면 우린 오래전에 알고 지냈을지도 몰라요...$B$B내 이름은 아주 중요한 인물의 이름을 딴 것 같은데...', NULL, '안녕하세요! 돌아와 줘서 기뻐요, $n. 내가 드린 첫 임무는 완수하셨나요? 그렇다면 다시 부탁드릴 임무가 있어요...', NULL, '여기에 불시착한 후로 분화구를 돌아다니고 있었는데 전에 누가 말한 게 기억이 나더군요... \"위로 가! 앞에 있는 산 위로!\" 머릿속에서 계속 이 말이 들렸어요.$B$B그 말을 듣고 여기로 오게 된 거랍니다!', NULL, '아주 오래전에 여행을 다니다가 누군가를 만났는데 그 사람이 이런 말을 했었어요. \"그걸 사용하는 법을 통달하면 이걸 주겠소\"라고.$B$B그게 무슨 뜻인 것 같아요? 그때 나는 몰랐어요. 실은 지금도 여전히 모르겠고요...', NULL, '이건 모두에게 비밀로 해야 해요. 나까지 포함해서 말이에요!$B$B날 찾아줘서 기뻐요. 내가 수풀 속이나 바위 밑에 숨어 있지 않아서 다행이지 않나요?', NULL, NULL, NULL, NULL, NULL),
(2635, 'koKR', '고마워요, $n! 당신이야말로 운고로 분화구의 영웅이세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2636, 'koKR', '라그나로스 님이 최고 지배자가 될 것이다!', '라그나로스 님이 최고 지배자가 될 것이다!', '한 잔 드시오, $c 친구. 이게 마지막 술잔일 수도 있으니!', '한잔해, $c. 마지막 술이 될지도 모르니까!', '험상궂은 주정뱅이 선술집이 아니었으면 여가 시간에 새끼용 날개나 뜯으면서 지냈을 거요.', '험상궂은 주정뱅이 선술집이 없었다면 난 남는 시간에 새끼용 날개나 뜯고 있었을걸.', '험상궂은 주정뱅이 선술집이 아니었으면 쉬는 시간에 새끼용 날개나 뜯으면서 지냈을 겁니다.', '험상궂은 주정뱅이 선술집이 아니었으면 쉬는 시간에 새끼용 날개나 뜯으면서 지냈을 거예요.', '물의 정령들이 불의 정령들과 전쟁을 치르고 있는데, 그렇게 따지고 보면 우리하고도 전쟁을 치르고 있는 셈이지. 녀석들의 우두머리 중 하나인 히드락시스가 요원들을 끌어 모으고 있다던데...', '물의 정령들이 불의 정령들과 전쟁을 치르고 있는데, 그렇게 따지고 보면 우리하고도 전쟁을 치르고 있는 셈이죠. 녀석들의 우두머리 중 하나인 히드락시스가 요원들을 끌어 모으고 있다던데...', '물의 정령들 사이에서 히드락시스라는 군주가 불의 종들과 전쟁을 치르고 있다고 하더군. 그 녀석이 지기를 바랍시다!', '물의 정령들 사이에서 히드락시스라는 군주가 불의 종들과 전쟁을 치르고 있다고 하더군요. 그 녀석이 지기를 바랍시다!', '물의 군주 히드락시스는 아즈샤라의 폭풍의 만에 있는 어떤 섬에서 숨어 지낸다고 합디다. 그 바보 같은 녀석이 그곳에서 대체 무슨 음모를 꾸미고 있는 건지...', '물의 군주 히드락시스는 아즈샤라 폭풍의 만에 있는 섬에 숨어 있지. 그런 곳에서 그 멍청이가 무슨 위협을 만들 수 있겠어?', '히드락시스가 이번 전쟁에 더 많은 병력을 끌어 모은다면 힘의 균형이 뒤바뀔지도 모르지...', '히드락시스가 이번 전쟁에 더 많은 병력을 끌어 모은다면 힘의 균형이 뒤바뀔지도 모르지요...'),
(2637, 'koKR', '총기류와 불을 가지고 장난 치다가 결국 누군가 죽게 되는 거라니까, 딸꾹.', '총기류와 불을 가지고 장난 치다가 결국 누군가 죽게 되는 거라니까, 딸꾹.', '아버지께서 이런 날들이 올 것이라고 말씀하셨지. 웬 낯선 사람이 다가와서 말을 걸면 그 사람을 죽이지 않으려고 꾹 참아야 한다고 말이야.', '아버지가 이런 날도 있을 거라고 하셨지. 낯선 사람이 말을 걸어 오면 $g 그놈:그녀;을 죽이고 싶은 걸 꾹 참아야 하는 날 말이야.', '썬더브루 맥주를 들어보셨소? 아주 좋은 술이지! 딸꾹!', '썬더브루 맥주 마셔 봤나? 꽤 괜찮더라고!', '한 시간 후에는 일을 해야 하지만 그때까지는 쭉 들이켜야지, 암!', '한 시간 뒤엔 근무지만... 그전까지는 한잔해야지! 건배!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'koKR', '돌망치 요새에 온 걸 환영하네, $c 친구. 내가 도와 줄 일이라도 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2639, 'koKR', '안녕하십니까. 가죽 용품이나 가죽세공 보급품을 찾고 있다면 반쯤은 퇴직했다고 할 수 있는 이 성기사를 잘 찾아오신 겁니다.', NULL, '정말이지... 쿠인티스가 한 번만 더 내 옷 속에 낚시용 땅벌레를 집어넣으려고 하면 날이 시퍼런 이 검으로 거길 잘라 버릴 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2640, 'koKR', '대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네.', '대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2641, 'koKR', '확실히 남쪽 바다 어디에서도 무법항에서 먹을 수 있는 조개 수프만한 게 없지. 아, 요리에는 관심이 없나 보군? 아무튼 처녀의 몽상호 정박장에 온 것을 환영하오. 이 처녀의 몽상호로 말하자면 동부 왕국과 칼림도어를 왕래하는 가장 빠른 여객선이지. 이 배를 타면 톱니항으로 금방 갈 수 있소. 그러니 배가 도착할 때까지 편히 기다리시오.', '확실히 남쪽 바다 어디에서도 무법항에서 먹을 수 있는 조개 수프만한 게 없죠. 아, 요리에는 관심이 없나 보군요. 아무튼 처녀의 몽상호 정박지에 온 것을 환영해요. 이 처녀의 몽상호로 말하자면 동부 왕국과 칼림도어를 왕래하는 가장 빠른 여객선이죠. 이 배를 타면 톱니항으로 금방 갈 수 있소. 그러니 배가 도착할 때까지 편히 기다리시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2642, 'koKR', '이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있습니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연입니다. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요.', '이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있답니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연이에요. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2643, 'koKR', '안녕하신가! 바로 당신 같은 이를 찾고 있었지. 자, 앉아서 잘 들어보라고. 우리 둘 다 떼부자가 될 수 있는 계획이 있으니까 말이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2644, 'koKR', '저희 형이 이 무역로를 통해 돈을 많이 벌 수 있다는 말은 해 줬지만, 여기에서 살아야 한다는 얘기는 안 해 줬답니다. 비행선을 타고 행여 여기 다시 들르면 먹을 걸 좀 가져다주지 않으시겠습니까? 오그리마에서 아주 먹음직한 고기를 판다는데 한번 맛보고 싶거든요.', '저희 오빠가 이 무역로를 통해 돈을 많이 벌 수 있다는 말은 해 줬지만, 여기에서 살아야 한다는 얘기는 안 해 줬거든요. 비행선을 타고 행여 여기 다시 들르면 먹을 걸 좀 가져다주지 않겠어요? 오그리마에서 아주 먹음직한 고기를 판다는데 한번 맛보고 싶거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2653, 'koKR', '붉은협곡 광부조합에서 북동쪽에 있는 명예의 골짜기에서 노그의 작업소를 찾게.', '붉은협곡 광부조합에서 북동쪽에 있는 명예의 골짜기에서 노그의 작업소를 찾게.', '장난감 가게 같은 걸 운영하는 고블린말이군. 명예의 골짜기로 가 보게.', '장난감 가게 같은 걸 운영하는 고블린말이군. 명예의 골짜기로 가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2673, 'koKR', '나는 뛰어난 능력을 지닌 마법사요. 새로운 것을 배우고, 그 능력을 유지하는 데 있어 정신력과 기억력이 어떤 관련이 있는지 연구하며 하루하루를 보내왔었지. 한밤중에 내 도움이 필요하다는 엄청난 목소리를 듣지 않았다면 지금 이 순간에도 연구를 하고 있었을 거요. 나는 아주 잠깐만 여기에 머물면서, 당신만의 재능을 갈고 닦을 수 있도록 여러 가지를 알려줄 것이오. 아무런 대가도 없이 말이오. 그러고는 다시 떠날 것이니, 당신은 자신의 선택에 신중하고 충실하', '나는 뛰어난 능력을 지닌 마법사요. 새로운 것을 배우고, 그 능력을 유지하는 데 있어 정신력과 기억력이 어떤 관련이 있는지 연구하며 하루하루를 보내왔었지. 한밤중에 내 도움이 필요하다는 엄청난 목소리를 듣지 않았다면 지금 이 순간에도 연구를 하고 있었을 거요. 나는 아주 잠깐만 여기에 머물면서, 당신만의 재능을 갈고 닦을 수 있도록 여러 가지를 알려줄 것이오. 아무런 대가도 없이 말이오. 그러고는 다시 떠날 것이니, 당신은 자신의 선택에 신중하고 충실하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2676, 'koKR', '안녕하시오, $n. 요리에 대해 배우고 싶거든 언제든 날 찾아오시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2693, 'koKR', NULL, '<여군주 프레스톨이 노려봅니다.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2694, 'koKR', NULL, '난 바로 그대 곁에 서 있었습니다, 어리석기는... 그대가 찾는 게 뭔지 알고 있단 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2695, 'koKR', NULL, '그댄 망상에 빠진 집정관과 대다수가 더위로 고생하고 있을 하층민 야영지를 달래기 위해 우리의 전체적인 방어력을 낮추려는 것이겠지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2696, 'koKR', NULL, '당연히 아니겠지요. 그대와 같은 \"모험가\"라는 자들은 백성과 왕실 사이에 벌어지는 정치 드라마의 피해자인 경우가 많으니까 말입니다.$B$B내가 해 줄 말이라곤 다른 걸 찾아보라는 것입니다. 더 정확히 말해서 직업을 바꾸어보라는 겁니다.$B$B이 세계에는 지금도 영웅이 충분하답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2713, 'koKR', '무슨 일이지? *딸꾹*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2714, 'koKR', '그날따라 윈저 님은 완고했소. 그 정도도 아주 대단한 성과였지, 정말이오. 윈저 님께서는 계속 \"뭔가 느낌이 좋지 않다\"라고 말씀하셨는데 그 말이 맞아떨어진 거요!$B$B검은바위 산 중턱에 있을 때 끔찍한 짐승들에게 습격을 당한 거요. 그 짐승이란 물론 오크를 말하는 거요. 내 말에 집중 좀 해주겠소? 녀석들이 돌진해 오는데, 으르렁대는 소리와 쇠 부딪히는 소리 때문에 바람도 잠잠해질 지경이었다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2715, 'koKR', '내가 그 더러운 오크 녀석들과 맞섰을 것 같소? 나는 바보가 아니외다. 우리 아버지께서 늘 삼십육계 줄행랑이 최고라고 그러셨소. 난 아버지 말씀을 잘 알아들었던 거지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2716, 'koKR', '아, 알겠소. 알았다고. 어쨌든 난 어두운 곳으로 살짝 빠져나갔지.$B$B윈저 님께서는 그렇지 않아도 화가 잔뜩 나있던 마당에, 그게 부아가 더욱 치미셨던 모양이오. 무쇠폭군을 마구 휘두르면서 오크 녀석들에게 미친 듯이 소리를 질러댔소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2717, 'koKR', '그렇소. 오크를 무찌르는 전설적인 망치, 무쇠폭군이라고 들어본 적 없소? 그래. 그건 윈저 님의 망치였소. 프랑클론 포지라이트가 직접 윈저 님의 고조 할아버지를 위해 만들어줬다고 들었소. 프랑클론 포지라이트란 자는 돌다지 건축물이라든가... 구조물인가를 만들었지. 윈저 님께 듣기로는 프랑클론이 무쇠폭군과 똑같은 망치를 하나 더 가지고 있다고 하오. 이름이 뭐라던가... 무쇠지옥이라든가 그랬소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2718, 'koKR', '어디까지 얘기했더라? 아, 맞아. 그 오크 녀석들이 윈저 님께 달려들었소. 윈저 님은 어땠느냐고? 그분은 그 자리에서 한 발짝도 움직이지 않았소. 오크 녀석들이 한꺼번에 열 놈씩이나 덤벼드는데도 홀로 우뚝 서 계시더군. 내 눈앞에 보이는 것이라고는 무쇠폭군에서 번득이는 불빛과 난무하는 선혈뿐이었소. 몇 시간, 아니 수일 동안 계속된 싸움으로 기억하오. 그랬을 거요. 기억도 잘 나지 않는군. 어쨌든, 결국에 가서 싸움은 멈췄지만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2719, 'koKR', '죽었다고? 무슨 소리요? 윈저 님의 실력은 역겨운 오크 녀석들에게 당할 만큼 형편없지는 않소. 텔사마 선지 소시지가 이 세상에서 제일 맛있는 음식이라는 사실만큼이나 분명하지. 그분은 그냥 그렇게 서 계셨소. 머리에서 발끝까지 오크의 피와 찢겨나간 살점을 겹겹이 뒤집어 쓴 채 말이오. 하지만 확실히 살아 계셨고 정말이지 엄청난 분노가 그분을 휩싸고 있었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2720, 'koKR', '왜 자꾸 죽었다고 하는 거요? 죽었다고 누가 그랬소? 난 그분이 죽었다고 말한 적 없소이다. 실종된 것뿐이오.$B$B우리는 분명 오크와 검은무쇠 드워프 간에 벌어진 전쟁에 휘말려 든 것 같았소. 그 망할 놈의 오크 녀석들은 일찌감치 당신도, 나도 이해하지 못할 덫을 놓고 사악한 함정을 파고 있었던 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2721, 'koKR', '하하, 드워프들은 결코 술에 취하는 법이 없지. 그냥 조금 나른한 것뿐이오.$B$B어쨌든, 윈저님 말이오? 아마도 검은바위 나락 어딘가에 계실 거요. 당신과 같이 무지한 자에게는 검은무쇠 부족의 도시라고 해야 알아듣겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2722, 'koKR', '아, 아, 거 참 서두르지 마시오! 방금 얘기하려던 참이었단 말이지!$B$B그렇게 그분이 오크 핏덩어리를 뒤집어 쓰고 서 있는데 누군가 나타났소...$B$B바로, 검은무쇠 부족이었지! 내 얘기를 듣기는 한 거요?$B$B뭐, 어쨌든 검은무쇠 녀석들은 검은바위 부족보다 지략이 좀 뛰어난 편이오. 정렬이 잘 맞춰진 300명의 부대가 몰려왔지. *딸꾹* 실례...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2723, 'koKR', '아, 이 답답한 친구야... 당신 사실은 $R|1이;가; 아니라 그 \"특이한\" 종족 아니오? 우리는 트로그라고 부르는 멍청한 놈들 말이지.$B$B윈저 님과 검은무쇠 부족의 사이는 나쁘지 않았소. 고조 할아버지의 죽마고우가 바로 검은무쇠 드워프였으니까. 아마 그래서 검은무쇠 부족에서 윈저 님을 보고도 즉시 사살하지 않았던 것 같소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2724, 'koKR', '정말이지 당신은 아는 게 없군. 제련 기술이 좀 더 늘거든 다시 찾아오도록 하시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2725, 'koKR', '이제야 말귀를 좀 알아듣는구먼. 귀라도 좀 후비지 그러쇼. 거 답답해서 무슨 얘길 하겠소?!$B$B그래서, 검은무쇠 녀석들은 윈저님을 생포해갔지. 콧대가 하늘을 찌를 만큼 거만한 우두머리, 타우릿산인가 뭔가 하는 녀석이 무쇠폭군을 빼앗아 가져갔소. 내가 마지막으로 윈저 님을 본 게 그때요. *딸꾹* 쩝, 실례...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2726, 'koKR', '악령숲의 타락이 나를 이곳에 가두어 버렸네... 나의 영혼은 쉴 수가 없네...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2727, 'koKR', NULL, '험상궂은 주정뱅이 선술집에 오신 것을 환영합니다!', NULL, '검은무쇠단 맥주를 꼭 한번 마셔보세요. 이 부근의 드워프들은 질리지도 않을 만큼 좋아한다고 하더군요.', NULL, '플러거 스파즈링님은 참 좋은 분이세요. 게다가 주머니가 찢어질 정도로 돈도 아주 많이 버시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2728, 'koKR', NULL, '좋은 생각이네요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2729, 'koKR', NULL, '다시 한번 고마워요, $n. 락노트랑은 정말로 잘 되가고 있어요!', NULL, '험상궂은 주정뱅이 선술집에 오신 것을 환영합니다!', NULL, '검은무쇠단 맥주를 꼭 한번 마셔보세요. 이 부근의 드워프들은 질리지도 않을 만큼 좋아한다고 하더군요.', NULL, '플러거 스파즈링님은 참 좋은 분이세요. 게다가 주머니가 찢어질 정도로 돈도 아주 많이 버시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2734, 'koKR', NULL, '운고로 분화구에 있는 멋진 것들은 다 보셨나요, $n? 정말 놀랍죠. 저의 기계공학 기술로 만들 수 있는 것들에 비하면 좀 덜하지만 여기 있는 것이 모두 자연 그대로의 것이라는 걸 생각한다면... 그리 나쁘지도 않죠.$B$B렘트래블 삼촌은 이렇게 고풍스러운 곳을 좋아하신답니다. 저도 삼촌의 뒤를 따르면서 잃어버린 문화에서 새로운 것들을 발견하고 싶거든요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2735, 'koKR', NULL, '흠. 미스릴 형틀은 다 떨어져서 하나도 없어요. 에이미를 고치는 데 그것만 있으면 되나요? 아, 그러면 정말 좋겠네요!$B$B문명이 발달한 곳에서라면 미스릴 형틀을 그리 어렵지 않게 구할 수 있답니다. 솜씨 좋은 기술자에게 하나 만들어 달라고 해보세요. 미스릴 주괴가 몇 개 필요할 테지만 절 도와주신다면 아주 후하게 보상해 드리겠어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2753, 'koKR', '이거야말로 세계 최고이자 최신식 운송 수단이라고 할 수 있죠. 뭐? 노움이 만든 깊은굴 지하철이라고요? 이봐요, 잘 들으세요. 그따위 쓰레기를 믿느니, 차라리 가시덤불 골짜기에 날 기리는 동상을 세웠다는 말을 믿으시죠. 자, 그롬골까지 걸어서 가시겠습니까? 아니면 저희 최신식 비행선을 타고 가시겠습니까? 선택은 당신에게 달렸습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2758, 'koKR', '이봐, 지금 날 보고 있나?', '이봐, 지금 날 보고 있나?', '여기, 검은무쇠 맥주 한잔이요. 아, 이런. 당신은 종업원이 아니군.', '여기, 검은무쇠 맥주 한잔이요. 아, 이런. 당신은 종업원이 아니군.', '플러거 그 친구가 맥주통 하나를 너무 채운 모양이야. 곧 터질 것 같아!', '플러거 그 친구가 맥주통 하나를 너무 채운 모양이야. 곧 터질 것 같아!', '한참 즐기는 중인데 귀찮게 하지 마시오...', '한참 즐기는 중인데 귀찮게 하지 마시오...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2760, 'koKR', '어디로 가는 길을 찾으십니까?', '어디로 가는 길을 찾으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2761, 'koKR', '안전하게 보관해야 할 보물이라도 찾으신 겁니까? 스톤맨틀 집안에서 운영하는 사설금고에 보관하는 게 좋겠군요.\n\n아이언포지 입구에서 북동쪽으로 망치 하나 던지면 닿을 거리에 사설금고가 있습니다.', '안전하게 보관해야 할 보물이라도 찾으신 겁니까? 스톤맨틀 집안에서 운영하는 사설금고에 보관하는 게 좋겠군요.\n\n아이언포지 입구에서 북동쪽으로 망치 하나 던지면 닿을 거리에 사설금고가 있습니다.', '은행 말입니까? 아, 사설금고 말씀이시지요? 귀중품을 보관할 장소로 그 만한 데가 없지요. 아이언포지 입구에서 북동쪽으로 가면 있습니다.', '은행 말입니까? 아, 사설금고 말씀이시지요? 귀중품을 보관할 장소로 그 만한 데가 없지요. 아이언포지 입구에서 북동쪽으로 가면 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2762, 'koKR', '그리핀을 타시려고요? 그렇다면 그리스 서든을 찾아가보세요.\n\n아이언포지 중앙에 있는 대용광로 동쪽으로 가면 그 친구를 찾을 수 있을 겁니다.', '그리핀을 타시려고요? 그렇다면 그리스 서든을 찾아가보세요.\n\n아이언포지 중앙에 있는 대용광로 동쪽으로 가면 그 친구를 찾을 수 있을 겁니다.', '그리핀을 타는 것만큼 재미난 일도 없지요. 나이트 엘프들은 히포그리프나 실컷 타라고 하죠! 저는 그리핀을 타고 날아갈 수만 있으면 그걸로 대만족이니까요!$b$b흠, 잡담이 너무 길어졌군요. 대용광로 동쪽에 있는 그리스 서든을 찾아가세요. 그자가 안내할 겁니다.', '그리핀을 타는 것만큼 재미난 일도 없지요. 나이트 엘프들은 히포그리프나 실컷 타라고 하죠! 저는 그리핀을 타고 날아갈 수만 있으면 그걸로 대만족이니까요!$b$b흠, 잡담이 너무 길어졌군요. 대용광로 동쪽에 있는 그리스 서든을 찾아가세요. 그자가 안내할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2764, 'koKR', '길드를 창설할 생각이라면 아이언포지 사무소에 있는 욘도르 스틸브라우를 찾아가세요. 아이언포지 성문에서 남동쪽으로 가면 됩니다.', '길드를 창설할 생각이라면 아이언포지 사무소에 있는 욘도르 스틸브라우를 찾아가세요. 아이언포지 성문에서 남동쪽으로 가면 됩니다.', '흠, 길드를 창설하려면 욘도르 스틸브로우를 찾아가 보시오. 그가 도와 줄 수 있을 겁니다. 원래 온갖 서류에다, 복잡한 절차를 거쳐야 하는데... 그 자를 만나면 간단히 해결할 수 있지. 아이언포지 사무소로 가보십시오. 거기서 만날 수 있을 겁니다.', '흠, 길드를 창설하려면 욘도르 스틸브로우를 찾아가 보시오. 그가 도와 줄 수 있을 겁니다. 원래 온갖 서류에다, 복잡한 절차를 거쳐야 하는데... 그 자를 만나면 간단히 해결할 수 있지. 아이언포지 사무소로 가보십시오. 거기서 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2766, 'koKR', '어떤 직업 상급자를 찾으십니까?', '어떤 직업 상급자를 찾으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2768, 'koKR', '여관이요? 아, 아이언포지에서 최고로 맛 좋은 맥주를 한잔 걸치고 싶은 거로군요. 그렇다면 부싯돌 선술집으로 가보십시오.$B$B오시는 길이라면 아이언포지 정문에서 왼쪽, 가시는 길이라면 오른쪽에 있습니다.', '여관이요? 아, 아이언포지에서 최고로 맛 좋은 맥주를 한잔 걸치고 싶은 거로군요. 그렇다면 부싯돌 선술집으로 가보십시오.$B$B오시는 길이라면 아이언포지 정문에서 왼쪽, 가시는 길이라면 오른쪽에 있습니다.', '여관을 찾고 계신다면 부싯돌 선술집으로 가보십시오. 오시는 길이라면 아이언포지의 왼쪽, 나가시는 길이라면 오른쪽에 있습니다.BB아, 가시는 김에 제가 갈 테니 맥주나 한 통 준비해두라고 일러두십시오.', '여관을 찾고 계신다면 부싯돌 선술집으로 가보십시오. 오시는 길이라면 아이언포지의 왼쪽, 나가시는 길이라면 오른쪽에 있습니다.BB아, 가시는 김에 제가 갈 테니 맥주나 한 통 준비해두라고 일러두십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2769, 'koKR', '우체통은 부싯돌 선술집 옆에 있습니다. 아이언포지 성문에서 북쪽으로 조금만 가면 됩니다.', '우체통은 부싯돌 선술집 옆에 있습니다. 아이언포지 성문에서 북쪽으로 조금만 가면 됩니다.', '우체통이라고요? 저도 쓰고 있지만 요즘엔 광고 전단지만 잔뜩 온다니까요!$b$b`뚱뚱이 드워프, 한 달만 운동하면 노움만큼 날씬이가 될 수 있다`, `트로그 작살 폭탄을 무료로 받으려면 즉시 답장을 보내라`... 주마다 수신자 이름을 바꿔야 할 지경이라고요!$b$b전 분명히 경고해 드렸습니다. 우체통을 찾고 계시다면 부싯돌 선술집 바깥에 있습니다.', '우체통이라고요? 저도 쓰고 있지만 요즘엔 광고 전단지만 잔뜩 온다니까요!$b$b`뚱뚱이 드워프, 한 달만 운동하면 노움만큼 날씬이가 될 수 있다`, `트로그 작살 폭탄을 무료로 받으려면 즉시 답장을 보내라`... 주마다 수신자 이름을 바꿔야 할 지경이라고요!$b$b전 분명히 경고해 드렸습니다. 우체통을 찾고 계시다면 부싯돌 선술집 바깥에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2770, 'koKR', '요전 날 전투의 전당에 갔다가 레그누스 썬더그래니트가 자신의 동굴에 박제해서 놓을 새로운 전리품을 잡아왔다고 자랑을 늘어놓더군. 솜씨 있는 사냥꾼에게서 훈련을 받을 생각이라면 레그누스를 찾아가보시죠.', '요전 날 전투의 전당에 갔다가 레그누스 썬더그래니트가 자신의 동굴에 박제해서 놓을 새로운 전리품을 잡아왔다고 자랑을 늘어놓더군. 솜씨 있는 사냥꾼에게서 훈련을 받을 생각이라면 레그누스를 찾아가보시죠.', '젊은 $C 양반, 당신이 사냥꾼으로서 소질이 있다고 생각하십니까? 뭐, 시간이 지나면 차차 알게 되겠죠. 하지만 친구 머리 위에 사과 올려놓고 맞추기 게임 같은 건 전투의 전당에 있는 레그누스와를 만나 기술을 익히고 충분히 자신이 있을 때나 하십시오.', '젊은 $C 양반, 당신이 사냥꾼으로서 소질이 있다고 생각하십니까? 뭐, 시간이 지나면 차차 알게 되겠죠. 하지만 친구 머리 위에 사과 올려놓고 맞추기 게임 같은 건 전투의 전당에 있는 레그누스와를 만나 기술을 익히고 충분히 자신이 있을 때나 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2771, 'koKR', '빙크라고 하는 자그마한 여자 마법사 하나가 신비의 전당에 있는데 마법의 도움이 필요하다면 그녀를 찾아가 보십시오.\n\n신비의 전당은 아이언포지 성문 바로 북쪽에 있습니다.', '빙크라고 하는 자그마한 여자 마법사 하나가 신비의 전당에 있는데 마법의 도움이 필요하다면 그녀를 찾아가 보십시오.\n\n신비의 전당은 아이언포지 성문 바로 북쪽에 있습니다.', '아이언포지 성문 북쪽의 신비의 전당에 가면 마법 기술을 배울 수 있습니다. 그곳에서 늘 책 속에 파묻혀 사는 율리 스톰케틀을 찾으십시오.', '아이언포지 성문 북쪽의 신비의 전당에 가면 마법 기술을 배울 수 있습니다. 그곳에서 늘 책 속에 파묻혀 사는 율리 스톰케틀을 찾으십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2772, 'koKR', '아, 브레나 플린트크래그 말이로군. 솜씨가 아주 뛰어나지. 사제와 관련된 일이라면 브레나를 찾아가보게.\n\n아이언포지 성문에서 북쪽으로 가면 신비의 전당이 있는데, 그곳에서 브레나를 찾을 수 있을 거야.', '아, 브레나 플린트크래그 말이로군. 솜씨가 아주 뛰어나지. 사제와 관련된 일이라면 브레나를 찾아가보게.\n\n아이언포지 성문에서 북쪽으로 가면 신비의 전당이 있는데, 그곳에서 브레나를 찾을 수 있을 거야.', '아, 고통을 치유하는 데는 사제만한 이가 없지. 물론 맥주를 큰 잔에다 따라 단숨에 들이켜는 것도 그만이지만, 브레나 플린트크래그가 양조법을 가르치지는 않거든. 신비의 전당으로 가서 사제 훈련을 받는 것에 만족해야 할 거야.', '아, 고통을 치유하는 데는 사제만한 이가 없지. 물론 맥주를 큰 잔에다 따라 단숨에 들이켜는 것도 그만이지만, 브레나 플린트크래그가 양조법을 가르치지는 않거든. 신비의 전당으로 가서 사제 훈련을 받는 것에 만족해야 할 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2773, 'koKR', '브란두르 아이언해머를 찾아가십시오. 아이언포지 성문의 북쪽에 위치한 신비의 전당으로 가면 그 친구를 찾을 수 있을 겁니다.', '브란두르 아이언해머를 찾아가십시오. 아이언포지 성문의 북쪽에 위치한 신비의 전당으로 가면 그 친구를 찾을 수 있을 겁니다.', '아! 브란두르 아이언해머를 찾는군요. 그에게 가면 분명 도움을 받을 수 있을 겁니다. 아이언포지 성문에서 북쪽으로 가십시오. 신비의 전당에 있을 겁니다.', '아! 브란두르 아이언해머를 찾는군요. 그에게 가면 분명 도움을 받을 수 있을 겁니다. 아이언포지 성문에서 북쪽으로 가십시오. 신비의 전당에 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2774, 'koKR', '당신, 무슨 일을 꾸미고 있기에 그런 작자의 도움이 필요한 건가? 그렇지 않아도 저 건너 쓸쓸한 뒷골목에 있는 훌프단 블랙비어드란 도적 때문에 골치를 앓고 있는데 당신도 내 감시 대상에 추가해야 하나?', '당신, 무슨 일을 꾸미고 있기에 그런 작자의 도움이 필요한 건가? 그렇지 않아도 저 건너 쓸쓸한 뒷골목에 있는 훌프단 블랙비어드란 도적 때문에 골치를 앓고 있는데 당신도 내 감시 대상에 추가해야 하나?', '도적 친구들이라면 아이언포지 성문에서 북쪽에 있는 쓸쓸한 뒷골목에 있습니다. 그곳에 가면 분명히 펜스윅이 다른 소매치기 친구들에게 훔친 돈을 세고 있을 테지요. 조만간 그들을 모조리 잡아들일 생각입니다! 물론 그동안 당신도 지켜볼 겁니다.', '도적 친구들이라면 아이언포지 성문에서 북쪽에 있는 쓸쓸한 뒷골목에 있습니다. 그곳에 가면 분명히 펜스윅이 다른 소매치기 친구들에게 훔친 돈을 세고 있을 테지요. 조만간 그들을 모조리 잡아들일 생각입니다! 물론 그동안 당신도 지켜볼 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2775, 'koKR', '늘 어둡고 사악한 생각에만 빠져 있는 패거리들을 찾으려면 아이언포지의 어두운 곳을 찾아가야지. 쓸쓸한 뒷골목이라고 이름도 아주 그럴듯하지? 그곳에 가면 시슬하트라는 녀석이 사악한 악마를 불러내어 부려 먹고 있을 거야.', '늘 어둡고 사악한 생각에만 빠져 있는 패거리들을 찾으려면 아이언포지의 어두운 곳을 찾아가야지. 쓸쓸한 뒷골목이라고 이름도 아주 그럴듯하지? 그곳에 가면 시슬하트라는 녀석이 사악한 악마를 불러내어 부려 먹고 있을 거야.', '흑마법사라... 글쎄, 여기서 그런 일을 할 생각이라면 당신의 악마를 잘 관리하는 게 좋을 걸, 젊은 양반. 난 악마를 좋아하지도 않아. 내 도끼로 악마들을 내리찍는 걸 훨씬 좋아하지. 무슨 말인지 알겠나?$b$b쓸쓸한 뒷골목으로 냉큼 가버리게. 거기서 시슬하트라는 흑마법사를 만날 수 있을 테니.', '흑마법사라... 글쎄, 여기서 그런 일을 할 생각이라면 당신의 악마를 잘 관리하는 게 좋을 걸, 젊은 양반. 난 악마를 좋아하지도 않아. 내 도끼로 악마들을 내리찍는 걸 훨씬 좋아하지. 무슨 말인지 알겠나?$b$b쓸쓸한 뒷골목으로 냉큼 가버리게. 거기서 시슬하트라는 흑마법사를 만날 수 있을 테니.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2776, 'koKR', '아! 전사의 무예를 배우시려고요! 켈스트럼 스톤브레이커가 아주 잘 가르쳐줄 겁니다. 아이언포지 성문 동쪽에 있는 전투의 전당으로 가십시오.', '아! 전사의 무예를 배우시려고요! 켈스트럼 스톤브레이커가 아주 잘 가르쳐줄 겁니다. 아이언포지 성문 동쪽에 있는 전투의 전당으로 가십시오.', '켈스트럼은 입도 싸고 허풍쟁이인데... 하지만, 전사로서의 솜씨와 기술은 아주 탁월하답니다!$b$b전사 훈련을 받고 싶다면 그와 얘기해 보세요. 아이언포지 성문 동쪽에 있는 전투의 전당에서 만날 수 있을 겁니다.', '켈스트럼은 입도 싸고 허풍쟁이인데... 하지만, 전사로서의 솜씨와 기술은 아주 탁월하답니다!$b$b전사 훈련을 받고 싶다면 그와 얘기해 보세요. 아이언포지 성문 동쪽에 있는 전투의 전당에서 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2793, 'koKR', '어떤 기술을 배우려고 하십니까?', '어떤 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2794, 'koKR', '연금술 가르쳐주는 데를 찾으세요? 저도 방금 다녀왔는데. 노움들이 모여있는 땜장이 마을에서 베리피즈 양을 찾아보십시오.', '연금술 가르쳐주는 데를 찾으세요? 저도 방금 다녀왔는데. 노움들이 모여있는 땜장이 마을에서 베리피즈 양을 찾아보십시오.', '전문 연금술사에게서 훈련을 받고 싶으십니까? 저도 방금 거기서 왔지요. 아, 저도 방금 다녀 왔는데... 노움들이 모여있는 땜장이 마을에서 베리피즈 양을 찾아보십시오.\r\n\r\n히유... 대체 왜 내가 푸른 물약을 마시지 않았지?', '전문 연금술사에게서 훈련을 받고 싶으십니까? 저도 방금 거기서 왔지요. 아, 저도 방금 다녀 왔는데... 노움들이 모여있는 땜장이 마을에서 베리피즈 양을 찾아보십시오.\r\n\r\n히유... 대체 왜 내가 푸른 물약을 마시지 않았지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2795, 'koKR', '아이언포지에 잘 찾아오신 겁니다! 아제로스 각지에서 대장장이가 되려는 자들이 이곳으로 모여들고 있답니다. 우리의 이 멋진 도시 중앙에 있는 대용광로 모루 옆에서 열심히 망치질을 하고 있는 벤구스 딥포지를 찾아가십시오.', '아이언포지에 잘 찾아오신 겁니다! 아제로스 각지에서 대장장이가 되려는 자들이 이곳으로 모여들고 있답니다. 우리의 이 멋진 도시 중앙에 있는 대용광로 모루 옆에서 열심히 망치질을 하고 있는 벤구스 딥포지를 찾아가십시오.', '정말 대장장이가 어디 있는지 몰라서 물으시는 겁니까? 대용광로를 들어본 적이 없다고요? 최고의 대장장이들이 모여서 무기와 방어구를 제작하는 곳이란 말입니다!$b$b아이언포지 한가운데에 있는데, 거기서 벤구스 딥포지가 단연 뛰어난 대장기술을 갖고 있으니 만나보십시오.', '정말 대장장이가 어디 있는지 몰라서 물으시는 겁니까? 대용광로를 들어본 적이 없다고요? 최고의 대장장이들이 모여서 무기와 방어구를 제작하는 곳이란 말입니다!$b$b아이언포지 한가운데에 있는데, 거기서 벤구스 딥포지가 단연 뛰어난 대장기술을 갖고 있으니 만나보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2796, 'koKR', '전문 요리사 말입니까? 대용광로 북동쪽에 있는 놋쇠단지 제과점으로 가보십시오. 다릴 리크너선이 기운을 북돋아줄 맛깔스러운 음식을 만드는 방법을 가르쳐줄 겁니다!', '전문 요리사 말입니까? 대용광로 북동쪽에 있는 놋쇠단지 제과점으로 가보십시오. 다릴 리크너선이 기운을 북돋아줄 맛깔스러운 음식을 만드는 방법을 가르쳐줄 겁니다!', '아! 다릴 리크너선은 정말 탁월한 요리 솜씨를 자랑하지요! 칠리 요리를 얼마나 화끈하게 잘도 만드는지, 쇳덩이를 담금질하는 데 써도 될 정도랍니다! 아마 그 특제 칠리 조리법은 비밀로 하려 할 테지만 괜찮은 요리법을 가르쳐 주긴 할 겁니다. 대용광로의 북동부에 있는 놋쇠단지 제과점에 가 보십시오.', '아! 다릴 리크너선은 정말 탁월한 요리 솜씨를 자랑하지요! 칠리 요리를 얼마나 화끈하게 잘도 만드는지, 쇳덩이를 담금질하는 데 써도 될 정도랍니다! 아마 그 특제 칠리 조리법은 비밀로 하려 할 테지만 괜찮은 요리법을 가르쳐 주긴 할 겁니다. 대용광로의 북동부에 있는 놋쇠단지 제과점에 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2797, 'koKR', '아, 마법부여 기술을 배울 생각이라면 김블 시슬퍼즈를 찾아가야 할 겁니다. 김블은 \'시슬퍼즈의 신비한 이야기\'라는 자기 가게에 있을 겁니다. 대용광로의 그리핀 조련사 바로 옆에 있죠.', '아, 마법부여 기술을 배울 생각이라면 김블 시슬퍼즈를 찾아가야 할 겁니다. 김블은 \'시슬퍼즈의 신비한 이야기\'라는 자기 가게에 있을 겁니다. 대용광로의 그리핀 조련사 바로 옆에 있죠.', '아! 어떤 물건에 마법을 부여할 때는 신중하게 생각해 볼 필요가 있습니다. 저는 술잔에 아까운 술 한 방울도 흘리지 않도록 마법을 부여했더니만, 이제는 그 잔으로 아무것도 마실 수가 없게 되었지 뭡니까! 참 비극이지요.$b$b김블을 만나거든 제 충고를 잊지 마십시오. 대용광로의 그리핀 조련사 바로 맞은 편에 있는 상점에 있을 겁니다.', '아! 어떤 물건에 마법을 부여할 때는 신중하게 생각해 볼 필요가 있습니다. 저는 술잔에 아까운 술 한 방울도 흘리지 않도록 마법을 부여했더니만, 이제는 그 잔으로 아무것도 마실 수가 없게 되었지 뭡니까! 참 비극이지요.$b$b김블을 만나거든 제 충고를 잊지 마십시오. 대용광로의 그리핀 조련사 바로 맞은 편에 있는 상점에 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2798, 'koKR', '땜장이 기술을 배우고 싶으십니까? 그렇다면, 여기저기 물어볼 것도 없이 바로 땜장이 마을로 가서 스프링스핀들 피즐기어를 찾아야지요.\n\n아이언포지 성문에서 동쪽으로 가십시오. 아니면 폭발 소리가 들리는 곳에 있을 겁니다.', '땜장이 기술을 배우고 싶으십니까? 그렇다면, 여기저기 물어볼 것도 없이 바로 땜장이 마을로 가서 스프링스핀들 피즐기어를 찾아야지요.\n\n아이언포지 성문에서 동쪽으로 가십시오. 아니면 폭발 소리가 들리는 곳에 있을 겁니다.', '아, 스프링스핀들 피즐기어를 찾고 계시는군요. 그 애물단지 노움 녀석... 쓸모없는 장치들이나 만들어 대고 있죠. 충고 하나 할까요? 땜장이 마을에 있는 그의 상점에 발을 들여 놓으면 함부로 아무것이나 만져보지 마십시오. 특히 그 기계 토끼에는 말입니다!$b$b폭발하는 토끼라니... 그런 건 대체 왜 만든단 말입니까?', '아, 스프링스핀들 피즐기어를 찾고 계시는군요. 그 애물단지 노움 녀석... 쓸모없는 장치들이나 만들어 대고 있죠. 충고 하나 할까요? 땜장이 마을에 있는 그의 상점에 발을 들여 놓으면 함부로 아무것이나 만져보지 마십시오. 특히 그 기계 토끼에는 말입니다!$b$b폭발하는 토끼라니... 그런 건 대체 왜 만든단 말입니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2799, 'koKR', '응급치료는 아주 값진 기술이오. 우리의 전문 응급치료사, 니사 파이어스톤이 잘 가르쳐줄 겁니다. 대용광로 남쪽에 있는 아이언포지 치료소에서 그 친구를 찾아보십시오.', '응급치료는 아주 값진 기술이오. 우리의 전문 응급치료사, 니사 파이어스톤이 잘 가르쳐줄 겁니다. 대용광로 남쪽에 있는 아이언포지 치료소에서 그 친구를 찾아보십시오.', '응급치료라고요? 어디 다치셨나요? 그런 것 같지는 않은데... 아, 응급치료를 배우고 싶다고요. 니사 파이어스톤을 찾아가 보십시오. 대용광로 옆에서 아이언포지 치료소를 운영하고 있으니 그곳으로 가시면 만나실 수 있을 겁니다.', '응급치료라고요? 어디 다치셨나요? 그런 것 같지는 않은데... 아, 응급치료를 배우고 싶다고요. 니사 파이어스톤을 찾아가 보십시오. 대용광로 옆에서 아이언포지 치료소를 운영하고 있으니 그곳으로 가시면 만나실 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2800, 'koKR', '그림누르 스톤브랜드는 타우렌만한 물고기를 낚았다고 허풍을 곧잘 늘어놓곤 하지만, 그래도 낚시 솜씨 하나는 알아준답니다. 그 친구, 쓸쓸한 뒷골목에서 여행용 낚시용품점이라는 가게를 하고 있습니다.', '그림누르 스톤브랜드는 타우렌만한 물고기를 낚았다고 허풍을 곧잘 늘어놓곤 하지만, 그래도 낚시 솜씨 하나는 알아준답니다. 그 친구, 쓸쓸한 뒷골목에서 여행용 낚시용품점이라는 가게를 하고 있습니다.', '한때 그림누르가 창을 낚은 적이 있다고... 아, 참치라고 그랬나? 그림누르 녀석! 낚시 얘기를 워낙 많이 늘어놔서 뭐가 뭔지 기억이 안 나는구먼. 쓸쓸한 뒷골목에 있으니 당신이 직접 찾아가서 창인지 참치인지 확인해 보십시오.', '한때 그림누르가 창을 낚은 적이 있다고... 아, 참치라고 그랬나? 그림누르 녀석! 낚시 얘기를 워낙 많이 늘어놔서 뭐가 뭔지 기억이 안 나는구먼. 쓸쓸한 뒷골목에 있으니 당신이 직접 찾아가서 창인지 참치인지 확인해 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2801, 'koKR', '약초니 씨앗이니 하는 것들 말씀입니까? 그런 거라면 레이나 스톤브랜치가 전문이지요. 레이나는 대용광로 남쪽에 있는 아이언포지 치료소에서 식물을 돌보고 있답니다.', '약초니 씨앗이니 하는 것들 말씀입니까? 그런 거라면 레이나 스톤브랜치가 전문이지요. 레이나는 대용광로 남쪽에 있는 아이언포지 치료소에서 식물을 돌보고 있답니다.', '할미꽃 다듬는 법을 배우고 싶은 건가요? 하하! 농담입니다.\r\n\r\n약초 채집 기술은 참 쓸모가 많지요. 레이나 스톤브랜치가 잘 가르쳐줄 겁니다. 지금 대용광로 남쪽에 있는 아이언포지 치료소에서 일하고 있을 겁니다.', '할미꽃 다듬는 법을 배우고 싶은 건가요? 하하! 농담입니다.\r\n\r\n약초 채집 기술은 참 쓸모가 많지요. 레이나 스톤브랜치가 잘 가르쳐줄 겁니다. 지금 대용광로 남쪽에 있는 아이언포지 치료소에서 일하고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2802, 'koKR', '핌블 파인스핀들이 대용광로 북서쪽에 가게를 차렸습니다. 그 친구라면 가죽으로 제법 쓸만한 방어구를 만드는 방법을 알려줄 겁니다.', '핌블 파인스핀들이 대용광로 북서쪽에 가게를 차렸습니다. 그 친구라면 가죽으로 제법 쓸만한 방어구를 만드는 방법을 알려줄 겁니다.', '아이언포지까지 왔는데 정말로 대장장이가 되고 싶지 않으세요? 뭐, 가죽 세공술로 마음을 굳히셨다면야 대용광로 북서쪽에 있는 파인스핀들의 가죽 상점으로 가서 핌블과 얘기해보는 게 제일 좋지요.', '아이언포지까지 왔는데 정말로 대장장이가 되고 싶지 않으세요? 뭐, 가죽 세공술로 마음을 굳히셨다면야 대용광로 북서쪽에 있는 파인스핀들의 가죽 상점으로 가서 핌블과 얘기해보는 게 제일 좋지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2804, 'koKR', '이곳에 상급 광부가 있느냐고요? 당연하죠! 여기는 위대한 드워프들의 도시, 아이언포지란 말입니다.\n\n대용광로 북쪽에 있는 깊은산속 광부조합과 보석세공점에 가면 던 모로에서 으뜸가는 광부들이 있습니다. 그중에서도 지오프람 볼더토라면 진정한 채광 기술이 무엇인지 가르쳐줄 겁니다.', '이곳에 상급 광부가 있느냐고요? 당연하죠! 여기는 위대한 드워프들의 도시, 아이언포지란 말이에요.\n\n대용광로 북쪽에 있는 깊은산속 광부조합과 보석세공점에 가면 던 모로에서 으뜸가는 광부들이 있어요. 그중에서도 지오프람 볼더토라면 진정한 채광 기술이 무엇인지 가르쳐줄 거예요.', '아! 채광을 배우실 거라면 아주 제대로 찾아오신 겁니다, 젊은 $C 양반! 깊은산속 광부조합에 그 유명한 지오프람 보울더토가 계시지요. 아제로스에서 그보다 훌륭한 스승은 찾을 수 없을 겁니다.', '아! 채광을 배우실 거라면 아주 제대로 찾아오신 겁니다, 젊은 $C 양반! 깊은산속 광부조합에 그 유명한 지오프람 보울더토가 계시지요. 아제로스에서 그보다 훌륭한 스승은 찾을 수 없을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2805, 'koKR', '무두질을 배우고 싶은 거라면 발투스 스톤플레이어를 찾아가십시오. 가죽을 깔끔하게 벗겨내는 방법이라면 그 친구가 잘 가르쳐줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가면 됩니다.', '무두질을 배우고 싶은 거라면 발투스 스톤플레이어를 찾아가십시오. 가죽을 깔끔하게 벗겨내는 방법이라면 그 친구가 잘 가르쳐줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가면 됩니다.', '무두질이라고요? 당신이 무두질을 할 수 있는 데라고는 자기 무릎뿐일 것 같은데요? 하하! 농담입니다. 발투스 스톤플레이어를 찾으세요. 짐승의 가죽을 제대로 벗기는 법을 가르쳐 줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가보십시오.', '무두질이라고요? 당신이 무두질을 할 수 있는 데라고는 자기 무릎뿐일 것 같은데요? 하하! 농담입니다. 발투스 스톤플레이어를 찾으세요. 짐승의 가죽을 제대로 벗기는 법을 가르쳐 줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2807, 'koKR', '요르문트 스톤브라우라는 친구가 실과 바늘을 다루는 요령을 잘 알고 있지요. 재봉술을 배우고 싶다면 대용광로 북쪽에 있는 스톤브라우의 의류점으로 가보십시오.', '요르문트 스톤브라우라는 친구가 실과 바늘을 다루는 요령을 잘 알고 있지요. 재봉술을 배우고 싶다면 대용광로 북쪽에 있는 스톤브라우의 의류점으로 가보십시오.', '이미 알고 계실지 모르지만, 요르문트는 솜씨 아주 좋은 재봉사일 뿐 아니라 거인 퇴치에도 일가견이 있습니다! 그가 거인 일곱을 한 방에 처치했다며 환호성을 지르는 걸 우리 중 몇몇이 들었으니까요!\r\n\r\n대용광로 북쪽에 있는 그의 의류점에 찾아가 그 굉장한 무용담을 한번 들려 달라고 청해 보십시오!', '이미 알고 계실지 모르지만, 요르문트는 솜씨 아주 좋은 재봉사일 뿐 아니라 거인 퇴치에도 일가견이 있습니다! 그가 거인 일곱을 한 방에 처치했다며 환호성을 지르는 걸 우리 중 몇몇이 들었으니까요!\r\n\r\n대용광로 북쪽에 있는 그의 의류점에 찾아가 그 굉장한 무용담을 한번 들려 달라고 청해 보십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2809, 'koKR', '지금까지 나는 고통에 시달려왔지만 이제 그 고통이 천천히 사라져가는 것 같구먼. 마치... 자유가 찾아온 듯해...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2810, 'koKR', '운고로의 수정탑들은 모두에게 수수께끼 같은 존재입니다. 이곳의 몇 안 되는 거주자에게 수정탑은 전설의 근원으로, 그 용도에 관해서는 많은 추측이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2811, 'koKR', '수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 푸른, 노란, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 푸른 수정의 양쪽으로는 노란 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2812, 'koKR', '수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 노란, 붉은, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 노란 수정의 양쪽으로는 붉은 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2813, 'koKR', '수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 붉은, 푸른, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 붉은 수정의 양쪽으로는 푸른 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2816, 'koKR', '안녕하시오, $c. 어떤 이들에게 사냥은 삶의 방식이고 직업이지만, 다른 이들에게는 취미나 용맹의 증거가 되기도 하고, 또 부족에 따라서는 통과의례가 되기도 하지.$B$B내게 종족이나 직업 따위는 아무런 의미가 없소. 그대의 영혼과 정신을 시험하는 수단일 뿐... 자연의 힘에 맞서 모든 능력을 시험해보는 것이 진정한 명예의 징표라오.$B$B자신을 시험해보고 나의 존경을 얻고 싶거든 언제든지 날 찾아오시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2817, 'koKR', NULL, '전 J.D.라고 해요. 어떻게 이곳에 오게 됐는가는 자세히 말 못하겠지만 이제 이 야영지가 제 집이라는 것만은 확실해요!$B$B전 분화구 주변에 널려 있는 신기한 수정들을 조사하면서 지낸답니다. 이곳으로 오는 길에 분명 뭔가를 본 듯하신데요. 대체 뭘 보신 건가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2818, 'koKR', '이제 혼자서도 요새로 돌아갈 수 있소. 당신이 시간을 벌어 주었으니 여기서 몰래 빠져나갈 수 있을 거요. 뉘신지는 잘 모르겠지만 어쨌든 고맙소이다. 언제나 엘룬의 축복이 함께하기를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2819, 'koKR', '불타는 평원 - 일곱 현자의 서판', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2820, 'koKR', '서판의 기호를 조심스럽게 사본에 옮겨 새깁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2821, 'koKR', '이제 그대는 명예로운 길을 걷기 시작한 것이오. 내 선조들은 그대의 의지에 존경을 보내고 있소. 하지만 나의 인정을 받기 위해서는 내가 주는 임무를 모두 완수해야 하오.$B$B그대가 진정한 사냥꾼임을 입증해 보이려면 무엇을 해야 하는지는 알고 있을 거라 생각하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2822, 'koKR', '어서 오게. 우리 으스러진 손에서는 자네를 환영하는 바이네.$B$B그리 놀란 표정 지을 것 없네, $n. 세상 모든 곳에는 음지가 필요하지. 이곳 오그리마에도 그림자는 있네. 어두운 곳에 숨겨져 있는 무언가가... 우리 으스러진 손이 그 역할을 맡은 것뿐이야. 스랄 님도 오크와 트롤의 안전을 위해서는 으스러진 손이 꼭 필요하다는 것을 인정하고 있네.$B$B지금은... 그 일에 대해 의논하러 온 게 아니라 다른 일 때문에 온 거겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2823, 'koKR', '운고로 분화구는 타나리스의 버섯구름 봉우리 너머 칼림도어 남쪽 멀리 있네. 가거든 둥둥 떠 있는 커다란 바위를 찾게나. 그 바위가 분화구로 들어가는 입구니까 말이야. 하지만 조심하게... 결코 쉬운 길은 아니라네. 입구에서 그리 멀지 않은 곳에 랩터들이 살고 있을 게야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2833, 'koKR', NULL, '당신 덕에 신비한 수정탑과 수정의 수수께끼를 풀 수 있게 됐어요, $n. 언제라도 정보가 더 필요하시면 날 다시 찾아오세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2834, 'koKR', NULL, '동쪽 수정탑에는 푸른, 노란, 녹색 수정이 들어가지요.$B$B동쪽 수정탑의 주된 마력 원천은 푸른 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 정신력이 높아지는 것이고 다른 하나는 상대에게 피해를 주는 방어막이 생성되는 것이에요.$B$B정신력의 수정에는 푸른 수정과 녹색 수정이 필요해요. 이 경우 정신력을 높일 수 있어요.$B$B그리고 돌기의 수정에는 푸른 수정과 노란 수정이 필요해요. 이 수정은 공격하는 자에게 피해', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2835, 'koKR', '이 운고로 분화구에 서식하는 라바사우루스는 불모의 땅에 서식하는 랩터와 분명히 어떤 관련이 있는 듯하오. 아주 지능이 높고 포악할 뿐 아니라 행동 지침 같은 것도 있소. 지금까지 내 눈으로 본 중에서 라르코르위라는 녀석이 가장 거대한데 그 어떤 짐승보다 위험한 녀석이오... 타우렌어로 라르코르위란 \'뾰족한 발톱\'이란 뜻인데, 그 말만으로는 녀석을 제대로 설명할 수 없지.$B$B라르코르위를 사냥할 생각이라면 녀석을 과소평가하지 마시오. 그리고 내가 힘닿는', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2836, 'koKR', NULL, '북쪽 수정탑에는 노란, 붉은, 녹색 수정이 들어가지요.$B$B북쪽 수정탑의 주된 마력 원천은 노란 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 상대에게 피해를 주는 것이고, 다른 것은 상대에게 입은 피해를 무효로 하는 것이지요.$B$B발화의 수정에는 붉은 수정과 노란 수정이 필요해요. 이 경우 적진 한가운데서 큰 폭발을 일으킬 수 있어요.$B$B그리고 회복의 수정에는 노란 수정과 녹색 수정이 필요해요. 이 경우에는 생', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2837, 'koKR', NULL, '서쪽 수정탑에는 붉은, 녹색, 푸른 수정이 들어가지요.$B$B서쪽 수정탑의 주된 마력 원천은 붉은 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 방어력이 높아지는 것이고, 다른 하나는 적의 방어력이 약해지는 것이지요.$B$B수호의 수정에는 붉은 수정과 녹색 수정이 필요해요. 이 경우 방어도를 높일 수 있어요.$B$B그리고 굴복의 수정에는 푸른 수정과 붉은 수정이 필요해요. 이 경우에는 적의 방어도를 약하게 할 수 있지요', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2838, 'koKR', NULL, '새로 하나 드리지요. 여기 받으세요, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2842, 'koKR', NULL, '한 때는 아름다웠던 이 숲이 끔찍한 저주에 걸려 고통받고 있어요! 타락한 세력이 이곳 생명체들을 변형시키고 있답니다. 자신들의 모습을 닮은 어두운 그림자로 만들려는 것 같아요. 당신이 이 타락의 앞잡이가 아니라면 저를 도와 악령숲을 정화할 수 있을지도 모르겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2843, 'koKR', NULL, '\"타우렌어?\"$B$B타우렌 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수는 없는 게 분명합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 남쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 언어가 통하는 드루이드가 있다는 뜻일까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2844, 'koKR', NULL, '한 때는 아름다웠던 이 숲이 끔찍한 저주에 걸려 고통받고 있어요! 타락한 세력이 이곳 생명체들을 변형시키고 있답니다. 자신들의 모습을 닮은 어두운 그림자로 만들려는 것 같아요. 당신이 이 타락의 앞잡이가 아니라면 저를 도와 악령숲을 정화할 수 있을지도 모르겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2845, 'koKR', NULL, '\"다르나서스어?\"$B$B나이트 엘프 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수 없다는 것이 명백합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 북쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 얘기를 나눌 수 있는 드루이드가 있다고 얘기하는 것일까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2846, 'koKR', '살려주시오!!!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2847, 'koKR', '크레스트가 보낸 거요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2848, 'koKR', NULL, '악령숲에는 세나리온 식물 고약을 바르면 오염된 성분을 정화할 수 있는 식물들이 있습니다. 나는 몇 가지 재료를 이용해 그 고약을 만드는 방법을 알고 있습니다. 당신이 갖고 있는 기술에 따라, 여러 가지 방법으로 날 도와줄 수 있습니다.$B$B그 일을 하려면 세나리온 등불이 필요할 거요. 그 등불을 이용하면 육안으로는 놓치기 쉬운 자연의 타락과 오염을 볼 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2849, 'koKR', NULL, '악령숲에는 세나리온 식물 고약을 바르면 오염된 성분을 정화할 수 있는 식물들이 있습니다. 나는 몇 가지 재료를 이용해 그 고약을 만드는 방법을 알고 있습니다. 당신이 갖고 있는 기술에 따라, 여러 가지 방법으로 날 도와줄 수 있습니다.$B$B그 일을 하려면 세나리온 등불이 필요할 거요. 그 등불을 이용하면 육안으로는 놓치기 쉬운 자연의 타락과 오염을 볼 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2850, 'koKR', '유해가 온통 파리와 구더기로 뒤덮여 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2873, 'koKR', '이 큰 제단은 오래전에 이 땅에 거주하던 나이트 엘프들이 지은 것입니다.$B$B이 사원에는 어떤 비밀이 숨겨져 있을지 아직은 알 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2933, 'koKR', '운고로 분화구의 수정탑에 숨겨진 비밀을 발견했습니다. 언제든지 수정탑에 가서 수정탑의 힘을 얻고 유용한 자원을 얻을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2953, 'koKR', '이 노래꽃은 타락으로 뒤덮인 악령의 숲에서 바다 한가운데 솟은 바위처럼 홀로 건강하게 자라고 있습니다. 꽃잎의 강한 향기는 기운을 북돋우고 결의를 굳게 해 줍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2954, 'koKR', '타나리스에 온 걸 환영한다고. 그래, 오늘은 무슨 일을 도와주면 되지? 그런데 당신 말이야, 대장장이처럼 보이지는 않는데? 하기야 겉모습이란 건 믿을 게 못 되는 법이니까 뭐...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2955, 'koKR', '이 바람꽃은 어둠에 잠긴 악령의 숲에서 한 줄기 빛처럼 건강하게 자라고 있습니다. 통통하고 즙 많은 열매가 가지마다 주렁주렁 열려 있어 금방이라도 따 먹을 수 있겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2956, 'koKR', '이 건강한 채찍뿌리는 악령의 숲을 뒤덮은 병든 타락과는 정반대의 모습입니다. 부드럽고 튼튼한 뿌리에서 맛좋은 덩이줄기가 자라나 식물 옆 땅에 놓여 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2957, 'koKR', '이 생기 넘치는 어둠용은 악령의 숲을 갈라놓은 악마의 타락과 선명한 대비를 이룹니다. \'어둠용의 숨결\'이라 불리는 희귀하고 탐스러운 열매가 무겁게 매달려 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2973, 'koKR', '나는 그다지 대화를 즐기는 편이 아닙니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2981, 'koKR', '반갑네, $C. 오랜 세월 동안 부족에 자신의 가치를 증명하고 싶어 안달 난 젊은 타우렌을 많이 보아 왔지. 하지만 열정만으로 지혜와 경험을 대신할 수는 없다는 걸 잊지 말게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2993, 'koKR', '열한 분의 스승님들께서 쓰신 고서를 잃어버렸소. 쿠엘탈라스에 스컬지가 침략했을 때 전 세계로 흩어져버린 게지.$B$B지금 우리는 그 고서를 찾고 있소. 그 고서에 담긴 비밀을 찾아내 한때 우리가 지녔던 힘을 되찾고자 하는 것이오.$B$B난 카리엘 윈탈루스 스승님께서 쓰신 10권을 찾고 있소. 고서 하나를 찾아 가지고 오면 그 고서의 마법을 흡수해 강력한 마력을 지닌 결정체를 만들어 주겠소. 물론 모든 일에는 대가가 따르게 마련이지. 비싼 값일 테지만 그', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2994, 'koKR', '아, 그래... 찾았군.$B$B<마트레디스가 당신이 가진 책을 가리킵니다.>$B$B필요한 재료는 다 모았나?$B$B성서에 적힌 재료 말이다, 이 멍청아!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2995, 'koKR', '<고서를 뚫어지게 바라는 마스레디스>$B$B결정체 때문에 온 거요? 고서에 적힌 대로 했소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2996, 'koKR', '물건들을 가져오면 결정체를 만들어 주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2997, 'koKR', '아주 희귀한 걸 찾았군.$B$B<고개를 끄덕이는 마스레디스>$B$B계속하고 싶거든 재료를 더 가지고 오시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2998, 'koKR', '욕심이 널 다시 내게로 이끌었군.$B$B<마트레디스가 웃습니다.>$B$B언젠가 현명한 드레나이가 내게 그러더군. 욕심이야말로 이 세상의 모든 종족이 공통으로 지닌 단 하나의 성질이라고. 나도 동의하지.$B$B성서에 적힌 재료는 다 모았나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2999, 'koKR', '성스러운 빛의 가호가 함께하길.', '성스러운 빛의 가호가 함께하길.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3001, 'koKR', '라제에게 뭘 원하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3014, 'koKR', '경매장 말입니까? 아이언포지 성문 근처에 있습니다. 아이언포지 사설금고 바로 맞은 편이랍니다.', '경매장 말입니까? 아이언포지 성문 근처에 있습니다. 아이언포지 사설금고 바로 맞은 편이랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3016, 'koKR', '다르나서스에는 정말로 멋진 곳이 많이 있답니다. 어디로 가시기를 원하십니까?', '다르나서스에는 정말로 멋진 곳이 많이 있답니다. 어디로 가시기를 원하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3017, 'koKR', '여행을 하시다가 얻은 귀중한 물건이나 돈을 보관할 곳을 찾으시는군요. 이 멋진 도시 중앙에 다르나서스 은행이 있으니 그곳으로 가 보시기 바랍니다.', '여행을 하시다가 얻은 귀중한 물건이나 돈을 보관할 곳을 찾으시는군요. 이 멋진 도시 중앙에 다르나서스 은행이 있으니 그곳으로 가 보시기 바랍니다.', '속세에 찌들어 물질을 추구하는 젊은 $C|1이;가; 하나 또 오셨군요. 뭐, 가지고 있는 귀중품이 그렇게 걱정된다면 도시 중심부에 있는 다르나서스 은행에 보관해 두시는 게 좋을 겁니다.', '속세에 찌들어 물질을 추구하는 젊은 $C|1이;가; 하나 또 오셨군요. 뭐, 가지고 있는 귀중품이 그렇게 걱정된다면 도시 중심부에 있는 다르나서스 은행에 보관해 두시는 게 좋을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3018, 'koKR', '베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 수 있습니다. 다르나서스 서쪽에 있는 문을 지나면 루테란 마을이 있는데 그곳에서 베스프리스투스를 찾아보십시오.', '베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 수 있습니다. 다르나서스 서쪽에 있는 문을 지나면 루테란 마을이 있는데 그곳에서 베스프리스투스를 찾아보십시오.', '베스프리스투스를 찾으시는군요. 그는 텔드랏실 숲 속과 이곳을 오가며 히포그리프를 보살피는데, 다르나서스 서부에서 루테란 마을로 통하는 문을 지나면 찾을 수 있을 겁니다.', '베스프리스투스를 찾으시는군요. 그는 텔드랏실 숲 속과 이곳을 오가며 히포그리프를 보살피는데, 다르나서스 서부에서 루테란 마을로 통하는 문을 지나면 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3019, 'koKR', '길드를 만들고자 하신다면 길드 사무관, 리셰아나를 만나셔야 합니다. 다르나서스 북동쪽에 있는 장인의 정원에 가면 그녀를 만나실 수 있을 겁니다.', '길드를 만들고자 하신다면 길드 사무관, 리셰아나를 만나셔야 합니다. 다르나서스 북동쪽에 있는 장인의 정원에 가면 그녀를 만나실 수 있을 겁니다.', '리셰아나라면 까다로운 길드 창설 서류를 올바르게 지도해 줄 겁니다. 다르나서스 북동부에 있는 장인의 정원에 있으니 그곳으로 가보십시오. 그대와 그대의 동료가 나이트 엘프에게 영광을 가져오기를!', '리셰아나라면 까다로운 길드 창설 서류를 올바르게 지도해 줄 겁니다. 다르나서스 북동부에 있는 장인의 정원에 있으니 그곳으로 가보십시오. 그대와 그대의 동료가 나이트 엘프에게 영광을 가져오기를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3020, 'koKR', '텔드랏실을 뒤덮고 있는 촉촉한 풀밭도 아주 훌륭한 침대가 될 수 있겠지만 좀 더 편안한 잠자리를 원한다면 장인의 정원에 있는 다르나서스 여관 침대가 제격일 것입니다. 가서 셀리에네를 찾으십시오.', '텔드랏실을 뒤덮고 있는 촉촉한 풀밭도 아주 훌륭한 침대가 될 수 있겠지만 좀 더 편안한 잠자리를 원한다면 장인의 정원에 있는 다르나서스 여관 침대가 제격일 것입니다. 가서 셀리에네를 찾으십시오.', '벌써 해가 떴나요? 밤은 너무 짧아요! 흠, 다르나서스 북동부에 있는 장인의 정원으로 가 보십시오. 셀리에네가 투숙객들을 보살피고 있을 겁니다. 분명 그대도 잘 돌봐 줄 거예요.', '벌써 해가 떴나요? 밤은 너무 짧아요! 흠, 다르나서스 북동부에 있는 장인의 정원으로 가 보십시오. 셀리에네가 투숙객들을 보살피고 있을 겁니다. 분명 그대도 잘 돌봐 줄 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3021, 'koKR', '다르나서스의 중앙 부근에 있는 은행 바깥쪽에 우체통이 있습니다.', '다르나서스의 중앙 부근에 있는 은행 바깥쪽에 우체통이 있습니다.', '우체통이요? 보낼 편지가 있거나 받을 편지가 있습니까? 뭔가 좋은 소식이었으면 좋겠군요! 다르나서스의 중앙에 은행 바로 밖에 우체통이 있습니다.', '우체통이요? 보낼 편지가 있거나 받을 편지가 있습니까? 뭔가 좋은 소식이었으면 좋겠군요! 다르나서스의 중앙에 은행 바로 밖에 우체통이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3022, 'koKR', '이곳 다르나서스에는 오랜 세월 동안 자신이 선택한 직업의 기술을 갈고 닦은 다양한 상급자들이 있답니다. 그대의 지도자가 될 분에게 가는 길을 가르쳐드리겠습니다.', '이곳 다르나서스에는 오랜 세월 동안 자신이 선택한 직업의 기술을 갈고 닦은 다양한 상급자들이 있답니다. 그대의 지도자가 될 분에게 가는 길을 가르쳐드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3023, 'koKR', '아, 조카스테처럼 훌륭한 사냥꾼이 있는 다르나서스로 오셔서 다행이군요. 그녀는 세나리온 자치령에 있으니 찾아가서 사냥꾼의 기술을 배우시기 바랍니다.', '아, 조카스테처럼 훌륭한 사냥꾼이 있는 다르나서스로 오셔서 다행이군요. 그녀는 세나리온 자치령에 있으니 찾아가서 사냥꾼의 기술을 배우시기 바랍니다.', '조카스테는 전성기에 동부 왕국에서 가장 뛰어난 사냥꾼이었습니다. 요즘에는 세나리온 자치령에서 사냥꾼의 길을 걷기 시작한 새내기들을 가르치고 있지요.', '조카스테는 전성기에 동부 왕국에서 가장 뛰어난 사냥꾼이었습니다. 요즘에는 세나리온 자치령에서 사냥꾼의 길을 걷기 시작한 새내기들을 가르치고 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3024, 'koKR', '드루이드는 이 세계의 자연을 보호하는 데 있어 결코 경계를 늦추지 않습니다. 세나리온 자치령에 사는 대드루이드 판드랄 스태그헬름이 이끌고 있으니 찾아가 조언을 구하시기 바랍니다. 다르나서스 북부에서 판드랄과 다른 상급 드루이드를 찾을 수 있습니다.', '드루이드는 이 세계의 자연을 보호하는 데 있어 결코 경계를 늦추지 않습니다. 세나리온 자치령에 사는 대드루이드 판드랄 스태그헬름이 이끌고 있으니 찾아가 조언을 구하시기 바랍니다. 다르나서스 북부에서 판드랄과 다른 상급 드루이드를 찾을 수 있습니다.', '지금과 같이 힘든 시기에 드루이드는 주위 동료에게 아주 절친한 친구가 되어줄 수 있답니다. 세나리온 자치령에 있는 어느 드루이드에게 물어도 같은 대답을 할 겁니다.', '지금과 같이 힘든 시기에 드루이드는 주위 동료에게 아주 절친한 친구가 되어줄 수 있답니다. 세나리온 자치령에 있는 어느 드루이드에게 물어도 같은 대답을 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3025, 'koKR', '달의 신전은 엘룬의 사제들에게 집과 같은 곳입니다. 그곳으로 가시면 잔드리아와 라리아가 사제의 길에 대해 자세히 안내해줄 것입니다.', '달의 신전은 엘룬의 사제들에게 집과 같은 곳입니다. 그곳으로 가시면 잔드리아와 라리아가 사제의 길에 대해 자세히 안내해줄 것입니다.', '엘룬께서 끝없는 능력으로 그대를 인도하기를!\r\n\r\n어서 가십시오. 다르나서스 남부에 있는 달의 신전 중앙 전당에서 잔드리아가 기다리고 있습니다.', '엘룬께서 끝없는 능력으로 그대를 인도하기를!\r\n\r\n어서 가십시오. 다르나서스 남부에 있는 달의 신전 중앙 전당에서 잔드리아가 기다리고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3026, 'koKR', '도적의 길을 걷겠다면 시우르나를 찾아가십시오. 그녀는 세나리온 자치령 서쪽 끝에 있는 나무 안의 소용돌이 모양의 길에서 기거하고 있습니다.', '도적의 길을 걷겠다면 시우르나를 찾아가십시오. 그녀는 세나리온 자치령 서쪽 끝에 있는 나무 안의 소용돌이 모양의 길에서 기거하고 있습니다.', '어둠을 사랑하여 도적의 길을 가려는 자들도 있지만, 진정으로 밤의 품에 안길 수 있는 건 우리 나이트 엘프뿐이랍니다. 그늘진 길을 걸어나가실 생각이시라면 세나리온 자치령에 있는 시우르나를 찾아가십시오.', '어둠을 사랑하여 도적의 길을 가려는 자들도 있지만, 진정으로 밤의 품에 안길 수 있는 건 우리 나이트 엘프뿐이랍니다. 그늘진 길을 걸어나가실 생각이시라면 세나리온 자치령에 있는 시우르나를 찾아가십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3033, 'koKR', '전사의 정원을 지키고 있는 파수꾼들 사이에서 실단나이르를 찾으십시오. 그녀는 혹시라도 적이 도시로 침입할 때를 대비해 텔드랏실의 숲 속을 감시하고 있습니다.', '전사의 정원을 지키고 있는 파수꾼들 사이에서 실단나이르를 찾으십시오. 그녀는 혹시라도 적이 도시로 침입할 때를 대비해 텔드랏실의 숲 속을 감시하고 있습니다.', '우리의 소중한 도시를 지키는 용맹한 파수꾼들은 대다수가 실단나이르로부터 훈련을 받았습니다. 그녀라면 틀림없이 그대를 전사로 키워줄 수 있을 테니, 도시의 입구 부근에 있는 전사의 정원에서 그녀를 찾아보시기 바랍니다.', '우리의 소중한 도시를 지키는 용맹한 파수꾼들은 대다수가 실단나이르로부터 훈련을 받았습니다. 그녀라면 틀림없이 그대를 전사로 키워줄 수 있을 테니, 도시의 입구 부근에 있는 전사의 정원에서 그녀를 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3034, 'koKR', '다르나서스의 장인들에게는 그대에게 도움이 될 만한 지식이 수천 가지는 있을 겁니다. 자, 말씀해 보십시오. 어떤 기술을 익히고 싶으세요?', '다르나서스의 장인들에게는 그대에게 도움이 될 만한 지식이 수천 가지는 있을 겁니다. 자, 말씀해 보십시오. 어떤 기술을 익히고 싶으세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3035, 'koKR', '진정 연금술을 배우고자 하신다면 다르나서스 북쪽, 장인의 정원으로 가서 뛰어난 실력을 지닌 에이네실이라는 연금술사를 찾으십시오.', '진정 연금술을 배우고자 하신다면 다르나서스 북쪽, 장인의 정원으로 가서 뛰어난 실력을 지닌 에이네실이라는 연금술사를 찾으십시오.', '연금술사를 찾으십니까? 제대로 오셨군요. 에이네실은 끝없는 노력을 기울인 끝에 장인의 정원에서 가장 뛰어난 연금술사가 되었답니다. 저라면 당장 찾아가 보겠습니다. 지금! 어서 가보십시오!', '연금술사를 찾으십니까? 제대로 오셨군요. 에이네실은 끝없는 노력을 기울인 끝에 장인의 정원에서 가장 뛰어난 연금술사가 되었답니다. 저라면 당장 찾아가 보겠습니다. 지금! 어서 가보십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3036, 'koKR', '알레고른은 수백 년 동안 요리 기술을 갈고 닦았지요. 그런 노련한 요리사에게 기술을 배울 수 있다면 정말 축복이라 여기십시오. 만약 그대에게 그럴 자격이 충분하다고 생각하거든 장인의 정원으로 찾아가 보십시오.', '알레고른은 수백 년 동안 요리 기술을 갈고 닦았지요. 그런 노련한 요리사에게 기술을 배울 수 있다면 정말 축복이라 여기십시오. 만약 그대에게 그럴 자격이 충분하다고 생각하거든 장인의 정원으로 찾아가 보십시오.', '알레고른이 뚝딱 만들어 내는 음식은 정말 맛이 끝내 주지요. 그는 장인의 정원에서 새로운 별미를 만드느라 여념이 없습니다. 그곳에 세나리온 무침 요리 남은 게 있거든 꼭 한번 드셔 보세요.$b$b자, 그럼 저는 이만 실례하겠습니다. 요새 부쩍 늘고 있는 사슴 실종 사건을 조사해야 하거든요.', '알레고른이 뚝딱 만들어 내는 음식은 정말 맛이 끝내 주지요. 그는 장인의 정원에서 새로운 별미를 만드느라 여념이 없습니다. 그곳에 세나리온 무침 요리 남은 게 있거든 꼭 한번 드셔 보세요.$b$b자, 그럼 저는 이만 실례하겠습니다. 요새 부쩍 늘고 있는 사슴 실종 사건을 조사해야 하거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3037, 'koKR', '상처를 치유해 줄 자가 곁에 없을 때, 응급치료법을 알고 있으면 목숨을 구할 수 있지요. 장인의 정원에 있는 단넬로르에게서 배워 보시죠.', '상처를 치유해 줄 자가 곁에 없을 때, 응급치료법을 알고 있으면 목숨을 구할 수 있지요. 장인의 정원에 있는 단넬로르에게서 배워 보시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3038, 'koKR', '오랜 시간이 걸리지만 그만한 보람이 있는 일이지요. 상인의 정원에 있는 아스타이아와 얘기를 나눠 보시면 뭔가 쓸 만한 걸 배울 수 있을 겁니다.', '오랜 시간이 걸리지만 그만한 보람이 있는 일이지요. 상인의 정원에 있는 아스타이아와 얘기를 나눠 보시면 뭔가 쓸 만한 걸 배울 수 있을 겁니다.', '아스타이아는 오랜 세월 동안 낚시를 하면서 희한한 보물들도 많이 낚아 올렸답니다. 상인의 정원으로 가세요. 그 보물 몇 개만 한번 보여 달라고 청해 보십시오.', '아스타이아는 오랜 세월 동안 낚시를 하면서 희한한 보물들도 많이 낚아 올렸답니다. 상인의 정원으로 가세요. 그 보물 몇 개만 한번 보여 달라고 청해 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3039, 'koKR', '약초채집에 대한 지식과 기술이라면 피로드렌 문콜러가 전문입니다. 다르나서스 남서부에 있는 신전 정원으로 가보십시오.', '약초채집에 대한 지식과 기술이라면 피로드렌 문콜러가 전문입니다. 다르나서스 남서부에 있는 신전 정원으로 가보십시오.', '그대는 약초채집가 지망생이시로군요? 그렇다면 신전 정원으로 가서 피로드렌 문콜러를 만나 보십시오. 몇 가지 요령을 가르쳐 줄 겁니다.', '그대는 약초채집가 지망생이시로군요? 그렇다면 신전 정원으로 가서 피로드렌 문콜러를 만나 보십시오. 몇 가지 요령을 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3040, 'koKR', '텔로니스만큼 가죽을 다루는 솜씨가 뛰어난 자가 이 동부 왕국에 있기나 할까요?! 그만한 수업료로 기술을 전수받을 수 있다는 걸 감사히 여겨야 합니다. 지금 다르나서스 북동부에 있는 장인의 정원으로 가서 그를 찾아보십시오. 쓸만한 가죽 방어구를 만들 수 있을 거예요.', '텔로니스만큼 가죽을 다루는 솜씨가 뛰어난 자가 이 동부 왕국에 있기나 할까요?! 그만한 수업료로 기술을 전수받을 수 있다는 걸 감사히 여겨야 합니다. 지금 다르나서스 북동부에 있는 장인의 정원으로 가서 그를 찾아보십시오. 쓸만한 가죽 방어구를 만들 수 있을 거예요.', '우리는 채소를 심고, 토끼가 그 채소를 먹고, 늑대가 토끼를 잡아먹고, 우리 손에 늑대는 죽고, 늑대는 우리에게 고기와 모피를 줍니다. 이런 걸 두고 생명의 마법진이라고 부르지요, 아마?\r\n\r\n세나리온 자치령에 있는 텔로니스를 찾아가 보시지요. 저는 제 일을 봐야 하니까요.', '우리는 채소를 심고, 토끼가 그 채소를 먹고, 늑대가 토끼를 잡아먹고, 우리 손에 늑대는 죽고, 늑대는 우리에게 고기와 모피를 줍니다. 이런 걸 두고 생명의 마법진이라고 부르지요, 아마?\r\n\r\n세나리온 자치령에 있는 텔로니스를 찾아가 보시지요. 저는 제 일을 봐야 하니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3042, 'koKR', '이 세계의 동물들은 숭고한 죽음으로 우리에게 생명을 주고, 보호해주기도 합니다. 가슴 속으로 그들의 희생에 경의를 표할 수 있다면, 그대는 무두질을 배울 자격이 있는 겁니다. 더 자세한 것을 알고 싶으시면 다르나서스 북부, 장인의 정원에 있는 엘라드리엘과 얘기를 나눠 보십시오.', '이 세계의 동물들은 숭고한 죽음으로 우리에게 생명을 주고, 보호해주기도 합니다. 가슴 속으로 그들의 희생에 경의를 표할 수 있다면, 그대는 무두질을 배울 자격이 있는 겁니다. 더 자세한 것을 알고 싶으시면 다르나서스 북부, 장인의 정원에 있는 엘라드리엘과 얘기를 나눠 보십시오.', '우리 나이트 엘프의 문화에서는 무엇이든 쓸데없이 낭비하지 않습니다. 부득이 살생을 할 수밖에 없는 경우에도 그 죽음이 헛되지 않도록 희생된 생물에서 가능한 한 많은 것을 취하지요.$b$b짐승의 가죽을 제대로 벗기는 방법을 배우고 싶다면 장인의 정원에 있는 엘라드리엘을 찾아가 보십시오.', '우리 나이트 엘프의 문화에서는 무엇이든 쓸데없이 낭비하지 않습니다. 부득이 살생을 할 수밖에 없는 경우에도 그 죽음이 헛되지 않도록 희생된 생물에서 가능한 한 많은 것을 취하지요.$b$b짐승의 가죽을 제대로 벗기는 방법을 배우고 싶다면 장인의 정원에 있는 엘라드리엘을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3044, 'koKR', '재봉사가 되어 보시겠다면 꼭 메린을 찾아가 보십시오. 다르나서스 북동부에 있는 장인의 정원에 살고 있습니다.', '재봉사가 되어 보시겠다면 꼭 메린을 찾아가 보십시오. 다르나서스 북동부에 있는 장인의 정원에 살고 있습니다.', '메린이 만들어 내는 옷을 바라보면 마치 엘룬께서 그녀의 바늘에 축복을 내리신 듯하답니다. 그대에게 그런 축복받은 재능이 있지 않은 이상, 메린을 찾아가 가르침을 구하는 것이 좋을 겁니다. 다르나서스 북동부에 있는 장인의 정원에서 그녀를 만날 수 있습니다.', '메린이 만들어 내는 옷을 바라보면 마치 엘룬께서 그녀의 바늘에 축복을 내리신 듯하답니다. 그대에게 그런 축복받은 재능이 있지 않은 이상, 메린을 찾아가 가르침을 구하는 것이 좋을 겁니다. 다르나서스 북동부에 있는 장인의 정원에서 그녀를 만날 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3046, 'koKR', NULL, '난 오염된 식물을 네 가지 보았습니다. 노래꽃, 바람꽃, 채찍뿌리, 그리고 어둠용풀이죠. 악령숲에서 노래꽃과 바람꽃은 쉽게 찾을 수 있지만 채찍뿌리와 어둠용풀은 그리 흔하지 않을 겁니다. 하지만 모두 악령숲 생태계에 없어서는 안 될 식물들이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3047, 'koKR', NULL, '난 오염된 식물을 네 가지 보았습니다. 노래꽃, 바람꽃, 채찍뿌리, 그리고 어둠용풀이죠. 악령숲에서 노래꽃과 바람꽃은 쉽게 찾을 수 있지만 채찍뿌리와 어둠용풀은 그리 흔하지 않을 겁니다. 하지만 모두 악령숲 생태계에 없어서는 안 될 식물들이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3048, 'koKR', '이곳은 대단한 전투의 장이었지. 정말 치열한 싸움이 여러 번 있었어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3049, 'koKR', '렉타르와 얘기해 보게. 그는 현명하니까 당신이 원하는 것을 찾는 데 도움을 줄 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3055, 'koKR', '끄응... 누구요?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3056, 'koKR', '아, 물론이네, $n! 미안, 난 또 다 본 줄 알았지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3061, 'koKR', '총이 좋습니까, 아니면 활이 더 마음에 드십니까?', '총이 좋습니까, 아니면 활이 더 마음에 드십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3073, 'koKR', NULL, '잠깐만 기다려 주세요. 지금은 나가들이 공격을 해 대고 있어서... 공격이 끝나는 대로 제가 얘기하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3074, 'koKR', '좋소. *딸꾹*... 근데, 당신 낯이 익어. *딸꾹* 나하고 윈저가 수 처... 으... 처... 수 백만이나 되는 오크를 물리친 얘기를 들려줬던가? 꺼억!$B$B좀 앉아 보시오, 친구. 아주 멋진 얘기니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3075, 'koKR', '오그리마 경매장은 힘의 골짜기에 있네. 붐스틱 수입상의 오른쪽 건물이니 한번 찾아가보게.', '오그리마 경매장은 힘의 골짜기에 있네. 붐스틱 수입상의 오른쪽 건물이니 한번 찾아가보게.', '소리를 지르느라 목이 쉬었군? 힘의 골짜기에서 오그리마 경매장을 찾아보게.', '소리를 지르느라 목이 쉬었군? 힘의 골짜기에서 오그리마 경매장을 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3076, 'koKR', '다르나서스 은행에 오신 걸 환영합니다. 저희 은행에서는 금융 계좌는 물론 각종 귀중품을 보관하기 위한 안전 금고도 제공합니다. 저희 은행에 계좌를 가지고 계십니까, 손님?', '다르나서스 은행에 오신 걸 환영합니다. 저희 은행에서는 금융 계좌는 물론 각종 귀중품을 보관하기 위한 안전 금고도 제공합니다. 저희 은행에 계좌를 가지고 계십니까, 손님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3077, 'koKR', '놀랍지 않소? 이 역사의 잔재들이...$B$B날 얼마나 더 놀라게 할지 가늠할 수 없소이다. 그 굉장한 크기? 아니면 유구한 역사? 조사할 게 너무나도 많소. 어떤 연관성이 있는지 알아내야지.$B$B그런데 혹시 여러 종족이 나이트 엘프와 같은 전통을 가지고 있다는 소문을 들어 본 적이 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3093, 'koKR', NULL, '안녕하세요? 난 페트라라고 하고 내 오른쪽은 내 코도, 다단가라고 합니다. 우린 마샬 원정대 소속이죠. 다단가가 새끼였던 이후로 벌써 몇 년이 지났군요.$B$B횃불이나 다른 화기 종류가 있다면 부디 감추어 주세요. 다단가는 연기를 싫어하거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3094, 'koKR', '제발 엎드려서 빌기라도 할 테니, 이 몹쓸 땅에서 우리를 좀 구해 주게. 비록 내가 마샬 원정대 소속이긴 하지만, 자네 배낭 안에 숨어 이곳을 뜰 수만 있다면 내 금니라도 뽑아서 주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3095, 'koKR', NULL, '어머나, 안녕하세요! 저는 마샬 원정대의 수석 과학자 겸 생물학자, 홀라니에라고 합니다. 저와 오빠는 동료와 함께 온 아제로스를 여행하며 장엄한 야생의 세계를 탐험하지요. 참 재미있는 일인데... 이번에는... 그 재미의 도가 좀 지나쳤던 모양이에요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3096, 'koKR', '안녕하십니까, 이방인 친구. 야생이 살아 숨 쉬는 운고로 분화구에 온 것을 환영합니다! 저는 윌리덴 마샬이라고 합니다. 저와 제 여동생, 그리고 동료는 마샬 원정대를 구성하고 있습니다. 우리는 위대한 아제로스의 야생과 미지의 세계를 탐험하는 과학자와 탐험가들이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3097, 'koKR', '믿을 수가 없군! 굉장해! 이게 대체 무슨 뜻인지 나도 모르겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3098, 'koKR', '이 견본들을 보시오! 이게 무슨 뜻일까? 이게 무슨 뜻일 것 같소? 시간이 필요할 거요. 이 모든 정보를 살펴 볼 시간이... 그리고 정보가 더 필요하오. 내가 얻을 수 없는 정보... 젠장! 머리를 써, 라리스! 머리를!$B$B어떻게 할 거야? 어떻게?$B$B해결책은 반드시 있을 거라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3099, 'koKR', '아제로스 어딘가에는 스컬지나 다른 것에 오염되지 않은 수액괴물이 분명 있을 거야. 그런데... 어디지?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3100, 'koKR', '그런 것 같지는 않소. 대부분 지역 특색에 따라 다른 것 같은데 어떤 종족들은 그걸 수액괴물이라고 부르고, 어떤 종족들은 진흙괴물이라고 부른다오. 대체로 취향의 문제인 것 같소.$B$B수액괴물이나 녹괴물, 진흙괴물을 접할 때마다 겉모양은 기본적으로 다 똑같은 생물들이었소. 환경에 따라 차이가 있는 것이기에 순수한 견본이 필요한 거요.', '그런 것 같지는 않소. 대부분 지역 특색에 따라 다른 것 같은데 어떤 종족들은 그걸 수액괴물이라고 부르고, 어떤 종족들은 진흙괴물이라고 부른다오. 대체로 취향의 문제인 것 같소.$B$B수액괴물이나 녹괴물, 진흙괴물을 접할 때마다 겉모양은 기본적으로 다 똑같은 생물들이었소. 환경에 따라 차이가 있는 것이기에 순수한 견본이 필요한 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3101, 'koKR', '순수한 견본이라면 어떤 영향에 의해서도 오염되지 않은 걸 말하는 거요. 가장 단순하고 정상적인 환경에서 이 생물들을 찾아야만 하오.$B$B그것은 곧 문명이 발달하지 않았거나 아제로스 주요 종족들의 영향을 받지 않은 곳을 말하는데, 어딘가... 천연 그대로의 장소라야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3102, 'koKR', '그런 곳은 동부 왕국에서는 절대 찾을 수 없소.$B$B칼림도어 어딘가에서 찾아야 하겠지만 호드를 비롯한 다른 모든 종족에게서 멀리 떨어진 곳이라야 하오. 대륙 분리의 영향도 받지 않아야 하니, 나이트 엘프 문명 근처는 아니겠지.$B$B아마 자연적으로 보호되는 곳일 거요. 골짜기라든가 분화구라든가... 음, 잘 모르겠소. 단지 내 추측일 뿐이니, 더 도움이 되지 못해서 미안하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3133, 'koKR', '왜 이 햇볕 따사로운 해안과 푸른 바다를 떠나려고 하는지 모르겠습니다. 여기는 낙원 같은 곳이라고요. 하지만 제 동생 자페타에게는 그런 말 하지 마십쇼. 티리스팔에 온종일 처박혀 있게 돼서 기분이 상당히 안 좋으니까요. 이 비행선은 다행히 오그리마에서 서니까 그 녀석의 불평불만을 들을 일은 없을 겁니다. 하지만 혹시라도 티리스팔에 가면 녀석 성질 돋우는 짓은 안 하시는 게 좋을 걸요.', '왜 이 햇볕 따사로운 해안과 푸른 바다를 떠나려고 하는지 모르겠습니다. 여기는 낙원 같은 곳이라고요. 하지만 제 동생 자페타에게는 그런 말 하지 마십쇼. 티리스팔에 온종일 처박혀 있게 돼서 기분이 상당히 안 좋으니까요. 이 비행선은 다행히 오그리마에서 서니까 그 녀석의 불평불만을 들을 일은 없을 겁니다. 하지만 혹시라도 티리스팔에 가면 녀석 성질 돋우는 짓은 안 하시는 게 좋을 걸요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3153, 'koKR', '봉우리 하층, 썬더 블러프 은행 바로 남쪽에 있는 건물에서 여관주인 팔라를 찾아보십시오.', '봉우리 하층, 썬더 블러프 은행 바로 남쪽에 있는 건물에서 여관주인 팔라를 찾아보십시오.', '여관주인 팔라가 몸과 마음, 그리고 당신의 영혼이 편히 쉴 수 있도록 해 줄 거예요. 봉우리 하층에 있는 은행 바로 남쪽에 여관이 있습니다.', '여관주인 팔라가 몸과 마음, 그리고 당신의 영혼이 편히 쉴 수 있도록 해 줄 거예요. 봉우리 하층에 있는 은행 바로 남쪽에 여관이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3154, 'koKR', '우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', '우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', '조금 전 새로운 우편물이 배달되는 것을 본 것 같습니다. 우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', '조금 전 새로운 우편물이 배달되는 것을 본 것 같습니다. 우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3155, 'koKR', '썬더 블러프 봉우리 하층에 있습니다. 은행 가까이에 있으니 한번 찾아보십시오.', '썬더 블러프 봉우리 하층에 있습니다. 은행 가까이에 있으니 한번 찾아보십시오.', '경매장은 썬더 블러프 중앙에서 찾을 수 있습니다. 와이번 조련사의 탑 맨 아래층을 찾아보십시오. 선조님의 영혼이 당신을 보살피기를.', '경매장은 썬더 블러프 중앙에서 찾을 수 있습니다. 와이번 조련사의 탑 맨 아래층을 찾아보십시오. 선조님의 영혼이 당신을 보살피기를.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3156, 'koKR', '충격적인 얘기일지 모르겠지만 요즘 들어 경기가 영 안 좋아서 말이지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3157, 'koKR', NULL, '테라모어에 온 것을 환영합니다, $n.$B$B도시를 지키는 것이 우선이라 제대로 인사할 시간도 갖지 못해 미안합니다. 우리 삶의 방식과 얼라이언스의 신성함을 위협하는 것들이 너무나도 많습니다. 내 주민들이 안전하고 행복하게 살 수 있도록 하려면 우리 지배권 밖에 있는 세력들에 대한 경계를 늦출 수 없답니다.$B$B우린 나중에 얘기를 더 나눌 기회가 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3158, 'koKR', NULL, '그대 덕분에 헨델을 잡아들일 수 있었습니다.$B$B심문은 천천히 진행되고 있지만 반드시 모든 걸 털어놓도록 할 겁니다.$B$B일단은 참고 기다려 주세요. 그대의 도움이 필요하면 즉시 연락을 드리겠습니다.$B$B그때까지는 부디 테라모어에서 편안히 지내도록 하세요. 얼라이언스의 벗으로서 우리 도시의 성벽 아래에서 집처럼 얼마든지 오래 머무르셔도 좋습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3173, 'koKR', '도시의 정문 바로 밖에 표지판이 있네. 그 표지판을 따라가면 서쪽 비행선 탑승장으로 갈 수 있을 거야.', '도시의 정문 바로 밖에 표지판이 있네. 그 표지판을 따라가면 서쪽 비행선 탑승장으로 갈 수 있을 거야.', '도시 밖, 남동쪽에 있는 비행선 탑승장을 찾아가게.', '도시 밖, 남동쪽에 있는 비행선 탑승장을 찾아가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3193, 'koKR', '우리 형제는 실바나스 여왕님에게 헌신하기로 다짐했소. 가장 힘든 시기에 그분은 한 줄기 빛과 같은 분이셨소. 우리에게 닥친 운명을 극복하기 위해, 아침 저녁으로 희생하고 있소.$B$B우리가 언제나 약하게만 머물러 있지는 않을 거요. 우리가 마땅히 받을 자격이 있는 것은 받아내고, 우리가 겪은 고통은 열 배로 되갚을 거요. 얼굴에 차디찬 미소를 머금은 채로... 반드시 그렇게 하고야 말 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3194, 'koKR', '실바나스 여왕님께서는 아제로스의 자연 현상을 조사하라고 명령을 내리셨소. 그러면 비밀스러운 과거에 대한 뭔가 엄청난 사실을 알아낼 수 있을 거라고 생각하고 계시지.$B$B여왕님께서 그런 것들을 어떻게 아시는지는 나도 잘 모르겠지만, 나는 그분을 전적으로 믿기 때문에 최선을 다할 것이오.$B$B지금은 진흙괴물, 수액괴물 같은 것들을 조사하고 있소. 이 생물들의 구조는 유사하지만 환경의 영향을 크게 받는 것 같소.$B$B이 생물들의 견본을 구하는 데 당신', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3213, 'koKR', '<볼코르에게 다가가도 볼코르는 전혀 이쪽을 보지 않습니다. 붕대가 풀리지 않도록 하는 데 집중하고 있는 것 같습니다. 잠시 후 약간 놀란 듯이 이쪽을 봅니다.>$B$B아, 미안하오. 지금은 때가 좋지 않으니 양해를 바라오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3214, 'koKR', '내 생각에 이 동굴을 빠져 나가는 방법은 두 가지뿐이오.$B$B당신이 준 망토를 내가 쓰고 당신은 알아서 자기 방어를 해 빠져 나가든가, 아니면 우리 둘이 등을 맞대고 함께 싸워 나가는 거요. 지금은 내가 다쳐서 좀 더 힘들겠지만...$B$B당신 자신의 힘은 스스로 더 잘 알 테니 당신의 판단에 맡기겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3218, 'koKR', '어서 오시오, 젊은이. 아이언포지 외곽에서 가장 괜찮은 물건을 찾고 있다면 제대로 찾아 오셨소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3233, 'koKR', NULL, '우리 호수에 있는 타락한 물의 정령들을 보셨나요? 참으로 안타까운 것이 어디서, 왜 나타나는 건지 조차 알지 못한다는 것입니다.$B$B사람들과 얘기를 나누다 그대의 이름을 접하게 되었습니다. 그대가 이 문제를 도와 줄 수 있을지도 모르겠군요.$B$B급선무는 이 타락한 정령들을 지배하는 자를 밝혀내는 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3234, 'koKR', '안녕하세요? 전 구버 블럼프라고 해요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3253, 'koKR', '...팬에 살짝 튀기고, 기름을 가득 넣고 튀기고, 휘저어 가며 튀기고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3273, 'koKR', '가까이 다가가 보니, 장비 안에 이상한 액체와 혼합물이 거품을 내며 끓고 있습니다. 장비 옆에는 수액괴물 견본을 집어넣는 데 쓸 법한 집게가 놓여 있습니다.$B$B안전 장비 비슷한 게 있는 것 같지만 먼지가 쌓여 있고 오랫동안 사용되지 않은 듯합니다.$B$B아무래도 건드리지 않는 것이 나을 것 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'koKR', '안녕하세요, $N. 임시 주둔지에 오신 걸 환영합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3294, 'koKR', '스쿼토의 말은 신경 쓰시지 않아도 됩니다. 일부러 무례하게 구는 게 아니라 굉장히 바쁜 것뿐이니까요. 스쿼토의 정찰이 끝날 때까지 우리는 좀 더 생산적인 걸 해 보도록 하죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3295, 'koKR', NULL, '안녕하세요!$B$B전 지금 어떤 장치를 만들고 있는데 나중에 용의 알을 가져다 줄 일손이 필요할 거예요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3296, 'koKR', NULL, '불타는 평원은 위험한 곳이지만 나 같은 학자들은 지식을 넓히기 위해서라면 어떤 일이라도 감수하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3297, 'koKR', '$n, 검은무쇠를 제련하는 기술을 유용하게 쓰길 바라네. 지식 때문에 타락하는 일이 없도록... 우리처럼 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3298, 'koKR', NULL, '카르 아만, $n. 아주 강한 $c 같군요. 이 지역에서는 조심하는 게 좋을 겁니다. 전혀 알지 못하는 물건에 손을 대거나 윗사람에게 불경하게 굴면 마땅한 응징을 받게 될 테니까요.$B$B우리를 존경하진 않더라도 불손한 행동을 하면 완력으로라도 우리의 힘을 존경하게 만들어 드리지요.$B$B자, 인사는 대충 이 정도로 끝내도록 하죠. 그런데 내가 도와 줄 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3299, 'koKR', NULL, '아, 어느 정도 자신의 가치를 입증한 흑마법사 동료로군요.$B$B만나게 돼서 반가워요. 나는 미네라 보이드렌더라고 해요. 이런 이름을 지은 데는 다 그만한 이유가 있죠.$B$B당신은 강한 새 도구들에 쉽게 적응하고 어리석게 남에게 줘 버리지 않을 정도의 상식은 있는 것 같군요. 그렇다면 다시 나와 얘기를 하도록 해요. 아니면 전투는커녕 부둣가로 돌아가서 다시 고향으로 돌아가 편히 사시는 게 좋을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3301, 'koKR', '아주 오래전 고대 전투와 여러 충돌이 있었을 때, 저희 종족은 거의 멸종될 뻔했지요. 많은 고난을 겪었습니다, $r.$B$B불타는 군단의 학살. 악마의 영혼. 5대 위상의 분리. 데스윙의 봉기. 용아귀 부족에게 포로가 되어버린 저희의 여왕, 알렉스트라자 님.$B$B그러한 와중에도 저희에겐 용들의 흔들리지 않는 의지가 생겼지요. 이 세계에서 사라져만 가는 저희 종족을 대표하려는 용감한 세력이었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3302, 'koKR', '그렇습니다. 지금은 당신의 앞에서 당신이 이해할 수 있는 형상으로 제가 서 있는 것입니다, 필멸자여. 밸라스트라즈라는 이름으로 알려진 용 앞에서 서 있을 용기가 있으십니까?$B$B<크게 웃는 밸란>$B$B그럼 계속 얘기를 할까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3303, 'koKR', '제가 왜 이곳에 왔는지 얘기해 드려야 하겠군요.$B$B데스윙이라는 위상이나 그의 자손들인 네파리안이나 오닉시아에 대해서 아십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3304, 'koKR', '한때 넬타리온이라는 이름으로 불린 데스윙은 세계의 힘을 보유한 위상이었지요. 이 필멸의 세계에 대한 거의 무한한 권한을 만물의 창조주, 카즈고로스라는 티탄에게서 받았습니다.$B$B타락한 그는 배반과 속임수로 다른 위상들이 자신들의 힘으로 악마의 영혼이라는 물건을 만들도록 설득했고 그 물건으로 한때 위대했던 위상들을 약하게 하여 갈라놓은 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3305, 'koKR', '그렇습니다. 이 물건은 결국 파괴되었고 데스윙도 다른 4명의 위상들이 모여 형성된 새로운 힘에 의해 거의 처치될 뻔했지요. 지금 데스윙이 어디에 있는지는 모르나 그의 자손인 네파리안이 이 요새를 지배하며 자신의 아버지가 남긴 업적을 마저 이루고자 한다는 것은 압니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3306, 'koKR', '데스윙은 추방을 당하기 전, 타락한 자식을 하나 탄생시키려고 하고 있었습니다. 위상의 선천적인 힘과 능력에 대한 면역이 있을 뿐만 아니라 데스윙의 완전한 지배를 받는 반 종족을 만들려고 한 것이지요.$B$B데스윙은 실패했지만 네파리안은 적어도 일부는 성공을 했을지도 모르겠습니다.$B$B꿈의 위상, 이세라 님이 이 몹쓸 생물들을 보고서는 저희에게 행동을 취하도록 한 것입니다. 이 \"오색\" 용혈족이라는 것들이 정말로 존재한다면 반드시 녀석들을 말살해야만 합', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3307, 'koKR', '그건 저희의 방식이 아닌데다 가능하지도 않습니다. 네파리안은 위상들만큼이나 오래된 고대 보호막의 보호를 받고 있지요. 그것 때문에 제가 이 요새의 내부 성소에 들어가지 못하는 것입니다. 암흑 마법 때문에 임명되지 않은용군단은 들어갈 수가 없어요. 하지만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3308, 'koKR', '용족이 아닌 자가 벼리지 않은 승천의 인장을 구해 보호막을 지나가는 것은 가능합니다. 저 같은 자가 그러한 물건을 지니면 저 자신이 파괴되어 버리겠지만 당신이라면 그 인장으로 보호막을 약하게 할 수 있을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3309, 'koKR', '이 요새의 아랫부분에서 가공하지 않은 승천의 인장을 습득한 녀석 하나를 찾아야 합니다. 그 물건을 취득하면 요새 위층으로 갈 수 있고, 또한 네파리안의 정예 경비대인 검은손부대의 일원이 되는 첫 걸음이니만큼 하급 생물이 이 물건을 취득하는 것은 크나큰 영광이지요. 그 물건을 찾아 제게 가져오시면 제가 그 물건의 성질을 조사하겠습니다. 인장을 다 조사하면 어떻게 해야 할지 알 수 있을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3310, 'koKR', '주의해야 합니다, 필멸자여. 이 요새의 하급 부족이 그런 물건을 가지고 있는 경우는 매우 드물기에 수십 년 동안 탐색을 해야 할지도 모릅니다. 인정사정 볼 것 없이 이 야수들을 처치하는 것이 좋을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3311, 'koKR', '그 인장을 더 가까이 가져오지 마십시오, 필멸자여. 여기서도 그 인장을 감싸고 있는 악을 느낄 수 있군요.$B$B제가 조사를 하는 동안 잠깐만 기다리십시오. 꽉 쥐고 계셔야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3321, 'koKR', '도끼를 제대로 사용하고 싶으면 적당한 인사도 해줘야 하는 법이지. 농담이 아냐. 날 한번 따라해 보게. \"안녕! 내 작은 친구야? 오늘은 뭘 베고 싶니?!\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3334, 'koKR', '나는 어둠해안에 악마의 이끼가 얼마만큼 퍼져 있는지 조사하러 왔소. 텔드랏실과 일대에 남은 타락의 기운이 퍼져 가고 있어서 세나리온 의회 드루이드들과 모든 나이트 엘프들이 심히 걱정하고 있지.$B$B이 사태의 원인을 알아내고 수습하는 게 내 목표라오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3337, 'koKR', '언제나 검은 더 날카롭게, 방어구는 더 단단해야 하는 만큼, 솜씨 좋은 마법부여사가 늘 우리 곁에 필요한 법이지요. 탈라단이 바로 그런 자입니다. 그라면 적절한 마법을 부여해 무기와 방어구의 성능을 향상시키는 방법을 알려줄 수 있을 테니, 장인의 정원으로 가서 그를 한번 찾아보십시오.', '언제나 검은 더 날카롭게, 방어구는 더 단단해야 하는 만큼, 솜씨 좋은 마법부여사가 늘 우리 곁에 필요한 법이지요. 탈라단이 바로 그런 자입니다. 그라면 적절한 마법을 부여해 무기와 방어구의 성능을 향상시키는 방법을 알려줄 수 있을 테니, 장인의 정원으로 가서 그를 한번 찾아보십시오.', '가슴 방어구에 마법 부여를 해주시겠다고요? 고마운 말씀이지만 별로 관심없는데요... 아, 마법 부여를 배울 곳을 찾고 계시다고요? 이런 당황스러울 데가! 배우셔야죠. 그... 누구지... 탈라단! 그래요. 장인의 정원에 있는 탈라단을 찾아가 보세요!', '가슴 방어구에 마법 부여를 해주시겠다고요? 고마운 말씀이지만 별로 관심없는데요... 아, 마법 부여를 배울 곳을 찾고 계시다고요? 이런 당황스러울 데가! 배우셔야죠. 그... 누구지... 탈라단! 그래요. 장인의 정원에 있는 탈라단을 찾아가 보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3357, 'koKR', '어서 오시게, $c|1이여;여;. 굿스티치 형제가 도와 드릴 일이라도 있는지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3358, 'koKR', '아, 내가 제일 좋아하는 손님이로군. 당신은 꽤 강한 흑마법사 같네. 만나서 반가우이. 혹시 내가 해 줄 수 있는 일이라도 있으면 말만 하게.$B$B우리 형제들은 당신과 같은 부류의 이들이 다음 세대를 이끌어 줄 것이라 믿고 있지. 그렇게나 큰 힘을 가진 이라면 불타는 군단이 무릎을 꿇는 것도 시간문제일 뿐이야.$B$B아주 부럽소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3375, 'koKR', NULL, '아, 저는 이 세계의 많은 지식을 알고 있습니다. 강력한 힘을 지닌 부적을 만드는 법도 안답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3377, 'koKR', NULL, '마우아리는 자네가 왜 나를 찾아왔는지 알고 있네...$B$B내게 에코를 갖고 오면 자네를 위해 부적으로 만들어 주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3380, 'koKR', '아, 그래, 맞아. 다단가는 연기를 싫어하지. 하지만 곁에서 냄새를 맡아 보니 목욕하는 것도 싫어하는 모양이던데?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3382, 'koKR', NULL, '마우아리의 부적은 많은 비밀을 간직하고 있지... 그 부적을 만드는 데 사용한 얼음 조각의 빛나는 표면은 반사 성질이 있어, 다른 존재들의 힘을 자기 자신에게 반사해 빨아들일 수 있네.$B$B부적을 소지하고 있으면 자신이 싸워 이긴 야수들의 영혼 에너지인 에코를 모을 수 있을 거야. 에코를 찾으면 이 마우아리에게 가져오게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3383, 'koKR', NULL, '에코란 모든 생물이 가지고 있는 힘을 말하지. 자네에게 만들어 준 부적을 몸에 지니고 있으면 그 힘을 얻을 수 있네.$B$B난 에코를 부적으로 변화시키는 주문을 알지.$B$B그러면 마우아리의 부적을 사용해 그 힘을 자신에게 반사시킬 수 있어.$B$B어때? 한번 해 보는 게. 에코를 이 마우아리에게 가져오면 한번 재미있게 놀아볼 수 있을걸.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3395, 'koKR', '어서 오시오, 젊은 $R 양반. 무얼 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3396, 'koKR', '훈련을 받고 싶단 말인가요? 저도 이제 막 배움의 길로 들어섰지만 제가 가르쳐 줄 수 있는 건 뭐든지 알려드리죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3397, 'koKR', '배우는 속도가 빠르시군요. 제가 따라갈 수 없을 만큼 아주 빨라요. 계속해서 훈련을 받고 싶거든 스승님을 만나 보시는 게 좋겠어요. 로트가스 스톤비어드라고 하는 분인데 아이언포지의 대용광로에서 계실 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3398, 'koKR', '응? 잡담할 시간 없어. 오늘 안으로 아버지가 시킨 일 다해야 한단 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3399, 'koKR', '솜씨가 좀 있어 보이는군. 몇 가지 더 배울 수 있겠어. 어디 내가 뭘 가르쳐 줄 수 있을지 한번 보지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3400, 'koKR', '이제 확실히, 당신이 나보다 더 많은 걸 알게 되었군. 이제 우리 아버지와 얘기해 봐. 당신 솜씨부터 먼저 증명해 보여야겠지만, 인정만 받으면 정말로 좋은 스승이 되어 주실 거니까. 아버지 성함은 로트가스인데, 벤구스 옆에서 작업하고 계셔.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3401, 'koKR', '이제 당신은 나보다 솜씨가 더 좋습니다. 내 오랜 친구인 로트가스 스톤비어드를 만나 보지 않겠소? 내가 제이나의 군대에 입대하기 전에 그 친구는 아이언포지에 남아 있었습니다. 그라면 당신에게 몇 가지 가르쳐 줄 수 있을 겁니다. 아니면 최소한 당신을 가르칠 수 있는 이를 알고 있을 거고. 아직 아이언포지에 있다면 대용광로에 살고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3402, 'koKR', NULL, '우선 여명의 설원에 있는 생물들에게서 찾아보는 게 좋겠지.$B$B하지만 다른 곳에서도 찾을 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3403, 'koKR', '훈련을 받고 싶으신가요? 당연히 도와 드릴 수 있습니다. 나도 수습 과정에 있을 뿐이지만 당신에게 가르쳐 줄 게 뭔가 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3404, 'koKR', '쉽게 인정하기는 싫은 사실이지만, 당신은 나보다도 솜씨가 훨씬 좋습니다. 이제 내가 가르쳐줄 수 있는 건 보잘것없는 것들뿐입니다. 더 큰 배움을 얻으려면 스톰윈드에 있는 테룸 딥포지라는 드워프를 찾아가 보십시오. 드워프 지구에 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3405, 'koKR', '미안하지만, 지금 호숫골에 있는 베르너 오스구드에게 가져갈 편자를 만드는 중이라 좀 바쁘오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3406, 'koKR', '내가 지금 수다나 떨고 있게 생겼소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3407, 'koKR', '솜씨가 나쁘지는 않지만 몇 가지 쓸 만한 요령을 더 가르쳐 주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3408, 'koKR', '당신은 분명 나보다 솜씨가 더 좋은 대장장이요. 내가 그렇게 말한 사실을 다른 이에게 말한다면야 당연히 부인할 테지만 말이오. 가서 테룸 딥포지와 얘기를 나눠 보시오. 당신에게 뭔가 더 가르칠 수 있는 이가 있다면 바로 그 친구니 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3409, 'koKR', '내가 싫어하는 물오리 얘기를 한마디라도 꺼내면 평생 누워서 살도록 해 주겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3410, 'koKR', '모루에다 망치만 휘두른다고 대장장이는 아니지. 누가 보고 비웃기 전에 그 망치를 이리 주게. 내가 제대로 가르쳐 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3411, 'koKR', '상당히 늘었군. 스날에게 가서 얘기를 해 보게. 사루의 슬하에서 수련을 받으러 오그리마로 갔으니, 전사 지구에 있는 불타는 모루 부근에서 찾을 수 있을 거야. 참, 그 친구 분명 당신을 시험하려 들 테니 준비 단단히 하는 게 좋을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3412, 'koKR', '스날은 내가 좀 느려서 답답하다고 하지만, 난 그저 일을 만족스럽게 마무리하고 싶은 것뿐이오. 일을 제대로 하려면 시간이 걸리는 법이지 않소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3413, 'koKR', '당신이 알고 싶어하는 걸 당장 가르쳐 줄 수도 있지만 인내심을 갖고 참아야 하오. 천천히 강철을 달구면서 망치로 두드릴 때마다 변화하는 형태를 몸과 마음으로 느끼도록 하시오. 강철과 당신이 하나가 되면 그제야 내 말을 이해할 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3414, 'koKR', '당신은 배우는 속도가 빠르군. 나쁜 건 아니지. 다만 작업은 제대로 마무리해야 한다는 것에만 주의하시오. 자, 이제 당신을 스날에게 보내야 하겠소이다. 그에게 가르침을 얻되 화가 나서 내뱉는 말은 귀담아 듣지 마시오. 사루의 딸들이 자기를 비웃을 때마다 늘 그러니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3415, 'koKR', '아무리 귀를 기울여도 카른이 말하는 그 영혼의 소리가 전혀 들리지 않소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3416, 'koKR', '카른은 강철과 가열로의 영혼이 우리를 인도하는 소리에 들어야 한다고 하는데, 나는 아무리 귀를 기울여도 쇳소리밖에 들리지 않더군. 자, 나와 같이 망치를 들고 영혼의 소리를 듣도록 노력해 봅시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3417, 'koKR', '강철의 영혼은 나보다 당신을 더 마음에 들어 하는 것 같소. 나는 아직도 그들의 소리를 듣지 못했지만 당신은 잘 배운 모양이오. 가서 카른과 얘기를 해 보시오. 자기처럼 영혼의 소리를 들을 줄 아는 이를 만나면 기뻐할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3418, 'koKR', NULL, '망치질할 시간도 턱없이 모자란 판에, 당신 지금 날 방해하는군요. 물론 그럴 만한 이유가 있는 거겠죠? 만약 그렇지 않다면...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3419, 'koKR', NULL, '아, 또 불의 힘과 모루를 이용해, 무기를 만들 자가 나타난 것이로군. 물론 가르쳐 드려야죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3420, 'koKR', NULL, '아주 제대로 배웠군요. 이제 언더시티로 가서 제임스 반 브런트라는 대장장이를 찾아보세요. 내가 가르치지 못하는 것들을 많이 가르쳐 줄 거예요. 전사를 양성하는 군사 지구 근처에서 무기와 방어구를 만들며 시간을 보내는 걸로 알고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3421, 'koKR', '나는 언젠가 적의 뼈로 무기와 방어구를 만들어 볼 날이 있기를 고대하고 있다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3422, 'koKR', '망치로 모루를 죽이는 게 아니라, 적을 죽일 무기를 만드는 거요. 당신이 지금 뭘 잘못하고 있는 건지 보여 주리다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3423, 'koKR', '당신은 많은 것을 배웠소. 이제 내가 더 가르칠 수 있는 게 없군. 제임스 반 브런트에게 가 보시오. 내가 가르칠 수 없는 것을 알려 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3424, 'koKR', NULL, '에코란 초자연적 힘이 흩어져 있는 형태이고, 부적은 그 힘이 정기로 집중된 것이라네. 난 강력한 주문을 외워서 에코를 부적으로 만들 수 있지. 마우아리의 부적을 사용해 자연의 힘을 자기 자신에게 반사시킬 수 있는 거라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3425, 'koKR', NULL, '당신처럼 조심성이 부족한 이가 이만큼 해냈다는 게 놀랍군...$B$B좋아, 부적을 하나 더 주겠어. 기분은 좀 나쁘군!$B$B어서 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3453, 'koKR', '망치와 모루를 다루는 솜씨가 좀 있긴 하지만 아직은 부족하오. 가서 데인 린드그렌과 얘기를 해 보시오. 내게 가르침을 얻을 수 있도록 준비를 제대로 시켜 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3454, 'koKR', '당신에게 대장장이의 피가 흐르고 있다고 말한 적이 있었지. 역시 내 말이 옳았소. 아이언포지의 대용광로로 가서 벤구스 딥포지라는 이름의 드워프 대장장이를 한번 찾아보시오. 내 스승이자 내가 아는 한, 최고의 대장장이니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3456, 'koKR', '대장장이의 삶이란 결코 쉬운 게 아니지만, 뼈에는 강철을 심어 주고 가슴에는 화염을 심어 준다오. 우리 아버지께서도 대장장이셨고, 조부님께서도 그림 바톨의 슬하에서 강철을 주무르셨지. 그리고 이제는 우리 아들 녀석도 가문의 발자취를 따르고 있소. 내 마음을 아주 뿌듯하게 하는 사실이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3457, 'koKR', '미안하지만, 당신은 내게 배울 준비가 아직 덜 된 것 같소. 내 아들 녀석, 그로움을 만나보시오. 새 수습생이 찾아오면 무척이나 기뻐할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3458, 'koKR', '솜씨가 부족해 보이지는 않지만, 당신을 제자로 받아들이기 전에 마지막 시험을 한 번 거쳐야겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3459, 'koKR', '그래요. 내 기꺼이 당신에게 대장기술을 가르쳐주겠소. 가서 작업복과 망치를 가져오시오. 뭘 만들 수 있을지 한번 보자고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3460, 'koKR', '배우는 속도도 빠르고 솜씨도 좋은 대장장이로군. 내가 가르칠 건 다 가르쳤네만 당신은 아직 더 배워야 할 것이 많은 것 같소. 가서 벤구스 딥포지와 얘기를 나눠보시오. 어려운 숙제를 많이 내주긴 하지만 그래도 최고의 대장장이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3461, 'koKR', NULL, '깜짝 놀랐잖아요. 그렇게 어두운 데서 불쑥 나타나지 마요. 다음에는 인기척이라도 내세요.', NULL, '암흑이 그늘숲을 집어삼켰을 때부터 난 잠을 잘 수가 없었어요. 바람에 실려오는 무시무시한 비명소리에 자꾸 잠이 깨거든요. 마치 양들의 비명 소리처럼 들리는데, 그치지를 않아요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3462, 'koKR', NULL, '흠... 당신 작품이 괜찮긴 하지만 아직까지 내가 바라는 기술에는 근처도 가지 못했군요. 황금골에 가서 대장장이 아르거스를 만나보세요. 그 친구가 기본기를 가르쳐줄 거예요. 기본기를 다 배우거든 다시 날 찾아오세요. 그러면 내게서 대장기술을 배울 준비가 됐는지 몇 가지 시험을 해보겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3463, 'koKR', NULL, '네, 조만간 당신이 찾아올 거라는 소식은 들었어요. 하지만 난 아무나 제자로 받지 않아요. 당신에게 솜씨가 있다는 확신이 있어야 하죠. 내가 주는 시험을 치르면서 한번 확인해 보도록 하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3464, 'koKR', NULL, '꽤 괜찮은 실력이지만 모서리 둘레가 좀 거칠군요. 그건 연습하면 나아질 테니까 걱정하진 마세요. 말이 나와서 말인데 요즘 당신이 만들고 있는 거나 한번 보도록 하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3465, 'koKR', NULL, '이제는 오히려 내 작품의 모서리 둘레가 거친 것 같군요. 솔직히 더 이상은 내가 가르쳐 드릴 게 없을 것 같아요. 아이언포지의 벤구스 딥포지라면 당신을 가르칠 수 있을 거예요. 금속에 관해서라면 모르는 게 없는 드워프거든요. 아이언포지의 대용광로로 가서 제자를 받는지 한번 알아보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3466, 'koKR', '사루에게 내 뛰어난 솜씨를 증명해 보이면 자기 딸 중 하나를 내게 줄 수밖에 없을 거야. 어디 최후에 누가 웃게 되는지 한번 보자고.', NULL, '수미와 투미에게는 접근하지 않는 게 자네 신상에 좋을 거야. 임자가 있거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3467, 'koKR', '한 번만 더 그런 형편없는 솜씨를 가지고 날 찾아오면 염소 오줌에 절인 조그만 상자에 집어넣어 집으로 보내버리겠어. 오그톡 같은 얼간이한테나 가봐. 자네 수준에는 그런 자가 딱 맞으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3468, 'koKR', '그러니까 내 가르침을 받을 만큼 솜씨가 있다고 생각하는 건가? 자네는 내 장화 밑의 벌레 정도밖에 되지 않아. 하지만 아랫 것을 받아주면 수미와 투미의 마음을 살 수 있을지도 모르겠군. 자네가 얼마나 실력이 있는지 한번 봐주지. 보잘것없을 게 뻔하지만!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3470, 'koKR', '자네에게 더는 가르칠 것이 없으니 이제 가 보게. 사루에게 갈 생각인가? 꿈도 야무지군. 자네처럼 보잘것없는 자가 찾아가면 피에다가 쇠를 담금질하고 말걸.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3471, 'koKR', '영혼들이 당신을 내게로 이끌어주었군. 내가 축복을 받았나 봅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3472, 'koKR', '젊은이, 당신은 영혼의 말에 좀 더 귀를 기울일 필요가 있소. 당신의 운명은 썬더 블러프에 있는 트라그 스톤후프라는 자에게 향해야 하오. 서로 가르침을 줄 수도 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3473, 'koKR', '자, 그럼 내가 제시한 과제를 수행할 준비가 되었소? 영혼들의 이야기로는 당신이 이 시험에 통과할 것이라고 하는군. 영혼들과 자신의 힘을 믿고 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3475, 'koKR', '우리 인생길에서 인연이란 아주 잠시 동안만 교차하는 것... 이제는 그 짧은 만남을 끝내고 각자의 길을 가야 할 때로군. 당신에게 가르침을 주고 그다음 스승에게까지 인도할 수 있음을 영광이라 생각하오. 오그리마에 있는 사루 스틸퓨리를 찾아가보시오. 당신이 배워야 할 것을 알 수 있을게요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3476, 'koKR', '당신에게는 큰 잠재력이 있지만 먼저 이해심부터 키워야 하오. 영혼의 힘을 인정하고 그들의 부름에 귀를 기울여야 하지. 그제야 비로소 당신이 가야 할 길을 걸을 준비가 된 거요. 가서 트라그와 얘기를 나눠보시오. 어쩌면 당신 둘은 서로 많은 도움이 될 수 있을 것 같단 생각이 드니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3478, 'koKR', '당신은 이미 많은 것을 배웠지만, 영혼의 말에 의하면, 아직도 배울 게 많이 있다는 것 같소. 나는 가야 할 방향만 제시할 뿐이지. 당신을 직접 이끌어줄 수는 없소. 오그리마에 있는 사루 스틸퓨리를 찾아가도록 하시오. 당신의 다음 여정은 그곳에서 시작될 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3479, 'koKR', '시간 뺏을 생각일랑 말고 내 제자, 바실하고나 얘기해 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3481, 'koKR', '장비를 만드는 실력이 꽤 쓸만하군. 훌륭해... 오크의 고향, 오그리마로 가서 사루 스틸퓨리라는 대장장이를 찾게. 오크에게도 한 가지 인정할 게 있다면, 바로 죽음의 도구를 썩 잘 만들 줄 안다는 거지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3482, 'koKR', '미안하지만 당신은 아직 기본기도 갖추고 있지 않아 내 가르침을 받기에는 무리겠소. 하지만 걱정하지 마시오. 내 제자인 로트가스를 찾아가 얘기해 보시오. 당신을 도와줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3484, 'koKR', '당신의 솜씨는 그 어떤 말로 칭찬해도 모자라겠군. 망치와 모루로 이렇게 놀라운 일을 할 수 있다니. 이제는 고블린에게 가서 대장기술을 배우시오. 단 내가 그런 말을 했다고는 아무에게도 얘기하지 말고. 브리크 킨크래프트라고 하는 자를 찾아가시오. 일전에 듣기로는 무법항에서 상점을 하나 운영하고 있다고 하더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3485, 'koKR', '대장기술이 무슨 어린애들 장난인 줄 아는가! 밖에 나가 스날하고나 얘기하게. 능구렁이 같은 놈이긴 해도 그래도 모루 다루는 법은 제대로 아니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3487, 'koKR', '자네는 나보다 쇠의 비밀을 더 많이 알고 있군. 좋은 일이야. 쇠의 비밀이란 꼭 손에 넣어야 할 가치있는 것이지. 자네는 이제 인간 영토 남쪽에 있는 밀림으로 가게. 무법항이라는 고블린 도시를 찾아. 그곳에 브리크 킨크래프트라고 하는 고블린이 있을 것이네. 별로 마음에 들지 않지만 쇠의 비밀에 대한 지식은 내가 아는 어느 누구하고도 비교할 수가 없을 정도지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3488, 'koKR', '응? 나? 당연히 대장장이지. 가만, 그러고 보니 자네 지금 드워프만 쇠를 다룰 줄 안다고 생각하는 게로군? 그럼 맘대로 하게. 가서 드워프한테나 도움을 청하라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3489, 'koKR', '지금 날 놀리는 거야? 맞지?! 놀리는 게 아니라면 나를 어릿광대 정도로 생각하는 거겠지. 그런 거야? 내가 광대처럼 보여? 나 원 참, 맞지?! 지금 내가 광대라고 생각하는 거지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3490, 'koKR', '마치 내가 이런 물건을 처음 본 것인 양 행동하는군. 괜찮은 물건이긴 하지만 이런 \"괜찮은\" 수준의 물건은 매일 본단 말이야. 이렇게 하지. 나를 아주 놀라게 해주면 잠자던 드워프가 벌떡 일어나게 할 만한 것을 만드는 법을 가르쳐주겠어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3493, 'koKR', '인정하기는 싫지만 곰이 나보다 한 수 위군. 무지막지하게 큰 곰이야!$B$B저 곰을 때려눕힐 수 있을 정도면 자랑스러워할 만하지! 녀석 때문에 골치깨나 앓은 사냥꾼이 한둘이 아니거든.$B$B<당신의 등을 철썩 치는 마렉>$B$B그 곰을 잡으면 자네를 우리 원정순찰대 오두막 정식 회원으로 받아주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3494, 'koKR', '이곳 원정순찰대 오두막에서는 무엇보다도 사냥 기술을 가장 높이 평가하지. 내게 인정을 받고 싶은가? 그건 공짜로 얻어지는 게 아니라네.$B$B한번 도전해 보게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3495, 'koKR', '꽤나 실력 있는 사냥꾼이 되었군, $n! 기술도 입증하고 다릴마저도 능가하다니. 진짜 칭찬받을만한 일이야!$B$B자네는 언제나 환영이네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3496, 'koKR', '후후, 기꺼이... 이 순간을 조금만 더 즐기겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3513, 'koKR', '마법 지구에 있지. 무시무시한 해골처럼 생긴 건물에서 찾아봐.', '마법 지구에 있지. 무시무시한 해골처럼 생긴 건물에서 찾아봐.', '어디 있는지 알아! 언더시티 외곽, 마법 지구, 해골 건물...', '어디 있는지 알아! 언더시티 외곽, 마법 지구, 해골 건물...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3514, 'koKR', '상업 지구 중앙에 있는 탑이 은행이야. 금방 찾아.', '상업 지구 중앙에 있는 탑이 은행이야. 금방 찾아.', '나, 눈 하나지만 너보다 잘 볼 수 있다! 언더시티 중앙에 은행 있어!', '나, 눈 하나지만 너보다 잘 볼 수 있다! 언더시티 중앙에 은행 있어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3515, 'koKR', '마이클 가레트? 상업 지구 위쪽에 있다.', '마이클 가레트? 상업 지구 위쪽에 있다.', '상업 지구 위층에 박쥐 조련사 있다.', '상업 지구 위층에 박쥐 조련사 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3516, 'koKR', '크리스토퍼 드라쿨은... 상업 지구 동쪽에.', '크리스토퍼 드라쿨은... 상업 지구 동쪽에.', '우리도 너네 길드 들 수 있어? 안 돼? 몸무게 제한? 상업 지구 동쪽에 길드 사무관 찾아봐.', '우리도 너네 길드 들 수 있어? 안 돼? 몸무게 제한? 상업 지구 동쪽에 길드 사무관 찾아봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3517, 'koKR', '상업 지구 위층, 여관주인 노먼한테 말해봐.', '상업 지구 위층, 여관주인 노먼한테 말해봐.', '마음이 사악한 자에겐 휴식 없다. 당신은 괜찮을 거야. 상업 지구 위층, 여관주인 노먼을 찾아봐.', '마음이 사악한 자에겐 휴식 없다. 당신은 괜찮을 거야. 상업 지구 위층, 여관주인 노먼을 찾아봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3518, 'koKR', '우체통... 한가운데... 상업 지구 위층 여관 옆에...', '우체통... 한가운데... 상업 지구 위층 여관 옆에...', '우리 파... 파쇄의 도끼 팔렸나? 상업 지구 위층, 여관 옆 우체통 찾아.', '우리 파... 파쇄의 도끼 팔렸나? 상업 지구 위층, 여관 옆 우체통 찾아.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3519, 'koKR', '경매장 여기 있어. 도시 중앙에 있는 원 쪽에.', '경매장 여기 있어. 도시 중앙에 있는 원 쪽에.', '여기 없다... 오크 도시에 있다. 밖에서 풍선을 타.', '여기 없다... 오크 도시에 있다. 밖에서 풍선을 타.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3520, 'koKR', '조그만 고블린... 로데론의 폐허 북쪽 건물 옥상에... 언더시티에서 나가.', '조그만 고블린... 로데론의 폐허 북쪽 건물 옥상에... 언더시티에서 나가.', '폐허의 북쪽 위로 풍선 보여. 타면 멀리 간다.', '폐허의 북쪽 위로 풍선 보여. 타면 멀리 간다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3521, 'koKR', '상급 사제? 군사 지구 외곽으로 가서 찾아봐.', '상급 사제? 군사 지구 외곽으로 가서 찾아봐.', '어.. 어... 군사 지구의 그 부정한 놈들... 도시 외곽에 있는 건물 둘러싸고 있어.', '어.. 어... 군사 지구의 그 부정한 놈들... 도시 외곽에 있는 건물 둘러싸고 있어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3522, 'koKR', NULL, '그 머리를 가져가면 다릴 녀석, 겁 좀 먹을 거예요. 당해도 싸지, 못된 녀석. 호호! 이걸 보고 어떤 표정을 지을지 기대가 되는걸요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3523, 'koKR', NULL, '원정순찰대 오두막에 오신 것을 환영해요, $n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3524, 'koKR', '도적 지구 외곽... 건물로 가봐.', '도적 지구 외곽... 건물로 가봐.', '우리 놈들에게 숨는 법 배운다. 언더시티 도적 지구 외곽으로 가.', '우리 놈들에게 숨는 법 배운다. 언더시티 도적 지구 외곽으로 가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3525, 'koKR', NULL, '당신은 언제나 환영이에요, $n. 웃게 해줘서 고마워요. 다릴 걱정은 안 하셔도 돼요. 당해도 싼 녀석이니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3526, 'koKR', '흑마법사들 마법 지구 외곽에, 마법사들이랑 있는 거 봤다.', '흑마법사들 마법 지구 외곽에, 마법사들이랑 있는 거 봤다.', '나 애완용 지옥사냥개 있으면 좋겠다. 먹을 거도 주고, 막대기 던지기 놀이도 하고, 잘 놀아줄 수 있는데. 흑마법사? 도시 외곽의 마법 지구에 있다.', '나 애완용 지옥사냥개 있으면 좋겠다. 먹을 거도 주고, 막대기 던지기 놀이도 하고, 잘 놀아줄 수 있는데. 흑마법사? 도시 외곽의 마법 지구에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3527, 'koKR', '도시 외곽, 군사 지구의 건물 안에 있다.', '도시 외곽, 군사 지구의 건물 안에 있다.', '전사 싸움 잘해. 언더시티 외곽, 군사 지구에서 찾아.', '전사 싸움 잘해. 언더시티 외곽, 군사 지구에서 찾아.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3528, 'koKR', '연금술 실험실로 가봐. 그곳에, 학자 허버트 핼시와 학자 마쉬, 물약 들고 꼼지락대고 있어.', '연금술 실험실로 가봐. 그곳에, 학자 허버트 핼시와 학자 마쉬, 물약 들고 꼼지락대고 있어.', '연금술 실험실에 학자 허버트 핼시 있다. 우리 태어난 곳이다. 당신도 우리처럼 잘 꿰매줄 거야.', '연금술 실험실에 학자 허버트 핼시 있다. 우리 태어난 곳이다. 당신도 우리처럼 잘 꿰매줄 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3529, 'koKR', '제임스 반 브런트 군사 지구 내곽에 있다.', '제임스 반 브런트 군사 지구 내곽에 있다.', '제임스 반 브런트 군사 지구 내곽에서 일해. 사슬 잘 만들어.', '제임스 반 브런트 군사 지구 내곽에서 일해. 사슬 잘 만들어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3530, 'koKR', '유니스 버치? 상업 지구!', '유니스 버치? 상업 지구!', '유니스 버치... 맨날 팔다 남은 음식만 줘. 상업 지구로 가.', '유니스 버치... 맨날 팔다 남은 음식만 줘. 상업 지구로 가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3531, 'koKR', '연금술 실험실 내곽으로 가. 거기 라비니아 크로...', '연금술 실험실 내곽으로 가. 거기 라비니아 크로...', '유령 아가씨 마법 물건 만들기 가르쳐 준다. 연금술 실험실 내곽에 있어.', '유령 아가씨 마법 물건 만들기 가르쳐 준다. 연금술 실험실 내곽에 있어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3532, 'koKR', '프랭클린 로이드? 언더시티 외곽 도적 지구에 있다.', '프랭클린 로이드? 언더시티 외곽 도적 지구에 있다.', '헤... 폭탄? 우리 꽝 좋아해. 그레이엄 반 탈렌 보면 만들기 가르쳐 줘. 도적 지구 외곽에 있다.', '헤... 폭탄? 우리 꽝 좋아해. 그레이엄 반 탈렌 보면 만들기 가르쳐 줘. 도적 지구 외곽에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3533, 'koKR', '나 안다. 그녀 좋아. 메리 에드라스 도적 지구 내곽에 있어.', '나 안다. 그녀 좋아. 메리 에드라스 도적 지구 내곽에 있어.', '우리 다치면 꿰매주고 붕대 감아줘. 도적 지구 내곽에서.', '우리 다치면 꿰매주고 붕대 감아줘. 도적 지구 내곽에서.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3534, 'koKR', '마법 지구 가면 알만드 크롬웰 금방 찾아. 둑에 서 있다.', '마법 지구 가면 알만드 크롬웰 금방 찾아. 둑에 서 있다.', '알만드 크롬웰... 맨날 마법 지구의 둑에 서있다. 그거 알아? 보라색 물고기 맛좋아. 한번 먹어봐. 꼭!', '알만드 크롬웰... 맨날 마법 지구의 둑에 서있다. 그거 알아? 보라색 물고기 맛좋아. 한번 먹어봐. 꼭!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3535, 'koKR', '마사 알리스타 찾아? 연금술 실험실 내곽에 있다.', '마사 알리스타 찾아? 연금술 실험실 내곽에 있다.', '연금술 실험실 내곽으로 가봐. 마사 알리스타가 꽃 꺾는 법 가르쳐 준다.', '연금술 실험실 내곽으로 가봐. 마사 알리스타가 꽃 꺾는 법 가르쳐 준다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3536, 'koKR', '도적 지구 내곽에 있다.', '도적 지구 내곽에 있다.', '가죽 세공? 도적 지구 내곽에서 아서 무어가 을 가르쳐.', '가죽 세공? 도적 지구 내곽에서 아서 무어가 을 가르쳐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3537, 'koKR', '군사 지구 내곽으로 가. 브롬 킬리안 있어.', '군사 지구 내곽으로 가. 브롬 킬리안 있어.', '브롬 킬리안 만나면, 반짝이는 돌을 캘 수 있어. 군사 지구 내곽에 있다.', '브롬 킬리안 만나면, 반짝이는 돌을 캘 수 있어. 군사 지구 내곽에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3538, 'koKR', '킬리안 헤이지는 도적 지구 내곽에서 무두질을 가르칩니다.', '킬리안 헤이지는 도적 지구 내곽에서 무두질을 가르칩니다.', '우리 무두질 갈고리 있다. 킬리안 헤이지가 줬어. 가죽 벗기는 법도 가르쳐주고. 아... 당신 피부가 좋군. 도적 지구 내곽에 가봐.', '우리 무두질 갈고리 있다. 킬리안 헤이지가 줬어. 가죽 벗기는 법도 가르쳐주고. 아... 당신 피부가 좋군. 도적 지구 내곽에 가봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3539, 'koKR', '조셉 그레고리안... 마법 지구 내곽 쪽... 녹색 운하 옆에 있다.', '조셉 그레고리안... 마법 지구 내곽 쪽... 녹색 운하 옆에 있다.', '음, 좋은 생각. 나도 가서 꿰맨 데 좀 봐달라고 할까? 조셉 그레고리안 바느질 잘한다. 마법 지구 내곽에 있다.', '음, 좋은 생각. 나도 가서 꿰맨 데 좀 봐달라고 할까? 조셉 그레고리안 바느질 잘한다. 마법 지구 내곽에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3540, 'koKR', NULL, '아, 네! 여기 있어요, $n. 당신이 도와준 데 대한 최소한의 보답이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3541, 'koKR', '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3542, 'koKR', '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3543, 'koKR', '어떤 물건을 찾으시나요?', '무엇을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3545, 'koKR', '이 늙은이의 얘기를 잘 들어보십시오, $n. 할 얘기가 많답니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3546, 'koKR', NULL, '$n, 마샬의 야영지에 오신 걸 환영해요. 이곳은 어떤 목적이 있어 오기도 하고 우연히 길을 가다 들르기도 하지요. 모두 나름대로 사연이 있는 법이지 않습니까?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3550, 'koKR', '크르르...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'koKR', '도움을 구하려 남쪽에서 크로스로드까지 왔소, $c. 그런데 여기엔 내게 등을 돌리는 겁쟁이들뿐이군. 위대한 토르크조차 날 모욕했소. 훌륭한 지도자이긴 하지만 내 간청을 묵살한 탓에 분노가 더 치밀어 오르오.$B$B그는 내 분노가 성급함을 부르고 판단을 흐린다고 말하지만... 복수하기 전에는 절대 쉬지 않겠소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3554, 'koKR', '고맙네, $n. 그토록 헌신적으로 내 부탁을 들어주다니 말일세. 죽은 내 아내의 영혼도 위안을 찾았을 거야. 얼마나 고마운지, 말로도 다하지 못하겠군.$B$B그래도 가시멧돼지에 대한 내 증오는 결코 멈추지 않겠지만, 지금은 흡족해.$B$B자, 이제 나는 새출발할 준비를 해야겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3557, 'koKR', NULL, '이 시체는 오크 여전사의 것입니다.$B$B전사한 것이 분명한데, 아마도 이 부근의 가시멧돼지와 싸우다 죽었나 봅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3558, 'koKR', NULL, '몸을 뒤집어보니 칼날과 마법에 의해 공격당한 상처가 선명하게 남아 있습니다. 방어구는 거의 다 산산조각났고 머리카락은 산발이 되어 있습니다.$B$B만크릭에게 들은 이야기를 떠올려 보니, 이 오크가 그의 아내인 것이 분명합니다.$B$B이 소식을 전해주면 애통해 하고, 분개할 것이 분명하지만, 그에게 진실을 알려주어야 한다는 생각이 듭니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3559, 'koKR', '$c|1이여;여;, 십자로에 온 걸 진심으로 환영하네. 내 이름은 톨크라고 하네. 대족장님을 대신하여 이곳의 수비를 맡고 있지.$B$B이곳에 머무는 동안, 부디 편히 지내도록 하게. 쓸데없이 간섭만 하지 않는다면, 아무도 뭐라고 할 사람은 없으니까.$B$B사실은, 이곳에서 우리의 안전을 위협하는 적들이 늘고 있어. 이곳의 지리에 익숙해졌거든 주민들과 얘기를 나눠보게. 자네에게 맡길 일이 있을지도 모르니까 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3560, 'koKR', '<침을 뱉는 고어투스>$B$B나는 호드의 전사라네, $n. 적들이 카르가스에서 하루도 안 되는 거리에 요새를 세워놓고 우리를 공격할 계략을 꾸미고 있다니 화가 치밀어 오르는군.$B$B명령의 구속에서 벗어나 대족장님의 이름으로 녀석들을 말살시켜버리고 싶은 심정이야.$B$B하지만 우리에겐 모두 각자의 역할이 있으니 어쩌겠나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3561, 'koKR', '정말로 자네가 부럽네. 호드의 이름으로 최전선에 나가 직접 적과 싸울 수 있으니 말이야. 내 역할은 지휘를 하는 것이지.$B$B나도 소싯적에는 내 꿈을 이루면서 살았기 때문에 이 늙은 나이에도 그나마 견딜 수 있는 것이라네. 이제는 승리의 영광도, 패배의 쓴맛도, 모두 내가 지휘하는 병사들을 통해 맛보고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3562, 'koKR', '난 꿈을 꾼다네, $n. 암. 꾸고 말고. 나는 꿈속에서 수천 가지 방법으로 수천 번 죽음을 맞이한다네. 이런 꿈들을 대개는 악몽이라고 부르지만 나는 그렇게 생각하지 않네! 꿈속에서만큼은 전장에서 죽음을 맞이하니까 말이야. 내가 한 번씩 죽을 때마다 호드의 일만 적이 내 앞에 쓰러지거든. 참 영광스럽지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3563, 'koKR', '그래. 자네를 보기만 해도 알겠어. 자네를 보면 소싯적 호드의 전사로 활약하던 때가 생각나.$B$B자네는 살아서 큰일을 해내고 죽어서는 더욱 큰일을 해낼 거야.$B$B<경례하는 고어투스>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3564, 'koKR', '겸손하기까지 하군. 이제 자네의 때가 된 것일지도 모르지, $n.$B$B검은바위 오크의 요새로 진입할 각오는 되어있나? 녀석들을 파멸시키고 산에 위치한 요새를 송두리째 뽑아버릴 각오가 되어있는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3565, 'koKR', '역시 기대를 저버리지 않는군, $n.$B$B명령서를 내리도록 하지. 날 실망시키지 않으리라 믿네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3566, 'koKR', '아, 방문객이로군! 모험가신 모양이군요. 관광객은 이쪽으로 잘 지나가지 않는단 말이야. 의자에 앉아 한잔 들이켜면서 편히 쉬십시오. 보아하니 힘깨나 쓸 것 같은데, 철창 경기에 나가보실 생각은 없으신가요?', '아, 방문객이로군! 모험가신 모양이군요. 관광객은 이쪽으로 잘 지나가지 않는단 말이야. 의자에 앉아 한잔 들이켜면서 편히 쉬십시오. 보아하니 힘깨나 쓸 것 같은데, 철창 경기에 나가보실 생각은 없으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3573, 'koKR', '어서 오게, 젊은 $c|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3574, 'koKR', '렌드... 블랙핸드의 아들이자 검은바위 부족의 무능한 족장이지. 그만큼 고집이 센 자도 드물 걸세.$B$B2차 대전쟁이 끝날 무렵, 렌드와 그의 동생인 마임은 검은바위 첨탑의 산중 요새에 피신했지. 바로 그곳에서 렌드 녀석, 자기가 검은바위 부족의 대족장임을 선언했다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3575, 'koKR', '그렇지. 내게 그런 걸 설득하려고 들 필요는 없네. 대족장님과 나는 많은 일을 함께 겪었으니 말이야. 하지만 자네의 헌신은 기억해두도록 하지.$B$B말했듯이 렌드 녀석은 자기 부족에게 새로운 터전을 마련해 주었지. 나도 힘겹게 따라가던 자들 중 하나였다네.$B$B싸움이 하나 터지면 그로 인해 또 다른 싸움이 터지고, 또 터지고... 끝이 없었지. 내 두 아들이 죽은 것도 검은바위 첨탑을 놓고 검은바위 부족과 검은무쇠 드워프 사이에서 일어난 전쟁에서였지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3576, 'koKR', '그래, 나는 떠났네. 도저히 검은바위 부족과 함께할 수가 없었지. 아니. 그렇게 하면 내 아들들의 죽음이 헛되이 돼버리기 때문에 말일세. 렌드처럼 무능하고 권력에 굶주린 미치광이를 섬길 수가 없었지.$B$B나는 로데론의 숲으로 가서 하스글렌 근처에서 몸을 숨기고 살았다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3577, 'koKR', '<크게 웃는 아이트리그>$B$B젊은이, 그 땐 세상이 원래 이처럼 어지러운 곳이 아니었다네. 그때는 스컬지가 들이닥치기 전이었고 로데론이 역병지대로 불리기도 전이었지.$B$B그곳에서 스랄 님은 내 목숨을 구해주셨고 그 일을 계기로 나는 새로운 호드의 일원이 되었지. 이런, 엉뚱한 얘기를 하고 있군. 이런 역사 이야기는 다른 때나 해야지. 그래, 어쩌면... 다음에 말이야...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3578, 'koKR', '그럴 줄 알았네. 언젠가 자네가 내 오랜 친구에게 소식을 전해줄 수 있을지도 모르겠군. 그 친구는 아직도 그 숲에서 지낸다는 소식을 들었다네.$B$B<마치 기도를 하듯, 잠시 고개를 숙이는 아이트리그>$B$B렌드 얘기를 하고 있었지... 그래. 렌드와 그 동생 마임은 검은바위 첨탑을 지배하며 계속해서 검은무쇠 드워프와 대립했지. 도시 위에 있는 드워프를 몰아내는 데는 성공했지만 그러는 과정에서 용이 쳐들어왔고 마임이 죽어버렸다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3579, 'koKR', '그렇지. 이제는 데스윙의 자손인 네파리안이 검은바위 첨탑을 지배하고 렌드는 그 용의 명령을 따르고 있네.$B$B자네가 어떻게든 승천의 전당을 지나갈 수만 있다면 좋을 텐데.$B$B<한숨을 내쉬는 아이트리그>$B$B안타깝게도 검은용군단에 자신의 가치를 입증한 자만이 그곳에 올라갈 수가 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3580, 'koKR', '그럴지도. 이제 가보게, 젊은이. 대족장님의 조언을 듣게. 대족장님께서 자네가 발견한 것에 대해 알고 싶어하실 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3583, 'koKR', '시험의 골짜기에서는 칼림도어에서 가장 허약한 자라도 호드와 어깨를 나란이 하고 싸울 수 있을 만한 강력한 전사로 단련시켜 주지. 우리의 시험을 통과하지 못한 자들은 이글거리는 사막의 태양 아래서 타죽게 된다고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3584, 'koKR', NULL, '안녕하세요, $n. 나는 크로노르무로 알려져 있지만 그냥 간단하게 크로미라고 불러주세요. 그런 격식 차리지 않는 게 편하니까.$B$B내가 어떻게 당신의 이름을 알고 있는지 궁금하세요? 나는 바로, 청동용군단의 일원으로서, 끝없이 순환하는 시간의 흐름과 함께 움직이는 몸이에요. 그러니, 전에 우리가 만난 적이 있다고 해도 좋겠지요. 그리고 앞으로도 다시 만나게 될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3585, 'koKR', NULL, '$n, 또 만나는군요. 엄청나게 강한 세력에 의해, 아직도 시간의 흐름이 위협받고 있어요. 청동용군단에서는 당신의 지속적인 도움을 항상 환영하는 바입니다.$B$B비록 과거는 그 자리에 고정되어 있으나 미래는 항상 변하는 것. 지금 바로 이 순간에 내리는 결정이 그러한 변화를 이끌게 될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3586, 'koKR', NULL, '$n, 윗사람들의 말을 귀담아 듣게나. 그리고, 굳은 의지력과 강한 정신력만 있다면 제어하지 못하는 마력 따위는 없는 법이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3587, 'koKR', NULL, '포세이큰이라고 해서 모두 실바나스의 뜻을 따르는 건 아니야. $n, 우리 중에는 진정한 힘, 그러니까 스스로 힘을 얻은 자들도 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3589, 'koKR', NULL, '때...가... 좋지 않...다..고, $n. 집중을 해...야...해.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3590, 'koKR', NULL, '$C|1이여;여;, 이렇게 깊은 습지대까지 들어오다니 아주 중요한 일이 있는 모양이군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3591, 'koKR', NULL, '지옥불정령은 흑마법사라면 모두 곁에 두기를 바라는 가장 강력한 소환수 중 하나지. 힘도 세고 방어력도 좋은데다 어떤 적에게든 치명상을 입히거든. 지옥불정령의 영혼을 자네의 무기에 담는다면 그러한 장점을 일부 얻을 수 있을 걸세. 이를테면 생명력과 재생력이 세지는 식으로 말이야.$B$B지옥사냥개에 대해 알고 싶거든, 맞은 편에 있는 위툴라와 얘기해 보게. 자세히 알려줄 테니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3592, 'koKR', NULL, '지옥사냥개... 정말 사나운 짐승이지. 물론, 지옥불정령만큼 힘이 세지는 않지만, 현명한 흑마법사라면 힘이 모든 문제의 해결책이 아니라는 것을 잘 알 거야. 힘이 모든 것을 해결해줄 수 있다고 생각했다면, 전사의 길을 가고 있겠지... 안 그래?$B$B지옥사냥개는 적의 마나를 흡수한 다음, 그걸 이용해 재빠른 몸놀림으로 적을 제압하지. 지옥사냥개의 힘은 마력에서 나오고, 자신의 목적을 위해 그 힘을 사용할 줄 안다는 점에서 강력한 거라네.$B$B지옥불정', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3594, 'koKR', NULL, '$n, 탑 안에 있는 제 수행사제들과 얘기는 해보셨나요? 그들이 주는 임무 중 하나는 완수해야, 제가 보주를 만들어드릴 수 있어요. 준비가 되셨다면 지금 가서 얘기를 나눠보도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3633, 'koKR', '제발 도와줘.$B$B나는 곧 이 세상을 뜨게 될 거라네. 지금은 고통스럽지만 숨을 거두면 더 이상 아픔도 없겠지. 하지만 야생동물들은... 동물들도 나와 같은 고통을 겪고 있는데 그 고통에는 끝이 보이질 않네. 죽기 전 마지막 부탁이니, 부디 들어주게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3634, 'koKR', '나는... 당신네 말을 할 줄 알아. 우리는 짐승이 아니야! 그런데 외모가 다르다고 우리를 괴물 취급하고 위협했지! 하지만, 이 문제는 이 땅이 처한 비극에 비하면 아무것도 아니지. 부디 우리와의 불화를 잠시 잊고, 죽어가는 나의 청을 들어주게.$B$B내가 여기 온 이유는 가능한 모든 수단을 동원해 이 땅을 치유하려는 거라네. 하지만 자네가 도와주지 않으면 모두 허사가 되어버릴 것 같아. 마지막 남은 힘을 다해 부탁하니 제발 도와줘.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3635, 'koKR', '\"...\"$B$B이 타우렌 드루이드의 몸에 움직임이 없습니다. 마침내 이승을 떠나 뒤틀린 황천으로 간 모양입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3653, 'koKR', '난 이 도시의 공무를 보고 있네. 언더시티의 인구를 조사하는 업무를 맡고 있지. 스컬지에게 해방된 후로 우리는 인구를 정확하게 기록해 두려고 노력하고 있지. 난 마법과 고도로 단련된 정신력으로 그걸 조사해 기록할 수 있다네. 용건이 있다면 말해 보게. 내게 용건이 있는지 없는지 정도는 알겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3654, 'koKR', '대족장님께서는 내게 모든 종류의 무기와 방어구에 대해 연구하라고 지시를 내리셨소. 타우렌과 오크의 문화가 만나는 이곳 불모의 땅으로 나를 보내, 이 땅의 문화에 대해서 배우고 가능한 한 다양한 여행자를 접해보라고 하셨지.$B$B대족장님께서는 가시멧돼지나 켄타우로스처럼 하찮은 짐승들의 문화에서도 배울 게 있다고 생각하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3656, 'koKR', '어이! $R! 이리 와 봐. <킁킁>$B$B시간이 없어. 난 곧 최후를 <킁> 맞을 거야. 하지만 두고 봐... 결국 최후의 승자는 이 뻐드렁니가 될 테니까 말이야. <킁킁>$B$B비록 갇혀 있는 신세이긴 하지만 <킁킁> 아직 우리 부족에게 도움이 될 수는 있거든. 서슬갈기 일족은 뾰족털 가시멧돼지들 중에서도 가장 강한 부족이란 말이야!$B$B호드는 습격을 주도한 자가 누군지 알고 싶어 해. <킁킁> 이 뻐드렁니를 도와주면 그 대가로 나만이 알고 있는', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3657, 'koKR', '스톰윈드에 오신 것을 환영합니다! 저는 인구조사국에서 시민을 위해 일하고 있는 공무원입니다. 찾는 사람이 있다면 제가 도와드릴 수 있을 겁니다. 저는 마법과 고도로 단련된 정신력을 이용하여 이 기록들을 조사할 수 있거든요.$B$B제게 용건이 있으시면 언제든지 말씀해 보십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3658, 'koKR', '화가 나서 코가 자꾸 막히지만, <킁킁> $R한테 이 이야기는 꼭 해줘야겠어.$B$B아주 오래전 신들의 전쟁이 일어났지. 우리 위대한 멧돼지 신, 아감마간 님은 그 고대의 전쟁에서 패배한 후, 땅으로 떨어지셨어. 피는 비가 되어 내리고 뼈는 산산조각나 버렸지. <킁킁>$B$B아감마간 님의 피가 뿌려진 땅에서는 커다란 가시들이 돋아났고, 해골은 남쪽에 있는 동굴에 떨어졌어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3659, 'koKR', '휴... 담배 한 모금 피운 후, 아리따운 노움 여성과 데이트라도 했으면... 아니, 데이트 먼저 하고 한 모금 펴도 좋겠지!$B$B전 저 녀석의 뱃속에 몇 달 동안이나 갇혀 있었답니다! 오늘이 무슨 요일이죠? 참, 나 방금 빠져 나왔지...$B$B얏호!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3660, 'koKR', '어떻게 들어갔느냐고요? 흠... 얘기하자면 길지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3661, 'koKR', '그렇다면 좋아요! 전 용암 방열복의 성능을 시험해 보려고 작열하는 교각의 용암 구덩이에 갔어요. 모든 게 잘 되고 있었지요. 그 속에서 한 군데도 화상을 입지 않고 헤엄칠 수 있을 정도로 말이에요!$B$B그곳에서 볼일도 보고 배영도 하면서 있는데 난데없이 녀석이 나타나서 날 통째로 집어삼키지 뭐예요! 용암 방열복이랑 그 안에 내장된 자동 음식 공급기가 아니었으면 전 그대로 끝장이었을 거라고요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3662, 'koKR', '허. 좀 믿지 못하는 듯한 목소리로네요. 그래요. 그런 일이 벌어졌어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3663, 'koKR', '이 괴물 뱃속에서 나온 지 얼마나 됐다고 벌써 제 화장실 습관에 대해 묻는 거죠? 이봐요, 날 구해준 것만 아니었으면 벌써 흠씬 두들겨 패 주었을 거라고요!$B$B어쨌든! 도와줘서 고마워요. 당신한테 사례라도 해야겠는데 말이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3664, 'koKR', '음... \'사례\'라는 말이 그리 적절하지 않을지도 모르겠군요. 제가 저 괴물의 뱃속에 들어앉아 있는 동안 쭉 생각을 해봤는데 말이죠...$B$B이 생물은 불길이 이글거리는 용암 속에 살면서도 전혀 화상이라든가 상처를 입지 않더라고요!$B$B그런 괴물의 가죽을 원상태 그대로 구할 수만 있다면, 눈망루 마을에 사는 말리퍼스 다크해머라는 제 친구에게 가지고 가세요. 그 괴물의 가죽을 가공할 수 있는 자가 있다면 바로 그 친구거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3665, 'koKR', '그럼 소식을 전해주지 않으시겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3666, 'koKR', '바퀴벌레 사시려고? 말도 잘 듣고 귀여운 놈으로 골라줄 테니, 한 마리 들여 가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3668, 'koKR', NULL, '저에게는... 아니, 우리 모두에게... 시간은 별로 남아있지 않아요.', NULL, '해야 할 일이... 역병의 폭풍우가 몰아닥치기 전에 할 일이 너무 많아요...', NULL, '존. 여보, 어디 있어요?', NULL, '모두 어떻게 된 걸까요? 추워요... 너무... 추워요.', NULL, '쉬이잇... 무슨 이상한 냄새가 나는 것 같지 않아요?', NULL, NULL, NULL, NULL, NULL, NULL),
(3669, 'koKR', NULL, '재니스의 영혼이 당신을 바라봅니다. 그녀의 눈에는 이전과는 달리 충만한 자각과 이해가 담긴 듯한 느낌입니다.$B$B\"마치 내 영혼에서 무거운 짐이 벗겨진 듯하군요. 저는 곧 영원한 안식을 취하게 될 거예요. 이제는 알아요. 그때를 침착하게 기다릴 겁니다.$B$B고마워요, 낯선 분이여.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3670, 'koKR', '<킁킁> 이 뻐드렁니에게 많은 도움을 주었군. 솔직히 기대 이상이야, $R!$B$B고마워. <킁>$B$B나는 여기에 갇혀 있지만, 뾰족털 가시멧돼지에게 혈석 파편을 빼앗아 오면 자네에게 아감마간 님의 힘을 주겠어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3673, 'koKR', '우리 토륨 대장조합에서는 개미 같은 자들과는 상대하지 않습니다. 썩 사라지시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3674, 'koKR', '나 정도의 솜씨를 가진 이에게는 간단한 일이지만.$B$B짐승의 가죽으로 물건을 제작할 때 가장 힘든 부분이 바로 그 재료를 구하는 일이오. 내게 온전한 괴수의 가죽을 가지고 오면 강력한 물건을 몇 가지 만들어 줄 수 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3675, 'koKR', '가능성은 아마 백만 분의 일 정도일 거요! 일생에 한번 볼까 말까 한 그런 가죽이지! 내로라하는 세공인들조차도 무두질 과정에서 수백 번은 실패한 후에 온전한 가죽을 얻을 수 있으니까 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3676, 'koKR', '그 가죽을 실제로 구했다면? 음... 더 설명해 드리지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3677, 'koKR', '토륨 대장조합 가을 품목:$B$B이 시대의 모험가를 위한 각종 용품을 아주 저렴한 가격에 제공하고 있습니다! 찾기 힘든 재료를 어디서 구해야 하는지도 설명해 드립니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3693, 'koKR', '이 책의 제목은 장식체로 \'마우린 달슨의 일기\'라고 쓰여 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3694, 'koKR', '책장이 누렇게 변해 가는 일기장의 마지막 페이지가 펼쳐진 채로 있습니다.$B$B\"해럴드가 언데드로 변해버려 이제 무슨 일이 벌어질지 모르겠다. 안간힘을 써서 그를 가두고 문을 잠갔다. 열쇠를 감춰뒀는데, 효과가 있었으면 좋겠다...$B$B여기서 빠져나가고 싶지만 그러려면 돈이 든다. 우리 물건은 모두 장롱에 넣어 둔 것 같다... 그러고 보니 해럴드에게도 열쇠가 있지 않나?$B$B그건 일단 쉬고 나서 생각해야겠다. 너무 피곤하다.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3695, 'koKR', '너덜너덜한 누더기골렘 봉합실이 필요하다면 스트라솔름으로 떠나야지.$B$B한때는 빛의 수호자의 고향이었지만, 지금은 켈투자드의 졸개들이 들끓는 곳이라네.$B$B불타는 도시의 위험을 뚫고 살덩이 누더기골렘들을 쓰러뜨려! 놈들에게서 원하는 걸 챙기게. 바로 너덜너덜한 누더기골렘 봉합실 말이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3696, 'koKR', '광기에 빠진 광신도들의 마지막 성소지. 마법이 깃든 붉은십자군 실로 붉은 제복을 만드는 곳이라네!$B$B스트라솔름으로 가게, 모험가여!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3697, 'koKR', '사람이든 스컬지든 인정하는 최고의 시체 보존제, 바로 프로스트위스퍼의 방부액이지. 그걸 구할 수 있는 곳은 딱 하나뿐인데, 이름의 주인인 리치가 누가 찾아오는 걸 반길 것 같진 않군.$B$B그래도... 그 방부액이 필요하다면 스칼로맨스를 헤매야 할 거야...', '사람이든 스컬지든 인정하는 최고의 시체 보존제, 바로 프로스트위스퍼의 방부액이지. 그걸 구할 수 있는 곳은 딱 하나뿐인데, 이름의 주인인 리치가 누가 찾아오는 걸 반길 것 같진 않군.$B$B그래도... 그 방부액이 필요하다면 스칼로맨스를 헤매야 할 거야...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3698, 'koKR', '스칼로맨스가 세워진 땅은 바로브 가문이 켈투자드에게 넘긴 곳이다. 저주받은 자들의 교단이 스컬지의 사악한 마법을 익힐 장소를 내주는 대가로, 켈투자드는 바로브 가문에 언데드로서의 불멸을 선사했지.$B$B어둠의 저장고에서 어둠의 가죽과 그 주인인 여군주 일루시아 바로브를 찾을 수 있을 것이다.$B$B허영에 찬 망자에게 이보다 훌륭한 거울은 없겠지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3699, 'koKR', '토륨 대장조합에서 빠질 수 없는 물건이지.$B$B아케이나이트 수정은 풍부한 토륨 광맥에서 얻는다. 뛰어난 연금술사의 솜씨가 더해지면 아케이나이트 주괴가 탄생하지.$B$B광부가 아니라면 광부부터 찾고... 실력 좋은 연금술사도 찾아! 둘 다 필요할 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3734, 'koKR', '그 안에 담겨있는 게 무엇입니까, $n?$B$B<당신의 가방 밖으로 튀어나온 불타지 않은 판금 건틀릿을 가리키는 말리퍼스>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'koKR', '최전선에 온 것을 환영하네, $c|1이여;여;. 정치가들은 공모니, 음모니 해대며 자기네들끼리 싸우지만 여기서는 그런 사치를 찾아볼 수가 없을 거야. 이곳은 보루, 매일같이 생존을 위해 투쟁을 하는 곳이지.$B$B자신이 영웅임을 입증하러 온 것이라면 여러 가지 기회를 찾을 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3754, 'koKR', '최전선에 온 것을 환영하오, $c|1이여;여;. 스톰윈드 왕국은 동맹들의 도움과 더불어 나를 이곳으로 보내 점점 강해져 가는 스컬지의 위협을 막도록 했다오. 이곳 서리바람 야영지에서는 매일같이 생존을 위해 투쟁하고 있지.$B$B자신이 영웅임을 입증하러 온 것이라면 여러 가지 기회를 찾을 수 있을 것이오... 특히 요즘에는 안돌할로 밀고 들어가 그곳에서 스컬지를 지배하는 사악한 세력을 처치하고 있으니 더욱 싸울 기회가 많겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3755, 'koKR', '스트라솔름에서 스컬지에 맞서 싸우는 자들을 보니 흐뭇하군. 스컬지는 이곳에서 제일 강한 존재요.$B$B만나서 반갑소. 나는 아우리우스라고 하오. 한때는 은빛 성기사단의 일원이었는데, 신앙을 굳게 지키지 못한 다른 이들처럼 믿음을 잃어버렸지. 스컬지의 거짓된 유혹에 빠져, 하마터면 죽음의 기사가 될 뻔했다오!$B$B다행히 위험을 감지한 나는 이 교회로 도망쳐왔소. 이 장소는 최초의 성기사인 빛의 수호자 우서 경이 은빛 성기사단을 창단한 아주 성스러운 곳이', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3756, 'koKR', '이 세상에서 나의 시간은 얼마 남지 않았지만, 성스러운 빛이 허락한다면 충분히 나의 숙명과도 같은 임무를 완수할 수 있소. 당신이 리븐데어 남작과 맞설 때 나도 함께하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3757, 'koKR', '나를 내버려두시오. 상처가 너무 깊어 머지않아 죽게 될 것 같소. 고맙소, $n. 나는 여기서 죽지만 당신 덕분에 편안히 눈을 감을 수 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3758, 'koKR', '평범한 생명체여, 내 인내심을 시험하지 마라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3759, 'koKR', '입 닥치지 못할까! $R... 머리카락을 뽑아서 내 뿔을 닦는 데 쓰기 전에.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3760, 'koKR', '무얼 하고 있겠나. 당연히 생각하고, 한탄하고, 증오하고, 음모를 꾸미고 있지. 다 끝나면 다시 생각하고 한탄하고... 원하는 게 뭐냐? 생각할 것도 많은데.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3761, 'koKR', '너랑 의논을?$B$B<로락스가 껄껄 웃습니다.>$B$B네가 도움이 되리라고는 생각하지 않아.$B$B나는 이 폐허 속에 서서 꿈을 꾸지. 언젠가 고랄루크 앤빌크랙이라는 비열한 도둑놈을 잡는 꿈.$B$B우린 계약을 맺었지. 그런데 녀석은 약속을 깨뜨려버렸어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3762, 'koKR', '녀석에게 악마의 룬을 가르쳐주는 대신 녀석의 영혼을 받기로 했어. 사실, 검은바위일족 오크의 영혼은 별 가치가 없지만 요즘처럼 어려운 시기에는 어떤 영혼이든 없는 것보단 낫거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3763, 'koKR', '악마의 룬 가슴보호갑을 만드는 데 사용하는 벼리지 않은 룬문자 가슴보호갑을 갖고는 도망쳐버렸지. 영혼도 주지 않고 날랐어. 하지만 난 바보가 아니지... 벼리지 않은 룬문자 가슴보호갑은 악마의 룬을 모르면 아무 쓸모도 없거든.$B$B혹시... 검은바위 첨탑에 틀어 박혀서 악마의 룬 가슴보호갑을 만들려고 하는 게 아닐까? 거기서 떠날 배짱이 없는 건 알거든!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3793, 'koKR', NULL, '우리가 운고로 분화구에 머무르기 시작하면서, 다단가는 이곳에서 자라나는 붉은꽃잎덩굴손 씨눈에 맛을 들였어요.$B$B누군가 좀 모아서 가져다주면 우리 다단가에게 좋은 간식이 될 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3794, 'koKR', '여어, 친구. 필요한 물건을 조금만 구하면 당장에라도 자넬 치료해 줄 수 있을 텐데!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3795, 'koKR', '이렇게 봉사 활동을 하는 것도 의술사 수련의 일부라네. 자넨 날 도와줬으니 공짜로 도와주지. 어딜 고쳐 줄까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3797, 'koKR', '아... 전 큰 상처를 입었어요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3798, 'koKR', '$R, 제 말을 잘 들으세요...$B$B밤에 검은 용을 탄 자들이 나타나서 무서울 정도로 빠르고 정확하게 저 같은 어린 용을 낚아채 어둠 속으로 사라졌어요.$B$B저는 형제와 누이들이 녀석들의 실험에 이용되는 끔찍한 광경을 목격하게 됐죠. 우리의 정기를 이용해 유채용군단을 만들려는 거였어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3799, 'koKR', '그나마 네파리안은 적합하지 않은 실험 대상은 즉시 없애버리라고 명령했지만, 이 천벌 받을 괴물들은 죽을 때까지 끔찍한 고문을 가했어요.$B$B놈들은 우리를 철저하게 \'망가뜨린\' 후 목숨이 붙어 있는 자와 죽은 자를 모두 모아 이 악당들에게 던져주었지. 녀석들은 우리의 몸을 가지고 온갖 더러운 놀이를 했어요. 용암 속에 던져 넣기도 하고, 피에 굶주린 병사들에게 던져주기도 했죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3800, 'koKR', '녀석들이 날 저 밑에 있는 악마들에게 던지려던 찰나에 당신이 나타난 거예요. 정말로 고마워요. 혹시 제가, 아니, 우리 푸른용군단의 자손들이 당신을 도와줄 일이 있나요?$B$B아니면, 많은 위험을 무릅쓰고 여기까지 왔으니 조금만 더 힘을 내서 네파리안과 그의 검은바위일족 군단과 싸워주지 않겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3801, 'koKR', '용을 사냥하러 왔다면 내가 대접하겠소. 애도의 뜻은 어디로 전해야 하는 거요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3802, 'koKR', '자네한테서 나는 악취 때문에 수 킬로 멀리서도 용이 쫓아오겠군. 원하는 거나 빨리 말해보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3803, 'koKR', '자네가 올 거라고 영혼들이 말해주었다네. 어떤 이유로 날 찾아오긴 하는데 그 이유는 자네도 모를 것이라고 하더군. 그래, 이곳에 온 이유는 알고 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3804, 'koKR', NULL, '아, 안녕하세요! 난 사라라고 해요. 뭐, 도와드릴 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3805, 'koKR', NULL, '숲이 그대가 온다는 소식을 전해주긴 했는데 오는 이유에 대해서는 말하지 않더군요. 자, 제게 오신 이유를 말씀해 주시겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3806, 'koKR', '안녕하신가!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3807, 'koKR', NULL, '에메랄드 의회에서 당신을 환영합니다.$B$B당신과 함께 한때 울창했던 이 숲을 다시 일으켜 세우고 보호할 수 있었으면 합니다. 외부에서는 물론이고, 내부에 숨은 다양한 세력이 이 숲을 파괴하려 들고 있어요.$B$B이곳에 있는 힘에 넘어가지 마세요. 이 땅을 다 가진 듯 유혹하며 당신을 타락시킬 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3813, 'koKR', '그리핀을 타는 게 싫으신가 보군요. 다행히도 조금만 깊숙이 들어가시면 다른 방법으로 이동하실 수 있습니다. 깊은굴 지하철이라고 노움이 건설한 편리한 이동 수단인데, 드워프 지구 후미진 곳에서 탈 수 있습니다.', '그리핀을 타는 게 싫으신가 보군요. 다행히도 조금만 깊숙이 들어가시면 다른 방법으로 이동하실 수 있습니다. 깊은굴 지하철이라고 노움이 건설한 편리한 이동 수단인데, 드워프 지구 후미진 곳에서 탈 수 있습니다.', '깊은굴 지하철 개통 소식을 들으셨군요? 한번 타보세요. 아주 재미있지요! 드워프 지구 뒤편에 있습니다. 참, 지하철이 이동하는 동안에는 절대로 팔이나 머리를 바깥으로 내밀면 안 됩니다.', '깊은굴 지하철 개통 소식을 들으셨군요? 한번 타보세요. 아주 재미있지요! 드워프 지구 뒤편에 있습니다. 참, 지하철이 이동하는 동안에는 절대로 팔이나 머리를 바깥으로 내밀면 안 됩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3814, 'koKR', '그래요! 모두 지하철을 타보고 싶어 하지요. 정말 재미나거든요. 깊은굴 지하철은 아이언포지 성문에서 바로 동쪽에 있는 땜장이 마을에 있습니다.', '그래요! 모두 지하철을 타보고 싶어 하지요. 정말 재미나거든요. 깊은굴 지하철은 아이언포지 성문에서 바로 동쪽에 있는 땜장이 마을에 있습니다.', '아, 지하철 말입니까? 모두 지하철만 타려고 하는구먼. 목숨을 내놓고 그리핀 등에 올라 하늘 높이 날아오를 때, 땀이 꽉 찬 손으로 갈기를 꼭 붙잡는 그 짜릿한 맛... 이제 한물 간 건가?$b$b이것 참... 그럼 문명의 이기, 지하철이나 타시죠. 땜장이 마을에 가보면, 노움이 만든 여러 기계며, 복잡한 장치 사이에서 찾을 수 있을 겁니다.', '아, 지하철 말입니까? 모두 지하철만 타려고 하는구먼. 목숨을 내놓고 그리핀 등에 올라 하늘 높이 날아오를 때, 땀이 꽉 찬 손으로 갈기를 꼭 붙잡는 그 짜릿한 맛... 이제 한물 간 건가?$b$b이것 참... 그럼 문명의 이기, 지하철이나 타시죠. 땜장이 마을에 가보면, 노움이 만든 여러 기계며, 복잡한 장치 사이에서 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3815, 'koKR', '이 책에는 데스윙이라는 보다 강력한 용에 맞서 다른 용들이 단결하는 내용이 나와 있습니다. 이해한 바에 따르면, 오색용군단이 이 세계에 풀려 날 뻔했었고 위상들은 단단히 준비를 하고 있었다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3833, 'koKR', '상인의 정원에 경매장이 열렸습니다. 은행에서 남동쪽으로 길을 따라가면 쉽게 찾을 수 있을 겁니다.', '상인의 정원에 경매장이 열렸습니다. 은행에서 남동쪽으로 길을 따라가면 쉽게 찾을 수 있을 겁니다.', '아, 그대는 물질적인 부유함에 대해 지나치게 신경을 쓰시는군요. 재물운이 따르는 분이라면 이곳 상인의 정원에서 경매장을 찾으실 수 있을 겁니다.', '아, 그대는 물질적인 부유함에 대해 지나치게 신경을 쓰시는군요. 재물운이 따르는 분이라면 이곳 상인의 정원에서 경매장을 찾으실 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3834, 'koKR', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', '아, 또 경매인이로군. 경매장은 상업 지구에서 찾을 수 있을 겁니다. 은행에서 멀지 않은 곳에 있지요.', '아, 또 경매꾼이로군. 경매장은 상업 지구에서 찾을 수 있을 겁니다. 은행에서 멀지 않은 곳에 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3854, 'koKR', '여행자여, 반갑소. 나를 만난 걸 행운으로 여겨야 할 거요. 동부 왕국에서 나를 만난 자는 아주 드무니까 말이오.$B$B내 이름은 리베른... 여명의 설원 눈호랑이를 탈것으로 훈련시킨다오.$B$B이 눈호랑이는 가장 사납고 다루기 어려운 맹수 중의 맹수요. 신뢰와 확고한 동맹으로 인정받는 자만이 탈 수 있다오.$B$B아무에게나 팔지는 않을 뿐 더러 열심히 노력해서 나뿐만 아니라, 눈호랑이에게서도 인정받아야만 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3855, 'koKR', '존재하는 것으로 추정. 상급 오색용혈족이나 오색용만이 이러한 등껍질을 보유할 수 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3856, 'koKR', '새끼용이나 하급 고룡족과 같은 하급 오색용군단에게서 흔히 찾을 수 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3857, 'koKR', '전설에 의하면 현재 역병지대라는 지역에서 극심한 충돌이 있었던 장소에는 땅에서 깨끗하고 신성한 샘물이 솟아오르기도 한다고 전해진다. 전쟁에서 스컬지에 의해 쓰러진 자들을 기리는 뜻에서 대가와 일반인 할 것 없이 모두 이러한 샘에서 나는 물을 \'영웅의 피\'라고 불렀다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3859, 'koKR', '이 거울은 스칼로맨스의 바로브 가가 더 이상 자신들이 소유하지 않는 영혼들을 비춰 보는 데 사용되는 아주 귀중한 유품이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3860, 'koKR', '아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', '아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', '아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', '아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3861, 'koKR', '스톰윈드 곳곳에 우체통이 깔렸습니다. 경매장, 은행 혹은 여관 앞에서도 찾아보실 수 있습니다.', '스톰윈드 곳곳에 우체통이 깔렸습니다. 경매장, 은행 혹은 여관 앞에서도 찾아보실 수 있습니다.', '우체통은 도대체 어떻게 만들어진 건지 모르겠습니다. 그 안에 무슨 마법의 문 같은 게 틀림없이 들어 있을 거예요. 스톰윈드 은행 옆에 있는 우체통 앞에 하루 종일 인파가 모여들어 그 작은 통에서 검이며 방패, 온갖 방어구를 꺼내더란 말입니다!', '우체통은 도대체 어떻게 만들어진 건지 모르겠습니다. 그 안에 무슨 마법의 문 같은 게 틀림없이 들어 있을 거예요. 스톰윈드 은행 옆에 있는 우체통 앞에 하루 종일 인파가 모여들어 그 작은 통에서 검이며 방패, 온갖 방어구를 꺼내더란 말입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3864, 'koKR', NULL, '$C|1이여;여;, 안녕하세요. 저는 제시르 문보우라고 해요. 두 명의 친구들을 찾기 위해 다르나서스에서 왔지요. 그들은 악령숲에 숨어 있다는 어둠의 의회에 대한 단서를 찾으러 떠났었죠.$B$B오크족의 고통에 많은 부분 책임이 있는 사악한 생물들이 다시 예전의 힘을 되찾으려는 것 같아요.$B$B제 두 친구들은 무슨 일이 일어나고 있는지 알아보려고 제데나르를 조사하러 갔답니다.$B$B제가 여기 도착하면 친구들이 와 있을 줄 알았는데 벌써 예정된 날짜를 며', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3865, 'koKR', NULL, '춥고 배도 고팠을 텐데...$B$B불쌍한 내 친구, 이제라도 편안해졌기를 빌게. 그놈들이 네게 무슨 짓을 했는지는 난 상상도 하기 싫어.$B$B이 보세요! 거기 잠깐만요! 저 좀 도와 주세요. 제발... 여기서 꼭 탈출해야 해요. 놈들 중 하나에게 열쇠가 있는데, 좀 찾아 주세요. 그 잔인무도한 녀석들이 가지고 있다고요. 열쇠 좀 찾아 주세요. 여기서 빠져나갈 수 있도록. 트레이는 벌써 죽었을 지도 모르지만 아직 시간은 있다고요! 제발 저 좀 도와 주세', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3866, 'koKR', NULL, '안녕하세요! 저는 남서쪽에 있는 켈테릴의 폐허를 조사하고 돌아왔답니다. 지금은 이곳 올빼미날개 숲의 산마루 위에 있는 올빼미야수들을 조사하는데 집중하고 있지요.$B$B루테란 마을에 있는 에렐라스 앰버스카이와 얘기해 본 적 있나요? 그가 절 이곳으로 와달라고 요청했었답니다. 아마도 그가 당신에게 임무를 줄 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3868, 'koKR', NULL, '순찰대원 바커스를 본 적 있나요? 얼마나 용맹스러운지...$B$B그가 모든 어둠의 순찰대원 중에서 제일 힘이 센 것 같아요. 내가 주변에 있다는 걸 그가 알기라도 할지 모르겠네요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3873, 'koKR', '고맙습니다! 절 해방시켜 주셨어요.', '고맙습니다! 절 해방시켜 주셨어요.', '아, 고맙습니다! 이 악몽에 너무 오랫동안 갇혀 있었어요...', '아, 고맙습니다! 이 악몽에 너무 오랫동안 갇혀 있었어요...', '드디어 제 영혼이 해방되었군요!', '드디어 제 영혼이 해방되었군요!', '감사합니다! 다로우샤이어 전투 이후, 이 끔찍한 운명의 속박을 피할 수 없었지만 당신이 절 해방시켜 주셨군요!', '고마워요! 다로우샤이어 전투가 날 저주했지만, 당신이 날 해방해 줬어요!', '아! 다로우샤이어에서 생존자를 보게 되시거든 제가 풀려났다고 전해 주세요!', '아! 다로우샤이어에서 생존자를 보게 되시거든 제가 풀려났다고 전해 주세요!', NULL, NULL, NULL, NULL, NULL, NULL),
(3874, 'koKR', NULL, '에메랄드 의회에서는 상처받은 악령숲을 치유하기 위해 노력하고 있어요. 비록 이 땅을 타락시킨 것의 이름을 따서 악령숲이긴 하지만, 언젠가 이 땅에서 그 타락을 완전히 뿌리 뽑을 수 있는 날이 오기만을 바라요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3893, 'koKR', '저그 저그, 용감한 $c|1이여;여;! 내겐 호드에서 제일 알아주는 늑대들이 있지. 자네도 꼭 한번은 봐야 해... 어떤 곳에서도 이보다 더 생존 본능이 뛰어나고 지구력이 강한 늑대는 찾아볼 수 없을 걸세! 직접 한번 시승해 보는 건 어때?', '저그 저그, 용감한 $c|1이여;여;! 내겐 호드에서 제일 알아주는 늑대들이 있지. 자네도 꼭 한번은 봐야 해... 어떤 곳에서도 이보다 더 생존 본능이 뛰어나고 지구력이 강한 늑대는 찾아볼 수 없을 걸세! 직접 한번 시승해 보는 건 어때?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3896, 'koKR', '안녕하십니까, 용감한 $c님. 훌륭한 탈것을 구하시는 것 같은데 그렇다면 랩터만큼 훌륭한 탈것도 없답니다! 제가 파는 것들을 한번 둘러보십시오. 전 어디서도 찾아볼 수 없는 사나운 놈들만 취급한답니다.', '안녕하십니까, 용감한 $c님. 훌륭한 탈것을 구하시는 것 같은데 그렇다면 랩터만큼 훌륭한 탈것도 없답니다! 제가 파는 것들을 한번 둘러보십시오. 전 어디서도 찾아볼 수 없는 사나운 놈들만 취급한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3935, 'koKR', '저는 시체를 받아서 구덩이에 던져 넣어 처리하는 일을 하고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3937, 'koKR', '안녕하시오, $n. 나는 대용광로 관리인, 미올로 선더퓨리라고 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3938, 'koKR', '$n, 당신의 대장기술은 아주 뛰어나군. 이제 결정을 내릴 때가 됐소. 두 가지 길을 선택할 수 있소. 무기제작자의 길을 걷든가, 방어구제작자의 기술을 배우든가 양자택일하시오.$B$B한 가지 주의할 점은, 한번 결정을 내리면 돌이킬 수 없다는 거요. 어느 것을 택하든 일단 하나를 선택하면 다른 것은 배울 수 없지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3939, 'koKR', NULL, '$g형제:자매;여. 스컬지에게서 밤을 다시 빼앗을 때가 되었습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3940, 'koKR', NULL, '$g형제:자매;여. 스컬지에게서 밤을 다시 빼앗을 때가 되었습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3942, 'koKR', '엘룬의 은총으로 그대에게 텔드랏실 최고의 탈것인 밤호랑이를 보여 드리게 된 것을 진심으로 기쁘게 생각합니다. 오랫동안 파수대는 이 밤호랑이 친구를 믿고 의지해 왔습니다.$B$B맘에 드는 게 있는지 천천히 살펴보십시오. 결코 실망하시는 일은 없을 겁니다.', '엘룬의 은총으로 그대에게 텔드랏실 최고의 탈것인 밤호랑이를 보여 드리게 된 것을 진심으로 기쁘게 생각합니다. 오랫동안 파수대는 이 밤호랑이 친구를 믿고 의지해 왔습니다.$B$B맘에 드는 게 있는지 천천히 살펴보십시오. 결코 실망하시는 일은 없을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3944, 'koKR', '그게... 그 기계타조를 타시기에는 좀 체격이 너무 크신 것 같은데요? 손님이 기계타조를 타시면 미세하게 조정된 서보 평형 유지 장치가 부서져 버릴 것 같아요!', '그게... 그 기계타조를 타시기에는 좀 체격이 너무 크신 것 같은데요? 손님이 기계타조를 타시면 미세하게 조정된 서보 평형 유지 장치가 부서져 버릴 것 같아요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3945, 'koKR', '빠르고 안전한 이동 수단을 찾으신다면 제대로 찾아오신 겁니다! 올해 신형 기계타조 모델이 최근에 들어왔어요, 왔어. 전부 다 보여 드리도록 하죠!', '빠르고 안전한 이동 수단을 찾으신다면 제대로 찾아오신 겁니다! 올해 신형 기계타조 모델이 최근에 들어왔어요, 왔어. 전부 다 보여 드리도록 하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3953, 'koKR', '나는 자네 정도의 수준에 이른 대장장이들에게 선택을 하도록 하지.$B$B반드시 선택을 해야 하는 건 아니지만, 그편이 더 좋을 거야. 어쨌거나 평생 남의 밑에서 있을 수만은 없지 않나? 우리 군대가 전쟁에서 승리하여 갈채를 받는 데 있어 주인공은 바로 물자를 보급하는 전문 방어구제작자와 무기제작자들이야!$B$B$n, 한 가지 주의를 줄 게 있네. 한번 선택을 하고 주어진 임무를 마치고 나면 돌이킬 수 없어. 오직 한 길을 걸어갈 수 있을 뿐이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3954, 'koKR', '나는 크라토크라고 하네. 이 대장장이들을 감독하고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3959, 'koKR', '반갑군, $r.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3960, 'koKR', '어서 오게, $c 친구!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3961, 'koKR', '왜 이러는 거요?', '왜 이러는 거예요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3974, 'koKR', '성스러운 빛이 함께하기를, $c|1이여;여;. 무엇을 도와 드릴까요?', '성스러운 빛이 함께하기를, $c|1이여;여;. 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3975, 'koKR', '당신이 은빛 성기사단처럼 성스러운 빛을 추종하는 건 아니지만, 언제든 저희에게 도움을 청하셔도 좋습니다.', '당신이 은빛 성기사단처럼 성스러운 빛을 추종하는 건 아니지만, 언제든 저희에게 도움을 청하셔도 좋습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3976, 'koKR', '성스러운 빛의 가호가 함께하길.', '성스러운 빛의 가호가 함께하길.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3977, 'koKR', '성스러운 빛의 가호가 함께하길.', '성스러운 빛의 가호가 함께하길.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3978, 'koKR', '뼈가 훤히 다 드러난 내 무릎이 쑤시는 걸 보니, 곧 굉장한 비바람이 불어오겠구먼. 그 폭풍에 갇히지나 않았으면 좋겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3979, 'koKR', '자 이제, 저 가마솥들에 작업을 시작해 봅시다, $n! 우리가 필요로 하는 재료들을 모으려면 나한테서 유리질 집중기를 하나 받아 가십시오. 스컬지에게서 가마솥들을 전환시키는 데 필요한 재료를 제대로 알아보려면 이게 있어야 하니까요.$B$B그리고 가마솥들에 사용할 비전 촉매제도 한 번 쓸 분량만큼 필요할 겁니다. 값도 싸지 않은 데다 안정성 있는 물건도 아니지만... 일단 그걸 구한 다음에는 30분이 지나면 못쓰게 되니 그 전에 사용해야 할 겁니다. 그러', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3980, 'koKR', '자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 골성 교반기 6개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 해골 언데드에게서 골성 교반기를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3981, 'koKR', '자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 체세포 강화물질 5개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 좀비나 구울 언데드에게서 체세포 강화물질을 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3982, 'koKR', '자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 체세포 강화물질 5개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 좀비나 구울 언데드에게서 체세포 강화물질을 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3983, 'koKR', '자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 심령 공명체 4개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 있으면 이곳 역병지대에 있는 망령이나 유령 언데드에게서 심령 공명체를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3984, 'koKR', '하는 일에 비하면 보수가 형편 없어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3985, 'koKR', '자 이제, 저 가마솥들에 작업을 시작해 봅시다, $n! 우리가 필요로 하는 재료들을 모으려면 나한테서 유리질 집중기를 하나 받아 가십시오. 스컬지에게서 가마솥들을 전환시키는 데 필요한 재료를 제대로 알아보려면 이게 있어야 하니까요.$B$B그리고 가마솥들에 사용할 비전 촉매제도 한 번 쓸 분량만큼 필요할 겁니다. 값도 싸지 않은 데다 안정성 있는 물건도 아니지만... 일단 그걸 구한 다음에는 30분이 지나면 못쓰게 되니 그 전에 사용해야 할 겁니다. 그러', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3996, 'koKR', '이 지역에는 아직도 스컬지의 역병이 만연해 있고 역병을 변형시켜 스컬지에 영향을 주기까지는 아직 한참이나 남았습니다. 필요한 재료를 모아 전쟁에 도움을 주십시오!', '이 지역에는 아직도 스컬지의 역병이 만연해 있고 역병을 변형시켜 스컬지에 영향을 주기까지는 아직 한참이나 남았습니다. 필요한 재료를 모아 전쟁에 도움을 주십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3997, 'koKR', '스컬지의 역병이 거의 전환 단계에 이르렀습니다. 조금만 더 가마솥 전복을 시도하면 우리가 우세해지게 될 겁니다! 당신도 도와 주십시오!', '스컬지의 역병이 거의 전환 단계에 이르렀습니다. 조금만 더 가마솥 전복을 시도하면 우리가 우세해지게 될 겁니다! 당신도 도와 주십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3998, 'koKR', '스컬지의 역병을 스컬지에게 역이용하기 시작했지만 아직은 미약한 수준입니다. 녀석들의 가마솥을 전복시켜 우리를 도와 주십시오!', '스컬지의 역병을 스컬지에게 역이용하기 시작했지만 아직은 미약한 수준입니다. 녀석들의 가마솥을 전복시켜 우리를 도와 주십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3999, 'koKR', '우리가 스컬지를 제압하고 있습니다. 변형된 역병의 효과는 적어도 만 하루 동안 더 지속될 것입니다! 하지만 계속해서 우세를 유지해야 하니 기회가 오면 꼭 가마솥 하나를 파괴해 주십시오.', '우리가 스컬지를 제압하고 있습니다. 변형된 역병의 효과는 적어도 만 하루 동안 더 지속될 것입니다! 하지만 계속해서 우세를 유지해야 하니 기회가 오면 꼭 가마솥 하나를 파괴해 주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4013, 'koKR', '소타르라는 상급 사냥꾼이 있긴 하지. 칼바위 언덕 남서쪽에 있는 지하실 안에서 찾아보게.', '소타르라는 상급 사냥꾼이 있긴 하지. 칼바위 언덕 남서쪽에 있는 지하실 안에서 찾아보게.', '자네도 사냥꾼인가? 어쨌든, 칼바위 언덕 남서쪽에 있는 어두컴컴한 지하실에서 태양을 피하고 있는 소타르를 찾아가 봐.', '자네도 사냥꾼인가? 어쨌든, 칼바위 언덕 남서쪽에 있는 어두컴컴한 지하실에서 태양을 피하고 있는 소타르를 찾아가 봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4014, 'koKR', '남쪽에 있는 센진 마을로 가서 운투와와 얘기해 보게.', '남쪽에 있는 센진 마을로 가서 운투와와 얘기해 보게.', '트롤에게 가봐. 남쪽에 있는 센진 마을로 가서 운투와를 찾아보게.', '트롤에게 가봐. 남쪽에 있는 센진 마을로 가서 운투와를 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4015, 'koKR', '타이진을 찾고 있군. 칼바위 언덕 동쪽에 있는 병영에서 찾아보게.', '타이진을 찾고 있군. 칼바위 언덕 동쪽에 있는 병영에서 찾아보게.', '타이진이라고 하는 여자를 찾아가보게. 칼바위 언덕 동쪽에 있는 병영 안에 있을 게야. 당신에게 신을 공경하는 법을 가르쳐 줄걸. 단, 당신이 그녀를 공경하는 태도를 보일 때의 얘기지.', '타이진이라고 하는 여자를 찾아가보게. 칼바위 언덕 동쪽에 있는 병영 안에 있을 게야. 당신에게 신을 공경하는 법을 가르쳐 줄걸. 단, 당신이 그녀를 공경하는 태도를 보일 때의 얘기지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4016, 'koKR', '카플라크와 얘기해 보게. 칼바위 언덕 남서쪽에 있는 지하실 위에 서 있을 거야.', '카플라크와 얘기해 보게. 칼바위 언덕 남서쪽에 있는 지하실 위에 서 있을 거야.', '카플라크는 왜 찾는 겐가? 뭐, 그야 내가 신경 쓸 일은 아니지만. 칼바위 언덕 남서쪽에 있는 지하실 위를 찾아보게. 그를 만나면 가방 단속은 단단히 하도록 하게.', '카플라크는 왜 찾는 겐가? 뭐, 그야 내가 신경 쓸 일은 아니지만. 칼바위 언덕 남서쪽에 있는 지하실 위를 찾아보게. 그를 만나면 가방 단속은 단단히 하도록 하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4017, 'koKR', '스워트를 찾아가야 해. 칼바위 언덕 동쪽에 있는 병영 안에서 찾아보게.', '스워트를 찾아가야 해. 칼바위 언덕 동쪽에 있는 병영 안에서 찾아보게.', '대족장님이 주도하고 계시는 개혁의 바람은 분명 호드에게 승리를 안겨 줄 거야! 참, 주술사라고? 마을 동쪽에 있는 병영 안에서 스워트를 찾게.', '대족장님이 주도하고 계시는 개혁의 바람은 분명 호드에게 승리를 안겨 줄 거야! 참, 주술사라고? 마을 동쪽에 있는 병영 안에서 스워트를 찾게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4018, 'koKR', '칼바위 언덕 동쪽, 병영 뒤편으로 가게. 두그루 고어러스트를 찾아.', '칼바위 언덕 동쪽, 병영 뒤편으로 가게. 두그루 고어러스트를 찾아.', '두그루 고어러스트는 마을 동쪽에 있는 병영 뒤편에 숨어 있지. 그는 왜 찾는가? 당신 혹시 불타는 군단과 한통속이야? 그런 일은 없길 바라네. 그렇다면 내 손으로 당신을 체포해야 하니까 말이야.', '두그루 고어러스트는 마을 동쪽에 있는 병영 뒤편에 숨어 있지. 그는 왜 찾는가? 당신 혹시 불타는 군단과 한통속이야? 그런 일은 없길 바라네. 그렇다면 내 손으로 당신을 체포해야 하니까 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4019, 'koKR', '칼바위 언덕 동쪽에 있는 병영에서 타쇼 재기드스카를 찾아보게.', '칼바위 언덕 동쪽에 있는 병영에서 타쇼 재기드스카를 찾아보게.', '칼바위 언덕 동쪽에 있는 병영 안에서 타쇼 재기드스카를 찾아보게. 호드의 젊은이들에게 자부심과 명예를 가져다주기를!', '칼바위 언덕 동쪽에 있는 병영 안에서 타쇼 재기드스카를 찾아보게. 호드의 젊은이들에게 자부심과 명예를 가져다주기를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4020, 'koKR', '남쪽에 있는 센진 마을로 가서 미아오잔을 찾아보게.', '남쪽에 있는 센진 마을로 가서 미아오잔을 찾아보게.', '센진 마을에는 미아오잔이라고 하는 트롤이 물약을 제조한다더군. 그곳에 가보지그래.', '센진 마을에는 미아오잔이라고 하는 트롤이 물약을 제조한다더군. 그곳에 가보지그래.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4021, 'koKR', '드우크 말이로군. 칼바위 언덕 북서쪽에 있는 가열로 옆에서 일하고 있을 거야.', '드우크 말이로군. 칼바위 언덕 북서쪽에 있는 가열로 옆에서 일하고 있을 거야.', '스스로 호드를 위한 무기와 방어구를 만들기 위해, 단단한 금속을 두드릴 힘이 있다고 생각이 들거든, 칼바위 언덕의 북서쪽으로 가게. 가열로 옆에 있는 드우크를 찾아가.', '스스로 호드를 위한 무기와 방어구를 만들기 위해, 단단한 금속을 두드릴 힘이 있다고 생각이 들거든, 칼바위 언덕의 북서쪽으로 가게. 가열로 옆에 있는 드우크를 찾아가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4022, 'koKR', '북쪽으로 난 길을 따라 오그리마로 가게. 그곳 그런트에게 어디로 가면 요리를 배울 수 있는지 다시 한번 물어보게.', '북쪽으로 난 길을 따라 오그리마로 가게. 그곳 그런트에게 어디로 가면 요리를 배울 수 있는지 다시 한번 물어보게.', '엄... 요리 말인가? 북쪽에 있는 오그리마로 가야겠군. 그리 멀지는 않지. 그곳에 도착하면 그런트에게 다시 한번 물어봐야 할 거야.', '엄... 요리 말인가? 북쪽에 있는 오그리마로 가야겠군. 그리 멀지는 않지. 그곳에 도착하면 그런트에게 다시 한번 물어봐야 할 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4023, 'koKR', '오그리마에 한 명 있지. 그곳에 있는 그런트가 길을 더 자세히 가르쳐 줄 거야. 여기서 길을 따라 북쪽으로 가기만 하면 바로 보여.', '오그리마에 한 명 있지. 그곳에 있는 그런트가 길을 더 자세히 가르쳐 줄 거야. 여기서 길을 따라 북쪽으로 가기만 하면 바로 보여.', '이 부근에 그런 일을 하는 자는 없네. 북쪽에 있는 오그리마에는 있을지도 모르지. 그곳 그런트에게 물어보는 게 제일 좋겠군.', '이 부근에 그런 일을 하는 자는 없네. 북쪽에 있는 오그리마에는 있을지도 모르지. 그곳 그런트에게 물어보는 게 제일 좋겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4024, 'koKR', '칼바위 언덕에 전문 기계공학자가 한 명 있지. 머크드락이라고 하는데, 보통 가열로 근처에 볼 수 있다네.', '칼바위 언덕에 전문 기계공학자가 한 명 있지. 머크드락이라고 하는데, 보통 가열로 근처에 볼 수 있다네.', '흥, 그런 건 고블린이나 손을 대는 일인데! 뭐, 그래도 이 칼바위 언덕에도 그런 걸 가르쳐 줄 오크가 한 명 있긴 해. 가열로 근처에 있는 머크드락을 찾아보게.', '흥, 그런 건 고블린이나 손을 대는 일인데! 뭐, 그래도 이 칼바위 언덕에도 그런 걸 가르쳐 줄 오크가 한 명 있긴 해. 가열로 근처에 있는 머크드락을 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4025, 'koKR', '칼바위 언덕 동쪽에 있는 병영 안으로 들어가보게. 로울크를 찾아.', '칼바위 언덕 동쪽에 있는 병영 안으로 들어가보게. 로울크를 찾아.', '이렇게 싸움을 많이 하는데 칼바위 언덕에 응급치료사가 없겠나? 동쪽에 있는 병영 안에서 로울크를 찾아보게.', '이렇게 싸움을 많이 하는데 칼바위 언덕에 응급치료사가 없겠나? 동쪽에 있는 병영 안에서 로울크를 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4026, 'koKR', '남쪽에 있는 검은창 해안에서 라우티키라는 트롤이 낚시를 하는 걸 본 적 있네. 센진 마을 바로 외곽에 있지.', '남쪽에 있는 검은창 해안에서 라우티키라는 트롤이 낚시를 하는 걸 본 적 있네. 센진 마을 바로 외곽에 있지.', '라우티키를 찾는군. 남쪽에 있는 센진 마을 바로 외곽에 있는 검은창 해안으로 가. 그곳에서 만날 수 있을 거야.', '라우티키를 찾는군. 남쪽에 있는 센진 마을 바로 외곽에 있는 검은창 해안으로 가. 그곳에서 만날 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4027, 'koKR', '미시키를 찾고 있군. 남쪽에 있는 센진 마을로 가보게. 그녀의 오두막을 찾아.', '미시키를 찾고 있군. 남쪽에 있는 센진 마을로 가보게. 그녀의 오두막을 찾아.', '꽃이라고? 이런 황무지에서 말인가? 그런 걸 찾는 법을 가르쳐 줄 이가 호드에 있으려나? 아, 남쪽에 있는 센진 마을로 한번 가보게. 미시키라면 뭔가 알 거야.', '꽃이라고? 이런 황무지에서 말인가? 그런 걸 찾는 법을 가르쳐 줄 이가 호드에 있으려나? 아, 남쪽에 있는 센진 마을로 한번 가보게. 미시키라면 뭔가 알 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4028, 'koKR', '오그리마로 가야할 걸세. 칼바위 언덕에서 나가는 북쪽 길을 따라 협곡을 통과하면 오그리마에 이르게 되지. 그곳에서 그런트 중 한 명에게 길을 더 자세히 물어보게.', '오그리마로 가야할 걸세. 칼바위 언덕에서 나가는 북쪽 길을 따라 협곡을 통과하면 오그리마에 이르게 되지. 그곳에서 그런트 중 한 명에게 길을 더 자세히 물어보게.', '가죽세공을 배우려면 북쪽에 있는 오그리마로 가야 하네. 오그리마 그런트에게 물어보면, 가죽세공을 어디서 배울 수 있는지 가르쳐줄 걸세.', '가죽세공을 배우려면 북쪽에 있는 오그리마로 가야 하네. 오그리마 그런트에게 물어보면, 가죽세공을 어디서 배울 수 있는지 가르쳐줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4029, 'koKR', '물론, 이 칼바위 언덕에 광부 하나쯤은 살고 있지. 북서쪽 여관 옆에서 크룬을 찾아보게.', '물론, 이 칼바위 언덕에 광부 하나쯤은 살고 있지. 북서쪽 여관 옆에서 크룬을 찾아보게.', '듀로타에는 채광을 하기 좋은 곳이 많다고 하더군. 그래서, 이 칼바위 언덕에도 광부가 하나 머물고 있지. 북서쪽에 있는 가열로 옆에서 크룬을 찾아보게.', '듀로타에는 채광을 하기 좋은 곳이 많다고 하더군. 그래서, 이 칼바위 언덕에도 광부가 하나 머물고 있지. 북서쪽에 있는 가열로 옆에서 크룬을 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4030, 'koKR', '무두장이라면 오그리마에 있네. 칼바위 언덕에서 나가는 길을 따라 북쪽으로 가. 도착한 후에 오그리마 그런트에게 물어봐.', '무두장이라면 오그리마에 있네. 칼바위 언덕에서 나가는 길을 따라 북쪽으로 가. 도착한 후에 오그리마 그런트에게 물어봐.', '여긴 없고, 오그리마에 한 명 있지. 북쪽으로 가서 그런트에게 다시 물어보게.', '여긴 없고, 오그리마에 한 명 있지. 북쪽으로 가서 그런트에게 다시 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4031, 'koKR', '오그리마로 가야겠군. 칼바위 언덕에서 나가는 북쪽 길로 곧장 가게. 그곳 그런트에게 물어보면 길을 더 자세히 가르쳐 줄걸.', '오그리마로 가야겠군. 칼바위 언덕에서 나가는 북쪽 길로 곧장 가게. 그곳 그런트에게 물어보면 길을 더 자세히 가르쳐 줄걸.', '재봉술이라고? 북쪽에 있는 오그리마로 가면 배울 수 있을지도 모르지. 그곳 그런트에게 물어보게.', '재봉술이라고? 북쪽에 있는 오그리마로 가면 배울 수 있을지도 모르지. 그곳 그런트에게 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4032, 'koKR', '은행? 오그리마에 있지. 길을 따라 북쪽으로 가면 된다고. 그런 다음 그곳 그런트 중 한 명에게 다시 물어봐.', '은행? 오그리마에 있지. 길을 따라 북쪽으로 가면 된다고. 그런 다음 그곳 그런트 중 한 명에게 다시 물어봐.', '아, 보관해 둘 물건이라도 있나보군. 길을 따라 북쪽으로 오그리마까지 가게. 그곳 그런트 중 한 명에게 다시 물어봐.', '아, 보관해 둘 물건이라도 있나보군. 길을 따라 북쪽으로 오그리마까지 가게. 그곳 그런트 중 한 명에게 다시 물어봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4033, 'koKR', '와이번 조련사는 오그리마에서 찾을 수 있지. 길을 따라 북쪽으로 가서 오그리마 그런트에게 물어보면 더 자세히 가르쳐 줄 거야.', '와이번 조련사는 오그리마에서 찾을 수 있지. 길을 따라 북쪽으로 가서 오그리마 그런트에게 물어보면 더 자세히 가르쳐 줄 거야.', '지금 한창 바쁜 거 안 보이나? 오그리마로 가서 그곳 그런트에게나 물어 봐. 오그리마는 쉽게 찾을 수 있겠지? 북쪽 길을 따라 가!', '지금 한창 바쁜 거 안 보이나? 오그리마로 가서 그곳 그런트에게나 물어 봐. 오그리마는 쉽게 찾을 수 있겠지? 북쪽 길을 따라 가!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4034, 'koKR', '크아, 나도 한잔 들이켜면서 쉬고 싶군. 칼바위 언덕 북서쪽으로 가보게. 도착하면 여관주인 그로스크에게 내 안부나 전해 주게.', '크아, 나도 한잔 들이켜면서 쉬고 싶군. 칼바위 언덕 북서쪽으로 가보게. 도착하면 여관주인 그로스크에게 내 안부나 전해 주게.', '칼바위 언덕에 병영 말고 또 다른 커다란 건물이 있네. 그게 바로 여관이지. 그 안으로 들어가 여관주인 그로스크에게 말을 건네보게. 알겠나?', '칼바위 언덕에 병영 말고 또 다른 커다란 건물이 있네. 그게 바로 여관이지. 그 안으로 들어가 여관주인 그로스크에게 말을 건네보게. 알겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4035, 'koKR', '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4036, 'koKR', '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4037, 'koKR', '어떤 물건을 찾으시나요?', '무엇을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4039, 'koKR', NULL, '가마솥에 침투했으니 이제 주변에 반작용 물질을 투입할 수 있게 됐어요. 이렇게 하면 스컬지가 자신들이 퍼뜨린 역병에 되려 당하게 되는 거죠!$B$B연금술사 알빙턴과 대화하여 가마솥에 사용해야 할 재료에 대한 정보를 얻도록 하세요. 스컬지에게 역병을 역이용하는 것에 대한 전체적인 상황 보고 정보는 모두 제가 처리할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4040, 'koKR', NULL, '가마솥에 침투했으니 이제 주변에 반작용 물질을 투입할 수 있게 됐습니다. 이렇게 하면 스컬지가 자신들이 퍼뜨린 역병에 되려 당하게 되는 겁니다!$B$B연금술사 디더스와 대화하여 가마솥에 사용해야 할 재료에 대한 정보를 얻도록 하세요. 스컬지에게 역병을 역이용하는 것에 대한 전체적인 상황 보고 정보는 모두 제가 처리할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4041, 'koKR', NULL, '안녕하세요? 저는 에바 사크호프라고 하고 이쪽은 제 남편 루시앙입니다. 만나 뵙게 돼서 반갑습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4042, 'koKR', NULL, '물론이죠. 저희들은 한때 바로브 가의 하인이었습니다. 지금은 스칼로맨스라고 부르지요.$B$B저는 하녀장이었고 제 남편 루시앙은 바로브 어르신의 집사였답니다.$B$B바로브 가에서 수십 년 동안을 일해 왔었는데 그만...$B$B<흐느끼는 에바>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4043, 'koKR', NULL, '오, 정말 끔찍해요. 한때 바로브 저택은 생기가 넘쳐나고 매우 호화로운 곳이었죠. 바로브 가의 드넓은 제국 중에서도 이 저택은 가문의 주 거주지였어요.$B$B시간이 흐르면서 루시앙과 저는 바로브 가문이 점점 침체해 가는 것을 느꼈어요. 주인님과 마님은 신경이 예민해지고 늘 불같이 화를 내셨죠. 밤에는 가족들이 방에서 서로 말다툼을 벌이는 소리가 들려 왔는데, 저희가 들은 바로는, 그러니까 말하자면, 탐욕의 둑이 터진 것 같았어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4044, 'koKR', NULL, '자신들의 수명이 다하고 난 뒤에도 재산과 땅을 지키기 위해 켈투자드라는 강력한 인간 마법사와 거래를 했던 것 같아요.$B$B<몸서리치는 에바>$B$B그 거래로 인해 강령술 학교가 세워졌죠. 그 학교에서 저주받은 자들의 교단이 생겨났고 그 장소는 그들의 본거지가 되었습니다.$B$B바로브가는 점점 더 허물어져 갔어요.$B$B저택 곳곳에는 암흑의 존재가 자리를 잡기 시작했고 도저히 저택을 유지할 수 없게 되었죠. 너무 역겹기까지 했답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4045, 'koKR', NULL, '어디로 가란 말이죠? 저희는 당시에도, 그 이전에도, 또 그 이후에도 바로브 가 외에는 아무것도 몰랐는 걸요.$B$B결국 우리는 바로브 가와 연락이 끊어졌고 마침내 바로브 가를 떠났답니다. 다른 하인들이 어떻게 됐는지는 몰랐어요. 비명 소리가 났다는 것밖에는... 고문을 당하는 비명 소리 말이에요.$B$B루시앙과 나는 달리 갈 곳이 없다는 걸 알았기 때문에 숙소에 숨어 있어야만 했어요. 학교가 비교적 조용한 낮 동안에 루시앙이 몰래 나가서 먹을 것과 마', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4046, 'koKR', NULL, '우린 여섯 달 정도 이렇게 지내면서 바로브 가가 끔찍한 변화를 겪는 것을 목격했어요. 고약한 괴물들이 마음대로 저택을 활보하는가 하면 암흑 이교도들이 집안 곳곳을 의식과 제물을 바치는 데 사용되는 갖가지 물건들로 채워 버렸죠. 우리는 오래 더 숨어 있지 못할 거라는 걸 알았어요.$B$B아니나 다를까, 우리는 발각돼 체포되었죠. 녀석들은 우리 옷을 모조리 벗기더니 피의 원 안에 집어넣더군요. 우린 알몸인 채로 공포에 떨며 며칠 동안 그 안에 앉아 있었어요', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4047, 'koKR', NULL, '결박이라고요? 이 세상에는 창살이나 족쇄보다도 훨씬 더 강하게 구속하는 것들이 있답니다. 언데드들이 우리를 둘러싸고는 간담을 서늘하게 하는 사악한 행위를 하며 줄곧 우리를 고문했어요.$B$B그리고 마침내 그가 왔죠. 자기를 의사 테올렌 크라스티노브라고 소개하더군요. 나중에 \'도살자\'라는 별명을 알게 되었죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4048, 'koKR', NULL, '우린 마침내 그 비명의 원인이 뭔지 알게 되었어요. 도살자는 우리에게 우리가 존재하는지조차 모르던 극심한 고통을 주더군요. 그는 역병을 고안해 내기 위해 우리를 무수한 실험에 이용했어요.$B$B몇 주 동안이나 고문이 계속됐죠. 그 잔인한 녀석이 마법 수단을 사용해 우리를 계속 살려 두고 있지만 않았더라면 우린 아마 첫날 죽고 말았을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4049, 'koKR', NULL, '도살자는 \"순결한 피\"와 자신의 사악한 주인 \'키르토노스\'를 언급하며 그가 그의 주인을 얼마나 기쁘게 해야 하는지에 대해 얘기하더군요.$B$B결국 그 짐승 같은 작자의 실험이 끝났고 생명력이 모두 소진된 우리의 영혼은 산산이 부서져 버렸어요. 무섭도록 달콤한 죽음의 손길이 다가왔고 우리는 그 손길을 크게 환영했죠. 하지만 끝도 없이 잔인한 도살자는 죽음의 문턱에서 우리를 다시 살려내더군요.$B$B우리를 계속 살려 둔 채로 걸신들린 듯한 구울들에게 던져', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4050, 'koKR', NULL, '우리는 아무것도 느끼지 못한답니다. 우리 영혼은 살지도, 죽지도 못한 채 이곳에 남아 있지요. 우리 시체를 찾고 영혼이 안식을 찾을 때까지 떠날 수가 없답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4051, 'koKR', '아, 은행 일을 보시려면, 저 높은 썬더 블러프까지 가셔야 합니다. 북쪽으로 길을 따라 블러드후프 마을에서 빠져나간 다음 썬더 블러프 밑에 있는 승강기를 타고 꼭대기로 가십시오. 썬더 블러프 경비병에게 다시 물어보면 더 자세히 길을 가르쳐 줄 겁니다.', '아, 은행 일을 보시려면, 저 높은 썬더 블러프까지 가셔야 합니다. 북쪽으로 길을 따라 블러드후프 마을에서 빠져나간 다음 썬더 블러프 밑에 있는 승강기를 타고 꼭대기로 가십시오. 썬더 블러프 경비병에게 다시 물어보면 더 자세히 길을 가르쳐 줄 겁니다.', '이 마을에 그런 곳은 없지만 저 깎아지른 듯 높은 썬더 블러프에는 있습니다. 북쪽으로 길을 따라 블러드후프 마을에서 빠져나가서 썬더 블러프 밑까지 가십시오. 거기서 승강기를 타고 꼭대기까지 올라가 썬더블러프 경비병에게 다시 길을 물어보시면 될 겁니다. 선조님의 가호가 함께하시기를.', '이 마을에 그런 곳은 없지만 저 깎아지른 듯 높은 썬더 블러프에는 있습니다. 북쪽으로 길을 따라 블러드후프 마을에서 빠져나가서 썬더 블러프 밑까지 가십시오. 거기서 승강기를 타고 꼭대기까지 올라가 썬더블러프 경비병에게 다시 길을 물어보시면 될 겁니다. 선조님의 가호가 함께하시기를.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4052, 'koKR', '북쪽에 있는 거대한 도시 썬더 블러프에 와이번 조련사가 한 명 있습니다. 썬더 블러프 밑에서 승강기를 타고 꼭대기로 올라가 썬더 블러프 경비병에게 더 자세히 길을 물어보십시오.', '북쪽에 있는 거대한 도시 썬더 블러프에 와이번 조련사가 한 명 있습니다. 썬더 블러프 밑에서 승강기를 타고 꼭대기로 올라가 썬더 블러프 경비병에게 더 자세히 길을 물어보십시오.', '하늘을 날아오르는 것만큼 영혼을 자유롭게 하는 것도 없습니다. 우리 타우렌족의 위대한 중심지 썬더 블러프에 와이번 조련사가 한 명 있습니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가면 됩니다. 도시 밑에 도착해서 승강기를 타고 꼭대기까지 간 다음 그곳에 있는 썬더 블러프 경비병에게 물어보면 길을 더 자세히 알려 줄 겁니다.', '하늘을 날아오르는 것만큼 영혼을 자유롭게 하는 것도 없습니다. 우리 타우렌족의 위대한 중심지 썬더 블러프에 와이번 조련사가 한 명 있습니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가면 됩니다. 도시 밑에 도착해서 승강기를 타고 꼭대기까지 간 다음 그곳에 있는 썬더 블러프 경비병에게 물어보면 길을 더 자세히 알려 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4053, 'koKR', '여관주인 카우스가 도와 줄 수 있겠군요. 블러드후프 마을 서쪽에 있는 길쭉한 건물 중 하나에 있을 겁니다.', '여관주인 카우스가 도와 줄 수 있겠군요. 블러드후프 마을 서쪽에 있는 길쭉한 건물 중 하나에 있을 겁니다.', '만사에는 때가 있게 마련입니다. 휴식도 마찬가지입니다. 적절한 시기에 휴식을 취하고자 하는 이들을 위해 여관주인 카우스가 블러드후프 마을 서쪽에서 여관을 하나 운영하고 있습니다. 그곳으로 가보십시오.', '만사에는 때가 있게 마련입니다. 휴식도 마찬가지입니다. 적절한 시기에 휴식을 취하고자 하는 이들을 위해 여관주인 카우스가 블러드후프 마을 서쪽에서 여관을 하나 운영하고 있습니다. 그곳으로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4054, 'koKR', '제니아 룬토템의 조언을 구하는 게 좋겠군요. 마을 동쪽에 있는 커다란 천막에서 제니아 룬토템을 만나실 수 있을 겁니다.', '제니아 룬토템의 조언을 구하는 게 좋겠군요. 마을 동쪽에 있는 커다란 천막에서 제니아 룬토템을 만나실 수 있을 겁니다.', '사실, 드루이드의 길은 주술사와 같은 뿌리를 가지고 있습니다. 지금 제니아 룬토템이 드루이드의 유래를 연구하는데 전념하고 있습니다. 블러드후프 마을 동쪽에 있는 커다란 천막 안에서 그녀를 찾아보십시오.', '사실, 드루이드의 길은 주술사와 같은 뿌리를 가지고 있습니다. 지금 제니아 룬토템이 드루이드의 유래를 연구하는데 전념하고 있습니다. 블러드후프 마을 동쪽에 있는 커다란 천막 안에서 그녀를 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4055, 'koKR', '블러드후프 마을 북쪽 끝에서 요 샤프메인이 당신을 기다리고 있습니다. 당신에게 사냥꾼의 도를 가르쳐 줄 수 있을 겁니다.', '블러드후프 마을 북쪽 끝에서 요 샤프메인이 당신을 기다리고 있습니다. 당신에게 사냥꾼의 도를 가르쳐 줄 수 있을 겁니다.', '대지모신 앞에서 자연과 하나가 되는 법을 배우려면 강한 자신감이 필요한 법입니다. 사냥꾼의 길을 당당히 걸어가고 싶다면 블러드후프 마을 북쪽 끝에 있는 요 샤프메인을 찾아가보십시오.', '대지모신 앞에서 자연과 하나가 되는 법을 배우려면 강한 자신감이 필요한 법입니다. 사냥꾼의 길을 당당히 걸어가고 싶다면 블러드후프 마을 북쪽 끝에 있는 요 샤프메인을 찾아가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4056, 'koKR', '블러드후프 마을 동쪽에 있는 큰 천막으로 가보십시오. 그곳에서 당신을 기다리고 있는 나름 스카이체이서를 만날 수 있을 겁니다.', '블러드후프 마을 동쪽에 있는 큰 천막으로 가보십시오. 그곳에서 당신을 기다리고 있는 나름 스카이체이서를 만날 수 있을 겁니다.', '이 마을에 나름 스카이체이서라는 현자가 있습니다. 주술사의 길을 걸어가는 당신에게 그가 도움을 줄 수 있을 겁니다.', '이 마을에 나름 스카이체이서라는 현자가 있습니다. 주술사의 길을 걸어가는 당신에게 그가 도움을 줄 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4057, 'koKR', '마을 남동쪽 가장자리로 가 보면 크랑 스톤후프가 동그란 마당에서 풋내기 전사들을 가르치고 있을 겁니다.', '마을 남동쪽 가장자리로 가 보면 크랑 스톤후프가 동그란 마당에서 풋내기 전사들을 가르치고 있을 겁니다.', '전사의 길을 갈망한다면 크랑 스톤후프를 찾아가 보십시오. 마을의 남동쪽 구석에 있는 동그란 마당에서 종종 풋내기 전사들을 가르치고 있으니까요.', '전사의 길을 갈망한다면 크랑 스톤후프를 찾아가 보십시오. 마을의 남동쪽 구석에 있는 동그란 마당에서 종종 풋내기 전사들을 가르치고 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4058, 'koKR', '이곳 블러드후프 마을에는 전문 연금술사가 없지만 북쪽에 있는 썬더 블러프에 한 명 있지요. 길을 따라 그곳으로 가서 꼭대기에 있는 썬더 블러프 경비병을 붙잡고 다시 한번 물어보십시오.', '이곳 블러드후프 마을에는 전문 연금술사가 없지만 북쪽에 있는 썬더 블러프에 한 명 있지요. 길을 따라 그곳으로 가서 꼭대기에 있는 썬더 블러프 경비병을 붙잡고 다시 한번 물어보십시오.', '대지모신의 선물로 물약을 만들어 끝이 나지 않는 우리의 투쟁을 돕는다는 것은 참으로 명예로운 일입니다. 이 기술을 배우기 위해서는 북쪽에 있는 우리의 위대한 고향 썬더 블러프로 가야 합니다. 꼭대기까지 가서 썬더 블러프 경비병에게 길을 더 자세히 물어보십시오.', '대지모신의 열매로 물약을 만들어 끝없는 투쟁에 힘을 보태는 건 명예로운 일이지. 배우고 싶다면 북쪽의 위대한 고향 썬더 블러프로 가게. 정상에 도착하면 블러프경비병 중 한 명에게 자세한 길을 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4059, 'koKR', '북쪽에 있는 우리의 위대한 고향, 썬더 블러프에 전문 대장장이가 한 명 있습니다. 대장기술을 배우고 싶으시면 그곳으로 가서 썬더 블러프 경비병에게 다시 한번 물어보십시오.', '북쪽에 있는 우리의 위대한 고향, 썬더 블러프에 전문 대장장이가 한 명 있습니다. 대장기술을 배우고 싶으시면 그곳으로 가서 썬더 블러프 경비병에게 다시 한번 물어보십시오.', '강철은 대지모신의 뼈와 다름없습니다. 뜨거운 강철과 씨름하여 호드에 도움이 될 도구를 만들고 싶으신가 보군요. 좋습니다. 블러드후프 마을에서 북쪽으로 나가는 길을 따라가다 보면 썬더 블러프 꼭대기로 가는 승강기가 있을 겁니다. 그 꼭대기에 있는 썬더 블러프 경비병에게 다시 한번 문의하십시오. 더 자세히 가르쳐 줄 겁니다.', '강철은 대지모신의 뼈와 다름없습니다. 뜨거운 강철과 씨름하여 호드에 도움이 될 도구를 만들고 싶으신가 보군요. 좋습니다. 블러드후프 마을에서 북쪽으로 나가는 길을 따라가다 보면 썬더 블러프 꼭대기로 가는 승강기가 있을 겁니다. 그 꼭대기에 있는 썬더 블러프 경비병에게 다시 한번 문의하십시오. 더 자세히 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4060, 'koKR', '마을의 북서쪽 구석에 있는 큰 천막 안으로 들어가 보십시오. 피알 사일런트스트라이드를 만날 수 있을 겁니다. 그라면 당신이 원하는 것을 가르쳐 줄 수 있지요.', '마을의 북서쪽 구석에 있는 큰 천막 안으로 들어가 보십시오. 피알 사일런트스트라이드를 만날 수 있을 겁니다. 그라면 당신이 원하는 것을 가르쳐 줄 수 있지요.', '피알 사일런트스트라이드는 블러드후프 마을에서 으뜸가는 요리사지요. 상상만 해도 벌써 입에 군침이 도는군요. 마을 북서쪽 구석에 있는 큰 천막 안에서 그를 만날 수 있을 겁니다.', '생각만 해도 군침이 도는군. 퍄올 사일런트스트라이드는 블러드후프 마을 최고의 요리사야. 마을 북서쪽 구석의 큰 천막에서 찾을 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4061, 'koKR', '멀리 북쪽에 있는 썬더 블러프까지 가셔야겠습니다. 그곳에 도착하면 썬더 블러프 경비병에게 문의하십시오. 당신이 찾는 곳이 어디인지 정확히 알려 줄 겁니다.', '멀리 북쪽에 있는 썬더 블러프까지 가셔야겠습니다. 그곳에 도착하면 썬더 블러프 경비병에게 문의하십시오. 당신이 찾는 곳이 어디인지 정확히 알려 줄 겁니다.', '수수께끼에 싸여 있는 그 지혜는 위대한 썬더 블러프에서만 찾을 수 있답니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라 썬더 블러프 밑까지 가십시오. 그곳에서 승강기를 타고 위로 올라가 썬더 블러프 경비병에게 다시 물어보십시오.', '그런 지혜는 위대한 썬더 블러프에서만 찾을 수 있는 신비에 싸여 있지. 블러드후프 마을에서 북쪽 길을 따라가다 절벽 아래 승강기를 찾게. 타고 정상으로 올라가 블러프경비병에게 더 자세히 물어보면 될 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4062, 'koKR', '마을 서쪽에 있는 길쭉한 건물 안에서 비라 영후프를 찾아보십시오. 지금쯤 다친 타우렌들을 치료하고 있을 겁니다.', '마을 서쪽에 있는 길쭉한 건물 안에서 비라 영후프를 찾아보십시오. 지금쯤 다친 타우렌들을 치료하고 있을 겁니다.', '평원에서 살다 보면 붕대나 해독제와 같은 물건들이 꼭 필요하지요. 비라 영후프가 뭔가 가르쳐 줄 수 있을 겁니다. 블러드후프 마을 서쪽에 있는 길쭉한 건물 안에서 그녀를 찾아보십시오.', '붕대와 해독제 같은 것들은 평원 생활에서 피할 수 없는 필수품이지. 비라 영후프가 그 지식을 가르쳐 줄 거야. 블러드후프 마을 서쪽의 긴 집에서 찾을 수 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4063, 'koKR', '우탄 스틸워터를 찾으시는군요. 마을 서쪽에 있는 황소바위 호수에서 낚시를 하고 있을 테니 찾아가 보십시오.', '우탄 스틸워터를 찾으시는군요. 마을 서쪽에 있는 황소바위 호수에서 낚시를 하고 있을 테니 찾아가 보십시오.', '젊은 타우렌에게 생선 한 마리를 주면 하루 동안 먹을 수 있지만, 낚시하는 법을 가르치면 평생을 먹을 수 있다고 하지요. 우탄 스틸워터가 평생 먹고 살 수 있는 법을 가르쳐 줄 수 있을 겁니다.$B$B블러드후프 마을 서쪽, 황소바위 호숫가 둑에서 그의 지혜를 구하십시오.', '황소에게 물고기를 주면 하루를 먹이고, 낚는 법을 가르치면 평생을 먹일 수 있지. 우탄 스틸워터가 낚시를 가르쳐 줄 걸세. 블러드후프 마을 서쪽, 스톤불 호숫가에서 그의 지혜를 구하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4064, 'koKR', '약초채집을 배우고 싶으시다면 썬더 블러프로 가셔야 합니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 썬더 블러프 올라가는 승강기가 있습니다. 그걸 타고 올라간 다음, 썬더 블러프 경비병에게 더 자세히 물어보십시오.', '약초채집을 배우고 싶으시다면 썬더 블러프로 가셔야 합니다. 블러드후프 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 썬더 블러프 올라가는 승강기가 있습니다. 그걸 타고 올라간 다음, 썬더 블러프 경비병에게 더 자세히 물어보십시오.', '멀리 북쪽에 있는 우리의 위대한 고향, 썬더 블러프에 가면 당신에게 약초채집을 가르쳐 줄 수 있는 이들이 있습니다. 마을에서 북쪽으로 빠져나가는 길을 따라가면 썬더 블러프 꼭대기로 가는 승강기를 탈 수 있습니다. 도착하면 썬더 블러프 경비병들이 많이 있지요. 더 자세히 길을 가르쳐 줄 수 있을 테니, 붙잡고 한번 물어보십시오.', '멀리 북쪽에 있는 우리의 위대한 고향, 썬더 블러프에 가면 당신에게 약초채집을 가르쳐 줄 수 있는 이들이 있습니다. 마을에서 북쪽으로 빠져나가는 길을 따라가면 썬더 블러프 꼭대기로 가는 승강기를 탈 수 있습니다. 도착하면 썬더 블러프 경비병들이 많이 있지요. 더 자세히 길을 가르쳐 줄 수 있을 테니, 붙잡고 한번 물어보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4065, 'koKR', '마을의 북서쪽 구석에 있는 커다란 천막 안으로 가보십시오. 초우 스트롱하이드를 만나 가죽세공에 대해 가르쳐 달라고 청해보십시오.', '마을의 북서쪽 구석에 있는 커다란 천막 안으로 가보십시오. 초우 스트롱하이드를 만나 가죽세공에 대해 가르쳐 달라고 청해보십시오.', '음식을 얻거나, 몸을 보호할 가죽을 구하려면, 동물을 쓰러뜨릴 수밖에 없습니다. 우리 타우렌은 희생된 동물의 가죽을 사용할 때, 대지모신께 영광을 올리고, 쓰러진 동물에게 경의를 표합니다. 초우 스트롱하이드라면 그 의미를 가르쳐 줄 수 있을 겁니다. 블러드후프 마을 북서쪽 구석에 있는 큰 천막 안에서 그를 찾아보십시오.', '먹거나 몸을 지키기 위해 쓰러뜨린 동물의 가죽을 쓰는 것은 대지모신께 경의를 표하고 그 동물을 존중하는 일이기도 하지. 차우 스트롱하이드가 그런 기술을 가르쳐 줄 거야. 블러드후프 마을 북서쪽 큰 천막에서 찾을 수 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4066, 'koKR', '흐음, 썬더 블러프로 가셔야 할 것 같군요. 블러드후프 마을에서 빠져나가는 길을 따라 북쪽으로 가십시오. 그러면 썬더 블러프 밑에 도착하게 되는데, 승강기를 타고 꼭대기로 올라가서 썬더 블러프 경비병들 중 아무에게나 물어보면 길을 더 자세히 가르쳐 줄 겁니다.', '흐음, 썬더 블러프로 가셔야 할 것 같군요. 블러드후프 마을에서 빠져나가는 길을 따라 북쪽으로 가십시오. 그러면 썬더 블러프 밑에 도착하게 되는데, 승강기를 타고 꼭대기로 올라가서 썬더 블러프 경비병들 중 아무에게나 물어보면 길을 더 자세히 가르쳐 줄 겁니다.', '북쪽에 있는 썬더 블러프에 상급 광부가 한 명 있다고 하더군요. 마을에서 빠져나가는 길을 따라가다가 보면 승강기가 있을 겁니다. 그걸 타고 꼭대기로 올라가십시오. 썬더 블러프 경비병 중 누구에게든 물어보면 도움을 줄 겁니다.', '북쪽에 있는 썬더 블러프에 상급 광부가 한 명 있다고 하더군요. 마을에서 빠져나가는 길을 따라가다가 보면 승강기가 있을 겁니다. 그걸 타고 꼭대기로 올라가십시오. 썬더 블러프 경비병 중 누구에게든 물어보면 도움을 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4067, 'koKR', '블러드후프 마을 북서쪽 구석에 있는 큰 천막 안에서 욘 디프컷을 만나보시는 게 좋겠습니다.', '블러드후프 마을 북서쪽 구석에 있는 큰 천막 안에서 욘 디프컷을 만나보시는 게 좋겠습니다.', '아, 무두질 말씀이시군요. 손칼 쓰는 법은 욘 디프컷의 실력이 단연 최고랍니다. 마을의 북서쪽 구석에 있는 큰 천막에서 만날 수 있을 겁니다.', '아, 무두질 말씀이시군요. 손칼 쓰는 법은 욘 디프컷의 실력이 단연 최고랍니다. 마을의 북서쪽 구석에 있는 큰 천막에서 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4068, 'koKR', '유감스럽게도 이곳 블러드후프 마을에는 재봉술을 가르치는 이가 하나도 없습니다. 하지만 썬더 블러프에는 있을 겁니다. 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 여러 대의 승강기가 있는 곳이 나오는데, 그걸 타고 꼭대기로 올라가서 썬더 블러프 경비병 중 한 명에게 길을 물어보십시오.', '유감스럽게도 이곳 블러드후프 마을에는 재봉술을 가르치는 이가 하나도 없습니다. 하지만 썬더 블러프에는 있을 겁니다. 마을에서 북쪽으로 빠져나가는 길을 따라가다 보면 여러 대의 승강기가 있는 곳이 나오는데, 그걸 타고 꼭대기로 올라가서 썬더 블러프 경비병 중 한 명에게 길을 물어보십시오.', '재봉술 말입니까? 흠, 북쪽에 있는 썬더 블러프로 가셔야 할 겁니다. 마을에서 빠져나가는 길을 따라가도록 하십시오. 썬더 블러프 밑에 도착하면 승강기를 타고 꼭대기로 올라가서 그곳에 있는 썬더 블러프 경비병에게 다시 문의하십시오.', '재봉술이라고? 흐음... 아, 그렇지. 북쪽 썬더 블러프로 가야겠군. 마을 밖 길을 따라가면 돼. 절벽 아래에 도착하면 승강기를 타고 정상으로 올라가 블러프경비병 한 명에게 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4069, 'koKR', '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4070, 'koKR', '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4072, 'koKR', '어떤 물건을 찾으시나요?', '무엇을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4074, 'koKR', '이곳 브릴에는 은행이 없으니 언더시티로 가야 하네. 남쪽에 있는 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 일단 언더시티로 가면, 수호병 중 한 명에게 좀 더 정확한 길을 물어보도록 하게.', '이곳 브릴에는 은행이 없으니 언더시티로 가야 하네. 남쪽에 있는 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 일단 언더시티로 가면, 수호병 중 한 명에게 좀 더 정확한 길을 물어보도록 하게.', '은행 같은 게 도대체 왜 필요한 건가? 뭐, 좋아. 브릴에서 남쪽, 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 몇 대 있지. 그걸 타고 언더시티로 내려간 다음 언더시티 수호병 일을 하는 덩치 큰 누더기골렘 중 아무나 붙잡고 길을 좀 더 자세히 물어보도록.', '은행 같은 게 도대체 왜 필요한 건가? 뭐, 좋아. 브릴에서 남쪽, 로데론의 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 몇 대 있지. 그걸 타고 언더시티로 내려간 다음 언더시티 수호병 일을 하는 덩치 큰 누더기골렘 중 아무나 붙잡고 길을 좀 더 자세히 물어보도록.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4075, 'koKR', '언더시티에 박쥐 조련사가 한 명 있다네. 브릴에서 빠져나가는 길을 따라 남쪽으로 가다가 T 자형 교차로가 나오면 서쪽으로 가게. 왼쪽으로 로데론의 폐허가 나올 거야. 그 안으로 들어가서 언더시티로 내려가야 해. 언더시티에 도착하면 수호병에게 더 자세히 물어보도록 하게.', '언더시티에 박쥐 조련사가 한 명 있다네. 브릴에서 빠져나가는 길을 따라 남쪽으로 가다가 T 자형 교차로가 나오면 서쪽으로 가게. 왼쪽으로 로데론의 폐허가 나올 거야. 그 안으로 들어가서 언더시티로 내려가야 해. 언더시티에 도착하면 수호병에게 더 자세히 물어보도록 하게.', '어디로 날아가려는 건가? 언더시티로 가게! 일단 마을에서 빠져나가는 길을 따라 남쪽으로 가게. 남서쪽 방향에 있는 로데론의 폐허로 가면 돼. 그 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 타고 내려가서 언더시티 수호병에게 길을 더 자세히 물어보게.', '어디로 날아가려는 건가? 언더시티로 가게! 일단 마을에서 빠져나가는 길을 따라 남쪽으로 가게. 남서쪽 방향에 있는 로데론의 폐허로 가면 돼. 그 폐허로 깊숙이 들어가면 언더시티로 내려가는 승강기가 있지. 타고 내려가서 언더시티 수호병에게 길을 더 자세히 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4076, 'koKR', '마을을 가로지르는 길의 남동쪽 끝에 있는 교수대끝 선술집으로 가게. 여관주인 리니가 기다리고 있을 거야.', '마을을 가로지르는 길의 남동쪽 끝에 있는 교수대끝 선술집으로 가게. 여관주인 리니가 기다리고 있을 거야.', '어디 보자. 만약 내가 여관주인 리니라면 어디에 있을까? 흐음...? 아, 아마 갤로우 선술집 안에 있겠지. 브릴 남동쪽 끝으로 가 보게... 찾아갈 수 있겠나?', '어디 보자. 만약 내가 여관주인 리니라면 어디에 있을까? 흐음...? 아, 아마 갤로우 선술집 안에 있겠지. 브릴 남동쪽 끝으로 가 보게... 찾아갈 수 있겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4077, 'koKR', '상급 마법사 케인 파이어송은 교수대끝 선술집 위층에서 찾을 수 있지. 브릴 남동쪽 끝으로 가보게. 그 마법사, 너무 늦게 가서 방을 구하지 못한 것 같아.', '상급 마법사 케인 파이어송은 교수대끝 선술집 위층에서 찾을 수 있지. 브릴 남동쪽 끝으로 가보게. 그 마법사, 너무 늦게 가서 방을 구하지 못한 것 같아.', '내가 마법을 사용할 줄 아는 것처럼 보이나? 후후, 갤로우 선술집 위층에 케인 파이어송이 있다는 얘길 들었네. 마을 남동쪽 끝으로 가보게. 그레첸의 방 바깥에 그렇게 서 있기만 하다니 좀 이상하지 않나?', '내가 마법을 사용할 줄 아는 것처럼 보이나? 후후, 갤로우 선술집 위층에 케인 파이어송이 있다는 얘길 들었네. 마을 남동쪽 끝으로 가보게. 그레첸의 방 바깥에 그렇게 서 있기만 하다니 좀 이상하지 않나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4078, 'koKR', '마을 남동쪽 가장자리에 교수대끝 선술집이라는 곳이 있네. 그곳 위층으로 올라가면 서재 안에 있는 어둠의 사제 베릴을 찾을 수 있을 걸세.', '마을 남동쪽 가장자리에 교수대끝 선술집이라는 곳이 있네. 그곳 위층으로 올라가면 서재 안에 있는 어둠의 사제 베릴을 찾을 수 있을 걸세.', '아, 어둠의사제 베릴을 찾는군. 갤로우 선술집 위층 서재에 있지. 보통 책을 읽거나 기도를 올리면서 지내는데, 무슨 꿍꿍이속인지 누가 알겠나? 감히 그에게 물어볼 수도 없지.', '아, 어둠의사제 베릴을 찾는군. 갤로우 선술집 위층 서재에 있지. 보통 책을 읽거나 기도를 올리면서 지내는데, 무슨 꿍꿍이속인지 누가 알겠나? 감히 그에게 물어볼 수도 없지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4079, 'koKR', '매리언 콜이라고 하는 상급 도적이 있긴 하네. 마을 남동쪽 가장자리에 있는 교수대끝 선술집 위층 서재로 가보게.', '매리언 콜이라고 하는 상급 도적이 있긴 하네. 마을 남동쪽 가장자리에 있는 교수대끝 선술집 위층 서재로 가보게.', '마리언 콜을 찾는다면, 브릴 남동쪽 가장자리에 있는 갤로우 선술집 위층으로 가보게. 서재에서 어둠의사제 베릴과 마주 보고 눈싸움이라도 하고 있는 모양인데, 누가 이길지 정말로 궁금하군.', '마리언 콜을 찾는다면, 브릴 남동쪽 가장자리에 있는 갤로우 선술집 위층으로 가보게. 서재에서 어둠의사제 베릴과 마주 보고 눈싸움이라도 하고 있는 모양인데, 누가 이길지 정말로 궁금하군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4080, 'koKR', '자네가 찾는 자의 이름은 루퍼트 보흐... 마을 남동쪽 끝에 있는 교수대끝 선술집으로 가보게. 위층에 있는 객실에 있을 테니 뒤져 보라고.', '자네가 찾는 자의 이름은 루퍼트 보흐... 마을 남동쪽 끝에 있는 교수대끝 선술집으로 가보게. 위층에 있는 객실에 있을 테니 뒤져 보라고.', '루퍼트 보흐를 찾고 있군. 브릴의 남동쪽 끝에 있는 갤로우 선술집 위층 방에서 친구들과 머물고 있다네.', '루퍼트 보흐를 찾고 있군. 브릴의 남동쪽 끝에 있는 갤로우 선술집 위층 방에서 친구들과 머물고 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4081, 'koKR', '교수대끝 선술집의 식당 안에서 오스틸 드 몽을 찾아보도록. 그 선술집은 브릴의 남동쪽 가장자리에 있다네.', '교수대끝 선술집의 식당 안에서 오스틸 드 몽을 찾아보도록. 그 선술집은 브릴의 남동쪽 가장자리에 있다네.', '아, 오스틸 드 몽을 말하는 건가? 늘 마을의 남동쪽 끝에 있는 선술집에서 시간을 보낸다고 하던데. 갤로우 선술집이라고 찾는 데 어렵지 않을 거야.', '아, 오스틸 드 몽을 말하는 건가? 늘 마을의 남동쪽 끝에 있는 선술집에서 시간을 보낸다고 하던데. 갤로우 선술집이라고 찾는 데 어렵지 않을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4082, 'koKR', '우리 마을 연금술사의 이름은 캐롤라이 아니즈라고 하는데, 브릴의 북서쪽 끝에 있는 그녀의 집에서 만날 수 있지.', '우리 마을 연금술사의 이름은 캐롤라이 아니즈라고 하는데, 브릴의 북서쪽 끝에 있는 그녀의 집에서 만날 수 있지.', '캐롤라이 아니즈는 마을 북서쪽 끝에 있는 자기 집을 통째로 날려버리려고 애쓰고 있더군. 자네가 가서 좀 거들어 줄 수 있을지 한번 보게.', '캐롤라이 아니즈는 마을 북서쪽 끝에 있는 자기 집을 통째로 날려버리려고 애쓰고 있더군. 자네가 가서 좀 거들어 줄 수 있을지 한번 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4083, 'koKR', '미안하지만, 이곳 브릴에는 없으니 언더시티로 가봐야 할 것 같네. 언더시티는 브릴 남쪽에 있는 로데론의 폐허 아래에 있지. 폐허의 뒤편에 아래로 내려가는 승강기가 있으니, 그걸 타고 가서 언더시티 수호병에게 더 자세히 길을 물어보도록 하게.', '미안하지만, 이곳 브릴에는 없으니 언더시티로 가봐야 할 것 같네. 언더시티는 브릴 남쪽에 있는 로데론의 폐허 아래에 있지. 폐허의 뒤편에 아래로 내려가는 승강기가 있으니, 그걸 타고 가서 언더시티 수호병에게 더 자세히 길을 물어보도록 하게.', '대장장이? 우리 마을에 마지막으로 남아있던 대장장이는 정신 나간 스컬지로 변해버렸지. 하지만, 언더시티에는 한 명 있으니 마을 남쪽으로 가보게. 언더시티는 로데론의 폐허 밑에 있다네. 언더시티라, 아주 딱 맞는 이름 아닌가? 폐허 안쪽에 있는 승강기를 타고 내려가서 언더시티 수호병 중 아무나 한 명 붙잡고 물어봐. 길을 가르쳐 줄 거야.', '대장장이? 우리 마을에 마지막으로 남아있던 대장장이는 정신 나간 스컬지로 변해버렸지. 하지만, 언더시티에는 한 명 있으니 마을 남쪽으로 가보게. 언더시티는 로데론의 폐허 밑에 있다네. 언더시티라, 아주 딱 맞는 이름 아닌가? 폐허 안쪽에 있는 승강기를 타고 내려가서 언더시티 수호병 중 아무나 한 명 붙잡고 물어봐. 길을 가르쳐 줄 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4084, 'koKR', '요리사가 되고 싶다고? 마을 남쪽에 있는 언더시티로 가서 수련을 받는 게 어때? 로데론의 폐허 깊숙한 곳에 아래로 내려가는 승강기를 탈 수 있네. 내려가거든 덩치 큰 언더시티 수호병에게 더 자세히 물어보게.', '요리사가 되고 싶다고? 마을 남쪽에 있는 언더시티로 가서 수련을 받는 게 어때? 로데론의 폐허 깊숙한 곳에 아래로 내려가는 승강기를 탈 수 있네. 내려가거든 덩치 큰 언더시티 수호병에게 더 자세히 물어보게.', '뭘 먹든 입에서는 텁텁한 재 맛밖에 안 나는데 요리 같은 건 왜 하겠다는 건가? 아, 자네는 아직 입이 남아 있다 이거군. 뭐, 그렇다면 브릴 남쪽에 있는 언더시티로 가게. 언더시티 수호병에게 요리사가 어디 있는지 다시 물어봐. 언더시티로 가려면 로데론의 폐허 안쪽에서 승강기를 타고 내려가야 하네.', '뭘 먹든 입에서는 텁텁한 재 맛밖에 안 나는데 요리 같은 건 왜 하겠다는 건가? 아, 자네는 아직 입이 남아 있다 이거군. 뭐, 그렇다면 브릴 남쪽에 있는 언더시티로 가게. 언더시티 수호병에게 요리사가 어디 있는지 다시 물어봐. 언더시티로 가려면 로데론의 폐허 안쪽에서 승강기를 타고 내려가야 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4085, 'koKR', '밴스 언더글룸을 찾는군. 브릴 남동쪽에 있는 교수대끝 선술집 위층 방으로 가보게.', '밴스 언더글룸을 찾는군. 브릴 남동쪽에 있는 교수대끝 선술집 위층 방으로 가보게.', '소문을 듣자 하니, 밴스 언더글룸은 마을 남동쪽 끝에 있는 갤로우 선술집 위층 방을 하나를 전세내어 살고 있다더군. 아마 서재 바로 근처에 있을 거야.', '소문을 듣자 하니, 밴스 언더글룸은 마을 남동쪽 끝에 있는 갤로우 선술집 위층 방을 하나를 전세내어 살고 있다더군. 아마 서재 바로 근처에 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4086, 'koKR', '이곳 브릴에는 전문 기계공학자가 없지만 저 아래 언더시티에는 한 명 있지. 마을 남쪽에 있는 로데론의 폐허로 깊숙이 들어가서 승강기를 타고 내려가게. 그곳에서 언더시티 수호병에게 한 번 더 물어보게.', '이곳 브릴에는 전문 기계공학자가 없지만 저 아래 언더시티에는 한 명 있지. 마을 남쪽에 있는 로데론의 폐허로 깊숙이 들어가서 승강기를 타고 내려가게. 그곳에서 언더시티 수호병에게 한 번 더 물어보게.', '다이너마이트, 폭탄, 소총... 하나같이 사랑스럽지 않은 게 없지. 이런 멋진 물건을 만드는 법을 배우고 싶거든 브릴 남쪽, 로데론의 폐허 아래에 있는 언더시티로 가보게. 폐허 안쪽에 있는 승강기를 타고 내려가. 언더시티 수호병 하나를 붙잡고 전문 기술자가 정확히 어디에 있는지 물어보게.', '다이너마이트, 폭탄, 소총... 하나같이 사랑스럽지 않은 게 없지. 이런 멋진 물건을 만드는 법을 배우고 싶거든 브릴 남쪽, 로데론의 폐허 아래에 있는 언더시티로 가보게. 폐허 안쪽에 있는 승강기를 타고 내려가. 언더시티 수호병 하나를 붙잡고 상급 기술자가 정확히 어디에 있는지 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4087, 'koKR', '마을의 남동쪽 끝에 있는 교수대끝 선술집에 있는 간호사 닐라는 모든 이들을 반갑게 맞아주지. 앞으로 모두 자기 손님이 될 거라고 말이야.', '마을의 남동쪽 끝에 있는 교수대끝 선술집에 있는 간호사 닐라는 모든 이들을 반갑게 맞아주지. 앞으로 모두 자기 손님이 될 거라고 말이야.', '도살자? 아, 응급치료사 말인가! 뭐, 결국 똑같은 거지. 마을 남동쪽에 있는 교수대끝 선술집에 있는 간호사 닐라를 만나 얘기해 보면, 금방 무슨 뜻인지 알게 될 거야.', '도살자? 아, 응급치료사 말인가! 뭐, 결국 똑같은 거지. 마을 남동쪽에 있는 교수대끝 선술집에 있는 간호사 닐라를 만나 얘기해 보면, 금방 무슨 뜻인지 알게 될 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4088, 'koKR', '클리데 켈렌이라는 농어 전문가가 있지. 그가 제일 좋아하는 낚시터는 브릴 바로 동쪽에 있는 청명 호수니까, 한번 가서 찾아보게.', '클리데 켈렌이라는 농어 전문가가 있지. 그가 제일 좋아하는 낚시터는 브릴 바로 동쪽에 있는 청명 호수니까, 한번 가서 찾아보게.', '음, 클리데 켈렌이라면 브릴 바로 동쪽에 있는 청명호수 둑에서 늘 낚시를 하고 있지. 그곳에서는 가면을 쓴 미치광이들을 조심하게. 작년에는 그놈들 때문에, 언데드 어린이 여름 캠프를 취소할 정도였으니까.', '음, 클리데 켈렌이라면 브릴 바로 동쪽에 있는 청명호수 둑에서 늘 낚시를 하고 있지. 그곳에서는 가면을 쓴 미치광이들을 조심하게. 작년에는 그놈들 때문에, 언데드 어린이 여름 캠프를 취소할 정도였으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4089, 'koKR', '파루자를 찾아가 보게. 마지막으로 봤을 때는 마을 북서쪽 끝에 있는 마구간 옆에 서 있었네.', '파루자를 찾아가 보게. 마지막으로 봤을 때는 마을 북서쪽 끝에 있는 마구간 옆에 서 있었네.', '나는 사실, 민간요법에 쓰이는 전통적인 약제를 더 좋아하지. 거머리, 구더기, 아니면 지네 같은 것 말이야. 뭐, 각자 취향에 따라 다르긴 하지만. 우리 마을 약초채집가의 이름은 파루자야. 기억해두라고. 브릴의 마구간 근처에 서있을 걸세.', '나는 사실, 민간요법에 쓰이는 전통적인 약제를 더 좋아하지. 거머리, 구더기, 아니면 지네 같은 것 말이야. 뭐, 각자 취향에 따라 다르긴 하지만. 우리 마을 약초채집가의 이름은 파루자야. 기억해두라고. 브릴의 마구간 근처에 서있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4090, 'koKR', '셸렌 로바트 말이로군. 브릴에서 나가는 길을 따라 남동쪽으로 가다가 교차로를 만나면 동쪽으로 가보게. 길가에서 야영을 하고 있을 거야.', '셸렌 로바트 말이로군. 브릴에서 나가는 길을 따라 남동쪽으로 가다가 교차로를 만나면 동쪽으로 가보게. 길가에서 야영을 하고 있을 거야.', '자네, 죽은 짐승 껍질에 살갗을 비벼 보았나? 아마 그렇게 좋은 감촉은 세상 어디에도 없을 거야. 마을에서 나가는 길을 따라 남동쪽으로 가다가 교차로에서 동쪽으로 꺾으면 멀리 가지 않아 길가에 있는 작은 야영지에서 셸렌 로버트를 찾을 수 있을 걸세.', '자네, 죽은 짐승 껍질에 살갗을 비벼 보았나? 아마 그렇게 좋은 감촉은 세상 어디에도 없을 거야. 마을에서 나가는 길을 따라 남동쪽으로 가다가 교차로에서 동쪽으로 꺾으면 멀리 가지 않아 길가에 있는 작은 야영지에서 셸렌 로버트를 찾을 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4091, 'koKR', '언더시티에 상급 광부가 하나 있다고 들었네. 그곳에 가려면 일단 마을에서 나가서 남쪽에 있는 로데론의 폐허로 깊숙이 들어가 보게. 거기서 승강기를 타고 언더시티로 내려가. 언더시티 수호병에게 다시 한번 물어보게.', '언더시티에 상급 광부가 하나 있다고 들었네. 그곳에 가려면 일단 마을에서 나가서 남쪽에 있는 로데론의 폐허로 깊숙이 들어가 보게. 거기서 승강기를 타고 언더시티로 내려가. 언더시티 수호병에게 다시 한번 물어보게.', '채광을 하고 싶다고? 그럼 연습 삼아 언더시티까지 직접 파내려 가보게. 크헤헤... 무슨 말인지 알겠나? 파내려 가라고... 크흐흐, 알았어. 농담 그만 하지. 언더시티로 가려면 브릴 남쪽, 로데론의 폐허로 깊숙이 들어가서 승강기를 타고 내려가면 된다고. 거기 도착하면 언더시티 수호병 한 명에게 더 자세히 물어봐.', '채광을 하고 싶다고? 그럼 연습 삼아 언더시티까지 직접 파내려 가보게. 크헤헤... 무슨 말인지 알겠나? 파내려 가라고... 크흐흐, 알았어. 농담 그만 하지. 언더시티로 가려면 브릴 남쪽, 로데론의 폐허로 깊숙이 들어가서 승강기를 타고 내려가면 된다고. 거기 도착하면 언더시티 수호병 한 명에게 더 자세히 물어봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4092, 'koKR', '박쥐 가죽 벗기는 일 같은 건 랜드 로바트가 아주 능숙하지. 일단 길을 따라 브릴에서 남동쪽으로 쭉 가면, 야영지에서 서있는 그를 만날 수 있을걸. 무슨 말인지 모르겠나? 마을에서 나가는 길을 따라 남동쪽으로 가다가, 교차로에서 동쪽으로 가면 된다고.', '박쥐 가죽 벗기는 일 같은 건 랜드 로바트가 아주 능숙하지. 일단 길을 따라 브릴에서 남동쪽으로 쭉 가면, 야영지에서 서있는 그를 만날 수 있을걸. 무슨 말인지 모르겠나? 마을에서 나가는 길을 따라 남동쪽으로 가다가, 교차로에서 동쪽으로 가면 된다고.', '박제 전문가라도 되려고? 죽었다고 무조건 껍질을 벗기고 속은 짚으로 채워서 장식품으로 만들려는 족속들은 정말 싫어. 안 그래? 정 배우고 싶다면, 마을의 남동쪽에 있는 야영지에서 랜드 로버트를 찾아보게. 브릴에서 나가는 길을 따라 남동쪽으로 가다가 교차로가 나오면 왼쪽으로 가게.', '박제 전문가라도 되려고? 죽었다고 무조건 껍질을 벗기고 속은 짚으로 채워서 장식품으로 만들려는 족속들은 정말 싫어. 안 그래? 정 배우고 싶다면, 마을의 남동쪽에 있는 야영지에서 랜드 로버트를 찾아보게. 브릴에서 나가는 길을 따라 남동쪽으로 가다가 교차로가 나오면 왼쪽으로 가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(4093, 'koKR', '보웬 브리스부아즈를 찾아가게. 그의 집은 브릴에서 남서쪽에 있는 버려진 장원 부근에 있어. 다리 건너면 바로 옆에 있는 건물이라네.', '보웬 브리스부아즈를 찾아가게. 그의 집은 브릴에서 남서쪽에 있는 버려진 장원 부근에 있어. 다리 건너면 바로 옆에 있는 건물이라네.', '흠, 그래? 요새 젊은 언데드들 사이에는 검은색, 회색, 그리고 어두운 자주색이 유행하고 있으니 놓치지 않도록 하게. 보웬 브리스부아즈가 자네를 도와 줄 거야. 마을 남서쪽에 있는 버려진 장원으로 가보게. 다리를 건너야 할 거야.', '흠, 그래? 요새 젊은 언데드들 사이에는 검은색, 회색, 그리고 어두운 자주색이 유행하고 있으니 놓치지 않도록 하게. 보웬 브리스부아즈가 자네를 도와 줄 거야. 마을 남서쪽에 있는 버려진 장원으로 가보게. 다리를 건너야 할 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4095, 'koKR', '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4096, 'koKR', '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4097, 'koKR', '어떤 물건을 찾으시나요?', '무엇을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4113, 'koKR', NULL, '제게 아주 큰 도움을 주셨군요, $n. 감사합니다.$B$B이제 제가 어떻게 해서 이곳으로 오게 됐는지 말씀 드릴 차례로군요. 저와 제 오랜 벗, 트레이 라이트포지는 제데나르로 와서 어둠의 의회를 조사하던 중 무방비 상태에서 녀석들에게 붙잡혔답니다. 놈들은 우리 물건을 모두 빼앗더니 저는 여기에 가두고 트레이는 어둠의 요새 깊숙이 끌고 갔지요... 지하에서 들려 오던 트레이의 비명 소리가 아직도 귀에 생생해요, $n. 그건... 인간의 비명 소리라고 하기', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4114, 'koKR', NULL, '우리 안에 갇힌 나이트 엘프를 보니 왠지 모르게 전에 어디에서인가 본 듯한 느낌이 듭니다. 어떤 이유에선지 이 나이트 엘프는 당신과 눈을 맞추려고 하지 있습니다. 마치 당신이 우리 앞에 서있는 게 보이지 않는 것처럼 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4117, 'koKR', '$R|1이여;여;, 그들은 자신들이 죽었다는 것도 모르고 있소. 저주를 받아, 마을이 통째로 집어 먹히는 최후의 기억만을 영원히 체험하게 된 거요. 그러니까, 대부분이 그렇소. 어떤 이들은 그보다 더 불운했지.$B$B당신 생각에는 스컬지가 이렇게 한 것 같소? 당시에 스컬지는 아직 존재하지도 않았지만, 만약 그게 스컬지 때문이었다면 최소한 우리가 격렬하게 저항이라도 했을 거요.$B$B아니, 이건 역병이 스칼로맨스에서 나와 마을을 집어삼킨 결과였소. 끔찍', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4118, 'koKR', '지금 우서 경의 방문을 위해 준비하고 있는 게 안 보입니까? 비켜요. 할 일이 태산 같단 말이에요!', '지금 우서 경의 방문을 위해 준비하고 있는 게 안 보입니까? 비켜요. 할 일이 태산 같단 말이에요!', '저희 빵을 드셔 보셨나요? 제빵사 마스터슨은 정말 최고의 천재 요리사가 틀림없다니까요!', '저희 빵을 드셔 보셨나요? 제빵사 마스터슨은 정말 최고의 천재 요리사가 틀림없다니까요!', '카엘 다로우에 오신 것을 환영합니다, 이방인이여.', '카엘 다로우에 오신 것을 환영합니다, 이방인이여.', '우리는 원래 그렇게 무례한 사람들이 아닙니다. 모두 우서 경의 도착에 맞춰 모든 걸 완벽하게 준비해 놓으려고 바삐 움직이다 보니 그런 것뿐이죠. 빛의 수호자 우서 경이 마을에 오는 게 자주 있는 일은 아니거든요.', '우리는 원래 그렇게 무례한 사람들이 아닙니다. 모두 우서 경의 도착에 맞춰 모든 걸 완벽하게 준비해 놓으려고 바삐 움직이다 보니 그런 것뿐이죠. 빛의 수호자 우서 경이 마을에 오는 게 자주 있는 일은 아니거든요.', '아, 오늘도 우리의 아름다운 섬의 날씨가 참 좋군요.', '아, 오늘도 우리의 아름다운 섬의 날씨가 참 좋군요.', NULL, NULL, NULL, NULL, NULL, NULL),
(4119, 'koKR', '몸가짐을 조심하시기 바랍니다, 이방인 친구. 우리 마을에서는 이단자를 용납하지 않으니까 말입니다.', '몸가짐을 조심하시기 바랍니다, 이방인 친구. 우리 마을에서는 이단자를 용납하지 않으니까 말입니다.', '내가 유심히 지켜보고 있다는 걸 명심하십시오, $r.', '내가 유심히 지켜보고 있다는 걸 명심하십시오, $r.', '그렇지 않아도 짜증나는 일이 많으니까 소동을 피우기만 해 보라고, 떠돌이 친구.', '그렇지 않아도 짜증나는 일이 많으니까 소동을 피우기만 해 보라고, 떠돌이 친구.', '뭐야, 거리의 부랑아 같은 모양을 해 가지고는!', '뭐야, 거리의 부랑아 같은 모양을 해 가지고는!', '카엘 다로우에서는 배회, 시비, 욕, 싸움 등 당신이 일으키려는 모든 소동은 용납되지 않습니다.', '카엘 다로우에서는 배회, 시비, 욕, 싸움 등 당신이 일으키려는 모든 소동은 용납되지 않습니다.', NULL, NULL, NULL, NULL, NULL, NULL),
(4122, 'koKR', '저주받은 자들의 교단은 세력이 커져서 호드와 얼라이언스 모두의 수도에서 작은 촌락과 오두막까지 이교도들이 일반 시민들 속에 숨어 있다네.$B$B이교도들은 의식을 위해서만 제복을 입으니까 그렇게 놀라지 말게. 자네가 여행을 하는 동안 만난 적이 있었는데도 전혀 모르고 지나쳤을 가능성도 꽤 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4123, 'koKR', '그럴까? 녀석들은 늘 이렇게 활동해 왔어. 켈투자드와 점점 더 성장해 가는 스컬지 군단에게 이보다 더 가치 있는 게 뭐가 있겠나? 사회 속에 파고든 다음 역병을 퍼뜨려 수천 명을 말살시킬 수 있는 광신적이고 살아 있는 추종자일까 아니면 언데드 병사 하나일까? 물론 자네가 이걸 모를 정도로 둔하진 않겠지.$B$B그래, $r 친구, 이 이교도들은 바로 자네들 사이에서 살고, 일하고, 음모를 꾸미고 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4124, 'koKR', '막는다고? 그건 안 될걸. 속도를 늦추는 거야 할 수 있을지도 모르겠지만 말이야.$B$B스컬지들의 훈련과 교육의 주요 거점은 스칼로맨스라네. 바로 그곳으로부터 이교도들이 퍼져 나와 결국 우리 사회 속에 침투하게 되지.$B$B그렇기에 녀석들의 근원을 쳐야만 해. 저주받은 자들의 교단의 심장부를 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4125, 'koKR', '진정하게, $r 친구. 자네가 처치해야 할 자는 이미 죽었어. 그 녀석을 다시 죽인다고 해 봐야 아무 소용없지. 그 강령술사를 실제로 파괴하는 방법은 아주 극소수이고 자네와 나에게는 그 수단마저도 없다네. 그래서 내가 계획을 하나 세웠지. 저주받은 자들의 교단에 아주 뚜렷하고 실질적인 타격을 줄 계획 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4126, 'koKR', '아주 간단해. 라스 프로스트위스퍼라는 강령술사에게서 그의 마력을 빼앗는 거지. 녀석을 다시 평범한 생명체로 되돌려 놓은 후에 영원히 처치해 버리는 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4127, 'koKR', '아, 내가 너무 앞서간 것 같군. 라스 프로스트위스퍼는 그 학교의 감독관일세. 그들의 모든 어둠의 세력들을 양성해 내는 장본인이자 켈투자드의 부관 겸 수제자지. 그는 한때 스트롬가드의 이탈 마법사였다네. 달라란에서 정식 훈련을 받은 적이 없는 이단마술사였지.$B$B켈투자드가 교단을 창단했을 때 라스는 가장 먼저 입단한 자들 중 하나였네. 암흑 마법을 통해 영생을 얻을 수 있음을 알고 있었던 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4128, 'koKR', '그리고 그는 정말로 영생을 얻었어. 저주받은 자들의 교단에서 서열이 빨리 오른 라스에게 리치 왕이 직접 영생을 주었지. 그리하여 리치로 변한 라스 프로스트위스퍼가 탄생한 것일세.$B$B이제 무슨 말인지 이해가 가는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4129, 'koKR', '좋아. 그럼 내 계획을 실행하려면 우선 수명석을 하나 만들어야 하는데, 준비됐나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4130, 'koKR', '어떤 이들은 기억이 만들어 내는 고통에서 벗어날 수 있었다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4133, 'koKR', '바로브 가 때문에 너무 바쁘답니다. 거기서는 항상 무슨 찌꺼기 같은 게 나온다니까요.', NULL, '제 직업은 폐기물 관리 전문가입니다.', NULL, '제 분노의 주먹에 들려 있는 이 소리 확대 장치에 대고 말씀해 보시죠!', NULL, '아, 사랑스런 브랜디. 너무나 보고 싶군요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4134, 'koKR', '반갑네, $C 친구. 나는 은빛장교 가루쉬라고 하네. 은빛십자군이라는 범세계적인 조직의 자랑스러운 일원이지. 우리가 추구하는 대의는 아제로스에서 불거지고 있는 악행에 어떤 자비도 베풀지 않고, 신속하고 강력한 처단을 내리는 것이라네. 우리는 정치적인 단체가 아니야. 그럴 생각은 추호에도 없지. 우리는 호드와 얼라이언스 모두를 동지로 여기고 있네. 악을 물리친다는 오직 한 가지 대의를 위한 동지 말이지!$B$B은빛십자군이여, 영원하라!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4135, 'koKR', NULL, '반갑습니다. $R 동지여! 나는 은빛장교 퓨어하트라고 합니다. 은빛십자군이라는 범세계적인 조직의 자랑스러운 일원입니다. 우리가 추구하는 대의는 간단합니다. 바로 아제로스 전역에 불거지고 있는 악의 요소에 대해 어떤 자비도 베풀지 않고 신속하게 처단하는 것이지요. 우리는 정치적인 단체가 아니며, 정치성을 띨 생각도 없습니다. 우리의 목표를 위해 호드와 얼라이언스 모두를 동지로 여기고 있지요. 악을 물리친다는 대의를 위한 동지 말입니다!$B$B빛을 위하여!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4173, 'koKR', NULL, '은빛 여명회에서 우리 $C 동지에게 인사드리겠네. 내 이름은 하사나, 은빛 여명회를 위해 장비와 물자를 취급할 수 있도록 승인을 받은 소수의 병참장교 중 하나지.$B$B우리의 위임봉을 착용하고 악에 맞서 싸우다 보면 은빛장교 가루쉬에게 명예 휘장을 받게 될 날이 올 거야. 우리로부터 존경과 신뢰를 충분히 쌓았을 때의 얘기지. 그 휘장에는 두 가지 용도가 있네. 은빛 여명회 내에서 지위를 높이는 데 사용하거나, 특별한 물건을 구입하는 데 사용할 수 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4174, 'koKR', NULL, '악에 맞선 전투에 참여하세요! 오늘 은빛 여명회에서 위임봉을 받으세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4193, 'koKR', '은빛십자군에서 $c 동지에게 인사드립니다. 제 이름은 라이트스파크라고 합니다. 은빛십자군을 위해 장비와 물자를 취급하도록 승인받은 소수의 병참장교 중 한 명이죠.$B$B우리 위임봉을 착용하고 악에 맞서 싸우면 은빛장교 퓨어하트가 명예 휘장을 줄 겁니다. 우리로부터 존경과 신뢰를 얻을 수 있죠. 그 휘장에는 두 가지 용도가 있습니다. 은빛십자군에서 지위를 높이거나, 특별한 물건을 구입할 수 있지요.$B$B은빛십자군에서 지위가 오를수록 더욱 다양한 물건을', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4194, 'koKR', '악에 맞선 싸움에 동참하십시오! 오늘 은빛 여명회에서 임무를 맡아 보세요!', '악에 맞선 전투에 참여하세요! 오늘 은빛 여명회에서 위임봉을 받으세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4213, 'koKR', NULL, '안녕하십니까, $C|1이여;여;. 저는 미란다 브리치락이라고 합니다. 은빛 여명회를 위해 장비와 물자를 취급할 수 있도록 승인을 받은 소수의 병참장교 중 한 명입니다.$B$B은빛 여명회 위임봉을 착용하고 악에 맞서 싸우다 보면, 여명회 내에서 당신에 대한 명성이 드높아질 것입니다. 충분한 존경과 신뢰가 쌓이면, 공작 니콜라스 즈바른호프님께 명예 휘장을 받게 될 겁니다. 그 휘장은 두 가지 용도가 있습니다. 은빛 여명회 내에서 지위를 높이는 데 사용하거나', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4233, 'koKR', '안녕하시오, $c.$B$B저기 있는 파수꾼들이 문제를 일으키지 않는 한 야영지를 써도 좋다고 허락하더군. 당신도 여기 있는 동안 평화를 위해 외교가 얼마나 중요한지 깨달을 수 있으리라 믿소.$B$B나는 최근 동요하고 있는 이 지역에 대해 조사하러 왔소. 저들은 내가 여기 있는 것이 아제로스의 여러 종족 간의 동맹에 도움이 될 거라고 생각한 거요. 신뢰의 끈은 미약하지만, 분명 필요한 것이지. 그리고, 내 존재가 자신들이 추구하는 대의에도 도움이 된다고', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4253, 'koKR', '스틸그릴의 정비소에 온 것을 환영하오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4254, 'koKR', '명예는 타고난 종족에 의해 결정되는 게 아닐세. 내 농장에 머무르는 동안 이러한 신조를 기억하고 존중하도록 하게나.$B$B나는 오크 중에서도 가장 숭고한 기사들만큼 명예로운 이들을 보았는가 하면 인간 중에서도 가장 악독한 스컬지만큼 사악한 자들을 보았다네.$B$B뭐, 내 소싯적 얘기로 자네를 지루하게 해서는 안 되겠지! 자네가 일을 하고 싶다면 할 일은 많다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4258, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4259, 'koKR', '무얼 찾고 계십니까?', '무얼 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4260, 'koKR', '은행 말씀이십니까? 은행 업무를 볼 수 있는 곳이라면 스톰윈드 회계사무소지요. 그래도 이 부근에서 제일 가까운 곳일 겁니다. 스톰윈드에서 들어가서 조금만 길을 따라가다 보면 나오는데, 성문에서 그리 멀지 않습니다.', '은행 말씀이십니까? 은행 업무를 볼 수 있는 곳이라면 스톰윈드 회계사무소지요. 그래도 이 부근에서 제일 가까운 곳일 겁니다. 스톰윈드에서 들어가서 조금만 길을 따라가다 보면 나오는데, 성문에서 그리 멀지 않습니다.', '아, 스톰윈드 회계사무소를 말씀하시나 보군요. 스톰윈드에 들어가면 성문에서 그리 멀지 않은 곳에 있습니다.', '아, 스톰윈드 회계사무소를 말씀하시나 보군요. 스톰윈드에 들어가면 성문에서 그리 멀지 않은 곳에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4261, 'koKR', '날아서 어딘가로 가야 하시나 보군요. 스톰윈드에 그리핀 조련사가 한 명 있지요. 영웅의 계곡을 지나자마자 오른쪽에 그리핀이 착륙하는 게 보일 겁니다.', '날아서 어딘가로 가야 하시나 보군요. 스톰윈드에 그리핀 조련사가 한 명 있지요. 영웅의 계곡을 지나자마자 오른쪽에 그리핀이 착륙하는 게 보일 겁니다.', '스톰윈드 내에서 출발하는 그리핀은 조련사가 감독하고 있지요. 그리핀을 타시려면 그를 찾아가 보셔야 합니다.', '스톰윈드 내에서 출발하는 그리핀은 조련사가 감독하고 있지요. 그리핀을 타시려면 그를 찾아가 보셔야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4262, 'koKR', '제가 알기에는 앨드윈 래프린이 여전히 스톰윈드 길드 사무관으로 주재하고 있다고 합니다. 스톰윈드 성문을 지나면 왼쪽 건물에 있을 겁니다.', '제가 알기에는 앨드윈 래프린이 여전히 스톰윈드 길드 사무관으로 주재하고 있다고 합니다. 스톰윈드 성문을 지나면 왼쪽 건물에 있을 겁니다.', '요새 그런 공적인 일들은 모두 스톰윈드에서 처리한답니다. 길드를 창설하고 싶다면 스톰윈드 사무소로 가보십시오.', '요새 그런 공적인 일들은 모두 스톰윈드에서 처리한답니다. 길드를 창설하고 싶다면 스톰윈드 사무소로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4263, 'koKR', '황금골에 있는 사자무리 여관이 딱 좋지요. 다양한 종류의 에일 맥주에다 푹신한 침대까지, 쉴 곳이라면 그만한 곳이 없답니다.', '황금골에 있는 사자무리 여관이 딱 좋지요. 다양한 종류의 에일 맥주에다 푹신한 침대까지, 쉴 곳이라면 그만한 곳이 없답니다.', '이 근처에서는 골드샤이어에 있는 사자무리 여관이 제일입니다. 그곳에 가시면 여관주인 팔레이가 아주 따뜻하게 맞아 줄 겁니다.', '이 근처에서는 골드샤이어에 있는 사자무리 여관이 제일입니다. 그곳에 가시면 여관주인 팔레이가 아주 따뜻하게 맞아 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4264, 'koKR', '엘윈 숲에는 직업 상급자가 꽤 많이 살고 있습니다. 어떤 직업 상급자를 찾으십니까?', '엘윈 숲에는 직업 상급자가 꽤 많이 살고 있습니다. 어떤 직업 상급자를 찾으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4265, 'koKR', '드루이드라고요? 이 근처에서 드루이드를 본 적은 없습니다. 하지만, 스톰윈드에 나이트 엘프들이 모여 사는 지구로 가시면 찾을 수 있을 것 같습니다.', '드루이드라고요? 이 근처에서 드루이드를 본 적은 없습니다. 하지만, 스톰윈드에 나이트 엘프들이 모여 사는 지구로 가시면 찾을 수 있을 것 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4266, 'koKR', '스톰윈드에 사냥 기술로 명성을 떨친 드워프가 한 명 있다고 들었습니다. 그를 찾아가면 될지도 모르겠군요.', '스톰윈드에 사냥 기술로 명성을 떨친 드워프가 한 명 있다고 들었습니다. 그를 찾아가면 될지도 모르겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4267, 'koKR', '조세타는 정말 이 마을에 축복과 같은 존재랍니다. 우리 경비병들까지 도와 주고 있으니까요. 그녀에게 사제 훈련을 받으려면 사자무리 여관으로 가보십시오.', '조세타는 정말 이 마을에 축복과 같은 존재랍니다. 우리 경비병들까지 도와 주고 있으니까요. 그녀에게 사제 훈련을 받으려면 사자무리 여관으로 가보십시오.', '조세타라면 새로운 주문 몇 가지 정도는 기꺼이 가르쳐 줄 겁니다. 아마 지금쯤 사자무리 여관에 있는 자기 방 안에 있을 겁니다.', '조세타라면 새로운 주문 몇 가지 정도는 기꺼이 가르쳐 줄 겁니다. 아마 지금쯤 사자무리 여관에 있는 자기 방 안에 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4268, 'koKR', '잘디마르라면 새로운 마법 몇 가지는 가르쳐 줄 수 있을 겁니다. 요새 사자무리 여관에서 지내는 걸 즐기는 모양이니, 그곳으로 가서 그가 있는지 둘러보십시오.', '잘디마르라면 새로운 마법 몇 가지는 가르쳐 줄 수 있을 겁니다. 요새 사자무리 여관에서 지내는 걸 즐기는 모양이니, 그곳으로 가서 그가 있는지 둘러보십시오.', '저는 마법에 대해서 잘 모르지만, 사자무리 여관에서 지내는 잘디마르라는 마법사가 당신을 도와 줄 수 있을 겁니다.', '저는 마법에 대해서 잘 모르지만, 사자무리 여관에서 지내는 잘디마르라는 마법사가 당신을 도와 줄 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4269, 'koKR', '수사 빌헬름은 보통 대장간 뒤에서 리리아와 얘기를 주고받고는 하더군요. 그는 항상 동료 성기사에게 새로운 기술을 가르쳐 주지요.', '수사 빌헬름은 보통 대장간 뒤에서 리리아와 얘기를 주고받고는 하더군요. 그는 항상 동료 성기사에게 새로운 기술을 가르쳐 주지요.', '수사 빌헬름은 종종 골드샤이어에 있는 대장간 뒤에서 리리아 뒤 라크와 훈련을 하지요. 틀림없이 그에게서 성기사 훈련 한두 가지 정도는 받을 수 있을 겁니다.', '수사 빌헬름은 종종 골드샤이어에 있는 대장간 뒤에서 리리아 뒤 라크와 훈련을 하지요. 틀림없이 그에게서 성기사 훈련 한두 가지 정도는 받을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4270, 'koKR', '도적이라고요? 뭐, 케린 실비우스가 그런 음침한 부류와 어울려 다닌다는 소문은 들었습니다. 케린을 찾아가서 배울 게 있는지 한번 알아보십시오.', '도적이라고요? 뭐, 케린 실비우스가 그런 음침한 부류와 어울려 다닌다는 소문은 들었습니다. 케린을 찾아가서 배울 게 있는지 한번 알아보십시오.', '케린 실비우스라면 당신이 찾는 그런 부류에 대해서 알고 있을 겁니다. 케린은 좀 음침한 이들과 잘 어울려 다니거든요. 사자무리 여관에 있을 테니 찾아가 보십시오.', '케린 실비우스라면 당신이 찾는 그런 부류에 대해서 알고 있을 겁니다. 케린은 좀 음침한 이들과 잘 어울려 다니거든요. 사자무리 여관에 있을 테니 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4271, 'koKR', '이 근방에서 리리아 뒤 라크만큼 칼 솜씨가 뛰어난 이는 없습니다. 대장간 뒤로 가면 리리아가 있을 겁니다. 당신에게 뭔가 새로운 걸 가르쳐 주고 싶어할 분위기인지 눈치를 한번 살펴보십시오.', '이 근방에서 리리아 뒤 라크만큼 칼 솜씨가 뛰어난 이는 없습니다. 대장간 뒤로 가면 리리아가 있을 겁니다. 당신에게 뭔가 새로운 걸 가르쳐 주고 싶어할 분위기인지 눈치를 한번 살펴보십시오.', '훈련이 필요하시다면 리리아와 얘기해 보셔야 할 겁니다. 보통 대장간 뒤에서 자기 무기가 완성되기를 기다리고 있지요.', '훈련이 필요하시다면 리리아와 얘기해 보셔야 할 겁니다. 보통 대장간 뒤에서 자기 무기가 완성되기를 기다리고 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4272, 'koKR', '흠, 그런 부류를 찾으시는군요. 글쎄, 이 근처에서 흑마법에 대해 알만 한 이라면 맥시밀리언밖에 없습니다. 사자무리 여관의 어두컴컴한 지하로 내려가면 그를 찾을 수 있을 겁니다.', '흠, 그런 부류를 찾으시는군요. 글쎄, 이 근처에서 흑마법에 대해 알만 한 이라면 맥시밀리언밖에 없습니다. 사자무리 여관의 어두컴컴한 지하로 내려가면 그를 찾을 수 있을 겁니다.', '흑마법사라고요? 만약에 제가 흑마법사였다면 틀림없이 이 부근에서 제일 어두운 곳에 있을 겁니다. 그렇다면 사자무리 여관의 지하실이 딱 좋겠지요. 먼저 그곳에 가 보셔야 할 겁니다.', '흑마법사라고요? 만약에 제가 흑마법사였다면 틀림없이 이 부근에서 제일 어두운 곳에 있을 겁니다. 그렇다면 사자무리 여관의 지하실이 딱 좋겠지요. 먼저 그곳에 가 보셔야 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4273, 'koKR', '이곳에서 기술 한두 가지를 가르치는 이들을 조금 알고 있지요. 그런데 어떤 기술을 배우려고 하십니까?', '이곳에서 기술 한두 가지를 가르치는 이들을 조금 알고 있지요. 그런데 어떤 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4274, 'koKR', '말로리라는 은둔자가 인근 주민들에게 이따금 물약을 조제해 준다고 알려져 있지요. 스톰윈드와 북녘골 사이에 있는 언덕에 그의 오두막이 있습니다.', '말로리라는 은둔자가 인근 주민들에게 이따금 물약을 조제해 준다고 알려져 있지요. 스톰윈드와 북녘골 사이에 있는 언덕에 그의 오두막이 있습니다.', '노스샤이어와 스톰윈드 사이에 있는 언덕에 사는 연금술사가 당신을 도와 줄 수 있을 겁니다. 그를 찾아가 보시는 게 어떻겠습니까?', '노스샤이어와 스톰윈드 사이에 있는 언덕에 사는 연금술사가 당신을 도와 줄 수 있을 겁니다. 그를 찾아가 보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4275, 'koKR', '황금골에 거주하는 대장장이라면 아르거스가 있지요. 그라면 분명 대장기술을 가르쳐 줄 수 있을 겁니다.', '황금골에 거주하는 대장장이라면 아르거스가 있지요. 그라면 분명 대장기술을 가르쳐 줄 수 있을 겁니다.', '대장장이 아거스를 찾으시는군요. 훈련이 필요하다면 그에게 가보시죠. 그는 하루 종일, 골드샤이어에 있는 가열로를 살펴보며 지낸답니다.', '대장장이 아거스를 찾으시는군요. 훈련이 필요하다면 그에게 가보시죠. 그는 하루 종일, 골드샤이어에 있는 가열로를 살펴보며 지낸답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4276, 'koKR', '토마스는 동부 왕국 최고의 요리사라고 하기는 좀 부족하지만 몇 가지 요리만큼은 누구 못지않게 잘한답니다. 지금 사자무리 여관에서 일하고 있을 테니 요리를 배우고 싶으시면 한번 찾아가 보십시오.', '토마스는 동부 왕국 최고의 요리사라고 하기는 좀 부족하지만 몇 가지 요리만큼은 누구 못지않게 잘한답니다. 지금 사자무리 여관에서 일하고 있을 테니 요리를 배우고 싶으시면 한번 찾아가 보십시오.', '사자무리 여관에 한번 가보시죠? 그곳에서 상급 요리사가 훌륭한 조리법을 몇 가지 가르쳐 줄 겁니다.', '사자무리 여관에 한번 가보시죠? 그곳에서 상급 요리사가 훌륭한 조리법을 몇 가지 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4277, 'koKR', '글쎄, 엘윈 숲에는 마법부여사가 있는 것 같지 않지만, 스톰윈드에 루칸이라는 이가 가게를 하나 운영하고 있지요. 그를 찾아가서 훈련을 받을 수 있는지 한번 알아보십시오.', '글쎄, 엘윈 숲에는 마법부여사가 있는 것 같지 않지만, 스톰윈드에 루칸이라는 이가 가게를 하나 운영하고 있지요. 그를 찾아가서 훈련을 받을 수 있는지 한번 알아보십시오.', '흐음... 이 근처에는 없고, 제가 아는 마법부여사라면 스톰윈드에서 일하는 이밖에 없습니다. 스톰윈드로 가서 경비병에게 다시 한번 물어보시는 게 어떻겠습니까?', '흐음... 이 근처에는 없고, 제가 아는 마법부여사라면 스톰윈드에서 일하는 이밖에 없습니다. 스톰윈드로 가서 경비병에게 다시 한번 물어보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4278, 'koKR', '저희는 보통 노움들에게 그런 일을 맡깁니다. 기계공학을 익히고 싶으시다면, 스톰윈드에서 지내는 노움들이 가르쳐 줄 수 있을 겁니다.', '저희는 보통 노움들에게 그런 일을 맡깁니다. 기계공학을 익히고 싶으시다면, 스톰윈드에서 지내는 노움들이 가르쳐 줄 수 있을 겁니다.', '스톰윈드에 가시면 분명 기계 공학을 가르쳐 줄 노움을 만날 수 있을 겁니다. 스톰윈드 경비병에게 다시 한번 물어보십시오. 길을 정확히 알려드릴 테니까요.', '스톰윈드에 가시면 분명 기계 공학을 가르쳐 줄 노움을 만날 수 있을 겁니다. 스톰윈드 경비병에게 다시 한번 물어보십시오. 길을 정확히 알려드릴 테니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4279, 'koKR', '최근 이 근처를 데피아즈단이 습격한 적이 있었습니다. 그때 상처입은 경비병들을 미셸 벨르가 아주 신속하게 치료해 주었지요. 그녀는 사자무리 여관에 있으니 찾아가서 뭔가 배울 수 있는지 한번 물어보십시오.', '최근 이 근처를 데피아즈단이 습격한 적이 있었습니다. 그때 상처입은 경비병들을 미셸 벨르가 아주 신속하게 치료해 주었지요. 그녀는 사자무리 여관에 있으니 찾아가서 뭔가 배울 수 있는지 한번 물어보십시오.', '미셸 벨르의 간호 솜씨는 아주 놀랍습니다. 아무리 심한 상처라도 신의 손으로 치료한 듯 빨리 아물지요! 그런 비법을 비밀로 할지 몰라도 응급치료라면 제대로 가르쳐 줄 수 있을 겁니다. 그녀는 현재 사자 무리 여관에 거주하고 있습니다.', '미셸 벨르의 간호 솜씨는 아주 놀랍습니다. 아무리 심한 상처라도 신의 손으로 치료한 듯 빨리 아물지요! 그런 비법을 비밀로 할지 몰라도 응급치료라면 제대로 가르쳐 줄 수 있을 겁니다. 그녀는 현재 사자 무리 여관에 거주하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4280, 'koKR', '리 브라운은 수정 호수에서 낚시로 하루 일과를 다 보낸답니다. 찾아가보면 분명 재미있는 이야기도 듣고 몇 가지 요령도 배울 수 있을 겁니다.', '리 브라운은 수정 호수에서 낚시로 하루 일과를 다 보낸답니다. 찾아가보면 분명 재미있는 이야기도 듣고 몇 가지 요령도 배울 수 있을 겁니다.', '리는 수정 호수에서 별의별 희한한 것들을 다 낚아봤다고 합니다. 몇 달 전에는 이상하게 생긴 투구를 건져 올린 얘기도 해주더군요. 그날 밤 사자무리 여관에서 술이 좀 과했던 것 같긴 하지만요.', '리는 수정 호수에서 별의별 희한한 것들을 다 낚아봤다고 합니다. 몇 달 전에는 이상하게 생긴 투구를 건져 올린 얘기도 해주더군요. 그날 밤 사자무리 여관에서 술이 좀 과했던 것 같긴 하지만요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4281, 'koKR', '북녘골과 스톰윈드 사이의 언덕에 사는 약초상 포메로이가 연금술사에게 약초를 제공하는 일을 하지요. 언덕 위 오두막으로 찾아가서 그녀에게 가르침을 구해 보시죠.', '북녘골과 스톰윈드 사이의 언덕에 사는 약초상 포메로이가 연금술사에게 약초를 제공하는 일을 하지요. 언덕 위 오두막으로 찾아가서 그녀에게 가르침을 구해 보시죠.', '스톰윈드 동쪽에 있는 언덕에서 약초채집가 하나가 연금술사와 함께 살고 있습니다. 둘이 같이 살다니 아주 궁합이 잘 맞지 않습니까?', '스톰윈드 동쪽에 있는 언덕에서 약초채집가 하나가 연금술사와 함께 살고 있습니다. 둘이 같이 살다니 아주 궁합이 잘 맞지 않습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4282, 'koKR', '가죽세공을 한번 배워보실 생각이라면, 수정 호수 너머에 살고 있는 아델레 필더를 찾아가 보시는 게 좋을 겁니다. 헬렌이란 무두장이에게 남는 가죽을 얻어서 인근 경비병들의 해진 가죽 방어구를 기워주는 자원봉사를 하더군요.', '가죽세공을 한번 배워보실 생각이라면, 수정 호수 너머에 살고 있는 아델레 필더를 찾아가 보시는 게 좋을 겁니다. 헬렌이란 무두장이에게 남는 가죽을 얻어서 인근 경비병들의 해진 가죽 방어구를 기워주는 자원봉사를 하더군요.', '엘윈 숲에서는 아델레 필더가 가죽 세공인으로서 명성이 있지요. 수정 호수 옆에 있는 자신의 집 바깥에서 작업을 하고 있을 겁니다.', '엘윈 숲에서는 아델레 필더가 가죽 세공인으로서 명성이 있지요. 수정 호수 옆에 있는 자신의 집 바깥에서 작업을 하고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4283, 'koKR', '채광을 배우려면 스톰윈드에 있는 드워프 지구로 가보십시오. 그곳 드워프 중 하나가 채광 기술을 가르쳐 줄 수 있을 겁니다.', '채광을 배우려면 스톰윈드에 있는 드워프 지구로 가보십시오. 그곳 드워프 중 하나가 채광 기술을 가르쳐 줄 수 있을 겁니다.', '스톰윈드로 가보시는 게 나을 것 같군요. 그곳에 도착하시면 경비병에게 다시 한번 물어보십시오. 친절하게 가르쳐 줄 겁니다.', '스톰윈드로 가보시는 게 나을 것 같군요. 그곳에 도착하시면 경비병에게 다시 한번 물어보십시오. 친절하게 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4284, 'koKR', '헬렌 펠트스키너는 오랜 세월 동안 무두질을 해 왔습니다. 아델레 필더가 방어구를 만들 수 있도록 가죽을 공급해왔죠. 수정 호수 옆에 있는 헬렌의 집으로 가보십시오.', '헬렌 펠트스키너는 오랜 세월 동안 무두질을 해 왔습니다. 아델레 필더가 방어구를 만들 수 있도록 가죽을 공급해왔죠. 수정 호수 옆에 있는 헬렌의 집으로 가보십시오.', '아주 실력이 뛰어난 무두장이 하나가 수정 호수 옆에 집을 짓고 살고 있지요. 그녀를 찾아가면 분명 무두질의 기초를 배울 수 있을 겁니다.', '아주 실력이 뛰어난 무두장이 하나가 수정 호수 옆에 집을 짓고 살고 있지요. 그녀를 찾아가면 분명 무두질의 기초를 배울 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4285, 'koKR', '엘윈 숲에서 재봉사라고 불릴 만한 이는 엘드린밖에 없습니다. 재봉술을 익히시려면 동쪽계곡 벌목지에 있는 그를 찾아가 보십시오.', '엘윈 숲에서 재봉사라고 불릴 만한 이는 엘드린밖에 없습니다. 재봉술을 익히시려면 동쪽계곡 벌목지에 있는 그를 찾아가 보십시오.', '재봉사가 되고 싶으시다고요? 흐음... 동부 벌목지에 당신에게 재봉술의 기초를 가르쳐 줄 수 있을 만한 재봉사가 한 명 있는 것으로 압니다.', '재봉사가 되고 싶으시다고요? 흐음... 동부 벌목지에 당신에게 재봉술의 기초를 가르쳐 줄 수 있을 만한 재봉사가 한 명 있는 것으로 압니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4287, 'koKR', '어디로 가는 길을 찾고 있습니까?', '어디로 가는 길을 찾고 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4288, 'koKR', '젊은 $C 친구, 은행 업무를 볼 요량이라면 아이언포지에 있는 사설금고로 가십시오. 그래도 여기서 제일 가까우니까.', '젊은 $C 친구, 은행 업무를 볼 요량이라면 아이언포지에 있는 사설금고로 가십시오. 그래도 여기서 제일 가까우니까.', '아이언포지 사설금고가 이 근방에서 그래도 제일 가까운 은행일 겁니다.', '아이언포지 사설금고가 이 근방에서 그래도 제일 가까운 은행일 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4289, 'koKR', '그리핀을 타고 다른 곳으로 가고 싶습니까? 안타깝게도 그리핀 조련사는 던 모로 어디에서도 찾을 수 없을 겁니다. 아이언포지로 가보십시오.', '그리핀을 타고 다른 곳으로 가고 싶습니까? 안타깝게도 그리핀 조련사는 던 모로 어디에서도 찾을 수 없을 겁니다. 아이언포지로 가보십시오.', '그리핀 조련사를 찾으신다면 아이언포지의 대용광로 근처로 가십시오. 그래도 가장 가까운 곳이니까요. 아이언포지로 가면 그리핀을 타고 날아갈 수 있을 겁니다.', '그리핀 조련사를 찾으신다면 아이언포지의 대용광로 근처로 가십시오. 그래도 가장 가까운 곳이니까요. 아이언포지로 가면 그리핀을 타고 날아갈 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4290, 'koKR', '공무를 담당하는 이들은 모두 아이언포지에 살고 있습니다. 길드를 창설하기 위해 서류가 필요하다면 아이언포지 사무소로 가보는 게 좋겠군요.', '공무를 담당하는 이들은 모두 아이언포지에 살고 있습니다. 길드를 창설하기 위해 서류가 필요하다면 아이언포지 사무소로 가보는 게 좋겠군요.', '길드를 창설하려고 하십니까? 아이언포지 사무소에 들러 필요한 서류 업무를 보셔야겠군요.', '길드를 창설하려고 하십니까? 아이언포지 사무소에 들러 필요한 서류 업무를 보셔야겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4291, 'koKR', '썬더브루 가문에서는 카라노스에 썩 괜찮은 양조장 겸 여관을 하나 운영하고 있습니다. 이름도 자기들 성을 따서 지었더군요. 그곳에 잠시 들러서 맥주도 한잔 하시고 좀 쉬었다 가십시오.', '썬더브루 가문에서는 카라노스에 썩 괜찮은 양조장 겸 여관을 하나 운영하고 있습니다. 이름도 자기들 성을 따서 지었더군요. 그곳에 잠시 들러서 맥주도 한잔 하시고 좀 쉬었다 가십시오.', '아, 여관 말씀이십니까? 쉴 곳으로는 썬더브루 양조장만한 데가 또 없지요. 휴식이 필요하다면 쉬었다 가십시오. 가신 김에 에일 맥주 한두 잔 정도는 꼭 드셔 보시기 바랍니다.', '아, 여관 말씀이십니까? 쉴 곳으로는 썬더브루 양조장만한 데가 또 없지요. 휴식이 필요하다면 쉬었다 가십시오. 가신 김에 에일 맥주 한두 잔 정도는 꼭 드셔 보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4292, 'koKR', '어떤 직업 상급자를 찾고 있습니까?', '어떤 직업 상급자를 찾고 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4293, 'koKR', '이 근방에서 사냥꾼을 찾으신다면 찾아갈 만한 이가 딱 하나 있습니다. 바로 그리프 와일드하트인데, 카라노스에 있는 대장간 바깥에 서있을 겁니다.', '이 근방에서 사냥꾼을 찾으신다면 찾아갈 만한 이가 딱 하나 있습니다. 바로 그리프 와일드하트인데, 카라노스에 있는 대장간 바깥에 서있을 겁니다.', '제 생각에 그리프는 동물들과 너무 많은 시간을 보내는 것 같습니다만, 뭐 그래도 사냥에 대해서라면 그보다 더 잘 아는 이는 없지요. 카라노스의 대장간 바깥에서 찾을 수 있을 겁니다.', '제 생각에 그리프는 동물들과 너무 많은 시간을 보내는 것 같습니다만, 뭐 그래도 사냥에 대해서라면 그보다 더 잘 아는 이는 없지요. 카라노스의 대장간 바깥에서 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4294, 'koKR', '썬더브루 양조장에 새로운 마법 몇 가지를 가르쳐 줄 만한 마법사가 하나 살고 있습니다. 이름이 마지스 스파크맨틀인 걸로 기억합니다만.', '썬더브루 양조장에 새로운 마법 몇 가지를 가르쳐 줄 만한 마법사가 하나 살고 있습니다. 이름이 마지스 스파크맨틀인 걸로 기억합니다만.', '정말 전장에서 몸을 부딪치며 싸우기가 싫습니까? 뭐, 그편이 안전하긴 하겠지만, 정녕 손가락이나 까딱 까딱거리는 법을 배우고 싶다면 썬더브루 양조장에 있는 마지스 스파크맨틀과 얘기해 보는 게 제일 나을 겁니다.', '정말 전장에서 몸을 부딪치며 싸우기가 싫습니까? 뭐, 그편이 안전하긴 하겠지만, 정녕 손가락이나 까딱 까딱거리는 법을 배우고 싶다면 썬더브루 양조장에 있는 마지스 스파크맨틀과 얘기해 보는 게 제일 나을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4295, 'koKR', '아, 성기사라고 했습니까? 아주 운이 좋으신 편이군요, 젊은 양반! 아자르 스트롱해머가 방금 훈련을 마치고 돌아와, 지금 카라노스의 썬더브루 양조장에 머무르고 있답니다.', '아, 성기사라고 했습니까? 아주 운이 좋으신 편이군요, 젊은 양반! 아자르 스트롱해머가 방금 훈련을 마치고 돌아와, 지금 카라노스의 썬더브루 양조장에 머무르고 있답니다.', '훈련이 필요하십니까? 아자르 스트롱해머는 늘 젊은 성기사들에게 한 수 가르쳐 주는 걸 즐기는 편입니다. 썬더브루 양조장으로 아자르를 한번 찾아가 보시는 게 어떨지요?', '훈련이 필요하십니까? 아자르 스트롱해머는 늘 젊은 성기사들에게 한 수 가르쳐 주는 걸 즐기는 편입니다. 썬더브루 양조장으로 아자르를 한번 찾아가 보시는 게 어떨지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4296, 'koKR', '아, 사제라고 했습니까? 훈련이 필요하다면 인심 좋은 막산을 찾아가 보십시오. 지금쯤 썬더브루 양조장에서 한잔 하고 있을 겁니다.', '아, 사제라고 했습니까? 훈련이 필요하다면 인심 좋은 막산을 찾아가 보십시오. 지금쯤 썬더브루 양조장에서 한잔 하고 있을 겁니다.', '썬더브루 양조장에 가면 분명 막산 앤볼이 몇 잔 들이키고 있는 걸 보게 될 겁니다. 당신이 직접 가서 한잔 같이 기울이며 그에게 새로운 기술을 가르쳐 달라고 청해 보십시오.', '썬더브루 양조장에 가면 분명 막산 앤볼이 몇 잔 들이키고 있는 걸 보게 될 겁니다. 당신이 직접 가서 한잔 같이 기울이며 그에게 새로운 기술을 가르쳐 달라고 청해 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4297, 'koKR', '호그럴 바칸을 찾고 있는 모양이군요. 마침 저도 몇 가지 절도 사건으로 그를 찾고 있었습니다. 그 드워프, 분명 에일 맥주를 마시러 썬더브루 양조장에 조만간 들를 겁니다. 어쩌면 지금도 거기 있을지도 모르겠군요.', '호그럴 바칸을 찾고 있는 모양이군요. 마침 저도 몇 가지 절도 사건으로 그를 찾고 있었습니다. 그 드워프, 분명 에일 맥주를 마시러 썬더브루 양조장에 조만간 들를 겁니다. 어쩌면 지금도 거기 있을지도 모르겠군요.', '호그럴을 찾고 계시다고 했습니까? 그럼 선술집부터 들르셨어야죠. 허허! 도적을, 그것도 드워프 도적을 찾는다면 맥주가 있는 여관부터 찾아봐야 할 겁니다. 어서 가서 찾아보십시오.', '호그럴을 찾고 계시다고 했습니까? 그럼 선술집부터 들르셨어야죠. 허허! 도적을, 그것도 드워프 도적을 찾는다면 맥주가 있는 여관부터 찾아봐야 할 겁니다. 어서 가서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4298, 'koKR', '흑마법사라... 별로 마음에 들지는 않습니다만. 제 말은 바로 썬더브루 양조장 밖에 노점상을 열어 놓고 있는 김리즈 녀석 말입니다. 그 녀석 때문에 그곳 에일 맥주는 몽땅 김이 새버릴 걸요! 흑마법사라... 흥!', '흑마법사라... 별로 마음에 들지는 않습니다만. 제 말은 바로 썬더브루 양조장 밖에 노점상을 열어 놓고 있는 김리즈 녀석 말입니다. 그 녀석 때문에 그곳 에일 맥주는 몽땅 김이 새버릴 걸요! 흑마법사라... 흥!', '그런 종류의 마법은 결코 좋은 게 못 됩니다. 김리즈 녀석, 다른 곳을 놔두고 왜 하필 썬더브루 양조장 바깥에다 노점을 차린 건지... 누구 허가를 받았는지도 모르고 있단 말입니다! 그 녀석은 가까이하지 않는 게 좋을 겁니다. 제 말 아시겠습니까?', '그런 종류의 마법은 결코 좋은 게 못 됩니다. 김리즈 녀석, 다른 곳을 놔두고 왜 하필 썬더브루 양조장 바깥에다 노점을 차린 건지... 누구 허가를 받았는지도 모르고 있단 말입니다! 그 녀석은 가까이하지 않는 게 좋을 겁니다. 제 말 아시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4299, 'koKR', '아! 저와 뭔가 통하는 분이시군요! 틀림없이 그라니스 스위프트액스라면 강철 무기를 휘두르는 법을 가르쳐 줄 겁니다. 지금 카라노스에 있는 썬더브루 양조장에 머물고 있지요.', '아! 저와 뭔가 통하는 분이시군요! 틀림없이 그라니스 스위프트액스라면 강철 무기를 휘두르는 법을 가르쳐 줄 겁니다. 지금 카라노스에 있는 썬더브루 양조장에 머물고 있지요.', '그라니스 스위프트액스는 끝도 없이 술을 퍼마시곤 하지만 도끼 하나는 정말 제대로 휘두를 줄 압니다. 훈련을 받고 싶은 거라면 그가 너무 취해 곯아떨어지기 전에 찾아가 보는 게 좋을 겁니다.', '그라니스 스위프트액스는 끝도 없이 술을 퍼마시곤 하지만 도끼 하나는 정말 제대로 휘두를 줄 압니다. 훈련을 받고 싶은 거라면 그가 너무 취해 곯아떨어지기 전에 찾아가 보는 게 좋을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4300, 'koKR', '어떤 기술을 배우려고 하십니까?', '어떤 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4301, 'koKR', '이곳 던 모로에는 연금술사가 없습니다. 아이언포지로 가보는 게 제일 좋을 겁니다. 땜장이 마을에 있는 노움들에게 한번 물어보시지요.', '이곳 던 모로에는 연금술사가 없습니다. 아이언포지로 가보는 게 제일 좋을 겁니다. 땜장이 마을에 있는 노움들에게 한번 물어보시지요.', '아이언포지에 노움들이 운영하는 연금술 전문 상점이 있다고 들었습니다. 그곳에 한번 가보십시오.', '아이언포지에 노움들이 운영하는 연금술 전문 상점이 있다고 들었습니다. 그곳에 한번 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4302, 'koKR', '아! 그거 알아둘 만한 기술임에 틀림없지요. 토그너스는 보기 드문 열정으로 모루를 때린답니다. 그를 찾아가서 당신이 배울 수 있는지 한번 보는 게 어떻겠습니까?', '아! 그거 알아둘 만한 기술임에 틀림없지요. 토그너스는 보기 드문 열정으로 모루를 때린답니다. 그를 찾아가서 당신이 배울 수 있는지 한번 보는 게 어떻겠습니까?', '카라노스로 가면 토그너스가 힘차게 모루를 때리는 소리를 틀림없이 들을 수 있을 겁니다. 귀를 후빈 지가 오래돼서 잘 들리지 않는다면, 더 자세히 알려드리지요. 대장간으로 가보십시오.', '카라노스로 가면 토그너스가 힘차게 모루를 때리는 소리를 틀림없이 들을 수 있을 겁니다. 귀를 후빈 지가 오래돼서 잘 들리지 않는다면, 더 자세히 알려드리지요. 대장간으로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4303, 'koKR', '그렘록이 만드는 음식은 썬더브루 에일 맥주와 정말 잘 어울립니다. 요리사가 되고 싶다면 꼭 그에게 배우십시오.', '그렘록이 만드는 음식은 썬더브루 에일 맥주와 정말 잘 어울립니다. 요리사가 되고 싶다면 꼭 그에게 배우십시오.', '그렘록이 언제나 최고의 요리를 만들어낼 만큼 운이 좋은 건 아니지만, 그래도 배워둘 만한 맛 좋은 조리법을 꽤 알고 있습니다. 썬더브루 양조장에서 일하고 있는 그를 찾아보십시오.', '그렘록이 언제나 최고의 요리를 만들어낼 만큼 운이 좋은 건 아니지만, 그래도 배워둘 만한 맛 좋은 조리법을 꽤 알고 있습니다. 썬더브루 양조장에서 일하고 있는 그를 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4304, 'koKR', '제가 알기에는 이곳 던 모로에 마법부여사는 없습니다. 마법부여에 대해 배우고 싶으세요? 그렇다면, 아이언포지로 가보는 게 좋겠습니다.', '제가 알기에는 이곳 던 모로에 마법부여사는 없습니다. 마법부여에 대해 배우고 싶으세요? 그렇다면, 아이언포지로 가보는 게 좋겠습니다.', '마법부여를 배우기로 마음을 굳혔다면 아이언포지로 가보십시오. 지난번에 제가 그곳에 갔을 때 그리핀 조련사 옆에 상점이 하나 있는 걸 봤습니다만.', '마법부여를 배우기로 마음을 굳혔다면 아이언포지로 가보십시오. 지난번에 제가 그곳에 갔을 때 그리핀 조련사 옆에 상점이 하나 있는 걸 봤습니다만.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4305, 'koKR', '스틸그릴의 정비소로 가서 브론크를 찾아보십시오. 기묘한 장치를 뚝딱거리고 있거나 증기 전차 조종사들과 떠들고 있을 겁니다.', '스틸그릴의 정비소로 가서 브론크를 찾아보십시오. 기묘한 장치를 뚝딱거리고 있거나 증기 전차 조종사들과 떠들고 있을 겁니다.', '브롱크... 그 친구 셀 수도 없이 많이 나사를 조이다 보니, 나사가 몇 개는 풀어진 것처럼 정신이 이상해 보이더군요. 그래도 기발한 장치를 만드는 머리는 비상하니, 스틸그릴의 정비소로 한번 찾아가 보십시오.', '브롱크... 그 친구 셀 수도 없이 많이 나사를 조이다 보니, 나사가 몇 개는 풀어진 것처럼 정신이 이상해 보이더군요. 그래도 기발한 장치를 만드는 머리는 비상하니, 스틸그릴의 정비소로 한번 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4306, 'koKR', '비록 응급치료가 사제의 치유만은 못하더라도 위급한 상황에서는 아주 유용합디다. 썬더브루 양조장에 있는 탐네르를 찾아가서 뭐든 배워 보는 게 좋을 겁니다.', '비록 응급치료가 사제의 치유만은 못하더라도 위급한 상황에서는 아주 유용합디다. 썬더브루 양조장에 있는 탐네르를 찾아가서 뭐든 배워 보는 게 좋을 겁니다.', '제가 며칠 전 고약한 트로그와 싸울 때, 탐네르 그 친구가 붕대를 감아 주더군요. 지금은 씻은 듯이 나았답니다! 분명 탐네르라면 당신에게 좋은 붕대 만드는 법을 기꺼이 가르쳐 줄 겁니다.', '제가 며칠 전 고약한 트로그와 싸울 때, 탐네르 그 친구가 붕대를 감아 주더군요. 지금은 씻은 듯이 나았답니다! 분명 탐네르라면 당신에게 좋은 붕대 만드는 법을 기꺼이 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4307, 'koKR', '이 근처에 낚시터는 별로 없지만 그나마 낚시를 할 수 있는 장소는 죄다 팩스턴이 차지하고 있답니다. 지금도 얼음 호수에서 낚시를 하고 있을 겁니다.', '이 근처에 낚시터는 별로 없지만 그나마 낚시를 할 수 있는 장소는 죄다 팩스턴이 차지하고 있답니다. 지금도 얼음 호수에서 낚시를 하고 있을 겁니다.', '이 부근에서 낚시터는 아주 드물답니다. 팩스턴은 낚시를 할 만한 곳을 죄다 알고 있지만 아마 비밀로 하고 있는 장소도 좀 있을 겁니다. 얼음 호수로 가서 한번 얘기를 나눠 보시겠습니까?', '이 부근에서 낚시터는 아주 드물답니다. 팩스턴은 낚시를 할 만한 곳을 죄다 알고 있지만 아마 비밀로 하고 있는 장소도 좀 있을 겁니다. 얼음 호수로 가서 한번 얘기를 나눠 보시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4308, 'koKR', '사시사철 혹한의 날씨인 이곳 던 모로에도 작은 들꽃들이 자라난다는 게 정말 신기하지 않습니까? 하지만 이곳에 약초채집가는 없답니다. 그 기술을 배우려면 아이언포지로 가보는 게 좋을 겁니다.', '사시사철 혹한의 날씨인 이곳 던 모로에도 작은 들꽃들이 자라난다는 게 정말 신기하지 않습니까? 하지만 이곳에 약초채집가는 없답니다. 그 기술을 배우려면 아이언포지로 가보는 게 좋을 겁니다.', '여기에는 약초 채집을 가르칠 수 있는 이가 없습니다. 하지만 아이언포지로 가면 배울 수 있을 겁니다.', '여기에는 약초 채집을 가르칠 수 있는 이가 없습니다. 하지만 아이언포지로 가면 배울 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4310, 'koKR', '가죽세공을 배우고 싶다면 아이언포지로 가보십시오. 대용광로 근처에 괜찮은 가게가 하나 있다고 들었습니다.', '가죽세공을 배우고 싶다면 아이언포지로 가보십시오. 대용광로 근처에 괜찮은 가게가 하나 있다고 들었습니다.', '가죽 세공인을 찾으신다면 아이언포지로 가보는 게 제일 좋을 겁니다. 제 기억이 정확하다면 대용광로 근처에 그런 상점이 하나 있답니다.', '가죽 세공인을 찾으신다면 아이언포지로 가보는 게 제일 좋을 겁니다. 제 기억이 정확하다면 대용광로 근처에 그런 상점이 하나 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4311, 'koKR', '이 세상에 광부가 한 명도 없는 마을이 있겠습니까? 카라노스 바로 외곽에 있는 스틸그릴의 정비소로 가보십시오. 얄이 기다리고 있을 겁니다.', '이 세상에 광부가 한 명도 없는 마을이 있겠습니까? 카라노스 바로 외곽에 있는 스틸그릴의 정비소로 가보십시오. 얄이 기다리고 있을 겁니다.', '광부가 있느냐고 물었습니까? 있냐, 없냐가 아니라, 어디로 가야 하는지 물어봐야지요, 젊은 $C 양반! 얄을 찾아가십시오. 아마 스틸그릴의 정비소에 있을 겁니다.', '광부가 있느냐고 물었습니까? 있냐, 없냐가 아니라, 어디로 가야 하는지 물어봐야지요, 젊은 $C 양반! 얄을 찾아가십시오. 아마 스틸그릴의 정비소에 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4312, 'koKR', '젊은 $C 양반, 애석하게도 이곳 던 모로에는 무두장이가 한 명도 없습니다. 무두질 좀 한다는 이들은 대부분 아이언포지에 있으니, 훈련을 받으려는 거라면 한번 찾아가 보십시오.', '젊은 $C 양반, 애석하게도 이곳 던 모로에는 무두장이가 한 명도 없습니다. 무두질 좀 한다는 이들은 대부분 아이언포지에 있으니, 훈련을 받으려는 거라면 한번 찾아가 보십시오.', '무두질한 가죽을 말리려면 꼭 아이언포지로 가야합니다. 무두장이라면 죄다 그곳으로 간 것도 이상한 일은 아니지요. 아이언포지로 가서 무두질을 가르쳐 줄 이가 있는지 한번 알아보십시오.', '무두질한 가죽을 말리려면 꼭 아이언포지로 가야합니다. 무두장이라면 죄다 그곳으로 간 것도 이상한 일은 아니지요. 아이언포지로 가서 무두질을 가르쳐 줄 이가 있는지 한번 알아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4313, 'koKR', '아, 재봉술을 배울 생각이라면 아이언포지로 가서 스톤브라우를 만나 봐야 할 겁니다. 요즘에는 아이언포지를 떠나는 일이 별로 없다고 하니 다행이군요.', '아, 재봉술을 배울 생각이라면 아이언포지로 가서 스톤브라우를 만나 봐야 할 겁니다. 요즘에는 아이언포지를 떠나는 일이 별로 없다고 하니 다행이군요.', '글쎄, 여기서는 재봉사를 찾기 어려울 겁니다. 아이언포지로 가면 솜씨 좋은 재봉사들이 꽤 있지요. 그곳에 도착하면 경비병에게 다시 한번 물어보도록 하십시오.', '글쎄, 여기서는 재봉사를 찾기 어려울 겁니다. 아이언포지로 가면 솜씨 좋은 재봉사들이 꽤 있지요. 그곳에 도착하면 경비병에게 다시 한번 물어보도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4316, 'koKR', '텔드랏실에는 가 볼만한 곳이 많이 있습니다. 무얼 찾고 계시는지 말씀만 해주십시오.', '텔드랏실에는 가 볼만한 곳이 많이 있습니다. 무얼 찾고 계시는지 말씀만 해주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4317, 'koKR', '은행은 고요한 밤의 도시, 다르나서스에 있습니다. 소지품을 보관하실 거라면 그곳으로 가셔야 합니다.', '은행은 고요한 밤의 도시, 다르나서스에 있어요. 소지품을 보관하실 거라면 그곳으로 가셔야 합니다.', '은행을 찾으신다면 다르나서스 중심부로 가 보세요. 그곳이라면 그대의 귀중한 보물을 안전하게 보관할 수 있을 겁니다.', '은행을 찾으신다면 다르나서스 중심부로 가 보세요. 그곳이라면 그대의 귀중한 보물을 안전하게 보관할 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4318, 'koKR', '히포그리프를 타시려면 일단 다르나서스로 가신 다음, 텔드랏실의 숲 가까이 있는 루테란 마을로 통하는 문을 지나세요.', '히포그리프를 타시려면 일단 다르나서스로 가신 다음, 텔드랏실의 숲 가까이 있는 루테란 마을로 통하는 문을 지나세요.', '텔드랏실의 숲 가까이 있는 루테란 마을에 가면 아우버다인으로 떠나는 히포그리프를 타실 수 있습니다. 다르나서스에 있는 문을 지나시면 루테란에 갈 수 있어요.', '텔드랏실의 숲 가까이 있는 루테란 마을에 가면 아우버다인으로 떠나는 히포그리프를 타실 수 있습니다. 다르나서스에 있는 문을 지나시면 루테란에 갈 수 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4319, 'koKR', '그런 공적인 업무는 다르나서스에서만 취급합니다. 길드 창설이라면 그곳에 가서 알아보셔야 할 겁니다.', '그런 공적인 업무는 다르나서스에서만 취급합니다. 길드 창설이라면 그곳에 가서 알아보셔야 할 겁니다.', '길드를 창설하시려고요? 문서 업무를 보셔야겠군요. 다르나서스에 있는 길드 사무관에게 가서 조언을 구하십시오.', '길드를 창설하시려고요? 문서 업무를 보셔야겠군요. 다르나서스에 있는 길드 사무관에게 가서 조언을 구하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4320, 'koKR', '편안히 침대에 누워 깊은 휴식을 취하고 싶으시면 돌라나르 여관으로 한번 가 보세요. 켈다미르가 운영하고 있습니다.', '편안히 침대에 누워 깊은 휴식을 취하고 싶으시면 돌라나르 여관으로 한번 가 보세요. 켈다미르가 운영하고 있습니다.', '잠시 쉬면서 지친 몸을 회복하고 싶으시다면 돌라나르에 최고의 여관이 있죠. 여관주인 켈다미르가 그대를 잘 보살펴 줄 겁니다.', '잠시 쉬면서 지친 몸을 회복하고 싶으시다면 돌라나르에 최고의 여관이 있죠. 여관주인 켈다미르가 그대를 잘 보살펴 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4322, 'koKR', '돌라나르 주변에는 그대에게 가르침을 드릴 상급자들이 여럿 있습니다. 그들은 오랜 경험을 가지고 있지요. 어떤 직업 상급자를 찾으시나요?', '돌라나르 주변에는 그대에게 가르침을 드릴 상급자들이 여럿 있습니다. 그들은 오랜 경험을 가지고 있지요. 어떤 직업 상급자를 찾으시나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4323, 'koKR', '드루이드의 도움이 필요하신가요? 그렇다면 돌라나르 여관 바로 남쪽에 있는 달샘에서 칼을 찾아보십시오.', '드루이드의 도움이 필요하신가요? 그렇다면 돌라나르 여관 바로 남쪽에 있는 달샘에서 칼을 찾아보십시오.', '칼이라는 드루이드가 돌라나르의 달샘에서 시간을 보내곤 하죠. 분명 그대에게 필요한 가르침을 줄 수 있을 거예요.', '칼이라는 드루이드가 돌라나르의 달샘에서 시간을 보내곤 하죠. 분명 그대에게 필요한 가르침을 줄 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4324, 'koKR', '사냥꾼을 찾으신다면 다잘라를 찾아가 보셔야 할 거예요. 보통 돌라나르 여관 바깥에서 시간을 보내곤 하지요.', '사냥꾼을 찾으신다면 다잘라를 찾아가 보셔야 할 거예요. 보통 돌라나르 여관 바깥에서 시간을 보내곤 하지요.', '다잘라의 기막힌 사냥 솜씨는 이곳 돌라나르에서 알아준답니다. 그를 찾아가서 가르침을 구해 보세요.', '다잘라의 기막힌 사냥 솜씨는 이곳 돌라나르에서 알아준답니다. 그를 찾아가서 가르침을 구해 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4325, 'koKR', '라우르나 모닝라이트라는 여사제가 돌라나르에서 살고 있습니다. 여관의 바로 북쪽에서 찾을 수 있다고 알고 있습니다.', '라우르나 모닝라이트라는 여사제가 돌라나르에서 살고 있습니다. 여관의 바로 북쪽에서 찾을 수 있다고 알고 있습니다.', '돌라나르 근처에 사는 이들은 라우르나 모닝라이트에게 가서 치유를 받습니다. 사제의 길을 가신다면 그녀를 찾아가 보시는 게 좋을 것 같네요.', '돌라나르 근처에 사는 이들은 라우르나 모닝라이트에게 가서 치유를 받습니다. 사제의 길을 가신다면 그녀를 찾아가 보시는 게 좋을 것 같네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4326, 'koKR', '도적이라고요? 그런 부류에 관한 일에 엮이는 건 그다지 좋아하지 않습니다. 분명 잔노크를 찾으시는 거겠죠. 돌라나르 여관으로 가보십시오.', '도적이라고요? 그런 부류에 관한 일에 엮이는 건 그다지 좋아하지 않습니다. 분명 잔노크를 찾으시는 거겠죠. 돌라나르 여관으로 가보십시오.', '도적을 찾으시나요? 잔노크 말씀이로군요. 돌라나르 여관으로 가보십시오.', '도적을 찾으시나요? 잔노크 말씀이로군요. 돌라나르 여관으로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4327, 'koKR', '칼 쓰는 솜씨라면 키라 윈드블레이드가 일품이죠. 돌라나르 여관에서 찾아보세요. 키라가 뭔가 가르쳐 줄 수 있을 거예요.', '칼 쓰는 솜씨라면 키라 윈드블레이드가 일품이죠. 돌라나르 여관에서 찾아보세요. 키라가 뭔가 가르쳐 줄 수 있을 거예요.', '예전에 한 번 키라 윈드블레이드가 싸우는 모습을 지켜 본 적이 있습니다. 정말 멋져서 탄성이 저절로 나오더군요. 키라가 그대를 잘 가르칠 수 있을 거예요. 돌라나르 여관에서 찾아보세요.', '예전에 한 번 키라 윈드블레이드가 싸우는 모습을 지켜 본 적이 있습니다. 정말 멋져서 탄성이 저절로 나오더군요. 키라가 그대를 잘 가르칠 수 있을 거예요. 돌라나르 여관에서 찾아보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4328, 'koKR', '어느 기술이나, 왕도가 되는 길은 길고도 험하지만 그만큼 큰 보람을 주지요. 어떤 전문가의 길을 걷고 싶으신가요?', '어느 기술이나, 왕도가 되는 길은 길고도 험하지만 그만큼 큰 보람을 주지요. 어떤 전문가의 길을 걷고 싶으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4329, 'koKR', '신드라는 만드는 물약만큼 똑 소리가 나지는 않지만 친절하니까 연금술 가르치는 데는 적격이죠. 돌라나르 여관 바로 동쪽에 있을 겁니다.', '신드라는 만드는 물약만큼 똑 소리가 나지는 않지만 친절하니까 연금술 가르치는 데는 적격이죠. 돌라나르 여관 바로 동쪽에 있을 겁니다.', '킨드라가 연금술에 대한 모든 것을 속속들이 알고 있다고 말하기에는 좀 무리가 있지만, 그대에게 기본기를 가르칠 정도로는 충분하죠. 돌라나르 여관 바로 동쪽에서 연금술을 연구하고 있을 겁니다.', '킨드라가 연금술에 대한 모든 것을 속속들이 알고 있다고 말하기에는 좀 무리가 있지만, 그대에게 기본기를 가르칠 정도로는 충분하죠. 돌라나르 여관 바로 동쪽에서 연금술을 연구하고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4330, 'koKR', '요리 기술이라면 자린이 아주 박식하죠. 찾아가면 조리법 몇 가지 정도는 가르쳐 줄 거예요. 그는 보통 돌라나르 여관 옆에서 요리를 하며 시간을 보내지요.', '요리 기술이라면 자린이 아주 박식하죠. 찾아가면 조리법 몇 가지 정도는 가르쳐 줄 거예요. 그는 보통 돌라나르 여관 옆에서 요리를 하며 시간을 보내지요.', '돌라나르 요리사가 한 명 더 있었으면 좋겠어요. 자린의 요리 솜씨가 부족하다는 소리는 아니고요. 매일 같은 요리만 먹으려니... 자린을 찾아가서 무얼 배울 수 있을지 한번 알아보시지요?', '돌라나르 요리사가 한 명 더 있었으면 좋겠어요. 자린의 요리 솜씨가 부족하다는 소리는 아니고요. 매일 같은 요리만 먹으려니... 자린을 찾아가서 무얼 배울 수 있을지 한번 알아보시지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4331, 'koKR', '알란나 레이븐아이는 신탁의 숲에 있는 영혼들과 교제한 이후 마법부여 능력을 얻었다고 하더군요. 지금 그곳에 가보시면 알란나를 만날 수 있을 거예요.', '알란나 레이븐아이는 신탁의 숲에 있는 영혼들과 교제한 이후 마법부여 능력을 얻었다고 하더군요. 지금 그곳에 가보시면 알란나를 만날 수 있을 거예요.', '알란나는 대부분의 시간을 신탁의 숲에서 마법 부여를 연구하며 보내죠. 마법 부여를 배우고 싶으시다면 그 숲으로 가서 알란나를 찾아보셔야 할 거예요.', '알란나는 대부분의 시간을 신탁의 숲에서 마법 부여를 연구하며 보내죠. 마법 부여를 배우고 싶으시다면 그 숲으로 가서 알란나를 찾아보셔야 할 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4332, 'koKR', '파수꾼들이 숲 속을 순찰하다가 다치면, 보통 비얀시에게 간답니다. 응급치료를 배우고 싶으시다면 비얀시를 찾아가 보세요.', '파수꾼들이 숲 속을 순찰하다가 다치면, 보통 비얀시에게 간답니다. 응급치료를 배우고 싶으시다면 비얀시를 찾아가 보세요.', '비얀시의 응급치료 기술이 없었다면 돌라나르의 많은 주민은 생명의 위기를 겪었을 겁니다. 비얀시에게서 배우고 싶다면 돌라나르 여관 바로 북쪽으로 가면 만날 수 있을 거예요.', '비얀시의 응급치료 기술이 없었다면 돌라나르의 많은 주민은 생명의 위기를 겪었을 겁니다. 비얀시에게서 배우고 싶다면 돌라나르 여관 바로 북쪽으로 가면 만날 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4333, 'koKR', '최근 알아메스 호수 주변이 공격을 당하는 바람에 낚시꾼들이 모두 다르나서스로 옮겨 갔답니다. 낚시를 배우시려면 다르나서스로 가보셔야 할 거예요.', '최근 알아메스 호수 주변이 공격을 당하는 바람에 낚시꾼들이 모두 다르나서스로 옮겨 갔답니다. 낚시를 배우시려면 다르나서스로 가보셔야 할 거예요.', '나무괴물 때문에 돌라나르 근처에서는 낚시하기가 너무 어려워졌어요. 낚시를 가르쳐 줄 이를 찾으시려면 다르나서스로 가보시는 게 제일 좋을 거예요.', '나무괴물 때문에 돌라나르 근처에서는 낚시하기가 너무 어려워졌어요. 낚시를 가르쳐 줄 이를 찾으시려면 다르나서스로 가보시는 게 제일 좋을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4334, 'koKR', '어떻게 그렇게 잘해내는지 모르겠지만 말로른은 아주 섬세한 약초도 다치지 않고 뽑을 줄 안답니다. 약초채집이라면 그에게서 배워야 할 거예요. 돌라나르 여관 바로 동쪽에 살고 있으니 그쪽으로 가보시지요.', '어떻게 그렇게 잘해내는지 모르겠지만 말로른은 아주 섬세한 약초도 다치지 않고 뽑을 줄 안답니다. 약초채집이라면 그에게서 배워야 할 거예요. 돌라나르 여관 바로 동쪽에 살고 있으니 그쪽으로 가보시지요.', '약초 채집을 하려면 말로른 정도는 되는 이에게 배우셔야죠. 섬세한 손길이 필요한 일이니까요. 돌라나르 여관 동쪽으로 가보십시오.', '약초 채집을 하려면 말로른 정도는 되는 이에게 배우셔야죠. 섬세한 손길이 필요한 일이니까요. 돌라나르 여관 동쪽으로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4335, 'koKR', '메인위버 부부는 다르나서스로 가는 길에 집을 짓고 살면서 가죽세공술을 연구하고 있답니다. 가죽세공이라면 나디야가 아주 잘 가르치지요. 배울 것이 있는지 가서 한번 보세요.', '메인위버 부부는 다르나서스로 가는 길에 집을 짓고 살면서 가죽세공술을 연구하고 있답니다. 가죽세공이라면 나디야가 아주 잘 가르치지요. 배울 것이 있는지 가서 한번 보세요.', '나디야는 오랜 경험이 있는 가죽 세공인입니다. 길을 따라 서쪽에 있는 다르나서스로 가십시오. 그녀를 찾아가서 그대에게 가르침을 줄 수 있는지 한번 여쭤보세요.', '나디야는 오랜 경험이 있는 가죽 세공인입니다. 길을 따라 서쪽에 있는 다르나서스로 가십시오. 그녀를 찾아가서 그대에게 가르침을 줄 수 있는지 한번 여쭤보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4336, 'koKR', '래드날은 다르나서스로 가는 길에 집을 짓고 살고 있어요. 그 집 바깥에서 무두질을 하고 있는 그를 보실 수 있을 겁니다. 가르침을 받을 수 있을지 알아보세요.', '래드날은 다르나서스로 가는 길에 집을 짓고 살고 있어요. 그 집 바깥에서 무두질을 하고 있는 그를 보실 수 있을 겁니다. 가르침을 받을 수 있을지 알아보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4337, 'koKR', '다르나서스로 가면 재봉술을 가르쳐줄 수 있는 재봉사가 분명 있을 거예요. 다르나서스에 도착하면 파수꾼을 하나 붙잡고 다시 한번 물어보도록 하세요.', '다르나서스로 가면 재봉술을 가르쳐줄 수 있는 재봉사가 분명 있을 거예요. 다르나서스에 도착하면 파수꾼을 하나 붙잡고 다시 한번 물어보도록 하세요.', '재봉사들이 필요로 하는 물품은 대부분 다르나서스에서 공급되고 있습니다. 그러니 재봉사들이 모두 그곳으로 옮겨 간 것도 놀라운 일이 아니지요. 그대도 재봉사가 되고 싶으시면 다르나서스로 가 보시는 게 좋을 거예요.', '재봉사들이 필요로 하는 물품은 대부분 다르나서스에서 공급되고 있습니다. 그러니 재봉사들이 모두 그곳으로 옮겨 간 것도 놀라운 일이 아니지요. 그대도 재봉사가 되고 싶으시면 다르나서스로 가 보시는 게 좋을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4353, 'koKR', '안녕하신가, $c 친구. 나는 역병지대로 떠날 준비를 하려고 이곳 보루에 야영지를 세웠네. 소문에 듣자하니 그리 오래지 않은 옛날에 어떤 뛰어난 인간 마술사 하나가 하스글렌에 정착했다고 하더군. 붉은십자군이 자신들의 전사와 사냥꾼들에게 지급할 새로운 활과 총을 만드는 일을 그에게 맡겼는데, 그가 아주 대단한 무기를 하나 완성하자 죽여 버렸다고 하더군.$B$B아무래도 비전 마법에 대한 그들의 불신이 더 커진 모양이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4354, 'koKR', NULL, '안녕하세요? 저는 서리바람 거점을 야영지로 삼아 하스글렌으로 떠나기 전에 잠시 쉬는 중이라서 얘기를 나눌 시간이 그리 많지는 않네요. 소문에 듣기로는 붉은십자군이 미쳐 버리기 전에 어떤 마법사를 시켜 병사들에게 지급할 강력한 활과 총을 만들게 했다고 해요. 그 마법사가 성공을 했는지 못했는지는 잘 모르겠고... 아무튼 완성될 때 즈음 붉은십자군에 의해 죽었다고 하더군요. 비밀을 지키기 위해서였거나... 아니면 비전 마법에 대한 그들의 불신이 그만큼 컸기', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4355, 'koKR', NULL, '아... 안녕하세요. 죄송하지만 저는 지금 부상에서 회복 중이랍니다.$B$B저 붉은십자군 녀석들은 생각했던 것보다 더 강해요. 절 거의 죽일 뻔했죠.$B$B당신도 조심하셔야 합니다. 녀석들이 당신을 해치는 건 보고 싶지 않으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4356, 'koKR', NULL, '제 가족은 지금은 서부 역병지대라는 곳에 있는 북마루 벌목지에서 일했었답니다. 제 가족은 두마 가문을 위해 헌신적으로 일했죠. 하지만 이제는 붉은십자군이 하스글렌의 모든 것을 통째로 집어삼켜 버렸어요!$B$B그 광신도 녀석들이 아제로스에서 완전히 제거될 때까지는 전 절대로 쉬지 않을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4357, 'koKR', '오래전, 마지막 대전쟁이 발발하기 전에 우리 아버지께서는 북마루 벌목지를 운영하셨습니다. 그건 아버님의 삶이었고 아버님은 그 일에 헌신하셨지요. 그러던 중 전쟁이 일어나자 우린 스톰윈드로 도망쳐야 했습니다. 아버님의 고통은 이루 말할 수 없었지요.$B$B그 당시 우린 많은 친구와 가족을 잃었고, 붉은십자군이 벌목지를 장악해서 그들 멋대로 이용하고 있다는 사실에 난 견딜 수가 없었습니다.$B$B그래서 내가 돌아온 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4393, 'koKR', '우리는 펄볼그일족 최후의 생존자요. 현재 나무구렁 일족은 타락하지 않은 상태로 남아 있지만, 외부 세력에 의해 우리와 똑같은 위협을 받고 있소이다. 대부분 불가능한 일이라고 생각하더군. 타락을 면한 펄볼그가 존재한다는 사실이 믿기지 않는 모양이지...$B$B너무나 쉽게 우리를 적대시하는 자들에게 화가 난 우리 형제들은, 이제 가까이 다가오는 자를 모두 공격하고 있소. 그러니 아무도 믿지 못하는 게 당연하지.$B$B하지만 당신이 평화롭게 접근한다면 당신을', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4394, 'koKR', '같은 편에서 싸우고 있다는 걸 보여 주어야만 하오. 나무구렁 일족이 당장은 공격할지도 모르나, 당신이 평화로운 동맹 관계를 입증할 길을 부지런히 찾는다면 반드시 길이 보일 거요.$B$B나무구렁 펄볼그를 공격하면 그들과 동지가 될 가능성이 많이 줄어든다는 것을 기억해 두시오.$B$B악령숲 곳곳에 있는 마른가지 펄볼그와 싸우는 걸로 시작하는 게 좋을 거요. 그 펄볼그들은 나무구렁 일족의 적이므로, 녀석들을 쓰러뜨리면 나무구렁 일족과의 관계가 크게 향상될 것', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4395, 'koKR', '우리 나무구렁 일족은 당신이 요새를 무사히 지나갈 수 있도록 허락해 줄 수 있지만, 먼저 당신이 우리의 도움을 받을 자격이 있다는 것을 증명해 보여야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4396, 'koKR', '이곳 여명의 설원에 사는 겨울눈 펄볼그는 한때 우리의 동맹이었지... 하지만 어느 날, 모든 게 변해 버렸소.$B$B그들은 대족장의 이상한 명령에 따라 우리 일족을 포함해 그들이 마주치는 모든 자들을 공격하기 시작한 거요. 이제는 자신들을 고립시키고 있소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4398, 'koKR', '당신 같은 부류를 믿는 일은 거의 없지만 당신만큼은 우리의 친구라는 것을 알 수가 있소, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4399, 'koKR', '아, 그래. 알겠소.$B$B썩 사라지시오. 당신이 우리 일족의 몇몇에게 신뢰를 얻었을지 모르겠지만, 나한테는 그것만으로는 부족하지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4401, 'koKR', '자네가 우리의 진정한 동맹이라는 걸 증명해 보인다면, 한번 생각해 볼 수도 있지... 훈련 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4433, 'koKR', '성스러운 빛이 함께하실 거라 믿습니다, $n. 도와 드릴 일이 있습니까?', '성스러운 빛이 함께하실 거라 믿습니다, $n. 도와 드릴 일이 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4434, 'koKR', '성스러운 빛을 피하려고 하지 마십시오, $c|1이여;여;. 언젠가 당신의 목숨을 구해 주는 유일한 길이 될 수 있습니다.', '성스러운 빛을 피하려고 하지 마세요, $c|1이여;여;. 언젠가 당신의 목숨을 구해줄 유일한 길이 될 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4435, 'koKR', '성스러운 빛을 피하려고 하지 마십시오, $c|1이여;여;. 언젠가 당신의 목숨을 구해 주는 유일한 길이 될 수 있습니다.', '성스러운 빛을 피하려고 하지 마세요, $c|1이여;여;. 언젠가 당신의 목숨을 구해줄 유일한 길이 될 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4436, 'koKR', '성스러운 빛이 함께하기를, $n. 무엇을 도와 드리면 되겠습니까?', '성스러운 빛이 함께하기를, $n. 무엇을 도와 드리면 되겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4437, 'koKR', '엘룬께서 그대와 함께하시기를, $c|1이여;여;.', '엘룬께서 그대와 함께하시기를, $c|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4438, 'koKR', '나의 지혜와 지식은 곧 그대의 지혜와 지식이 될 것입니다. 무엇을 도와 드릴까요, $n?', '나의 지혜와 지식은 곧 그대의 지혜와 지식이 될 것입니다. 무엇을 도와 드릴까요, $n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4439, 'koKR', '무슨 일이오, $c|1이여;여;?', '그래, $c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4440, 'koKR', '몸가짐을 삼가십시오, $c|1이여;여;. 우리의 예를 존중하지 않으면 당신과 당신 일족에 저주가 내릴 것입니다.', '몸가짐을 삼가게, $c|1이여;여;. 우리의 예를 존중하지 않으면 당신과 당신 일족에 저주가 내릴 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4441, 'koKR', '사제의 길을 배우러 여기 오셨다면 최선을 다해 가르쳐 드리겠습니다.', '사제의 길을 배우러 여기 오셨다면 최선을 다해 가르쳐 드리지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4442, 'koKR', '안녕하신가, $n. 포세이큰의 미천한 종에게 무엇을 바라나? 훈련을 원하나?', '안녕하신가, $n. 포세이큰의 미천한 종에게 무엇을 바라나? 훈련을 원하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4443, 'koKR', '지금 누굴 좀 찾고 있으니 내버려두게나... 제발... 중요한 일이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4444, 'koKR', '나는 동부 왕국에서 온 사신이네, $n. 이곳으로 오는 사제들이 올바른 지도를 받을 수 있도록 하기 위해서 파견되었지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4445, 'koKR', '조용히 하세요! 스승님이 말씀하시는 중이잖습니까?', '조용히 하세요! 스승님이 말씀하시는 중이잖습니까?', '잡담할 시간에 경청하도록 하세요.', '잡담할 시간에 경청하도록 하세요.', '우리의용군단을 만들어 내려면 집중을 해야만 해요!', '우리의용군단을 만들어 내려면 집중을 해야만 해요!', '조용히 하세요! 난 이 강의 내용을 한순간도 놓칠 수 없으니까!', '조용히 해! 이 강의는 한순간도 놓칠 수 없다고!', '학생 복장을 갖추는 걸 잊으셨나요? 스컬지의 세계 정복보다 옷맵시가 더 중요하다고 생각하는 겁니까?', '학생 복장을 갖추는 걸 잊으셨나요? 스컬지의 세계 정복보다 옷맵시가 더 중요하다고 생각하는 겁니까?', '어제 숙제는 다 했나요? 그렇다면 어서 내 옆에 앉으라고요!', '여기서는 몸가짐을 잘 하세요. 스승님은 뭐든 다 보고 계시니까...', '여기서는 몸가짐을 잘 하세요. 스승님은 뭐든 다 보고 계시니까...', '교과서는 가져왔나요? 같이 봐도 될까요?', '교과서는 가져왔나요? 같이 봐도 될까요?', '교재 가져왔어? 나도 같이 좀 봐도 될까?'),
(4446, 'koKR', '지금 도대체 여기서 뭐 하고 있는 건가? 어서 학생다운 복장을 갖추고 공부해라!', NULL, '조용히 해! 우리의 역병 걸린 용들이 스스로 알을 깨고 나와서 저절로 훈련을 할 거라 생각하는 건가?', NULL, '불타는 평원에서 왔나? 내 검은용 알은 가져왔는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4447, 'koKR', '자네 마음은 집중이 되어 있지 않군. 나에게 뭔가 숨기는 거라도 있나?', NULL, '자네 주변에서 뭔가 동요가 느껴져...', NULL, '자네는 미래가 흐릿하군. 집중을 한 후에 다시 물어 보도록 하게.', NULL, '자네는 학생 같아 보이지 않는데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4449, 'koKR', '이 코도는 애초에 길들인 것과는 전혀 딴판으로 생겼습니다! 코도 유인기가 먹혀 들지 궁금합니다.', '이 코도는 애초에 길들인 것과는 전혀 딴판으로 생겼습니다! 코도 유인기가 먹혀 들지 궁금합니다.', '어째서 고블린 같이 작은 녀석들은 덩치 큰 놈들만 보면 힘을 못 쓰는 거지?', '어째서 고블린 같이 작은 녀석들은 덩치 큰 놈들만 보면 힘을 못 쓰는 거지?', '어떻게 고블린이 코도한테 짐을 지키게 할 수가 있나? 코도가 10배는 더 크다고!', '어떻게 고블린이 코도한테 짐을 지키게 할 수가 있나? 코도가 10배는 더 크다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4450, 'koKR', NULL, '역병지대는 스컬지를 공격하기에 아주 좋은 장소랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4473, 'koKR', '만나서 반갑습니다. 반드시 마가타 주인님을 직접 만나야 하는 일이 아니라면 제게 말씀하시죠.$B$B마가타 님께서 중요한 업무에 집중할 수 있도록 제가 대부분의 일을 처리하고 있습니다. 마가타 님을 알현하시기 전에 저와 의논할 일이 있으시겠죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4474, 'koKR', '$n, 안녕하시오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4475, 'koKR', '언제든지 말씀만 하십시오. $n, 마가타 님을 잘 보좌해 주셨더군요. 나중에 분명 마가타 님께서 도움을 청하실 날이 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4476, 'koKR', '감히 나와 맞먹으려고 하지 마라. 실바나스 님은 나의 여왕님이시며 나는 여왕님께서 원하시는 대로 할 것이다.$B$B나에게 경의를 표하지 않는다면 단언컨대 지옥으로 보내 주마.$B$B하지만 네가 어둠의 여왕을 돕겠다면 대화를 나눌 수도 있을 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4477, 'koKR', '이 스랄의 앞에서 호드의 만백성들은 평등하도다. 우리는 힘든 시기를 함께 해왔다. 명예, 그리고 지혜가 없었더라면 악마 만노로스에 의해 우리의 피는 더럽혀지고 스컬지와 다를 바 없는 신세가 되었으리라.$B$B너의 임무는 호드를 돕고 우리 오크족을 수호하는 것이다. 그리고 적군에게도 자비와 관대함을 보여야 하는 시기를 알아내는 것도 너의 임무다.$B$B이 점을 명심해라. 이제 우리는 자유 의지를 빼앗긴 악마의 군대가 아니라 새로운 시대의 호드로 거듭났도다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4493, 'koKR', '우선 내 신분을 솔직하게 밝히지 못한 것부터 사과해야겠군. 난 자네를 신뢰해도 되는지 확신이 없었다네. 누가 늙고 잊혀진 은둔자를 사심 없이 도와주겠는가?$B$B자네는 스스로 그걸 증명해 보였네. 자네는 청렴하고 명예를 아는 친구야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4494, 'koKR', '내가 반역죄로 얼라이언스에서 추방당하고 망명 생활을 할 때 내 아들 탤런은 어린 아이였네. 나는 여기 남아서 내 아들을 지켜보기로 결정했지. 어떤 방법으로든 아들이 훌륭하게 성장할 수 있도록 지켜주기 위해서였다네.$B$B내가 바라던 대로 아들은 내 자리였던 마르덴홀드의 군주가 되었지. 그러나 운명이란 어찌나 가혹하던지... 아들은 붉은십자군이 되었고 지금은 그들의 대영주가 되었지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4495, 'koKR', '그렇다네. 은빛 성기사단의 원칙을 어기는 자들이 붉은십자군이 되는 거라네.$B$B날 믿어야 해. 탤런은 좋은 녀석일세. 이끌어줄 자가 필요해. 녀석은 무엇이 옳은 일인지 명예란 어떤 것인지 다시 기억해 내야만 하네. 탤런도 자기가 하는 일이 잘못이라는 걸 가슴으로는 느끼고 있을 거야. 자네가 탤런을 도와서 기억을 일깨워 주겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4513, 'koKR', '남의 말을 들을 땐 주의를 기울이게. 성급하게 믿어서도 안 되지만, 무턱대고 불신하는 것도 어리석은 일이지. 친구 사이라도 자신의 목적을 위해서라면 수단과 방법을 가리지 않는 세상이지 않나, $c.$B$B위대하신 우리 대족장님께서도 이 점을 잘 알고 계시지. 나는 우리의 젊은 지도자를 돕기 위해 자발적으로 나섰다네. 흑마법사들이 다 호드를 무너뜨리거나 장악하려고 드는 건 아니라는 것을 증명하려고 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4516, 'koKR', '우 핑의 체력은 정말 놀랍습니다. 몇 시간 동안이나 넋을 놓고 우 핑이 기술을 연마하는 걸 지켜본 적이 있는데 훈련용 허수아비가 불쌍하다는 생각이 들 정도였어요. 무기를 사용한 전투 기술도 일품이니 당신에게는 최고의 스승일 겁니다.', '우 핑의 체력은 정말 놀랍습니다. 몇 시간 동안이나 넋을 놓고 우 핑이 기술을 연마하는 걸 지켜본 적이 있는데 훈련용 허수아비가 불쌍하다는 생각이 들 정도였어요. 무기를 사용한 전투 기술도 일품이니 당신에게는 최고의 스승일 겁니다.', '무기 전문가 우 핑은 동부 왕국에 존재하는 거의 대부분의 무기를 능숙하게 다룰 줄 압니다. 특히 그의 검술은 정말 위력적이죠. 지금쯤 구 시가지에서 전사들과 함께 훈련을 하고 있을 테니, 무기를 들고 싸우는 전투 기술을 배우고 싶다면 찾아가 보십시오.', '무기 전문가 우 핑은 동부 왕국에 존재하는 거의 대부분의 무기를 능숙하게 다룰 줄 압니다. 특히 그의 검술은 정말 위력적이죠. 지금쯤 구 시가지에서 전사들과 함께 훈련을 하고 있을 테니, 무기를 들고 싸우는 전투 기술을 배우고 싶다면 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4517, 'koKR', '일예니아 문파이어는 지난 천 년 동안 수많은 무기를 익혀왔습니다. 지금은 다른 이들에게 그 기술을 전수하고 있지요. 훈련을 받고 싶으면 전사의 정원으로 가서 일예니아를 찾아보십시오.', '일예니아 문파이어는 지난 천 년 동안 수많은 무기를 익혀왔습니다. 지금은 다른 이들에게 그 기술을 전수하고 있지요. 훈련을 받고 싶으면 전사의 정원으로 가서 일예니아를 찾아보십시오.', '저희 파수꾼들도 대부분 일예니아 문파이어에게 무기 훈련을 받았습니다. 새로운 무기의 사용법을 배우고 싶다면 전사의 정원으로 일예니아를 찾아가보십시오.', '저희 파수꾼들도 대부분 일예니아 문파이어에게 무기 훈련을 받았습니다. 새로운 무기의 사용법을 배우고 싶다면 전사의 정원으로 일예니아를 찾아가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4518, 'koKR', '빅시와 불리위프는 별별 무기를 다 써서 오크를 때려잡은 경험이 있소. 그들은 언제나 잘나가는 무기 상점에 머물고 있으니까 훈련을 받고 싶으면 가보시오.', '빅시와 불리위프는 별별 무기를 다 써서 오크를 때려잡은 경험이 있소. 그들은 언제나 잘나가는 무기 상점에 머물고 있으니까 훈련을 받고 싶으면 가보시오.', '새로 얻은 무기를 제대로 사용하는 방법을 배우고 싶습니까? 그렇다면 잘나가는 무기 상점에 가서 빅시나 불리위프를 찾아보십시오. 그들은 도끼부터 시작해서 투척용 나이프까지 정통하답니다.', '새로 얻은 무기를 제대로 사용하는 방법을 배우고 싶습니까? 그렇다면 잘나가는 무기 상점에 가서 빅시나 불리위프를 찾아보십시오. 그들은 도끼부터 시작해서 투척용 나이프까지 정통하답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4519, 'koKR', '새로 얻은 무기 사용법을 배우고 싶은가? 명예의 골짜기에 있는 전설의 무기점으로 가서 하나시와 함께 있는 사요크를 찾아보게.', '새로 얻은 무기 사용법을 배우고 싶은가? 명예의 골짜기에 있는 전설의 무기점으로 가서 하나시와 함께 있는 사요크를 찾아보게.', '명예의 골짜기에 있는 용사의 전당으로 가서 사요크와 하나시를 찾아보게. 그들 앞에서는 말 조심하는 게 좋을 거요. 까딱 잘못 했다간 사요크가 당신 살점을 사나운 들개에게 간식으로 줄지도 모르니까.', '명예의 골짜기에 있는 용사의 전당으로 가서 사요크와 하나시를 찾아보게. 그들 앞에서는 말 조심하는 게 좋을 거요. 까딱 잘못 했다간 사요크가 당신 살점을 사나운 들개에게 간식으로 줄지도 모르니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4520, 'koKR', '안세크화의 지혜를 구하러 오셨군요. 썬더 블러프 봉우리 하층에 있는 썬더 블러프 무기점에서 그를 찾아보십시오.', '안세크화의 지혜를 구하러 오셨군요. 썬더 블러프 봉우리 하층에 있는 썬더 블러프 무기점에서 그를 찾아보십시오.', '무기를 다루는 기술은 안세크화를 따라올 자가 없습니다. 우리 선조 중에서도 최고로 뛰어난 전사의 영혼이 안세크화를 이끌어 주고 있다고 합니다. 수렵의 봉우리에 가서 안세크화를 찾아보십시오. 당신이 알고 싶어하는 것을 가르쳐 줄 것입니다.', '무기를 다루는 기술은 안세크화를 따라올 자가 없습니다. 우리 선조 중에서도 최고로 뛰어난 전사의 영혼이 안세크화를 이끌어 주고 있다고 합니다. 수렵의 봉우리에 가서 안세크화를 찾아보십시오. 당신이 알고 싶어하는 것을 가르쳐 줄 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4521, 'koKR', '아키발드 말이야? 군사 지구의 내곽으로 가봐. 무기 상점 밖에 있을 거야.', '아키발드 말이야? 군사 지구의 내곽으로 가봐. 무기 상점 밖에 있을 거야.', '작은 포세이큰 친구, 아키발드... 모르는 무기가 없다. 군사 지구의 내곽에서 찾을 수 있다.', '작은 포세이큰 친구, 아키발드... 모르는 무기가 없다. 군사 지구의 내곽에서 찾을 수 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4522, 'koKR', '지금까지 적들이 우릴 어떻게 속여왔는지 설명해주지.$B$B지금부터 내가 하는 말을 명심하게. 우리의 적은 바로 어둠의 의회일세. 내가 자네에게 어떤 일을 시키든지, 누구와 싸우라고 하든지... 이것 하나만은 잊지 말게.$B$B어둠의 의회는 수많은 종파로 나누어져 있지만 모두 어리석은 자들의 눈을 흐리게 만들기 위한 수단일 뿐일세.$B$B불타는 칼날단, 아르거스 재림회, 그리고 이글거리는 칼날단 같은 단체들이 모두 어둠의 의회의 앞잡이란 말이지. 모두 한', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4533, 'koKR', '아, 동지였군. 하루가 다르게 동지들이 늘어나서 좋기는 한데 얼굴을 익힐 수가 있어야지...$B$B멍청한 볼진은 내가 흑마법사의 부정적인 이미지를 벗고 자신의 충실한 종이라는 걸 증명하기 위해 불철주야 열심히 일하는 줄로만 알고 있지. 바보 같은 놈! 불타는 군단이 휩쓸고 지나가면 온 세상이 잿더미가 될 게 분명하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4534, 'koKR', '순진하군. 불타는 칼날단이 바로 어둠의 의회야! 어둠의 의회에는 많은 종파와 단체가 있지만 다 한통속이지. 내가 불타는 칼날단을 이끈다고 해도 어둠의 의회에서 보면, 일원에 불과할 뿐이야. 다 한 식구란 말이야...$B$B그런데, 이글거리는 칼날단을 한번 생각해 보게. 자기들이 어둠의 의회를 대신할 강력한 흑마법사 군단으로 떠오를 거라고 떠들고 다니지. 어리석은 것들.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4535, 'koKR', '하하! 놈들의 우두머리를 잡으려면 힘을 아껴두어야 할 거야. 사티로스 바잘란, 흑마법사 제로쉬... 난 지금까지 그들에게 스랄의 숭배자들을 숱하게 보내왔네. 볼진의 도시에서 악을 제거하고 있다는 인상을 주고 싶었거든. 꼭 성공해서 돌아오게. 볼진의 추종자들을 처치하고 이글거리는 칼날단 녀석들이 우리 편이 될 자격이 있는지 한번 시험해 보는 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4536, 'koKR', '잘 들게. 자네는 이미 어둠의 의회에서 특출난 실력을 증명했기 때문에 부관으로 고속 승진이 가능할 정도야. 나중에 돌아온다면 임무를 맡기도록 하지. 어둠의 의회는 비전 마법에 능숙한 자를 유독 반기지만, 동지가 되고 싶다면 직업이나 종족에 상관없이 누구나 환영한다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4573, 'koKR', '난 탐험가 연맹의 일원으로서 유물을 찾아다녔소. 여명의 설원에 신비한 마법이 걸린 물건이 있다고 하는데... 대부분은 감시가 철저하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4633, 'koKR', NULL, '위험한 시기라네, 모험가 양반. 걸음을 빨리 하시게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4634, 'koKR', NULL, '안녕하세요. 여명의 설원에는 무슨 일이신가요? 이 춥고 광활한 땅은 정말 황량하지만, 정말로 많은 비밀이 숨어 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4635, 'koKR', NULL, '너무 슬퍼요오... 과거는 돌이킬 수 없거든요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4636, 'koKR', NULL, '네가 한 일은 잊지 않겠어...$B$B제발, 이제 나를 내버려 둬...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4673, 'koKR', '앉아서 내 얘기를 좀 들어보게, $r.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4693, 'koKR', '$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾으십니까? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다더군요. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 겁니다. 어쩌면 진짜 정글표범도 볼 수도 있고. 어떻습니까? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보십시오. 에메랄드빛 해안에서 일광욕을 할 수도 있습니다. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 형 얼굴이나 보는 동안', '$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾나요? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다던데. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 거예요. 어쩌면 진짜 정글표범도 볼 수도 있고. 어때요? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보세요. 에메랄드빛 해안에서 일광욕을 할 수도 있어요. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 오빠의 얼굴이나 보는 동안 말이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4694, 'koKR', '뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?', '뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4697, 'koKR', '$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾으십니까? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다더군요. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 겁니다. 어쩌면 진짜 정글표범도 볼 수도 있고. 어떻습니까? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보십시오. 에메랄드빛 해안에서 일광욕을 할 수도 있습니다. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 형 얼굴이나 보는 동안', '$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾나요? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다던데. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 거예요. 어쩌면 진짜 정글표범도 볼 수도 있고. 어때요? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보세요. 에메랄드빛 해안에서 일광욕을 할 수도 있어요. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 오빠의 얼굴이나 보는 동안 말이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4713, 'koKR', '마침내 악몽이 끝났다! 다로우골이여, 날 용서해라!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4714, 'koKR', '초승달발톱의 영혼이 뭔가 원하는 것이라도 있는 듯 당신을 뚫어져라 응시합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4715, 'koKR', '영혼이 당신의 눈을 뚫어져라 응시합니다. 손을 잡는 것이 느껴집니다. 당신의 온몸에 매우 따뜻한 온기가 퍼지면서, 거의 무릎까지 후들거릴 지경입니다.$B$B온기가 지나간 자리에 당신의 결의를 더욱 굳건하게 해줄 곰의 영혼이 존재하는 것이 어렴풋이 느껴집니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4716, 'koKR', '우리 모두 끔찍한 비극을 경험했지만, 결코 절망하지는 맙시다.$B$B다만, 빚을 갚아줄 그날까지는 그 기억을 잊어서도 안 되오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4718, 'koKR', '거대한 곰이 당신을 조용하고 느긋하게 바라볼 뿐 아무 말도 하지 않습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4719, 'koKR', '거대한 곰이 당신을 침착하고 부드러운 눈길로 바라봅니다. 곰의 것이라고 생각되는 말소리가 들리지만... 이상하게도 곰의 입은 전혀 움직이지 않습니다.$B$B\"반갑다, 어린 친구. 내게 뭔가 청이 있어서 온 것인가? 그대가 원하는 것을 얻을 수 있을 것이다.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4721, 'koKR', '나는 그대와 같은 젊은 드루이드를 강화시켜 주기 위해서 존재한다. 그대가 내게 힘을 얻으러 왔으니 가르침을 내려 주겠다. 그대가 내 말을 귀 기울여 듣고 이해할 준비가 되었다면 나... 거대한 곰의 혼에 대한 모든 것을 배울 수 있다.$B$B그리고... 그대의 영혼에 의지한다는 것이 무슨 의미인지 알려면, 정신의 힘뿐만 아니라 육체적 힘의 중요성도 이해해야 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4732, 'koKR', '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4733, 'koKR', '육체의 힘이란 민첩하고도 강한 동작을 말한다. 그대는 육체적으로나 정신적으로 항상 최적의 상태를 유지해야 한다. 전투에서 가장 위협적인 요소는 바로 힘이다. 곰은 그 거대함으로 힘을 확연히 드러내지만 그 안에는 유연한 민첩성과 날카로운 정신이 감춰져 있다. 이 점을 잘 이용하면 상대방을 완전히 제압할 할 수 있지.$B$B할퀴기의 도를 완전히 익히려면 곰의 육체적 힘을 믿어야 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4734, 'koKR', '정신의 힘은 순수하고 솔직한 마음에서 우러나오는 행동을 할 수 있는 의지를 준다. 균형을 유지하는 것은 자기만족을 위함도 아니고 사소한 일도 아니다.$B$B그대 자신이 믿음에 대한 의지를 보여야 하며 그 믿음을 위해 싸울 수 있어야 한다. 어미 곰이 새끼를 지킬 때나, 늙은 곰이 자기 보금자리를 지킬 때는, 굳은 신념을 보여 준다. 이것이 바로 할퀴기의 도를 완전히 익히기 위해 그대가 깨달아야 하는 의지이자 정신의 힘이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4735, 'koKR', '그러려면 우선 그대가 준비됐는지 확인해야 한다. 가장 현명하고 성숙한 드루이드라고 해도 최종 시험에 대해 완벽하게 준비가 됐다고는 할 수 없는 법이지.$B$B내 말을 새겨들었으면, 쉬지 말고 전진하라. 내가 가르쳐 준 교훈을 유념해라. 그대의 힘을 시험할 때가 곧 올 것이다. 곰과 같은 육체와 정신의 힘으로 적과 맞서라. 실전을 통해 배워라. 나의 축복이 그대와 함께할 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4753, 'koKR', '안녕하십니까? $C|1이여;여;. 밤의 안식처에 잘 오셨습니다. 달숲 전역에서 그대를 환영하는 바입니다. 세나리온 의회에서는 자연을 사랑하는 모든 이들을 환영합니다.$B$B여기 머무시는 동안, 매사에 균형을 잃지 않도록 주의하십시오. 특히 소란을 일으키는 행위는 절대 용납하지 않습니다. 우리는 모든 적대적인 행위에 대해 이유를 불문하고 진압하도록 훈련받았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4773, 'koKR', NULL, '환영을 원하는 건가?$B$B임무 수행 도중에 환영의 효력이 사라지면 내게 돌아오게. 그러면 다시 환영 마법을 걸어주지.$B$B실패해도 절대로 포기하지 말게! 내게 돌아오면 일을 마칠 때까지 돕도록 하겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4774, 'koKR', '$C|1이여;여;, 매사에서 균형을 유지하도록 노력하게. 진정한 조화는 바로 거기에 있는 법이니까.', '$C|1이여;여;, 매사에서 균형을 유지하도록 노력하세요. 진정한 조화는 바로 거기에 있는 법이니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4775, 'koKR', '환영하네. 훈련을 하러 온 거라면 기꺼이 가르침을 주지.$B$B다시금 자신의 자리를 확인하는 것도 나쁘지 않겠지. 난 그걸 위대한 균형이라고 부르고 싶다네. 우리는 균형의 수호자로서 청명한 정신력과 강한 의지를 지키기 위해 꾸준히 노력해야 해. 바로 뼈를 깎는 듯한 훈련을 통해서 말일세.', '환영합니다. 훈련을 하러 오신 거라면 기꺼이 가르침을 드리지요.$B$B다시금 자신의 자리를 확인하는 것도 나쁘지 않겠지요. 전 그걸 위대한 균형이라고 부르고 싶습니다. 우리는 균형의 수호자로서 청명한 정신력과 강한 의지를 지키기 위해 꾸준히 노력해야 합니다. 바로 뼈를 깎는 듯한 훈련을 통해서 말이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4776, 'koKR', '전투는 끝났고 이제 다로우골 주민들은 안전합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4777, 'koKR', '전투가 끝났고 이제 다로우골 주민들은 안전합니다.$B$B$n, 이제 살았습니다. 모두 당신 덕분이에요. 당신은 진정한 다로우골의 영웅입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4778, 'koKR', '한때 사악한 악의 힘에 의해 판단력이 흐려졌지만, 이제 당신이 저를 사악한 망상으로부터 자유롭게 해주었어요. 절 구하셨군요.$B$B그리고, 부디... 제 잘못을 용서해주세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4779, 'koKR', '어서 오시오, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 내가 기꺼이 가르쳐 드리겠소.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자요. 이 사실을 잊지 마시오.', '어서 오세요, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리지요.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자입니다. 이 사실을 잊지 마세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4780, 'koKR', '$c님, 우리의 지도자이신 말퓨리온 님께서는 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', '$c님, 우리의 지도자이신 말퓨리온 님께서는 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4781, 'koKR', '$C|1이여;여;, 세나리우스의 축복이 그대와 함께하기를.', '$C|1이여;여;, 세나리우스의 축복이 그대와 함께하기를.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'koKR', '어서 오세요, 나의 $g 형제:자매;여. 훈련을 받으러 왔다면 기꺼이 가르쳐 드리겠습니다.$B$B세나리온 의회 내부에 불화가 있다는 소문이 돌지만 그런 뜬소문에 귀 기울일 필요는 없습니다. 우리의 대드루이드 판드랄 스태그헬름께서 우리와 텔드랏실 전체를 영광으로 이끌고 계시니까요!', '어서 오세요, 나의 $g 형제:자매;여. 훈련을 받으러 왔다면 기꺼이 가르쳐 드리겠습니다.$B$B세나리온 의회 내부에 불화가 있다는 소문이 돌지만 그런 뜬소문에 귀 기울일 필요는 없습니다. 우리의 대드루이드 판드랄 스태그헬름께서 우리와 텔드랏실 전체를 영광으로 이끌고 계시니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4783, 'koKR', '이 마을을 보호하는 돌벽과도 같이 차가운 벽 안에서도 평온을 찾을 수는 있답니다. 마음의 균형을 찾아 자신의 내면을 살펴본다면 사실 어디에서나 평온을 찾을 수 있습니다.', '이 마을을 보호하는 돌벽과도 같이 차가운 벽 안에서도 평온을 찾을 수는 있답니다. 마음의 균형을 찾아 자신의 내면을 살펴본다면 사실 어디에서나 평온을 찾을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4784, 'koKR', '어서 오십시오. 이곳에 훈련을 받으러 오셨다면 제가 기꺼이 훈련을 시켜 드리죠.$B$B곧 에메랄드의 꿈이 부르는 소리를 듣게 될 때가 올 겁니다. 여러 해 동안 동면을 취하고 가장 순수한 상들 중에서 걷게 될 텐데, 바로 그때 그곳에서 궁극의 수련을 쌓게 될 겁니다.', '어서 오십시오. 이곳에 훈련을 받으러 오셨다면 제가 기꺼이 훈련을 시켜 드리죠.$B$B곧 에메랄드의 꿈이 부르는 소리를 듣게 될 때가 올 겁니다. 여러 해 동안 동면을 취하고 가장 순수한 상들 중에서 걷게 될 텐데, 바로 그때 그곳에서 궁극의 수련을 쌓게 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4785, 'koKR', '$C|1이여;여;, 우리는 세나리우스의 가르침대로 균형을 지키기 위해 노력하고 있습니다. 그분은 우리의 길을 비추는 빛이시지요. 우리는 그 빛을 지키기 위해 최선을 다해야 합니다.', '$C|1이여;여;, 우리는 세나리우스의 가르침대로 균형을 지키기 위해 노력하고 있습니다. 그분은 우리의 길을 비추는 빛이시지요. 우리는 그 빛을 지키기 위해 최선을 다해야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4786, 'koKR', '어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B세나리우스의 가르침대로 우리는 언제까지나 균형을 지키도록 노력해야 합니다. 절대 잊지 마십시오.', '어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B세나리우스의 가르침대로 우리는 언제까지나 균형을 지키도록 노력해야 합니다. 절대 잊지 마십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4787, 'koKR', NULL, '$n, 다시 한 번 감사드려요! 이 사실을 알게 돼서 얼마나 기쁜지 모른답니다.$B$B행운을 빌어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4788, 'koKR', NULL, '숲에 올라갈 채비를 하고 있었어요. 누가 도와주면 좋겠는데... 같이 가실래요? $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4793, 'koKR', '난 $c|1은;는; 가르치지 않는다네.', '난 $c|1은;는; 가르치지 않는다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4794, 'koKR', '우리는 이 세계의 어둠이자 그림자요. 영원하며 보이지 않는...', '우리는 이 세계의 어둠이자 그림자요. 영원하며 보이지 않는...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4795, 'koKR', '젊은 도적이여, 안녕하시오? 무엇을 찾고 있소?', '젊은 도적이여, 안녕하세요? 무엇을 찾고 계세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4796, 'koKR', '난 자네를 가르칠 수 없어. 자네 직업에 맞는 상급자나 찾아가 보게.', '난 자네를 가르칠 수 없어. 자네 직업에 맞는 상급자나 찾아가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4797, 'koKR', '$n, 미안하네만 도와줄 수 없네. 난 도적만 가르친다네.', '$n, 죄송하지만 도와드릴 수 없어요. 전 도적만 가르친답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4798, 'koKR', '$n, 미안하네만 도와줄 수 없네. 난 도적만 가르친다네.', '$n, 죄송하지만 도와드릴 수 없어요. 전 도적만 가르친답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4799, 'koKR', '죄송합니다만, 전 도적만 가르칩니다.', '죄송합니다만, 전 도적만 가르칩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4813, 'koKR', '오! 또 손님이군. 어서 오시게! 내 위대한 발명품, 자동판매기 1000을 한번 사용해 보는 게 어때? 필요한 건 다 있다고. 칼림도어의 온 상점을 다 뒤져도 못 찾을 희귀한 물건도 있다네! 참, 값을 깎지 못하도록 프로그램했을 거라는 건 말 안 해도 알겠지? 그냥 달라는 대로 내라고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4814, 'koKR', '보나 마나 어둠의 여왕님께서 훈련을 시키라고 보내신 얼간이로군.$B$B<한숨을 쉬는 나타노스>$B$B이제까지 너 같은 놈들은 모조리 두 동강을 내서 여왕님께 돌려보냈지. 네놈도 같은 꼴이 될 거야.$B$B나야 뭐, 여왕님의 분부대로 할 뿐이니까 상관없지만 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4815, 'koKR', '정말 운이 좋으시군요. 방금 슈퍼 판매기 680의 정비를 마쳤는데. 아주 저렴한 물건이 잔뜩 쌓여 있습니다. 가서 한번 보시죠. 제 동생 코르크는 자동판매기 1000이 물건을 더 많이 팔 거라고 했지만, 흥!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4833, 'koKR', '$n, 도와줄 수 없겠구먼. 난 도적만 가르치거든.', '$n, 도와줄 수 없겠구먼. 난 도적만 가르치거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4834, 'koKR', '$n, 뭘 도와 드릴까요?', '$n, 뭘 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4835, 'koKR', '보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', '보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4837, 'koKR', '당신에게 내 기술은 별로 쓸모가 없을 것 같습니다. 상급 $c|1을;를; 찾아가면 도움을 받을 수 있을 거요.', '당신에게 제 기술은 별로 쓸모가 없을 것 같군요 상급 $c|1을;를; 찾아가면 도움을 받을 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4838, 'koKR', '전문가의 솜씨를 배우러 왔나?', '전문가의 솜씨를 배우러 왔습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4839, 'koKR', '네 눈에는 내가 $c|1으로;로; 보이나? 내 칼날을 너의 피로 물들이기 전에 썩 물러가라!', '당신 눈에는 내가 $c|1으로;로; 보입니까? 내 칼날을 당신 피로 물들이기 전에 썩 물러가세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4841, 'koKR', '안녕하시오? 이 혼란과 격동의 시기에 여명이 당신을 지켜주기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4855, 'koKR', '잘 키운 바라크 토롤 산양을 타보기 전까지는 제대로 된 탈것에 올라봤다고 할 수 없지요. 이 훌륭한 놈들을 언제라도 어느 모험가에게든 자랑스럽게 보여주십시오. 그리고 어떤 상황에서든지 아주 유용할 테니까요, 제 말을 믿으십시오.', '잘 키운 바라크 토롤 산양을 타보기 전까지는 제대로 된 탈것에 올라봤다고 할 수 없지요. 이 훌륭한 놈들을 언제라도 어느 모험가에게든 자랑스럽게 보여주십시오. 그리고 어떤 상황에서든지 아주 유용할 테니까요, 제 말을 믿으십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4856, 'koKR', '저는 최신형 자동 로봇 상인입니다. 언젠가는 우리가 세계를 지배할 것입니다. 제가 돈을 떼먹고 있다고 주인님에게 이르거나 하지는 마십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4857, 'koKR', '물건값을 깎을 수 없도록 프로그램되어 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4859, 'koKR', '수년에 걸친 품종 개량과 정성을 쏟은 결과로 탄생한 말들을 자랑스럽게 소개합니다! 타실 말을 천천히 골라 보세요. 말은 평생 친구죠. 오늘 여기서 멋진 녀석으로 한 마리 마련하세요! 당신은 소중한 분이시니까요!', '수년에 걸친 품종 개량과 정성을 쏟은 결과로 탄생한 말들을 자랑스럽게 소개합니다! 타실 말을 천천히 골라 보세요. 말은 평생 친구죠. 오늘 여기서 멋진 녀석으로 한 마리 마련하세요! 당신은 소중한 분이시니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4861, 'koKR', '사냥을 나갈 때는 사냥감을 찾아 나서기 전에 사냥감에 대해 누군가에게 물어보는 것이 좋다네.', '사냥을 나갈 때는 사냥감을 찾아 나서기 전에 사냥감에 대해 누군가에게 물어보는 것이 좋다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4862, 'koKR', '이놈이 코도요! 어렸을 때부터 멀고어의 황금 초원에서 훈련을 받으면서 자란 이 멋진 놈들은 정말 최고의 탈것이라고 할 수 있소! 코도들을 직접 한 번 보시오. 우리 타우렌이 이 멋진 친구들을 믿는 이유를 알게 될 거요!', '이놈이 코도요! 어렸을 때부터 멀고어의 황금 초원에서 훈련을 받으면서 자란 이 멋진 놈들은 정말 최고의 탈것이라고 할 수 있소! 코도들을 직접 한 번 보시오. 우리 타우렌이 이 멋진 친구들을 믿는 이유를 알게 될 거요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4863, 'koKR', '$C|1이여;여;, 세나리온 의회에 잘 오셨습니다.', '$C|1이여;여;, 세나리온 의회에 잘 오셨습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4864, 'koKR', '그대를 훌륭한 사냥꾼으로 훈련시켜 주겠소.', '그대를 훌륭한 사냥꾼으로 훈련시켜 주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4866, 'koKR', '자네에게 알려주고 싶은 게 많다네. 명예롭게 사냥하는 법을 배우는 것이 특히 중요하지.', '당신에게 알려드리고 싶은 게 많습니다. 명예롭게 사냥하는 법을 배우는 것이 특히 중요하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4867, 'koKR', '저는 사냥꾼들을 우리 선조들의 방식과 전통에 따라 가르치고 있습니다.', '난 사냥꾼들을 우리 선조들의 방식과 전통에 따라 가르치고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4868, 'koKR', '타우렌은 사냥에 대한 열정이 대단하지. 우리 종족은 사냥에 뛰어난 재능을 타고났소.', '타우렌은 사냥에 대한 열정이 대단하지요. 우리 종족은 사냥에 뛰어난 재능을 타고났습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4869, 'koKR', '왕립 연금술 학회를 대표해서 우리 포세이큰의 동지에게 최고로 훌륭한 탈것을 제공하게 되어 기쁘군. 우리는 이놈들을 고된 훈련을 통해서 더 강하게 길렀지. 직접 살펴보면서 확인하게.', '왕립 연금술 학회를 대표해서 우리 포세이큰의 동지에게 최고로 훌륭한 탈것을 제공하게 되어 기쁘군. 우리는 이놈들을 고된 훈련을 통해서 더 강하게 길렀지. 직접 살펴보면서 확인하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4870, 'koKR', '사냥꾼의 길에 대해 배우십시오. 긍지, 명예, 그리고 전통에 대해서 말입니다.', '사냥꾼의 길에 대해 배우시오. 긍지, 명예, 그리고 전통에 대해서 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4871, 'koKR', '뛰어난 산양 기수가 되는 법을 가르쳐 주겠어요. 단 수업료로 낼 골드만 충분하다면 말이죠!', '뛰어난 산양 기수가 되는 법을 가르쳐 주겠어요. 단 수업료로 낼 골드만 충분하다면 말이죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4873, 'koKR', '뛰어난 해골마 기수가 되는 법을 가르쳐 주지. 그런데 자네... 수업료는 충분한가?!', '뛰어난 해골마 기수가 되는 법을 가르쳐 주지. 그런데 자네... 수업료는 충분한가?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4874, 'koKR', '뛰어난 코도 기수가 될 수 있도록 제가 알고 있는 모든 기술을 전수해 드리겠습니다. 단, 수업료는 내셔야 합니다!', '뛰어난 코도 기수가 될 수 있도록 제가 알고 있는 모든 기술을 전수해 드리겠습니다. 단, 수업료는 내셔야 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4875, 'koKR', '뛰어난 랩터 기수가 되는 법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분하겠지요?!', '뛰어난 랩터 기수가 되는 법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분하겠지요?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4876, 'koKR', '뛰어난 승마 기술을 가르쳐 드리겠습니다. 단, 수업료는 제대로 내셔야 합니다!', '뛰어난 승마 기술을 가르쳐 드리겠습니다. 단, 수업료는 제대로 내셔야 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4877, 'koKR', '그대에게 뛰어난 호랑이 기수가 되는 방법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분한가요?!', '그대에게 뛰어난 호랑이 기수가 되는 방법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분한가요?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4878, 'koKR', '제가 기계타조 조종법을 가르쳐 줄 수 있어요. 손에 몇 골드나 쥐었는지 한번 짤랑거려 보세요. 헤헤... 수업료가 충분한지 궁금해서요.', '제가 기계타조 조종법을 가르쳐 줄 수 있어요. 손에 몇 골드나 쥐었는지 한번 짤랑거려 보세요. 헤헤... 수업료가 충분한지 궁금해서요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4879, 'koKR', '뛰어난 늑대 기수가 되는 법을 가르쳐 주겠소. 단, 수업료만 충분하다면!', '뛰어난 늑대 기수가 되는 법을 가르쳐 주겠소. 단, 수업료만 충분하다면!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4881, 'koKR', '당신에게 기계타조 조종법을 가르쳐 봤자 돈 낭비에, 시간 낭비예요. 당신은 너무 크시잖아요!', '당신에게 기계타조 조종법을 가르쳐 봤자 돈 낭비에, 시간 낭비예요. 당신은 너무 크시잖아요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4888, 'koKR', '난 여러 세대를 거쳐 내려온 전통적인 방법으로 젊은 사냥꾼들을 가르치고 있소.', '전 여러 세대를 거쳐 내려온 전통적인 방법으로 젊은 사냥꾼들을 가르치고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4889, 'koKR', '이 세계의 모든 것이 연관되어 있다는 것을 잊지 마시오. 만일 이 대지에 짐승들이 사라진다면 우리 종족은 영혼이 메말라 죽어버릴 것이오. 짐승들에게 무슨 일이 생긴다면 우리 타우렌도 결코 무사할 수 없소. 아제로스의 대지와 그곳에 사는 생명들은 운명을 같이하는 법이지.', '이 세계의 모든 것이 연관되어 있다는 것을 잊지 마세요. 만일 이 대지에 짐승들이 사라진다면 우리 종족은 영혼이 메말라 죽어버릴 것입니다. 짐승들에게 무슨 일이 생긴다면 우리 타우렌도 결코 무사할 수 없지요. 아제로스의 대지와 그곳에 사는 생명들은 운명을 같이하는 법이니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4890, 'koKR', '사냥 전략을 배우러 왔다면 제대로 찾아왔네!', '사냥 전략을 배우러 왔다면 제대로 찾아오셨습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4891, 'koKR', '어이! 바다 깊숙이 잠수해본 적 있나? 내가 비밀 하나 알려줌세. 물속으로 깊이 들어가면 거품 균열이 있네. 그 근처에 있으면, 물속에서도 숨을 쉴 수 있지. 이건 우리끼리만 알고 있자고, 알았나? 가재 잡는 데 경쟁자가 생기는 건 싫으니까 말일세. 무슨 말인지 알겠지?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4893, 'koKR', '야수의 지혜와 지식을 보면 자신을 볼 수가 있소. 올빼미와 같은 관찰력을 기르고, 퓨마의 영리함을 배우며, 늑대의 강한 영혼을 몸에 담도록 하시오.', '야수의 지혜와 지식을 보면 자신을 볼 수가 있소. 올빼미와 같은 관찰력을 기르고, 퓨마의 영리함을 배우며, 늑대의 강한 영혼을 몸에 담도록 하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4913, 'koKR', NULL, '그대는 드루이드가 아니지 않습니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4914, 'koKR', NULL, '세나리온 의회에서 베푸는 호의입니다. 루테란 마을로 날아가시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4915, 'koKR', NULL, '다시 썬더 블러프로 날아가려면 저 같은 일을 하는 타우렌, 분덴 플레인즈윈드와 대화를 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4916, 'koKR', '그대는 드루이드가 아니잖소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4917, 'koKR', '루테란 마을로 다시 날아가려 하오? 그렇다면 나와 같은 일을 하는 나이트 엘프, 실비아 필나베스와 이야기를 나눠보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4918, 'koKR', '세나리온 의회에서 베푸는 호의요. 썬더 블러프로 날아가시겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4933, 'koKR', '우리가 사는 이 시대는 풍향이 바뀌듯 변덕스럽소. $c, 땅이 저절로 열리고, 괴로움으로 울부짖고 있소. 굳세게 버텨야 하오. 그러지 않으면 우리는 이 혼란에 압도당하고 말 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4934, 'koKR', '$C|1이여;여;, 아제로스에서 우리만큼 고통을 당한 종족은 없다네. 죽음을 눈앞에 두고도 웃음을 짓는 건 이제 우리의 천성처럼 돼버렸지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'koKR', '반갑습니다, $N. 나라체 야영지에 오신 걸 환영합니다. 당신이 왔다는 소식이 벌써 부족에 쫙 퍼졌군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4936, 'koKR', '아! 아름다운 그늘 협곡은 언제나 저의 오감을 만족시켜 주지요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'koKR', '오, 꽤 튼튼해 보이는군? 몇 가지 일을 도와줄 수 있겠어. 여기엔 풋내기 견습생밖에 일손이 없는데, 그 애들도 신경 쓸 일이 따로 많거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4938, 'koKR', '북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4953, 'koKR', '날 도와주었으니 이 땅에 대해서 아는 대로 말해주겠소. 내 지식이 그리 깊지는 않지만, 어쩌면 당신 같은 이가 흥미를 가질 만한 사실을 몇 가지 알려줄 수 있지도 않겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4954, 'koKR', '나이트 엘프에 대해 내가 알고 있는 지식에는 한계가 있소. 하지만, 일전에 들은 바로는 오래전 나이트 엘프가 아직 비전 마법의 성스러움을 지키고 있을 당시, 아즈샤라가 그중 가장 뛰어났다고 하오. 그들은 이 아름다운 여인을 여왕으로 받들었소. 하지만 비전술에 중독이 되어버린 여왕은 역사상 가장 파괴적인 사건의 주인공이 되어버렸소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4955, 'koKR', '그곳은 한때 거대한 나이트 엘프 도시였소. 엘프의 명가가 군림하며 아주 강력한 비전 마법을 연마했지. 하지만 지금은 저주를 받아 유령처럼 그곳을 떠돌고 있지. 폐허가 되어버린 도시는 원한꼬리 나가들 때문에 더욱더 황폐해지고 말았소. 나가들은 그 폐허에 숨겨진 강력한 명가의 유물을 찾아다니는 걸로 알고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4956, 'koKR', '북쪽에 아주 강력한 힘을 지닌 인간 마법사가 산다는 소문이 있소. 어째서인지 이 땅을 감시하고 있다더군. 나도 직접 만난 적은 없지만 들리는 바로는 누구든지 방문할 수 있고, 그자가 시키는 일을 좀 해주면 아주 친절하게 대해 준다고 하더이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4957, 'koKR', '지난 몇 년 동안 펄볼그에게는 끔찍한 일들이 일어났소. 수많은 전투에서 피해를 입었지. 하지만 그 부족이 왜 그렇게 되었는지는 잘 모르오. 악령숲에 퍼진 역병으로 인해 타락했을 수도 있고, 한때는 평화로웠던 자기 종족에게 생긴 일이 화가 나서 지나치게 자기방어적으로 변한 걸 수도 있지. 이유야 어떻든 녀석들은 그 지역에 들어오는 모든 자들에게 아주 공격적이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4958, 'koKR', '이곳에 푸른용혈족은 없지만, 말리고스의 추종자들은 있소. 정확한 이유는 모르겠지만 한 가지는 분명하오. 푸른용혈족이 있는 곳에는 비전 마법이 있게 마련이라는 것이지. 이곳에서 용혈족이 뭔가를 보호하고 있다고 해도 놀라운 일은 아니오... 어쩌면 엘프의 명가가 남긴 것을 보호하는 걸지도 모르오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4959, 'koKR', NULL, '시간제 직원이라도 고용해야겠어요. 온종일 여기 앉아 낚시용품이나 파는 건 정말 지겹군요. 장사보단 낚시가 제 적성에 맞습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4960, 'koKR', NULL, '트롬카, $c. 오늘 기분이 무척 좋지 않으니, 도와주러 온 게 아니라면 혼자 있게 내버려둬.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4973, 'koKR', '$c|1이여;여;, 당신은 내게 훈련을 받을 수 없습니다.', '$c|1이여;여;, 당신은 내게 훈련을 받을 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4974, 'koKR', '나는 용맹호의 선장, 율리시스 랙모어다. 돌이킬 수 없는 운명에 처한 우리 배에서 마지막 며칠 동안의 일을 이 일지에 기록했다.$B$B보급 물자를 싣고 페더문 요새로 향하던 중 나가들이 배의 측면을 공격해 왔다. 간신히 녀석들을 몰아내기는 했지만, 놈들이 되돌아오리란 걸 알고 있었다. 나는 귀중한 물건들을 잃어버릴까 염려해 용맹호를 잊혀진 땅의 해안에서 좀 떨어진 섬으로 몰고 갔다. 그 섬은 나이트 엘프의 고대 유적이 있는 곳으로서, 나는 거기에 보물이', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4975, 'koKR', '내 궤짝은 견고하게 설계되어 있으며, 궤짝을 열려면 은색 열쇠와 금색 열쇠가 필요하다. 첫 번째 열쇠인 은색 열쇠는 내 일등항해사에게 주었고 금색 열쇠는 내가 가지고 있었다.$B$B하지만, 우리는 그 열쇠를 잃어버리고 말았다. 금색 열쇠는 나가를 공격하던 중 잃어버렸고, 은색 열쇠는 다음날 사나운 마크루라가 쳐들어와 일등항해사를 물속 깊이 끌고 가버리면서 잃어버렸다.$B$B분명 나가와 마크루라가 두 열쇠를 가지고 있을 것이다. 녀석들이 사이가 좋지 않아', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4976, 'koKR', '마크루라의 습격을 받은 후, 우리는 용맹호가 또다시 공격을 받으면 버텨내지 못할 것임을 알았다. 그래서 나와 살아남은 선원들은 배를 버렸다.$B$B이제 바닷가에 왔으니 곧 나이젤의 야영지로 갈 생각이다. 하지만 그 길에는 너무나 많은 위험이 도사리고 있다. 잊혀진 땅이 우릴 집어삼킬까 두렵다.$B$B언젠가 어느 영웅이 이 곤경을 알고, 우리를 이 지경으로 만든 물귀신 놈들에게 복수해 주길 바라는 마음에서 이 글을 남긴다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4977, 'koKR', NULL, '달숲에서 이곳 레물로스의 제단은 우리 세나리온 의회가 모이는 성스러운 곳이니 방문객의 신분에 어긋나지 않게 행동해 주시기 바랍니다.$B$B제 시미터에 당해 숲에 묻히고 싶지 않다면 말이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4978, 'koKR', NULL, '세나리우스의 가호가 당신과 함께하기를.$B$B저는 타자리라고 합니다. 이 제단을 수호할 것을 맹세했지요. 수호자 레물로스를 받들어 이 성스러운 땅의 관리인으로서 일하는 것은 정말 영광이랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4979, 'koKR', '스컬지가 오기 전까지만 해도, 나도 정말 잘 나갔는데 말이야. 뭐든지 사고 팔았지. 뭐든지!$B$B정말 말도 안 되게 가격도 높게 불렀는데도 말이야!$B$B살아있는 자라면 다 알 테니 아무나 붙잡고 물어보라고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4980, 'koKR', '안녕하신가, $n! 뭔가 사러 온 건가? 아니면 팔러?$B$B여기보다 더 싼 곳은 없을 거야. 아니면 내가 성을 갈겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4982, 'koKR', '$n, 이곳은 위험한 곳입니다. 조심하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4984, 'koKR', '$c|1이여;여;, 내 시간을 뺏지 않는 게 좋을 걸세.', '$c|1이여;여;, 내 시간을 뺏지 않는 게 좋을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4985, 'koKR', '난 $c|1은;는; 가르치지 않는데... 괜히 성질 돋우지 말고 자네에게 맞는 상급자나 찾아가 보게.', '난 $c|1은;는; 가르치지 않는데... 괜히 성질 돋우지 말고 자네에게 맞는 상급자나 찾아가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4986, 'koKR', '딴 데 가서 알아보게. 나는 전사만 가르치니까.', '딴 데 가서 알아보게. 나는 전사만 가르치니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4987, 'koKR', '뭘 도와드릴까?', '뭘 도와드릴까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4988, 'koKR', '당신, 직업의 호환성이 저와는 일치하지 않는 문제로 인해, 당신의 능력이 모자라 처한 상황을 수정하도록 도와드릴 수 없군요.', '당신, 직업의 호환성이 저와는 일치하지 않는 문제로 인해, 당신의 능력이 모자라 처한 상황을 수정하도록 도와드릴 수 없군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4989, 'koKR', '훌륭합니다! 필요한 변수와 규격에 관한 요구 사항을 모두 만족하는군요. 뭘 도와드릴까요?', '훌륭합니다! 필요한 변수와 규격에 관한 요구 사항을 모두 만족하는군요. 뭘 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4990, 'koKR', '저는 헤그너 럼블샷이라고 합니다. 말씀만 하십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4991, 'koKR', '테라모어가 뛰어난 전사 훈련으로 명성을 떨치고 있긴 하지만, 안타깝게도 당신을 도와드릴 수는 없소.', '테라모어가 뛰어난 전사 훈련으로 명성을 떨치고 있긴 하지만, 안타깝게도 당신을 도와드릴 수는 없소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4992, 'koKR', '테라모어 경비병과 함께 훈련을 받으러 온 거군요?', '테라모어 경비병과 함께 훈련을 받으러 온 거군요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4993, 'koKR', '그대와 같은 $c|1을;를; 가르칠 수는 없습니다.', '그대와 같은 $c|1을;를; 가르칠 수는 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4994, 'koKR', '무슨 일로 오셨소이까?', '무슨 일로 오셨습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4995, 'koKR', '불의 군주님은 한때 동지들과 함께 전 세계를 군림했었다. 그분은 고대 신의 신하로서 티탄들과 이 세계를 장악하기 위한 싸움을 벌였지. 하지만 승리는 티탄들에게 돌아갔고 주인님은 동지들과 정령계로 영원히 추방당했다. 그리고 티탄의 시대가 끝날 때까지 그곳에 갇히고 말았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4996, 'koKR', '나는 그대를 훈련시켜줄 수 없소, 젊은이.', '저는 당신을 훈련시켜줄 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4997, 'koKR', '총이 좋습니까, 아니면 활이 더 마음에 드십니까?', '총이 좋습니까, 아니면 활이 더 마음에 드십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4998, 'koKR', '당신이 구하는 지식은 나에게 없소이다.', '당신이 구하는 지식은 나에게 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4999, 'koKR', '무슨 일로 오셨습니까?', '무슨 일로 오셨습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5000, 'koKR', '나는 당신을 훈련시킬 수 없으니 상급 $c|1을;를; 만나보십시오.', '저는 당신을 가르칠 수 없으니 상급 $c|1을;를; 만나보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5001, 'koKR', '뭔데요?', '뭐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5002, 'koKR', '이건 시간 낭빈데...', '이건 시간 낭빈데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5003, 'koKR', '나는 자네를 훈련시킬 수 없네.', '저는 당신을 훈련시킬 수 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5004, 'koKR', '반갑네. 자네는 상급 $c|1을;를; 찾아가야겠군.', '반갑습니다. 당신은 상급 $c|1을;를; 찾아가야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5005, 'koKR', '영혼들이 당신을 나에게로 이끌어주셨군. 무얼 도와드리면 되겠소?', '영혼들이 당신을 내게로 이끌어주셨군요. 무얼 도와드리면 되겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5006, 'koKR', '영혼이 그대와 함께하기를.', '영혼이 그대와 함께하기를.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5007, 'koKR', '자네의 존재감에서 영혼의 힘이 강하게 느껴지는군. 이 트롤이 무슨 일을 도와주면 되나?', '자네의 존재감에서 영혼의 힘이 강하게 느껴지는군. 이 트롤이 무슨 일을 도와주면 되나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5008, 'koKR', '영혼들의 가호가 있기를.', '영혼들의 가호가 있기를.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5009, 'koKR', '어디로 가시려고 하십니까? 어딜 가시든지, 빠른 여행을 원하신다면 더 멀리 가서 찾을 것도 없습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5010, 'koKR', '난 항상 감시의 언덕에 물자를 충분히 비축해 두려고는 하지만, 이렇게 전투가 빈번하게 일어나서 쉽지만은 않소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5011, 'koKR', '불과 300년 전, 타우릿산이라는 무모한 드워프 하나가 주인님을 불타는 세계로부터 소환해냈다. 주인님께서 이 보잘것없는 작은 세계로 귀환하시는 것만으로, 땅이 파괴되고 화산의 심장부가 생겨났지. 그때부터 위대하신 라그나로스는 이 산 아래 잠들어 계신다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5012, 'koKR', '우리는 그분의 종으로 헌신할 것을 맹세했고, 주인님의 철권 통치를 받들어 지시를 따르며 시행한다. 라그나로스 님이 현신하셔도 불의 세계로부터 정기를 받지 못하기 때문에 실체가 아닌 그림자에 불과하지만, 너 정도는 끝내고도 남을 만큼 강력하시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5013, 'koKR', '안녕하십니까? 악수를 청하고 싶지만 보시다시피 뭘 하고 있는 중이라서요... 제가 도와 드릴 일이라도 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5014, 'koKR', '$n, 첫 출발은 좋습니다만 아직 배울 건 많이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5015, 'koKR', '제가 알고 있는 건 모두 가르쳐 드렸으니 더 많은 것을 배우고 싶으면 스톰윈드 마법사 지구에 있는 나이트 엘프 릴리시아 나이트브리즈를 만나 보십시오. 그녀가 연금술에 대해서는 잘 가르친다는 소문이 있더군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5016, 'koKR', NULL, '이 조그만 집 안에서 전 성벽 밖에서 한창 벌어지고 있는 전투에 참가하는 꿈을 꾸곤 합니다. 하지만 지금으로서는 의무감에 저를 대신해서 싸움터로 나가는 이들에게 지식을 나누어줄 수밖에 없답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5019, 'koKR', '이시누 알라, 엘룬께 영광을. 저에게 외부 소식이라도 가지고 오셨습니까? 텔드랏실의 소식이 무척 궁금하답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5020, 'koKR', '그대에게 저의 지식을 나누게 되어 영광입니다. 부디 잘 사용하시기를 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5021, 'koKR', '그대는 제 능력을 벗어나셨으니 좀 더 숙련된 스승을 찾아가시는 게 좋겠습니다. 이곳에 있는 릴리시아 나이트브리즈를 만나 보시면 배울 것이 많을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5022, 'koKR', NULL, '드루이드들이 말하길 자연 스스로 호드를 칼림도어에서 밀어내는 것은 시간문제라고 하더군요. 하지만 우리의 대지는 계속 오염되고 있고 여기 텔드랏실도 마찬가지입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5023, 'koKR', NULL, '잘하셨습니다! 물약에 대한 이해가 빠르시군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5024, 'koKR', NULL, '안타깝게도 그대와 같이 경험 많은 이에게 제가 할 수 있는 일은 거의 없습니다. 다르나서스 장인의 정원에 거주하는 나이트 엘프 실반나 포레스트문을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5025, 'koKR', NULL, '엘룬 아도레, $g형제:자매;여, 잘 오셨습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5026, 'koKR', NULL, '숲에 있는 식물로 창조할 수 있는 것들이 정말 놀랍지 않습니까? 실로 엘룬께서 우리를 아낌없이 축복하셨습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5027, 'koKR', NULL, '저를 찾아 주시니 감사하지만 그대는 제 능력을 능가하시는군요. 바로 저쪽 편에 있는 실반나 포레스트문을 만나 보세요. 그녀가 제자로 삼을 만한 이를 찾고 있더군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5028, 'koKR', '사랑스러운 칼리가 당신을 여기로 보냈나? 눈에 넣어도 아프지 않을 만큼 사랑스럽지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5029, 'koKR', '나의 사랑스러운 칼리 얘기를 하려고 온 것 같진 않군. 그렇다면 좋아, 물약에 대해 얘기를 하지. 당신은 너무 융통성이 없다고 누가 말해주지 않든가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5030, 'koKR', '당신은 내 능력 밖이군. 아이언포지 땜장이 마을에 사는 노움인 탈리 베리피즈에게 가서 졸라보시오. 아, 그리고 가는 김에 사랑스러운 칼리에게 안부도 좀 전해주시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5031, 'koKR', '크고 순진해 보이는 그녀의 눈을 보고 착각하지 말게나. 탈리는 대단한 전문가야. 매일 새로운 것을 배우곤 하지. 내가 왜 땜장이 마을에 있다고 생각하나? 내가 기술자로 보이나? 그래, 당연히 아니지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5032, 'koKR', '힘 좀 써보라고! 고된 일과 결단력만이 살길이야! 책만 보면 모든 걸 배울 수 있다는 녀석들은 쳐다보지도 말게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5033, 'koKR', '흠, 자네에겐 가르칠 게 하나도 없군. 저기 있는 탈리 베리피즈에게 가 보게. 탁자에 겨우 팔이 닿는 키지만 물약을 제조할 때는 조심하는 게 좋다네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5034, 'koKR', '모험을 찾고 있는 게로군. 나도 말이야... 우리 트롤이 이곳으로 왔을 때 지겹게 모험을 찾아 다녔지. 이제는 하루하루를 다른 이들을 가르치면서 그들의 모험담을 듣는 낙으로 살지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5035, 'koKR', '다음 수업을 받을 준비가 됐나? 좋아, 그렇다면 먼저 긴장을 풀게. 물약을 올바르게 저으려면 긴장하면 안 돼.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5036, 'koKR', '내게는 너무 어려운 요청이군. 오그리마 골목길에 있는 오크 옐마크를 만나 보면 자네를 도와줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5037, 'koKR', '탁자에 있는 물약은 전부 내가 오늘 만든 것이지. 냄비를 쳐다보고 있으면 절대 끓지 않는다고 그러더군. 하하!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5038, 'koKR', '다들 나보고 멍청하다고 했지만 그들에게 보여주고 말겠어. 여기 있는 모든 냄비를 쳐다보고 있다가 그래도 물약이 끓는다는 것을 증명해 보이겠어! 꼭 성공할 거야! 이제 누가 진짜 멍청한지 말해봐! 말해보라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5039, 'koKR', '난 자넬 도와줄 수 없어. 자넨 나보다 물약에 대해 더 많이 알고 있네. 게다가 난 이 냄비들을 계속 쳐다봐야 한다고. 저기 있는 옐마크에게 가 보게. 저 친구는 물약에 대해 많이 알고 있으니까 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5040, 'koKR', '베나는 마치 신들린 것처럼 일을 한다네. 잠도 안 자고 밥도 안 먹고 밤낮으로 물약 제조에만 파묻혀 있었지. 나도 언데드 동맹들이 도움을 필요로 한다는 것을 모르는 건 아니지만 저러다가 쓰러지고 말지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5041, 'koKR', '내가 처음 물약을 만들기 시작했을 때 약병을 수도 없이 깼지. 내 서툰 손놀림에 유리 약병이 너무 쉽게 깨진 걸세. 자넨 나보다는 조심성이 있기를 바라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5042, 'koKR', '자네의 능력이 나를 능가했군. 더 많은 것을 배우고 싶다면 저기에 있는 베나 윈터후프에게 가는 것이 좋을 걸세. 하지만 베나도 쉬어야 하니까 시간을 너무 많이 뺐지는 말게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5043, 'koKR', NULL, '정다운 얼굴을 보니 좋군. 연금술사 요한은 뭔가 원하는 것이 있을 때만 잡담을 늘어놓지. 그는 무덤 밖에 너무 오래 있었네. 언젠가는 나도 그렇게 되겠지. 소름 끼치지만 그때쯤이면 별로 신경 쓰지 않을지도 모르겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5044, 'koKR', NULL, '물약에 대해 배우러 왔다고? 가르쳐 줄 것이 아주 많다네. 죽은 몸이긴 하지만 아직은 머리까지 죽진 않았네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5045, 'koKR', NULL, '같이 지내게 된다면 좋겠지만 현실을 직시하자고. 자넨 나보다 물약 제조 경험이 더 많잖나. 더 많은 것을 배우고 싶으면 언더시티 연금술 실험실에 있는 포세이큰인 학자 마쉬를 찾아가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5046, 'koKR', '한때는 나도 인간이었네. 인간의 약점이 우리에게는 이점이 되기도 하지. 난 인간의 약점을 속속들이 알거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5047, 'koKR', '좋아. 표본에서 살점을 더 잘라내 보게. 자, 이제까지 배운 것을 시험해 볼까나. 시험을 기초로 더 많은 것을 배울 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5048, 'koKR', '물약에 대한 지식이 나를 능가했군. 하지만 자넨 아직도 더 배울 것이 많네. 동남쪽 계단을 따라 올라가서 학자 마쉬를 만나 보게나. 그가 진정한 고통을 가르쳐 줄 걸세... 에헴! 학자 마쉬는 포세이큰으로서 자네에게 많은 것을 가르쳐 줄 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5049, 'koKR', '그렇게 쳐다보지 마시오! 당신과 같은 모험가는 아니어도 근육정도는 있다오. 물약을 휘저으면 팔이 이렇게 강해지지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5050, 'koKR', '자네에겐 더 가르칠 게 더 없군. 하지만 자네를 가르칠 만한 나이트 엘프를 하나 알고 있다네. 에이네실이라고 다르나서스 장인의 정원에 살고 있으니 그리 가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5051, 'koKR', '미안하지만 난 초보자를 가르칠 시간은 없네. 자네 기술 숙련도에 맞는 자를 찾아보도록 하게나. 다르나서스 장인의 정원에 있는 나이트 엘프 밀라 페어랜코라에게 가 보는 게 좋겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5053, 'koKR', '내 도움이 필요하다고? 좋아. 뭘 도와줄까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5054, 'koKR', NULL, '말똥말똥한 눈과 무성한 수염을 보고 착각하지 말라고요. 보수르는 유능한 수습생이자 좋은 친구랍니다. 얘기할 때 목에 쥐가 날 것 같기는 하지만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5055, 'koKR', NULL, '음... 제가 가르칠만한 것은 이미 다 아시네요. 이제 다른 스승을 찾아갈 시간입니다. 다르나서스 장인의 정원에 있는 나이트 엘프 에이네실을 한 번 찾아가 보세요. 정말 유능한 나이트 엘프랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5057, 'koKR', NULL, '좋아요. 저기 있는 보수르에게 뭔가 보여 주세요. 모르는 것이 있으면 물어보시면 될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5058, 'koKR', NULL, '누구신데 절 귀찮게 하시죠? 아, 맞다. 물약 제조에 대해 배우려는 분이시군요. 좋아요. 뭘 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5059, 'koKR', NULL, '이시누 달 디에브, $n. 지식을 추구하려 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5060, 'koKR', NULL, '가르친다는 것은 주기만 하는 것이 아닙니다. 당신을 가르침으로써 저 또한 배우고 제가 가진 지식도 늘어가는 것이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5063, 'koKR', NULL, '제 능력을 인정하시니 기쁘지만 당신은 이미 제 능력을 앞질렀습니다. 다르나서스 장인의 정원으로 가셔서 나이트 엘프인 에이네실을 만나시면 그녀가 당신을 도와줄 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5064, 'koKR', NULL, '물약의 재료를 조금만 바꿔도 완전히 다른 물약이 된답니다. 인내와 정확성이 필요한 것이지요. 이 두 요소는 삶의 모든 영역에서 도움이 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5065, 'koKR', NULL, '제 물약 제조술은 그대에 비해 수준이 낮습니다. 이제 저기에 있는 에이네실을 만나도 되겠군요. 그녀도 그대가 좀 더 수준이 높은 교육을 받을 시간이 되었다는 것을 알아볼 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5067, 'koKR', NULL, '아, 젊음이란... 물약을 처음 접했을 때는 또 어떻고... 기억을 상기시켜줘서 고맙습니다. 이제 저기에 있는 밀라 페어랜코라와 젊은 열정을 나누어 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5068, 'koKR', NULL, '전 오랫동안 물약 제조법에 대해 많은 것을 배웠습니다. 이제는 그 지식을 그대에게 전해드릴 테니 말씀만 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5069, 'koKR', '난 바쁩니다, $n. 무슨 일로 왔든 우트에게 가 보십시오. 그 풋내기 녀석... 온종일 뭔가 푹푹 끓이고만 있는데, 계속 저러다간 무슨 일이 나고 말 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5070, 'koKR', '만나서 영광이오, $n. 당신의 연금술 기술이 내 솜씨보다 낫군. 언더시티 연금술 실험실에 있는 언데드 학자 허버트 핼시를 찾아가 보시오. 이제부터는 그가 도와줄 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5072, 'koKR', '당신은 잘못 찾아왔군. 난 초보자는 가르치지 않소이다. 저기 있는 우트라는 젊은이에게 가 보시오. 저 친구랑 얘기할 때 긴 단어는 사용하지 마시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5073, 'koKR', '또 다른 학생이로군? 좋아. 도와주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5074, 'koKR', '글릭스와 난 서로 이해관계가 있지. 글릭스는 나에게 물품을 공급해 주고 나는 글릭스를 부자로 만들어 주거든. 농담은 그만하고! 그 해적놈이 쭈글쭈글한 왕꽃잎풀을 쥐방울만한 주머니에 넣어 주면서 돈을 얼마나 많이 달라고 하는지... 다 큰 고블린도 울 정도라니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5075, 'koKR', '난 좋은 제조법을 아주 많이 보유하고 있다고. 자, 이거 보라고... 게다가 할인도 해 준다니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5078, 'koKR', '나보다 훨 낫군! 나보다는 경험이 풍부한 스승이 필요하겠는걸? 그렇다면 아마 다르나서스의 장인의 정원에 사는 나이트 엘프 에이네실 정도가 되겠지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5079, 'koKR', NULL, '처음으로 언데드를 봤을 땐 그들의 공포와 외로움이 너무 커보였기에 눈물을 흘릴 수밖에 없었습니다. 그때 대지모신께서 제게 말씀하셨지요. 그분께서는 제 핏속에서 노래하셨습니다. 그러시면서 \"그들을 구하라.\"고 말씀하셨답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5080, 'koKR', NULL, '당신은 대지모신께서 사랑스러운 자식인 언데드들을 잃는 것에 대해 고뇌하고 계시다는 것을 느낄 수 없단 말입니까? 한시가 급하니 어서 말해보십시오. 그들이 대지모신에게 돌아갈 수 있도록 도와줘야만 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5081, 'koKR', NULL, '내 양심상 우리 동맹인 언데드들이 고통을 겪고 있는 상황에서 초보자를 가르칠 수는 없습니다. 나 대신 저기 있는 크레이에게 부탁하면 당신을 도와줄 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5083, 'koKR', NULL, '당신의 물약 제조 기술은 나를 능가하는군요. 그렇다면 언더시티 연금술 실험실에 있는 언데드 학자 허버트 핼시를 찾아가도록 하십시오. 그 친구는 당신에게 더 많은 것을 가르칠 수 있는 기술이 있는데다가 당신 눈으로 직접 언데드들의 고통을 목격할 수도 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5084, 'koKR', '또 방해로군. 이런 식으로 나오면 대체 나보고 어떻게 일을 하라는 거요? 대답할 필요 없소. 변명 따위 듣자고 한 말이 아니니까. 만약 이곳을 청소하고 우리 제국의 영토를 확장할 생각이라면 날 좀 가만히 놔두시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5085, 'koKR', '당신에게 기술을 가르쳐달라는 말입니까? 왜 이러십니까? 안 된다는 거 알면서... 제 기술이 부족해서 가르칠 게 없습니다. 언더시티 연금술 실험실에 있는 포세이큰 학자 허버트 핼시를 찾아가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5087, 'koKR', '제 시간을 뺏지 마십시오. 제겐 당신이 살아온 시간보다도 더 오래 연구해 온 과제가 있단 말입니다. 언더시티 연금술 실험실에 있는 박사 마틴 펠벤을 찾아가보십시오. 그 포세이큰이라면 기초부터 가르쳐줄 수 있을 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5088, 'koKR', '새로 온 제자인가? 멋지군. 이래서 라이던은 관리자로 칭송받고 난 여기 처박혀서 교습이나 하는 거겠지. 또다시 올해의 최우수 강사로 선정되는 날에는 민망해서 얼굴도 못 들고 다닐 거야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5089, 'koKR', '알게르논이 물품을 다 대주니 나는 약초 하나 안 캐고 여기서 작업을 할 수 있다네. 앞으로도 계속해서 약초를 직접 캐지 않아도 된다면 멀지 않아 할 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5090, 'koKR', '자네에겐 더 이상 가르칠 지식이 없네. 아치길을 지나 동남쪽 경사로 밑으로 가서 학자 허버트 핼시를 만나 보게. 그 친구가 자네에게 전문 기술을 가르쳐 줄 포세이큰일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5092, 'koKR', '나를 찾아와 가르쳐 달라고 하다니 뻔뻔스럽기 짝이 없군. 아치길을 지나 동남쪽 경사로 밑으로 가서 박사 마틴 펠벤을 만나 보게. 그 친구가 자네를 기초부터 가르쳐 줄 포세이큰이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5093, 'koKR', '연금술을 배우러 왔다고? 아주 좋아. 자네를 가르친다고 우리 동맹에 해가 되지는 않겠지. 자네가 우리의 적들에게 피해를 줄 수 있는 한은 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5094, 'koKR', NULL, '똑같은 재료를 쓰는데도 제가 만든 물약을 사용하면 상처가 덜 아무는 것 같아요. 식물들이 변하고 있다는 한 가지 결론이 나오네요. 하지만 식물들이 무슨 이유로 무엇으로 변하고 있는지는 말씀 드릴 수가 없군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5095, 'koKR', NULL, '이제 그대는 좀 더 숙련된 스승에게 배울 때가 되었습니다. 페랄라스의 페더문 요새에는 킬란나 윈드위스퍼라는 나이트 엘프가 살고 있답니다. 그녀는 지력이 대단하니 그대에게 많은 것을 가르쳐 줄 수 있을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5097, 'koKR', NULL, '그대는 저의 제자가 되기에는 물약 제조 기술이 부족합니다. 저기 있는 실반나 포레스트문이나 밀라 페어랜코라가 그대를 도와줄 수 있을 듯싶군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5098, 'koKR', NULL, '교육을 잘 따라오시는군요. 자신의 성과에 자부심을 가져도 좋습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5099, 'koKR', '나와 내 동료는 우리가 아는 가장 치명적인 물질들을 모아 적에게 그 효과를 시험해 보고 있습니다. 필요한 걸 모두 알아내면, 여태 본 적도 없는 무시무시한 역병을 만들어낼 수 있겠지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5100, 'koKR', '놀라워. 자네의 물약은 내 물약과 비교해도 손색이 없군. 더 가르칠 것이 없네. 하지만 슬픔의 늪, 스토나드로 가서 최신 실험으로 유명한 로그바라는 오크를 만나 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5102, 'koKR', '자넨 나에게 배우기에는 아직 기술이 부족하군. 저기 있는 마틴 펠벤 박사에게 가 보게나. 아니면 동남쪽으로 경사로를 올라가서 학자 마쉬에게 가던가. 그들은 자네에게 필요한 기술을 가르쳐 줄 수 있는 포세이큰들이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5103, 'koKR', '훈련 준비는 됐나? 그렇다면 배울 내용이 아주 방대하니까 잘 따라오게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5104, 'koKR', NULL, '한때 저는 어둠이 밤의 동생이기 때문에 어둠을 반겼답니다. 하지만 이제는 낮에도 어둠이 깔려 숲이 생명을 유지하기 위해 절규하고 있습니다. 우리가 즉시 행동하지 않으면 이 어두운 그림자는 곧 세상을 덮어버릴 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5105, 'koKR', NULL, '물약 제조 기술을 배우려고 이곳에 오셨습니까? 노력 없이 그런 특권을 주리라 생각했다면 오산입니다. 가서 기술을 더 익힌 후에 돌아오십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5106, 'koKR', NULL, '그대의 기술을 보면 물약 제조술에 대해 상당한 애정이 있음을 알 수 있습니다. 하지만 그것으로는 조금 부족합니다. 그런 의미로 임무를 하나 드리도록 하겠으니 이를 완수하신다면 저도 만족할 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5108, 'koKR', '스랄 님께서 직접 이곳으로 저를 보내셨습니다. 대족장님께 명령을 받은 것만으로도 영광스럽기 때문에 하나도 힘든 줄 모르겠습니다. 사실 스토나드보다 나은 곳도 없지요. 필요한 약초는 죄다 여기 이 늪지대 진흙탕에서 자라니까 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5110, 'koKR', '흠, 물약 만드는 소질이 좀 있으시군요. 그렇다고 제자로 받아들이겠다는 건 아닙니다. 전 아주 바쁜 몸이니까요. 저를 만족시킨다면 또 얘기가 틀리지만. 당신에게 맡길 일이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5111, 'koKR', '어느 안전에서 감히 가르쳐 달라는 겁니까? 뭘 바라고 온 거예요? 이 답답하고 얼빠진 촌놈 같은 양반. 은엽수 덤불 사용법이라도 배우겠다는 겁니까? 당장 나가요! 아까운 시간을 낭비하게 한 대가로 신나게 두들겨 맞지 않은 것만 해도 다행인 줄 아십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5112, 'koKR', '이것만 조금 조절하면... 아, 됐다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5113, 'koKR', '할 수만 있으면 내가 당신을 훈련시켜 주겠지만 당신에게는 그... 뭐라고 하더라? 그렇지! 머리가 좀 더 잘 굴러 가는 이가 필요할 것 같소. 아이언포지에 있는 트리시 퀵스위치를 찾아가서 브론크가 보냈다고 해 보시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5114, 'koKR', '기술자가 되고 싶은 거요? 아, 그렇다면 두말할 것 없이 아주 잘 찾아온 거요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5115, 'koKR', '내 스피너가 어디 있지? 분명히 여기 어딘가에 뒀는데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5116, 'koKR', '당신이 현재 가지고 있는 재능은 제 능력을 한참 웃도는군요. 아이언포지에 있는 내 노움 친구 트리시 퀵스위치에게 더 자세히 물어 보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5117, 'koKR', '당신이 추구하는 바를 시작할 수 있도록 내 기꺼이 도와드리겠습니다! 내 스피너를 찾은 다음 곧 시작합시다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5118, 'koKR', NULL, '신형 병아리저울 6000의 제조가 곧 끝날 거라고 하더군요. 너무 흥분돼서 참을 수가 없어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5119, 'koKR', NULL, '글쎄요... 인정하고 싶진 않지만 계속해서 훈련을 받으실 거라면 제 언니를 찾아가 보셔야 할 것 같군요. 저는 언니만큼 많이 알지는 못하거든요. 아직까지는 말이에요! 언닌 로켓 자동차 옆에 서 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5120, 'koKR', NULL, '기꺼이 가르쳐 드리죠! 기계공학에 대해서 좀 알고 있는 게 언니 뿐만은 아니라는 걸 보여 주고 말겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5121, 'koKR', NULL, '안녕하세요! 저는 지나라고 해요! 당신은요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5122, 'koKR', NULL, '아, 배우실 거야 아직도 잔뜩 있죠. 제가 할 수만 있으면 모두 다 가르쳐 드리고 싶지만 저도 아직 배우고 있는 입장이라서요. 아이언포지에 있는 트리시 퀵스위치를 한번 찾아가 보세요. 계속해서 훈련을 시켜 줄 수 있을 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5123, 'koKR', NULL, '훈련을 받고 싶으시다고요? 저한테서요? 아주 좋죠! 탄환이랑 폭발 장치를 조립하는 것보다 더 나은 유일한 일은 바로 그 지식을 다른 이와 나누는 거니까요! 어서 시작해요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5124, 'koKR', NULL, '아, 뭐 하나 날려 버리기에는 딱 좋은 날씨네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5125, 'koKR', NULL, '당신은 이제 제 실력 밖에 있는 것들을 배우기 시작해야 해요! 저쪽 천막 앞에 있는 릴리암 스파크스핀들과 얘기해 보세요. 그가 필요한 내용을 가르쳐 줄 수 있을 테니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5126, 'koKR', NULL, '이런 종류의 일은 담이 약한 이는 할 게 못 돼요. 한쪽 손을 잃어 버린 삼촌도 있다니까요! 불쌍한 스텀피 삼촌... 어쨌든 그래도 관심이 있다면 제가 몇 가지 가르쳐 드릴 수 있을지도 모르겠네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5127, 'koKR', '음? 저한테 원하는 게 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5128, 'koKR', '나는 당신을 도와 줄 수 없소! 당신은 나보다 더 오래 이 일을 해 온 이를 찾아갈 때가 된 거요! 보자... 아무래도 당신은 얼라이언스 일원이니 스톰윈드에 있는 릴리암 스파크스핀들과 얘기해 봐야 할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5129, 'koKR', '좋아요, 당신에게 몇 가지 가르쳐 드리죠. 당신 솜씨나 한번 봅시다. 어쩌면 저를 놀라게 할 정도일지도 모르죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5130, 'koKR', '*킁킁* 냄새가 나시오? 기름 냄새가 아주 황홀하지 않소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5131, 'koKR', '미안하지만 나는 자네를 가르칠 실력이 안 되네! 오그리마로 가서 노그를 찾아보시게. 그가 자네를 다음 단계로 이끌어 줄 테니까 말이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5133, 'koKR', '나는 뭔가 만드는 걸 좋아하지. 물론 산산조각나게 폭발시켜 버리는 건 훨씬 더 좋아하고 말이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5134, 'koKR', '기계공학을 정말 제대로 아는 게 누군지 알기나 하는 거요? 오그리마로 가서 노그를 찾아보시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5135, 'koKR', '내가 기계공학을 좀 알지. 내가 가르쳐 드릴까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5136, 'koKR', '도대체 누가 오크는 머리가 나쁘다고 하는 거야? 머리가 나쁘면 기술자는 될 수 없단 말이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5137, 'koKR', '진짜 머리 좋은 기술자가 누군지 아나? 바로 노그지! 나보다도 머리 회전이 빠르다니까. 노그에게 가서 선드가 보냈다고 하게! 바로 저기 기계 장치 제어판 앞에 서있으니까...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5138, 'koKR', '자네 스스로 머리가 꽤 좋다고 생각하나? 뭐든지 잘해낼 수 있을 자신이 있다고? 어디 한번 보세!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5139, 'koKR', '어둠의 여왕님께서 말씀하시길, 이 전쟁에서 우리의 가장 큰 무기는 바로 지식이라고 하셨소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5140, 'koKR', '당신은 이제 더 큰 것들을 배워야 합니다! 내 오른편에 있는 프랭클린 로이드와 얘기해 보십시오. 이제부터는 그가 당신을 지도해 줄 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5141, 'koKR', '기계공학을 알면 적을 산산조각 낼 기술과 지식을 얻을 수 있습니다! 내가 보여주겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5142, 'koKR', '이방인 친구와 얘기할 시간이야 언제든 있고 말고요! 뭐, 적어도 거의 항상 그렇답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5143, 'koKR', '이제부터 당신은 나보다 더 높은 기술을 쌓게 되는 겁니다! 아이언포지에 있는 스프링스핀들 피즐기어를 찾아가서 나보다 더 잘할 수 있다는 걸 보여주십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5144, 'koKR', '그러니까 먼저 간단한 일 하나만 해 준다면 내가 몇 가지 요령을 가르쳐 줄 수 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5145, 'koKR', '흐음... 글쎄, 나는 아직 당신에게 큰 도움을 줄 수 없겠네요! 당신은 우선 기본적인 것부터 배워야겠습니다. 스톰윈드로 가서 스프라이트 점프스프로켓을 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5146, 'koKR', '대단하군요! 당신 정말 열심히 하는군요. 자, 그럼 시작해 봅시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5147, 'koKR', '어디 보자... 14 더하기 7은... 2 올라가고... 아, 네?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5148, 'koKR', '정말 빨리 배우는군요! 제가 달리 가르쳐 드릴 게 없네요. 하지만 스프링스핀들 피즐기어라면 틀림없이 더 많은 걸 가르쳐 줄 겁니다! 그 친구를 만나려면 아이언포지로 가세요. 행운을 빌어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5149, 'koKR', '가는 정이 있으면 오는 정도 있어야지요! 제가 한수 가르쳐드릴 테니 그 전에 먼저 간단한 일 한 가지만 해주시지요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5150, 'koKR', '때가 되면 나한테서도 배울 수 있게 되겠지만 아직은 이릅니다... 이곳 내 오른편에 있는 스프라이트 점프스프로켓과 먼저 얘기를 나눠 보십시오. 기본기를 다지거든 날 다시 찾아오시기 바랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5151, 'koKR', '확실히 솜씨가 괜찮군요! 일을 끝냈으니 이제 수업을 시작합시다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5152, 'koKR', NULL, '6미터 높이의 칠면조 조리 기계 설계도가 거의 다 완성됐어요! 이제 6미터짜리 칠면조만 있으면 되는데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5153, 'koKR', NULL, '우리끼리만 하는 얘긴데, 저도 모든 걸 다 아는 건 아니랍니다! 계속 배우고 싶으시다면 가게 주인인 스프링스핀들 피즐기어와 얘기해 보셔야 할 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5154, 'koKR', NULL, '제 비법을 전수해 주기 전에 먼저 당신이 배울 자격이 있다는 걸 보여 주셔야 해요! 아주 적당한 시험이 하나 있죠...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5155, 'koKR', NULL, '뭐, 거의 가깝긴 하지만 아직은 안 되겠네요. 아무래도 먼저 제 여동생 젬마와 얘기를 나눠 보셔야 할 것 같군요. 젬마한테서 기본기를 배운 다음 절 찾아오시면 아주 끝내주는 것들을 보여 드리죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5156, 'koKR', NULL, '초보자치고는 상당한데요? 당신에게 몇 가지 가르쳐 줘도 문제없을 것 같군요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5157, 'koKR', '하루가 몇 시간만 더 길다면 좋을 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5158, 'koKR', '당신은 이제 나보다 더 훌륭한 스승에게 훈련받을 수 있는 특권을 얻은 겁니다. 저기 내 친구 록시크와 얘기해 보시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5159, 'koKR', '하루하루가 다 시험이고, 오늘 역시 예외는 아니죠. 이 시험을 통과하면 내 지식을 좀 전수하도록 하겠어요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5160, 'koKR', '당신은 아직 나에게 가르침을 받을 수 있는 권리를 얻지 못했어요. 저쪽 탁자 옆에 있는 선드부터 먼저 만나 보시죠. 그가 당신더러 준비가 됐다고 하거든 다시 날 찾아오시고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5161, 'koKR', '시험을 통과했군요. 잘하셨어요! 이제 훈련을 계속하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5162, 'koKR', '한가하게 잡담이나 하고 있을 시간 없습니다. 저는 프로란 말입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5163, 'koKR', '내가 뭘 가르쳐 줄 수 있을 거라 생각하는 건가? 그런 거라면 록시크가 훨씬 더 잘할 걸세. 그 친구는 오그리마에 가면 있을 테니 어서 가 보게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5164, 'koKR', '자네 실력이 어느 정도 되는지 어디 한번 볼까? 이 임무를 내가 만족할 수 있을 정도로 잘 완수한다면 내 시간을 내서 자네를 가르쳐 주도록 하겠네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5165, 'koKR', '이건 당신한테나 나한테나 시간 낭비야! 훈련을 시작하고 싶거든 그레이엄 반 탈렌을 찾아가 보게! 그 친구는 저기 내 왼쪽에 서 있으니까 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5167, 'koKR', '제 계산이 맞는다면 이 바퀴는 곧 구식이 되어 버릴 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5168, 'koKR', '당신은 그동안 많은 훈련을 쌓아 왔군요. 수련을 좀 더 쌓고 싶다면, 사막으로 여행을 떠나야 할 겁니다. 가젯잔으로 가서 부젝 브라켓스윙을 찾아보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5170, 'koKR', '내가 가르쳐 줄 내용은 당신 머리를 어지럽게 만들 겁니다! 충분히 배운 후에 다시 찾아오도록 하세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5171, 'koKR', '아주 좋아요. 내게 배울 만한 자격이 있다는 걸 보여 줬으니 이제 다음 순서로 넘어갑시다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5172, 'koKR', '가끔 저는 저 자신에게도 깜짝 놀랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5173, 'koKR', '내가 모르는 걸 가르쳐 줄 수는 없잖나! 나보다 더 많이 아는 누군가가 있다면 모를까... 잠깐, 그렇지! 가젯잔에 있는 부젝 브라켓스윙을 만나 보게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5175, 'koKR', '노력하는 건 좋지만, 나한테서 배우려면 경험이 좀 더 있어야겠군! 좀 더 경험을 쌓도록 하게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5176, 'koKR', '잘했네! 다른 사람들이 뭐라고 하든 나는 내가 당신을 제대로 본 줄 알았다니까. 하하! 농담일세! 좋아, 수업을 시작하도록 하지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5177, 'koKR', '지하 통로를 통해 대도시들 간에 기름을 운송할 방법을 연구하고 있었는데, 다들 뜬구름 잡는 얘기라고 하는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5179, 'koKR', '이제까지 닦아 온 실력을 보여 보시게! 내 생각엔 틀림없이 잘해 낼 것 같으니까 말이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5180, 'koKR', '나에게 배울 준비가 된 이를 돌려보내는 일은 절대로 없소만, 유감스럽게도 자네는 그런 사람이 아닐세! 아직 배워야 할 게 많이 남아 있단 말일세!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5181, 'koKR', NULL, '안녕하세요, 여행자님! 제 집에는 무슨 일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5182, 'koKR', NULL, '죄송하지만 당신만큼 경험이 많은 분에게는 제가 가르쳐 드릴 게 없군요. 하지만 당신이 배워야 할 건 아직 더 남아 있으니 저기 카운터 뒤에 있는 루칸 코르델과 얘기해 보세요. 당신 여정의 다음 단계를 안내해 줄 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5183, 'koKR', NULL, '흐음... 당신은 꽤 실력이 있는 것 같군요. 정말로 배우고 싶으시다면 넘지 못할 벽이란 없겠죠! 앞으로 길고도 보람으로 가득 차게 될 여행의 첫걸음은 제가 안내해 드리겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5184, 'koKR', '망치와 가열로 외에도 강철을 더 강하게 만드는 길은 있습니다, 방랑자 양반.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5185, 'koKR', '당신은 아주 괜찮은 마법부여사로군요! 이제 실력을 더 발전시킬 때가 됐습니다. 위층으로 가서 김블 시슬퍼즈와 얘기해 보는 게 좋겠군요. 좀 괴짜 같은 친구지만 지금부터 당신을 제대로 가르쳐 줄 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5186, 'koKR', '아, 호기심이 많은 친구로군요. 아주 좋습니다! 상황이 험악해질 때 당신 목숨을 구할 수 있을지도 모르니까 잘 봐 두십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5187, 'koKR', NULL, '이방인이여, 엘룬께서는 제게 지혜를 베푸셨습니다. 엘룬의 뜻이라면 그대에게도 그 지혜를 전해 드리도록 하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5188, 'koKR', NULL, '그대의 솜씨는 내가 닿을 수 없는 곳에 있군요. 이제 새로운 도전을 할 때입니다. 저기 탁자 옆에 서 있는 탈라단을 찾아가면 그대가 준비하는 걸 도와 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5189, 'koKR', NULL, '제가 할 수 있는 대로 모두 가르쳐 드리지요. 각 수업은 엘룬께서 내리시는 선물이랍니다. 엘룬께서 내려주신 선물을 지혜롭게 사용하면 실패하는 일이 없을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5190, 'koKR', NULL, '엘룬께는 많은 비밀이 있지만, 그 비밀은 아무하고나 나눌 수 없는 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5191, 'koKR', NULL, '마법부여 지식이 정말 뛰어나군요. 원한다면 더 많은 것을 배울 수 있답니다. 다르나서스 장인의 정원에 있는 탈라단과 얘기를 나눠 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5192, 'koKR', NULL, '마음의 눈을 뜨세요, 방랑자여. 그러면 시작하도록 하겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5193, 'koKR', '낭비할 시간이 없네, 이방인 양반. 용건을 말하든가 아니면 썩 물러가게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5194, 'koKR', '뭐, 이 정도 해 냈으니... 저기 책장 옆에 있는 라비니아 크로를 만나 보게. 너무 서투르게 굴지만 않으면 좀 더 배울 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5195, 'koKR', '내게 그리 대단해 보이진 않지만 혹시 또 모를 일이지, 어딘가에 마법부여사의 재능이 숨어 있을지도!', '겉보기엔 별거 없어 보이는데... 누가 알겠어? 안에 훌륭한 마법부여사가 숨어 있을지도 모르지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5196, 'koKR', '오늘 같은 날은 드넓은 초원을 맘껏 거닐고 싶은 맘 간절하지만... 할 일이 있으니 어쩔 수 없지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5197, 'koKR', '나는 자네가 이미 알고 있는 것 이상을 가르쳐 줄 수 없네. 하지만 우리 아버지께서 나보다 훨씬 더 많은 것을 알고 계시니 안에 들어가서 우리 아버지와 얘기를 나눠 보게나. 행운을 빌겠네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5198, 'koKR', '인내와 굳은 결의가 있으면 많은 비밀을 알아낼 수 있지. 자, 시작하세나...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5199, 'koKR', '트롬카! 뭘 찾고 있는 것이오, 이방인 친구?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5200, 'koKR', '잘못 찾아왔군. 저쪽에 있는 전문가 고단과 얘기하면 더 배울 수 있을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5201, 'koKR', '전장에서 전사하는 것은 영광스러운 일! 하지만 내가 가르쳐 주는 걸 배워 두면 그리 빨리 죽지 않을지도 모른다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5202, 'koKR', '당신 누구요? 나한테 뭘 원하는 거요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5203, 'koKR', '내가 마법부여사의 지존이라도 되는 듯이 보이나요? 당신만큼 실력이 좋은 이라면 대가를 찾아가서 배워야 한다고요! 아조라의 탑으로 가서 키타 파이어윈드를 만나보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5204, 'koKR', '좋습니다, 그럼 시작해 볼까요? 하핫! 속았죠! 나한테서 배우기가 그리 간단할 줄 알았나요? 다른 이들과 마찬가지로 당신도 실력을 증명해 보여야지요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5205, 'koKR', '지금 농담하는 건가요? 당신이 찾는다는 키 작은 친구는 내가 아니라 토니스 필라스톤인 것 같군요. 아래층에 있을 테니 어서 가 보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5206, 'koKR', '흠, 좋아요. 잘난 척하진 마세요! 당신 실력을 입증해 보였으니 이제 시작합시다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5207, 'koKR', '내게서 배울 만한 실력이 된다면 내 기꺼이 가르쳐 주도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5208, 'koKR', '진정한 프로는 자신의 한계를 아는 법이지요. 당신 실력이 나보다 뛰어나다는 것을 인정하는 데 전혀 부끄러움이 없습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보는 게 좋겠습니다. 키타는 아주 유명한데, 충분히 그럴 만한 이유가 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5209, 'koKR', '당신은 자신감에 차 있는 것 같군요. 물론 당신의 실력을 시험해 보는 걸 꺼리지는 않겠지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5210, 'koKR', '당신은 아직 준비가 덜 됐군요. 저기 계단 옆에 서 있는 베티 퀸과 얘기해 보도록 하고 좀 더 실력을 쌓은 후에 내게 다시 오도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5211, 'koKR', '당신은 자신감을 갖기에 충분한 실력을 지니고 있군요, 여행자 친구. 이제 진정한 교육을 시작해도 되겠습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5212, 'koKR', '나가를 사냥하려면 이용할 수 있는 건 뭐든 이용해야 합니다. 물속 깊이 들어가면 거품 균열이 있는데, 거기서는 공기 방울이 많이 솟아나 물속에서도 숨을 쉴 수 있게 해줍니다. 균열 가까이 헤엄쳐 가서 그 공기 방울을 잘 이용하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5213, 'koKR', '전 자격이 있는 이들에게 가르쳐 줄 기술을 지니고 있는 것은 사실입니다만, 그대에게 그런 자격이 있는지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5214, 'koKR', '그대는 아주 뛰어난 마법부여사로군요. 스승인 나의 재능보다도 뛰어난 것 같습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보십시오. 그대의 스승이 될 만한 이는 이제 그 친구뿐입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5215, 'koKR', '전 그대가 이 임무를 맡을 자격이 있다고 믿습니다... 이 임무를 받아들이겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5216, 'koKR', '그대는 아직 기본기를 익히지 못했군요, 방랑자 친구. 내 조수, 랄리나 서머문과 얘기해 보았습니까? 그녀와 얘기해 봐야 할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5217, 'koKR', '잘했습니다! 진정 나의 가르침을 받을 만한 자격이 있군요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5218, 'koKR', NULL, '진정으로 보람된 길을 걷고 싶다면 마법부여사가 되어 보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5219, 'koKR', NULL, '나도 많은 것을 알고 있지만 그대의 지식 수준은 나와 견줄 만하군요. 기술을 더 연마하고자 하는 마법부여사들은 아조라의 탑으로 간다고들 하죠. 그곳에 키타 파이어윈드라는 대가가 살고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5220, 'koKR', NULL, '그대의 솜씨를 한번 보도록 할까요? 임무를 완수하면 기꺼이 그대를 훈련시켜 드리도록 하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5223, 'koKR', '마법부여는 우리 가문 대대로 내려온 일이오. 내 아들 녀석처럼 나도 어렸을 때부터 배웠소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5224, 'koKR', '나보다 더 많이 알고 있는 이가 있소. 이제 당신은 그를 찾아갈 때가 된 것 같소. 돌발톱 산맥에 있는 해바위 야영지로 가시오. 하가스를 만나 계속 훈련을 받도록 하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5225, 'koKR', '내 곧 가르쳐 주리다... 단 먼저 당신의 성실함을 증명해 보여야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5226, 'koKR', '모트가 아직 준비가 안 된 당신을 내게 보낼 정도로 바보는 아닌데... 당신은 아직 내가 가르칠 내용을 전부 이해할 수 없소. 바로 저 바깥에 있는 내 아들 모트에게 가서 남은 훈련을 마치도록 하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5227, 'koKR', '아, 아주 잘했소. 당신은 내게 배울 자격이 있군. 당신이 나의 제자가 된다는 사실이 아주 흡족하군. 자, 이제 훈련을 시작합시다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5228, 'koKR', NULL, '저한테 손님이 찾아오는 일은 드문데... 구체적으로 뭔가 찾으시는 게 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5229, 'koKR', NULL, '나도 하루종일 이곳에 처박혀 있지만 않다면 당신 같은 이를 가르칠 수 있을 정도로 기술을 익힐 수 있었을 거예요! 하지만 유감스럽게도 그렇지 못하니 돌발톱 산맥의 해바위 야영지로 하가스를 찾아가 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5230, 'koKR', NULL, '흠... 가는 게 있으면 오는 것도 있어야겠죠. 내가 부탁하는 일을 잘해 준다면 당신 훈련에 관해 얘기해 볼 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5231, 'koKR', NULL, '아뇨, 안 되겠어요. 나한테서 배우려면 그 전에 한참 더 훈련을 해야겠군요! 저 무뚝뚝한 초심자 말콤 린한테 가서 얘기해 보세요. 저쪽에 책에 파묻혀 있는 이가 말콤이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5232, 'koKR', NULL, '음, 당신은 향상의 여지가 있긴 하네요. 당신이 잠재력을 지니고 있다는 건 인정하죠. 자, 잘 보고 배우도록 하세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5233, 'koKR', '어서 오게, 여행자 친구! 비전 마법의 수수께끼를 파헤쳐 볼 생각 없나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5238, 'koKR', '어떤 모험가들은 마법부여가 무용지물이라고 생각하지만, 내가 싸움을 걸려고 하면 얼른 말을 바꾼단 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5239, 'koKR', '이방인 친구, 자네의 솜씨는 내가 가르칠 수 있는 정도를 초월했군. 돌발톱 산맥으로 가서 해바위 야영지에서 하가스와 얘기해 보게나. 나보다 더 많은 걸 가르쳐 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5240, 'koKR', '솜씨가 있는지 없는지 어디 한번 보세!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5241, 'koKR', '내게 훈련을 받기에는 아직 실력이 조금 부족하구먼, 이방인 친구. 시간을 좀 내서 저쪽에 있는 내 조수 자그를 만나보도록.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5242, 'koKR', '잘했네! 자네 눈빛이 예사롭지 않군... 그런 눈빛을 잘 알고 있지. 나도 마법부여를 막 시작했을 때 그런 눈빛을 하고 있었으니까! 자, 이제 당신에게 가르쳐줄 만한 게 뭐가 있나 한번 보세나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5243, 'koKR', NULL, '아조라의 탑에는 어쩐 일이세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5244, 'koKR', NULL, '훈련이 거의 절정에 다다랐군요. 더 나은 실력을 갖춘 마법부여사가 되려면 찾아가야 할 스승이 또 있습니다. 그녀의 이름은 안노라라고 하며, 울다만으로 가면 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5246, 'koKR', NULL, '배우고자 하는 마음이 간절하군요. 좋은 모습이지만 당신은 아직 나 같은 숙련자에게 배울 준비가 안 돼 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5247, 'koKR', NULL, '당신 실력은 참으로 현저히 좋아져 가고 있네요. 자, 이제 훈련을 계속해 볼까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5248, 'koKR', '이 하가스의 지식을 구하기 위해 온 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5249, 'koKR', '이 분야에서 나를 능가하는 실력을 갖춘 이가 하나 있지. 자네 그 여자의 지식을 전수받을 준비가 됐군. 안노라라고 하는데, 울다만...에서 만날 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5251, 'koKR', '매일 열심히 훈련을 하게. 솜씨를 완벽하게 다듬은 후에 다시 날 찾아오도록 하고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5252, 'koKR', '자네 마법부여의 대가를 향한 길에서 새로운 경지에 올라섰군. 더 높이 올라갈 수 있을지 어디 한번 보세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5253, 'koKR', NULL, '안녕하세요, 여행자님. 저 끔찍한 생물들을 물리쳐 줘서 뭐라고 감사의 말을 전해야 할지 모르겠네요! 평생 숨어 지내야 할지도 모른다고 생각하고 있었거든요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5255, 'koKR', NULL, '당신에게 필요한 교육이 거의 다 끝나가는군요. 이제 모든 노력의 완성과 당신 사이에는 마지막 임무 하나만이 남아 있을 뿐이랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5256, 'koKR', NULL, '내 지식을 전수받기 전에 먼저 다른 이에게 배워야 할 게 아직 남아 있군요. 부지런히 노력하고 희망을 잃지 마세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5257, 'koKR', NULL, '제 남편이 전쟁터에 나가 있기 때문에 헬렌이 저에게 힘이 돼주었답니다. 그녀의 고운 심성과 뛰어난 검술 실력으로 힘든 시기를 견디도록 도와주었죠. 전 헬렌이 없었으면 어떻게 되었을지 정말 모르겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5258, 'koKR', NULL, '이런, 미안해요. 제가 가르쳐 드릴 게 없네요. 스톰윈드 구 시가지에 있는 사이먼 태너를 만나 보세요. 그는 멋진 근육을 가지고 있고 붉은색 머리를 한 친구랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5259, 'koKR', NULL, '잘 지내세요? 저는 가죽 냄새가 너무 좋답니다. 당신은 어떤가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5260, 'koKR', '유행 스타일에 대해서는 이미 충분히 알고 있습니다. 이젠 가죽 다듬는 법만 통달하면 되죠. 사이먼이 흔쾌히 도와줘서 정말 다행입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5261, 'koKR', '색깔 보는 법처럼 자잘한 사항 외에는 더는 당신에게 가르쳐 줄 게 없습니다. 저기 있는 사이먼 태너에게 가보십시오. 숙련된 가죽세공 기술을 가지고 있는 사람입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5262, 'koKR', '어떠세요? 이 방어구가 제 짙고 서글서글한 눈매를 더욱 돋보이게 하는 것 같지 않습니까? 저를 척 보면 몇 가지 기술 정도는 가르쳐 줄 만큼 솜씨가 뛰어나다고 생각이 안 드십니까? 그러니 제 말을 귀 기울여 잘 들어 보십시오. 아셨죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5263, 'koKR', NULL, '저희 집에 오신 것을 환영합니다. 래드날과 저는 가르쳐 드릴 게 별로 없지만 최선을 다해 돕겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5264, 'koKR', NULL, '죄송하지만 제가 아는 것은 이미 배우셨군요. 하지만 팔드론이라는 나이트 엘프는 그대를 도와줄 수 있을 것입니다. 다르나서스에 있는 장인의 정원에서 그를 찾아보도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5265, 'koKR', NULL, '음... 바느질을 더 꼼꼼히 하셔야 해요. 그러면 화살통과 탄환 주머니에서 물건이 빠지지 않을 겁니다. 게다가 울퉁불퉁한 조끼를 좋아하는 이는 아무도 없을 것이고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5273, 'koKR', NULL, '가죽세공에 관심이 있으시다면 제대로 찾아오셨습니다. 팔드론과 텔로니스는 진정한 예술가들이죠. 저도 그들에게 많은 것을 배우고 싶습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5274, 'koKR', NULL, '오, 죄송하지만 제가 가죽에 대해 아는 것보다 더 많은 것을 알고 계시는군요. 더 많은 것을 배우고 싶으시다면 저기 있는 팔드론을 만나 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5275, 'koKR', NULL, '이렇게 다르나서스의 유능한 이들에게 둘러싸여 있다니 너무 흥분되지 않나요? 가족들이 저를 자랑스러워할 겁니다. 정말 운이 좋으면 파수대에서 입대해 전방에서 싸워 달라는 부탁을 받게 될지도 모른답니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5276, 'koKR', NULL, '이 모피는 아직 손을 더 봐야 할 거 같군요. 가죽 만드는 데 오래 걸리지 않으면 좋으련만... 이렇게 오래 기다리지 않아도 될 방법이 있을 거예요! 건강에도 안 좋잖아요, 그렇죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5277, 'koKR', NULL, '으으, 운도 되게 없으시네요! 제 기술은 당신에게 도움이 될 만큼 뛰어나지 않아요. 음... 저기 베틀 옆에 있는 핌블 파인스핀들에게 가 보세요. 저보다 훨씬 더 오래 가죽세공을 했으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5278, 'koKR', NULL, '오, 좋았어요! 기다리는 동안 할 일이 생겼네요! $n, 당신은 저의 구세주세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5279, 'koKR', NULL, '그 양탄자가 맘에 드시나요? 내 손으로 짐승을 잡아 가죽을 벗겼답니다. 다른 켄타우로스도 다 이렇게 쉽게 잡을 수 있었으면!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5280, 'koKR', NULL, '난 더는 가르칠 게 없군요. 가죽세공에 대해 더 많은 것을 배우려면 카롤렉에게 가보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5281, 'koKR', NULL, '인간과 그 동맹들의 껍질을 벗길 수 없다니 정말 유감이네요. 그 껍질을 다 허비하다니... 하지만 누가 그런 껍질로 만든 보잘것없는 가죽을 입겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5282, 'koKR', NULL, '놀라운 가죽... 내장을 감싸 안아 주죠. 제 피부가 별로 안 좋은 걸 눈치채셨나요? 예전엔 저도 모공 관리를 했었다니까요. 요새는 피부가 거의 남아 있지도 않죠. 어떻게 생각하면 더 자유로워진 것 같아요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5283, 'koKR', NULL, '가죽세공의 감을 잡았군요. 저는 더 가르칠 것이 없으니 언더시티의 도적 지구에서 일하는 아서 무어라는 포세이큰을 만나서 제가 보냈다고 하면 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5284, 'koKR', NULL, '역병이 오기 전에는 가죽의 가라는 글자도 몰랐답니다. 이젠 다른 이들을 충분히 가르칠 수 있을 정도로 알고 있지요. 죽으니 할 일이 없더라고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5285, 'koKR', '고기, 뼈, 그리고 가죽... 훌륭한 사냥꾼이라면 아무것도 버리지 않는다네. 가죽을 깨끗이 벗겨 동지의 방어구를 두껍게 만들어 줄 수 있지. 즉 혼자서도 독야청청 강할 수 있겠지만 힘을 합치면 무적이 되는 법이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5286, 'koKR', '자네는 이미 내 능력을 능가하는군. 대지모신의 축복을 등에 업고 전진하게. 썬더 블러프 중앙에서 북서쪽에 있는 갑옷 상점으로 가서 타른이라는 타우렌을 찾아. 그의 지혜의 인도를 구하게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5287, 'koKR', '우리는 이 세계에서 살다가 제 명을 다하면 떠나야 하지만 대지는 세상사에 관계없이 영원히 남는다네. 그러므로 대지는 우리의 것이 아니야. 우리가 대지에 속하는 것이지. 그러므로 우리는 대지를 보호해야 하는 것이야. 대지 없이는 생존할 수 없으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5288, 'koKR', '우리 밑에 있는 동굴은 신비하고 놀라운 가죽의 원천일세. 하지만 깊이 들어가면 조심해야 하네. 가죽 몇 조각 구하려다 자네의 가죽이 다칠 수 있으니까. 자네는 소중하다는 걸 항상 기억하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5289, 'koKR', '가죽에 대한 자네의 지식이 나보다 깊어졌군. 불모의 땅 타우라조 야영지에 있는 크룰무 풀문이라는 타우렌을 만나보는 것이 좋겠네. 자네처럼 재능이 있는 자에게 전해줄 지식이 많으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5291, 'koKR', '이곳에 케른이 산다고 하더군. 그의 고귀한 성품과 심오한 지식에 걸맞은 선물을 완성하면 그를 찾아 떠날 거야. 내게 지혜로운 말 한마디쯤은 들려주실지도 모르지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5292, 'koKR', '자네 능력은 이미 나를 앞섰네. 이곳에 있는 타른을 만나 보게나. 가죽에 대한 그의 지식은 나를 압도하니까. 자네라면 흔쾌히 제자로 받아줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5293, 'koKR', '작업을 시작하기 전에 손부터 씻고 오게. 싸움에서 묻은 피나 먼지로 가죽을 더럽히면 그 천연의 아름다움이 사라질 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5294, 'koKR', '내가 무덤 속에서 기어 나왔을 때 가족들이 나를 두 팔 벌려 반겨줄 것만 같았소. 환대는커녕 이제는 더 이상 이해할 수 없는 언어로 소리를 고래고래 지르며 나를 마을 밖으로 쫓아내더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5295, 'koKR', '난 자네를 도와줄 수가 없겠군. 자넨 내 능력을 뛰어넘었어. 저기 저 관 앞에 서있는 아서 무어에게 가보게. 나보다 더 많은 걸 가르쳐 줄 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5296, 'koKR', '내가 하는 모든 말을 명심하게. 적의 뿌리를 뽑을 때까지는 절대 배움을 게을리해서는 안 돼. 방어구도 열심히 갈고 닦아놓고. 경비도 소홀히 해서는 절대 안 되지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5314, 'koKR', NULL, '그대는 저의 능력을 능가하시는군요. 다르나서스의 장인의 정원에 있는 에이네실이라는 나이트 엘프를 찾아가 보시면 그녀가 더 많은 것을 가르쳐 줄 것입니다. 저도 그대와 함께 가고 싶을 뿐입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5316, 'koKR', NULL, '제가 가르치는 내용을 이해하기에 그대의 수준이 너무 낮군요. 물약 제조에 대해 배우고 싶다면 이곳에 있는 텔아실을 만나 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5317, 'koKR', NULL, '주의 깊게 들으십시오, $n. 나누어 드릴 지식이 많습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5318, 'koKR', '내게도 한계는 있단 말이야! 계속해서 훈련을 하고 싶다면 언더시티에 있는 라비니아 크로를 찾아가 보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5319, 'koKR', '꽤 괜찮은데... 자네는 훈련을 시킬 만하겠어. 아주 좋아! 그럼 시작해 볼까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5320, 'koKR', '랜달은 멋 부리기를 지나치게 좋아하는 것이 사실이지만 제가 가르치는 어떤 학생들보다 믿음직스럽죠. 모험을 좀 좋아한다고 뭐라고 할 수는 없는 일이니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5321, 'koKR', '미안하지만 당신을 가르치는 것은 제 능력 밖입니다. 더 많은 것을 배우고 싶다면 다르나서스 장인의 정원에 있는 텔로니스를 찾아가 보세요. 듣기로는 아주 실력파라고 하더군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5323, 'koKR', '좀 더 수련을 한 뒤에 찾아오세요. 저쪽에 있는 랜달 워스에게 가면 당신을 도와드릴 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5324, 'koKR', '흠, 제자로 받아들여도 될 만큼 실력이 있는 분이로군요. 거기 그렇게 가만히 서있지만 마시고 배우고 싶은 게 뭔지 말해보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5325, 'koKR', '다리안나에게 소질이 보이는 것 같기는 한데 활기가 넘쳐서 가만히 듣고 있지를 못합니다. 다리안나가 가진 힘과 민첩성이라면 곧 전투에 불려 나가게 될 텐데. 좀 더 빨리 가르쳐야겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5326, 'koKR', '더 많은 배움을 구하러 오셨다면 제 능력을 과대평가하셨습니다. 저쪽에 있는 텔로니스를 만나 보십시오. 그대에게 도움이 될 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5328, 'koKR', '시간이 지나면 그대도 제 가르침을 받을 준비가 될 것입니다. 그때까지는 저기 있는 다리안나에게 가서 훈련을 받으십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5329, 'koKR', '재료를 구한다는 명분으로 수많은 동물이 희생되었습니다. 그들의 희생을 가볍게 생각해서는 안 됩니다. 숭고한 죽음에 대한 존경심을 가지고 가죽을 다루어 주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5330, 'koKR', '휴, 할 일이 너무 많네요! 제 사촌의 실수로 놈리건의 모든 옷감과 가죽이 증발한 뒤로 이렇게 바쁜 적 처음이랍니다. $n, 그러고 보니 요새 꽤 추웠죠?! 아, 옛날이여...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5331, 'koKR', '아뇨, 도와 드릴 수가 없네요. 이미 저를 능가하셨거든요! 더 배우고 싶으시다면 다르나서스 장인의 정원에 있는 텔로니스라는 나이트 엘프에게 가 보세요. 정말 훌륭한 분이죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5333, 'koKR', '아! 새로운 학생이로군요! 기술을 조금만 더 익혀오시면 제가 아는 것을 기꺼이 가르쳐 드리죠. 저쪽에 있는 그레타 파인스핀들에게 가 보세요. 당신이라면 아마 금방 배우실 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5334, 'koKR', '잘 따라 배우시는군요. 얼마 안 가 가죽 상점을 직접 차려도 되겠어요. 기꺼이 도와 드려야죠. 너무 바빠서 문제지만... 할 일이 너무 많아요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5335, 'koKR', '이 황무지에서 쉬고 있는 코도에게서는 아주 튼튼한 가죽을 얻을 수 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5336, 'koKR', '더 이상 가르칠 게 없네. 자네의 기술이 이미 나를 능가했기 때문이야. 썬더 블러프 중앙에서 북서쪽에 있는 상점으로 우나라는 타우렌을 찾아가게. 고급 기술을 가르쳐줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5338, 'koKR', '난 수습생은 가르치지 않아. 이곳 불모의 땅에 있는 통곡의 동굴에서 왈도르라는 타우렌을 찾아가게. 자네를 도와줄 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5339, 'koKR', '훈련을 받으러 왔나? 자네의 옷에 묻어 있는 그 먼지부터 털어내고 시작하도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5340, 'koKR', '수많은 전투에서 나와 함께한 이 도끼를 항상 옆에 두고 싶소. 적군이 우리 수도로 쳐들어온 게 한두 번은 아니지만 두려워할 필요는 없지. 그들을 막지 못한 적은 한 번도 없었으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5341, 'koKR', '더는 가르쳐 줄 게 없소. 당신의 가죽세공술은 이미 나와 대등하니까. 저쪽에 있는 우나에게 가도록 하시오. 필요하다면 당신의 실력은 내가 보증하도록 하겠소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5343, 'koKR', '내가 가르치는 것을 배우기에 당신의 기술은 아직 설익었소. 대신 저쪽에 있는 마크를 찾아가보시오. 고급 기술을 배울 수 있을 때까지 당신을 도와줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5344, 'koKR', '이렇게 발전한 당신의 모습을 보니 기쁘기 그지없소. 대지모신께서 당신의 손에 영감을 불어넣어 주신 것이 틀림없군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5345, 'koKR', '현재 우리가 이 땅에 설 자리는 별로 없지만 언제나 인간들이 이기란 법은 없지 않소. 그때가 되면 우리를 노예로 만든 대가를 치르게 될 거요. 그들의 기만에 대한 대가로 거짓말만을 내뱉는 그 혀를 잘라버리고 말겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5346, 'koKR', '내가 할 수만 있다면 가르쳐 주겠지만 너무 벅차군. 그러지 말고 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 보시오. 정말 유능한 타우렌이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5348, 'koKR', '제대로 된 교육도 받지 않고 나에게 왔단 말이오? 머리보단 행동이 앞서는군. 당신 수준에 맞는 자나 찾아가 보십시오. 오그리마 골목길에 있는 카마리 같은 오크 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5350, 'koKR', '바쁘냐고? 무슨 질문이 그래? 내가 하루종일 발가락이나 꼼지락거리면서 빈둥거리는 줄 알아? 뭘 사러 온 거라면 한도르에게나 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5351, 'koKR', '내게 배울 건 별로 없을 걸? 이미 많은 걸 알고 있잖아. 더 많이 배우고 싶다면 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 봐. 가는 김에 내 안부도 좀 전해주고. 알았지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5353, 'koKR', '기초도 모르면서 내 기술을 배울 수는 없네. 카마리를 찾아가 더 배우고 오게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5354, 'koKR', '오그리마의 길이 구불구불 굴곡이 많은 것은 침입자의 이동을 방해하기 위함이지. 조그만 노움들이 그 짧은 다리로 여기서 길을 잃고 헤매는 걸 상상해 봤나? 하하! 운만 좋으면 하나 잡아서 애완동물로 키우면 딱 좋겠는데 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5355, 'koKR', '내가 죽기 전에는 사서를 했었지. 전쟁이나 역병과는 아무 상관이 없는 일이었다고. 이렇게 되고 싶은 적은 단 한 번도 없었네... 이제 정신을 되찾았으니 한번 제대로 싸워보지도 않고 항복하는 일은 절대로 없을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5356, 'koKR', '자네가 이제 나를 능가하다니 정말 기쁘군. 이제 길을 떠나야 해. 음, 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가보게. 내가 보장하건대 그녀는 아주 실력 있는 스승일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5358, 'koKR', '초보자까지 전부 받아들이면 너무 시끌벅적해질 거야. 저쪽에 있는 단 골다스에게 가보게. 좀 감정적이기는 하지만 다 좋은 뜻으로 그러는 걸세. 게다가 아주 잘 가르친다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5359, 'koKR', '처음 상점을 연 게 마법 지구였는데 그쪽은 좀 시끄럽더군. 그래서 자리를 옮겼는데도 끈질기게 나를 쫓아다니며 제자로 받아달라는 이들의 발걸음은 끊이질 않았어. 어쩔 수 없이 그들을 막아야 했지. 이제는 아주 조용해진 편이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5360, 'koKR', NULL, '엘룬께서는 나이트 엘프들에게 많은 재능을 부여하셨습니다. 그에 대한 보답으로 호드의 마력으로부터 숲이 오염되는 것을 막는 것이 저희의 의무입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5361, 'koKR', NULL, '그대를 더 가르치는 것은 제 능력 밖입니다. 다르나서스 장인의 정원에 있는 텔로니스를 만나 보십시오. 그는 재능 있는 학생이라면 항상 가르치고 싶어한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5363, 'koKR', NULL, '전 기초 기술을 습득한 이들만 가르치고 있습니다. 다르나서스 장인의 정원에 있는 다리안나라는 나이트 엘프를 만나 보십시오. 당신의 기술을 보완하는 데 그녀가 적격일 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5364, 'koKR', NULL, '가죽을 자르기 전에 항상 치수를 두 번씩 확인하도록 하십시오. 재료를 낭비할 수는 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5373, 'koKR', '서부 몰락지대의 물속을 찾아봐야 하오. 여기서 정서쪽, 황금해안 채석장과 해안이 만나는 곳에서 북서쪽에 있소. 닻을 찾으시오. 그곳이 바로 배가 바다 깊숙이 가라앉은 곳이니까. 수압이 워낙 세서 아무리 수영을 잘하는 자라도 너무 멀리까지 수영하면 지쳐서 빠져 죽기 십상이오.$B$B$n, 주변을 잘 살피시오. 분명 도움이 될 만한 게 있을 테니까. 그 근처에는 거품 균열이 있는데 가까이 가면 깊은 물속에서도 숨을 쉴 수 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5374, 'koKR', '은빛소나무 숲에서 북부 해안가의 가장자리를 따라가다 보면, 바닷가에 난파된 배 한 척이 있을 거요. 거기서 서쪽으로 가면 당신이 찾는 것이 있소. 하지만 거기 가려면 깊은 바닷속을 오래 헤엄을 쳐야 하기 때문에 피로에 지치게 될 거요. 펜던트는 바로 거기, 바닥의 금고 안에서 당신이 가져가길 얌전히 기다리고 있을 거요.$B$B그렇게 깊은 곳을 혼자 힘으로 헤엄쳐 들어간다는 것은 쉬운 일이 아니니 각오를 단단히 해야 할 거요. 다행히도 펜던트 반쪽을 찾아', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5375, 'koKR', NULL, '어둠해안 북부로 가면 악령숲이라고 하는 땅에서 흘러내려 오는 폭포수 강이 있어요. 폭포수 강이 안개 해안으로 들어가는 곳에서 북쪽으로 가면 수심이 아주 깊어지죠. 거기에는 모양이 발톱 같다 하여 돌발톱이라는 이름이 붙은 바위 지형이 있는데 당신이 찾는 게 거기 있답니다.$B$B조심하세요. 돌발톱 바위 근처에 모여 있는 트레샤돈은 자기 영토에 들어오는 자는 모조리 공격하거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5376, 'koKR', NULL, '불모의 땅 북동부로 가면 오염으로 병든 물웅덩이가 하나 있어요. 그곳에서는 그 웅덩이를 진흙 늪이라고 부르죠. 한때는 수정처럼 맑고 푸르렀던 물을 투자개발회사에서 산업 폐기물과 쓰레기 수렁으로 만들어버린 거예요. 그 진흙 늪 한가운데 당신이 찾는 물건이 있답니다, $n.$B$B조심하세요. 투자개발회사에서는 불법 침입자를 그냥 놔두지 않거든요. 자기네 회사에서 일하지 않는 자는 모두 불법 침입자로 취급해요. 녀석들은 자연에 대한 반감이 아주 강하기 때문에', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5393, 'koKR', '풀밭은 부드럽고 폭신합니다. 공기는 상쾌하고 밝은 빛과 노랫소리로 가득 차 있습니다. 제가 보는 모든 것들이 텔드랏실은 꿈의 장소라는 것을 말해줍니다. 그런데 왜 제 마음은 이리도 불길한 예감으로 가득할까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5394, 'koKR', '그대를 가르치기에 제 능력이 모자랍니다. 이제 동부 내륙지에 있는 맹금의 봉우리로 가서 드라크 스톤핸드라는 드워프를 만나 보십시오. 그의 작품은 제 것과는 비교조차 안 될 정도로 훌륭합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5396, 'koKR', '송구스럽지만 가죽세공 기술을 좀 더 배우실 때까지는 그대를 도와드릴 수가 없습니다. 저 대신 이곳에 있는 팔드론이나 다리안나를 만나 보십시오. 필요한 수련을 받으실 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5397, 'koKR', '가죽에 그대의 의지를 강요하려고 하지 마십시오. 대신 가죽의 자연적 성향을 판단해 어떤 형태로 만들어 어떤 기능을 하도록 할지 생각해 보십시오. 가죽을 세공하는 일은 전쟁이 아닙니다. 가죽을 이기려 들지 말고 가죽과 함께하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5398, 'koKR', NULL, '바늘은 작지만 실은 강하며 이 실로 맺은 바늘 땀은 촘촘한 것입니다. 스랄 님과 다른 이들과 맺은 조약은 유효하니 호드를 이 땅에서 몰아낼 수는 없을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5399, 'koKR', NULL, '내 재능도 한계가 있다는 것을 당신이 일깨워 주는군요. 축하합니다. 이제 페랄라스에 있는 모자케 야영지로 가십시오. 그곳에는 기술이 아주 뛰어난 하라나 아이언하이드라는 타우렌이 살고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5401, 'koKR', NULL, '내가 초보자였던 것이 까마득한 옛날이기에 당신을 제대로 가르칠 수 없을 것 같습니다. 바로 저기에 있는 타른이나 마크에게 가면 둘 중 하나는 당신에게 도움을 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5402, 'koKR', NULL, '케른께서는 우리를 무한한 가능성의 땅으로 데려오셨습니다. 우리는 대단한 자산을 받았기에 그에 대한 보답으로 우리의 자산을 다른 이에게도 나누어 주어야 합니다. 그것이 바로 내가 학생들을 가르치기 시작한 이유입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5403, 'koKR', '이곳에서 찾을 수 있는 재료로 놀라운 것들을 만들어낼 수 있지. 무라딘 님의 수염을 걸고 말하는데 이 언덕에는 환상적인 생물이 많아. 한 번 가서 잡아 보라고. 돌아와서는 멋진 얘기도 좀 해주고 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5405, 'koKR', '난 도전이 좋아. 자넨 안 그런가? 그래, 당연히 그래야지. 그러면 내가 시키는 일도 당연히 해주겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5406, 'koKR', '난 요람에서 방금 기어 나온 친구를 가르칠 순 없어. 내 제자가 되려면 많은 기술을 익혀야 한다고. 사실 자넨 몰골도 말이 아니니 거기 서서 입 좀 다물어 준다면 고맙겠군그래.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5407, 'koKR', NULL, '내 작품을 사려면 직접 나를 찾아와야 합니다. 올윈은 종종 다시 생각해 보라고 하지만 아쉬운 건 내가 아닙니다. 주위를 둘러보십시오. 많은 전사들이 내 갑옷에 의지하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5408, 'koKR', NULL, '당신 같은 제자만 있다면 좋겠군요. 용기 있게 적진 깊은 곳으로 들어갈 자는 많지 않답니다. 당신의 용기에 경의를 표합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5409, 'koKR', NULL, '이 전쟁에서는 한 조각의 가죽도 허비하지 말아야 합니다. 난 밤낮으로 새 갑옷을 만들어 내지만 헌 갑옷도 최대한 수선해서 다시 입을 수 있게 합니다. 난 다른 임무를 할 시간이 없습니다. 그래서 말인데 내 부탁 하나 들어주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5410, 'koKR', NULL, '나를 찾아오느라 당신 시간뿐 아니라 내 시간까지 허비했군요. 난 기본 기술까지 가르칠 시간이 없습니다. 이곳에서는 전투가 벌어지고 있으며 여기는 최전선이란 말입니다. 좀 더 준비가 될 때까지 돌아오지 마십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5413, 'koKR', '당신의 행색을 보아하니 하루빨리 옷 좀 구하셔야겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5414, 'koKR', '저는 그저 재봉술을 조금 아는 평범한 사람에 불과합니다. 당신은 제가 지닌 기술보다 더 많은 것을 배워야 합니다. 스톰윈드 마법사 지구에서 상당히 솜씨 좋은 나이트 엘프 재봉사가 산다고 들었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5415, 'koKR', '제게서 몇 가지 배우고 싶다는 말입니까? 기꺼이 가르쳐드리겠습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5416, 'koKR', '인생이란 정성 들여 짠 양탄자와 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5417, 'koKR', '흠... 당신이 이제부터 배워야 할 것은 제 한계를 넘는 것들입니다. 이제 여기서 나가 골목을 오른쪽으로 틀면 있는 라슨의 옷가게로 가십시오. 거기서 일하는 셀란두스와 의논하셔야 합니다. 사실은 제 모든 기술도 그 나이트 엘프에게 전수 받은 것이랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5418, 'koKR', '좋습니다. 이제 재봉술의 여정을 시작해 봅시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5419, 'koKR', '바느질에는 안정된 손길도 필요하지만, 무엇보다 인내심이 필요합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5420, 'koKR', '이제 그대는 다르나서스로 가서 메린과 얘기해야 합니다. 이제부터는 그녀가 그대를 가르쳐줄 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5421, 'koKR', '기꺼이 그대를 제자로 받아들이겠습니다. 자, 시작해볼까요?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5422, 'koKR', '어서 오십시오. 무얼 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5423, 'koKR', '잠시만요... 전 수습 재봉사에 불과합니다. 멋진 걸 만들고 싶다면 저기 스톤브라우와 얘기를 나눠 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5424, 'koKR', '잘 됐군요! 그렇지 않아도 새로운 제자를 기다리고 있었는데. 자, 그럼 당장 시작하도록 합시다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5425, 'koKR', '우리는 여러 가지 동물에서 벗겨낸 가죽과 껍질로 제품을 만들고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5426, 'koKR', '내가 아는 게 좀 있긴 하지만 전문가는 아니오. 다행히도 마가르는 전문가지. 상점 뒤편에 있으니 가서 도와줄 수 있는지 한번 물어보시오. 성질이 불같으니 화나지 않게 조심해야 할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5427, 'koKR', '내가 아는 데까지 최선을 다해 가르쳐주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5428, 'koKR', '우리가 사냥하는 동물의 어떤 부분도 낭비해서는 안 되오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5429, 'koKR', '더 높은 지식을 구하고 있군. 테파가 그런 지식을 가지고 있소. 이 근처 어딘가에 서있을 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5430, 'koKR', '대지모신의 축복을 빌며 이제 수업을 시작하도록 합시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5431, 'koKR', '만나서 반갑소. 내가 도와드릴 일이라도 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5432, 'koKR', '나도 재봉에 대해서 꽤 알긴 하지만 전문가는 아닐세. 자네가 얘기해야 할 사람은 바로 리안논이지! 멀리 있지 않으니 언더시티에서 그녀가 어디 있는지 물어보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5433, 'koKR', '그러니까... 재봉사가 되고 싶다는 것이오? 좋소. 당신이 그럴 만한 실력이 있는지 알아봅시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5434, 'koKR', '이곳에 방문객이 오는 일은 드문데. 뭐 관심 가는 거라도 있는 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5435, 'koKR', '실은 나도 수습생일 뿐이오. 리안논이 진짜 전문가인데, 저기 상자들 옆에 서 있소. 당신은 리안논에게 많은 것을 배울 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5436, 'koKR', '그래. 소질은 있는 것 같군. 내가 몇 가지 가르쳐줘도 되겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5437, 'koKR', NULL, '정신을 가다듬는 데는 실을 짜는 게 최고지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5438, 'koKR', NULL, '저는 아직 계속 배우는 중인데 그대가 저보다 한 수 위군요. 더 배우고 싶거든 메린과 얘기해 보시면 그대를 가르쳐줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5439, 'koKR', NULL, '재봉술이란 아주 즐거운 기술이니까 결코 실망하지 않을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5440, 'koKR', '어서 오세요. 뭘 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5441, 'koKR', '이제 당신은 내게 배울 수 있는 걸 다 배웠습니다. 당신은 오그리마에 있는 마가르를 찾아가야 할지도 모르겠군요. 성질이 불같은 게 탈이긴 하지만 당신을 도와주기는 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5442, 'koKR', '바로 그런 자세입니다! 바늘하고 실을 가지고 오십시오. 당장 시작합시다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5443, 'koKR', '내가 더는 친절하거나 겸손하지 못할까 걱정이군. 세월과 끝없는 전쟁으로 내 몸뚱이와 영혼이 모두 굳어버린 듯하군. 어쩌면 그 때문에 케른 님께서 날 해바위 야영지로 보낸 것인지도 모르지... 부드러운 바람과 따뜻한 햇살이 고통을 덜어주는구려.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5453, 'koKR', '안녕하시오. 우리 박쥐들은 훈련도 잘된 상태고 먹을 것도 많이 먹었소. 이 박쥐들보다 빠른 녀석들은 찾아볼 수 없을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5454, 'koKR', '무엇을 도와주면 되겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5455, 'koKR', '안녕하십니까? 잘 오셨습니다. 전 웃는 데 서투르지만 당신을 손님으로 맞이하게 되어 기쁩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5473, 'koKR', NULL, '히포그리프는 긍지를 알고 고결하며 재빠른 짐승으로서 명예를 위해 훈련을 받아왔습니다. 그대를 아주 먼 곳까지 빠르게 데려다 줄 수 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5474, 'koKR', '육지와 연결하기 위해 저희는 루테란 마을과 어둠해안 사이를 왕복하는 히포그리프를 두고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5475, 'koKR', NULL, '텔드랏실의 해안에서 잡히는 물고기는 매우 크고 기운차답니다. 소문에 따르면 우리 세계수가 빨리 자라는 것이 그 원인이라고 하는군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5476, 'koKR', '어둠해안이 텔드랏실의 해안보다 위험하기는 하지만 많은 낚시꾼들이 이곳에서 수익을 올리고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5477, 'koKR', '모험가분들께 제 물건을 제공하게 되어 영광입니다. 모험가분들은 영웅이 될 자질이 풍부한 이들이니까 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5479, 'koKR', '맹금의 봉우리에서 가장 빠른 그리핀일세. 타겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5480, 'koKR', '북쪽 부두에서는 루테란 마을과 다르나서스로 가는 배를 탈 수 있고 남쪽 부두에서는 대해를 건너 스톰윈드 항구로 갈 수 있네. 방파제의 맨 끝에 있는 서쪽 부두에서 엑소다르 근처인 하늘안개 섬으로 갈 수 있다네. 그럼, 편안하고 즐거운 여행이 되기를 빌지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5481, 'koKR', '여기 이 부두 말인가요? 이곳을 운항하는 배는 그 나이트 엘프들이 있는 곳으로 출항하죠. 이름이 뭐더라? 아마도... 아우... 아우버다인일 거예요. 정확하게는 모르겠어요. 전 단지 짐만 싣고 내릴 뿐이거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5494, 'koKR', '이 화약통들을 발굴현장으로 배달하는 것은 힘든 일이네. 하지만 그곳에는 화약을 얻으려고 우리에게 의지하는 이가 너무 많다네.$B$B검은무쇠 부족에 대항하기 위해 우리가 할 수 있는 일은 다해야 하네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5495, 'koKR', '내 와이번은 뜨거운 불모의 땅의 공기를 헤치고 빠르게 나아갈 수 있도록 훈련되어 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5496, 'koKR', '불모의 땅에는 작열하는 태양과 적대적인 생물들이 있어 자네의 강인함과 불굴의 의지를 시험하기에 최적의 장소라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5497, 'koKR', '안녕하시오. 가죽 용품을 사려고 왔다면 내 물건이 질이 좋다는 것을 한 눈에 알아볼 수 있을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5498, 'koKR', '자네 내 배달을 도와주러 왔나? 미란도 이제 곧 준비가 될 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5500, 'koKR', '와이번 등에 타면 왜 와이번이 강인함과 빠른 속도로 유명한지 알게 될 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5501, 'koKR', '화약을 운반하는 일은 정말 위험한 일이야!$B$B미란은 방금 물건을 전달하러 갔으니 몇 분 후에 돌아올 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5513, 'koKR', '자네 나보다 훨씬 낫군! 자넨 나보다도 경험이 풍부한 이가 필요하겠는데... 그런 이라면 아마 언더시티 연금술 실험실에서 일하는 언데드 학자 허버트 핼시 정도가 되겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5515, 'koKR', '내 고기 좀 둘러보게, 친구. 예비 식량을 넉넉하게 챙기지 않고서 불모의 땅에 나가고 싶지는 않을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5516, 'koKR', '와이번 등에 올라타 세상을 내려다보지 않고서는 세상을 살았다고 할 수 없지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5517, 'koKR', '이 부두에서 테라모어로 가실 수 있습니다. 제 말 잘 들으세요. 그곳은 얼라이언스들이 여행하기에 안전한 곳이 절대 아니니 항상 조심하시고 뒤를 살피세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5519, 'koKR', '안녕하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5520, 'koKR', '그대의 기술은 이제 내 기술을 앞질렀습니다. 길모퉁이 근처에 던컨의 옷가게의 주인인 조르지오 볼레로가 그대의 기술을 향상할 수 있도록 도와줄 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5522, 'koKR', '왼쪽 모퉁이를 돌아 쭉 내려가면 던컨의 옷가게가 보일 겁니다. 거기서 일하는 로렌스 슈나이더와 얘기해 보십시오. 초보 재봉사들을 아주 잘 가르치는 분입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5523, 'koKR', '그대의 실력은 잘 보았으니 그럼 이제부터 내 기술을 가르쳐주도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5524, 'koKR', '아, 이 다르나서스 옷감이 최고라니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5525, 'koKR', '음... 머리가 아주 좋은 친구로군. 당신이 나보다도 많이 알고 있는 건 인정하지! 자만하라고 하는 말은 아니지만 계속해서 배우고 싶다면 스톰윈드에 있는 조르지오 볼레로와 얘기해 보시오. 재봉술만큼은 아주 제대로 알고 있는 친구니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5527, 'koKR', '난 초보자나 봐주고 있을 시간은 없소이다! 내 조수인 우슬라하고나 얘기해 보시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5528, 'koKR', '흠... 소질은 있는 것 같군. 그건 인정하지. 좋소. 그럼 어디까지 얘기했더라?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'koKR', NULL, '주위를 둘러보십시오. 그리고 오늘 그대가 본 것을 생각해 보십시오.$b$b이 숲에 처음으로 온 이후로 많은 것이 변했습니다. 깜짝 놀랄만한, 그리고 전혀 예상치 못했던 변화지요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5530, 'koKR', '이 가게에 있는 많은 것들을 내가 만들었지. 어떤가? 신중히 대답하지 않으면 목숨을 잃을 수도 있어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5531, 'koKR', '자네는 나보다 더 많이 아는 자에게 배워야 하네. 언더시티로 가서 조셉 그레고리안과 얘기해 보게나. 아니, 어서 가지 않고 뭐 하는 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5533, 'koKR', '뭐지? 왜 날 귀찮게 하는 건가? 자네는 고품질의 로브도 만들지 못할 것 같은데 말이야! 가서 스낭하고나 얘기해 보게. 내 가르침을 받을 자격이 되면 그때 다시 찾아오라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5534, 'koKR', '이제야 뭔가 좀 하는 것 같군! 지금부터는 내가 제대로 하는 게 어떤 건지 보여주지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5535, 'koKR', '제때 한 땀 뜬 것이 몇 땀의 수고를 던다더라? 열한 땀이던가? 아, 모르겠군. 어차피 말도 안 되는 속담이니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5536, 'koKR', '초보자치고는 말이야... 나쁘지 않군! 게다가 나랑 실력도 비슷하고. 더 배우고 싶거든 언더시티에 있는 조셉 그레고리안을 찾아가야 할 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5539, 'koKR', '흠... 괜찮군. 내가 몇 가지 가르쳐줘도 되겠어...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5540, 'koKR', NULL, '날씨가 아주 좋군요! 새로운 옷을 만들어 내기에 좋은 날씨에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5541, 'koKR', NULL, '그대는 재능이 아주 뛰어나군요! 정말로 영감이 좋은 분이에요. 계속해서 더 배울 생각이라면 스톰윈드에 있는 조르지오 볼레로를 찾아가 보세요. 아주 유명하신 분이라 그대를 잘 가르쳐주실 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5543, 'koKR', NULL, '어느 기술이나 꼭 배워야 하는 기본기가 있게 마련이죠. 트리안나가 근처에 있을 테니 가서 얘기를 나눠보고 나중에 다시 찾아오도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5544, 'koKR', NULL, '아주 잘하셨어요, 여행자님. 이제 그대를 제자라고 자신 있게 불러도 되겠네요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5545, 'koKR', NULL, '저희 야영지에 잘 오셨습니다. 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5546, 'koKR', NULL, '아주 많은 것을 알고 계시군요, 여행자님. 당신은 나보다 더 현명한 사람에게 배워야 해요. 조셉 그레고리안이라는 자의 지혜에 대해서 많이들 얘기하니 언더시티로 한번 가보도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5549, 'koKR', NULL, '아주 훌륭해요! 그럼 수업을 계속하도록 하죠...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5551, 'koKR', NULL, '무늬가 정말 아름답지 않나요? 각각의 무늬가 저마다의 목소리로 말을 하고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5552, 'koKR', NULL, '저도 계속 배우고는 있지만 제 지식에는 아직까지 한계가 있어요. 이제 당신은 다른 사람을 찾아가야 합니다. 언더시티에 있는 조셉 그레고리안을 찾아가 배울 준비가 됐다고 말하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5554, 'koKR', NULL, '제 도움을 받기 전에 먼저 기본적인 것들을 배워야 합니다. 제 수습생인 반과 얘기해 보세요. 친절하고 인내심이 강한 친구라 당신이 배워야 할 것들을 잘 가르쳐줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5555, 'koKR', NULL, '당신은 아주 의지가 강한 학생이로군요. 기꺼이 재봉술을 가르쳐주도록 하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5556, 'koKR', NULL, '재봉술은 아주 유용하답니다. 한번은 제 팔을 꿰맨 적도 있었거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5557, 'koKR', NULL, '당신은 열심히 배웠으니... 이제는 나보다 더 뛰어난 재봉술을 보유한 자를 만나야 해요. 조셉에게 가서 준비가 됐다고 말하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5559, 'koKR', NULL, '초보자에게는 제 비밀 노하우를 나눠드릴 수 없으니 먼저 빅터 워드와 얘기해 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5560, 'koKR', NULL, '좋아요, 소질이 있군요! 맘에 드는데요. 자, 그럼 시작하도록 하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5561, 'koKR', '그렇습니다. 이 상점을 운영한 지는 꽤 됐지요. 요즘 들어서는 장사도 아주 잘 되는 편이랍니다. 새로운 모험가들이 많이 지나다니고 있거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5562, 'koKR', '나보다 재봉술 솜씨가 좋은 자가 아제로스에 있다면 딱 하나뿐입니다. 마지막으로 들은 소문에 의하면 테라모어 섬에 있다고 하던데, 바로 그분을 찾아가야 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5564, 'koKR', '안 됐지만 내게 가르침을 받기에는 아직 좀 모자라는 것 같군요. 더 배워야겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5565, 'koKR', '좋아! 당신을 가르치는 게 최소한 헛수고는 되지 않겠군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5566, 'koKR', '옷감도 괜찮지만 개인적으로는 인간의 피부를 더 좋아하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5567, 'koKR', '진정한 장인의 지도를 받아야겠군! 타렌 제분소에 있는 다릴 스택을 찾아가 자네의 운명을 맡기는 게 좋겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5569, 'koKR', '때가 되면 가르쳐주겠어. 하지만 지금은 때가 안 됐어. 먼저 기초부터 다지고 와야겠군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5570, 'koKR', '좋아! 당신을 가르치는 게 최소한 헛수고는 되지 않겠군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5571, 'koKR', '전 왕에게도 옷을 만들어 바쳤지요. 훈련만 제대로 받는다면 당신도 그렇게 할 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5573, 'koKR', '아주 먼 길을 오셨군요. 당신이 해줄 일이 하나 있습니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5574, 'koKR', '기본기를 좀 더 다지고 오셔야겠습니다. 그렇지 않으면 저도 도와드릴 수가 없겠군요. 준비가 되거든 그때 다시 찾아오십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5575, 'koKR', '이곳에는 찬바람이 좀 들긴 하지만... 뭐, 상관없지. 어차피 난 죽은 몸이니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5577, 'koKR', '재봉술을 아주 착실하게 배우고 있군. 그건 인정하겠소. 자, 그러면 진짜 솜씨가 어느 정도인지 알아볼까...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5578, 'koKR', '누가 당신을 여기로 보냈소? 아직 가르침을 받을 준비가 덜 됐어! 때가 되면 누군가 말해줄 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5579, 'koKR', NULL, '전 대해에서 들려오는 소리를 들으며 여기 앉아 있는 것을 좋아한답니다. 오, 뭐라고 하셨죠? 네, 메네실 항구로 가는 배가 있죠. 이곳에 가끔 정박한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5580, 'koKR', '내가 장담하지! 자네는 여기 텔사마에 있는 그리핀보다 더 빠른 녀석을 동부 왕국 어디에서도 찾아볼 수 없을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5581, 'koKR', '누가 물어보더라도 이 세상에 광부보다 좋은 직업은 없다고 대답하겠습니다. 우리 드워프를 능가하는 광부는 더더욱 없고 말이죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5582, 'koKR', '맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5583, 'koKR', '최고의 광부라면 곡괭이를 단단히 잡는 손과 가슴에 있는 용기, 머리에 두껍게 앉은 먼지부터가 다르지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5584, 'koKR', '튼튼한 상자가 잔해와 붉은십자군의 열성적인 추종자들에게 둘러싸인 채로 벌목지 중앙에 놓여 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5593, 'koKR', NULL, '그 곰은 갈퀴자국 토굴길 근처의 길을 서성거린답니다. 갈퀴자국 토굴길은 미스트랄 호수와 실바람 산장에 있는 얼라이언스 전초기지 서쪽에 있지요. 그 곰은 잿빛 골짜기 사냥 대회의 동물 세 마리 중에서 가장 쉬운 녀석입니다. 그러니 당신은 녀석과 꼭 한 번은 만나겠지요. 쉽게 볼 놈은 아니란 걸 기억하시고 조심하시기 바랍니다. 사실 그 녀석은 잿빛 골짜기와 돌발톱 산맥 사이를 오가는 여행자들에게 위협이 되는 존재이거든요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5594, 'koKR', NULL, '잿빛 골짜기 사냥 대회에서 가장 어려운 상대인 뾰족발톱은 이 땅의 수호자라 주장하는 나이트 엘프들에 의해 자유로이 살고 있습니다. 뾰족발톱은 이곳의 남쪽 지역을 다니며 먹이를 사냥하고 있지요. 그들의 존재를 모르는 여행자들의 사지를 하나씩 찢어내는 것을 즐기며 말입니다.$B$B그런 짐승을 처치한다는 것은 대단한 소득일 것입니다. 이 짐승을 잡는 데 행운이 따르길 바랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5595, 'koKR', NULL, '이 밤호랑이는 나이트 엘프들과 그들의 동맹 사이에서는 유순하다는 소문이 있습니다. 그래서 더 가치 있는 사냥감이지요. 샤둠브라의 사냥길은 레인나무 은신처에서 바로 우리 서쪽 땅까지 이른답니다. 샤둠브라의 털은 송진빛이 돌며 그 속도를 절대 얕잡아 봐서는 안 됩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5613, 'koKR', '안녕하시오. 잿빛 골짜기 점령을 위한 최전선에 오신 걸 환영하오! 영웅이 되기 위한 임무를 구하러 왔다면 제대로 찾아 오신 겁니다. 나는 이곳에서 호드에 영광을 가져다줄 강한 $C|1을;를; 찾고 있었소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5633, 'koKR', '그 용은 귀족의 가면 뒤에 숨어 있지만 이 서판으로 그 정체가 드러나게 될 거요... 내가 본 것이 진실이라면 난 이 전투에서 살아남지 못할 거요, 친구. 내가 시작한 일을 끝낼 자는 바로 당신이오. 당신 부대와 당신은 준비가 됐소? 당신이 준비가 되면 시작하도록 하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5653, 'koKR', '이곳 토막나무 주둔지를 오가는 짐마차와 상인들에 대해 알고 싶은 거라면 운 좋게도 바로 내가 자네가 찾고 있는 오크라네. 하지만 유감스럽게도 난 사람들을 싫어하거든.$B$B필요한 게 있으면 얼른 말하라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5654, 'koKR', '자연의 원소들은 우리에게 말을 한다네, $c 친구. 우리가 배워야 할 지식을 나눠 주고 반드시 지켜져야 할 비밀을 가르쳐 주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5673, 'koKR', '난 제자들에게 새로운 것을 가르치기 위해 아주 고된 재훈련을 통해서 이전에 배운 것들을 다 잊게 한 적이 많이 있었다네. 이건 매번 할수록 점점 더 어려워지는 일이기 때문에 재훈련을 할 때마다 비용이 점점 더 많이 들지. 내가 자네가 배운 특성을 다 잊어 버리게 해 주길 바라나?', '난 제자들에게 새로운 것을 가르치기 위해 아주 고된 재훈련을 통해서 이전에 배운 것들을 다 잊게 한 적이 많이 있었다네. 이건 매번 할수록 점점 더 어려워지는 일이기 때문에 재훈련을 할 때마다 비용이 점점 더 많이 들지. 내가 자네가 배운 특성을 다 잊어 버리게 해 주길 바라나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5674, 'koKR', '원한다면 나는 훈련을 시켜 줄 수 있을 뿐 아니라 자네 머릿속에서 이전에 배운 특성 지식을 지워 버릴 수가 있네. 하지만 이렇게 이전에 배운 특성을 지워 버리는 것은 할 때마다 점점 더 어려운 일이 되기 때문에 점점 더 큰 비용이 들게 된다는 것을 명심해야 하네.', '원한다면 나는 훈련을 시켜 줄 수 있을 뿐 아니라 당신 머릿속에서 이전에 배운 특성 지식을 지워 버릴 수가 있습니다. 하지만 이렇게 이전에 배운 특성을 지워 버리는 것은 할 때마다 점점 더 어려운 일이 되기 때문에 점점 더 큰 비용이 들게 된다는 것을 명심해야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5693, 'koKR', '나약한 자들이나 마법으로 타락하게 됩니다. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련입니다.', '나약한 자들이나 마법으로 타락하게 됩니다. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5694, 'koKR', '어서 오십시오. 이곳에 훈련을 받으러 오셨다면 제가 기꺼이 훈련을 시켜 드리죠.$B$B곧 에메랄드의 꿈이 부르는 소리를 듣게 될 때가 올 겁니다. 여러 해 동안 동면을 취하고 가장 순수한 상들 중에서 걷게 될 텐데, 바로 그때 그곳에서 궁극의 수련을 쌓게 될 겁니다.', '어서 오십시오. 이곳에 훈련을 받으러 오셨다면 제가 기꺼이 훈련을 시켜 드리죠.$B$B곧 에메랄드의 꿈이 부르는 소리를 듣게 될 때가 올 겁니다. 여러 해 동안 동면을 취하고 가장 순수한 상들 중에서 걷게 될 텐데, 바로 그때 그곳에서 궁극의 수련을 쌓게 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5695, 'koKR', '무슨 일로 오셨나요?', '무슨 일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5696, 'koKR', '당신처럼 많이 알고 있는 이에겐 나는 더 이상 가르칠 게 없소! 당신은 호드 일원이니까 오그리마에 있는 노그를 찾아가야 하오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5713, 'koKR', NULL, '당신을 해칠 생각은 없어요. 나는 가시멧돼지들을 염탐하면서 녀석들의 동태를 살피고 있어요. 동료가 이 지역에서 뭔가 이상한 암흑의 기운이 뿜어져 나오는 것이 느껴진다고 해서 조사하러 왔는데, 우려할만한 사실을 알아냈어요.$B$B마법에 능한 언데드 외교관이 있는 것 같아요. 포세이큰은 아닌 것 같고... 그보다 더 악한 자라고 생각돼요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5714, 'koKR', '자네가 치명적인 마법을 많이 알고 있긴 하지만 나한테는 아직도 부족해 보이는군. $n, 훈련을 더 받아야 할 것 같네.', '자네가 치명적인 마법을 많이 알고 있긴 하지만 나한테는 아직도 부족해 보이는군. $n, 훈련을 더 받아야 할 것 같네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5715, 'koKR', '자네는 우리가 제어하는 힘을 맘대로 조작할 정도로 의지가 강하지 않네, $c 친구.', '자네는 우리가 제어하는 힘을 맘대로 조작할 정도로 의지가 강하지 않네, $c 친구.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5716, 'koKR', '대지모신 앞에서 대체 내가 어떻게 자네를 더 훈련시켜 줄 수 있겠나, $n?', '대지모신 앞에서 대체 제가 어떻게 당신을 더 훈련시켜 줄 수 있겠습니까, $n 님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5717, 'koKR', '대지모신의 길에는 여러 가지가 있지. 선조들께서 보살펴 주시기를 비네, $c|1이여;여;.', '대지모신의 길에는 여러 가지가 있지요. 선조들께서 보살펴 주시기를 빕니다, $c|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5719, 'koKR', '흑마법사 지식을 더 얻고자 내 앞에서 자신을 낮추다니, 아주 현명한 친구로군, $n.', '흑마법사 지식을 더 얻고자 내 앞에서 자신을 낮추다니, 아주 현명한 친구로군, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5720, 'koKR', '자네 같은 $c에게 낭비할 시간은 없네.', '자네 같은 $c에게 낭비할 시간은 없네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5721, 'koKR', '서 있는 모습만 봐도 전사가 아닌 걸 알겠군.$B$B저리 가서 좀 더 안전한 일이나 독서를 하는 게 어떻겠소?', '서 있는 모습만 봐도 전사가 아닌 걸 알겠군.$B$B저리 가서 좀 더 안전한 일이나 독서를 하는 게 어떻겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5722, 'koKR', '어둠은 당신 같은 $c|1을;를; 원하지 않소. 그만 재잘대고 내 눈앞에서 썩 사라지시오!', '어둠은 당신 같은 $c|1을;를; 원하지 않습니다. 그만 재잘대고 내 눈앞에서 썩 사라지세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5723, 'koKR', '당신에게 함유된 흑마법 소질을 측정해보니, 그 분량이 충분하지 않군요. 제가 더 이상 얘기를 나눌 이유가 없어요. 이만 가보세요.', '당신에게 함유된 흑마법 소질을 측정해보니, 그 분량이 충분하지 않군요. 제가 더 이상 얘기를 나눌 이유가 없어요. 이만 가보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5724, 'koKR', '당신은 전사가 아닌데... 내 훈련 방식은 하루도 견뎌 내지 못하게 생겼군!$B$B$c 주제에 자기가 전사쯤이나 되는 줄 알다니, 허 그것 참!', '당신은 전사가 아닌데... 내 훈련 방식은 하루도 견뎌 내지 못하게 생겼군!$B$B$c 주제에 자기가 전사쯤이나 되는 줄 알다니, 허 그것 참!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5725, 'koKR', '그대에게는 전사의 혼이 보이지 않는군요. 나는 그대 같은 $c에게 가르칠 만한 것이 없습니다.', '그대에게는 전사의 혼이 보이지 않는군요. 나는 그대 같은 $c에게 가르칠 만한 것이 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5733, 'koKR', '으스러진 손은 검은바위 요새 위쪽 곳곳에 첩자들을 파견할 수 있었지. 정보 수집 절차가 느리긴 했지만 보고 그냥 넘길 수 없는 발견을 했다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5734, 'koKR', '검은용군단의 세력이 불타는 평원의 경계를 넘어 스톰윈드 왕국까지 퍼져나갔던 것 같아! 그 찬탈자가 발각되어 축출된 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5735, 'koKR', '그래. 검은용군단의 여왕이 속임수를 써서 스스로 인간 왕궁의 일원으로 가장했던 거야. 더 끔찍한 사실은 그 용이 현재 스톰윈드의 대영주 볼바르 폴드라곤을 마음대로 조종했다는 거지.$B$B그렇게 터무니없는 군사 전략을 취한 것도 이해가 가기는 한다네. 최근 얼라이언스의 움직임을 보면서 우리 모두 언제 일이 터질지 궁금해 했거든. 이제야 검은용군단이 얼라이언스의 내부부터 무너뜨리려고 했던 거라는 걸 알게 됐지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5736, 'koKR', '<소리 내어 웃는 스랄>$B$B$R|1이여;여;, 자넨 아직 배울 게 많군.$B$B하긴 아주 오래전에 벌어진 전쟁과 유혈 충돌을 알기엔 자네는 너무 젊지... 우리 종족이 짊어졌던 굴레와 저주도 모르겠지.$B$B지금 얼라이언스와 우리의 관계는 아주 미묘하다네. 자잘한 충돌과 전투가 일어나고는 있지만 그래도 평화가 유지되고 있지 않는가? 우리가 수천 년 동안이나 누리지 못했던 그 평화 말이야. 이 평화를 저버리고 다시 혼돈의 불덩어리 속으로 뛰어들어야 하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5737, 'koKR', '그래, 그랬겠지, $n. 자네를 나무라는 것은 아니야. 나도 젊었을 때는 그랬거든. 충동적이고, 반항적이고... 게다가 사고에 일관성이라고는 하나도 찾아볼 수 없을 때가 많았지! 난 이제 더 이상 그런 성깔을 부릴 수가 없다네.$B$B휴, 넋두리는 그만하도록 하지. 자네에게 맡길 임무가 있네. 목숨을 걸어도 성공을 장담 못 하는 위험한 임무야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5738, 'koKR', '<소리 내어 웃는 스랄>$B$B잘 기억해 두지. 자, $n. 내 말을 잘 듣게. 검은용군단의 여왕인 오닉시아가 스톰윈드의 권력층에서 밀려났네. 그 용은 탈출해서 먼지진흙 습지대에 있는 자기 둥지로 도망갔지.$B$B우리 호드의 수도와 그렇게 가까운 곳에서 살게 놔둘 수는 없어! 당하기 전에 우리가 먼저 쳐야 해!$B$B$n, 오닉시아를 처치하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5739, 'koKR', '어서 오시오, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 내가 기꺼이 가르쳐 드리겠소.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자요. 이 사실을 잊지 마시오.', '어서 오세요, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리지요.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자입니다. 이 사실을 잊지 마세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5740, 'koKR', '어서 오시오, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 내가 기꺼이 가르쳐 드리겠소.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자요. 이 사실을 잊지 마시오.', '어서 오세요, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리지요.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자입니다. 이 사실을 잊지 마세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5753, 'koKR', '이 항구에 꽤 수상한 자들이 드나들고 있으니 몸조심하는 게 좋을 겁니다, $n. 절대 아무나 믿어서는 안 돼요. 여기서는 알 수 없는 일들도 많이 일어나고 있으니까 말이죠...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5754, 'koKR', '그러니까 전쟁노래 도끼 때문에 온 게로군요. 좀 늦었군요. 저 화물상자는 벌써 며칠째 저렇게 있었답니다.$B$B준비가 끝나거든 주저하지 말고 가지고 가십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5773, 'koKR', '돌발톱 산맥에는 곳곳에 위험한 동굴들이 많이 있지. 영광을 위해서 기꺼이 목숨까지 내놓을 각오가 돼 있는 자라면 이 동굴에서 많은 모험을 할 수 있을 걸세.$B$B어쩌면 자네는 마음과 영혼을 따라야만 얻을 수 있는 부를 찾고 있는 것인지도 모르겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5793, 'koKR', '음... 생선은 너무 맛있어. 당신 낚시 배우러 온 건가? 아님 생선 먹으러? 음...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5794, 'koKR', '물론, 낚시하는 걸 가르쳐줄 수 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5795, 'koKR', NULL, '$n, 제발 이곳을 떠나세요. 그대는 여기서 어떤 일이 일어나고 있는지 모릅니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5796, 'koKR', NULL, '마력 깃든 토륨은 많은 이들이 찾는 금속이죠. 그걸 찾으려면 대장장이나 광부에게 물어보는 게 가장 빠른 길일 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5797, 'koKR', NULL, '회복의 수정은 구하기 쉽지 않은 물건입니다.$B$B운고로 분화구에서 구할 수 있을 것이니 그리로 가보는 게 제일 좋은 방법일 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5798, 'koKR', '가뭄이 들어 고생을 할지언정 고기는 부족한 법이 없지! 내 물건을 한번 보겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5799, 'koKR', NULL, '이 잠자가 도와드릴 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5800, 'koKR', '요리는 내가 좀 하지. 그렇소, 내가 다릴 리크너선이오. 뭘 원하는지 말만 하시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5813, 'koKR', '나만큼 응급치료를 잘 아는 이도 없다오, $r. 배우러 여기 왔다면, 내 최선을 다해 가르쳐 드리리다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5815, 'koKR', NULL, '의술을 배우는 학생이신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5816, 'koKR', NULL, '여기는 어쩐 일이신가요, $c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5817, 'koKR', NULL, '우리 종족은 그대가 고치려는 그 유물만큼이나 산산조각났답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5818, 'koKR', NULL, '과거는 바꿀 수 없지만 시간은 어떤 상처라도 치유할 수 있죠. 그게 가능하다는 걸 보여줘서 고마워요, $n. 안녕히 가세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5819, 'koKR', '어서 오게, $c. 내가 도울 일이라도 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5820, 'koKR', '내가 그대에게 할 질문은 이것일세.$B티탄이 창조한 위상 중 데스윙이라는 사악한 존재가 된 것은 무엇인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5821, 'koKR', '누군가 나와 얘기를 나누려고 찾아온다는 것은 항상 기분 좋은 일이야. 어떻게 지냈나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5822, 'koKR', '자, 내 질문에 대답해 보게나, $n.$B리치 왕이 되어 로데론 전역에 역병을 퍼뜨린 존재는 무엇인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5833, 'koKR', '그래, 자네 좀 아는군! 더 배우고 싶거든 스톰윈드에 있는 조르지오 볼레로를 찾아가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5834, 'koKR', '토륨 대장조합에서는 불의 군주의 성스러운 무기를 만드는 비법을 알고 있는데, 필요한 재료를 모아올 인력이 부족한 형편이네.$B$B나, 로크토스 다크바게이너는 토륨 대장조합을 대신하여 화산 심장부에서 재료를 모아오는 자에게 보상으로 아주 값진 비법을 줄 거야.$B$B$R|1이여;여;, 자네의 생각을 말해 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5835, 'koKR', '당신의 악마를 더 강하게 만들고 싶습니까? 돈이야 좀 들겠지만 제대로 찾아오셨습니다.', '당신의 악마를 더 강하게 만들고 싶습니까? 돈이야 좀 들겠지만 제대로 찾아오셨습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5836, 'koKR', '당신은 흑마법사가 아니니 당신한테 낭비할 시간은 없습니다. 어서 가십시오!', '당신은 흑마법사가 아니니 당신한테 낭비할 시간은 없습니다. 어서 가십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5838, 'koKR', '야수에게 가르칠 기술을 배우러 오셨습니까?', '야수에게 가르칠 기술을 배우러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5839, 'koKR', '$g형제:자매;여, 미안하지만 나는 사냥꾼과 그 야수에게만 도움을 줄 수가 있습니다.', '$g형제:자매;여, 미안하지만 저는 사냥꾼과 그 야수에게만 도움을 줄 수가 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5840, 'koKR', '왕립 연금술 학회는 어리석은 자를 기다려 주지 않으며 나 또한 마찬가지일세. 다음에 내가 타고 다니는 녀석에 대해 우리가 대화를 나눌 때쯤이면 자네가 언더시티의 친구로 인정받게 될지도 모르겠군. 그럼 그때까지 안녕히...', '왕립 연금술 학회는 어리석은 자를 기다려 주지 않으며 나 또한 마찬가지일세. 다음에 내가 타고 다니는 녀석에 대해 우리가 대화를 나눌 때쯤이면 자네가 언더시티의 친구로 인정받게 될지도 모르겠군. 그럼 그때까지 안녕히...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5841, 'koKR', '난 오그리마와 오크 종족에게 확고한 동맹인 자들에게만 탈것을 판매하네. 가서 우리 오크족에게 자신을 증명해 보이게나. 그럼 내 힘센 늑대들을 살펴볼 수 있게 해 주겠네.', '난 오그리마와 오크 종족에게 확고한 동맹인 자들에게만 탈것을 판매하네. 가서 우리 오크족에게 자신을 증명해 보이게나. 그럼 내 힘센 늑대들을 살펴볼 수 있게 해 주겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5842, 'koKR', '미안하네만 검은창 부족에게 확고한 동맹임을 증명하지 않은 자에게 랩터를 팔지 않네. 우리에게 우호적인 평판 이상이라는 걸 증명해 보인다면 내 랩터를 보여 주겠네.', '죄송하지만 전 검은창 부족에게 확고한 동맹임을 증명하지 않은 자에게 랩터를 팔지 않습니다. 우리에게 우호적인 평판 이상이라는 걸 증명해 보인다면 제 랩터를 보여 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5843, 'koKR', '자네는 우리 종족에게 알려지지 않았군. 코도는 강인한 탈것이며, 우리 종족의 사랑과 애정으로 자란 짐승이기 때문에 낯선 자에게는 팔지 않네. 즉 썬더 블러프의 장로들이 자네를 확고한 동맹으로 인정하기 전까지는 코도를 팔 수가 없다네.', '당신은 우리 종족에게 알려지지 않았군요. 코도는 강인한 탈것이며, 우리 종족의 사랑과 애정으로 자란 짐승이기 때문에 낯선 자에게는 팔지 않습니다. 즉 썬더 블러프의 장로들이 당신을 확고한 동맹으로 인정하기 전까지는 코도를 팔 수가 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5844, 'koKR', '안타깝게도 다르나서스와 텔드랏실의 나이트 엘프는 그대를 같은 편으로 생각하지 않는군요. 말이 아닌 행동으로 그대가 우리 나이트 엘프의 친구라는 것을 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여드릴 수 있습니다.', '안타깝게도 다르나서스와 텔드랏실의 나이트 엘프는 그대를 같은 편으로 생각하지 않는군요. 말이 아닌 행동으로 그대가 우리 나이트 엘프의 친구라는 것을 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여드릴 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5853, 'koKR', '물러서시오! 여긴 애들이 올 곳이 아니오! 애송이는 어서 가란 말이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5855, 'koKR', '미안하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않소. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말이오.$B$B물론 당신이 적이라는 얘기는 아니지만 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠소이다.', '죄송하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않습니다. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말입니다.$B$B물론 당신이 적이라는 얘기는 아닙니다. 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5856, 'koKR', '너무 서두르지는 마세요. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없습니다. 당신이 아이언포지의 확고한 동맹이라는 게 인정되면 팔려고 내놓은 산양을 기꺼이 보여드리지요.', '너무 서두르지는 마세요. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없습니다. 당신이 아이언포지의 확고한 동맹이라는 게 인정되면 팔려고 내놓은 산양을 기꺼이 보여드리지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5857, 'koKR', '엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 확고한 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건의 확고한 동맹이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하죠.', '엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 확고한 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건의 확고한 동맹이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5858, 'koKR', '아이언포지 드워프들과 확고한 동맹이 되시면 산양을 부리는 법을 가르쳐 드릴 수 있답니다.', '아이언포지 드워프들과 확고한 동맹이 되시면 산양을 부리는 법을 가르쳐 드릴 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5859, 'koKR', '해골마 타는 법은 먼저 언더시티 포세이큰들과 확고한 동맹이 되면 배울 수 있다네.', '해골마 타는 법은 먼저 언더시티 포세이큰들과 확고한 동맹이 되면 배울 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5860, 'koKR', '기계타조 조종법을 배우려면 먼저 놈리건의 노움들과 확고한 동맹이 되어야 합니다.', '기계타조 조종법을 배우려면 먼저 놈리건의 노움들과 확고한 동맹이 되어야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5861, 'koKR', '스톰윈드의 인간과 확고한 동맹이 되시면 말 타는 법을 배우실 수 있습니다.', '스톰윈드의 인간과 확고한 동맹이 되시면 말 타는 법을 배우실 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5862, 'koKR', '다르나서스 나이트 엘프들과 확고한 동맹이 되시면 호랑이 타는 법을 가르쳐 드릴 수 있습니다.', '다르나서스 나이트 엘프들과 확고한 동맹이 되시면 호랑이 타는 법을 가르쳐 드릴 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5863, 'koKR', '오그리마 오크들과 확고한 동맹인 자만이 늑대 기수가 될 수 있습니다.', '오그리마 오크들과 확고한 동맹인 자만이 늑대 기수가 될 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5864, 'koKR', '코도 타는 법은 썬더 블러프 타우렌들과 확고한 동맹이 되면 배울 수 있다네.', '코도 타는 법은 썬더 블러프 타우렌들과 확고한 동맹이 되면 배울 수 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5865, 'koKR', '랩터 타는 법은 검은창 트롤과 확고한 동맹이 되시면 가르쳐 드릴 수 있습니다.', '랩터 타는 법은 검은창 트롤과 확고한 동맹이 되시면 가르쳐 드릴 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5873, 'koKR', NULL, '당신에게는 차원문 마법을 이해할만한 정신적인 능력이 없는 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5874, 'koKR', NULL, '마법사로서 자네는 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 자, 준비가 됐다면 내 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5875, 'koKR', NULL, '당신에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5876, 'koKR', NULL, '마법사로서 자네는 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 자, 준비가 됐다면 내 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5877, 'koKR', '당신에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5878, 'koKR', '마법사로서 자네는 차원문을 소환해 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 준비가 됐다면 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5879, 'koKR', '보아하니 차원문을 이해할만한 정신적인 능력이 없는 것 같은데...', '보아하니 차원문을 이해할만한 정신적인 능력이 없는 것 같은데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5880, 'koKR', '마법사로서 자네는 차원문을 소환해 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 준비가 됐다면 가르쳐 주도록 하지.', '마법사인 당신은 차원문을 열어 바로 이곳으로 돌아올 수 있는 소수의 사람 중 하나입니다. 준비됐다면 제가 가르쳐 드리죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5881, 'koKR', NULL, '마법사로서 자네는 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 자, 준비가 됐다면 내 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5882, 'koKR', NULL, '자네에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5883, 'koKR', '자네에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5884, 'koKR', '마법사로서 자네는 차원문을 소환해 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 준비가 됐다면 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5885, 'koKR', '자네에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5886, 'koKR', '마법사로서 자네는 차원문을 소환해 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나일세. 준비가 됐다면 가르쳐 주도록 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5894, 'koKR', '내 이름은 몬티. 쥐들은 내 사냥감이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5913, 'koKR', '오, 이 푸른 가죽은 정말 매력적이군. 알다시피 이 근방에는 호드의 신병이 되고 싶어서 지혜보다 열정만을 앞세워 사냥을 하는 이들이 아주 많네. 그러니 누구나 조심해야 하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5914, 'koKR', '자네 솜씨가 나보다 훨씬 뛰어나구먼, 젊은이. 이제 썬더 블러프의 중앙 고원에서 가게를 운영하고 있는 우나를 찾아가보게. 그녀라면 자네가 원하는 것을 가르쳐줄 수 있을 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5917, 'koKR', '이제 자네는 한층 수준 높은 코도 통가죽 무두질을 배울 준비가 된 걸세. 시작하도록 하지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5918, 'koKR', NULL, '빛과 어두움 사이에는 그림자가 있지요... 그 그림자는 당신이 지금껏 보지 못한 힘을 가지고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5919, 'koKR', NULL, '빛과 어두움 사이에는 그림자가 있지요... 그 그림자는 당신이 지금껏 보지 못한 힘을 가지고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5920, 'koKR', '카즈 모단에서는 우리 쥐 꼬치구이가 최고지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5921, 'koKR', '보아하니 일거리를 찾고 있는 것 같은데 지하철을 타고 아이언포지에 있는 깊은굴 지하철로 가서 내 동생 몬티를 만나보세요. 아마 당신에게 맡길 일이 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5933, 'koKR', '이방인 친구, 조심하는 게 좋을 겁니다.', NULL, '라벤홀트 장원에서는 당신을 인정할 수 없소.', NULL, '무례한 친구로군. 라벤홀트 경은 무례한 자를 싫어하시지.', NULL, '건방지군. 레이븐홀트의 주인께서는 건방진 자를 싫어하신다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5934, 'koKR', '이렇게 다시 만나다니 너무 기쁘구려, $n.', NULL, '어서 오십시오. 파라드 님과는 얘기해 봤습니까?', NULL, '비밀결사대는 그야말로 오합지졸입니다. 조직력은 물론이고 실력도 형편없는 데다가 게으르기까지 하니...', NULL, '비밀결사대는 체계도 없고 실력도 없고 게으르기까지 한 얼치기들일 뿐이지... ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5935, 'koKR', '정말 더 영리해졌군, $n.', NULL, '다시 만나 영광입니다, $n.', NULL, '아까 시몬이 널 찾던 것 같던데, $n. 아직 못 만났나?', NULL, '시몬이 아까 자네를 찾던 것 같던데, $n. 벌써 이야기해 봤나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5938, 'koKR', '벌레 같은 것이 감히 라벤홀트 장원에 발을 들여놓다니!', '벌레 같은 것이 감히 라벤홀트 장원에 발을 들여놓다니!', '등에 비수가 꽂히거나 몸 속에 독이 퍼지거나 하겠지. 성한 몸으로 이곳을 빠져나가기는 힘들 테니까 말이야.', '등에 비수가 꽂히거나 몸 속에 독이 퍼지거나 하겠지. 성한 몸으로 이곳을 빠져나가기는 힘들 테니까 말이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5939, 'koKR', '갈수록 실력이 늘고 있군요, $n. 소문을 좀 들었습니다...', '갈수록 실력이 늘고 있군요, $n. 소문을 좀 들었습니다...', '윈스톤을 찾아가 얘기해 보십시오. 당신처럼 실력 있는 도적을 찾고 있다고 합니다.', '윈스톤을 찾아가 얘기해 보십시오. 당신처럼 실력 있는 도적을 찾고 있다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5940, 'koKR', '누락된 텍스트', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5943, 'koKR', NULL, '엘룬께서 그대와 함께하시길, $c|1이여;여;. 저는 아우버다인의 고통받는 주민들을 돕기 위해 달의 신전에서 왔습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5973, 'koKR', '쇼자미는 저 건너 여관 앞에 있으니 어서 가보게나. 저리 비켜! 난 지금 아주 바쁘니까.', '쇼자미는 저 건너 여관 앞에 있으니 어서 가보게나. 저리 비켜! 난 지금 아주 바쁘니까.', '야수라도 돌봐줘야 하는 모양이군? 그냥 대소변이나 잘 치우면 되는 일이지! 여관 앞에 가면 쇼자미가 있을 테니 그리로 가보게.', '야수라도 돌봐줘야 하는 모양이군? 그냥 대소변이나 잘 치우면 되는 일이지! 여관 앞에 가면 쇼자미가 있을 테니 그리로 가보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5974, 'koKR', '명예의 골짜기로 가서 우리 근처에 있는 손차를 찾아보게나.', '명예의 골짜기로 가서 우리 근처에 있는 손차를 찾아보게나.', '자네가 데리고 있는 야수라면 손차가 잘 돌봐줄 걸세. 명예의 골짜기에 가면 용맹의 투기장과 사냥꾼의 전당이 있는데 그 사이에 있는 우리에 있지. 그럼 어서 가보게!', '자네가 데리고 있는 야수라면 손차가 잘 돌봐줄 걸세. 명예의 골짜기에 가면 용맹의 투기장과 사냥꾼의 전당이 있는데 그 사이에 있는 우리에 있지. 그럼 어서 가보게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5976, 'koKR', '아, 세이크와를 찾아가셔야겠군요. 여관 앞에 서 있는 걸 마지막으로 본 것 같습니다.', '아, 세이크와를 찾아가셔야겠군요. 여관 앞에 서 있는 걸 마지막으로 본 것 같습니다.', '세이크와가 당신의 동물 친구를 돌봐줄 수 있을 겁니다. 여관 앞에서 찾아보십시오.', '세이크와가 당신의 동물 친구를 돌봐줄 수 있을 겁니다. 여관 앞에서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5977, 'koKR', '불루그의 도움이 필요하신 거로군요. 봉우리 하층에 있는 여관과 썬더 블러프 은행 사이에 있을 겁니다.', '불루그의 도움이 필요하신 거로군요. 봉우리 하층에 있는 여관과 썬더 블러프 은행 사이에 있을 겁니다.', '동물 친구들의 안녕에 그렇게 신경을 쓰이시나요? 당신은 참 좋은 분이시군요. 봉우리 하층에 있는 불루그가 도와드릴 수 있을 겁니다. 은행과 여관 사이에 있으니 한번 찾아보십시오.', '동물 친구들의 안녕에 그렇게 신경을 쓰이시나요? 당신은 참 좋은 분이시군요. 봉우리 하층에 있는 불루그가 도와드릴 수 있을 겁니다. 은행과 여관 사이에 있으니 한번 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5978, 'koKR', '야수 관리인 모르가누스라면 당연히 마구간 앞에 서 있지...', '야수 관리인 모르가누스라면 당연히 마구간 앞에 서 있지...', '눈치가 좀 느리군? 흠, 자네가 만약 야수 관리인이라면 어디에 있겠나? 마구간 근처로 가서 모르가누스를 찾아보게.', '눈치가 좀 느리군? 흠, 자네가 만약 야수 관리인이라면 어디에 있겠나? 마구간 근처로 가서 모르가누스를 찾아보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5979, 'koKR', '안야 마울레이 상업 지구 위층 여관에 있다.', '안야 마울레이 상업 지구 위층 여관에 있다.', '우리 야수가 많으면 좋겠다. 야수 돌봐주는 거 안야 마울레이가 도와준다. 상업 지구 위층 여관에서 찾아봐라.', '우리 야수가 많으면 좋겠다. 야수 돌봐주는 거 안야 마울레이가 도와준다. 상업 지구 위층 여관에서 찾아봐라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5980, 'koKR', '소환수는 안심하고 알랏신에게 맡기셔도 좋습니다. 그는 사냥꾼들이 모이는 세나리온 자치령에 살고 있으니 그리로 가서 만나보도록 하십시오.', '소환수는 안심하고 알랏신에게 맡기셔도 좋습니다. 그는 사냥꾼들이 모이는 세나리온 자치령에 살고 있으니 그리로 가서 만나보도록 하십시오.', '알랏신은 수백 년 동안 사냥꾼이 길들인 야수를 돌봐왔습니다. 이 부근 사냥꾼들은 알랏신의 손길을 많이 찾지요. 그대도 알랏신을 찾는 거라면 세나리온 자치령으로 가보시기 바랍니다.', '알랏신은 수백 년 동안 사냥꾼이 길들인 야수를 돌봐왔습니다. 이 부근 사냥꾼들은 알랏신의 손길을 많이 찾지요. 그대도 알랏신을 찾는 거라면 세나리온 자치령으로 가보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5981, 'koKR', '우리는 모두 하나의 커다란 퍼즐을 이루는 조각들이오, $n. 조각조각 모여 하나의 퍼즐을 맞춰나가듯이 우리도 서로 이끌어나가는 거요.$B$B그리고 우리를 이끌어주는 이들 역시 더욱 큰 세력의 이끌림을 받고 있는 것인지도 모르오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5982, 'koKR', '아, 상냥한 세리아드네 말이군요. 그녀가 보살피는 동물들은 모두 우리 안에 안전하게 살고 있지요. 돌라나르 여관 바로 밖에서 찾을 수 있을 겁니다.', '아, 상냥한 세리아드네 말이군요. 그녀가 보살피는 동물들은 모두 우리 안에 안전하게 살고 있지요. 돌라나르 여관 바로 밖에서 찾을 수 있을 겁니다.', '동물을 보살피는 사람을 찾으신다고요? 그렇다면 돌라나르의 여관 밖에 있는 세리아드네를 찾아보십시오. 그녀가 도와줄 수 있을 겁니다.', '동물을 보살피는 사람을 찾으신다고요? 그렇다면 돌라나르의 여관 밖에 있는 세리아드네를 찾아보십시오. 그녀가 도와줄 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5983, 'koKR', '인심 좋은 엘마는 오랜 세월 동안 이곳 동물들을 보살펴 왔소. 당신이 동물을 맡긴다면 기꺼이 보살펴줄 거요. 엘마는 사자무리 여관 바로 밖에서 찾을 수 있소이다.', '인심 좋은 엘마는 오랜 세월 동안 이곳 동물들을 보살펴 왔어요. 당신이 동물을 맡긴다면 기꺼이 보살펴줄 거예요. 엘마는 사자무리 여관 바로 밖에서 찾을 수 있습니다.', '이 근처에서 동물을 보살피는 일이라면 엘마가 다 맡아서 하오. 사자무리 여관 바로 밖에 있을 테니 필요하면 찾아가 보시오.', '이 근처에서 동물을 보살피는 일이라면 엘마가 다 맡아서 해요. 사자무리 여관 바로 밖에 있을 테니 필요하면 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5984, 'koKR', '드워프 지구에 있는 제노바 스톤실드를 찾아가셔야 합니다. 사냥꾼들이 그녀의 아버지를 찾아가 훈련을 받는 동안 그녀가 동물들을 돌봐주곤 합니다.', '드워프 지구에 있는 제노바 스톤실드를 찾아가셔야 해요. 사냥꾼들이 그녀의 아버지를 찾아가 훈련을 받는 동안 그녀가 동물들을 돌봐주곤 하지요.', '야수 훈련을 위해 다른 야수를 맡길 곳이 필요하다면 저기 드워프 지구에 있는 제노바 소튼실드를 찾아가 보십시오.', '야수 훈련을 위해 다른 야수를 맡길 곳이 필요하다면 저기 드워프 지구에 있는 제노바 소튼실드를 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5985, 'koKR', '카라노스 썬더브루 양조장 바로 밖에 있는 셸비 스톤플린트를 찾아가 보세요. 당신이 맡기는 동물을 아주 잘 돌봐줄 겁니다.', '카라노스 썬더브루 양조장 바로 밖에 있는 셸비 스톤플린트를 찾아가 보세요. 당신이 맡기는 동물을 아주 잘 돌봐줄 겁니다.', '셸비 스톤플린트가 이 지역 사냥꾼들의 동물을 꽤나 많이 보살피고 있지요. 당신도 도움이 필요하다면 썬더브루 양조장 쪽에 있는 셸비를 한번 찾아가 보세요.', '셸비 스톤플린트가 이 지역 사냥꾼들의 동물을 꽤나 많이 보살피고 있지요. 당신도 도움이 필요하다면 썬더브루 양조장 쪽에 있는 셸비를 한번 찾아가 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5986, 'koKR', '울브렉 파이어핸드는 다른 일이라면 몰라도 동물 보살피는 일이라면 아주 진지하게 생각하죠. 울브렉은 전투의 전당에서 사냥꾼들과 자주 어울리는 모양이니 동물을 돌봐줄 자가 필요하다면 그를 찾아가 보십시오.', '울브렉 파이어핸드는 다른 일이라면 몰라도 동물 보살피는 일이라면 아주 진지하게 생각하죠. 울브렉은 전투의 전당에서 사냥꾼들과 자주 어울리는 모양이니 동물을 돌봐줄 자가 필요하다면 그를 찾아가 보십시오.', '전투의 전당으로 가면 이 지역 야수 관리인 울브렉 파이어핸드가 있어요. 동물을 맡기면 잘 먹이면서 정성껏 보살펴줄 겁니다.', '전투의 전당으로 가면 이 지역 야수 관리인 울브렉 파이어핸드가 있어요. 동물을 맡기면 잘 먹이면서 정성껏 보살펴줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5993, 'koKR', '$n, 당신에게 드릴 것이 있습니다. 꽤 중요한 것이라고 할 수 있지요.', '$n, 당신에게 드릴 것이 있습니다. 꽤 중요한 것이라고 할 수 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5994, 'koKR', '$n 님, SI:7 본부에 온 걸 환영합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5995, 'koKR', '오늘 아침 당신 앞으로 이것이 왔습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5996, 'koKR', '라벤홀트 장원에서 온 사절이 오늘 아침 제게 이 편지를 건네주더군요. 수신인이 당신으로 되어 있습니다, $n.', '라벤홀트 장원에서 온 사절이 오늘 아침 제게 이 편지를 건네주더군요. 수신인이 당신으로 되어 있습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6033, 'koKR', '$C|1이여;여;, 보고를 하러 온 거요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6058, 'koKR', '얼음이빨 광산은 호드의 영토에 있으며 서리늑대 무덤에서 북쪽 산맥에 있습니다.$B$B현재 코볼트들이 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6061, 'koKR', '깊은무쇠 광산은 얼라이언스 영토에 있으며 스톰파이크 무덤의 북쪽에 있습니다.$B$B현재 트로그들이 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6062, 'koKR', '이 기념비는 스톰윈드를 수호하다 쓰러져 간 모든 이들에게 바쳐진 것이다. 우리 종족은 자유를 지키고 스스로 운명에 대한 주도권을 잃지 않기 위해 믿을 수 없을 정도의 고난을 극복해 왔다. 바로 이곳에서 우리 종족을 휩쓸고 간 1차 대전쟁 중에 있었던 시민들의 모든 희생을 기념하는 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6066, 'koKR', '알터랙 계곡에서는 전투가 한창인데 장비 보급이 부족하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6073, 'koKR', '우리 부대는 아직 아무런 승급도 되지 않았소. 현재 보급품이 부족해 승급할 수 없소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6093, 'koKR', NULL, '전장에는 적의 피가 흐르고 위대한 정령들이 우리의 부름에 응하여 호드의 앞을 가로막는 이들은 모두 쓰러뜨릴 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6095, 'koKR', NULL, '여기까지 오느라 수고하셨습니다. 요새로 돌아가야 하니 본관을 엄호해 주지 않겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6096, 'koKR', NULL, '이제서야 오는군요. 도대체 뭐가 이리 오래 걸린 거죠? 아무튼 날 엄호해요. 요새로 돌아가야 하니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6098, 'koKR', NULL, '$n, 할 일이 많이 남아 있습니다! 계속해서 적을 쓰러뜨리도록 하십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6099, 'koKR', NULL, '그렇습니다, $n! 정령들이 동요하고 있습니다. 곧 적들에게 정령들의 힘을 보여 주게 될 것이고 엄청난 타격으로 놈들이 비틀거릴 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6100, 'koKR', NULL, '$n, 얼음군주 로크홀라와 접촉하는 데 성공했습니다. 그를 대지에 결속하기 위한 제물도 충분했고 우리의 대의를 듣고 가치 있는 일이라 여기셨습니다. 준비하십시오. 이제 그분이 오십니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6101, 'koKR', '여기서 무사히 빠져나가 요새로 귀환하려면 날 호위 해줄 쓸만한 병사가 몇 명 필요한데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6104, 'koKR', '여기에는 거래와 구매인에 대한 정보며 기타 사업과 관계된 여러 가지 사항이 가득 적혀 있는 것 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6105, 'koKR', NULL, '지휘관님의 눈을 똑바로 쳐다봐서는 안 되네.', NULL, '우리는 케른님으로부터 직접 명령을 받았네. 지휘관님의 임무를 방해하지 말게나.', NULL, '주술사 지휘관은 소홀히 대할 대상이 아니네, $r.', NULL, '곧 로크홀라님께서 일어나실 거예요... 이제 곧...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6107, 'koKR', NULL, '편대 출격 준비 완료! $n, 지금 이 봉화를 전장의 중앙으로 가져가서 동부 분화구에 놓도록 한다. 편대의 출격 좌표를 전송할 때까지 봉화를 수호하도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6108, 'koKR', '나는 바다제왕들의 군주인 히드락시스다. 너는 정령이 아니므로 우리의 전쟁을 이해하지 못할 것이다... 어쩌면 우리 모두에게 이득이 될 거래를 할 수 있을 것도 같군...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6109, 'koKR', '만나서 반갑군. 또 다른 정령 군주들과 대적하는 우리의 전투는 아직 격해지지 않지만 자네의 노력은 우리가 승리하는 데 도움이 될 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6110, 'koKR', NULL, '편대 출격 준비 완료! $n, 지금 이 봉화를 전장의 중앙으로 가져가서 서부 분화구에 놓도록 한다. 편대의 출격 좌표를 전송할 때까지 봉화를 수호하도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6134, 'koKR', '뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까.', '뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6153, 'koKR', '세나리온 의회가 어딘가에 기록해 두었을 정보를 찾고 있는 거라면 제게 말해 보십시오. 그렇지만 제 도움을 받으려면 먼저 당신 스스로 무슨 정보를 찾고 있는지부터 확실히 알아야합니다.$B$B이제 이해가 가신다고요? 좋습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6154, 'koKR', '모든 문제의 답은 그대의 내면에 잠들어 있소. 그러니 세상 사람들이 하는 소리에 너무 귀를 기울이지 마시오. 그대는 이미 답을 알고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6155, 'koKR', '$C님, 이 황무지에는 과거의 망령들이 살고 있습니다. 우린 그들을 깨우지 않도록 항상 조심해야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6158, 'koKR', '$n, 이제 최종 임무를 수행할 준비가 되었군. 화산 심장부 바닥에 새겨진 불의 룬은 불의 세계로 통하는 길로서, 불의 군주들에게 마력을 부여하는 원천이노라. 우리에게는 치욕의 상징일 뿐이지. 반드시 그것을 꺼야만 하노라!$B$B룬을 끄려면 물의 진수를 한 병 들고 가서 그 위에 부어야 한다. 그러면 불길이 꺼져 룬은 제 힘을 잃어버릴 것이고 당연히 우리의 적들도 약해질 것이다!', '안녕, 친구. 내 이름은 레미야. 동쪽 붉은마루 산맥에서 왔고, 장사거리 좀 찾으러 왔지, 장사거리 말이야. 혹시 뭐... 뭐 좀 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6159, 'koKR', '언더시티 길드 사무소에 온 것을 환영하네. 무슨 일로 왔는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6160, 'koKR', '세나리온 의회에 오신 것을 환영합니다, $c|1이여;여;. 무엇을 도와 드릴까요?', '세나리온 의회에 오신 것을 환영합니다, $c|1이여;여;. 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6161, 'koKR', '히드락시스와 얘기를 나눠 보도록!', NULL, '필멸의 존재여... 나를 귀찮게 하지 마라!', NULL, '감히 어디서 그 저속한 언어를 내뱉는가! 그런 걸 참을 수 있는 건 오직 히드락시스 군주뿐이시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6162, 'koKR', '필멸의 존재여, 어서 오라! 물의 군주에게 무슨 용무라도 있느냐?', NULL, '그간 네가 이룬 위업에 대한 얘기가 널리 퍼지고 있다. $n, 모두 너의 이름을 알고 있지.', NULL, '우리를 대신해 적과 싸울 결심을 하다니, 내 기꺼이 너와 위대한 물의 힘을 나누도록 하겠다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6163, 'koKR', '$n, 그간 네가 이룬 위업에 대한 얘기를 좀 듣고 싶구나. 시간을 내어 들려 준다면 큰 영광으로 알겠노라.', NULL, '군주 히드락시스께서 자네 칭찬을 아주 많이 하시더군. 친구여, 편히 있다 가게나.', NULL, '다음에 또 화산 심장부로 가게 되면 날 위해 불의 군주 한 놈을 처치해 주지 않겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6164, 'koKR', '나의 가르침을 받을 만한 자질이 없군. 상급 $c|1을;를; 찾아보는 게 좋을 거요.', '나의 가르침을 받을 만한 자질이 없군. 상급 $c|1을;를; 찾아보는 게 좋을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6165, 'koKR', '보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', '보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6167, 'koKR', '천리안을 찾아야 해!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6173, 'koKR', '다르나서스에서 저희를 이곳으로 보낸 이유는 스톰파이크 부족이 어려울 때 돕기 위해서입니다.', NULL, '대드루이드께서는 알터랙 계곡의 파괴적인 상황을 알리면 숲군주 이부스께서 분명 도우러 올 것이라 생각하고 계십니다.', NULL, '이런 끔찍한 일에 대한 심판은 우리의 몫이 아닙니다. 이부스가 오셔서 심판의 응징을 내리실 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6174, 'koKR', NULL, '$r|1이여;여;, 저는 믿음에 따라 행동한답니다. 이부스는 분명히 올 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6175, 'koKR', NULL, '에메랄드의 꿈에서 깨어난 지 얼마 되지 않아 조금 몽롱하군요. 그래도 이부스의 생명력이 느껴져요. 하지만 제 힘이 충분히 회복되지 않아서 아직 접촉하기는 어렵겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6176, 'koKR', NULL, '$n. 숲군주의 위치를 파악했어요. 더욱더 노력해야 합니다! 수정을 더 모아야 해요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6177, 'koKR', NULL, '$n, 숲군주에게 이 계곡의 파괴 상황 알렸어요. 서둘러 소환진으로 가야 합니다. 준비하세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6178, 'koKR', '주제도 모르는 바보 멀베릭에게 격추당했소. 요새로 돌아가지 못하면 모든 게 끝장일까 두렵소! 멀베릭과 그 전투와이번 부대를 막아내야 하오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6179, 'koKR', '아직도 믿기지가 않아... 매일 하던 정찰 임무로 중앙 비무장지대 위를 날던 중 변을 당했지 뭔가. 난 이크만과 실도르 모두 호드 편대사령관 멀베릭에게 당하는 모습을 목격했네! 그래서 홧김에 혼자 동료를 벗어나 그 잘난 척하는 멀베릭 녀석을 격추시켜 버렸지. 그런데 녀석이 떨어지기 전에 내 그리핀에 상처를 입히는 바람에 불행히 나도 추락했고, 이렇게 이 야만족 녀석들에게 포로로 붙잡힌 신세가 됐다네.$B$B꼭 요새로 돌아가야 하니 도와주게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6180, 'koKR', '$C|1이여;여;, 내 그리핀이 추락해 불타고 있을 때 녀석들이 날 조롱하는 목소리를 들었지.$B$B\"실도르! 너한테선 지독한 냄새가 나!\"라고 소리치더군.$B$B감히 이 실도르 님에게 그런 조롱을 퍼붓다니! 여기서 빠져나가도록 좀 도와줘! 정말로 냄새 나는 게 누군지 똑똑히 가르쳐 줄 수 있도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6181, 'koKR', '아, 재타르... <셀레브라스가 시선을 돌립니다.>$B$B내 아버지 레물로스는 그를 막으려 했지...$B$B재타르는 고집이 셌고, 대지의 정령 공주와 사랑에 빠졌을 때 아버지는 그들의 결합이 저주받았다는 걸 알았지만 재타르는 듣지 않았어.$B$B켄타우로스는 그 실수에서 태어났다. 기형적이고 증오로 가득한 존재들이었고, 내 삼촌 재타르는 결국 자기 자식들에게 죽임을 당했지...$B$B사악한 공주 테라드라스는 아직도 이 수정 동굴에서 그의 유해를 지키고 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6193, 'koKR', NULL, '때로는 이 숲이 아주 혼란스러울 때도 있답니다. 조심하도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6194, 'koKR', '즐겁고 풍족한 명절 되라고!', '즐겁고 풍족한 명절 되라고!', '굴뚝나무 목장조합 직영 농장에서 직접 공수해온 신선한 재료로 만든 맛있는 요리를 맛보라고!', '굴뚝나무 목장조합 직영 농장에서 직접 공수해온 신선한 재료로 만든 맛있는 요리를 맛보라고!', '트랄랄랄라! 풍성한 계절이 돌아왔군! 축제를 맞이해 나온 특별 용품들을 대폭 할인된 가격으로 줄 테니 한번 둘러보라고!', '트랄랄랄라! 풍성한 계절이 돌아왔군! 축제를 맞이해 나온 특별 용품들을 대폭 할인된 가격으로 줄 테니 한번 둘러보라고!', '이번 겨울맞이 축제는 굴뚝나무 목장조합에서 제공하는 맛있는 요리와 함께 하라고!', '이번 겨울맞이 축제는 굴뚝나무 목장조합에서 제공하는 맛있는 요리와 함께 하라고!', '이번 겨울맞이 축제에는 어떤 선물을 받고 싶은지 겨울 할아버지에게 소원을 비는 거 절대 잊지마!', '이번 겨울맞이 축제에는 어떤 선물을 받고 싶은지 겨울 할아버지에게 소원을 비는 거 절대 잊지마!', '다른 데 찾아봤자 실속 없이 돈만 낭비할 뿐이지... 굴뚝나무 목장조합에서 맛있는 요리를 사서 즐거운 겨울맞이 축제 보내라고!', '다른 데 찾아봤자 실속 없이 돈만 낭비할 뿐이지... 굴뚝나무 목장조합에서 맛있는 요리를 사서 즐거운 겨울맞이 축제 보내라고!', '고구마라도 좀 있으면 모닥불에다가 구워 먹을 텐데... 음, 맛있겠다!', '고구마라도 좀 있으면 모닥불에다가 구워 먹을 텐데... 음, 맛있겠다!', '연말연시엔 포장지 구입하는 것을 잊지 말라고! 친구들에게 방어구와 무기를 예쁘게 포장해 선물하는 것만큼 겨울맞이 축제의 따뜻한 정을 잘 전달할 수 있는 방법도 없지!', '연말연시엔 포장지 구입하는 것을 잊지 말라고! 친구들에게 방어구와 무기를 예쁘게 포장해 선물하는 것만큼 겨울맞이 축제의 따뜻한 정을 잘 전달할 수 있는 방법도 없지!'),
(6217, 'koKR', '우리 부대는 상급 부대로 승급했소. 하지만 정예 부대로 승급하기에는 보급품이 부족하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6218, 'koKR', '우리 부대는 정예 부대로 승급했소. 하지만 최정예 부대로 승급하기에는 보급품이 부족하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6219, 'koKR', '상급 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6220, 'koKR', '정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6222, 'koKR', '우리 부대가 최정예 부대로 승급하기는 했지만 그래도 보급품을 좀 더 모아야 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6223, 'koKR', '더 이상 보급품을 저장할 수 없소. 보관할 공간이 바닥났단 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6233, 'koKR', '새로운 무기를 다루는 법을 배우러 온 건가, 아니면 나의 소중한 시간을 빼앗으러 온 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6235, 'koKR', '어떤 무기를 배우고 싶은지 말해 보게. 볼일이 없다면 썩 물러가도록.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6236, 'koKR', '스톰파이크 무덤은 던 발다르의 동쪽 다리 건너에 있으며 산을 앞뒤로 만나고 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6242, 'koKR', '서리늑대 무덤은 서리늑대 마을에서 북쪽으로 그리 멀리 떨어지지 않은 길가에 있습니다.$B$B현재 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6250, 'koKR', '귀여운 우리 친구! 즐거운 겨울맞이 되세요... 착한 와우저 어린이들이라면 굴뚝나무 목장조합에서 특별한 물품을 할인된 가격에 구입할 수 있어요. 음... 생각만 해도 군침 도는 음식들이 다양하게 준비되어 있답니다.', NULL, '이번 명절이 지나가면 분명 이 겨울 할아버지는 다음 해를 위해 새 술을 빚을 준비를 할 거예요. 그러니 여기 이 가방 안에 있는 겨울맞이용 술은 한 방울도 남김없이 모조리 마셔 버려야겠어요.', NULL, '아니... 아무리 폭신해 보여도 그렇지, 제 무릎 위에 앉으면 안 되지요.', NULL, '그래요! 이번 겨울맞이 축제에는 겨울 할아버지에게서 어떤 선물을 받고 싶은지 한번 말해 봐요.$B$B호호호! 어서...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6255, 'koKR', '군대는 물자의 힘으로 움직인다고 하는데, 정말 맞는 말이오. 어떤 공격이든 성공하려면 반드시 병사들을 잘 먹이고 보급품을 충분히 지급해야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6257, 'koKR', '어떤 이들은 군대의 성공은 힘과 용기가 좌우한다고들 하는데, 그 말도 맞소! 하지만 군대를 제대로 유지하기 위해서는 보급품이 반드시 필요하지. 그런 보급품을 공급하는 게 바로 내 일이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6273, 'koKR', NULL, '어서 오십시오. 호드의 대의를 따르러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6274, 'koKR', NULL, '잘하셨습니다. 조금만 더 하면 이 우리에 호드의 기병대가 전투에 타고 나갈 늑대가 넘쳐날 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6275, 'koKR', '어서 오게. 새 무기 휘두르는 걸 배우려는 거면 아주 제대로 찾아온 거라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6276, 'koKR', '아, $n! 마침 자네 같은 이를 찾고 있던 중이었네! 이제 보급품이 충분히 모여서 호드에 맞설 지상 공격 부대를 출격시킬 수 있어! 투쟁의 벌판에서 테라베인 야전사령관이 명령서를 기다리고 있을 걸세.$B$B자네는 수 차례 자기 자신의 가치를 몸소 입증해 보인 노련한 용사이니 테라베인에게 명령서를 전달해 주지 않겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6277, 'koKR', '친구여, 어떤 무기를 배우고 싶나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6279, 'koKR', '무기 사용하는 법을 내 기꺼이 가르쳐 주겠소. 내가 통달한 꼭 그만큼 당신도 능숙하게 무기 다루는 법을 배우게 될 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6281, 'koKR', '더 배우기를 원한다면 누가 그대를 도와줄지 기꺼이 알려드리겠소. 그래, 어떤 무기가 그대의 관심을 끌었소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6282, 'koKR', '스톰파이크에 죽음을!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6284, 'koKR', '$n! 보급품이 점점 줄어들고 있어서 더 모으기 전에는 투쟁의 벌판에서 대규모 지상 공격을 펼칠 수가 없네!$B$B우리 병참장교와 얘기해 보게나. 우리 부대에 보급품을 보충하기 위해 자네가 할 수 있는 일이 뭔지 말해 줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6286, 'koKR', '새 무기 사용법을 배우러 온 거겠지? 내가 많이 바쁘니까 빨리 말해 보라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6287, 'koKR', '어떤 무기를 배우고 싶은지 알려 주면 어디로 가야 할지 가르쳐 주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6288, 'koKR', '$n, 자네처럼 노련한 이를 전장에서 보게 되다니 반갑네! 유감스럽게도 현재 우리는 보급품이 너무 적어서 호드에 대한 대규모 지상 공격을 펼칠 수 없는 상태라네.$B$B우리 병참장교와 얘기해 보게. 보급품 관련 임무를 줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6289, 'koKR', '무기를 들고 싸우는 전투 훈련을 받으려고 왔습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6290, 'koKR', '어떤 무기에 특별히 관심이 있으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6291, 'koKR', NULL, '싸울 때의 내 우아한 모습은 가르쳐 줄 수 있는 게 아니지만 여러 가지 무기를 다루는 법은 가르쳐 줄 수 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6292, 'koKR', NULL, '원한다면 다른 무기 전문가에게 가는 길을 안내해 드리겠습니다. 어떤 무기를 배우고 싶으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6293, 'koKR', '그러니까, 무기 다루는 법을 배우고 싶단 말이지? 거기 그렇게 바보같이 서 있지만 말고 대답 좀 크게 해 보라고, 젊은이!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6294, 'koKR', '어떤 무기가 배우고 싶어서 왔나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6295, 'koKR', NULL, '안녕하세요! 새 무기를 제대로 사용하는 기술을 배우러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6296, 'koKR', NULL, '저한테 훈련을 받고 싶지는 않나 보죠? 그래, 어떤 다른 무기에 눈길이 가던가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6313, 'koKR', '서리늑대 부족에게 죽음을!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6315, 'koKR', '나의 상관에게서 올 명령서를 기다리는 중이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6316, 'koKR', NULL, '우리 기병대가 움직이려면 알터랙 토종 산양이 꼭 필요해요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6317, 'koKR', NULL, '조금만 더 있으면 이 우리가 탈것으로 넘쳐나겠어요. 용맹한 얼라이언스의 병사여, 산양들은 이제부터 제가 잘 돌볼 테니 안심하시고 넘기세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6333, 'koKR', '만나서 반갑습니다, $n. 할 일이 굉장히 많으니 인사는 간단히 하도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6334, 'koKR', '$C|1이여;여;, 세나리우스께서 그대를 인도하시길.$B$B나는 세나리온 의회의 명을 받아 아주 중요한 임무를 수행하고자 자매들과 함께 이 타락한 땅에 왔네. 하지만 우리의 문제에 관해서는 좀 더 강한 자와 얘기를 나누고 싶군. 섣불리 약한 자를 보내는 것은 바보 같은 짓이니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6335, 'koKR', NULL, '저와 제 자매들은 오래전에 발생한 비극을 멈추기 위해 돌발톱 산맥에서 내려왔어요. 유감스럽게도 우리만으로는 그 목표를 달성할 만한 힘이 부족하기에 이제 당신과 같은 필사의 존재들에게 힘을 빌리게 된 거죠.$B$B당신에게 충분한 힘이 있다면 나누고 싶은 얘기가 너무나 많답니다, $c. 그렇지 않다면 당신 자신의 안전을 위해서라도 우리 임무에 대해 자세히 얘기하지 않겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6336, 'koKR', '어서 오라, $r|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6353, 'koKR', '내게 비록 고향이라고 부를 만한 곳은 없지만 이 세계에서 내가 설 자리가 있다는 것은 알고 있소. 언젠가 모든 부족들이 깨닫게 될 거요. 독수리가 먹다 남긴 찌꺼기... 불타는 군단이 득실거리는 이 땅을 두고 서로 싸우고들 있다니... 쳇!$B$B켄타우로스는 자신들의 혈통을 자랑스럽게 여겨야 하오. 나이트 엘프나 오크의 혈통만큼이나 고귀하니까 말이오. 이제 우리도 고귀한 혈통에 맞는 행동을 개시할 때가 됐소이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6354, 'koKR', '드디어, 이곳에 나를 묶어 놓았던 타락에서 벗어났구나...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6373, 'koKR', '$n, 날 구해 줘서 진정으로 고맙네.$B$B그 홀은 잘 간수하게나. 이곳에 침입한 악의 무리와 맞서 싸우는 데 도움이 될걸세...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6374, 'koKR', '어쩌다 이렇게 된 거지, $n? 셀레브라스의 홀 같은 물건이 하찮다고 생각한 건가?$B$B이번에는 도와주겠지만, 다시는 이렇게 귀중한 물건을 함부로 다루지 말게...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6375, 'koKR', '내 홀... 그렇게 오랜 세월 끝에... 자네가 되찾았군! 자네야말로 이곳의 진정한 구원자라 할 수 있겠군...$B$B내 말 잘 듣게나, $n. 홀의 머리 부분과 자루는 마라우돈의 돌에서만 다시 하나로 결합시킬 수 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6377, 'koKR', '색 사이로 길이 있어$B$B빛 가운데 지나가니$B$B물에서 그대가 나타나도다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6378, 'koKR', '마라우돈으로 통하는 문 근처에 있는 주황색 길과 보라색 길 사이에 세 번째 길이 보일 걸세.$B$B자네가 손에 들고 있는 그 홀이 바로 열쇠인 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6379, 'koKR', '피곤하게 하는군...$B$B여기서 폭포가 보일 텐데, 다시 마라우돈의 정문을 통과하고 싶다면 그 홀이 자네에게 바로 이곳까지 올 수 있는 힘을 부여해 줄 거란 말일세, $n.$B$B마라우돈의 입구 근처에 동굴 밑으로 통하는 길이 있으니 고대 의식 장소에서 홀을 사용해 차원문을 만들면 다시 여기로 오게 된다는 거지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6380, 'koKR', '오래전, 내 드리아드 자매들과 나는 내 숙부 재타르의 고통받는 영혼을 풀어 드리기 위해 이 동굴에 들어왔었네. 하지만 우리도 곧 이 동굴에 이미 퍼져 있던 타락에 제압돼 쓰러져 버렸지.$B$B우리는 이 길에서 방황할 운명을 맞게 되었고, 우리의 정신에는 독이 퍼지고 있었어...$B$B이제 내 영혼은 쉴 수 있게 됐지만 내 임무는 실패한 것이라는 걸 아네. 내가 짊어져야 할 큰 슬픔이지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6381, 'koKR', '아, 재타르 숙부... <고개를 돌리는 셀레브라스>$B$B우리 아버지 레물로스께서 재타르 숙부를 말리려고 하셨었지...$B$B고집 센 재타르 숙부가 대지의 정령 공주와 사랑에 빠졌을 때 우리 아버지께서는 그 사랑이 저주받은 것이라는 사실을 깨달으셨지만 재타르 숙부는 그 말을 들으려 하지 않았네.$B$B그 실수의 결과로 켄타우로스가 탄생한 것이지. 증오에 가득 차 기형으로 태어난 그 켄타우로스들의 손에 우리 재타르 숙부도 살해 당하셨네... 자신의 혈족의', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6383, 'koKR', '탐험가 연맹에 잘 왔네. 정보를 찾고 있는 거라면 내가 도와 줄 수 있을지도 모르지. 난 책에는 빠삭하니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6384, 'koKR', '마라우돈 안에 퍼져 있는 독이 내 정신에 스며들면서 나는 현실에 대한 감각을 잃어 가기 시작했네. 내 홀이 악한 목적에 사용될 것을 두려워한 내 드리아드 자매들은 내게서 홀을 빼앗아 두 조각 낸 다음 이 굴 속에 숨겨 두었지.$B$B그러나 곧 그들도 광기에 희생되었고 아무도 지키고 있지 않던 홀의 두 부분은 바일텅 녀석의 손에 들어가게 되었다네. 바일텅은 그중 하나는 녹시온이라는 사악한 정령에게 맡겼고, 나머지 하나는 지금까지 그가 지니고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6385, 'koKR', '군주 바일텅이 두 조각을 결합시키는 데 필요한 주문을 알지 못하니 그 홀을 사용할 수가 없었지. 하지만 이제 내가 바일텅의 타락의 저주로부터 해방됐으니 자네가 홀의 머리 부분과 자루 부분을 모두 가져오면 내가 자네를 도와 주도록 하겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6393, 'koKR', '레물로스와 재타르는 세나리우스의 아들들이라네.$B$B우리 아버지 레물로스는 강하고 뛰어난 분이셨고, 재타르 숙부는 매우 영리하고 늘씬한 신체를 지닌 분이셨지. 두 분 모두 똑같이 존경을 받았지만 재타르 숙부는 언제나 아버지가 자신보다 훨씬 더 큰 영광과 주목을 받고 있다고 생각했다네.$B$B나와 내 자매들이 태어난 후, 시기심에 눈이 먼 재타르 숙부는 자신의 형을 처치해 버리려 했고... 결국 자멸의 길을 걷고 말았지. 시간이 흘러도 그로 인한 내 슬픔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6413, 'koKR', '안녕하시오. 나는 호드 응급의학회 수석 군의관을 맡고 있는 의사 그레고리 빅터라고 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6414, 'koKR', '다시 보게 되어 반갑소. 그동안 지켜본 결과, 당신의 의술은 상당히 향상되었군. 이제 좀 더 어려운 고급 기술을 익힐 때가 되었다는 걸 알려주게 되어 상당히 기쁘오.$B$B지금처럼 기술이 향상될 즈음이면 때때로 이 몸을 찾아 주시오. 내가 알고 있는 모든 것을 천천히 당신에게 가르쳐 줄 작정이니까 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6415, 'koKR', '안녕하십니까! 나는 얼라이언스 응급의학회 수석 군의관을 맡고 있는 의사 구스타프 밴하우젠이라고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6433, 'koKR', NULL, '$n! 자네가 날 찾아와 다행이야. 우린 투쟁의 벌판에 대한 지상 공격을 펼칠 준비가 됐어! 전투대장 가르릭이 명령서를 받기만 하면 그의 부대가 얼라이언스를 싹 쓸어버릴 거야!$B$B$n, 이 명령서를 전달해 주지 않겠나? 가르릭이 투쟁의 벌판에서 기다리고 있을 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6435, 'koKR', NULL, '$n, 알터랙 계곡에서 자네처럼 노련한 용사를 만나게 돼서 반갑네. 우린 보급품이 너무 적어서 알터랙 계곡에 대한 지상 공격을 펼칠 수 없는 상태일세. 우리 병참장교와 얘기해 보게. 보급품 물량을 늘리는 방법을 가르쳐 줄 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6437, 'koKR', NULL, '이봐! $n! 그렇게 마을을 어슬렁거리고 다니면서 뭐 하는 거지? 지금 알터랙 계곡에 얼라이언스 놈들이 쳐들어왔단 말이야! 반드시 놈들을 몰아내야 해!$B$B그런데 보급품이 턱없이 모자라 대규모 지상 공격은 꿈도 못꾸니 이렇게 안타까울 데가... 서리늑대 병참장교와 얘기를 나눠 보게. 어떻게 하면 보급품을 늘릴 수 있는지 방법을 가르쳐 줄 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6475, 'koKR', '나는 서리늑대 부족의 신병 모집을 담당하고 있네. 서리늑대 부족의 일원이라면 계급이 오를 때마다 나를 찾아와야 하지.$B$B명예와 존경은 이렇게 혹독한 추위 속에서 얻을 수 있는 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6476, 'koKR', '어서 오시오, 용맹한 $r 친구! 나는 스톰파이크 경비대의 신병 모집을 담당하고 있는 부관 해거딘이라 하오.$B$B스톰파이크 경비대 내에서 신망과 명성을 얻으면 새 계급장을 달아줄 테니 날 찾아오도록 하시오. 만약 계급장을 잃어버리는 일이 생기면 새로 지급해 주도록 하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6491, 'koKR', '아직 네 때가 아니다. 산 자의 세계로 돌아가는 여정을 도와주지... 대가를 치른다면 말이다.', '당신은 아직 여기 올 때가 아닙니다. 다시 삶의 세계로 돌아갈 수 있도록 내가 도와드리겠습니다... 하지만 약간의 대가를 치러야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6513, 'koKR', '우리 선조들은 개개인의 힘도 강해야 하지만 힘을 합칠수록 더욱 안전하다고 가르치셨지. 길드를 조직해 썬더 블러프의 명예를 수호할 생각이 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6514, 'koKR', '아, 지도자의 면모를 갖춘 분이시로군요. 얼라이언스를 위해 싸울 길드를 조직하려고 여기를 찾으셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6520, 'koKR', '누락된 텍스트', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6533, 'koKR', '안녕하신가, $c. 나는 로카로라고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6534, 'koKR', NULL, '푸른용군단에 무슨 청을 하러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6535, 'koKR', '네싱워리 님께서는 큰 놈을 잡을 준비를 하고 계십니다. 사실 전 전투보다는 사냥 준비를 돕는 게 훨씬 더 마음 편하더군요... 가끔 전장의 영광스럽던 순간들이 그립긴 하지만 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6553, 'koKR', NULL, '전 이 숲을 제 몸의 한 부분처럼 속속들이 다 알고 있답니다. 하지만, 아직도 숲에는 배워야 할 것들이 더 많고 수많은 위험 또한 도사리고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6554, 'koKR', '그래, 돌아올 줄 알았어. 조금 전에 코라를 보냈는데 숲에 버려진 다르톨의 마법봉을 찾아왔더군.$B$B그걸 되찾느라 얼마나 고생했는데, $n. 다음부터는 그렇게 소중한 물건을 함부로 다루지 말아 줘.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6555, 'koKR', NULL, '당신은 테로니스의 임무를 완수해 주었군요. 임무를 완수하는 동안 해낸 모든 일에 감사드립니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6556, 'koKR', NULL, '안녕하세요! 지금 이 작업장의 주인은 제가 아니지만 언젠가 수련을 마치고 훌륭한 발명가가 될 거랍니다. 제 영웅이신 마본 리벳시커씨처럼 말이죠.$B$B들어본 적도 없다고요? 그럴 수도 있겠죠. 얼마 전 늘 말씀하시던 어느 고대 트롤의 유적지를 조사하러 떠났거든요. 비행선을 타고 갔는데... 정확히 어디로 갔는지는 잘 모르겠어요.$B$B타나라신? 텡케리스? 타네라니사니?$B$B<고개를 가로 흔드는 리브>$B$B아니, 그게 아닌데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6557, 'koKR', NULL, '안녕하세요. 애석하게도 마본씨는 여기 안 계세요. 앞으로 한동안은 돌아오지 않을 거예요. 사실 좀 걱정되기는 해요...$B$B빨리 오셨으면 좋겠어요. 마본씨 앞으로 웬 커다란 궤짝이 하나 왔는데 도저히 제 힘으로는 안으로 가져올 수가 없어서 밖에 문 옆에다 뒀답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6573, 'koKR', '당신은 이번에 내가 가르쳐 줄 수 있는 모든 것을 배웠습니다, 의사 양반. 당신의 기술이 발전했을 때 내게 돌아오면 내가 좀 더 고급의 응급치료 기술을 가르쳐 주도록 하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6574, 'koKR', NULL, '이곳은... 오염되었어요.$B$B전 간신히 탈출했지만 도저히 다시 굴을 통과해서 내려가질 못하겠네요.$B$B제 형제와 자매들은... 운이 좋지 못했답니다. 내부에 있는 덫 때문에, 그들은 그곳에 자라는 악마의 정원에서 흘러나온 타락한 기운이 깃든 안개로 제정신이 아니에요.$B$B당신이 우리를 도와줘야만 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6575, 'koKR', NULL, '오, $n! 당신이 돌아와서 무척 기쁘군요.$B$B제 형제의 영혼은 이제 오염에서 해방되었지만 전 애도의 뜻에서 이곳에 남기로 했습니다.$B$B당신의 도움에 깊이 감사드립니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6594, 'koKR', NULL, '보급품이 필요하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6595, 'koKR', '내가 가지고 있는 물건을 좀 볼 텐가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6654, 'koKR', '병법을 배우러 왔소, $r 친구? 그렇다면 잘못 찾아 왔구려.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6655, 'koKR', '이 땅에서 끊임없이 벌어진 승리와 패배의 교훈에 대해 배우러 왔소? 그런데 여기 승자는 없소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6657, 'koKR', '정신 바짝 차리시오, 제군! 스톰파이크 첩보부의 보고에 의하면 고블린 수석 기술자 하나가 겨울도끼 부족에게 포로로 끌려갔다고 하오. 그런데 서리늑대 놈들이 그를 구출해서 기계를 만들게 해 우리를 치려고 하고 있소! 그런 일이 절대로 일어나서는 안 되지...', NULL, '비밀결사대가 동부 고원 지대의 한 동굴에서 은밀히 움직이고 있다는 보고가 들어왔소. 제군, 녀석들이 무슨 수작을 부리려는 것인지 알아오시오! 가는 길에 서리늑대 부족을 조심하도록!', NULL, '서리늑대 부족의 영토에 들어갈 때는 조심하시오. 그 망할 곳은 온통 지뢰가 깔려 있소! 말 그대로 지뢰밭이란 말이오! 더 자세한 얘기는 최전선의 첫 번째 보초탑에 있는 우리 폭파전문가에게 가서 들으시오. 분명, 이 상황을 어떻게 해결할 것인지 가르쳐줄 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6658, 'koKR', '잘 들으시오, $c.$B$B나로부터 퍼져나가는 힘과 사기를 느낄 수 있소? 이미 당신도 충만해 보이는군. 하지만 적도 마찬가지일 거요. 적의 방어선을 붕괴하고 그들의 수를 줄이는 것은 쉬운 임무가 아니지만 반드시 해내야만 하오! 승리는 우리 것이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6659, 'koKR', '최전선에는 방어를 지휘하는 적의 부대장이 여섯이 있는데, 먼저 그들을 처치해야 하오! 사제들이 쓰러진 놈을 부활시키면 곤란해지니까 속전속결로 끝내 버리시오!$B$B순식간에 부대장을 모두 해치워버리면 최전선의 사기가 떨어지겠지! 전의를 상실한 부대원들은 겁에 질려 도망칠 테고, 그러면 나머지 병사들은 지원군도 없이 싸우다 비참한 죽음을 맞이할 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6694, 'koKR', '힘이 없다... 아무것도 할 수가 없다... 힘을 되찾아야 하노라... 제브림의 손에 있다... 이 고통을 끝내다오...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6695, 'koKR', '고맙구나, 필멸의 존재여. 꿈속으로 돌아가기 전에 네게 해줄 수 있는 게 딱 한 가지 있노라.$B$B제브림의 주인인 알진에게로 통하는 문이 너의 길을 가로막고 있으니 내가 그 문을 파괴할 수 있도록 도와주겠다. 명령만 내리거라. 그리하면 문이 열리리라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6714, 'koKR', '돌난로 무덤은 투쟁의 벌판에 있는 돌난로 전초기지 동쪽에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6718, 'koKR', '보급품이 좀 있긴 하지만 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6719, 'koKR', '$n, 투쟁의 벌판에 대한 지상 공격을 펼치는 데 필요한 보급품이 충분히 모아졌소. 공격명령서를 보내길 원하고 또 당신 계급이 충분히 높다고 생각한다면 서리늑대 마을에 있는 하사관 야즈라 블러드스날에게 가서 얘기를 나눠 보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6720, 'koKR', '보급품이 있긴 하지만 충분하지 않소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 있어야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6721, 'koKR', '보급품은 거의 다 떨어졌소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많은 보급품이 필요하오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6730, 'koKR', '$n, 우리에겐 지상 공격을 펼치는 데 필요한 보급품이 충분히 있소. 스톰파이크 경비대에서 지위가 충분히 높다면 하사관 노레그 스톰파이크와 얘기해 보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6731, 'koKR', '여분의 보급품이 많이 있긴 하지만 투쟁의 벌판으로 공격 부대를 보내려면아직 더 많이 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6732, 'koKR', '여분의 보급품이 있긴 하지만 많지는 않소. 투쟁의 벌판으로 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 필요하다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6733, 'koKR', '여분의 보급품이 거의 없소. 투쟁의 벌판으로 다른 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 노력해야 할 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6735, 'koKR', '우리 부대가 승급하려면 보급품이 더 많이 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6736, 'koKR', '우리 부대가 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6737, 'koKR', '정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6741, 'koKR', '으으... 저 잡초들 때문에 밤낮으로 눈코 뜰 새가 없으니, 원! 당신도 보셨죠?$B$B그냥 수도관 같은 걸 타고 이 녀석들에게 멀리 좀 도망갔으면 좋겠다니까...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6742, 'koKR', '이건 특수 장비야! 함부로 만지지 말고, 자네가 좋아한다는 그 독한 럼주를 너무 마셨다면 절대 작동시키려 하지도 마.$B$B그러고 보니... 그 고약한 술 혹시 조금 갖고 있진 않나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6755, 'koKR', '무슨 일인가, $c 양반?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6775, 'koKR', '최정예 부대로 승급하는 데 필요한 보급품이 절반 정도 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6777, 'koKR', '우리 부대가 승급하려면 보급품이 더 많이 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6778, 'koKR', '우리 부대가 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6779, 'koKR', '정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6780, 'koKR', '우리 부대가 승급하려면 보급품이 더 많이 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6781, 'koKR', '정예 부대로 승급하는 데 필요한 보급품이 절반 정도 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6783, 'koKR', '최정예 부대로 승급하는 데 필요한 보급품이 절반 정도 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6784, 'koKR', '승급하는 데 필요한 보급품이 거의 없소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6785, 'koKR', '우리 부대는 아직 아무런 승급도 되지 않았소. 현재 보급품이 부족해 승급할 수 없소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6786, 'koKR', '우리 부대는 상급 부대로 승급했소. 하지만 정예 부대로 승급하기에는 보급품이 부족하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6787, 'koKR', '우리 부대는 정예 부대로 승급했소. 하지만 최정예 부대로 승급하기에는 보급품이 부족하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6788, 'koKR', '상급 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6789, 'koKR', '정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', '우리 병력을 정예병으로 승급시킬 보급품은 충분히 확보했습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6790, 'koKR', '최정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6791, 'koKR', '더 이상 보급품을 저장할 수 없소. 보관할 공간이 바닥났단 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6793, 'koKR', '당신의 기술이 저보다 뛰어나군요. 무법항에 있는 헤밍이라는 노인이 \"고급 낚시정보\"라는 책을 가지고 있답니다. 분명 그 책이라면 당신에게 도움이 될 겁니다.', '당신의 기술이 저보다 뛰어나군요. 무법항에 있는 헤밍이라는 노인이 \"고급 낚시정보\"라는 책을 가지고 있답니다. 분명 그 책이라면 당신에게 도움이 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6794, 'koKR', '당신의 기술이 저보다 뛰어나군요. 무법항에 있는 헤밍이라는 노인이 \"고급 낚시정보\"라는 책을 가지고 있답니다. 분명 그 책이라면 당신에게 도움이 될 겁니다.', '당신의 기술이 저보다 뛰어나군요. 무법항에 있는 헤밍이라는 노인이 \"고급 낚시정보\"라는 책을 가지고 있답니다. 분명 그 책이라면 당신에게 도움이 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6795, 'koKR', '저 너머에 부서진 함정이 보이나? 오우거들은 너무 멍청해서 부서진 함정을 고칠 생각은 꿈에도 못하지. 분명히 수선 작업이 필요하단 말이야. 함정을 고치면, 오우거 경비병 슬립킥을 그쪽으로 꾀어내어 사로잡을 수 있다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6796, 'koKR', '알터랙에는 두 개의 광산이 있습니다. 얼라이언스 영토인 깊은무쇠 광산과 호드 영토인 얼음이빨 광산이지요. 이 두 광산은 풍부한 자원의 보고이며 오래전부터 풍부한 보급품들이 비축된 것으로 알려져 있습니다.$B$B현재 이 광산을 차지하기 위해 호드와 얼라이언스는 물론 인근에 사는 생명체들까지 끊임없는 전투를 벌이고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6797, 'koKR', '알터랙 계곡에서 보초탑과 참호는 전술적으로 아주 중요한 곳입니다. 우리가 보초탑을 점령하면 아주 멀리 있는 곳까지 공격할 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6798, 'koKR', '알터랙 계곡의 무덤은 망자들의 영혼이 휴식을 취하고 구원을 받는 곳입니다. 만약 당신이 장렬히 전사하면 그 영혼은 우리가 점령한 무덤 중 가장 가까운 곳으로 이동할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6799, 'koKR', '스톰파이크 보급기지는 던 발다르 병영 바로 외곽인 던 발다르에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6805, 'koKR', '눈사태 무덤은 겨울도끼 요새에서 동쪽, 투쟁의 벌판 언덕 꼭대기에 있습니다.$B$B아무도 이곳을 점령하지 않았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6807, 'koKR', '서리늑대 구호막사는 서리늑대 보초탑의 남쪽, 서리늑대 요새에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6810, 'koKR', '얼음피 무덤은 얼음피 보초탑에서 동쪽, 투쟁의 벌판 남쪽에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6812, 'koKR', '$r 동지여, 참혹하도록 황폐해진 이 벌판을 보고 파괴적인 정령의 힘을 잘 새겨두십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6813, 'koKR', '남부 던 발다르 참호는 던 발다르의 동쪽과 남쪽 측면을 방어합니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6816, 'koKR', '북부 던 발다르 참호는 던 발다르로 진입하는 동쪽 입구를 방어합니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6819, 'koKR', '얼음날개 참호는 얼라이언스 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6822, 'koKR', '돌난로 참호는 투쟁의 벌판 동쪽 측면을 방어합니다.$B$B현재는 얼라이언스가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6826, 'koKR', '서부 서리늑대 보초탑은 서리늑대 마을과 서리늑대 요새 사이의 관문을 방어합니다.$B$B현재 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6829, 'koKR', '동부 거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재는 호드가 점령하고 있습니다. 동부 서리늑대 보초탑은 서리늑대 마을과 서리늑대 요새 사이의 관문을 방어합니다.$B$B현재는 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6832, 'koKR', '거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B현재 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(6833, 'koKR', '거점 보초탑은 남쪽의 호드 영토와 투쟁의 벌판 사이에 통로를 확보하고 있습니다.$B$B아무도 이곳을 점령하지 않았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6835, 'koKR', '얼음피 보초탑은 남동쪽으로부터 얼음피 주둔지를 방어합니다.$B$B현재 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6838, 'koKR', '서부 서리늑대 보초탑은 서리늑대 마을과 서리늑대 요새 사이의 성문을 방어합니다.$B$B현재는 호드가 점령하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6842, 'koKR', '$r|1이여;여;, 이제부터 내 말을 잘 듣고 배우도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6843, 'koKR', '아주 오래전, 찬탈자들이 훗날 창세기라 부르던 시대에, 내 주인님과 그 형제들은 이 세상을 지배했습니다. 그들이 바로 이 세상을 창조한 고대 신들이셨지요.$B$B하지만, 결국 고대 신들은 창조주라고 자칭하던 놈들에 의해 밀려나고 말았답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6844, 'koKR', '기나긴 전투를 치르면서 고대 신들의 육체는 점점 쇠약해져 자신들이 손수 창조한 세계의 지하에 갇히게 되었고, 티탄 창조주의 타락이 온 지상에 퍼지면서 고대 신들을 욕되게 했습니다.$B$B바로 그때 주인님의 형제들이 배반을 하여, 오천 년 동안 이 세계의 심장부에서 전쟁이 일어난 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6846, 'koKR', '호드와 얼라이언스 양 진영의 부대장들이 모두 전선에 나섰습니다. 우리의 발린다 스톤하스 부대장님께서는 돌난로 전초기지에서 스톰파이크 경비대를 지휘하고, 적군의 갈반가르 부대장은 얼음피 주둔지에서 명령을 내리고 있습니다.$B$B진격하십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6848, 'koKR', '호드와 얼라이언스 양 진영의 부대장이 모두 전선에 나섰습니다. 우리 갈반가르 부대장께서는 얼음피 주둔지에서 서리늑대 부족을 지휘하고 있고, 그의 경쟁자인 발린다 스톤하스 부대장은 돌난로 전초기지에서 숨어 있습니다.$B$B전쟁이 시작된 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6851, 'koKR', '갈반가르 부대장께서 전사하셨습니다! 쓰러진 갈반가르 님의 뜻을 받들어 얼라이언스를 공격하십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6853, 'koKR', '알터랙 계곡은 오랜 세월 동안 서리늑대 부족의 고향이었습니다. 절대 드워프 놈들과 얼라이언스가 차지하게 둘 순 없어요! 전쟁을 벌여야 합니다!$B$B던 발다르에 있는 반다르 스톰파이크 사령관을 처치하면 알터랙 계곡은 우리 것이 되는 겁니다.$B$B호드를 위하여!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6854, 'koKR', '스톰파이크 경비대가 알터랙 계곡에서 고대 유물을 발굴했는데, 서리늑대 부족 오크 녀석들이 탐험가를 싫어해서 말입니다. 드워프족이 자신들의 선조가 남긴 지식을 위해 싸워야만 할 운명이라면 그렇게 해야겠지요!$B$B이 전투에서 승리하려면 서리늑대 요새에 있는 오크족의 사령관인 드렉타르를 처치해야 합니다. 운명의 여신이 함께하길 빕니다, 영예로운 얼라이언스의 $C|1이여;여;!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6859, 'koKR', '발린다 스톤하스 부대장은 투쟁의 벌판 북쪽에 있는 돌난로 전초기지를 본거지로 최전선에서 얼라이언스 군을 지휘하고 있습니다.$B$B발린다 부대장은 현재 돌난로 전초기지에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6861, 'koKR', '드렉타르는 서리늑대 부족의 군사적, 정신적 지도자로서 서리늑대 요새에서 군을 지휘합니다.$B$B그를 처치하면 알터랙의 호드군은 무너질 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6863, 'koKR', '갈반가르 부대장은 드렉타르가 신뢰하는 부하입니다. 투쟁의 벌판 남부에 있는 얼음피 주둔지에서 호드를 지휘하고 있지요. $B$B갈반가르 부대장은 현재 얼음피 주둔지에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6865, 'koKR', '반다르 스톰파이크 님은 알터랙에 주둔하고 있는 얼라이언스 군대의 사령관이시며, 던 발다르에서 군을 지휘하십니다.$B$B반다르 님이 쓰러지면 얼라이언스 군대는 알터랙 전투에서 패배할 것입니다.$B$B반다르 님은 현재 알터랙 계곡에 계시지 않습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6867, 'koKR', '정령계에 대전쟁이 벌어지던 시기에 불의 군주 라그나로스가 저의 주인이자 바람의 왕자이신 썬더란을 소멸시키려 했습니다.$B$B<분노로 얼굴이 일그러지며 고개를 떨구는 데미트리안>$B$B놈의 이름을 입 밖에도 내지 마십시오. 화가 치밀어 당신의 이빨로 이 황폐한 야영지를 장식해버릴지도 모르니까 말입니다. 조용히 듣기만 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6868, 'koKR', '주인님을 배신한 것은 라그나로스의 부관인 게돈과 가르였습니다. 썬더란께서는 영문도 모르고 변을 당하셨습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6869, 'koKR', '썬더란께서는 불의 군주가 다가오는 것을 전혀 모르고 계셨기 때문에 손쓸 겨를도 없이 라그나로스의 전설적인 망치인 설퍼라스에 의해 무자비하게 당하고 말았습니다. 썬더란께서는 참패를 당해 쓰러지셨지요.$B$B불의 군주가 탐욕스럽게 주인님의 정기를 빨아들였지만 그분을 완전히 소멸시키지는 못했습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6870, 'koKR', '라그나로스는 썬더란 님의 남은 정기를 정령을 봉인하는 부적에 넣은 다음 완벽하게 이등분했습니다. 그러곤 그 조각들을 자기 부관에게 나누어 주었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6871, 'koKR', '던 발다르는 알터랙 계곡에서 얼라이언스의 위력이 가장 강한 지역입니다. 계곡의 북쪽에 자리 잡고 있는 던 발다르는 남쪽으로 진격하기 위한 중간 거점이라고 할 수 있습니다.$B$B던 발다르는 안전합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6873, 'koKR', '서리늑대 요새는 알터랙 계곡의 남쪽 구석에 자리하고 있으며, 오크족의 고향인 서리늑대 마을을 방어하고 있습니다. 알터랙 계곡의 모든 호드 영토는 이곳을 거점으로 뻗어나갑니다.$B$B서리늑대 요새는 안전합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6875, 'koKR', '열쇠를 찾았다고? 정말 그 열쇠가 맞아? 그러니까 이 족쇄를 풀 수 있는 열쇠냐는 말이지. 뭐, 한번 해보면 알 수 있겠지만!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6876, 'koKR', '너 이제 왕이다! 왕이야! 모두 고르독 왕인 $n 폐하에게 경례!$B$B너 이제 왕 됐으니까 부하들이 공물 바칠 거야! 왕, 몇 놈이나 살려뒀지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6877, 'koKR', '나랑 놀이 하나 할래, 말썽꾼 양반?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6878, 'koKR', '난 자유의 땅으로 통하는 열쇠를 갖고 있지롱! 나 잡아봐! 그럼 무슨 소린지 알게 될 거야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6879, 'koKR', '아직도 살아있네? 신기해라! 도망가는 내 꽁지나 구경해라!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6880, 'koKR', '그렇게 울상만 짓지 말고 좀 웃어봐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6881, 'koKR', '다 끝났어. 너랑 친구 안 할래!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6882, 'koKR', '음, 당신이 왕 죽였지? 그럼 당신이 왕 자리를 차지하는 거지. 새 왕이 되는 거라고! 왕 만세!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6883, 'koKR', '내가 저 멍청이들의 밥이 되길 기다리다 알아낸 바로는... 여기 오우거를 다 처치할 필요는 없다는 거지.$B$B그제는 오우거들이 고르독 왕이 즉위한 것에 대해서 하루종일 수다를 떨더라고. 자세히 들어보니까, 고르독이 이전 왕을 죽이고 그 자리를 차지했다지 뭐야. 그리고 그 이전 왕의 부하들, 그러니까 고르독이 살려둔 부하들은 즉시 새 왕에게 충성의 맹세를 했다네.$B$B그러니까 혹시 알아? 당신이 살려둔 오우거가 훗날 당신에게 충성을 맹세할지... 말하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6894, 'koKR', '당신 새 왕이지? 새 왕 만세!$B$B이 크리그 고르독 술 보게 해 준다. 술 하면 오우거 술, 오우거 술 하면 고르독 술! 나한테서 좀 살 생각 없어, 왕?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6895, 'koKR', '왕! 좋아, 부하들에게서 공물을 받을 준비가 되면 내게 알려주라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6896, 'koKR', NULL, '이방인이여, 이곳을 떠나세요. 그렇지 않으면 그대도 다른 이들처럼 재가 되어버릴 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6897, 'koKR', NULL, '명가에 대해 아시나요? 셴드랄라는요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6898, 'koKR', NULL, '셴드랄라는 아즈샤라 여왕의 가장 신임받는 비전술사였어요. 온통 성벽으로 둘러싸인 바로 이곳에서 여왕이 맡긴 중요한 일들을 비밀리에 처리했지요.$B$B영원의 샘이 파괴되고 그로 인해 나이트 엘프 명가를 비롯한 모든 계층이 권태에 빠지자 엘드레탈라스의 왕자 토르텔드린은 서쪽 전당에 흩어져 있는 수정탑들을 짓기 시작했답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6899, 'koKR', NULL, '토르텔드린 왕자는 거대한 마법진 안에 어마어마한 힘을 가진 악마를 가두려는 계획을 세웠지요. 그 마법진은 수정탑들이 전달하는 눈에 보이지 않는 어떤 마력에 의해 작동하는 것 같았어요.$B$B이몰타르는 그 안에 갇혀 있는 동안 엘드레탈라스 주민들에게 힘의 원천이 되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6900, 'koKR', NULL, '마법진이 이몰타르에게서 흡수한 힘이 명가의 마력을 유지시켜 주었고, 엘드레탈라스 성벽 안에 사는 이들이 갖고 있는 마법에 대한 끝없는 갈망을 충족시켜 주었습니다.$B$B그런데, 수천 년이 지나면서 엘드레탈라스의 생명력을 유지하면서 이몰타르를 가두어 두는 데 필요한 마력이 필요하게 됐어요. 이몰타르를 가두어 둠으로써 얻는 힘보다 그를 가두는 데 더 많은 마력이 필요해진 것이죠. 즉, 흑자에서 적자로 바뀐 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6901, 'koKR', NULL, '사실, 엘드레탈라스의 마당과 전당을 배회하고 있는 명가의 영혼들은 고르독 오우거나 사티로스의 침략으로 살해된 것이 아닙니다. 바로 토르텔드린 왕자에게 죽임을 당한 것이지요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6902, 'koKR', NULL, '토르텔드린 왕자는 불멸의 삶과 무한한 힘을 위해 주민들을 살해했습니다. 한 때는 수천 명이 함께 나누던 마력을 이제는 토르텔드린 왕자와 셴드랄라 광신도들이 독점하고 있지요. 소수의 생존자들이 이몰타르를 계속 가두어 놓기 위해 수정탑에 직접 마력을 불어넣고 있습니다.$B$B그 악마가 풀려나기라도 한다면 한때는 위대한 비전술의 보루였던 이곳의 유적들은 완전히 파괴될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6903, 'koKR', '이제 네가 왕이야! 위대한 고르독의 멍멍이!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6904, 'koKR', '펜구스가 너 거칠게 만들어 주지! 미친 것처럼! 크아악!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6905, 'koKR', '왕이 제대로 이겨버렸네?! 어떻게 슬립킥을 속였담?? 하지만 슬립킥은 똑똑하니까 다음번엔 어림없어! 하하!$B$B이제 아무도 슬립킥 못 속여. 슬립킥 약속해!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6906, 'koKR', '왕, 나 얼마나 똑똑한지 보여주지! 이제 왕은 강력한 마법 모조로 더욱 똑똑해질 거야!$B$B엄... 어쩌면 마법을 슬립킥한테 써 볼까? 그것 참 좋은 생각이네...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6907, 'koKR', '고르독의 왕이시여! 진정한 고르독의 일인자로군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6908, 'koKR', '너 죽었다고 들었는데... 이렇게 하면 쉽게 죽지 않을 거다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6909, 'koKR', '나는 일만 년 동안이나 이 왕국을 다스려왔습니다. 그동안 셴드랄라 가문의 신성한 땅을 밟은 자들에게서 흥미로운 이야기를 많이 들었지요.$B$B여기 매인 몸인지라 이곳을 찾는 이들을 통해 바깥세상의 이야기를 듣는 것입니다. 그대는 내게 들려주러 오셨나요? 아니면 내 이야기를 듣고자 오셨습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6911, 'koKR', '주인님의 노여움을 살 생각은 마십시오. 한 번 노하시면 상상을 초월할 만큼 잔인해지신답니다.', '주인님의 노여움을 살 생각은 마십시오. 한 번 노하시면 상상을 초월할 만큼 잔인해지신답니다.', '이방인이여, 목소리를 낮추십시오. 주인님의 명상을 방해하지 않는 게 좋을 겁니다.', '이방인이여, 목소리를 낮추십시오. 주인님의 명상을 방해하지 않는 게 좋을 겁니다.', '이 성소를 찾아온 자들은 많지만 성한 몸으로 떠난 자는 별로 없지요.', '이 성소를 찾아온 자들은 많지만 성한 몸으로 떠난 자는 별로 없지요.', '그 현자는 고대에서부터 존재했으며 우리의 여왕님을 받들어 영예로운 임무를 맡아왔소!', '그 현자는 고대에서부터 존재했으며 우리의 여왕님을 받들어 영예로운 임무를 맡아왔소!', '최근 들어 책이 계속 분실되고 있소. 현자들과 그 조수들이 크게 분노하고 있소이다. 엘드레탈라스 내의 누군가가 배신행위를 저지르고 있는 것이 아닌가 의심들을 하고 있소.', '최근 들어 책이 계속 분실되고 있습니다. 현자들과 그 조수들이 크게 분노하고 있습니다. 엘드레탈라스 내의 누군가가 배신행위를 저지르고 있는 것이 아닌가 의심들을 하고 있지요.', '토르텔드린 왕자께서 파멸의 인도자에 대한 얘기를 들려 주셨소? 그분의 이야기 중에서 우리가 제일 좋아하는 얘기지. 그분이 제일 좋아하시는 건 파멸의 인도자의 다음 얘기요. 물론 아무도 그분에게서 그 이야기를 듣진 못했소이다.', '토르텔드린 왕자께서 파멸의 인도자 얘기를 들려 주셨습니까? 그분의 이야기 중에서 우리가 제일 좋아하는 얘기지요. 그분이 제일 좋아하시는 건 파멸의 인도자의 다음 얘기랍니다. 물론 아무도 그분에게서 그 이야기를 듣진 못했지만요.', '내 생각엔 임프들이 책을 훔치고 있는 것 아닌가 싶소이다.', '내 생각엔 임프들이 책을 훔치고 있는 것 아닌가 싶습니다.', '주인님께서는 네파리안의 소굴에 큰 관심을 갖고 계시오. 누군가가 네파리안과 그 졸개들을 처치하고 그 무용담을 왕자님께 들려 드리기만 한다면 왕자님도 틀림없이 흔쾌히 말해 주실 거요. 파멸의 인도자를 찾을 수 있을지도 모른단 말이오!', '주인님께서는 네파리안의 소굴에 큰 관심을 보이고 계십니다. 누군가가 네파리안과 그 졸개들을 처치하고 그 무용담을 왕자님께 들려 드리기만 한다면 왕자님도 틀림없이 흔쾌히 말해 주실 겁니다. 파멸의 인도자를 찾을 수 있을지도 모른단 말입니다!'),
(6913, 'koKR', '여기서 왜 어슬렁대는 거냐? 저 녀석들한테 왜 족쇄 채우지 않았지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6914, 'koKR', '이제 당신이 왕이야! 모두 고르독의 새 왕에게 경례!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6915, 'koKR', '아직도 녀석들 무기를 들고 있는 것 같은데? 어째서 무기를 그대로 지니고 있게 한 거냐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6916, 'koKR', '전부 왕의 부하다. 천둥발 크리그, 경비병 셋, 크롬크러쉬 대장, 그리고 정찰병이 새 왕에게 공물 바친다. 부하를 죽이면 공물 못 받는다! 부하 한 놈씩 살려둘 때마다 공물을 더 받는다. 모두 살려두면 아주 큰 공물 받을 거다!$B$B암, 그렇고말고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6917, 'koKR', NULL, '맙소사! 이런 비극이! 거의 다 됐는데 모든 걸 잃어버릴 수 있다니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6918, 'koKR', '어... 때려서 미안! 왕, 나 죽이지 마, 제발... 알았지!? 이제 네가 왕이니까 내가 더 좋은 공물 받게 돕는다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6919, 'koKR', '유해를 대충 조사해보니 살갗이 불에 타서 떨어져 나간 것 같습니다. 아주 소름끼치는 광경입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6920, 'koKR', '음... 당신이라면 이전 왕하고 달리 기분 나쁜 명가의 왕자에게서 귀중한 고르독 유물 되찾을 수 있을지도 모르겠군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6922, 'koKR', '새로운 왕 만세!', NULL, '어... 그러니까 너 새로운 왕이 되기 전에 째려본 건... 그냥 장난이었는데?$B$B정말이다, 왕!', NULL, '왕을 공격하다니, 다른 오우거들은 바보야! 그래서 내가 아직 살아 있는 거야, 난 똑똑하니까!', NULL, '우리 타나리스에 있는 오우거보다 훨씬 깨끗해. 저 넓은 사막에서 눈에 보이는 거라곤 오우거 똥뿐이니... 여기서는 절대 안 그렇지, 왕!', NULL, '여기서 우리랑 머무는 한 네가 왕이지. 딴 데로 가버리면 다른 오우거가 왕 자리를 차지한다. 그게 고르독의 방식이거든!', NULL, '나 진짜 천재야, 천재!', NULL, '옛날 왕이 죽었어? 어, 그럴 리가!', NULL, '나 아무 말썽 안 부린다, 왕.', NULL),
(6923, 'koKR', '미즐하고 얘기 안 하면 왕 못 돼! 약삭빠른 미즐하고 얘기를 해 봐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6924, 'koKR', '그러니까... 당신이 왕을 해치운 모양이군. 그 얼간이들이 당신을 새 왕으로 삼을 줄 알았다니까, 진짜! 그 멍청이들이 아는 거라고는 힘밖에 없거든.$B$B부하들을 많이 살려 둘수록 공물도 그만큼 많이 들어올 테니, 그것도 괜찮지. 재미있는 과제랄까... 당신이 떠나면 아마 왕 노릇은 계속 못 할 거야. 분명 그 촌뜨기 녀석들 중 하나가 나서서 당신 자리를 차지할 테니까.$B$B참, 혹시 내 열쇠 못 봤나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6925, 'koKR', '당신이 한 가지 알아두어야 할 것은 1만 년 동안의 삶을 기록할 수 있다 보니 삶에 대해서 좀 독특한 관점을 갖게 되더라는 거요. 오늘날 당신의 고난과 시련은 무의미하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6926, 'koKR', '어린 주인님께서 얼마나 야단법석을 하시던지... 꼭 세계의 운명을 그대로 어깨에 짊어지기라도 하신 것 같았을 것이오. 우리 세계에 대해 그런 비뚤어진 관점을 가질 수 있는 건 평범한 필멸의 생명체들뿐이지.$B$B안타깝게도 주인님이 남겨 주신 거라곤 이 빈약한 마법 비밀뿐이라오... 고서나 말도 안 되는 것들뿐이지. 나한테는 이런 시시한 마법이 필요 없지만 당신이라면 흥미가 있을지도 모르겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6927, 'koKR', '책을 도둑맞았소, $r 친구! 우리가 가장 귀중히 여기는 책 세 권을 말이오. 그 책들을 되찾아주면 반드시 보상을 해 주리다.', '도둑맞았소, $r! 가장 귀한 고서 세 권을 말이오. 책을 찾아오면 반드시 보상하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6929, 'koKR', '이 두루마리에 적힌 방대한 분량의 기술적인 내용은 무슨 말인지 전혀 이해할 수가 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6930, 'koKR', '이 두루마리에는 야전수리로봇의 설계도가 그려져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6931, 'koKR', '복잡한 이 설계도의 내용을 이해하기에는 기계공학 숙련도나 지식이 부족합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6932, 'koKR', '이미 이 로봇의 제작 방법과 기능에 대해 잘 알고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6933, 'koKR', '이 세계를 구성하는 구조물은 아주 섬세하기 때문에 약간의 지식을 응용하는 것만으로도 상처를 낼 수 있답니다. 그리해서 균열이 생겨나는 것이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6934, 'koKR', '적을 똑바로 응시하게, $r 친구. 가장 막강하다는 용들마저 호드의 힘 앞에서 얼마나 보잘것없는가! 우리에게 맞서는 모든 이들이 똑같은 운명을 맞이할 것이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6935, 'koKR', '우리는 호드다. 타우렌, 오크, 트롤, 그 외 모든 종족 모두 다! 우리가 함께란 사실을 절대로 잊지 마라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6936, 'koKR', '국왕 폐하를 위해 이 한 목숨 바칠 따름이노라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6937, 'koKR', '아마 그대들도 언젠가는 오늘의 영웅들처럼 얼라이언스를 위해 위대한 공헌을 하게 될 것이다. 영웅들에게 경의를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6938, 'koKR', '찾아 주다니 영광일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6939, 'koKR', '1만 년간의 기록된 지식이 모여 있다 보니 도서관에 쓸데없는 것들이 몰려오곤 한다니까. 책을 도난당하고, 회수하고, 다시 도난당하고 하는 건 매일 있는 일이라오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6940, 'koKR', NULL, '킬드라스는 상황을 너무 부풀리는 경향이 있단 말이죠. 예를 들자면 \"가로나: 은신과 기만에 대한 연구\"는 400번 넘게 도난당했던 책이랍니다.$B$B책에는 도서관의 낙인이 있어서 허락 없이 아무나 읽을 수 없지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6947, 'koKR', '바쁘니까 방해하지 말게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6948, 'koKR', '내가 도와 줄 일이라도 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6949, 'koKR', '그렇소. 하지만 내가 아는 그곳의 진짜 이름은 바로 엘드레탈라스요. 아주 오래전 나이트 엘프들의 마법을 간직한 보루였던 곳이지.$B$B엘드레탈라스에 대해 들어본 적 있으시오? 지금 내가 처한 상황과 우연히 맞아떨어진다고 할 수도 있겠지만... 나는 우연 같은 걸 믿지 않아서 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6950, 'koKR', '세나리온 의회의 요원들이 엘드레탈라스의 현재 상황과 관련해 우려할 만한 정보를 알아냈소. 벼랑 끝에 매달린 상황이라 분명 힘깨나 쓰는 이들의 도움이 필요할 테지.$B$B하지만, 엘드레탈라스에서 제대로 행동을 취하려면 풍요의 열매라고 알려진 물건에 대해서 잘 알아 둬야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6951, 'koKR', '아주 오래전, 엘드레탈라스는 마법의 집합소였고 그 성스러운 전당 안에 사는 자들은 모두 엄청난 힘을 소유하고 있었소. 그중 밀리센트 세레네라는 나이트 엘프가 있었는데, 자연의 힘을 자유자재로 부여해 강력한 물건을 만들어 내는 식물학자였지.$B$B그녀의 업적 중 으뜸가는 것이 바로 풍요의 열매였소... 보호와 성장의 오라를 불어넣은 희귀하고 생기 넘치는 덩굴을 특별히 준비한 달샘에다 길렀는데, 엘드레탈라스 전체가 그 덩굴로 우거졌었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6952, 'koKR', '안타깝게도, 세상 일이 늘 그런 것 같소이다. 나를 비롯한 세나리온 의회의 다른 이들도 모두 고대의 전쟁 중에 밀리의 덩굴이 파괴되었을 거라 추측했었지... 이제야 알게 된 사실이지만 전혀 그렇지 않았던 거요.$B$B풍요의 열매는 살아남았소... 이제는 악령덩굴이라 불리고 있지만... 엘드레탈라스에 거처하는 칼날바람 알진이라는 악마 군주에 의해 타락하고 있었던 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6953, 'koKR', '상... 상상조차 할 수 없소, $n. 확실한 건 그런 일이 발생하도록 내버려둬서는 안 된다는 사실이오. 그 덩굴을 반드시 파괴해야 하오. 악마의 타락으로부터 우리 자신을 보호하기 위해서가 아니더라도 밀리센트 세레네를 기리기 위해서... 밀리...$B$B바로 그대가 도와 줬으면 하는 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6954, 'koKR', '<털썩 무릎을 꿇는 데미트리안>$B$B당신이 우리 주인님을 가둔 끝없는 감옥을 찾아내셨습니다!$B$B아! 그토록 오랜 세월을 기다려온 꿈이 드디어 현실로 다가왔군요.$B$B반드시 주인님을 풀어드려야 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6955, 'koKR', '저에게 그분이 환생할 수 있는 결정이 있습니다. 이 임무를 맡을 각오가 되었다면 결정을 강하게 만드십시오. 궁극적으로 라그나로스의 마수로부터 벗어나야 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6956, 'koKR', '환생의 관은 반드시 엘레멘티움으로 강화해야 합니다. 그런데 그 광석이 나는 곳은 바로 우리 세계의 중심부에 있는 정령계, 한 군데뿐이지요.$B$B그토록 귀한 물건을 구하는 일이라면 저보다 대지창조자가 더 잘 알 테니 꼭 대지창조자를 찾으십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6957, 'koKR', '영웅이시어, 안녕하십니까! 양쪽의 대륙은 물론 다른 지역에서 온 최근 소식이 있는데 아마 관심이 있을 겁니다.', '영웅이시어, 안녕하십니까! 양쪽의 대륙은 물론 다른 지역에서 온 최근 소식이 있는데 아마 관심이 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6958, 'koKR', '라그나로스의 육신을 파괴하십시오. 그의 시체에서 정수가 나타날 것입니다. 그렇게 라그나로스가 약해지면 썬더란을 감옥에 가둬 놓는 힘도 느슨해 지겠지요. 정수가 바로 열쇠 역할을 하는 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6959, 'koKR', '지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 것일세.', '지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 것일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6960, 'koKR', '지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 겁니다.', '지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6961, 'koKR', '제가 낚시 기술을 가르쳐 드릴 수 있습니다.', '제가 낚시 기술을 가르쳐 드릴 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6974, 'koKR', '저습지에 있는 메네실 항구 북쪽의 푸른아가미 습지대로 가보게. 난파된 배에서 뭍으로 떠내려온 금고들이 잔뜩 있을 걸세. 물이 빠지고 나니 드러났지 뭔가.', '저습지에 있는 메네실 항구 북쪽의 푸른아가미 습지대로 가보게. 난파된 배에서 뭍으로 떠내려온 금고들이 잔뜩 있을 걸세. 물이 빠지고 나니 드러났지 뭔가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6975, 'koKR', '잊혀진 땅의 북쪽 살데리스 해안 수역이나 황야의 땅에 있는 고통의 요새로 가면 자물쇠 따는 연습을 할만한 잠겨진 금고들이 있을 겁니다.', '잊혀진 땅의 북쪽 살데리스 해안 수역이나 황야의 땅에 있는 고통의 요새로 가면 자물쇠 따는 연습을 할만한 잠겨진 금고들이 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6976, 'koKR', '슬픔의 늪에 있는 눈물의 연못에 가면 오랜 세월 방치되어 있던 고대의 금고들을 찾을 수 있을 겁니다.', '슬픔의 늪에 있는 눈물의 연못에 가면 오랜 세월 방치되어 있던 고대의 금고들을 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6977, 'koKR', '이글거리는 협곡의 잿가루 채석장에 있는 검은무쇠 드워프들이 잠겨진 금고를 잔뜩 갖고 있습니다.', '이글거리는 협곡의 잿가루 채석장에 있는 검은무쇠 드워프들이 잠겨진 금고를 잔뜩 갖고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6978, 'koKR', '타나리스의 해적단 소굴과 아즈샤라에 있는 폭풍의 만에 자물쇠 따기 연습을 하기에 좋은 금고들이 있습니다.', '타나리스의 해적단 소굴과 아즈샤라에 있는 폭풍의 만에 자물쇠 따기 연습을 하기에 좋은 금고들이 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6979, 'koKR', '동부 역병지대에 있는 티르의 손 수도원에 가면 자물쇠 따는 연습을 하기에 좋은 금고들이 많이 있을 겁니다.', '동부 역병지대에 있는 티르의 손 수도원에 가면 자물쇠 따는 연습을 하기에 좋은 금고들이 많이 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6980, 'koKR', '붉은마루 산맥에 있는 영원고요 호수로 가보시오. 오크들의 보급품이 든 금고가 여러 개 가라앉아 있소.', '붉은마루 산맥에 있는 영원고요 호수로 가보시오. 오크들의 보급품이 든 금고가 여러 개 가라앉아 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6981, 'koKR', '나가들이 잿빛 골짜기에 있는 조람 해안을 점령했을 때 보급품을 담은 많은 금고들이 분실되었습니다.', '나가들이 잿빛 골짜기에 있는 조람 해안을 점령했을 때 보급품을 담은 많은 금고들이 분실되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6982, 'koKR', '투자개발회사는 돌발톱 요새에 있는 칼바람 바위산에 자신들의 물품을 금고에 넣어 보관하고 있으니 그리로 가 보시오.', '투자개발회사는 돌발톱 요새에 있는 칼바람 바위산에 자신들의 물품을 금고에 넣어 보관하고 있으니 그리로 가 보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6983, 'koKR', '언덕마루의 던홀드 요새에 비밀결사대의 보급품을 넣은 금고가 많이 있소이다.', '언덕마루의 던홀드 요새에 비밀결사대의 보급품을 넣은 금고가 많이 있소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6984, 'koKR', '<소리 내어 껄껄 웃는 데미트리안>$B$B이 바보 녀석!너에게 내릴 보상은 빠르고도 고통스러운 죽음뿐이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6985, 'koKR', '전 이 세계에 이미 알려진 원소들은 물론 미지의 원소들도 연구합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6986, 'koKR', '엘레멘티움이라고? 수십 년 동안 필멸자의 입에서 그 말을 듣지 못했는데.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6987, 'koKR', '크릭시스라는 내 옛 제자가 평생을 지하 세계에 사슬로 묶인 신들과 접촉하려 애썼다. 그는 황폐해진 대지에서 솟아나는 것... 원소들이 거대한 충돌을 일으킬 때만 만들어지는 것을 좇았지.$B$B필멸자들은 그것을 엘레멘티움이라 부른다.$B$B거의 10년 전 어느 날, 크릭시스의 집착은 바로 이 협곡에 균열을 만들어 냈다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6988, 'koKR', '그래, 불가능하다고 여겼던 일을 해냈지. 균열에서 테라제인의 사절이 튀어나왔어!$B$B내가 있던 곳에서는 고블린이 고대 신의 사절과 이야기를 나누는 게 보였지. 그 뒤에 벌어진 일은 끔찍했다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6989, 'koKR', '균열이 닫히자 크릭시스가 사라졌다! 통째로 삼켜진 거야!$B$B명심해라, $r. 네가 바라는 것이 가장 원치 않는 결과가 될 수도 있다. 넌 시간 그 자체보다 오래된 존재와 비전의 힘을 건드리고 있어!$B$B크릭시스가 살아 있고 네가 찾는 정보를 알고 있다 해도, 순순히 내놓을 거라 생각하지 마라. 그자는 네가 상상할 수 있는 것보다 훨씬 끔찍한 공포를 이미 겪은 자니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6990, 'koKR', '살다 보면 우리가 아는 삶이란 것이 아주 실망스러울 때가 있습니다. 어딘가에 갇혀서 해답을 갈구하다가 어둠 속에서 타오르는 희망을 찾게 되지요.$B$B그때에서야 비로소 자유를 향한 첫 걸음을 떼게 되는 겁니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6991, 'koKR', '거미나 딱정벌레 좀 있나, $c 친구? 녀석들이 날쌔긴 하지만 몸을 조금만 더 빨리 움직여서 잡아보라고! 아주 별미라는 걸 알게 될 테니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6992, 'koKR', '혹시 방금 던전에서 나오셨나요? 그럼, 저한테 줄 선물은 뭐 없어요?', NULL, '전 이 다음에 커서 스톰윈드의 국왕이 될 거예요!', NULL, '전에 아이언포지에 한번 가봤는데요... 퀴퀴하고 이상한 냄새가 났어요.', NULL, '버섯은 다 축축한 곳에서 자라니까 우산처럼 생겼나 봐요.', NULL, '멜빵 바지는 위에 달린 멜빵으로 바지를 올려 입는 건데 허리띠 넣는 구멍은 왜 있어요?', NULL, '콧구멍 안에서 코딱지가 얼어붙으면 어떻게 돼요?', '물고기도 목말라 해요?', '물고기도 목이 마를까?', '실패하려고 마음먹은 것에 성공했다면 성공한 건가요, 실패한 건가요?', '실패하려고 했는데 성공했다면, 결국 뭘 한 거지?', NULL),
(6993, 'koKR', '아이, 무서워! 그 방어구 보니까 정말 겁나요... $g형:누나;, 무서운 분이에요?', NULL, '$g형이:누나가; 진짜 호드의 영웅이라면 용하고 싸우는 걸 얼른 보여줘요!', NULL, '바다에 벼락이 떨어지면 어째서 물고기들이 다 죽지 않죠?', NULL, '날개 없는 파리들을 벼룩이라고 부르나요?', NULL, '코 속에 돌이 낀 것 같아요.', NULL, '거북이가 등껍질이 없으면 집을 잃은 건가요, 아니면 옷을 잃은 건가요?', NULL, '그런데 \"저그 저그\"가 무슨 뜻이에요?', NULL, '장갑이 너무 큰데도 \'손에 딱 맞는 장갑\'이라고 할 수 있을까?', NULL),
(6995, 'koKR', '아주 멀리서 왔군, $r 친구.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6996, 'koKR', '날 용케도 찾았구려. 내게 억제와 지배에 대해 배우려고 온 거겠지.$B$B그보다 더 많은 기술도 가르쳐주리다... 희생에 대해서도 가르쳐주겠단 말이오.$B$B<씩 웃는 다이오.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6997, 'koKR', '그건 당신이 소환해서 부하로 만들기를 원하는 악마의 종류에 따라 다르다오. 우리는 암흑의 마력을 이용하고 그에 따른 큰 대가를 치러야 하는 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6998, 'koKR', '뭔가를 해 보려면 먼저 그 악마를 가두어 둘 감옥을 만들어야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7001, 'koKR', '어서 내 앞에 엎드려 머리를 조아리지 못할까, 이 벌레 같은 것! 네까짓 것의 힘은 내 손아귀 안에 있다는 걸 모르겠느냐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7002, 'koKR', '이 나이비에게서 황천으로부터 지옥불정령을 소환하는 비결을 배우고 싶은 거로군.$B$B아무 말 하지 마! 이 나이비는 모든 걸 알고 있으니까!$B$B하지만, 그런 지식을 쉽게 전수할 만큼 이 나이비가 호락호락하진 않아. 먼저 나를 도와 아주 중요한 임무를 하나 수행하도록!', '그래, 황천에서 지옥불정령 종을 불러내는 비밀을 배우려고 니비를 찾아왔군.$B$B조용! 니비는 다 알아!$B$B하지만 니비는 그런 지식을 쉽게 알려 주지 않아. 먼저 아주 중요한 일을 도와줘야 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7003, 'koKR', '이 야영지에서 북동쪽으로 가면 크로쉬우스라는 지옥불정령이 하나 쓰러져 있지. 이 나이비가 여기 온 이유도 바로 그 녀석 때문이야. 크로쉬우스는 상급 지옥불정령으로 예상보다 오래 버텼어. 원래 지옥불정령이란 게 주인을 섬기기 위해 강렬한 힘으로 땅 위에 떨어지지만 그 힘은 아주 빨리 시들거든. 화염이 꺼지면 지옥불정령도 힘을 잃고 재가 되어 부서지는 거야.', '이 야영지 북동쪽에 크로시우스라는 강력한 지옥불정령이 있다. 니비가 여기 온 이유도 그거야. 크로시우스는 일반 지옥불정령보다 훨씬 오래 버틴 상급 개체다. 잘 봐, 풋내기. 지옥불정령은 엄청난 힘으로 대지에 떨어져 주인을 섬기지만 그 힘은 금방 사라져. 타오르는 불꽃이 꺼지고 나면 몸도 부서지고 말지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7004, 'koKR', '어리석은 것! 이 나이비의 말을 함부로 가로막지 마라. 네 살가죽을 벗긴 다음 뼈다귀를 옷걸이로 써버릴 수도 있다. 그런데... 어디까지 말했더라? 아, 그래. 그러니까 이 크로쉬우스란 놈은 평범한 지옥불정령보다 열 배는 더 오래 버텼다는 말이야. 어떻게 그럴 수 있는지는 모르겠지만 자세히 조사하면 분명 알아낼 수 있을 거야.$B$B가서 크로쉬우스의 지옥핵을 가져 오도록.', '니비 말 끊지 마, 멍청아! 네 살을 뼈에서 벗겨 내고 그 해골을 옷걸이로 써 버릴 거다. 어디까지 했더라? 아, 그래. 크로시우스는 보통 지옥불정령보다 거의 열 배나 오래 버텼어. 이유는 모르지만 충분히 연구하면 알아낼 수 있을 거라 확신하지.$B$B크로시우스의 지옥불정령 핵이 필요하다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7005, 'koKR', '지옥불정령 하수인을 소환하는 비결을 알고 싶으면 먼저 크로쉬우스를 처치하고 불타버린 그의 잔해에서 지옥핵을 가져 와야 해. 그게 말처럼 쉬운 일은 아니겠지만... 크로쉬우스는 이미 완전히 타버렸을 테니 그의 잔해에 다시 불을 지펴 잿더미가 된 다시 살려야 하거든. 그렇게 하려면 다른 악마적 존재로부터 어떤 재료를 모아야 해.$B$B저기 있는 내 부하 임프시가 더 자세히 가르쳐줄 거야.', '지옥불정령 종을 소환하는 비밀을 배우고 싶다면 크로시우스를 파괴하고 타버린 잔해에서 지옥불정령 핵을 가져와야 한다. 하지만 말처럼 쉽진 않아. 크로시우스는 거의 완전히 타버렸거든. 시체에 다시 불을 붙여 잔해 속에서 일으켜 세워야 해. 그러려면 다른 악마들에게서 몇 가지 재료를 모아야 하지.$B$B내 임프 임프시가 시작할 길을 알려 줄 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7010, 'koKR', NULL, '전쟁에는 희생이 따르죠... 시간이 지나면 묻혀버리고 마는 희생이요. 그러한 희생이 바로 고아들이랍니다. 아제로스 전역에서 너무나 빈번하게 발생하는 충돌로 인해 부모를 잃은 불쌍한 아이들이죠. 기댈 곳이 없는 아이들은 이곳에 와서 혼자 살아갈 수 있는 나이가 될 때까지 지낸답니다.$B$B우리 호드는 봄이 오면 일주일 동안 시간을 내서 이 무고한 아이들에게 뭔가를 해주는 행사를 벌이는데, 이 주간을 바로 어린이 주간이라고 해요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7011, 'koKR', NULL, '전쟁에는 희생이 따르지요... 가끔 그냥 묻혀버리고 마는 희생이요. 그러한 희생이 바로 고아들이랍니다. 아제로스 전역에서 너무나 빈번하게 일어나는 충돌로 말미암아 부모를 잃은 아이들이죠. 기댈 곳이 없는 아이들은 이곳에 와서 혼자 살아갈 수 있는 나이가 될 때까지 지낸답니다.$B$B얼라이언스에서는 봄이 오면 일주일 동안 시간을 내어 이 무고한 아이들에게 아이들이 원하는 뭔가를 해주는 행사를 벌이는데, 이 주간을 어린이 주간이라고 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7012, 'koKR', NULL, '그렇군요... 그대는 참 친절하군요. 어린이 주간 동안 자원봉사를 하는 모양이지요. 정말 칭찬받을 만한 일이 아닐 수 없네요. 우리 모두 전쟁으로 불우해진 이웃들, 특히 어린이들을 꼭 기억해야 해요.$B$B기꺼이 서명해 드리지요. 자, 받으세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7013, 'koKR', '어서 오게, 젊은 친구... 썬더 블러프에 온 걸 환영하네. 이곳에서는 세상 짐을 벗어버리고 편안하게 쉴 수 있을 걸세. 호드의 일원이라면 누구나 환영이지.$B$B이 성스러운 곳에서는 현재와 과거의 영혼들이 다시 살아난다네. 그들에게 예를 갖추게. 그리고 자기 자신에게 예를 갖추는 것도 잊지 말게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7014, 'koKR', '아, 어린이 전사의 부탁인 게로군! 그대도 어린이 주간 중 자원봉사를 하고 있는 모양이지? 솔선수범해서 다른 이들에게 좋은 본보기가 되고 있다니 나의 시린 무릎이 다 따뜻해지는구나.$B$B그대와 그 어린 소년의 부탁을 기꺼이 들어주겠다. 흠... 그런데 그 아이에게 어떤 조언을 해주는 게 좋을까? 영혼의 소리에 귀를 기울이거라? 그래... 편식하지 말고 반찬을 골고루 먹거라... 특히 채소를 말이지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7015, 'koKR', '호그럴을 찾고 계시다고 했습니까? 그럼 선술집부터 들르셨어야죠. 허허! 도적을, 그것도 드워프 도적을 찾는다면 맥주가 있는 여관부터 찾아봐야 할 겁니다. 어서 가서 찾아보십시오.', '호그럴을 찾고 계시다고 했습니까? 그럼 선술집부터 들르셨어야죠. 허허! 도적을, 그것도 드워프 도적을 찾는다면 맥주가 있는 여관부터 찾아봐야 할 겁니다. 어서 가서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7016, 'koKR', '실바람 산장에 있는 샨드리나를 찾아가 보십시오. \"고급 요리책\"을 팔고 있을 겁니다.', '실바람 산장에 있는 샨드리나를 찾아가 보십시오. \"고급 요리책\"을 팔고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7017, 'koKR', '요리라면 가젯잔의 더지 퀵클레이브가 달인입니다. 요리 솜씨를 늘리려면 그자를 찾아가야 할 겁니다.', '요리라면 가젯잔의 더지 퀵클레이브가 달인입니다. 요리 솜씨를 늘리려면 그자를 찾아가야 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7019, 'koKR', '그늘수렵 마을에 있는 울란이 \"고급 요리책\"을 팔고 있소. 요리 솜씨를 늘리려면 그 책이 필요할 것이오.', '그늘수렵 마을에 있는 울란이 \"고급 요리책\"을 팔고 있소. 요리 솜씨를 늘리려면 그 책이 필요할 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7021, 'koKR', '제가 요리를 가르쳐 드리죠!', '제가 요리를 가르쳐 드리죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7024, 'koKR', '이제 당신의 기술을 키워줄 수 있는 자는 유명한 그레고리 빅터 의사밖에 없소이다. 아라시 고원에 있는 망치 주둔지에 가면 그 친구를 찾을 수 있을 것이오.', '이제 당신의 기술을 키워줄 수 있는 자는 유명한 그레고리 빅터 의사밖에 없소이다. 아라시 고원에 있는 망치 주둔지에 가면 그 친구를 찾을 수 있을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7025, 'koKR', '먼지진흙 습지대의 담쟁이 마을에 있는 발라이 로크웨인이 당신의 기술을 향상시키는 데 필요한 서적을 팔고 있소.', '먼지진흙 습지대의 담쟁이 마을에 있는 발라이 로크웨인이 당신의 기술을 향상시키는 데 필요한 서적을 팔고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7026, 'koKR', '응급치료 기술을 더 배우고 싶다면 존경받는 의사 구스타프 밴하우젠을 찾아가 보십시오. 테라모어 병영에서 부상자를 치료하고 있을 겁니다.', '응급치료 기술을 더 배우고 싶다면 존경받는 의사 구스타프 밴하우젠을 찾아가 보십시오. 테라모어 병영에서 부상자를 치료하고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7027, 'koKR', '듣자 하니 스트롬가드에 틀어박혀 지내는 데네브 워커에게 응급치료 기술을 뚜렷이 향상시킬 서적이 있다고 합니다.', '듣자 하니 스트롬가드에 틀어박혀 지내는 데네브 워커에게 응급치료 기술을 뚜렷이 향상시킬 서적이 있다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7028, 'koKR', '응급치료 기술을 가르쳐 드리죠.', '응급치료 기술을 가르쳐 드리죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7029, 'koKR', NULL, '빛을 찬양하라, 응답이 드디어 이루어졌군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7030, 'koKR', NULL, '<고개를 끄덕이는 에리스>$B$B어둠의 눈은 수많은 공포와 기적을 보아왔어요.$B$B어둠의 눈은 그것을 들여다보고 있는 자에게 가장 적합하다고 느끼는 것을 보여주죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7031, 'koKR', NULL, '그래요. 어둠의 눈은 틀리는 일이 없답니다.$B$B결국 그대는 $g사제:여사제;인 거예요. 어둠의 눈이 이런 끔찍한 기억을 보여주었다면 그대는 강력한 힘을 지닌 $g사제:여사제;인 것이랍니다.$B$B그대는 구원 때문에 이곳에 왔음에도 정작 자신은 그것을 깨닫지 못하고 있어요. 그렇죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7032, 'koKR', NULL, '그럴 거라 믿어요, $N.$B$B저 역시 사제였지만 당신과 달리 이미 오래전에 이 세상을 떠났습니다. 그래도 제 영혼은 이곳에 남아 있지요. 미친 왕자 아서스 메네실과 그의 언데드 군단에게 무참히 살해된 수천 명의 영혼과 함께 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7033, 'koKR', NULL, '나는 그대 자신이 구원받기 위해 여기 온 거라고는 말하지 않았습니다. 그대는 나와 스트라솔름에서 탈출하려다 살해당한 무고한 이들을 구원하러 온 거예요.$B$B내 영혼과 길 잃은 영혼들은 이곳에 구속되어 끊임없이 우리의 비극적인 죽음을 되풀이하고 있어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7034, 'koKR', NULL, '내가 할 수 없었던 일을 해야 합니다. 스트라솔름에서 탈출하려다 살해당한 인부들을 구해야 해요.$B$B그들은 빛을 향해 나아갈 겁니다. 그대는 그들이 살아남을 수 있도록 지켜줘야 해요. 너무 많은 이들이 쓰러진다면 우리의 저주받은 삶은 계속될 겁니다. 그런 일이 벌어지면 그대는 실패하게 될 겁니다.$B$B그대가 지금까지 터득한 모든 기술과 주문, 마법을 시험받을 거예요. 빛의 가호가 있기를 빌겠어요, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7036, 'koKR', '공포마의 영혼이 격노하여 요동칩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7037, 'koKR', '제데나르의 방식은 어둡고 믿을 수 없는 것이오. $C|1이여;여;, 당신의 움직임 하나하나에 주의하시오. 자칫하면 적에게 영혼을 빼앗길 수 있으니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7038, 'koKR', '썩 꺼져! 나는 공포의 군주님들과 우리의 계획을 함께 상의하는 몸이시고 우리가 의논하는 내용은 네가 신경 쓸 바 아니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7039, 'koKR', '...베인할로우 님이 내게? 무슨 얘기지? 그분의 훌륭한 조언가이자 신하인 이 울라텍을 필요로 하시나? 나더러 오라고 하시는 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7040, 'koKR', '뭐? 하지만 어떻게? 아냐! 그럴 리가 없어! 그렇게 주의를 했는데... 알 수 있을 리가 없잖아!$B$B네 말은 거짓이다! 거짓말로 속이려 들다니 죽여 주마!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7041, 'koKR', NULL, '살아 있다는 게 감사히 느껴지는 멋진 날이로군요! 친구여, 주위에 펼쳐진 아름다운 광경을 한번 보세요. 삶이 우리에게 준 선물을 즐기자고요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7042, 'koKR', '*그르르르* *멍* *멍*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7043, 'koKR', '용암? 그런 것에는 신경 쓸 것 없습니다, 친구여... 주위 경관을 둘러보며 자연이 주는 기쁨을 있는 그대로 받아들이세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7044, 'koKR', '전 매년 이맘때쯤 실리더스를 찾습니다. 발가락 물집에는 이런 날씨가 아주 딱이거든요.$B$B저랑 산책이나 합시다, 친구. 멋진 경치와 이것저것 구경해보자고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7045, 'koKR', '이렇게 외진 곳에서 친구를 만나게 되다니 정말 반갑군. 자, 함께 걸어보세. 서로 체온을 나누면 몸도 따뜻해지고 좋지 않나?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7046, 'koKR', '힘의 골짜기 서쪽 높은 곳을 찾아보게.', '힘의 골짜기 서쪽 높은 곳을 찾아보게.', '전설의 전당을 찾는군. 힘의 골짜기에서 서쪽으로 높은 곳에 있다네.', '전설의 전당을 찾는군. 힘의 골짜기에서 서쪽으로 높은 곳에 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7047, 'koKR', '갑자기 \'얼라이언스의 수호자\'라도 되기로 결심하신 겁니까?! 아무래도 구 시가지 안에 용사의 전당으로 가보셔야겠군요.', '갑자기 \'얼라이언스의 수호자\'라도 되기로 결심하신 겁니까?! 아무래도 구 시가지 안에 용사의 전당으로 가보셔야겠군요.', '아, 진급이라도 하시는 모양인가요?! 용사의 전당으로 가보십시오. 구 시가지의 남동쪽 끝에서 찾을 수 있을 겁니다. 장교라면 전당 안으로 들어갈 수 있고, 장교가 아니더라도 밖에 서 있는 아레인 장교와 얘기를 나눌 수 있지요. 좋은 하루 되세요!', '아, 진급이라도 하시는 모양인가요?! 용사의 전당으로 가보십시오. 구 시가지의 남동쪽 끝에서 찾을 수 있을 겁니다. 장교라면 전당 안으로 들어갈 수 있고, 장교가 아니더라도 밖에 서 있는 아레인 장교와 얘기를 나눌 수 있지요. 좋은 하루 되세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7055, 'koKR', '최고의 솜씨를 가진 장인을 찾아다닌 것이라면 제대로 오셨소!$B$B그리만트 엘모어라고 하오. 뭐든지 주문만 하시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7056, 'koKR', '공포마를 소환하려면 먼저 대소환진을 만들어야 합니다. 소로스로 가는 차원문을 그 안에서만 열 수 있기 때문이지요.$B$B대소환진을 만들려면 세 가지 강력한 도구가 필요합니다. 데스무라의 종, 어둠의 물레, 심판의 양초가 바로 그것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7057, 'koKR', '준비가 다 됐군요. 지금 그대와 그대의 공포마 앞에 놓인 일은 대소환진과 공포마의 영혼을 봉인하기 위한 의식입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7074, 'koKR', '아! 투기장에서 사람들이 죽을 때까지 싸우는 것을 보는 것보다 좋은 건 없지. 자네가 제때에 여기 있다면 아마도 그중 하나가 될 수 있을 거라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7094, 'koKR', '그래, 맞아. 나는 장님이나 다름없지! 또 그... 뭐냐... 어쨌든 뭣처럼 취했다고.$B$B한 가지 알려 주지, $c. 내 감각이 날카로운 건 술 덕분이라고. 한 가지 감각을 잃으면 나머지 감각들이 더 날카로워진다는 건 상식이라니까. 내 취각이 요즘 들어 아주 기막히게 좋아졌어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7095, 'koKR', NULL, '우리는 세계를 착취... 아... 아니... 그러니까 탐험하고자 검은바위 나락의 보호와 안락함을 떠나기로 했답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7114, 'koKR', '아무래도 여기다 가게를 차린 건 좋은 생각이 아니었나 봐...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7115, 'koKR', '난 대장장이인 버니네이트라네. 어... 그리고... 약간의 음식과 음료 등을 파는 일을 부업으로 하고 있지. 고기 좀 들지 않겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7116, 'koKR', '다시 만나 반갑습니다, $n! 제가 얼마나 더 오랫동안 이런 외딴 곳에 작업장을 세우려는 작업을 계속해 나갈지는 모르겠습니다. 그래도 전에 도와 주신 적이 있으니 관심을 가지실 만한 물건을 좀 보여 드리죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7117, 'koKR', '롤로가 자신의 소중한 에일 맥주를 흘리거나 옷을 더럽히고 싶어하지 않을 때면 내가 등장하지. 암, 그렇고 말고. 정의를 실현하고 누군가를 응징해야 할 때는 이 노병 한셀을 부른다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7120, 'koKR', '이곳의 현역 작업반장으로서 이곳에서 일어나는 모든 형태의 사업, 노동, 휴식, 그리고 휴식에 일정 수준의 지루함이 포함되도록 하는 게 내 임무라네.$B$B자네에게 부탁한 일이 너무 쉽고 간단하다고 생각되면 즉시 내게 보고하라고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7121, 'koKR', '내가 부탁한 일을 모두 끝냈으니 정말 이곳에서는 더 이상 자네에게 맡길 일이 없네. 토륨 대장조합의 요원으로 계속 일할 의향이 있으면, 검은바위 나락에 있는 험상궂은 주정뱅이 선술집에서 로크토스 다크바게이너와 얘기해 보게나.$B$B살펴가게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7122, 'koKR', NULL, '토륨 대장조합이든 아니든, 검은무쇠 드워프 녀석들이 가까이 오기만 하면 내 곡괭이로 혼내 줄 거예요! 어머, 제가 말이 많았네요. 자, 어디로 보내 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7123, 'koKR', NULL, '저 드워프들이 저쪽에서만 지낸다면 문제는 없을 거야. 그런데 어디로 가려는가, $n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7134, 'koKR', '강력한 $n의 군대 앞에 내가 두려워 움츠러들기라도 할 줄 알았더냐?$B$B넌 나에게 하찮은 존재일 뿐이다. 아니, 그 이하지.$B$B너도 모든 평범한 생명체들이 저지르는 것과 똑같은 실수를 저지른 것이니라.$B$B<한숨을 쉬는 군주 빅터 네파리우스>$B$B시간은 시간을 돈의 형태로 사용하는 자들에게 이상한 짓을 저지르지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7154, 'koKR', '보주의 표면에 커다란 인간의 손자국이 새겨져 있습니다. 끊임없는 조작과 처리에 시달려 보이지만 보주는 전혀 손상되지 않았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7155, 'koKR', '보주에 있는 표시가 손에 찍힌 낙인과 일치합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7156, 'koKR', '나... 나는 실패하고 말았다, $n. 검은... 검은바위의 군주는 너무나도 강하다. 간단히 내 마력을... 소진시켜 버리더군. 난... 날... 죽여라... 네가... 날 죽여야 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7174, 'koKR', '나는 저들의 감시자이자 복수의 주먹... 저항 세력을 진압하는 자이니라. 감히 이 대군주에게 덤빌 자가 누구냐? 나의 무자비한 심판에 맞설 자가 누구란 말이더냐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7175, 'koKR', '지금 낚시하고 있는 게 안 보이시오!', NULL, '당신 때문에 물고기가 겁나서 도망갔잖소! 원하는 게 뭐요?', NULL, '무슨 일로 왔소, $c 친구?', NULL, '난 34Kg짜리 농어를 잡을 때까지는 여기 있을 참이오! 당신은 어디 다른 곳으로 가고 싶은 것이겠지... 그렇지 않소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7176, 'koKR', '이 쓰러진 용을 보게, $r 친구. 호드의 강한 힘은 의심의 여지가 없지 않나?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7177, 'koKR', '성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴로 이루어져 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장이신 스랄 님께서 불타는 칼날단의 존재를 아시지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망 때문에 그들을 멸하지 않기로 했다고 믿고 있습니다.', '성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴들로 구성되어 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장이신 스랄 님께서 불타는 칼날단의 존재를 아시지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망 때문에 그들을 멸하지 않기로 했다고 믿고 있습니다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7178, 'koKR', '검은바위의 군주가 죽었다는 증거가 홍예문 위에 걸려 있다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7179, 'koKR', '이곳에는 볼 것이 없으니 어서 가십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7180, 'koKR', '이 던전들 중 하나를 골라 탐험해 보시겠습니까?', '이 던전들 중 하나를 골라 탐험해 보시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7181, 'koKR', '여기에 설계도로 보이는 종이 뭉치가 흩어져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7182, 'koKR', '이 종이들을 지키고 있는 자가 있습니다. 자멕과 대화하여 그의 주의를 분산시키십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7183, 'koKR', '최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거로 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 소문에 따르면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀', '최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거로 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 소문에 따르면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7185, 'koKR', '달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 \'그림자송곳니 성채\'라는 새로운 이름으로', '달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 \'그림자송곳니 성채\'라는 새로운 이름으로', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7186, 'koKR', NULL, '안녕하세요! 검은창 부족의 존경과 호의를 얻고 싶다면 가난한 이들에게 귀한 자원을 기부하는 걸로 시작해 보십시오! 옷감이나 붕대가 하늘에서 뚝 떨어질 수는 없으니까요.$B$B모험을 하시면서 다양한 옷감을 구하실 텐데... 그냥 팔아버리는 것보다 좋은 일에 쓰는 건 어떻습니까?! 검은창 부족으로부터 인정도 받고 말입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7187, 'koKR', '한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 달빛시내 마을에 있다고 하더군요.', '한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 달빛시내 마을에 있다고 하더군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7188, 'koKR', NULL, '이런 어려운 시기에는 옷감 같은 단순한 걸 기부하는 일만으로도 형편이 어려운 이들에겐 큰 힘이 되지. 붕대나 옷을 만들 수 있는 옷감이야말로 전시에 아주 중요한 물건이고 말고!$B$B오그리마의 오크족에게 옷감을 기부할 생각이 있다면 기꺼이 받겠어. 그리고 자네도 마땅한 대우와 인정을 받을 수 있을 거야.$B$B호드를 위하여!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7189, 'koKR', '요즘처럼 힘든 전시에 포세이큰을 돕는 게 자네에게도 큰 득이 될 걸세. 난 같은 말을 되풀이하는 걸 좋아하지 않으니 잘 듣게나.$B$B지금 우린 옷감이 몹시 부족한 상태라 붕대와 옷을 만들 수 없다네... 그래서 줄어만 가는 재고를 채우기 위해 기부를 받고 있네. 착한 일을 했다고 금전적인 보상을 바라지는 말게나. 기부란 원래 그런 거니까 말이야. 그렇다고 자네의 도움을 완전히 무시하겠다는 얘기는 아니라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7190, 'koKR', '안녕하십니까! 잠깐 제 얘길 좀 들어주십시오.$B$B우리 타우렌족은 고향 땅을 일으켜 세우기 위해 많은 고난과 시련을 겪어 왔습니다. 그러다 보니 지금 옷감이 많이 부족하군요. 혹시 여분이 좀 있다면 기부를 부탁드려도 될까요? 나를 도우면 어디에서든지 타우렌 종족의 감사와 존경을 받게 될 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7191, 'koKR', '성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다.', '성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7192, 'koKR', '통곡의 동굴 입구는 불모의 땅에 있는 십자로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다.', '통곡의 동굴 입구는 불모의 땅에 있는 십자로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7193, 'koKR', '안녕하시오, 친구여... 괜찮다면 잠시 시간을 내서 이야기를 들어주시오.$B$B우린 텔드랏실을 일으켜 세우는 데 많은 고난과 시련을 겪어 왔소. 계속되는 고난으로도 모자라 이제는 옷감까지 부족하구려. 혹시라도 여분이 있다면 부디 기부해 주시오. 우리를 도와 주면 어디서든 나이트 엘프의 친구로 대접받게 될 것이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7194, 'koKR', '우린 놈리건에서 떠날 수밖에 없었던 사태 때보다 훨씬 더 큰 곤경에 빠져 있어요! 좀 도와 주지 않을래요? 옷감이 모자라요!$B$B재고를 보충할 여분의 옷감이 있거든 좀 가져오세요. 남는 옷감을 기부하면 어딜 가나 우리 노움들의 신뢰와 존경을 받게 될 거예요. 그건 돈으로도 살 수 없는... 결국 옷감으로 사는 게 되겠지만, 지금 그게 중요한 게 아니니까...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7195, 'koKR', NULL, '안녕하세요! 아이언포지 드워프들의 존경을 한몸에 받고 싶다면 귀중한 물건을 기부하는 선행으로 시작해 보십시오! 아이언포지에서는 붕대나 옷을 만들 옷감이 턱없이 모자라요. 그런 귀한 물건들이 하늘에서 뚝 떨어지는 게 아니니까요!$B$B당신 같은 모험가라면 세상 곳곳을 여행하면서 다양한 옷감을 모으시겠죠?! 그냥 팔아 버리기보다는 기부를 통해 뜻 깊은 일에 쓰시는 게 어떠신가요?! 아이언포지 드워프 주민들의 존경과 인정을 받을 수도 있고 말이죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7196, 'koKR', '스톰윈드의 친구여, 스톰윈드에서는 당신의 도움과 관대한 마음을 필요로 하고 있습니다!$B$B한때 그 많던 옷감 재고가 위태로울 정도로 바닥나 버렸습니다. 스톰윈드에서는 옷감과 붕대 생산을 위해 그 재고량을 다시 보충하기 위해 여러 각도의 노력을 기울이고 있습니다! 옷감을 기부하면 스톰윈드에 큰 도움이 될 뿐만 아니라 시민들의 존경도 받게 될 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7197, 'koKR', '그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다.', '그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7198, 'koKR', '영광을 구하며 돌진하던 너는 만사가 네 행동에 의해 좌우된다고 믿었지. 나 같은 존재에게는 그게 얼마나 터무니없어 보이는 일인지 상상이나 할 수 있겠나? 나는 원한다면 네놈의 보잘것없는 생각이 네 머릿속에 떠다니는 땅콩만한 잿빛 덩어리를 짓뭉개 버리도록 할 수도 있는 존재란 말이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7199, 'koKR', '실은 간단하다. 내가 요약해 주지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7200, 'koKR', '검은심연 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다.', '검은심연 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7201, 'koKR', '잿빛 골짜기의 조람 해안에 위치한 검은심연 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남았는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다.', '잿빛 골짜기의 조람 해안에 위치한 검은심연 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남았는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7202, 'koKR', '놈리건은 던 모로 서쪽에 있습니다.', '놈리건은 던 모로 서쪽에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7203, 'koKR', '던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집', '던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7204, 'koKR', '가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다.', '가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7205, 'koKR', '고대의 전쟁 때, 반신 아감마간은 분연히 나서 불타는 군단과 싸웠습니다. 하지만 그 거대한 멧돼지는 패배했고, 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 서슬깃 차를가라는 노파가 가시덩굴 우리를 점령했는데, 강력하고 독보적인 주술을 사용하는 흙점쟁이입니다. 그녀가 권력을 얻으면서 가시멧돼지 부족', '고대의 전쟁 때, 반신 아감마간은 분연히 나서 불타는 군단과 싸웠습니다. 하지만 그 거대한 멧돼지는 패배했고, 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 서슬깃 차를가라는 노파가 가시덩굴 우리를 점령했는데, 강력하고 독보적인 주술을 사용하는 흙점쟁이입니다. 그녀가 권력을 얻으면서 가시멧돼지 부족', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7206, 'koKR', '붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다.', '붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7207, 'koKR', '수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다.', '수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7208, 'koKR', '가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다.', '가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7209, 'koKR', '가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다.', '가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7210, 'koKR', '울다만은 황야의 땅 북쪽 맨 끝에 있습니다.', '울다만은 황야의 땅 북쪽 맨 끝에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7211, 'koKR', '라드 여기 지킨다. 라드 물고기도 팔아. 물고기 살래?', '라드 여기 지킨다. 라드 물고기도 팔아. 물고기 살래?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7212, 'koKR', '울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다.', '울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7213, 'koKR', '줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다.', '줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7214, 'koKR', '햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다.', '햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7215, 'koKR', '마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다.', '마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7216, 'koKR', '마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고', '마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7217, 'koKR', '가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다.', '가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7218, 'koKR', '검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다.', '검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7219, 'koKR', '한때 검은무쇠 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다.', '한때 검은무쇠 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7220, 'koKR', '검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다.', '검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7221, 'koKR', '혈투의 전장의 폐허는 페랄라스 중심부에 있습니다.', '혈투의 전장의 폐허는 페랄라스 중심부에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7223, 'koKR', '스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다.', '스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7225, 'koKR', '폐허가 된 도시 스트라솔름은 역병숲 북쪽에 있는 동부 역병지대에 있습니다.', '폐허가 된 도시 스트라솔름은 역병숲 북쪽에 있는 동부 역병지대에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7226, 'koKR', '한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군 사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다.', '한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군 사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7227, 'koKR', '죽음의 폐광은 서부 몰락지대 남쪽에 있는 달빛시내 마을 아래에 있습니다.', '죽음의 폐광은 서부 몰락지대 남쪽에 있는 달빛시내 마을 아래에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7229, 'koKR', '스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다.', '스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7230, 'koKR', '지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다.', '지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7237, 'koKR', '요리에 필요한 재료라면 뭐든 다 가지고 있다네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7238, 'koKR', NULL, '깨진엄니 마을에 잘 왔네. 나는 깨진엄니 트롤의 지도자인 주술사 톤터스크라고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7239, 'koKR', '부서진 거라면 이 슬래그트리가 뭐든 고칠 수 있소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7240, 'koKR', NULL, '신비한 물건과 각종 상품을 다루는 게 내 일이오, 낯선 이여.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7241, 'koKR', '낚시란 참 즐거운 거란 말이야. 자네도 아나? 내 스승이자 전 세계에서 가장 훌륭한 낚시꾼인 내트 페이글 님 덕분에 이런 큰 기쁨을 누리게 되었지. 그분에 대해 들어 본 적이 있나?$B$B깨달음을 얻고 싶다면 내트 페이글 님께서 길을 보여 주실 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7242, 'koKR', '언젠가는 줄진 님께서 돌아오실 걸세. 내 말 잘 듣게나. 그때까지는 우리 모두 우리 위치를 사수하고 숲트롤의 수가 조금이라도 줄어들지 않게 하는 데 최선을 다해야 하네.$B$B따라서 깨진엄니 마을의 사냥의 대가로서 내 임무는 우리 주변의 환경을 살기에 안전하게 만드는 것일세.$B$B이 지역의 짐승들을 반드시 제압해야만 하네.$B$B혹시 일거리를 찾고 있는 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7243, 'koKR', '나는 도끼의 달인 킬램이라고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7244, 'koKR', '아, 한때는 경험 많은 노련한 분이셨군요. 이 킬램이 다시 노련한 제작자로 만들어 드리지요. 당신은 재능이 있어 보이니 요청만 하시면 도끼 제작자의 길을 가르쳐 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7245, 'koKR', NULL, '$n, 너무 가까이 오지는 마세요. 잘못해서 이 망치를 당신 얼굴 쪽으로 휘두르기라도 하면 큰일이니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7246, 'koKR', NULL, '망치 제작자의 길을 가르쳐 줄 테니 정중하게 요청만 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7247, 'koKR', '물러나지 않으면 두 동강 내 주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7248, 'koKR', '검 제작자가 되고 싶으면 물어만 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7249, 'koKR', '나를 다른 고블린들이 상상도 못할 만큼 엄청난 부자로 만들어 줄 새로운 차원 내파기를 방금 완성했다고! 이제 차원 분할기를 만들 실력 있는 고블린 기술자를 찾아서 분할기를 이 내파기에 연결하는 시험만 해보면 되는데!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7251, 'koKR', '놈리건으로 모험을 떠난 용감한 노움들이 가져온 기술 일부를 가지고 내가 물체 순간이동기라는 아주 엄청난 발명품을 만들어 냈죠! 이제 순간이동기에 맞게 조율된 강력한 유도장치를 만들 실력 있는 노움 기술자만 있으면 되는데 말이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7252, 'koKR', '장치를 만들고 작동만 하면 아름다운 가젯잔으로 재빨리 이동하게 될 거예요! 장치를 사용한 이들은 거의 모두 시작했을 때와 똑같은 모습으로 이곳에 도착했죠!\n\n일부 이용자들의 경우 다른 차원으로부터 온 괴상하고 사악한 존재로 바뀌는 문제가 있다는 보고가 있긴 했지만... 뭐, 틀림없이 곧 해결될 거예요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7253, 'koKR', '장치를 향상시킬 방법이 생각나면 내게 알려 주세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7256, 'koKR', '최후의 의식을 행하노라. 이것으로 충분하기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7257, 'koKR', '열쇠를 가져와 이 족쇄를 풀어 주게나! 열쇠는 동굴 뒤편에 있는 수호자 히타야가 가지고 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7274, 'koKR', '구인광고/분실물센터/현상 수배:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7294, 'koKR', '저그 저그! 내 이름은 켈름 하건스! 전쟁노래 정찰대에 보급품을 도맡아 공급하는 상인일세. 우리 부족을 위해 자네의 실력을 증명해 보인다면 전쟁노래 협곡에서만 사용할 수 있는 좋은 물건들을 보여주도록 하지. 거기다 장비 수리 서비스도 제공하고 있으니까 뭐라도 부서지면 찾아주라고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7295, 'koKR', NULL, '밤의 축복이 함께하기를! 저는 여기 잿빛 골짜기를 책임지고 있는 은빛날개 파수대의 병참장교 문블레이즈라고 합니다. 우리 은빛날개 파수꾼을 위한 싸움을 통해 그대의 실력을 증명하신다면 전쟁노래 협곡에서만 사용할 수 있는 좋은 물건들을 보여드리겠습니다. 거기다 장비 수리 서비스도 제공하고 있으니까 고칠 물건이 있으시면 언제든지 찾아주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7314, 'koKR', '어서 오세요! 이곳은 바로 예브 네블기어의 다크문 별난 동물원입니다. 살아 있는 전설과 신비로운 것들이 모여 있는 곳이죠! 마음껏 즐기십시오!$B$B하지만 아무거나 함부로 만져서는 안 됩니다! 여기에 전시된 유물과 짐승들에는 신성한 것도 있고, 아주 무시무시한 것도 있으니까요! 과도한 호기심을 참지 못하고 함부로 만졌다가는 손이 불에 탈 수 있습니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7315, 'koKR', '오늘은 어디로 보내 드릴까요?', NULL, '불모의 땅에서는 크로스로드가 가장 번화한 중심지인 것 같지만 전 타우라조 야영지의 평온함이 더 마음에 듭니다. 그런데 어디로 보내 드릴까요?', NULL, '대지모신께 이르는 길은 여러 가지가 있습니다. 언제 어디에서 여행을 하든지 대지모신께서 그대를 지켜주시기를...', NULL, '와이번을 잘 다루십시오. 그대를 원하는 목적지로 데려가 줄 테니까. $N, 선조의 가호가 있기를 빕니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7334, 'koKR', '아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 오셔서 마음껏 즐기세요. 다크문 유랑단이 이 드넓고 신비한 세계를 유랑하며 발견한 온갖 놀라운 물건들을 구경하시라니까요! 다양한 연령층의 어린이들이 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7335, 'koKR', '아제로스 최고의 쇼에 다시 오신 것을 환영합니다! 다시 뵙게 돼서 정말 기뻐요!$B$B어서 오세요! 다시 한번 마음껏 즐기시기 바랍니다. 다크문 축제에는 항상 새롭고 신나는 것들이 늘어만 가고 있으니 구석구석 둘러보세요! 그동안 발견한 온갖 놀라운 물건들을 구경하세요! 어린이라면 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7336, 'koKR', '돈이 문제가 아니죠! 사실 상당한 액수의 기부를 받고 있거든요. 때론 정말 어마어마한 거액을 주는 분도 있지요. 저희 유랑단은 전쟁으로 피폐해진 이 세계에 밝은 웃음을 선사하고자 모였어요. 이러한 선의의 목적이 저희의 재능과 노력에 원동력이 되고 있으니 걱정은 마세요. 걱정은 우리가 할게요. 어떻게 하면 여러분을 최고로 즐겁게 해 드릴 수 있을까... 바로 이런 걱정요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7337, 'koKR', '상품권 교환! 귀한 상품으로 바꿔 가게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7338, 'koKR', '저리 비켜, 촌뜨기...', NULL, '난 탈것이 아니야. 꺼져.', NULL, '신경 건드리고 싶지 않으면 입 다물어. 그래, 아예 숨도 쉬지 마.', NULL, '아직도 이해를 못 했나? 나 여기 장사하러 온 거 아니다.', NULL, '실라스랑 친구면 나하고도 친구다. 좋은 하루!', NULL, '머리가 하나 더 필요해. 지금 달린 건 언제 떨어질지 몰라.', NULL, '잠깐 혈투의 전장에서 살았었다. 재미있었어. 진짜!', NULL, '난 다른 오우거들이랑은 달라. 화장실이 뭔지 아니까. 갔다 나오면 빙글빙글 어지러워 지는 거지. 이제 꺼져.', NULL),
(7339, 'koKR', '$n, 자네가 날 찾고 있다는 사실을 오래전부터 알고 있었네.$B$B이 아제로스 세계에 지각이 있는 모든 존재는 자신의 결정과 선택에 따라 살아가지. 선택이 또 다른 선택을 낳고, 결국 이러한 선택의 연속으로 자신의 존재가 형성된다네. 결국 자네가 내리는 선택에 따라 자네가 누구인지, 자네의 운명도 결정되는 법이지.$B$B자신의 운명을 발견할 준비가 되었나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7340, 'koKR', '좋아...$B$B자네가 모시는 주군한테서 밀렵꾼과 도적으로부터 옥수수밭을 지키라는 임무를 받았다고 침세. 어느 날 밤 밭에서 순찰하다가 누더기를 걸친 수척한 사내가 옥수수를 훔치는 것을 발견했지. 그자는 자네에게 금방 붙잡혔고 곧바로 목숨을 구걸하기 시작했네. 그러면서 옥수수를 훔친 이유는 가족을 먹여 살리기 위해서라고 주장했다네. 그 땅의 영주, 그러니까 자네 주군이 세금을 너무 많이 거둬 갔기 때문에 먹을 것이 없었던 게지. 실제로 자네 주군은 과중', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7341, 'koKR', '다음 선택일세.$B$B자네는 주군에게 충성을 맹세한 사형집행인일세. 어느 날 자네 앞으로 주군과 영지 주민을 배반한 죄목으로 사형 선고를 받은 자가 끌려 왔네. 그런데 자세히 보니 과거에 홀연히 실종되었던 절친한 친구가 아닌가?! 자네가 알기에는 고귀한 성품의 소유자이지만 그 친구가 유죄가 맞는다면 무고한 주민을 수없이 학살한 장본인이라네. 그자가 자네를 알아보자 목숨만 살려 달라고 애원하면서 자신은 권력자의 모함에 빠진 것이라고 주장하네.$B$B자,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7354, 'koKR', '나 이거 참, 내 앞에 산더미처럼 놓인 일거리가 안 보인단 말입니까?', '지금 내 앞에 산더미처럼 놓인 일거리가 안 보인단 말인가요?', '머지않아 축제가 열린답니다!', '머지않아 축제가 열린대요!', '맞습니다! 다크문 축제가 바로 여기서 열릴 겁니다. 제가 짐들을 다 내리고, 천막을 모두 치고, 동물원을 세우고, 먹고 마실 걸 모두 준비하는 즉시 말이죠. 나중에 꼭 한번 다시 들르세요!', '맞습니다! 다크문 축제가 바로 여기서 열릴 겁니다. 제가 짐들을 다 내리고, 천막을 모두 치고, 동물원을 세우고, 먹고 마실 걸 모두 준비하는 즉시 말이죠. 나중에 꼭 한번 다시 들르세요!', '다크문 축제가 곧 열립니다. 나중에 다시 한번 들러 보세요.', '다크문 축제가 곧 열립니다. 나중에 다시 한번 들러 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7355, 'koKR', '축제에 오신 것을 환영합니다! 저희는 전 세계의 진귀한 물건들을 모아서 전시하고 있습니다. 혹시 일반 다크문 카드 한 벌을 모으거든 알려주십시오. 주인님이... 아니, 제가 그 카드에 상당히 관심이 많아서 말입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7356, 'koKR', '우리는 아제로스의 실력 있는 자들이 8가지 카드 종류 중 어느 한 벌을 완성할 수 있는지 시험해 보려고 전 세계에 다크문 카드를 뿌려 놓았습니다. 한 종류의 카드 8장을 모두 모으면 상급 다크문 카드 중 한 장을 보상으로 받게 될 겁니다. 이 카드는 강력한 장신구이자 다크문 축제로 연결해 주는 장치지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7357, 'koKR', '야수 카드를 모아 한 벌이 되면 푸른용의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 마법의 힘을 회복하는 데 아주 유용하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7358, 'koKR', '차원문 카드를 모아 한 벌이 되면 뒤틀린 황천의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 죽었을 경우 당신의 영혼을 바로 부활시켜 주기도 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7359, 'koKR', '정령 카드를 모아 한 벌이 되면 혼돈의 소용돌이의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 맞서 싸우고 있는 적에게 커다란 피해를 주기도 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7360, 'koKR', '대장군 카드를 모아 한 벌이 되면 영웅심의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 근접전을 펼칠 때 치유를 해 주기도 하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7361, 'koKR', '다음 선택일세.$B$B자네는 주군을 대신하여 난폭한 적국에서 외교 임무를 수행하는 중일세. 모두 전쟁 때문에 큰 피해를 입고 있는 상태라서 자네는 양국의 체면을 모두 살리면서 평화 협정을 체결하라는 임무를 받았지.$B$B외교 만찬을 들던 중 자네의 귀에 적국의 지도자가 인자한 주군을 지독히도 모욕하는 소리가 들려왔네. 물론 그 지도자는 자네에게는 들리지 않을 거라고 믿고 말한 것이 분명하지만 어쨌든 주군의 명예를 더럽힌 것일세.$B$B자, 자네의 선택을', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7362, 'koKR', '다음 선택일세.$B$B자네는 정예 부대의 일원인데 동생이 들어오고 싶어하네. 책임감과 충성심은 나무랄 데 없는 동생이지만 정예 부대의 어려운 임무를 수행할 능력이 있는지는 반신반의일세. 어쩌면 동생의 실수로 인해 부대원 전체가 위험에 처할 수도 있을 법하거든. 어쨌든 동생이 정예 부대에 걸맞은 능력을 갖췄는지는 확실치 않지만, 자네 말 한 마디로 동생의 입대가 결정될 것은 분명하네.$B$B자, 자네의 선택을 말해 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7363, 'koKR', '다음 선택일세.$B$B변두리 지역을 휩쓸고 다니던 끔찍한 괴물을 자네 혼자 물리치고, 그 괴물의 귀를 전리품으로 챙겼네. 그런데 주군이 모르고 나중에서야 그 괴물의 목에 현상금을 걸었고, 자네와 면식이 있는 한 기사가 괴물을 죽였다는 거짓 주장을 한다는 소식을 듣게 되었네. 그 기사는 성품이 온화하지만 집안이 가난하여 가족을 겨우 먹여 살릴 수 있을 정도라네. 솔직히 자네에게 돈은 필요 없지만 그 가난한 기사는 개인적인 이익을 위해 거짓말을 하고 있는', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7364, 'koKR', '$c|1이여;여;, 자네 운명이 담긴 점괘가 나왔네. 앞으로 몇 시간 동안 자네의 영혼이 진정한 본성에 눈뜬 것을 느낄 수 있을 거야. 하지만 주의하도록. 점괘가 말하는 자네의 운명은 결코 자네 생각처럼 분명한 것이 아니니까.$B$B내가 주는 작은 단서를 통해서라도 자신의 미래에 대해 생각해 볼 필요가 있다면 언제든지 말하게. 가방에 여유가 있다면 내 기꺼이 점괘를 적어 주지. 내 질문에 대답하면서 보여 준 자네의 영감에 따라 정해진 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7365, 'koKR', '$n, 여기 자네의 점괘가 있으니 읽어보게. 현명하게 해석하길!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7366, 'koKR', '곧 마을에서 다크문 축제가 시작되니 절대 놓치지 마시오!', NULL, '마을에 다크문 축제가 시작되면 그 놀라운 구경거리들을 하나도 놓치지 마십시오!', NULL, '다크문 축제가 곧 시작됩니다! 동심을 간직하고 있는 분이라면 모두 즐길 수 있습니다. 모두 오십시오!', NULL, '이리 와서 아제로스 최고의 구경거리인 다크문 축제에 대해 들어 보십시오! 허이짜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7374, 'koKR', '다크문 축제가 시작됐습니다! 모두 아제로스 전체에서 가장 신나는 쇼를 놓치지 마세요!', NULL, '마을에 다크문 축제가 열리고 있소! 평생 두 번 다시는 못 볼 짜릿한 구경거리를 절대 놓치지 마시오!', NULL, '다크문 축제는 머지않아 막을 내릴 거요. 그러니 지금 바로 구경 가시오!', NULL, '다크문 축제가 시작됐소! 형, 누나, 오빠, 언니, 동생이랑 다 같이 구경들 하시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7375, 'koKR', '다크문 축제가 시작됐습니다! 모두 아제로스 전체에서 가장 신나는 쇼를 놓치지 마세요!', NULL, '마을에서 다크문 축제가 열리고 있습니다! 평생 두 번 다시는 못 볼 짜릿한 쇼를 꼭 경험해 보세요!', NULL, '다크문 축제는 머지않아 막을 내릴 겁니다. 그러니 지금 바로 구경 가십시오!', NULL, '다크문 축제가 시작됐습니다! 형, 누나, 오빠, 언니, 동생이랑 다 같이 구경들 하십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7376, 'koKR', '다크문 축제는 멀고어에서 열릴 예정입니다. 썬더 블러프 바로 남서쪽에 여러분을 맞이할 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7377, 'koKR', '지금 썬더 블러프 바로 남서쪽 멀고어 황금빛 초원에서 다크문 축제가 열리고 있습니다. 꼭 구경 가세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7378, 'koKR', '다크문 축제는 엘윈 숲에서 열릴 예정입니다. 다크문 유랑단이 황금골 바로 남쪽에서 여러분을 맞이할 겁니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7379, 'koKR', '지금 엘윈 숲, 황금골 바로 남쪽에서 다크문 축제가 열리고 있으니 절대로 놓치지 마세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7381, 'koKR', '안녕하세요.', '안녕하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7382, 'koKR', '이 주변은 정말 지저분하군요.', '이 주변은 정말 지저분하군요.', '즐거운 시간 보내고 계신가요?', '즐거운 시간 보내고 계신가요?', '간식거리와 기념품 사시는 것도 잊지 마세요!', '간식거리와 기념품 사시는 것도 잊지 마세요!', '다크문 축제는 아제로스 전체에서 가장 큰 행사랍니다!', '다크문 축제는 아제로스 전체에서 가장 큰 행사랍니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7383, 'koKR', NULL, '$c님, 다크문 축제에 오신 걸 환영해요!$B$B전 케리 힉스라고 해요. 악수를 청하고 싶지만 손을 다치실까 봐 그럴 수가 없네요. 왜냐하면 전 이 세계에서 가장 강한 여자거든요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7387, 'koKR', '어서 오시게! 여기 매콤한 핫윙 좀 먹어 보게나!', NULL, '방금 구워낸 따끈따끈한 다크문 핫도그... 식기 전에 어서 와서 들게나!', NULL, '자네한테는 돈이 있고 우리에겐 맛있는 음식이 있는데, 뭘 망설이는 겐가?!', NULL, '다크문 축제에서만 맛볼 수 있는 개구리 튀김! 한정 기간만 판매하지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7389, 'koKR', NULL, '내가 팔고 있는 물건들은 모두 내가 직접 모은 것들이지. 그러니까 제대로 된 물건이라는 걸 내가 직접 보증한다고.', NULL, '다크문 축제 카드? 그거라면 여기 있는 학자에게 가봐. 골동품이나 유물을 거래하고 싶다면 나를 찾아오도록.', NULL, '기회가 있을 때 내 물건들을 실컷 구경해 두는 게 좋을 거야. 우린 이번 주까지만 여기 있고 멀리 이동할 거니까.', NULL, '이 귀중한 물건들을 구하기 위해 내가 얼마나 고생했는지 상상도 못 할걸. 와서 전부 다 구경하도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7390, 'koKR', '여기, 누가 이 개구리 좀 잡아 주세요!', NULL, '개구리가 달아나려 해요!', NULL, '개굴아, 이리 돌아와!', NULL, '개구리와 가죽공을 팔고 있어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7393, 'koKR', '이런... 안됐지만, 자네는 최근에 내게서 점괘를 받았기 때문에 지금은 운명 상담을 받을 수 없어.$B$B점괘를 받은 지 몇 시간이 지난 후에 다시 오라고. 그러면 운명의 힘이 다시 원상태로 돌아오게 되니까 내가 자네의 미래를 예견할 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7394, 'koKR', '$N, 다시 만나서 반갑군! 축제는 재미있나?$B$B팔씨름 한판 할 텐가? 아, 물론 싫겠지... 팔은 멀쩡히 간직하고 싶을 테니까!', '$n, 다시 만나 반가워요! 축제에서 즐거운 시간 보내고 계신가요?$B$B팔씨름 한 판 하실래요? 물론, 피하시겠죠... 팔이 부러지고 싶지는 않을 테니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7395, 'koKR', '안녕하시오. 나는 기억력의 대가인 크로노스라고 하오. 내 기억력은 완벽해서 아무리 사소한 것이라도 모두 정확하게 기억한다오.$B$B믿어도 좋소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7396, 'koKR', '또 만났군. 내가 당신을 잊을 거라 생각했소?$B$B물론 당신이 그렇게 생각하지 않으리란 걸 난 알고 있었지. 당신은 완벽한 기억력을 가진 자를 몰라보지 않을 만큼 똑똑한 $c|1이니까;니까; 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7397, 'koKR', '안녕하신가! 어서 오게!$B$B도전할 수 있겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7398, 'koKR', '오, 자네 돌아왔군! 지난밤에 찾아온 어떤 영혼이 그러더군. 자네가 곧 나를 찾아와서 일 얘기를 하게 될 거라고 말이야.$B$B그 말이 맞는 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7399, 'koKR', '$n, 안녕하세요! 다시 만나서 반가워요! 다크문 축제, 정말 멋진 쇼 아닌가요?$B$B볼거리는 또 얼마나 많은지! 열심히 구경해 두세요! 그러면 언젠가는 더 많은 것들이 당신 눈에 보이게 될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7400, 'koKR', NULL, '내 애완 개구리 줍줍이 사라졌어. 검은무쇠 맥주를 정말 좋아해서 그거만 마시는 녀석인데... 그런데 그 맥주는 정말 구하기가 너무 어려워! 맥주가 다 떨어지니까... 그 맛을 찾아서 도망친 게 틀림없다고!$B$B꼭 다시 돌아왔으면 좋으련만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7401, 'koKR', NULL, '주브주브가 돌아와서 정말 기뻐! 검은무쇠 맥주가 떨어지지만 않았으면 좋겠군. 또 떨어지면 내 애완 개구리가 다시 도망갈지도 모르니까!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7402, 'koKR', '무슨 일이 있어도 반드시 이 야영지를 지켜 내야 합니다! 어느 한 구역도 절대 적들에게 넘겨 줘서는 안 됩니다. 반대 입장이었다면 틀림없이 녀석들도 그렇게 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7403, 'koKR', '요즘은 아주 위험한 시기라네. 고대 악의 씨앗이 싹트고 있는데, 호드와 얼라이언스를 구분하지 않거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7404, 'koKR', NULL, '시원하고 맛있는 음료 팝니다! 다크문 축제 최고의 음료로 갈증을 해소하세요!', NULL, '뭘 망설이세요?! 모두에게 한 잔씩 돌려 보아요!', NULL, '팁이라면 언제든 대환영입니다.', NULL, '방금 막 들어온 다크문 폭탄주 있어요. 다 팔리기 전에 어서 와서 맛보세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7406, 'koKR', '개굴!', NULL, '키스해줘요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7415, 'koKR', '반갑네, 젊은 $c|1이여;여;... 자네 대족장이 오그림 둠해머를 상대한 곳이 바로 여기라네! 아주 오래전 일이지만 내 마음속에는 아직도 그 모습이 생생히 남아 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7416, 'koKR', '젊은 $c|1이여;여;, $966w명이 살아있군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7434, 'koKR', NULL, '뭘 좀 배우러 온 모양이로군. 자네에게 맡길만한 일이 있을지도 모르겠어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7435, 'koKR', '<거수경례를 하는 스톰파이크 하사관>$B$B성명, 계급, 그리고 군번! 그것들만이 자네가 저 더러운 서리늑대 개들에게 넘겨 줄 수 있는 유일한 정보다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7436, 'koKR', '$964w 명이네. 젊은 $c|1이여;여;...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7437, 'koKR', '스톰파이크 지휘관은 $962w명, 스톰파이크 부관은 $950w명이 살아남아 있네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7438, 'koKR', '알터랙 계곡은 분명히 우리 것이 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7439, 'koKR', '$962w명 살아있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7440, 'koKR', '$950w명 살아있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7441, 'koKR', '서리늑대 지휘관은 $966w명, 서리늑대 부관은 $964w명이 살아남았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7454, 'koKR', '세계를 구하러 온 것이라면 제대로 찾아왔군. 얼굴 없는 자, 혈신 학카르가 다시 나타났다네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7455, 'koKR', '$n, 자네의 얼굴에 결의가 빛나는군. 계속해서 우리 부족의 편에 서서 돕고 있으니 언젠가는 온 세상이 자네의 훌륭한 업적을 알게 될 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7456, 'koKR', '자라나는 영웅이 돌아왔군! 다시 보게 되다니 반갑네, $n. 자네라면 우리 마을에서는 언제든지 대환영이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7458, 'koKR', '멀고도 험난한 길을 걸어왔군. 우리 부족에서도 자네처럼 높은 지위를 얻은 자는 드물지. $n, 자네는 잔달라 제국의 위대한 벗일세.$B$B그래... 어쩌면, 전설이라고도 부를 수 있을지 몰라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7476, 'koKR', NULL, '$n, 출격 명령을 내려주십시오! 말씀만 하시면 당장 하늘로 올라가 놈들의 다리를 공격하겠습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7479, 'koKR', '사령관님, 명령만 내리시면 즉시 출발하겠습니다! 서리늑대 요새까지 이르는 경로를 정찰하겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7481, 'koKR', NULL, '$c|1이여;여;, 어서 오세요. 전쟁노래 협곡에서 힘겨운 싸움을 하고 있는 은빛날개 파수대를 도우러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7482, 'koKR', NULL, '엘룬께 영광을! 전쟁노래 협곡 전투모병관을 찾는 건가요? 그녀의 이름은 애살라스이며 상급 전사들 곁에서 그대를 기다리고 있을 겁니다.', NULL, '지금 그대가 하려는 일은 결코 쉬운 일이 아니랍니다, $n. 전쟁노래 협곡에 가려면 은빛날개 파수꾼 전투모병관인 애살라스와 대화하십시오. 그녀가 길을 가르쳐줄 겁니다. 여신님의 축복이 함께하기를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7483, 'koKR', '그래, 알터랙 계곡의 호드로부터 얼라이언스를 지켜낼 자신이 있단 말이지요? 그렇다면 이곳 아이언포지에서 글로드룸 스틸비어드와 이야기를 나눠보십시오. 그는 전투의 전당에 있는 탁자 앞에서 전략을 짜고 있을 겁니다.', '그래, 알터랙 계곡의 호드로부터 얼라이언스를 지켜낼 자신이 있단 말이지요? 그렇다면 이곳 아이언포지에서 글로드룸 스틸비어드와 이야기를 나눠보십시오. 그는 전투의 전당에 있는 탁자 앞에서 전략을 짜고 있을 겁니다.', '아, 알터랙 계곡이라... 아주 즐거운 추억들이 잔뜩 있는 곳이지요. <한숨> 당신과 함께 전투에 참가할 수는 없지만 제게 자랑스러운 얼라이언스의 일원으로서 기뻐할 경사를 가져다주십시오. 그곳에 가려면 이곳 아이언포지에 있는 전투의 전당에서 글로드룸 스틸비어드와 대화해야 할 겁니다.', '아, 알터랙 계곡이라... 아주 즐거운 추억들이 잔뜩 있는 곳이지요. <한숨> 당신과 함께 전투에 참가할 수는 없지만 제게 자랑스러운 얼라이언스의 일원으로서 기뻐할 경사를 가져다주십시오. 그곳에 가려면 이곳 아이언포지에 있는 전투의 전당에서 글로드룸 스틸비어드와 대화해야 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7484, 'koKR', '알터랙 계곡으로 가려면 카르타 블러드스날과 얘기해보게. 명예의 골짜기에 있는 용사의 전당에서 그녀를 찾을 수 있을 걸세.', '알터랙 계곡으로 가려면 카르타 블러드스날과 얘기해보게. 명예의 골짜기에 있는 용사의 전당에서 그녀를 찾을 수 있을 걸세.', '아, 영광스러운 전투에 나도 참가하고 싶지만 임무 때문에 어쩔 수 없이 여기 있어야 하네. 오그리마 명예의 골짜기에 있는 용사의 전당을 찾아가게. 카르타 블러드스날과 얘기하도록. 그녀라면 알터랙 계곡으로 데려다 줄 수 있을 테니까. $n, 부디 호드의 자랑거리가 되도록!', '아, 영광스러운 전투에 나도 참가하고 싶지만 임무 때문에 어쩔 수 없이 여기 있어야 하네. 오그리마 명예의 골짜기에 있는 용사의 전당을 찾아가게. 카르타 블러드스날과 얘기하도록. 그녀라면 알터랙 계곡으로 데려다 줄 수 있을 테니까. $n, 부디 호드의 자랑거리가 되도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7495, 'koKR', NULL, '어느 전장으로 가시겠습니까? 전투모병관의 위치를 안내해 드리지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7496, 'koKR', NULL, '누구를 찾고 있는지 알겠어요. 전사의 정원에 있는 브로군 스톤쉴드에게 가보십시오.', NULL, '서리늑대 부족에 맞서 싸우고 있는 스톰파이크 경비대는 그대의 도움을 필요로 하고 있습니다. 전사의 정원에 있는 브로군 스톤쉴드가 알터랙 계곡으로 가는데 도움을 줄 겁니다. 엘룬께 영광을...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7497, 'koKR', '어느 전장을 찾고 계십니까?', '어느 전장을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7498, 'koKR', '전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', '전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', '호드, 특히 오크와 맞서 싸울 기회가 생긴다면 아주 잘 된 거라고 할 수 있소. 전쟁노래 협곡에서 당신이 원하는 전투를 무수히 많이 접하게 될 겁니다. 전투의 전당으로 가서 리란드리스와 얘기해 보시면 전쟁노래 협곡으로 이끌어 줄 겁니다.', '호드, 특히 오크와 맞서 싸울 기회가 생긴다면 아주 잘 된 거라고 할 수 있소. 전쟁노래 협곡에서 당신이 원하는 전투를 무수히 많이 접하게 될 겁니다. 전투의 전당으로 가서 리란드리스와 얘기해 보시면 전쟁노래 협곡으로 이끌어 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7499, 'koKR', '어떤 전장에 관심이 있으신가요?', '어떤 전장에 관심이 있으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7500, 'koKR', '그렇다면 텔만 슬레이트피스트와 이야기해 보게. 스톰윈드 왕궁에서 국왕 폐하 곁에 있을 걸세.', '당신이 만나야 하는 자의 이름은 텔만 슬레이트피스트입니다. 스톰윈드 왕궁의 알현실로 가면 찾을 수 있을 겁니다.', '나도 자네와 함께 가고 싶군, $N. 스톰윈드 왕궁으로 가게. 왕좌의 방에 있는 텔만 슬레이트피스트가 알터랙 계곡으로 가는 걸 도와줄 걸세.', '저도 당신과 동행할 수 있다면 좋겠군요. 알터랙 계곡으로 가려면 스톰윈드 왕궁으로 가십시오. 국왕 알현실에서 텔만 슬레이트피스트를 만날 수 있을 겁니다. 그라면 당신을 도와 줄 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7501, 'koKR', '맞네, 은빛날개 파수대는 자네의 도움이 필요하네. 스톰윈드 왕궁 왕좌의 방에 있는 엘파란과 이야기해 보게.', '사실, 지금 은빛날개 요새에서 당신의 도움을 필요로 하고 있습니다. 스톰윈드 왕궁의 알현실로 가서 엘파란과 얘기해 보십시오.', '은빛날개 파수대는 전쟁노래 정찰대와 맞서 싸울 도움이 절실하네. $N, 돕고 싶다면 스톰윈드 왕궁으로 가서 엘파란과 이야기하게.', '은빛날개 파수대는 전쟁노래 정찰대와 전투를 위해 가능한 많은 이들의 도움을 받고 있습니다. 도움을 주려거든 스톰윈드 왕궁으로 가서 엘파란과 얘기해 보도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7502, 'koKR', '전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', '전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', '은빛날개 파수대는 존중할 만한 적이라고 하기는 어렵지. 그래도 놈들을 처치하고 싶다면, $c, 용사의 전당에 있는 브락굴 데스브링어를 찾아가게.', '은빛날개 파수대라면 싸워볼 만한 가치도 없다고... 그래도 놈들을 쓸어 버리고 싶다면 용사의 전당에 있는 브락굴 데스브링어를 찾아가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7503, 'koKR', '어느 전장을?', '어느 전장을?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7504, 'koKR', '어느 전장에서 명예와 영광을 얻길 바라십니까?', '어느 전장에서 명예와 영광을 얻길 바라십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7505, 'koKR', '그렇다면 타임 레이지토템과 이야기해야 하네. 사냥꾼의 봉우리에서 찾아보게.', '타임 레이지토템을 말하는 게 틀림없군... 수렵의 봉우리로 가서 찾아보십시오.', '여기 썬더 블러프에 자네가 알터랙 계곡으로 가는 걸 도와줄 사람이 있네. 사냥꾼의 봉우리에서 타임 레이지토템을 찾아보게. 원하는 것을 찾길 바라네, $N.', '이곳 썬더 블러프에 알터랙 계곡으로 가는 걸 도와 줄 수 있는 이가 한 명 있습니다. 수렵의 봉우리에서 타임 레이지토템을 찾아보십시오. 당신이 원하는 것을 구하게 되기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7506, 'koKR', '수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', '수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', '싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', '싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7507, 'koKR', '어느 전장?', '어느 전장?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7508, 'koKR', '거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', '거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', '그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', '그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7509, 'koKR', '왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', '왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', '전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', '전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7514, 'koKR', '나는 라스타칸 님의 오른팔이신 무감바 님께서 보내신 파괴자 진로크다!$B$B난 전사와 이교도들을 담당하고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7515, 'koKR', '나는 라스타칸께서 보내신 천리안 알타빔이네.$B$B사제, 마법사, 그리고 흑마법사를 담당하고 있지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7516, 'koKR', '아라소르 연맹은 스트롬가드의 인간들과 얼라이언스 전체를 위해 아라시 분지를 되찾겠노라 맹세했소. 이번 전투가 결코 만만치는 않지만 싸울 가치는 충분할 것이외다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7517, 'koKR', NULL, '가만히 앉아 기다리고 있어서야 전쟁에서 이길 수 없습니다. 거칠고 빠르게 밀어붙여야 합니다. 그렇지 않으면 아라시 분지를 영원히 되찾지 못할 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7519, 'koKR', NULL, '어느 전장으로 가시겠습니까? 전투모병관의 위치를 안내해 드리지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7520, 'koKR', '전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', '전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', '은빛날개 파수대라면 싸워볼 만한 가치도 없다고... 그래도 놈들을 쓸어 버리고 싶다면 용사의 전당에 있는 브락굴 데스브링어를 찾아가 보게.', '은빛날개 파수대라면 싸워볼 만한 가치도 없다고... 그래도 놈들을 쓸어 버리고 싶다면 용사의 전당에 있는 브락굴 데스브링어를 찾아가 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7521, 'koKR', '어느 전장을?', '어느 전장을?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7523, 'koKR', '수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', '수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', '싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', '싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7524, 'koKR', '어느 전장에서 명예와 영광을 얻길 바라십니까?', '어느 전장에서 명예와 영광을 얻길 바라십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7525, 'koKR', '거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', '거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', '그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', '그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7526, 'koKR', '왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', '왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', '전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', '전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7527, 'koKR', '어느 전장?', '어느 전장?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7528, 'koKR', '전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', '전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', '호드와의 싸움이라... 특히 오크와 한판 붙어 볼 기회가 생기길 빌게요. 전쟁노래 협곡으로 가면 당신이 그렇게도 바라던 전투를 끝없이 할 수 있을 겁니다. 전투의 전당으로 가서 리란드리스를 찾으세요. 전쟁노래 협곡으로 이끌어 줄 테니까요.', '호드와의 싸움이라... 특히 오크와 한판 붙어 볼 기회가 생기길 빌게요. 전쟁노래 협곡으로 가면 당신이 그렇게도 바라던 전투를 끝없이 할 수 있을 겁니다. 전투의 전당으로 가서 리란드리스를 찾으세요. 전쟁노래 협곡으로 이끌어 줄 테니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7529, 'koKR', '어느 전장을 찾고 계십니까?', '어느 전장을 찾고 계십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7530, 'koKR', '뭘 도와드릴까요, $c님?', '뭘 도와드릴까요, $c님?', '저도 당신과 동행할 수 있다면 좋겠군요. 알터랙 계곡으로 가려면 스톰윈드 왕궁으로 가십시오. 국왕 알현실에서 텔만 슬레이트피스트를 만날 수 있을 겁니다. 그라면 당신을 도와 줄 수 있을 거예요.', '저도 당신과 동행할 수 있다면 좋겠군요. 알터랙 계곡으로 가려면 스톰윈드 왕궁으로 가십시오. 국왕 알현실에서 텔만 슬레이트피스트를 만날 수 있을 겁니다. 그라면 당신을 도와 줄 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7532, 'koKR', '어떤 전장에 관심이 있으신가요?', '어떤 전장에 관심이 있으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7534, 'koKR', NULL, '뭘 바라는 거죠?$B$B나 메이위키는 드루이드와 주술사만 상대한다고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7535, 'koKR', '어서 오시오. 풍성한 수확의 기쁨을 기리는 추수절이 돌아왔소이다. 마땅히 축제를 벌여 우리에게 주어진 모든 것에 감사해야 하오! 특히 선조와 과거의 영웅들을 기억하며 그들이 물려 준 유산에 감사를 표해야지...$B$B자, 이곳에서 열리는 축제를 마음껏 즐기시오. 참, 그리고 이 명절을 더욱 아름답게 빛내 줄 폭죽도 팔고 있으니 둘러 보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7536, 'koKR', '어서 오세요. 풍성한 수확의 기쁨을 기리는 추수절이 돌아왔습니다. 마땅히 축제를 벌여 우리에게 주어진 모든 것에 감사해야지요! 특히 선조와 과거의 영웅들을 기억하며 그들이 물려 준 유산에 감사를 표해야 합니다.$B$B자, 이곳에서 열리는 축제를 마음껏 즐기세요. 참, 그리고 전 이 명절을 더욱 아름답게 빛내 줄 폭죽도 팔고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7554, 'koKR', NULL, '절대로 얼라이언스가 아라시 분지에서 세력을 확대하게 내버려둬선 안 돼! 저 조그마한 임시 주둔지가 커져서 훗날 우리 목숨을 위협할 수도 있는 일 아닌가!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7555, 'koKR', '아라시 분지의 전쟁은 곧 물자 전쟁이나 다름없다네. 목재, 광석, 식량... 이 모든 것이 전쟁의 승리를 위해 필수적이지.$B$B그러므로 전장에서 적의 물자 보급을 차단하는 일은 적장을 처치하는 것만큼이나 훌륭한 공을 세운 것일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7556, 'koKR', '이 몸, 비록 눈은 멀었지만 사리 판단은 분명합니다.$B$B저는 주로 사냥꾼과 도적을 상대하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7574, 'koKR', '어서 오십시오.전 줄다자르의 상인 린워쇼라고 합니다. 제 고향 남쪽 바다에서 여러 가지 이국적인 물건들을 가지고 왔지요.$B$B당신이 우리 부족에게 가치 있는 존재라는 걸 충분히 입증해 보인다면 나와 교환을 할 수 있을 겁니다. 그리고 잔달라 명예 징표를 손에 넣으면 우리 거래 얘기는 한결 쉬워질 거고요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7594, 'koKR', '나는 잔달라의 로아, 잔자라오. 동족을 돕기 위해 잔달라에서 이 에테리얼 형상을 하게 됐소이다. 학카르는 결코 내 영혼을 지배하지 못하오.$B$B난 잔달라 부족을 돕는 이들을 돕는 일을 하고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7595, 'koKR', '오, 잔달라 부족의 친구로군! 당신은 혈신의 소굴 깊은 곳으로 들어왔소. 그러니 내가 하는 말을 잘 들어야 할 거요.$B$B지금으로부터 수천 년 전, 줄아만 제국의 토착 트롤들이 하이 엘프 침략자들과 싸울 때 이 잔자의 위대한 주술이 도둑을 맞았소. 하이 엘프들은 훔친 주술로 무기와 방어구에 마법을 걸어 이 지역의 트롤들을 완전히 정복하려 했소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7596, 'koKR', '그래? 그렇다면, 하이 엘프들이 사용하는 트롤 주술이 아주 약하고 형편없다는 것도 알고 있소?$B$B하이 엘프들은 자신들의 마력과 비슷한 트롤 주술에 왜 맞설 수 없는지 의아해 했지만, 트롤 주술이란 허여멀건 얼굴의 하이 엘프 놈들 따위는 절대로 이해할 수 없는 것이오. 결국, 트롤 주술의 흉내만 내는 하급 마법을 사용하는 데 그치고 말더군. 놈들은 그걸 \'영석\'이라고 부르는 모양이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7597, 'koKR', '잔자에게 알맞은 재료만 주면 고대 트롤 주술을 사용할 수 있소. 그 마법은 학카르와 그의 부하들을 무찌르는 데 큰 도움이 될 거요.$B$B자, 두 가지 물건만 가져다주시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7598, 'koKR', '첫 번째 재료는 고대 학카리 휘장이요. 학카르 부족의 가장 강력한 지휘자인 진도와 혈군주에게서 얻을 수 있지.$B$B두 번째는 구멍 난 부두 인형인데, 타락한 이 땅의 이곳저곳에 버려진 쓰레기 더미를 뒤져보면 찾을 수 있을 거요. 특히 불길한 흑마술 더미 안을 눈여겨 보시오.$B$B이 두 가지 재료를 모두 가져오면 당신에게 강력한 마법을 허락하겠소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7599, 'koKR', '$c 친구, 미안하지만 전쟁노래 협곡에 들어가기엔 훈련이 아직 부족하군.', '$c 친구, 미안하지만 전쟁노래 협곡에 들어가기엔 훈련이 아직 부족하군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7614, 'koKR', '매주 낚시왕 선발대회가 열리는 무법항에 오신 걸 환영합니다!\n\n대회가 시작되면, 가시덤불 골짜기 전역의 낚시터에서 맛둥어를 낚을 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7615, 'koKR', '어서 오게. 나는 라스타칸 님의 종복인 엑잘이라고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7616, 'koKR', '$c 친구, 미안하지만 알터랙 계곡에서 살아남을 수 있으려면 더 많은 경험을 쌓아야 한다네.', '$c 친구, 미안하지만 알터랙 계곡에서 살아남을 수 있으려면 더 많은 경험을 쌓아야 한다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7634, 'koKR', '마력의 보물은 고대 구루바시 제국의 유물로서 우리 잔달라 부족이 찾고 있는 물건이지요. 우리에겐 가치가 엄청날 뿐 아니라 고대 제국에서 사용하던 마법의 힘이 잠들어 있다고 믿고 있습니다.$B$B줄구룹에서는 세 가지 보물을 발견하게 될 겁니다. 바로 주화와 장신구, 그리고 고대 전투 장비들이지요. 우리가 원하는 만큼 가져오면 상으로 잔달라 부족이 제작한 물건 중에서 가장 훌륭한 것을 받게 될 겁니다.', '마력의 보물은 고대 구루바시 제국의 유물로서 우리 잔달라 부족이 찾고 있는 물건이지요. 우리에겐 가치가 엄청날 뿐 아니라 고대 제국에서 사용하던 마법의 힘이 잠들어 있다고 믿고 있습니다.$B$B줄구룹에서는 세 가지 보물을 발견하게 될 겁니다. 바로 주화와 장신구, 그리고 고대 전투 장비들이지요. 우리가 원하는 만큼 가져오면 상으로 잔달라 부족이 제작한 물건 중에서 가장 훌륭한 것을 받게 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7635, 'koKR', '이 서판에는 고대의 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다. 하지만 당신은 아무리 살펴봐도 그 의미를 알아낼 수가 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7636, 'koKR', '이 서판에는 광기의 구루바시 모조를 만드는 데 필요한 고대 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7637, 'koKR', '이 서판의 표식에는 고대의 도식과 섬뜩한 힘의 문구가 새겨져 있습니다.$B$B연금술 조제법인 것 같지만, 당신의 실력으로는 이해하기 어렵습니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7638, 'koKR', '낚시는 느긋하게 할 수 있다는 점이 장점인 것 같습니다. 지난 일들을 회상한다든가 장래 계획을 세운다든가 생각할 시간이 생기니까 말이에요.$B$B아, 그리고 술 마시기에 아주 좋은 핑곗거리이기도 하지요. 아주 코가 비뚤어지도록 말입니다, 하하.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7639, 'koKR', '제 줄자를 다시 가져다주셔서 감사합니다, $n! 이것만 있으면 더 큰 물고기를 낚을 수 있다고요, 장담합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7640, 'koKR', '가즈란카를 낚으려면 특별한 진흙노린재 미끼가 필요할 겁니다. 내가 직접 만드는 물건이지요!$B$B일반 미끼로는 안 됩니다. 진흙노린재가 필요해요... 미끼에 꿰어서 그 지독한 썩은 내를 풍겨야 하거든요!$B$B진흙노린재를 잡으면 줄구룹에 있는 페이글의 낚시터로 가서 미끼를 던진 다음... 술이나 한 잔 들이켜며 기다리세요... 하지만 너무 오래 기다릴 필요는 없을 겁니다. 틀림없이 가즈란카가 소란을 떨며 나타날 테니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7641, 'koKR', '*위잉* *철컥*\n\n낚시로봇 5000은 질 좋은 희귀종 물고기를 가져오면 내트 페이글이 수여하는 특별한 낚시용품으로 보상하도록 설계되어 있습니다. 물고기 요청 중...\n\n*툭* *지지지*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7642, 'koKR', '미안하지만, 아라시 분지에는 좀 더 강해진 다음에 가야겠군.', '미안하지만, 아라시 분지에는 좀 더 강해진 다음에 가야겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7643, 'koKR', '철혈의 그리렉$B$B방랑자. 그의 힘과 전투에 대한 열망이 오래 기억되기를...$B$B그리렉은 지금 먼 곳에 있지만 언젠가는 돌아올 것입니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7644, 'koKR', '용사의 전당으로 가게. 포세이큰 파멸단의 데제 스노우베인이 아라시 분지로 가는 걸 도와 줄 걸세.', '용사의 전당으로 가게. 포세이큰 파멸단의 데제 스노우베인이 아라시 분지로 가는 걸 도와 줄 걸세.', '포세이큰을 도와 아라시 분지에서 인간들과의 한판 벌이고 싶은 건가? 용사의 전당으로 가서 데제 스노우베인과 얘기를 해 보게.', '포세이큰을 도와 아라시 분지에서 인간들과의 한판 벌이고 싶은 건가? 용사의 전당으로 가서 데제 스노우베인과 얘기를 해 보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7645, 'koKR', '진흙노린재는 유별나게 냄새가 지독한 어종인데, 특히 열대 수역을 좋아한답니다. 그중에서도 냄새가 제일 지독한 줄리안 진흙노린재는 김이 모락모락 피어오르는 줄구룹의 수역에서만 발견할 수 있지요.$B$B제 생각엔 그곳에 가즈란카가 나타나게 된 것도 줄리안 진흙노린재 때문이 아닌가 싶군요. 트롤들은 자신들이 믿는 여러 신 중 하나라고 얘기하겠지만 말입니다...$B$B어떤 얘기를 믿든 그거야 당신이 알아서 할 일이지만, 아무튼 제 말 잘 들어 두세요. 내 미끼', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7646, 'koKR', '왕실로 가. 너 말로리 휠러 경 만나. 난 무서워서 못 만나.', '왕실로 가. 너 말로리 휠러 경 만나. 난 무서워서 못 만나.', '아라시 고원! 뺏어야 해! 물렁물렁한 인간들한테서... 말로리 휠러 경이 보내준다.', '아라시 고원! 뺏어야 해! 물렁물렁한 인간들한테서... 말로리 휠러 경이 보내준다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7648, 'koKR', '정기의 봉우리 아래 예언의 웅덩이로 가서 마틴 린지를 찾아보십시오. 아라시 분지로 가는 걸 도와 줄 겁니다.', '정기의 봉우리 아래 예언의 웅덩이로 가서 마틴 린지를 찾아보십시오. 아라시 분지로 가는 걸 도와 줄 겁니다.', '아라시 분지에서 포세이큰 파멸단을 도와 아라소르 연맹에 맞서 싸우고 싶으십니까? 좋습니다! 그럼, 마틴 린지에게 도움을 청해야겠군요. 예언의 웅덩이로 가서 찾아보십시오.', '아라시 분지에서 포세이큰 파멸단을 도와 아라소르 연맹에 맞서 싸우고 싶으십니까? 좋습니다! 그럼, 마틴 린지에게 도움을 청해야겠군요. 예언의 웅덩이로 가서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7649, 'koKR', '아라시 분지에서 포세이큰과 전쟁을 벌이고 있는 인간들이 지원을 요청하고 있습니다. 전투의 전당으로 가서 인간 대표 도날 오스구드를 만나 보십시오.', '아라시 분지에서 포세이큰과 전쟁을 벌이고 있는 인간들이 지원을 요청하고 있습니다. 전투의 전당으로 가서 인간 대표 도날 오스구드를 만나 보십시오.', '아라시 분지에서 아라소르 연맹은 포세이큰의 손으로부터 선조의 영토를 되찾기 위해 투쟁하고 있습니다. 도와 주실 생각이 있다면 전투의 전당에 있는 도날 오스구드를 만나보십시오.', '아라시 분지에서 아라소르 연맹은 포세이큰의 손으로부터 선조의 영토를 되찾기 위해 투쟁하고 있습니다. 도와 주실 생각이 있다면 전투의 전당에 있는 도날 오스구드를 만나보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7650, 'koKR', '아라소르 연맹이 포세이큰 파멸단을 상대로 힘겨운 전투를 벌이고 있는 아라시 분지로 가려면 스톰윈드 왕궁의 국왕 알현실에 있는 영주 하티셈을 찾으십시오. 그녀가 도와 줄 겁니다.', '아라소르 연맹이 포세이큰 파멸단을 상대로 힘겨운 전투를 벌이고 있는 아라시 분지로 가려면 스톰윈드 왕궁의 국왕 알현실에 있는 영주 하티셈을 찾으십시오. 그녀가 도와 줄 겁니다.', '아라소르 연맹은 아라시 분지에서 참으로 훌륭한 일을 추진하고 있습니다. 그런데 저 끔찍한 언데드와 호드 패거리를 방해를 하니 정말 안타까운 노릇이지요. 영주 하티솀이 당신을 아라시 분지로 안내해 드리기 위해 스톰윈드 왕궁의 국왕 알현실에서 기다리고 있을 겁니다.', '아라소르 연맹은 아라시 분지에서 참으로 훌륭한 일을 추진하고 있습니다. 그런데 저 끔찍한 언데드와 호드 패거리를 방해를 하니 정말 안타까운 노릇이지요. 영주 하티솀이 당신을 아라시 분지로 안내해 드리기 위해 스톰윈드 왕궁의 국왕 알현실에서 기다리고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7651, 'koKR', NULL, '아라시 분지에 사는 인간들이 지금 필사적으로 도움을 청하고 있습니다. 전사의 정원으로 가서 케라스 울프하트라는 자와 얘기해 보십시오. 그대가 오기를 기다리고 있을 겁니다.', '그것이 자네의 뜻이라면, $c, 전사의 정원에 있는 케라스 울프하트와 이야기하게. 아라소르 연맹의 대표이니 아라시 분지로 가는 걸 도와줄 걸세.', '그곳으로 가려면 전사의 정원에 있는 케라스 울프하트와 얘기해 보십시오. 아라소르 연맹 대표이니까 아라시 분지로 가는 걸 도와 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7652, 'koKR', '트롬카! $c|1이여;여;, 전쟁노래 협곡으로 가서 호드를 위해 싸울 준비는 됐나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7653, 'koKR', NULL, '안녕하세요, $n... 전쟁노래 협곡으로 보내드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7654, 'koKR', '$n, 은빛날개 파수대를 반드시 물리쳐야 하네! 전쟁노래 협곡에서 싸울 준비는 됐나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7655, 'koKR', '록타르 오가르! 우리를 위해 전쟁노래 협곡에서 싸우기 위해 온 건가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7656, 'koKR', NULL, '$C|1이여;여;, 전쟁노래 협곡에서는 지금 그대에게 도움을 요청하고 있습니다. 우리를 도와 전쟁노래 정찰대에 맞서 주십시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7657, 'koKR', '젊은이, 알터랙 계곡으로 준비는 됐습니까? 듣자하니, 호드 녀석들이 매를 벌고 있다던데 나 대신 혼 좀 내십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7658, 'koKR', '$n, 알터랙 계곡에서 우리가 상대할 적이 도대체 어떤 놈들인지는 아십니까? 바로 서리늑대 부족입니다. 준비는 됐겠지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7659, 'koKR', '스톰파이크 경비대를 반드시 섬멸해야 하네! 알터랙 계곡으로 갈 준비는 됐나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7660, 'koKR', NULL, '록타르! $c|1이여;여;, 지금 알터랙 계곡에서 도움을 요청하고 있네. 자네 이름을 지원병 명단에 올려도 되겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7661, 'koKR', '알터랙 계곡에서 우리 부대가 승리를 거머쥐기 위해서는 지혜로운 영웅이 필요합니다. 당신이라면 우리 부대를 이끌 만한 인물로 보이는데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7662, 'koKR', '$n, 당신이 알터랙 계곡으로 가는 길을 찾으러 온 거라면 참 좋겠는데... 우린 지금 그 어떤 도움이라도 절실히 필요한 상황이라서 말이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7663, 'koKR', NULL, '자칭 아라소르 연맹이라고 하는 인간 놈들이 아라시 분지에서 우릴 몰아낼 궁리를 하고 있어. 그렇게는 못 하지! 놈들에게 가서 곧 그 땅을 떠날 장본인은 우리 파멸단이 아니라 바로 그들이라는 걸 똑똑히 가르쳐 주게. 준비됐나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7664, 'koKR', '아라시 분지는 한때 우리 고향이었습니다. 당신이 도와 준다면 다시 우리 땅이 될 겁니다! $c|1이여;여;, 우리를 도와주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7665, 'koKR', '$n, 무슨 일로 오셨소? 저 파멸단 놈들로부터 아라시 분지를 되찾는 걸 도우러 왔다면 언제나 환영이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7666, 'koKR', NULL, '$n, 기다리고 있었어요. 준비는 됐나요? 아라시 분지로 가서 우리를 도와주세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7667, 'koKR', '자네 스스로 아라소르 연맹을 물리칠 만한 능력이 있다고 생각하나? 그렇다면 정말로 좋겠지만... 여긴 뭐하러 온 게야? 아까운 내 시간만 축내러 온 건 아니겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7668, 'koKR', '보아하니 자네는 확실히 보기 드물게 용감한 $C같긴 하네만 그래도 아직은 좀 더 실력을 갈고 닦아야겠군. 아라시 분지에서 포세이큰의 대의를 위한 전쟁에 동참할 기회를 줄 수 있을 듯한데... 자네 생각은 어떤가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7669, 'koKR', '철혈의 그리렉$B$B방랑자. 그의 힘과 전투에 대한 갈증이 길이 기억되기를.$B$B이제 그리렉은 광란의 경계에서 배회하고 있다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7670, 'koKR', '몽술사 하자라$B$B악몽의 힘은 그의 것, 적들이 영원한 잠에 빠지기를...$B$B하자라는 지금 먼 곳에 있지만 언젠가는 돌아올 것입니다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7673, 'koKR', '폭풍칼날 레나타키$B$B고통은 그의 혈액이요, 공포는 그의 동지일지니. 언젠가 살육의 기쁨과 함께 돌아오기를.$B$B이제 레나타키는 광란의 경계에 살고 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7674, 'koKR', '폭풍술사 우슐레이$B$B그 힘은 곧 하늘, 비, 그리고 산산이 부서진 대지의 힘일지니, 다시 한번 구루바시의 아버지로 군림하기를...$B$B지금 우슐레이는 먼 곳에 있지만 언젠가는 돌아올 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7676, 'koKR', '안녕하신가! 가시덤불 골짜기에서 열리는 멋진 낚시왕 선발대회 홍보차 들렀네! 참가 자격은 가시덤불 골짜기에서 생존할 만큼 강하고 배짱 있는 자, 그리고 그곳 수역에서 낚시 좀 할 만한 기술을 갈고 닦은 자에게 주어지지.$B$B기량을 좀 더 닦거든 다시 오게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7677, 'koKR', '정말 반가군! 낚시 기술을 한 번 겨뤄 보고 싶나? 딱 좋은 곳을 하나 추천하지! 이번 일요일에 가시덤불 골짜기에서 낚시왕 선발대회가 열린다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7678, 'koKR', '아직 덜 여물었군! 저리 비켜!', '아직 덜 여물었군! 저리 비켜!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7679, 'koKR', '$n, 우린 아라시 분지에서 상상도 못 할 정도로 많은 도움을 필요로 하고 있네. 어려운 시기에는 그만큼 큰 명예와 좋은 평판을 얻을 수 있는 법이지. 내 자네에게 간청하건대, 이 도시에 있는 아라시 분지 전투모병관을 찾아가 얘기를 나눠보게.', '$n, 우린 아라시 분지에서 상상도 못 할 정도로 많은 도움을 필요로 하고 있네. 어려운 시기에는 그만큼 큰 명예와 좋은 평판을 얻을 수 있는 법이지. 내 자네에게 간청하건대, 이 도시에 있는 아라시 분지 전투모병관을 찾아가 얘기를 나눠보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7680, 'koKR', '관심을 보여줘 고맙네. 왕실에 가 보면 말로리 휠러 경이 어둠의 여왕님과 함께 있을 거야.', '관심을 보여줘 고맙네. 왕실에 가 보면 말로리 휠러 경이 어둠의 여왕님과 함께 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7681, 'koKR', '좋아, 아주 좋아! 이 도시에서 명예의 골짜기 용사의 전당으로 가서 데제 스노우베인과 얘기해 보게나.', '좋아, 아주 좋아! 이 도시에서 명예의 골짜기 용사의 전당으로 가서 데제 스노우베인과 얘기해 보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7683, 'koKR', '$c|1이여;여;, 알터랙 계곡에서 우리를 도우려면 더 강해지셔야 합니다.', '$c|1이여;여;, 알터랙 계곡에서 우리를 도우려면 더 강해지셔야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7684, 'koKR', '안녕하신가? 지금 알터랙 계곡에서는 대대적인 지원을 요청하고 있네. 큰 명예를 얻고 자네의 이름을 떨칠 기회란 말이지. 스톰파이크 경비대에 맞서는 우리의 전투에 참여하겠나?', '안녕하신가? 지금 알터랙 계곡에서는 대대적인 지원을 요청하고 있네. 큰 명예를 얻고 자네의 이름을 떨칠 기회란 말이지. 스톰파이크 경비대에 맞서는 우리의 전투에 참여하겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7685, 'koKR', '자네의 가문과 선조에게 명예가 있기를! 명예의 골짜기, 용사의 전당으로 가면 카르타 블러드스날을 만날 수 있을 것일세.', '자네의 가문과 선조에게 명예가 있기를! 명예의 골짜기, 용사의 전당으로 가면 카르타 블러드스날을 만날 수 있을 것일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7687, 'koKR', '좋습니다, $n. 언더시티의 왕실로 가면 그리즐 하프메인이 있을 겁니다. 알터랙 계곡에서 큰 명예를 얻기를 빌겠습니다.', '좋습니다, $n. 언더시티의 왕실로 가면 그리즐 하프메인이 있을 겁니다. 알터랙 계곡에서 큰 명예를 얻기를 빌겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7688, 'koKR', '안타깝지만, 당신은 아직 전쟁노래 협곡에서 살아남을 수 있을 만큼 강한 분은 아니시로군요.', '안타깝지만, 당신은 아직 전쟁노래 협곡에서 살아남을 수 있을 만큼 강한 분은 아니시로군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7689, 'koKR', '$c|1이여;여;, 은빛날개 파수대와 전쟁이 벌어지는 전쟁노래 협곡에서는 지금 당신의 도움을 절실히 필요로 하고 있습니다. 성공만 하면 큰 명예는 물론 전쟁노래 정찰대에서 당신의 평판도 크게 오를 겁니다! 자, 전장에 참여할 용기가 있습니까?', '$c|1이여;여;, 은빛날개 파수대와 전쟁이 벌어지는 전쟁노래 협곡에서는 지금 당신의 도움을 절실히 필요로 하고 있습니다. 성공만 하면 큰 명예는 물론 전쟁노래 정찰대에서 당신의 평판도 크게 오를 겁니다! 자, 전장에 참여할 용기가 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7690, 'koKR', '전투의 전당으로 가 보게. 브락굴 데스브링어가 전쟁노래 협곡으로 가는 자들을 돕기 위해 기다리고 있지. 이런 얘길 나누게 되어 아주 뿌듯하군. 명예의 골짜기로 가서 찾아보게나.', '전투의 전당으로 가 보게. 브락굴 데스브링어가 전쟁노래 협곡으로 가는 자들을 돕기 위해 기다리고 있지. 이런 얘길 나누게 되어 아주 뿌듯하군. 명예의 골짜기로 가서 찾아보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7691, 'koKR', '현명한 선택일세, $n. 수렵의 봉우리로 가서 케르굴 블러드액스를 찾아보게나. 전쟁노래 협곡으로 가도록 도와 줄 테니까.', '현명한 선택일세, $n. 수렵의 봉우리로 가서 케르굴 블러드액스를 찾아보게나. 전쟁노래 협곡으로 가도록 도와 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7692, 'koKR', '큰 명예와 영광을 얻게 될 자로군! 이 도시의 왕실로 가서 쿠르덴 블러드클로와 상의해 보게나.', '큰 명예와 영광을 얻게 될 자로군! 이 도시의 왕실로 가서 쿠르덴 블러드클로와 상의해 보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7693, 'koKR', '$c|1이여;여;, 안됐지만 자네를 보아하니 알터랙 계곡에서 오래 살아남을 수 있을 것 같지가 않아. 경험을 좀 더 쌓거든 다시 찾아오도록!', '$c|1이여;여;, 안됐지만 자네를 보아하니 알터랙 계곡에서 오래 살아남을 수 있을 것 같지가 않아. 경험을 좀 더 쌓거든 다시 찾아오도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7694, 'koKR', '지금 알터랙 계곡에서 서리늑대 부족과 대치하고 있는 스톰파이크 경비대는 그 어느 때보다 절실히 지원을 요청하고 있네. 그만큼 큰 명예와 좋은 평판을 얻을 기회지! 전장에 참여해 보겠나?', '지금 알터랙 계곡에서 서리늑대 부족과 대치하고 있는 스톰파이크 경비대는 그 어느 때보다 절실히 지원을 요청하고 있습니다. 그만큼 큰 명예와 좋은 평판을 얻을 기회지요! 전장에 참여해 보시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7696, 'koKR', NULL, '낚시왕 선발대회를 위해 낚시의 대가이신 바스베이트 님이 이곳 수역에 질 좋은 맛둥어를 잔뜩 풀어놓으셨어요!\n\n참, 낚시왕이 뽑힌 후에 맛둥어를 제게 가져오는 분에게는 5마리당 적당한 가격을 쳐 드리지요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7697, 'koKR', '$c|1이여;여;, 훌륭한 결정일세. 전투의 전당으로 가면 우리 전투모병관 글로드룸 스틸비어드를 찾을 수 있을 거야. 행운을 비네, $n!', '$c|1이여;여;, 훌륭한 결정일세. 전투의 전당으로 가면 우리 전투모병관 글로드룸 스틸비어드를 찾을 수 있을 거야. 행운을 비네, $n!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7699, 'koKR', '생각은 고맙지만, 안타깝게도 당신은 아라시 분지에서 위험을 이겨내기에는 아직 경험이 충분치 않군요.', '생각은 고맙지만, 안타깝게도 당신은 아라시 분지에서 위험을 이겨내기에는 아직 경험이 충분치 않군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7700, 'koKR', '아라시 분지에서 어려운 싸움을 하고 있는 우리를 도와 주시렵니까? 사실 그 어느 때보다 더 큰 명예와 영광을 얻을 수 있는 좋은 기회죠. 당신이 힘을 빌려 준다면 포세이큰 파멸단과의 싸움에서 분명 전세를 역전시킬 겁니다. 당신을 믿어도 되겠죠?', '아라시 분지에서 어려운 싸움을 하고 있는 우리를 도와 주시렵니까? 사실 그 어느 때보다 더 큰 명예와 영광을 얻을 수 있는 좋은 기회죠. 당신이 힘을 빌려 준다면 포세이큰 파멸단과의 싸움에서 분명 전세를 역전시킬 겁니다. 당신을 믿어도 되겠죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7701, 'koKR', '좋습니다, $n! 전사의 정원으로 가면 상급자들 옆에 케라스 울프하트가 서 있을 겁니다. 아라시 분지로 가는 길을 알려 줄 거예요. 항상 행운과 명예가 함께하기를...', '좋습니다, $n! 전사의 정원으로 가면 상급자들 옆에 케라스 울프하트가 서 있을 겁니다. 아라시 분지로 가는 길을 알려 줄 거예요. 항상 행운과 명예가 함께하기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7702, 'koKR', '$c|1이여;여;, 우리가 당신에게 신세를 지겠군요. 전투의 전당에서 도날 오스구드를 찾아보십시오. 아라시 분지로 가는 거라면 기꺼이 도와줄 겁니다.', '$c|1이여;여;, 우리가 당신에게 신세를 지겠군요. 전투의 전당에서 도날 오스구드를 찾아보십시오. 아라시 분지로 가는 거라면 기꺼이 도와줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7703, 'koKR', '좋습니다! 당신은 곧 아라시 분지에서 포세이큰 파멸단과 호드 패거리를 제거하여 아라소르 연맹을 위한 큰 공을 세우게 될 겁니다. 스톰윈드 왕궁의 국왕 알현실로 가서 영주 하티셈을 찾아보십시오. $n, 당신을 기다리고 있을 겁니다.', '좋습니다! 당신은 곧 아라시 분지에서 포세이큰 파멸단과 호드 패거리를 제거하여 아라소르 연맹을 위한 큰 공을 세우게 될 겁니다. 스톰윈드 왕궁의 국왕 알현실로 가서 영주 하티셈을 찾아보십시오. $n, 당신을 기다리고 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7704, 'koKR', '누구에게든 언젠가는 때가 오는 법... 그대의 삶은 아직 봄을 맞이했을 뿐입니다. 경험을 좀 더 쌓은 후에 다시 저를 찾아오세요.', '누구에게든 언젠가는 때가 오는 법... 그대의 삶은 아직 봄을 맞이했을 뿐입니다. 경험을 좀 더 쌓은 후에 다시 저를 찾아오세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7705, 'koKR', '우린 솔직히 말해서 전쟁노래 협곡의 전투를 위해 그 어떤 도움의 손길이라도 마다하지 않습니다. 우릴 돕는다면 그 어느 때보다 큰 명예를 얻을 수 있답니다. 그리고, 그대의 노고는 분명 은빛날개 파수대로부터 좋은 평판을 살 거고요. 전장에 참여하시겠습니까?', '우린 솔직히 말해서 전쟁노래 협곡의 전투를 위해 그 어떤 도움의 손길이라도 마다하지 않습니다. 우릴 돕는다면 그 어느 때보다 큰 명예를 얻을 수 있답니다. 그리고, 그대의 노고는 분명 은빛날개 파수대로부터 좋은 평판을 살 거고요. 전장에 참여하시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7706, 'koKR', '$n, 엘룬의 빛이 그대에게 비추기를! 전사의 정원으로 가면 우리 전투모병관 애살라스를 만날 수 있을 겁니다. 그대를 전쟁노래 협곡으로 인도해 드릴 거예요.', '$n, 엘룬의 빛이 그대에게 비추기를! 전사의 정원으로 가면 우리 전투모병관 애살라스를 만날 수 있을 겁니다. 그대를 전쟁노래 협곡으로 인도해 드릴 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7707, 'koKR', NULL, '마력의 보물은 우리 잔달라 부족이 찾고 있는 고대 구루바시 제국의 유물입니다. 우리에겐 수집 가치가 엄청날 뿐 아니라 고대 제국에서 사용되던 모조의 가장 강력한 힘이 포함되어 있다고 믿고 있답니다.$B$B아마 줄구룹에서 세 가지 보물을 발견하게 될 텐데, 바로 주화와 장신구, 고대 전투 장비들이랍니다. 우리가 원하는 만큼 가져오면 우리 잔달라 부족이 제작해 온 물건들 중에서 가장 훌륭한 것들로 보상하도록 하겠습니다.$B$B약속하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7708, 'koKR', '나이에 비해 아주 지혜로운 분이시군요. 우선 감사부터 드리지요. 전투의 전당에 있는 원탁 앞에 우리 전투모병관 리란드리스가 있을 겁니다. 그대를 전쟁노래 협곡으로 인도해 드릴 거예요.', '나이에 비해 아주 지혜로운 분이시군요. 우선 감사부터 드리지요. 전투의 전당에 있는 원탁 앞에 우리 전투모병관 리란드리스가 있을 겁니다. 그대를 전쟁노래 협곡으로 인도해 드릴 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7709, 'koKR', '은빛날개 파수대가 그대의 신세를 지게 되는군요. 우리 전투모병관 엘파란이 스톰윈드 왕궁에 어린 국왕과 함께 있을 겁니다. 여신의 가호가 있기를!', '은빛날개 파수대가 그대의 신세를 지게 되는군요. 우리 전투모병관 엘파란이 스톰윈드 왕궁에 어린 국왕과 함께 있을 겁니다. 여신의 가호가 있기를!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7711, 'koKR', '반갑습니다! 가시덤불 골짜기에서 낚시 실력을 겨루는 대회를 홍보하러 왔습니다. 참가하려면 그곳에서 살아남을 만큼 강해야 하고, 물고기를 낚아 올릴 만큼 낚시 실력도 갖춰야 합니다.$B$B자격을 더 갖춘 뒤 다시 찾아오세요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7712, 'koKR', '낚시의 달인이여, 만나서 반갑습니다! 아제로스 최고의 낚시꾼들과 솜씨를 겨뤄 보고 싶다면 잘 들으세요! 바로 이번 일요일에 가시덤불 골짜기에서 낚시왕 선발대회가 열린다니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7713, 'koKR', '마력의 보물은 강력한 구루바시 제국의 모조일세. 우리 잔달라 부족은 반드시 그 모조를 찾아야만 하네. 혈신이 우리를 파멸시키지 못하도록 말이야.$B$B줄구룹에는 세 가지 종류의 보물이 있다네. 주화, 장신구, 그리고 고대 전투 장비들을 찾게나. 이것들이 바로 보물이라네.$B$B지금 줄구룹으로 가서 적을 쓰러뜨리고 마력의 보물을 구해 우리 부족에게 가져다주게나. 그러면 우리의 존경과 전투 장비, 그리고 진정한 힘을 얻게 될 것이야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7714, 'koKR', '오늘은 이미 승자가 모두 나왔지만, 낚아 올린 맛둥어는 전부 장에게 팔 수 있습니다!\n\n잊지 마세요! 일요일엔 언제나 낚시 기술을 뽐낼 기회가 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7717, 'koKR', '내 뒤로 보이는 건 우리 잔달라 부족의 성소인 잔자의 제단일세. 혈신 학카르와 전쟁을 준비할 때 이곳에서 기원을 올리고 결의를 다지지.$B$B줄구룹 내에서 찾을 수 있는 학카리 장신구 중 아무것이나 가져와 이 제단에서 파괴하여 스스로 자네의 가치를 우리 부족에게 입증해 보이도록 하게나. 또 줄구룹에서 찾을 수 있는 일련의 주화들을 가져오면 우리 잔달라 명예 징표와 교환해 주지. 내가 찾고 있는 주화들을 가져오면 반드시 보상을 하겠단 말일세!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7718, 'koKR', '잔달라 부족 트롤들은 이곳까지 오기 위해 먼 길을 왔고 큰 고통을 겪었소. 하지만 아무것도 하지 않는다면... 멸망을 자초하게 될 뿐이오.', '잔달라 부족 트롤들은 이곳까지 오기 위해 먼 길을 왔고 큰 고통을 겪었소. 하지만 아무것도 하지 않는다면... 멸망을 자초하게 될 뿐이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7720, 'koKR', '우리 잔달라 트롤들은 지금 이 세계에 닥친 위협을 묵인할 수 없어 머나먼 섬에서 이곳까지 건너왔네.$B$B원정대의 지도자인 몰소르 님은 가시덤불 골짜기 북부 해안에 있는 요잠바 섬으로 우리를 인도하셨고, 지금도 고대 트롤 도시로 들어가 모험을 감행할 용맹한 영웅들을 모으고 있지... 바로 줄구룹으로 갈 영웅들 말일세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7721, 'koKR', '우리 잔달라 트롤은 현재 이 세계에 닥친 위협을 못 본체 할 수 없어 머나먼 섬에서 이곳으로 건너왔네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7722, 'koKR', '누군가 그러더군요... 다 큰 개에게는 새로운 재주를 가르치지 못한다고! 다행히도 그대에게는 해당하지 않는 말인 것 같습니다.$B$B자, 야수가 배운 기술을 모두 취소하고 싶으신가요?', '누군가 그러더군요... 다 큰 개에게는 새로운 재주를 가르치지 못한다고! 다행히도 그대에게는 해당하지 않는 말인 것 같습니다.$B$B자, 야수가 배운 기술을 모두 취소하고 싶으세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7723, 'koKR', '난 병참장교 러더퍼드 트윙이라고 하네. 이곳 아라시 분지에 주둔하는 파멸단에 물품을 보급하고 있지. 우리 파멸단으로부터 좋은 평판을 얻을수록 더욱 훌륭한 물건들을 살 수 있다네. 참, 수리할 물건이 있으면 고쳐줄 테니 가지고 오도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7724, 'koKR', '나는 병참장교 사무엘 호키라고 하오. 이곳 아라시 분지에 주둔한 아라소르 연맹에 물품을 보급하고 있소이다. 우리 연맹으로부터 좋은 평판을 얻을수록 더욱 좋은 물건들을 살 수 있소. 참, 부서진 장비가 있으면 수리해줄 테니 잊지 마시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7725, 'koKR', NULL, '전쟁노래 협곡에서 호드와 벌이는 싸움은 절대 질 수 없는 전투입니다. 은빛날개 파수대에서는 파수대의 명예와 우리의 땅을 지키기 위해 싸우고 있습니다. 저 오크들이나 잘못된 길을 가고 있는 우리의 동맹도 이러한 우리의 의지를 앗아갈 순 없을 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7726, 'koKR', '이곳 잿빛 골짜기에서 보급품을 비축하는 우리의 노력을 지켜내는 임무는 쉽지 않다네. 그러나 우리는 절대로 전투를 피해 꽁무니를 빼지 않지! 나이트 엘프와 녀석들의 동맹은 우리 앞에 무릎 꿇게 될 것이야!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7727, 'koKR', '아이고, 불쌍한 사람 같으니. 머리부터 발끝까지 모래에 뒤덮였군요! 여기 아름다운 오아시스에서 푹 쉬고 기운을 차리세요.', '아이고, 불쌍한 사람 같으니. 머리부터 발끝까지 모래에 뒤덮였군요! 여기 아름다운 오아시스에서 푹 쉬고 기운을 차리세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7728, 'koKR', '전 주문 시전에 필요한 룬 및 여러 가지 재료와 연금술 재료를 세나리온 요새에 공급하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7729, 'koKR', '거대한 악의 기운이 꿈틀대고 있는데 느껴지십니까?$B$B당연히 못 느끼실 겁니다! 자, 갑옷과 무기를 주십시오. 말끔하게 고쳐드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7730, 'koKR', NULL, '이런! 물건이 얼마 남지 않았네요. 저 지독한 고블린은 어쩜 저렇게 오래 버틸 수 있죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7731, 'koKR', '뒤를 보십시오. 우리 주변의 땅이 흔들릴 때마다 곤충 집이 움직이고 있습니다.$B$B천 년 전의 약속을 지킬 때가 온 것입니다. 퀴라지가 전쟁을 계획하고 있으니 사막에 다시 한번 소용돌이가 일 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7732, 'koKR', '왜 이제서야 온 겁니까? 할 일이 산더미 같은데... 이해할 수 없군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7733, 'koKR', '마랄리스 지휘관님이 요즘 제정신이 아닙니다. 부인이 남부 사막의 고대 발굴지에서 흔적도 없이 실종되셨습니다. 정말 이상한 일이 아닐 수 없습니다.$B$B별다른 단서는 없지만 말입니다. 혹시 이 일을 맡으실 생각은 없습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7734, 'koKR', NULL, '저 소리 들리세요? 날이 갈수록 윙윙거리는 소리가 점점 커지고 있어요. 아무래도 수정이 벌레들을 흥분시키는 것 같아요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7735, 'koKR', '하늘을 보십시오, $c|1이여;여;. 이 지역은 천 년 동안 용군단이 나타난 적이 없습니다! 내 느낌으로는 퀴라지가 무슨 일을 꾸미고 있는 게 분명합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7736, 'koKR', '브론즈비어드 님이 또 사라지셨네! 당신 형님의 반만이라도 닮으셨다면 좋으련만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7737, 'koKR', '불타는 밀짚인형의 재는 마력을 뿜어냅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7738, 'koKR', '불타는 밀짚인형의 재는 마력을 뿜어냅니다. 이미 당신의 얼굴에는 재가 발라져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7739, 'koKR', '$c! 할로윈 축제 즐겁게 보내!', NULL, '너 사탕 좋아해? 난 좋아하는데...', NULL, '포세이큰 만세! 우리에게 축복을!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7740, 'koKR', NULL, '$c, 밀짚인형 축제에 온 것을 환영하네!$B$B우리 포세이큰은 밀짚인형을 제물로 태워서 할로윈 축제의 전통을 기념하지. 우리를 리치 왕과 스컬지의 속박에서 구원하고 멋진 복수를 해 주신 밴시 여왕님을 기리는 거야. 그때야 우린 비로소 완전한 자유를 얻은 것이라네...$B$B축제를 멋지게 즐기고 싶다면, 밀짚인형이 불탈 때 그 아래 흩어진 재를 얼굴에 바르게!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7741, 'koKR', '거기 계셨군! 당신 몸이 더 좋아진 것 같은데... 남녘해안 방어를 좀 도와 주시오!$B$B저 악독한 포세이큰 놈들이 총공격을 감행할 것 같소. 바로 할로윈 축제가 돌아오지 않았겠소?! 놈들은 틀림없이 축제를 이용해 쳐들어올 거요. 그렇게 바쁜 일이 없다면 우리를 도와 주시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7742, 'koKR', '우리가 먼저 공격해야 한다. 과거의 실수를 되풀이해서는 절대로 안 되느니라...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7744, 'koKR', '이단자는 물러가라! 심연의 힘이 너를 심판할 것이다!', '이단자는 물러가라! 심연의 힘이 너를 심판할 것이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7746, 'koKR', NULL, '세나리온 요새에 오신 것을 환영합니다. 여기는 실리시드의 세력이 가장 강한 곳입니다. 실리시드를 몰아낼 수 있도록 꼭 도와주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7747, 'koKR', NULL, '다시 만나게 되어 반갑습니다, $n. 도와주신 덕분에 보급선이 아주 안전해졌습니다. 잘 아시겠지만 지금과 같은 대규모 전투에서는 물자 보급이 정말 중요하답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7748, 'koKR', NULL, '황혼의 망치단에서 탈영한 자가 운이 없었던 것일까요? 산맥 남동쪽을 샅샅이 조사해 주셨으면 합니다. 그곳에 신비에 싸인 은둔자가 살고 있다는 소문이 무성합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7749, 'koKR', '너처럼 하찮은 존재가 어떻게 심연의 군주님과 교신할 수 있단 말이냐!', '너처럼 하찮은 존재가 어떻게 심연의 군주와 교신할 수 있단 말이냐!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7751, 'koKR', '죽음의 갈고리를 잡겠다는 말입니까, $n? 반드시 성공하기 바랍니다. 죽음의 갈고리에게 이번 주에만 벌써 부하 둘을 잃었습니다. 부디 행운이 함께하시길...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7752, 'koKR', '목숨을 구해 주셔서 감사합니다! 저는 몸이 회복될 때까지 좀 누워 있어야 할 것 같네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7753, 'koKR', '누구시죠? 여기가 어디죠? 아... 힘이 다 빠졌어요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7754, 'koKR', '감히 심연의 군주에게 맞서는 놈이 누구냐? 죽고 싶은 것이 틀림없구나!', '감히 심연의 군주에게 맞서는 놈이 누구냐? 죽고 싶은 것이 틀림없구나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7755, 'koKR', '편히 앉게나. 얘기가 좀 길다네.$B$B우리가 실리더스에 처음 도착했을 때 여군주 마랄리스는 세나리온 요새의 나이트 엘프 중 가장 먼저 원정대에 참가했지. 우리는 지극히 평범한 일부터 진행했다네. 사라진 유물을 찾기 위해 곤충 집을 헤집을 조사단을 구성했지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7756, 'koKR', '물론이지! 곤충 집에는 온갖 실리시드가 득실거렸고 우리를 보면 바로 달려들었네.$B$B하이브레갈에서 이상한 문자가 새겨진 수정을 발견하기 전까지는 사실 별문제가 없었지. 그런데 여군주 마랄리스가 그 수정을 보자마자 뭔가에 홀린 듯 가까이 다가갔네. 마치 불을 보고 달려드는 나방 같았지! 그 작고 고운 뺨을 수정에 갖다 대더니 갑자기 기절했네. 우리는 깜짝 놀라 여군주 마랄리스를 둘러업고 최대한 빨리 그곳을 빠져나왔네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7757, 'koKR', '우리는 여군주 마랄리스를 지휘관님께 데리고 갔네. 세나리온 의회의 드루이드라면 그녀를 고칠 수 있을 거로 생각했기 때문이지. 역시 드루이드는 뭔가 다르더군. 그들 덕분에 여군주 마랄리스는 정신을 차렸네. 다행히 그녀도 회복하고 해서 우리는 다시 조사를 시작할 수 있을 거라 생각했지.$B$B그 후 몇 주 동안은 브란 님도 돌아오실 예정이었고 해서 조직도 정비해 가며 별문제 없이 지냈지. 그러던 어느 날 뜻밖에 그녀가 우리 야영지에 찾아왔네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7758, 'koKR', '내 얘기 제대로 듣고 있는 건가? 그럼 내가 대체 누구 얘기를 하고 있겠나? 그래, 맞아. 여군주 마랄리스였네. 어쨌든 우리를 찾아왔는데 기분이 썩 좋아 보이지 않았네. 그러더니 부탁을 하더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7759, 'koKR', '하이브레갈에 다시 가 달라고 했다네! 브란 님은 한동안 말이 없다가 군대의 지원 없이는 하이브레갈에 들어갈 방법이 없다고 하셨지. 그때는 하이브레갈이 더 위험한 곳으로 변해 있었으니 말이야. 그 끔찍한 벌레들의 수가 우리가 처음 들어갔을 때보다 3배는 많아진 것 같았지.$B$B그 말을 듣자마자 나탈리아가 갑자기 미쳐 버렸네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7760, 'koKR', '미쳤다는 게 무슨 말인지 모르는 건가? 정신이 나갔단 말일세! 그녀는 우리에게 미친 듯이 달려들었네. 평소에는 여자를 절대 때리지 않는 내가 그녀의 공격에 당해 잠시 의식을 잃었다 깨보니 무척이나 화가 나더군. 브란님과 프랭칼 그리고 나는 원숭이와 함께 온 힘을 다해 그녀를 제압했네! 사실 그녀를 제압했다는 자체가 기적이었다고 할 수 있지. 그녀는 마치 누군가에게 조종을 당하는 것 같았다네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7761, 'koKR', '그걸 누가 알겠나? 아무튼 그 후로는 그녀를 본 적이 없네. 프랭칼이라면 쓸 만한 정보를 많이 알고 있을 걸세.$B$B그런데 얘기의 주제를 흐릴까 봐 이런 말은 안 하려고 했네만... 자네가 맡은 임무가 중요하다는 건 잘 알고 있네. 하지만 우리가 하고 있는 일도 중요하단 말일세. 그것도 매우 말이야! 아이언포지에 병력을 요청한 게 대체 언젠데 아직 아무런 소식이 없다는 게 말이 되는가? 이 넓은 지역을 방어하느라 말라 죽을 지경이네. 지휘관님께 보고한', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7762, 'koKR', '이런, 또 그 이야기로군... 우선 앉으세요.$B$B루트거에게 대충은 들었을 테니 사소한 내용은 건너뛰고 핵심만 얘기하도록 하죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7763, 'koKR', '바로 그때! 부인이 잠깐 정신을 차리는 것 같더니 바로 곤충 집으로 들어갔습니다. 브란 님이 말릴 새도 없이 말입니다! 전투가 시작되기 전에 그녀는 누군가와 이야기하기 시작했죠. 아니 물건이었던 것 같기도 하고... 어쨌든 대화를 했습니다. 그렇게 점점 미쳐가는 것 같더니 한 번도 들어본 적이 없는 언어로 주문을 외우기 시작했어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7764, 'koKR', '그렇죠, 정말 이상한 일이죠! 브란 님과 루트거 그리고 저는 티탄의 두 종족인 바니르와 에시르의 언어까지 모두 38가지나 되는 언어를 알고 있는데 정말 이해할 수 없었어요. 물론 그 말은 원숭이의 언어도 아니었죠.$B$B그러니까 그녀가 무슨 말을 하는지는 몰랐지만 분명한 건 그곳에 저희 외에 다른 사람은 없었다는 겁니다. 그런데 그녀가 고개를 끄덕이더니 갑자기 공격을 시작하더군요! 그것도 저희를 완전히 죽일 둣이 말입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7765, 'koKR', '잘 들어 보세요. 우릴 공격한 건 여사제가 낼 수 있는 그런 힘이 절대 아니었어요! 그녀의 눈은 악마와 같이 붉게 충혈되어 있었고 입에는 거품을 물고 있었단 말입니다. 정말이에요! 그녀는 미친 듯이 괴성을 질러대며 다가왔는데 우리를 각자 다른 곳으로 몰아 영혼을 하나씩 약탈하려는 것 같았어요. 내 머릿속에서 어둠의 목소리가 들려오기 시작했답니다. 주위를 둘러보니 동료도 하나씩 정신을 잃어가고 있었지요. 모두 미쳐가고 있었던 겁니다! 만약 저 원숭이가 없', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7766, 'koKR', '물어볼 게 뭐가 있겠습니까? 녀석은 말 그대로 원숭이일 뿐입니다. 그러니까 원숭이는 브란 님의 얼굴이 모래에 처박히는 걸 보더니 광분해서 그녀에게 달려들었습니다. 원숭이가 아니었더라면 그 나이트 엘프 여사제의 공격을 막아내지 못했을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7767, 'koKR', '그다음은 말이죠... 그녀는 곤충 집으로 곧장 달리기 시작했습니다. 그런데 더 이상한 게 뭔지 아세요? 바로 그 저주받은 벌레들 중 단 한 마리도 그녀를 막지 않았다는 겁니다. 그녀는 수 세기동안 녀석들의 친한 친구였던 듯이 녀석들 모두를 지나쳐 들어갔습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7768, 'koKR', '그렇습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7770, 'koKR', '수정에 이해할 수 없는 복잡한 문양과 룬 문자가 새겨져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7771, 'koKR', '바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?', '바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7772, 'koKR', '바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다...', '바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7773, 'koKR', '바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신분을 증명했으니 네 얘기를 들어주도록 하지. 하지만 시간은 끌지 않도록 해라. 우리 의회는 너 같은 애송이의 쓸데없는 잡담 따윈 들어줄 시간이 없으니...', '바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신분을 증명했으니 네 얘기를 들어주도록 하지. 하지만 시간은 끌지 않도록 해라. 우리 의회는 너 같은 애송이의 쓸데없는 잡담 따윈 들어줄 시간이 없으니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7774, 'koKR', '바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B반갑네, 지휘관. 심연의 군주님께 전할 실리더스에 관한 새 소식이란 게 뭔가?', '바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B반갑네, 지휘관. 심연의 군주님께 전할 실리더스에 관한 새 소식이란 게 뭔가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7775, 'koKR', '돌에서 천둥 같은 목소리가 울려 퍼집니다...$B$B신도여, 네 계급장은 느껴지지만 군주의 반지는 없구나? 네가 정말 황혼의 망치단 지휘관인가, 아니면 윗사람들의 심부름이나 하는 자인가?', '돌에서 천둥 같은 목소리가 울려 퍼집니다...$B$B네 신분의 메달은 느껴지는군, 이교도여. 그런데 군주의 반지는 없단 말인가? 정말 황혼의 망치단 지휘관인가, 아니면 윗사람 심부름이나 하는 졸개인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7776, 'koKR', '바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B대체 무슨 일이냐? 애송이 이교도 놈이 달아나고 있구나! 그래, 도망쳐라, 벌레 같은 놈. 아니면 심연의 군주로부터 진노를 사게 될 것이다!', '바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B대체 무슨 일이냐? 애송이 이교도 놈이 달아나고 있구나! 그래, 도망쳐라, 벌레 같은 놈. 아니면 심연의 군주로부터 진노를 사게 될 것이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7778, 'koKR', '어디로 날아가고 싶습니까?', '어디로 날아가고 싶으세요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7779, 'koKR', '실리더스의 영혼이 우리를 부르고 있소, $n. 대지의 흐느낌이 뭔가 비통한 소식을 전하려는 듯 대지가 흐느끼고 있소...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7780, 'koKR', '안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 암호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네.', '안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 암호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7781, 'koKR', NULL, '$n! 그대의 여정을 시작할 준비가 되어 있기를 바랍니다. 여기 선스트라이더 섬에는 할 일이 아주 많답니다.$B$B아서스와 스컬지에게 태양샘이 파괴된 후로, 우리 종족은 거친 바다를 표류하는 신세가 되었지요. 그리고 이제 세상에서 잊혀지느냐 마느냐의 갈림길에 서 있습니다. 하지만, 이 상황은 바뀔 것입니다. 그대의 도움으로 우리는 지난날로 돌아갈 수 있을 것이며, 그대도 많은 것을 배울 것입니다.$B$B아웃랜드가 우리를 기다리고 있습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7782, 'koKR', NULL, '세나리온 의회는 현명한 판단력으로 이 세계의 많은 비밀을 밝혀냈습니다. 장인들은 이 드루이드들의 말에 귀를 기울여야 할 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7783, 'koKR', '유령 같은 형상이 불신에 찬 눈으로 당신을 바라보며 침묵합니다.', '유령 같은 형상을 하고 불신에 가득 찬 눈초리로 아무 말 없이 당신을 응시합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7784, 'koKR', '한때 태양 첨탑은 태양샘이 있던 아름다운 곳이었습니다. 비록 지금 우리의 삶은 완전히 엉망이 되어 버렸지만... 그래도 포기하지 않고 앞으로 나아갈 것입니다. 우리는 생존자들이니까요.$B$B이 험난한 시기에 블러드 엘프라면 반드시 누구에게도 의지하지 않고 살아남는 법을 배워야 합니다. 마법에 대한 끝없는 욕망에 빠져들기 전에 자신을 다스려야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7785, 'koKR', '블러드 엘프들이 살아남으려면 그대가 계속 우리를 도와주셔야 합니다! 다 같이 전력을 쏟아야 우리가 처한 어려움을 타개할 수 있습니다.$B$B일할 준비가 되었으면 시작해 봅시다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7786, 'koKR', '젊은 $c|1이여;여;, 아는 것이야말로 진정한 힘입니다. 그대는 현명하니 앞으로도 많은 것을 배울 수 있을 것이며, 그대보다 아는 것이 많은 이들에게도 귀를 기울일 줄 알게 될 겁니다.$B$B태양샘이 파괴되기 전, 우리는 어리석게도 완벽한 문명의 정점에 도달했다는 자만심에 빠져 있었습니다. 그 때문에 스컬지에게 무릎을 꿇고 말았죠. 어떤 면에서 보면 현실에 눈을 뜨는 계기가 되었지만요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7787, 'koKR', '연구에 결정적으로 중요한 순간에 찾아오셨군요! 그래도 괜찮습니다. 저와 함께 \'조용히\' 명상을 하신다면... 얼마든지 환영입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7788, 'koKR', NULL, '여행자님, 도시로 가시는 길이라면 중요한 일을 하나 맡아 주셔야겠어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7789, 'koKR', NULL, '어서 오세요! 쑥스러워하지 마시고요.$b$b자, 제 자랑이자 기쁨인... 블라스텐하이머 5000 초특급 대포를 소개합니다! 정말 멋지지 않나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7790, 'koKR', NULL, '간단해요! 제게 다크문 게임 동전을 주시면, 제가 당신을 대포 안으로 던져 넣고 심지에 불을 붙이는 거죠.$B$B일단 대포가 발사되면 몸이 잠깐 붕 뜨게 될 거예요. 하지만 제가 지금 달아드릴 날개가 떨어지면서 빠르게 하강하게 될 거랍니다.$B$B당신은 판잣길 바로 근처 바닷가에 떠 있는 과녁을 향해 발사될 거예요.$B$B땅 위에 있을 때 날개를 떼어내지만 마세요... 아니면... 뭐... 하여튼 생명 보험 같은 건 없어요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7792, 'koKR', NULL, '안녕하십니까? 다크문 축제에 오신 것을 환영합니다. 아주 다양한 행사가 있기 때문에 처음 오신 분은 뭘 해야 할지 모르는 경우가 많아요. 전 그런 분들을 위해 축제 정보를 알려 드리는 도우미를 맡고 있습니다. 궁금한 사항이 있으신가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7793, 'koKR', '아주 좋은 질문이로군요! 다크문 축제에서는 다양한 물건을 구입할 수 있습니다. 음식과 음료가 필요하면 저쪽에 있는 스탬프나 실라니아의 전시장으로 가십시오.\n\n좀 더 특이한 물건을 원하시면 라흐라를 찾아가십시오. 그녀는 세계 각지에서 온 희귀한 물건을 전문으로 취급하고 있습니다.\n\n그리고 이 근처 어딘가에 돌아다니고 있을 플릭을 마주치면 공이랑 애완용 개구리도 살 수 있을 겁니다.', '아주 좋은 질문이로군요! 다크문 축제에서는 다양한 물건을 구입할 수 있어요. 음식과 음료가 필요하면 저쪽에 있는 스탬프나 실라니아의 전시장으로 가세요.\n\n좀 더 특이한 물건을 원하시면 라흐라를 찾아가세요. 그녀는 세계 각지에서 온 희귀한 물건을 전문으로 취급하고 있습니다.\n\n그리고 이 근처 어딘가에 돌아다니고 있을 플릭을 마주치면 공이랑 애완용 개구리도 살 수 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7794, 'koKR', '그거 안 물어보시면 어쩌나 했습니다. 다크문 축제 상품권으로 특별한 선물을 살 수 있습니다.$b$b상품권은 월간 퀘스트를 완료하거나 축제에서 게임을 즐기면 획득할 수 있습니다. 월간 퀘스트를 완료하면 축제 상품권을 대부분 모을 수 있지만, 게임을 매일 하면 더 좋은 결과가 있을 겁니다.$b$b상품권을 충분히 모으면 다크문 축제에 있는 여러 상인에게 사용할 수 있습니다.', '그거 안 물어보시면 어쩌나 했어요. 다크문 축제 상품권으로 특별한 선물을 살 수 있답니다.$b$b상품권은 월간 퀘스트를 완료하거나 축제에서 게임을 즐기면 획득할 수 있어요. 월간 퀘스트를 완료하면 축제 상품권을 대부분 모을 수 있지만, 게임을 매일 하면 더 좋은 결과가 있을 거예요.$b$b상품권을 충분히 모으면 다크문 축제에 있는 여러 상인에게 사용할 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7795, 'koKR', NULL, '다크문 카드를 누가, 무슨 목적으로 만들었는지는 아무도 몰라요. 제가 말씀드릴 수 있는 것은 아제로스 전역에서 종종 발견됐다는 것, 그것도 주로 카드의 비밀을 밝혀내려는 악당들이 가지고 있었다는 것뿐이에요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7796, 'koKR', '세이지를 만나서 운명을 점쳐보기를 권해드립니다. 그래요, 그래요... 세이지는 놀이죠. 하지만, 세이지는 미래를 점치는 힘을 지닌 아주 특별한 놀이랍니다!$B$B저희는 온갖 새로운 즐길 거리를 마련하여 그 능력을 더 널리 사용하고자 한답니다.', '세이지를 만나서 운명을 점쳐보기를 권해드립니다. 그래요, 그래요... 세이지는 놀이죠. 하지만, 세이지는 미래를 점치는 힘을 지닌 아주 특별한 놀이랍니다!$B$B저희는 온갖 새로운 즐길 거리를 마련하여 그 능력을 더 널리 사용하고자 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7797, 'koKR', '실리더스에는 적이 하나만 있는 것이 아닙니다, $n.$B$B모두의 이목이 실리시드에 집중되어 있지만 저는 형과 함께 황혼의 망치단 미치광이들을 주시해 왔습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7799, 'koKR', NULL, '세이지를 만나서 운명을 점쳐보기를 권해드립니다. 그래요, 그래요... 세이지는 놀이죠. 하지만, 세이지는 미래를 점치는 힘을 지닌 아주 특별한 놀이랍니다!$B$B저희는 온갖 새로운 즐길 거리를 마련하여 그 능력을 더 널리 사용하고자 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7800, 'koKR', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7801, 'koKR', NULL, '안녕하세요, 여행자님. 이곳은 거의 1천 년 전, 퀴라지가 칼림도어를 건너 파괴의 행진을 시작한 곳입니다.$B$B전쟁 중에 수천 명이 목숨을 잃었는데, 그 대부분은 첫 번째 침략 당시 이 저주받은 사막에서 숨을 거뒀지요.$B$B저는 몇 안 되는 생존자 중의 한 명이며, 과거와 현재의 속박에서 벗어나지 못하는 불쌍한 영혼이랍니다. 제가 여기 남아 있어야 하는 이유는 알지 못하지만 그럴 수밖에 없다는 것은 알고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7802, 'koKR', NULL, '저는 백 번이나 살해당했지만 깨어나면 다시 이곳이었죠. 어떤 이들은 저를 보고 저주받았다고 하고, 또 어떤 이들은...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7803, 'koKR', NULL, '축복받은 것이라고 하더군요. 새로운 시대를 알려 주는 전령이라면서...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7804, 'koKR', NULL, '수천 년 동안 보이지도 않고 느낄 수도 없었던 고대의 세력이 움직이고 있습니다. 이 세계가 흐느끼고 있어요. 아마도 새로운 세계 분리가 일어나겠죠. 내부로부터 탄생한 병...$B$B사악함이 우리 땅에 퍼지기 시작했어요. 에메랄드의 꿈으로부터 악몽이 나타나고 있습니다. 깨어 있는 동안 우리를 타락시킬 악몽이...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7805, 'koKR', NULL, '할로윈 축제 즐겁게 보내세요! 제가 쓴 가면 어때요? 너무 무섭지 않아요?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7806, 'koKR', NULL, '즐거운 할로윈 축제! 제가 쓴 가면 어때요? 진짜 섬뜩하죠?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7808, 'koKR', NULL, '사탕 구하러 다는 게 너무 그리울 거예요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7809, 'koKR', NULL, '$g오빠가:언니가; 최고예요. 절 위해 사탕을 얻어다 주시겠다니... 정말 고맙습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7810, 'koKR', '할로윈 축제인데 밖에 나갈 수가 없다니... 사탕 얻으러 다니고 싶은데!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7812, 'koKR', NULL, '뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 \"사탕 하나 주면 안 잡아먹지!\" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한번 가보세요! 그리고 매일 저녁에는 언더시티 밖에서 밀짚인형 축제가 열려요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7813, 'koKR', NULL, '뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 \"사탕 하나 주면 안 잡아먹지!\" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한 번 가보세요! 참, 그리고 남녘해안에 있는 하사관 허트만이 밀짚인형 축제를 맞이한 포세이큰을 저지하기 위해 도움이 필요하다고 하더군요.$B$B아, 한 가지 더 있어요. 스톰윈드의 보육원에 한 소년이 병들어 몸져누워 있는데 축제 기간 동안 누군가 대신 사탕을 모아줬으면 한데요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7814, 'koKR', '누가 뭐라고 날 부르던데... 임프시라던가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7816, 'koKR', '이방인이여, 당장 떠나십시오! 당신과는 볼일이 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7817, 'koKR', '아, 돌아오셨군요! 뭘 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7818, 'koKR', '$n, 호드와의 전쟁이 임박했네. 지금은 얼라이언스에 매우 중요한 때이니 우리 모두 각자 맡은 역할을 수행하는 데 온 힘을 기울여야 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7819, 'koKR', '$n, 전쟁이 코앞에 다가왔소. 모든 호드는 부름에 응하여 얼라이언스 겁쟁이들과의 전투에 참가해야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7820, 'koKR', NULL, '그대는 가죽세공인이 맞으시죠? 그대에게서 경화 가죽 냄새가 나요. 그 냄새라면 어디서든 분간할 수 있죠.$B$B아버지 말씀으로는 수 세기 전 마파람 마을에 유명한 가죽세공의 장인이 살았었대요. 유감스럽게도 지금 그곳은 폐허가 됐지만...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7821, 'koKR', NULL, '오, $n 님! 다시 만나서 반가워요. 그동안 잘 지내셨죠?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7823, 'koKR', '필요한 구리 주괴를 모두 모았습니다. 도와주셔서 감사합니다, $c|1이여;여;. 이곳에서 다른 재료를 모으는 일도 도와주지 않으시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7824, 'koKR', '구리 주괴가 더 필요합니다! 안퀴라즈 성문 앞에 전쟁의 열기가 끓어가고 있는 상황에서 전쟁 물자를 비축해야 합니다. 지금까지 얼라이언스 연합에서 모은 것은 $1997w개인데 우리에게 필요한 것은 모두 $1998w개입니다. 구리 주괴를 다 모으지 못하면 제가 혼이 날지도 몰라요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7825, 'koKR', '수정 안으로 거대한 통로가 굴처럼 뚫려 있는 것이 비춰 보입니다. 직감으로 그곳이 화산 심장부라는 것을 알 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7827, 'koKR', '안녕하십니까, $r. 살아 있기에 정말 좋은 날이지 않습니까?', '안녕하십니까, $r. 살아 있기에 정말 좋은 날이지 않습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7828, 'koKR', '모든 타우렌이 당신네 종족을 싫어하는 것은 아닙니다, $r. 그렇지만, 당신에게 내 와이번을 태워드릴 순 없군요.', '모든 타우렌이 당신네 종족을 싫어하는 것은 아닙니다, $r. 그렇지만, 당신에게 내 와이번을 태워드릴 순 없군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7829, 'koKR', '잘 들으시오, 친구. 안퀴라즈의 벌레들과 목숨을 건 한판승을 하려면 준비를 해야 하오. 그래서 난 여기에서 철 주괴를 모으고 있소이다. 현재 얼라이언스에서 보유하고 있는 철 주괴는 $2002w개인데, 우리가 계획한 전쟁 물자를 생산하려면 모두 $2003w개가 필요하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7830, 'koKR', '모두 노력해 준 덕분에 필요한 철 주괴를 모두 모았소. 이제 다른 곳에 가서 전쟁에 필요한 물자를 수집해 줄 것이 없는지 알아보시오. 나는 좋아하는 카드 게임이나 즐기게 이곳을 조금이라도 일찍 벗어날 수 있는지 알아봐야겠소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7831, 'koKR', NULL, '$C|1이여;여;, 잘 들으세요. 지금 얼라이언스와 호드는 실리시드와 그들을 조종하는 무리와 싸울 안퀴라즈 전쟁을 준비하고 있어요. 도와주신다면 정말 감사하겠습니다. 보시다시피 저는 전쟁에 필요한 토륨 주괴를 모으고 있습니다. 모두 $2012w개가 필요한데 현재 보유하고 있는 것은 $2011w개입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7832, 'koKR', NULL, '다시 저를 찾아주셔서 감사합니다. 우리는 필요한 토륨 주괴를 모두 모았습니다. 하지만 여기서 다른 물자를 수집하는 곳에 가서 도움이 필요하지 않은지 물어보는 것도 괜찮을 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7833, 'koKR', '장담하건대 곧 있을 안퀴라즈 전쟁에 필요한 물자를 만드는 데 갈래물풀만큼 유용한 것도 드물 겁니다! 뜨거운 실리더스의 태양이 내리쬐는 무더운 날에 아이스크림을 만들고, 일부 식물의 역겨운 냄새를 없애 주고, 물속에서 숨을 쉴 수 있게 해 주고, 피부를 단단하게 해 주고, 동작을 민첩하게 해 주고, 마력을 보충해 주는 등등... 용도가 하도 많아 일일이 기억하기도 힘들어요! 제가 아이스크림도 만들 수 있다고 말했나요?$B$B어쨌든 제가 모은 것은 대략 $2047w개인데, 총 $2048w개가 필요해요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7834, 'koKR', '혼자 평생 먹고 남을 아이스크림을 만들 수 있을 만큼 많은 갈래물풀을 모을 능력이 있는 분이로군요. 그런데 어쩌죠... 우리는 필요한 갈래물풀을 충분히 모은 것 같은데... 어쨌든 그렇다고 얘기를 들었어요. 하지만 여기서 다른 물자를 모으고 있는 이들 중 도움을 필요로 하는 이가 있을 거예요. 그래도 갈래물풀을 모으는 것만큼 재미있는 일은 없다는 걸 알게 되실 겁니다요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7835, 'koKR', '젊은 $c|1이여;여;, 얼라이언스 연합에서 내게 안퀴라즈에서 실리시드와 벌어질 전쟁에 대비하기 위해 보라 연꽃을 모아 달라고 부탁했답니다. 보라 연꽃은 쓸모가 많고 해서 전 거기에 동의했죠. 보라 연꽃은 총 $2055w개를 모아야 하는데 현재 $2053w개를 모은 상태입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7837, 'koKR', NULL, '지금 우리는 전쟁을 준비하고 있습니다. 안퀴라즈에서 실리시드와 그들을 조종하는 놈들과 싸우려면 전력을 다해 모든 종류의 전쟁 물자를 수집해야 합니다. 전 아서스의 눈물을 모으고 있는데 정확히 어디에 사용할 건지는 잘 모릅니다. 저한테 물어볼 생각이었다면 포기하는 게 좋을 겁니다. 아서스의 눈물이 단지 아서스 님의 이름을 딴 꽃에 불과하다고 해도 그 미치광이와 관련된 것은 눈곱만큼도 알고 싶지 않으니까요.$B$B저는 여전히 제 아버지의 딸이자 일개 병사이', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7838, 'koKR', '이제 다 된 것 같군. 필요한 아서스의 눈물은 모두 모았네. 다른 이들에게도 물어보게. 전쟁 물자 수집에 아직 도움이 필요한 사람이 있을지도 모르니.', '음, 이제 다 된 것 같군요. 필요한 아서스의 눈물을 모두 모았습니다. 주위에 도움이 필요한 곳은 없는지 알아보세요. 어딘가 전쟁 물자 수집에 도움을 바라는 이가 분명히 있을 테니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7839, 'koKR', '$n, 지금까지 심연의 의회를 상대로 벌인 영웅적인 업적은 보고를 통해 이미 알고 있습니다... 정말 위대한 일을 했더군요!$B$B그렇게 꾸준히 나아가도록 하십시오. 우린 그 노고를 절대 모른 척하지 않을 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7840, 'koKR', NULL, '$c|1이여;여;, 얼라이언스에서 우리 가족들에게 머지않아 발발할 안퀴라즈 전쟁에 필요한 얇은 가죽을 모아달라고 부탁했답니다. 지금까지 모두 $2061w개가 필요한데 지금까지 $2060w개가 모였습니다. 당신은 남을 잘 도와줄 $r|1으로;로; 보이는군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7842, 'koKR', NULL, '오, 내 일이 어떻게 되어가는지 물어보러 다시 오시다니 고맙군요. 하지만 이미 필요한 얇은 가죽을 모두 모았답니다. 근처에 다른 물자를 모으는 이들 중에 당신의 도움이 필요한 이가 있지 않을까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7843, 'koKR', '네, 그렇습니다! 병사 포터가 보고 드립니다. 일반 가죽 모으는 일을 도와드리겠습니다. 우리는 다가올 안퀴라즈 전쟁에 대비하여 만반의 준비를 해야합니다.$B$B보시다시피 정확하게 $2063w개의 일반 가죽을 모았고 제가 맡은 임무는 모두 $2064w개를 모으는 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7844, 'koKR', '아, 네, 그렇습니다. 얼라이언스 연합에서 전쟁을 수행하는 데 필요한 일반 가죽을 모두 모은 것 같습니다. 다른 물자를 모으는 곳에서 당신의 도움을 필요로 할지 모른다는 말을 드리고 싶군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7845, 'koKR', NULL, '안녕하세요, $c님! 안퀴라즈 전쟁이 임박했어요. 그에 따라 이곳의 수집도 박차를 가하고 있습니다. 전 두꺼운 가죽 수집을 책임지고 있지요. 두꺼운 가죽 모으기에 정말 좋은 날씨로군요, 그렇지 않나요? 여기 이게 지금까지 모은 가죽인데 $2069w개입니다. $2071w개를 모으는 것이 목표인데, 도와주시겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7846, 'koKR', NULL, '야호! 얼라이언스 연합에서 필요로 하는 두꺼운 가죽을 모두 모은 것 같네요. 정말 빨리도 모았군요. 이 주변에 당신의 도움이 필요한 이들이 있을 겁니다. 물론 본인이 도와줄 마음이 있어야겠지만요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7847, 'koKR', NULL, '$c|1이여;여;, 안녕하세요! 저는 안퀴라즈 전쟁에서 사용할 리넨 붕대를 모으고 있습니다. 수집 일이 고되긴 하지만, 다가올 전쟁에 대비하여 우리의 단결력을 강하게 해주죠. 하지만 분명한 건, 당신께서 기부하실 모든 붕대는 때가 되면 우리 병사들의 소중한 생명을 구하는데 사용될 거란 사실입니다. $2077w개를 모아야 하는데 지금까지 $2076w개 밖에 구하지 못했답니다. 우릴 도와주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7848, 'koKR', '물어봐 줘서 고맙네, $c. 하지만 보다시피 안퀴라즈 전쟁에 필요한 리넨 붕대는 얼라이언스가 요구한 만큼 모두 모았네. 여기서 진행 중인 다른 물자 수집은 계속 도와주게.', '친절하신 $c님, 다시 물어봐 주시다니 감사합니다. 보시다시피 이미 안퀴라즈 전쟁에서 얼라이언스 연합에 필요할 것으로 예상되는 리넨 붕대를 모두 모았습니다. 그래도 이곳에서 다른 물자를 모으는 이들을 계속 도와주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7851, 'koKR', NULL, '안녕하세요, 오늘 기분이 어떠세요? 모쪼록 여기 일에 관심이 있으셨으면 좋겠네요. 이곳에서는 현재 안퀴라즈 전쟁에 대비해 계획을 짜고 준비하는 중이에요. 우리와 호드는 만반의 태세를 갖추기 위해 최선을 다하는 중이죠.$B$B얼라이언스는 제게 이곳에서 비단 붕대 모으는 일을 감독해 달라고 했죠. 지금까지 우리는 $2082w개의 비단 붕대를 모았는데 $2083w개가 필요해요. 어때요, 도와주시겠어요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7852, 'koKR', NULL, '매우 친절한 분이시군요. 그런데 우리에게 필요한 비단 붕대는 모두 모은 것 같군요. 이 근처에서 다른 물자를 수집하는 곳에 도움이 필요한지를 알아보시는 것도 괜찮을 것 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7853, 'koKR', '우리 막강한 전사들과 정찰병들이 아무리 뛰어나다 해도 곧 있을 안퀴라즈 전쟁에서 부상을 전혀 입지 않을 수는 없소이다. 그리고 마법으로 치료할 상황이 안 된다면 우리가 여기서 만들고 있는 붕대에 전적으로 의존할 수밖에 없는 것이오.$B$B지금까지 $2088w개의 룬무늬 붕대를 모았는데 모두 $2090w개가 필요합니다. 원한다면 어느 정도 도와주실 수 있는지 말해주시기 바라오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7854, 'koKR', '많은 얼라이언스의 동지들이 도와주신 덕분에 다가오는 안퀴라즈 전쟁에서 연합에 필요한 룬무늬 붕대를 가까스로 모을 수 있었습니다. 내가 그대라면 이곳에서 다른 물자를 모으고 있는 이들 중 도움이 필요한 이는 없는지 알아보겠소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7855, 'koKR', '이런, $n! 너무 바빠서 얘기를 나눌 시간도 없군요. 말씀드린 것처럼 곧 닥칠 상황에 대해 생각할 시간이 필요합니다.$B$B그대의 여정에 행운이 함께하기를 바랍니다. 좋은 하루 되십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7856, 'koKR', '음... 좋은 냄새가 나지 않습니까? 바로 저기서 먹고 있는 음식에서 나는 냄새죠. 무지개날개다랑어 구이는 언제 먹어도 맛있단 말이에요. 나 슬리키 개스트로놈으로 말씀드릴 것 같으면 최고의 감식가로서, 특히 생선이 전문입니다. 얼라이언스 연합에서는 이제 곧 닥쳐올 안퀴라즈 전쟁 물자를 준비하는 데 전문가의 도움을 받는 것이 좋겠다고 생각했죠. 그래서 여기에 제가 왔고, 아주 중요한 역할을 담당하고 있답니다.$B$B모두 $2093w마리의 무지개날개다랑어가', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7857, 'koKR', '다가오는 안퀴라즈 전쟁에 대비해 이미 충분한 양의 무지개날개다랑어를 모았습니다. 신선도와 맛을 유지하기 위해 소금을 적당히 뿌려 저장해 두었지요. 어쨌든 물어봐 주셔서 감사합니다. 더 돕고 싶다면 주변을 좀 둘러보세요. 필요한 물자를 모으는 데 당신 도움이 필요한 다른 수집가들이 여기엔 분명히 있을 테니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7859, 'koKR', NULL, '오, 안녕하세요 $c님! 얼라이언스 연합에서는 저에게 이곳에서 사람들이 다가올 안퀴라즈 전쟁에 필요한 육류를 모아 오면 그걸 잘 관리해 달라고 부탁했답니다. 정말 웃기는 소리죠?$B$B어쨌든 숯불구이가 얼마나 모였는지 궁금하실 텐데... 마지막으로 확인했을 때가 $2098w개였고 모두 $2099w개의 랩터 숯불구이가 필요해요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7860, 'koKR', '조금 늦었군, $c. 필요한 구운 랩터 고기는 이미 다 잡고 굽고 소금에 절여 두었네. 다른 이들은 아직 도움이 필요한 것 같으니 가서 알아보게. 나는 집에 가도 되는지 물어봐야겠어.', '너무 늦게 오신 것 같네요. 이미 필요한 랩터 숯불구이를 모두 모았답니다. 도살해서 조리한 다음 소금을 뿌려 놓았죠. 그건 그렇고, 주변에 도움을 기다리는 이들이 있으니 그들에게 가보시는 게 좋겠어요. 전 이제 집에 돌아갈 수 있는지 알아봐야겠어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7861, 'koKR', NULL, '영양분을 잘 섭취하면 전쟁터에서 치명적인 부당을 당해도 오래 버틸 수 있어요. 다가올 안퀴라즈 전쟁에서 오래 버티려면 지니고 나갈 수 있는 모든 식량을 준비해야 하죠. 저는 이곳에서 필요한 양이 모일 때까지 점박이놀래기를 모으고 있어요.$B$B지금까지 $2101w마리가 모였는데, 모두를 먹이려면 $2103w마리를 모아야 한답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7866, 'koKR', '$c|1이여;여;, 구리 주괴가 아주 많이 필요하오. 안퀴라즈에서 벌어질 전쟁에 쓸 무기며 갑옷 등을 만들려면 대량의 구리를 확보해야만 하오. 호드에게 필요한 구리 주괴만 해도 최소한 $1998w개라는데 우린 지금까지 $2018w개 비축했을 뿐이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7868, 'koKR', '누락된 텍스트', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7869, 'koKR', '$n 님, 다시 만나서 반갑습니다.$B$B배움에 집중하십시오. 그대의 어깨에 우리 미래가 달렸습니다. 그대가 흔들린다면 우리의 미래는 암울해질 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7870, 'koKR', '트롬카! 주석 주괴 모으는 일을 도와주러 왔소? 다가올 안퀴라즈 전쟁에 필요한 무기와 갑옷을 만들려면 $2006w개가 필요하다고 했는데 아직 $2005w개 밖에 모으질 못했소이다. 주석 주괴를 좀 더 가지고 와 주시오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7872, 'koKR', NULL, '매날개 광장 여관에 오신 것을 환영합니다. 따뜻한 식사를 대령할까요 아니면 편히 누우실 방을 준비해 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7874, 'koKR', NULL, '$c|1이여;여;, 안녕하십니까? 아이언포지 여단은 하이브조라를 감시하기 위해 이곳에 배치되었습니다. 실리시드의 동태를 계속 주시해 온 세나리온 의회 드루이드들에 의하면 이 지역에서 뭔가 심상치 않은 일이 벌어질 것 같다고 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7875, 'koKR', NULL, '연대장님은 우리가 최근에 입수한 실리시드의 지하 둥지 지도를 연구하시느라 지금 바쁘십니다. 돕고 싶다면 여기서 기다리세요. 금방 오실 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7876, 'koKR', NULL, '이봐요, 척 보니 제게 미스릴 주괴를 가져다 주려고 여기 오셨군요. 안퀴라즈의 실리더스 사막에서 벌어질 격전이 임박했어요. 우리와 얼라이언스 모두 벌레들을 막기 위해 총력을 다하고 있죠. 모두들 여기 모인 이유도 바로 그것 때문이죠.$B$B호드는 제게 $2009w개를 모아 달라고 부탁했는데 제가 가지고 있는 건 $2008w개밖에 없어요. 그러니 절 좀 도와주셔야겠어요. 안 도와주실 건가요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7878, 'koKR', NULL, '반갑습니다, 젊은 $c|1이여;여;. 제게 평온초 꽃잎 다발을 주시려고 오셨습니까? 우리는 안퀴라즈 전쟁에 사용할 물약과 비약을 만들기 위해 평온초 꽃잎을 모으고 있답니다. 사실 전쟁 자체가 커다란 비극이라고 할 수 있지만 철저하게 준비하지 않으면 상상조차 할 수 없는 끔찍한 결과가 찾아올 수도 있습니다.$B$B호드에서 요청한 평온초 꽃잎의 수량은 $2020w개인데 지금까지 $2021w개 밖에 못 모았습니다. 할 수 있다면 평온초 꽃잎을 최대한 많이 모', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7880, 'koKR', '날 해치려는 것이냐?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7881, 'koKR', '필멸의 존재여, 나의 감시는 영원할 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7882, 'koKR', '마법이란 단지 신비로운 재주만을 일컫는 것이 아니오. 그대는 이미 이 사실을 알고 있겠지?$B$B가르침을 얻고자 나를 찾아왔으니 내 말에 귀를 기울이시오. 악마의 비밀은 어리석은 이가 알아낼 수 있을 만큼 간단하지 않고, 나 역시 현명한 이들에게만 가르침을 내려준다오.', '마법이란 단지 신비로운 재주만을 일컫는 것이 아닙니다. 당신은 이미 이 사실을 알고 있겠지요?$B$B가르침을 얻고자 나를 찾아왔으니 내 말에 귀를 기울이십시오. 악마의 비밀은 어리석은 이가 알아낼 수 있을 만큼 간단하지 않고, 나 역시 현명한 이들에게만 가르침을 내려줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7883, 'koKR', '<단호한 표정으로 당신을 바라보는 안도로브>$B$B만약 놈이 피를 흘리게 할 수만 있다면 해치울 수 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7885, 'koKR', '푸른용군단이 지키고 있는 홀 파편을 찾고 있나?$B$B<희미한 미소를 짓는 아주어고스>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7886, 'koKR', '물론 나는 그것을 가지고 있지 않다. 그건 바보 같은 짓이지. 여기는 이 저주받은 땅의 미개한 족속들이 날뛰는 곳이다! 채 다섯 걸음도 옮기기 전에 내 가죽을 노리고 미친 오크나 인간들이 서슬 퍼런 칼을 들이대고 무자비하게 마법을 난사한단 말이다. 때가 되면 너는 내 영혼과 언제든 대화를 나눌 수 있을 것이다.$B$B어쨌든... 그 조각은 내가 숨겨 두었다.$B$B어디있느냐 물어보아야 하지 않겠는가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7887, 'koKR', '좋다, 네가 좋아할 만한 얘기를 들려주지. 말리고스가 내게 홀의 파편을 지키는 임무를 맡겼을 때 나는 그 일로 내 긴 영생동안 골머리를 앓을 것이라는 걸 알았다.$B$B내가 하고자 하는 일은 마력으로 충만한 이 해안들을 연구하고 세계의 분리 후 남아 있을지 모르는 유물을 거두는 것뿐이다. 너도 알겠지만 한때 이곳에는 번영을 누리던 명가의 문명이 있었다! 이 근처에 괜찮은 마법 물품이 있을 거라는 얘기는 하지 않아도 된다. 그 정도는 나도 알 수가 있으니', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7888, 'koKR', '말했듯이 나는 500년간 홀의 파편을 지켜 왔지만 홀의 파편은 한낱 골칫거리에 지나지 않았다. 그것은 모든 관심, 순수하지 않은 나쁜 의도를 지닌 자들의 관심을 끌었다. 내가 원하는 것은 조용히 혼자 연구하는 것이지 영웅이 되고 싶은 누군가가 그것을 훔쳐 가지는 않을까 감시하는 것이 아니었다. 그래서... 나는 홀의 파편을 물고기에게 던져 주었다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7889, 'koKR', '아무 물고기에게나 준 것이 아니다, 필멸의 존재여. 작고도 아주 특별한 물고기였느니라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7890, 'koKR', '그래, 맞다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7891, 'koKR', '내가 생각해도 정말 기발한 발상이었지... 절대 그 물고기를 찾지 못할 것이다. 하지만 발견될 경우를 대비해 그 작은 물고기에게 약간 특별한 능력을 주었느니라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7892, 'koKR', '그렇다. 내 말을 경청했구나! 나의 피조물인 이 작은 물고기는 정말 무섭고도 귀여운 녀석이지. 나는 휴식을 취할 때면 운 나쁜 낚시꾼들이 떠오르곤 하지.그들은 어쩌다 운이 나빠 이 작은 물고기를 만나 통째로 잡혀먹혔지. 모두 깜짝 놀랐을 것이다!$B$B<웃음을 터뜨리는 아주어고스>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7893, 'koKR', '평범한 생명체가 나 같은 천재의 행동은 이해할 수 없을 때가 많은 게지, 이해한다. 자, 이제 홀의 파편에 대해 다시 얘기해 볼까? 홀의 파편을 원한다면, 그리고 그 조각을 찾느라 앞으로 만 년을 허비하고 싶지 않다면 내 말을 귀담아 듣도록 하여라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7894, 'koKR', '아케이나이트 부표라는 말을 기억해라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7895, 'koKR', '아무튼 좋다... 넌 아케이나이트 부표를 만들어 바다 속에 던져야 한다. 그러면 분출되는 마력에 의해 내 작은 물고기가 이끌려 올 것이다. 그 녀석이 부표 가까이 오면... 꽝! 신비한 힘이 폭발하여 그녀석을 원래 모습으로 되돌릴 것이니라. 그리고 한 가지 더, 너는 넵튤론의 분노를 살 수도 있고 그렇지 않을 수도 있다. 확률은 반반이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7896, 'koKR', '필멸의 존재여, 난 네가 나를 조롱하고 있다는 것을 모를 정도로 어리석지는 않다. 그러나 사실이다. 너의 말은 대부분 맞다만 옷은 아무리 많이 입어도 상관없느니라.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7897, 'koKR', '타나리스에 있는 내 오랜 친구인 나라인 수스팬시에게 이 장부를 가지고 가라. 아주 무서운 심령술사이지만 뛰어난 기술자이기도 하지! 그라면 이 장부를 해석할 수 있을 것이다.$B$B이것이 내가 할 수 있는 최소한의 일이니 내게 감사할 필요는 없다, $n.$B$B잘 가거라!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7899, 'koKR', NULL, '필멸의 존재여, 부디 조심하세요. 당신보다 더 강한 존재들도 죽음을 피하지 못한 곳에 가게 될 것이니...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7900, 'koKR', '천 년 전, 흐르는 모래의 전쟁이 끝났을 때 아나크로노스와 스태그헬름이 안퀴라즈를 봉쇄하는 동안, 우리 혈족 중 세 명이 자신을 희생하여 퀴라지를 이 전당 안에 가두었습니다.$B$B우리는 언젠가 스카라베 성벽이 무너지면 메리스라, 아리고스 그리고 캘레스트라즈를 구하자고 서로 맹세했습니다.$B$B드디어 성벽이 무너져... 우리가 온 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7901, 'koKR', '아제로스를 구해주지 않겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7902, 'koKR', '<개봉하지 않은 봉투를 이마에 붙이고 있는 나라인>$B$B뭘까... 으음... 벨벳!$B$B맞죠?$B$B배운 전문 기술을 취소하려고 이곳에 온 거라면, 저 위에 있는 책을 이용하도록 하세요...$B$B<\'왕초보를 위한 예언 완전정복\'을 가리키는 나라인>', NULL, '쉿, 말하지 마세요! 파멸의 인도자 때문에 여기 온 거죠?!? 그래... 맞아... 아닌가! 음, 아닌 것 같네요.$B$B뭘 도와드릴까요?', NULL, '말만 하시라고요! 난 은퇴한 기술자이자 최고의 예언자, 나라인 수스팬시입니다! 난 아직 일어나지 않은 당신의 미래를 알려 줄 수 있답니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7903, 'koKR', '$C|1이여;여;, 그대가 가야 할 길은 저와 다릅니다. 훈련을 할 수 있는 다른 곳을 찾아보십시오.', '$C|1이여;여;, 그대가 가야 할 길은 저와 다릅니다. 훈련을 할 수 있는 다른 곳을 찾아보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7904, 'koKR', '가르침을 더 구하고자 하시오, $n?', '가르침을 더 구하고자 하시나요, $n 님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7905, 'koKR', '헤헤헤, 잘 지냈나? 이 펠레케이키 생각에 자네가 날 아주 많이 도와줄 거 같아. 우린 안퀴라즈 전쟁에 대비해 엄청난 양의 화염초가 필요해. 호드에서는 \'이봐, 펠레케이키! 자네는 신속히 $2051w개의 화염초를 구해와\'라고 말했지.$B$B이제 이 펠레케이키가 자네에게 말하겠는데, 내게 화염초가 $2050w개 밖에 없네. 하지만 자네가 금방 모아주겠지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7907, 'koKR', NULL, '좋아, 자네가 우릴 도와줄 수 있을 거란 얘기는 들었으니까 내 말 잘 듣도록. 지금 상황은 이렇다네. 나의 임무는 다가오는 안퀴라즈 전쟁에 대비해 $2055w개의 보라 연꽃을 모으는 거라네. 지금까지 $2054w개 모았어.$B$B사실 밖에 나가 보라 연꽃을 채집하는 일은 자네 같은 모험가들이 해주어야지. 나는 여기 남아 보라 연꽃을 잘 관리하고, 실리시드를 비롯해 우리를 기다리고 있을 미지의 적을 상대로 보라 연꽃의 새롭고 독창적인 용도를 연구해야 하니', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7909, 'koKR', NULL, '$c|1이여;여;, 안퀴라즈 전쟁에 필요한 질긴 가죽 수집 일을 도우러 오셨지요? 좋습니다. 보시다시피 전 $2066w장 모았습니다. 하지만 필요한 수량은 모두 $2067w장이랍니다. 정말 질긴 가죽이 많이도 필요하지요, 친구. 당신의 손칼이 날카롭기를... 질긴 가죽은 전쟁에서 승리를 위해 꼭 필요한 여러 물건을 만드는 온갖 용도에 쓰일 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7911, 'koKR', NULL, '이곳에는 말로 표현할 수 없을 만큼 무서운 공포의 존재가 도사리고 있습니다. 필멸의 존재여, 모든 이들이 알고 있듯이 크툰과 그의 숭배자들은 자연을 위협하는 정도가 아니라 아제로스를 완전히 파괴해 버릴 수 있는 존재예요.$B$B천 년 전 메리스라는 캘레스트라즈, 아리고스와 함께 자신을 희생했죠. 그들 또한 이러한 조짐을 알고 있었기 때문이었어요. 우리가 여기까지 온 이유는 그들을 구하기로 한 맹세 때문이기도 하지만 무슨 일이 있어도 크툰을 저지해야만 하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7912, 'koKR', NULL, '록타르! $c, 자네에게 긴히 할 말이 있네! 우리는 안퀴라즈에서 곧 시작될 전쟁에 대비해야 한다네. 나는 여기서 두꺼운 가죽을 최대한 많이 모아야 해. 지금까지 우리가 모은 가죽은 $2070w장인데 대족장님께서는 총 $2071w장을 모으라고 지시하셨지. 자네도 보다시피 가죽이 조금 모자라는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7914, 'koKR', '$c|1이여;여;, 반갑네. 자네가 안퀴라즈 전쟁 준비에 관한 좋은 소식을 가져다줄 거라 믿네. 난 호드를 위해 튼튼한 가죽을 모으는 일에 자원했다네. 내게 가장 적합한 일이라고 생각했기 때문이지. 자네도 날카롭게 벼린 손칼을 괜히 썩혀두지 말게.$B$B튼튼한 가죽에 대해 말하자면 $2074w장이 필요한데 지금까지 $2073w장 모았다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7916, 'koKR', NULL, '다시 만나 정말 반갑군요, $n! 나의 사랑하는 노움씨에게 제 편지를 전해 주셔서 얼마나 감사한지 모른답니다.$B$B노래 하나 들려드릴까요? 거친 바다를 항해할 때 부르면 여행이 한결 편해질 거예요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7917, 'koKR', NULL, '바다 속은 아주 평온해요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7918, 'koKR', '$c|1이여;여;, 만나서 반갑네. 우리는 다가올 안퀴라즈 전쟁에 필요한 물자를 모으고 있는데 자네의 도움이 필요하네. 내가 맡은 일은 응급치료 물품 중에서 양모 붕대를 대량 모으는 것이라네. 지금 정확하게 $2079w개 가지고 있는데 총 $2080w개가 필요하다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7920, 'koKR', NULL, '안녕하세요. $c님, 때맞춰 오셨군요. 간단히 본론부터 말씀드리겠어요. 우리는 안퀴라즈 전쟁에서 필요 이상의 사상자를 내지 않기 위해 필요한 물자를 모으고 있답니다.$B$B제 임무는 $2086w개의 마법 붕대를 모으는 것인데 지금까지 $2085w개를 모았답니다. 당신께서 도움의 손길을 베푸실 수 있을는지요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7923, 'koKR', NULL, '대지모신께서 보살펴주시지만 $c들도 가끔은 살아남기 위해 약간의 도움이 필요한 경우가 있죠. 그래서 저는 다가올 안퀴라즈 전쟁에 대비해 룬무늬 붕대를 모으고 있어요. 모두 $2090w개를 모아야 하는데 지금까지 우리가 모은 것은 $2089w개예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7924, 'koKR', NULL, '붕대가 더 필요하지는 않은지 물어봐 주셔서 고마워요. 하지만 전쟁에 필요할 것으로 예상되는 룬무늬 붕대는 모두 모은 것 같아요. 주변에서 전쟁 물자를 수집하고 있는 이들 중에 도움이 필요한 이들을 당신에게 부탁드려도 될까요? 선조의 가호가 있기를...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7925, 'koKR', NULL, '크르르, $r|1이로군;로군;. 뭘 원해? 오, 안퀴라즈 전쟁에 필요한 늑대 살코기 스테이크 때문에 여기 온 게 틀림없군그래! 자네가 들은 얘기는 사실일세. 나는 늑대 살코기 스테이크를 모으고 있어. 그런데 무슨 볼일이지? 혹시 내게 줄 신선한 늑대 살코기 스테이크가 있나? 모두 $2096w개면 되겠는데 지금까지 우리가 모은 것은 $2095w개로군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7927, 'koKR', '여보십시오, 전 호드에 필요한 전투 식량을 모으고 있습니다. 호드는 안퀴라즈의 사막에서 벌어질 대전쟁을 준비하고 있는데 내게는 점박이놀래기 구이 $2103w개를 모아달라고 했어요. 하지만 지금까지 우리가 모은 것은 $2102w개뿐입니다. 절 좀 도와주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7929, 'koKR', '$c|1이여;여;, 평안하시오? 전쟁 물자 준비를 돕는 그대와 같은 분을 만나니 무척이나 반갑소이다. 이곳에서는 많은 이들이 중요한 시기를 대비하기 위해 다양한 물자를 수집하고 있소.$B$B난 안퀴라즈 전쟁에 참전할 병사들을 위해 훈제 연어 $2106w개를 모아 비축해두는 일을 맡았소이다. 마지막으로 수량을 확인했을 때가 $2105w개였지, 아마!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7930, 'koKR', '$c|1이여;여;, 물어봐 주니 고맙소만 우린 전쟁에 사용할 훈제 연어를 모두 모았소이다. 이곳에서 다른 전쟁 물자를 수집하는 이들에게 가보는 게 어떻겠소? 그대의 도움을 바라는 이들이 분명히 있을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7933, 'koKR', '해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7935, 'koKR', '아주 오래전, 우리는 사냥으로 살아갔다. 우리는 영광을 위해, 명예를 위해 사냥을 했다...$B$B지금은 어떤가?', '아주 오래전, 우리는 사냥으로 살아갔다. 우리는 영광을 위해, 명예를 위해 사냥을 했다...$B$B지금은 어떤가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7937, 'koKR', '필멸의 존재여, 용언을 배우려는 너의 노력은 헛수고로 돌아갔다. 도대체 왜 고대 언어를 배우려고 하느냐? 정말 이해할 수가 없구나...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7942, 'koKR', '록타르, $r! 나는 호드 연합의 사절, 전투사령관 조그다. 내가 여기 배치된 이유는 위대한 호드의 안퀴라즈 전쟁 준비가 어떻게 진행되고 있는지 알려 주기 위함이다. 무엇이 알고 싶나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7944, 'koKR', '금속 주괴들을 얼마나 모았냐고 물었나? 내가 마지막으로 확인한 결과는 다음과 같다. 호드에 필요한 구리 주괴는 $1998w개인데 $2018w개를 모았고, 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았다. 그리고 미스릴 주괴는 $2009w개를 모아야 하는데 $2008w개를 모았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7945, 'koKR', '내가 마지막으로 들은 바로는 평온초는 $2020w개가 필요한데 $2021w개를 모았고, 화염초는 $2051w개 중 $2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7946, 'koKR', '가죽 말인가? 그래, 방금 가죽에 대한 보고를 받았다. 호드에 필요한 질긴 가죽은 $2067w개인데 $2066w개를 모았다. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개를 모았고, 튼튼한 가죽은 $2074w개 중 $2073w개를 모았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7947, 'koKR', '호드는 엄청난 양의 붕대를 모으고 있다. 지금까지 양모 붕대는 $2080w개 중 $2079w개를 모았다. 마법 붕대는$2086w개 중$2085w개를 모았고, 룬무늬 붕대는 $2090w개 중 $2089w개를 모았다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7948, 'koKR', '식량을 얼마나 모았는지 알고 싶다고 했나? 좋아. 마지막으로 들은 바에 의하면, 늑대 살코기 스테이크는 $2096w개 중 $2095w개가 준비됐다고 한다. 그리고 필요한 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 포장해 두었다고 한다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7949, 'koKR', '반갑네, $r $c! 나는 이곳에서 얼라이언스를 대표하여 사절을 맡고 있는 사령관 스트롱해머라고 하네. 얼라이언스의 안퀴라즈 전쟁 물자 수집 상황에 대해 궁금하다면 주저하지 말고 물어보게나.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7951, 'koKR', '아주 좋은 질문이군. 내가 마지막으로 듣기로, 얼라이언스는 전쟁에 필요한 구리 주괴 $1998w개 중 $1997w개, 철 주괴 $2003w개 중 $2002w개, 그리고 토륨 주괴 $2012w개 중 $2011w개를 모았다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7952, 'koKR', '어디 한 번 보세나. 여기 어디에 적어놓은 게 있을 텐데... 아, 여기 있군! 지금까지 얼라이언스는 필요한 갈래물풀 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개를 모았네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7953, 'koKR', '그걸 물어보다니 참 재미있군. 가죽에 대한 정보를 방금 받았거든. 지금까지 얼라이언스는 얇은 가죽 $2061w개 중 $2060w개, 일반 가죽 $2064w개 중 $2063w개, 두꺼운 가죽 $2071w개 중 $2069w개를 모았네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7954, 'koKR', '붕대라고 했나? 에... 그러니까, 마지막으로 들은 내용을 떠올려 보면 얼라이언스는 리넨 붕대 $2077w개 중 $2076w개, 비단 붕대 $2083w개 중 $2082w개, 룬무늬 붕대 $2090w개 중 $2088w개를 모은 것 같네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7955, 'koKR', '그 질문을 들으니 뭘 좀 먹어야 할 것 같군... 듣자하니 얼라이언스가 지금까지 모은 전투 식량은 무지개날개다랑어 구이 $2093w개 중 $2092w개, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개가 준비되어 있다네. 실리더스의 세나리온 요새로 수송할 때까지 포장된 상태로 냉장고에 보관할 거라는군. 음...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7956, 'koKR', '지금 별빛은 다가올 시대에 희망과 힘의 등불이 될 새 길을 인도하고 있도다.', '지금 별빛은 다가올 시대에 희망과 힘의 등불이 될 새 길을 인도하고 있도다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7958, 'koKR', '모든 준비가 끝나고 이제 한판 붙을 일만 남았군요. 전쟁 물자를 모두 실리더스의 세나리온 요새로 수송 중인데 최소한 $2113w일 안에는 마지막 물자가 도착할 것입니다. 조만간 홀만 합쳐지면 드디어 전쟁이 시작되는 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7960, 'koKR', '야호, 끝났다! 모두 물자 수집을 완료했소. 그리고 일전에 말했듯이 수집한 전쟁 물자는 비행선에 실어 실리더스로 공수 중이지. 늦어도 $2113w일 안에는 마지막 물자가 도착할 거요. 수송이 완료되고 파편들을 모아 홀이 하나로 합쳐지면 더러운 벌레들과의 전쟁이 시작되는 거지. 병사들의 표현을 빌리자면 한마디로 이런 거요. \'보내 버려!\'', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7962, 'koKR', '안녕하신가, $c. 내가 알기로는 물자 수집이 끝났고 모두 실리더스로 운송 중이라네. $2113w일 안에 전부 도착할 걸세. 그다음 흐르는 모래의 홀로 징을 울리면 전쟁이 본격적으로 시작되겠지.', '안녕하세요? 제가 들은 바로는 물자 수집이 완료되어 우리가 얘기한대로 모든 전쟁 물자를 실리더스로 수송 중이라고 하네요. 적어도 $2113w일 안에는 모두 보내야 한다는군요. 만반의 준비가 끝나면 흐르는 모래의 홀로 징을 울리고 진짜 전쟁을 시작할 수 있는 거죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7964, 'koKR', '다 됐습니다. 양쪽 모두 물자 수집을 완료했어요. 현재 모든 물자를 실리더스로 수송하는 중이며 적어도 $2113w일 안에는 모두 보내야 한다는군요. 만반의 준비가 끝나고 누군가 흐르는 모래의 홀로 스카라베 제단의 징을 울리면 전쟁이 시작되는 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7965, 'koKR', '무법항에 온 걸 환영하네, 친구. 우리 마을에 머무는 동안 아무 일 없이 즐겁게 지내길 바라네. 꼭 아무 일도 없이... 꼭! 마실 것이 필요한가? 일꾼이 필요한가? 말만 하게. 얼마든지 제공해 줄 테니까.$B$B그건 그렇고... 스팀휘들 무역회사의 충복인 이 몸께서 뭘 도와주면 되겠나? 아, 이렇게 말하는 게 더 낫겠군. 날 위해 자네는 뭘 해 줄 수 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7967, 'koKR', '젊은 $c|1이여;여;, 모든 준비가 끝났습니다. 일전에 우리가 말한 대로 호드와 얼라이언스 모두 전쟁 물자를 세나리온 요새 근처의 실리더스로 수송하고 있지요. 최종 작업은 늦어도 $2113w일 내에 완료될 겁니다. 그다음 안퀴라즈 관문 근처의 징이 울리면 전쟁이 시작되는 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7969, 'koKR', NULL, '$c|1이여;여;, 임무를 보고하러 오셨나요? 얼라이언스와 호드의 전쟁 물자 수집이 모두 완료되어 일전에 말한 대로 지금 실리더스로 수송하는 중입니다. 늦어도 $2113w일 안에 모두 도착할 거예요. 누군가 흐르는 모래의 홀의 흩어진 파편들을 찾아서 하나로 합쳐 놓았다면 좋겠는데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7971, 'koKR', NULL, '자원 수집이 완료되어 마지막까지 모은 물자를 세나리온 요새로 수송 중인 걸로 알고 있어요. 마지막 수송은 $2113w일 내로 완료될 거고요. 우리 군대와 모든 장비가 그곳에 집결하면 흐르는 모래의 홀을 가진 이가 안퀴라즈 근처에 있는 징을 울려 성문을 열 거예요. 전쟁이 시작되는 거죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7981, 'koKR', '차렷! 안퀴라즈 전쟁에 필요한 전쟁 물자 수집이 완료되었으며 현재 세나리온 요새로 수송 중입니다! $2113w일 내로 마지막 물자가 도착할 예정이라고 합니다. 수송이 완료되고 누군가 그곳의 징을 울려 성문을 열면 우리는 벌레 놈들을 한 방에 날려 버릴 것입니다. 자신 있습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7984, 'koKR', '안녕하신가, $c! 호드도 마지막 물자를 모았고 이제 양쪽 물자를 모두 실리더스로 옮기고 있다네. $2113w일 안에 도착한다더군. 그러면 누군가 안퀴라즈 성문 앞의 커다란 징을 울려 전쟁을 시작할 수 있을 걸세.', '안녕하세요! 호드 측에서 물자를 모두 모았어요. 말씀드린 대로 우리가 모은 것과 함께 지금 실리더스로 수송 중인 것 같아요. 제가 듣기로 $2113w일 내로 모두 도착할 예정이고 누군가 안퀴라즈 관문 근처의 커다란 징을 울리면 전쟁이 시작될 거라고 하네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7988, 'koKR', NULL, '우리가 말한 대로 모든 전쟁 물자를 실리더스로 수송 중입니다. 현재 상황으로 봤을 때, $2113w일 내로 마지막 수송이 완료될 것 같습니다. 그러면 아제로스의 영웅이라 할만한 누군가 스카라베 제단에 있는 징을 울려야 합니다. 그때야 비로소 본격적인 전쟁이 시작되는 것이지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7991, 'koKR', NULL, '우리가 마지막 힘을 다해 모은 전쟁 물자가 앞으로 $2113w일 내에 실리더스로 옮겨질 것 같아요. 물자 수송이 완료되면 누군가 안퀴라즈 밖에 있는 스카라베 제단에서 징을 울려 문을 열어야 해요. 바로 그때 우리 붕대가 필요할 때가 시작되는 거죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7994, 'koKR', '물자 수집을 모두 완료했소. 마지막 준비를 위해 실리더스로 수송 중인데 $2113w일 내로 도착할 예정이오. 우리 연합군은 지금 흐르는 모래의 홀을 하나로 결합하여 징을 울려 안퀴라즈 전쟁을 시작할 영웅을 기다리고 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7997, 'koKR', '생선을 포함한 모든 물자들을 실리더스로 수송하는 중인데 $2113w일 내로 도착할 겁니다. 그런 다음 누군가 흐르는 모래의 홀로 징을 울리면 전쟁이 시작될 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7998, 'koKR', '들리는 얘기로는 우리에게 필요한 모든 물자가 모였다고 하네요. 이제 호드 측에서 물자 수집을 완료하기만 하면 되겠어요. 호드의 준비가 끝나면 모든 물자를 실리더스로 옮기겠죠. 바야흐로 전쟁을 시작할 수 있는 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8000, 'koKR', NULL, '식량을 포함해서 우리가 수집한 모든 전쟁 물자를 실리더스로 옮기는 중이에요. 모두 $2113w일 내로 도착할 거예요. 세나리온 요새 근처에 모든 물자가 모이면 누군가 스카라베 제단에 있는 징을 울려야 안퀴라즈 관문을 열고 전쟁을 시작할 수 있다고 들었어요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8003, 'koKR', NULL, '안녕하세요? 전쟁 물자를 세나리온 요새로 수송하는 중인데 $2113w일 내로 모두 도착할 거예요. 그런 후에는 누군가 흐르는 모래의 홀을 결합한 후 징을 울려서 성문을 열기를 기도하는 수밖에 없지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8006, 'koKR', '예상과 달리 이런 능력이 얼라이언스에게 있었군. 이제 호드 얼라이언스와 모두 안퀴라즈 전쟁에 필요한 준비를 마쳤네. 일전에 말한 대로 실리더스로 물자를 수송하는 중인데 $2113w일 내로 도착할 걸세. 그다음엔 누군가 흐르는 모래의 홀을 다시 결합하여 스카라베 제단에 있는 징을 울리고 안퀴라즈의 관문을 열 걸세. 바야흐로 전쟁이 시작되는 거지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8007, 'koKR', '예상한 대로 얼라이언스보다 우리 호드가 먼저 준비를 끝냈다네. 자네들 얼라이언스가 약속한 일을 아직 끝내지 못했기 때문에 우리는 전쟁에 필요한 마지막 단계를 진행하지 못하고 있네.$B$B자, $r|1이여;여;, 그러니 가서 자네가 맡은 일을 열심히 하도록.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8037, 'koKR', '모든 물자 수집을 끝마치고 실리더스로 옮기는 중이네. $2113w일 내로 모든 물자가 도착할 걸세. 징이 울린 후 관문이 열리면, 그동안의 우리의 노력이 생명을 구하고 많은 도움을 줄 수 있기를 바랄 뿐이네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8049, 'koKR', '이곳의 모든 전쟁 물자가 실리더스 사막으로 옮겨질 테니 낚시를 할 수 있는 시간도 이제 $2113w일밖에 남지 않은 것 같군요. 물자를 모두 옮기고 준비를 끝내면 관문을 열고 전쟁을 시작하기 위해 누군가가 세나리온 요새 남쪽에 있는 징을 울려야 할 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8052, 'koKR', '호드와 얼라이언스 모두 물자 수집을 완료했다고 들었다면 제대로 들은 것이오. 우리가 수집하고 준비한 물자를 현재 실리더스의 세나리온 요새로 옮기는 중이오. $2113w일 내로 마지막 물자가 도착할 것이오. 물자가 모두 도착하면 아마도 우리는 누군가 홀을 짜 맞춰서 징을 울릴 때까지 기다려야 할 것이오. 징이 울리면 안퀴라즈의 관문이 열리고 전쟁이 시작될 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8059, 'koKR', '우리는 스랄 님을 모신다는 데 큰 자부심을 가지고 있다. 적을 무찌르는 일에 필요하다면 아무리 먼 곳이라도 기꺼이 떠날 각오가 되어 있다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8060, 'koKR', '때맞춰 도착했군. 발밑의 땅이 흔들리는 것이 느껴지는가?$B$B곤충 집에서 뭔가 접근하고 있다.$B$B그런트 옆으로 가서 자리 잡도록, $n. 자네에게 거는 기대가 크노라!', '딱 맞춰 왔군, $c. 발밑이 흔들리는 게 느껴지나?$B$B둥지에서 뭔가 다가오고 있다. 그런트들 옆에 자리 잡아, $N. 자네를 믿겠네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8061, 'koKR', '실리시드 따위는 오그리마의 자랑스러운 아들딸들의 상대가 될 수 없다. 곧 우리 발 밑에는 벌레들의 다리와 날개만이 어지럽게 널려 있을 것이다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8063, 'koKR', '실리시드에게 들키지 않고 이렇게 가까이 접근하려면 약간의 훈련이 필요하오. 그대에게 그럴만한 배짱이 있다면 굳이 훈련을 요구하지는 않겠소이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8064, 'koKR', '오해하지 마십시오. 저도 실리시드가 우글거리는 터널에 온종일 갇혀 있고 싶지는 않지만, 여기 숨어서 이 벌레들의 움직임을 감시하는 것이 우리의 승리에 도움이 된다면 며칠이 걸리든 그렇게 할 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8065, 'koKR', '조만간 우리는 실리시드라는 끔찍한 존재를 아제로스에서 몰아낼 것입니다. 놈들에게 잠재되어 있는 파괴력은 그대가 직접 본 것보다 훨씬 더 엄청나답니다, $n. 더 강력하고 사악한 힘이 놈들을 조종하고 있는 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8070, 'koKR', NULL, '얼라이언스 무공 훈장은 영웅에게 수여되는 것입니다. 얼라이언스의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말이에요. 모든 주요 도시에 얼라이언스의 각 종족별로 여러 명의 인사 장교가 있어요. 당신의 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 훈장을 가져다주세요!$B$B그나저나 군수 물자 수급 기간 동안에는 평판 대신에 당신의 훈장을 보상으로 받게 될 것이니 야전사령관 스노우폴을 찾아가 보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8071, 'koKR', '우리는 대업을 위해 힘을 합쳤습니다. 고대의 악마가 칼림도어의 모든 생명을 말살하고 이 세계를 타락으로 물들이려 합니다... 그는 위대한 창조주인 영원의 티탄에 의해 태어난 모든 생명에 대한 적개심을 품고 있습니다.$B$B우리는 크툰의 군대에 맞설 최초이자 최후의 방어선입니다. 우리가 봉기하여 적을 물리치지 않는다면 적은 우리를 파멸로 몰아넣을 것입니다.$B$B이번 전쟁 준비에 당신의 도움이 꼭 필요합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8072, 'koKR', '얼라이언스 무공 훈장은 영웅에게 수여되는 것입니다. 얼라이언스의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에 얼라이언스의 종족별로 여러 명의 인사 장교가 있습니다. 당신의 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 야전사령관 스노우폴을 만나보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8073, 'koKR', '호드 무공 훈장은 영웅에게 수여되는 것입니다. 호드의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에는 호드의 종족별로 여러 명의 인사 장교가 있습니다. 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 무공 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 장군 고르척을 만나보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8074, 'koKR', NULL, '호드 무공 훈장은 영웅에게 수여되는 것입니다. 호드의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에는 호드의 종족별로 여러 명의 인사 장교가 있습니다. 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 무공 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 장군 고르척을 만나보세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8076, 'koKR', '이 순록의 목에는 \"멧젠\"이라는 이름의 딱지가 굴뚝나무 목장조합 로고에 달렸습니다.$B$B멧젠이 당신을 슬프고 불쌍한 눈으로 쳐다봅니다. 이 순록은 어떤 보이지 않는 힘에 의해 움직일 수 없게 된 것 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8077, 'koKR', '멧젠의 눈이 기쁨으로 밝게 빛납니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8078, 'koKR', '비록 자네가 우리를 구해내는 데는 성공했지만 크툰을 꺾지는 못했다. 우리 모두 힘을 모아 그 괴물을 지옥으로 다시 추방해야 한다. 어떤 대가를 치르더라도!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8079, 'koKR', NULL, '그대가 혈족의 영웅인가요? 크툰을 없애야 합니다! 우리가 그대를 돕겠습니다, 필멸의 존재여!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8080, 'koKR', '자네가 내 앞에 있는 걸 보니 기적이 벌어진 모양이군! 이곳에 감금된 천 년 동안 살아 있는 생명체가 이 방에 들어온 것은 타락한 퀴라지와 실리시드 외에는 본 적이 없다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8081, 'koKR', '다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리랍니다.', '다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리예요.', '이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어갑니다!', '이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어갑니다!', '불꽃놀이가 끝나면 축배를 들기 위한 술잔이 나올 겁니다!', '불꽃놀이가 끝나면 축배를 들기 위한 술잔이 나올 겁니다!', '친구여, 만나서 반갑습니다!', '친구여, 만나서 정말 반가워요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8082, 'koKR', '어서 오게. 나는 이곳에서 전쟁 준비를 총지휘하고 있는 야전사령관 스노우폴이라고 하네. 우리가 갈 길은 멀고도 험난하니 자네가 좀 도와줬으면 좋겠네. 궁금한 게 있다면 주저하지 말고 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8084, 'koKR', '우린 준비가 끝났네! 얼라이언스와 호드 모두 안퀴라즈 전쟁에서 필요할 걸로 생각되는 물자를 모두 모았네. 현재 최종적으로 완성된 물자를 실리더스의 세나리온 요새로 옮기고 있는데 $2113w일 내로 모든 물자가 도착할 것이야. 물자 수송이 끝나면 안퀴라즈 관문을 열어야 하는데 그러려면 어떤 용감한 영웅이 흐르는 모래의 홀로 스카라베 징을 울려야 하지. 문이 열리면 전쟁이 시작되는 거라네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8085, 'koKR', '자네 좋은 소식 들었나, $c 친구? 이번 전쟁에서 얼라이언스에 필요한 물자를 모두 모았다네! 지금은 호드가 물자 수집을 완료할 때까지 기다리는 중이지. 그게 끝나면 모든 전쟁 물자를 실리더스로 옮기기 시작할 것이야. 물자 수송이 완료되면 머지않아 안퀴라즈 전쟁이 시작되겠지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8087, 'koKR', '질문 잘하셨습니다, $c. 마지막으로 보고받은 내용에 따르면 $1998w개의 구리 주괴가 필요한데 지금까지 $1997w개를 모았다고 말했습니다. 또, 철 주괴는 $2003w개 중 $2002w개, 토륨 주괴는 $2012w개 중 $2011w개를 모았다고 보고받은 상황입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8088, 'koKR', '약초, 약초라. 어디 봅시다. 오, 그렇군요. 여기 있네요. 지금까지 모은 것을 보면 갈래물풀은 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8089, 'koKR', '조금 전에 새로운 보고를 받았습니다. 얇은 가죽은 $2061w개가 필요한데 현재까지 모은 것은 $2060w개인 것 같더군요. 다른 가죽을 보면 일반 가죽은 $2064w개 중 $2063w개, 두꺼운 가죽은 $2071w개 중 $2069w개를 모았다고 되어 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8090, 'koKR', '붕대 수집은 예정대로 잘 진행되고 있습니다. 리넨 붕대를 살펴보면 지금까지 $2077w개 중 $2076w개를 모았습니다. 그리고 비단 붕대는 $2083w개 중 $2082w개, 룬무늬 붕대는 $2090w개 중 $2088w개를 모았습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8091, 'koKR', '저 앞에 있는 식량을 보면 무지개날개다랑어 구이는 $2093w개가 필요한데 $2092w개를 모아서 보관해 둔 것 같습니다. 또, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개를 모아서 냉장 창고에 저장해 두었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8092, 'koKR', '트롬카. 호드 $C|1이여;여; 자부심을 가지게나! 나는 호드의 전쟁 물자 준비를 총지휘하고 있는 장군 고르척이네. 우리는 지금 어려운 시기를 겪고 있네. 하지만 언제나 그랬듯이 잘 극복할 수 있을 것이야.$B$B궁금한 게 있으면 저들에게 가서 물어보게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8094, 'koKR', '전쟁이 눈앞으로 다가왔네! 호드와 얼라이언스 모두 전쟁 준비를 완료했어. 말했듯이 우리는 모든 전쟁 물자를 실리더스로 옮기고 있네. $2113w일 내로 마지막 물량이 도착할 걸로 예상한다네. 모든 물자가 실리더스에 도착하면 누군가가 흐르는 모래의 홀을 복원하는 어려운 임무를 완수한 후 스카라베 징을 울리고 안퀴라즈의 관문을 열 걸세. 그러면 지금까지 유례없는 대전쟁이 시작되겠지!$B$B록타르 오가르!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8096, 'koKR', '구리 주괴는 $1998w개 중 $2018w개를 모았네. 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았네. 그리고 이번 전쟁에서 승리하려면 제련된 미스릴 주괴 $2009w개가 필요한데 지금까지 $2008w개를 모았다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8097, 'koKR', '방금 약초에 대한 보고를 받았네. 필요한 평온초는 모두 $2020w개인데 현재까지 $2021w개를 모았고, 화염초는 $2051w개 중$2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8098, 'koKR', '잠시만 기다려 보게. 기억할 숫자가 뭐가 이렇게 많은지... 질긴 가죽은 $2067w개 중 $2066w개를 모은 것 같네. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개, 튼튼한 가죽은 $2074w개 중 $2073w개를 모아서 쌓아 두었네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8099, 'koKR', '붕대? 그건 왜 물어보나? 붕대가 필요할 때까지 오래 버텨 보려는 속셈인가? 하하! 아주 좋아. 알려주도록 하겠네. 양모 붕대는 $2080w개 중 $2079w개를 모았네. 그리고 마법 붕대는 $2086w개를 모아야 하는데 그중 $2085w개를, 룬무늬 붕대는 $2090w개 중 $2089w개를 모았네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8100, 'koKR', '식량! 드디어 내가 관심 있는 분야를 물어보는군! 보고받은 바로는 늑대 살코기 스테이크는 $2096w개 중 $2095w개, 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 모아서 냉장 창고에 저장해 두었다고 하네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8101, 'koKR', '만나서 반가워요. 여기 오신 이유가 안퀴라즈 전쟁 준비 상황을 묻기 위한 것이라면 좋겠군요. 우리는 지금 도움이 절실한 상황이에요.$B$B전쟁 물자 준비 작업은 실리시드와 놈들의 주인들을 상대로 벌이게 될 안퀴라즈 전쟁에 대비해 얼라이언스와 호드가 합동으로 펼치는 작전이에요. 우리는 아이언포지의 군사 지구에서 전쟁 물자를 생산하는 데 필요한 모든 종류의 재료를 모으고 있는데 이런 수집 임무에는 당신의 도움이 필요해요.$B$B이번 임무에 대해서 지휘관님과', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8103, 'koKR', NULL, '반갑습니다. 안퀴라즈 전쟁 준비 때문에 오셨기를 바랍니다. 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 아이언포지의 군사 지구에서 전쟁 물자가 될 만한 물건을 모으고 있는데, 당신이 좀 도와주셨으면 좋겠습니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8104, 'koKR', NULL, '반갑습니다. 안퀴라즈 전쟁 준비 때문에 오셨기를 바랍니다. 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 아이언포지의 군사 지구에서 전쟁 물자가 될 만한 물건을 모으고 있는데, 당신이 좀 도와주셨으면 좋겠습니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8105, 'koKR', '반갑네. 안퀴라즈 전쟁 준비 상황을 물어보러 왔다면 언제나 환영일세. 우리는 지금 도움이 절실히 필요해.$B$B전쟁 물자 준비는 실리시드와 놈들을 조종하는 무리를 상대로 벌일 안퀴라즈 전쟁에 대비해 호드와 얼라이언스가 합동으로 펼치는 작전이라네. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자를 만드는 데 필요한 온갖 재료를 모으고 있어. 이런 임무에는 자네의 도움이 꼭 필요하지.$B$B장군님과 이 일에 대해 꼭 의논해 볼 거라 믿네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8106, 'koKR', NULL, '안녕하십니까. 안퀴라즈 전쟁 준비 때문에 오신 것이겠지요? 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자가 될만한 물건들을 모으고 있는데, 그대가 좀 도와주셨으면 합니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8107, 'koKR', NULL, '안녕하십니까. 안퀴라즈 전쟁 준비 때문에 오신 것이겠지요? 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자가 될만한 물건들을 모으고 있는데, 그대가 좀 도와주셨으면 합니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8108, 'koKR', '안녕하십니까? 저는 세나리온 요새의 야수 관리인 레오렌입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8109, 'koKR', '조심스럽게 포장된 선물 더미가 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8110, 'koKR', '선물에는 \'40세 이상의 모험가용\'이라는 딱지가 붙어있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8111, 'koKR', '이 세계는 자네와 자네 동맹에게 큰 은혜를 입었네, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8112, 'koKR', '크툰이 살아 있었다면 우리의 자유는 아무런 의미가 없었을 것입니다. 진정 그대는 고대의 예언에 계시된 영웅이 맞습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8113, 'koKR', '이 저주받은 사원에서 무슨 일이 일어났는지 모두가 알게 될 것이오, 영웅이여. 역사책에 기록되고, 아제로스부터 머나먼 공허 끝까지 전설로 전해질 것이오!', '영웅이여, 이 저주받은 신전에서 무슨 일이 있었는지는 모두 알게 될 것입니다. 그리고 모든 사실은 역사에 기록될 것입니다. 아제로스에서 머나먼 황천에 이르기까지 위대한 전설로 사람들의 입에 오르내릴 것입니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8114, 'koKR', '지금 전운의 그림자가 최고조로 짙어지고 있지만 우리에게는 호드와 얼라이언스의 뛰어난 전사들이 많이 있기 때문에 아무 걱정이 없소.$B$B단, 이들이 서로 위협하지만 않는다면...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8115, 'koKR', '선물에는 \'20세 이상의 모험가용\'이라는 딱지가 붙어있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8116, 'koKR', '선물에는 \'10세 이상의 모험가용\'이라는 딱지가 붙어있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8120, 'koKR', NULL, '이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 어떤 가방을 만드는 도안이 그려져 있습니다. 하지만, 이 도안을 해석하기에는 당신의 재봉술에 대한 이해가 조금 부족합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8121, 'koKR', NULL, '이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 도안을 당신의 마법책에 옮겨 적겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8122, 'koKR', NULL, '이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 당신은 이미 이 가방을 만드는 방법을 알고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8123, 'koKR', '나무구렁 일족과 적대적인 관계가 아니라는 것을 증명한 자만이 공격을 받지 않고 무사히 요새를 통과할 수 있소. 이방인이여, 당신은 우리의 신뢰를 얻기 위해 어떠한 노력을 했소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8124, 'koKR', '$c|1이여;여;, 무얼 찾고 있소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8125, 'koKR', '새해를 맞이하여 새롭게 나온: PX-238 겨울맞이 원더볼트를 소개하지! 자자, 부끄러워 말고 어서 올라가 보라고.$B$B아, 해 보기 전에 이 양식에 서명하라고. 우린 아직 이 기계에서 몇 개의 작동 오류를 수정하려고 작업하고 있는 중이거든.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8126, 'koKR', '안녕하십니까, $C|1이여;여;? 저는 다르나서스를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무예요.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 다르나서스에서 그대의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', '안녕하십니까, $C|1이여;여;? 저는 다르나서스를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무예요.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 다르나서스에서 그대의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8127, 'koKR', '안녕하십니까, $C|1이여;여;? 저는 검은창 부족을 위해 일하는 인사 장교입니다. 호드 무공 훈장을 받은 모험가들을 돕는 것이 제 임무입니다.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 당신의 공적을 기록해 두겠습니다. 그러면 검은창 부족에서 당신의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', '안녕하십니까, $C|1이여;여;? 저는 검은창 부족을 위해 일하는 인사 장교입니다. 호드 무공 훈장을 받은 모험가들을 돕는 것이 제 임무입니다.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 당신의 공적을 기록해 두겠습니다. 그러면 검은창 부족에서 당신의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8128, 'koKR', '안녕하세요? 저는 놈리건을 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 놈리건은 당신의 임무 수행 능력을 인정할 거예요.', '안녕하세요? 저는 놈리건을 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 놈리건은 당신의 임무 수행 능력을 인정할 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
