(6707, 'koKR', '<TXT> ZUL,ST,MAR - 반복 가능', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6708, 'koKR', NULL, '텍스트', '텍스트', NULL, NULL, NULL, NULL, NULL, NULL),
