(8266, 'koKR', '희생의 기장', NULL, NULL, NULL, '잿빛 골짜기의 은빛날개 숲에 있는 파수꾼 파송에게 가야 합니다.', NULL, NULL, NULL, NULL),
(8267, 'koKR', '희생의 기장', NULL, NULL, NULL, '잿빛 골짜기의 은빛날개 숲에 있는 파수꾼 파송에게 가야 합니다.', NULL, NULL, NULL, NULL),
(8268, 'koKR', '희생의 기장', NULL, NULL, NULL, '오그리마에 있는 부대장 쉐터스컬에게 가야 합니다.', NULL, NULL, NULL, NULL),
(8269, 'koKR', '희생의 기장', NULL, NULL, NULL, '오그리마에 있는 부대장 쉐터스컬에게 가야 합니다.', NULL, NULL, NULL, NULL),
(8270, 'koKR', '테스트 복사 퀘스트', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
